//! SQL engine: catalog + executor over document heaps.
//!
//! The catalog itself is a document stored on page 1:
//! `{ "tables": { "<name>": { "columns": [names...], "pages": [...] } } }`
//! so metadata rides the same WAL/pager machinery as data.

use crate::btree::{BTree, BTreeError};
use crate::encode;
use crate::heap::Heap;
use crate::pager::{PageReader, Pager, PagerError, Snapshot, PAGE_SIZE};
use crate::value::{Decimal, Object, Value};
use num_traits::ToPrimitive;
use sqlparser::ast::{
    BinaryOperator, Expr as SqlExpr, Function, LimitClause, ObjectName, ObjectNamePart, Query,
    SelectItem, SetExpr, Statement, TableObject,
};
use sqlparser::dialect::GenericDialect;
use sqlparser::parser::Parser;
use std::cmp::Ordering;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

pub const CATALOG_PAGE: u32 = 1;
/// Catalog payload paginates across a chain of pages: page 1 carries
/// `CATALOG_MAGIC`, the total payload length and the next overflow page id
/// (0 = end); every overflow page repeats the same 16-byte header. The old
/// single-page catalog capped a database at ~4 KB of metadata (one full page
/// id list eats that in ~800 heap pages, i.e. a few MB of rows) and then
/// failed every write that allocated a page. Pages are append-only and never
/// reused, so overflow pages orphaned by a shrinking catalog are just dead
/// space. The payload still contains each table's page-id list, so a save is
/// O(catalog bytes) — acceptable because saves only fire on page allocation
/// and DDL, both sublinear in row count.
const CATALOG_MAGIC: &[u8; 8] = b"DOCSCAT2";
const CATALOG_HDR: usize = 16;
const CATALOG_CHUNK: usize = PAGE_SIZE - CATALOG_HDR;

/// System table backing persistent pub/sub. Created by docsql-server at
/// startup; hidden from user-facing catalogs (read through the server's
/// `docsql_pubsub` view instead).
pub const PUBSUB_TABLE: &str = "_pubsub_messages";

/// System table backing catch-up replication (rejoin repair): every
/// locally-committed write, in commit order, with a node-local monotonic
/// `seq`. Peers record the last seq they applied per origin (see
/// [`Database::position_set`]) and pull the range after it when they
/// rejoin — sync exactly what's missing instead of adopting a full
/// snapshot. Node-local by design: an op's canonical sequence is its
/// origin's.
pub const CLUSTER_LOG_TABLE: &str = "_cluster_log";

/// Byte cap for one `journal_range` catch-up batch: large documents make a
/// fixed row count an unbounded memory commitment on the serving node.
const JOURNAL_RANGE_MAX_BYTES: usize = 8 * 1024 * 1024;

/// System table backing catch-up replication positions: per origin node
/// id, the last applied journal seq. Updated right after each applied
/// replicated write; a crash between apply and update leaves the position
/// behind the data, so a later catch-up replays an already-applied op —
/// that errors, and the repair falls back to a full snapshot (the safe
/// direction: positions can only lag the data, never lead it).
pub const CLUSTER_POS_TABLE: &str = "_cluster_pos";

/// System table holding this node's persistent random identity: the key
/// positions are stored under, stable across restarts and independent of
/// reachable addresses.
pub const CLUSTER_ID_TABLE: &str = "_cluster_id";

/// Upper bound for LPAD/RPAD target lengths (in characters). The padded
/// result goes into a document whose hard cap is `MAX_DOC_SIZE`, so this
/// is pure allocation-bomb armor: an unbounded `String::with_capacity`
/// used to abort the process on a single `SELECT LPAD('a', 2^62)`.
const MAX_PAD_LENGTH: usize = 1 << 20;

/// Upper bound for the number of grouping sets one GROUP BY may expand to
/// (ROLLUP/CUBE/GROUPING SETS combine as a cartesian product — three
/// 12-element CUBEs used to multiply into an astronomic with_capacity).
const MAX_GROUPING_SETS: usize = 16_384;

/// True for the engine-managed system tables: excluded from user-facing
/// catalogs, digests, dumps and snapshot wipes.
pub fn is_system_table(name: &str) -> bool {
    name == PUBSUB_TABLE
        || name == CLUSTER_LOG_TABLE
        || name == CLUSTER_POS_TABLE
        || name == CLUSTER_ID_TABLE
}

/// Internal tables in the broad sense: engine system tables (excluded from
/// replication — digests/snapshots never carry them) PLUS the user/role
/// storage tables, which DO replicate (they are regular data) but are
/// shielded from direct SQL writes and hidden from the object browser.
/// Display filters and the server's write gate use this predicate;
/// replication-exclusion logic must keep using `is_system_table`.
pub fn is_internal_table(name: &str) -> bool {
    is_system_table(name) || crate::useradmin::is_user_table(name)
}

#[derive(Debug, thiserror::Error)]
pub enum SqlError {
    #[error("heap error: {0}")]
    Heap(#[from] crate::heap::HeapError),
    #[error("{0}")]
    Message(String),
    #[error("parse error: {0}")]
    Parse(String),
    #[error("storage error: {0}")]
    Storage(#[from] PagerError),
    #[error("encoding error: {0}")]
    Encode(#[from] encode::EncodeError),
}

pub type Result<T> = std::result::Result<T, SqlError>;

/// Statement-local CTE table (`WITH name AS (SELECT …)` materialized rows),
/// threaded through the SELECT execution chain so it can run on `&Database`
/// (MVCC stage A concurrent readers).
type Ctes = std::collections::BTreeMap<String, Vec<Object>>;

pub(crate) fn err<T>(msg: impl Into<String>) -> Result<T> {
    Err(SqlError::Message(msg.into()))
}

/// Cooperative statement deadline for the server-side statement timeout
/// (`DOCSQL_STATEMENT_TIMEOUT_MS`). The engine is synchronous inside one
/// global writer — nothing can preempt a runaway statement from the
/// outside — so long row loops (table scans, nested-loop joins, UPDATE/
/// DELETE matching) check in here instead. The wall clock is sampled once
/// per [`StmtDeadline::TICK_BATCH`] iterations; a fired deadline surfaces
/// as a normal SQL error, rolling the statement back like any failure.
/// Mutex-based (not Cell): `Database: Sync` is required once the server
/// shares `&Database` across threads under the read tier.
#[derive(Default)]
pub struct StmtDeadline {
    inner: std::sync::Mutex<(Option<std::time::Instant>, u64)>,
}

impl StmtDeadline {
    pub fn set(&self, deadline: Option<std::time::Instant>) {
        let mut g = self.inner.lock().unwrap_or_else(|p| p.into_inner());
        *g = (deadline, 0);
    }

    /// Call once per row iteration from long loops. Engine-global, not per
    /// connection — the caller arms and clears it around exactly one
    /// statement (see [`Database::set_statement_deadline`]).
    pub fn check(&self) -> Result<()> {
        const TICK_BATCH: u64 = 1024;
        let mut g = self.inner.lock().unwrap_or_else(|p| p.into_inner());
        g.1 = (g.1 + 1) % TICK_BATCH;
        if g.1 != 0 {
            return Ok(());
        }
        if let Some(d) = g.0 {
            if std::time::Instant::now() >= d {
                return err("statement timeout exceeded (DOCSQL_STATEMENT_TIMEOUT_MS)");
            }
        }
        Ok(())
    }
}

/// Outcome of executing one statement.
#[derive(Debug, Clone, PartialEq)]
pub enum ExecOutcome {
    /// Rows affected (DML) or a status message (DDL).
    Affected(u64),
    Rows(QueryResult),
}

/// Transaction-control classification, used by servers to time replication:
/// writes inside an open transaction must not reach peers until the
/// transaction commits; a rollback discards them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TxControl {
    Begin,
    Commit,
    /// Plain ROLLBACK, or ROLLBACK TO SAVEPOINT when `savepoint` is set.
    Rollback {
        savepoint: Option<String>,
    },
    Savepoint(String),
    Release(String),
    /// Not transaction control.
    None,
}

/// One statement parsed once for a whole server round-trip: the AST feeds
/// [`Database::execute_parsed`], while `tx`/`is_write` route the request
/// (write path, transaction control, replication timing) without re-parsing
/// the text.
/// Process-wide parsed-statement cache (`SQL text → classified AST`).
/// Bounded two ways: oversized statements never enter (a multi-MB batch
/// INSERT would churn the map), and a full map clears wholesale — a
/// workload with more distinct texts than the cap simply falls back to
/// always-parse, the previous behavior. Errors are not cached.
fn stmt_cache() -> &'static std::sync::Mutex<std::collections::HashMap<String, ParsedStatement>> {
    static CACHE: std::sync::OnceLock<
        std::sync::Mutex<std::collections::HashMap<String, ParsedStatement>>,
    > = std::sync::OnceLock::new();
    CACHE.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// Second-sight filter behind the statement cache: hashes of texts that
/// parsed once (cap-bounded, cleared wholesale). A repeat sighting promotes
/// the text into the cache — see [`Database::parse_classified`].
fn stmt_seen() -> &'static std::sync::Mutex<std::collections::HashSet<u64>> {
    static SEEN: std::sync::OnceLock<std::sync::Mutex<std::collections::HashSet<u64>>> =
        std::sync::OnceLock::new();
    SEEN.get_or_init(|| std::sync::Mutex::new(std::collections::HashSet::new()))
}

#[derive(Clone)]
pub struct ParsedStatement {
    pub stmt: AnyStmt,
    pub tx: TxControl,
    pub is_write: bool,
    /// Original statement text. Wall-clock folding re-parses a rewritten
    /// copy of this (journaled writes must not carry NOW()/SYSDATE()) and
    /// the server's queue path holds a parsed statement long before the
    /// write lock — the text rides along so the fold is available at every
    /// execute_parsed call site.
    pub source: String,
}
/// A parsed statement: standard SQL (`sqlparser` AST) or one of the
/// hand-parsed user-management statements (sqlparser 0.62 does not accept
/// `CREATE USER … PASSWORD` / `GRANT role TO user`). The SQL AST is boxed —
/// it dwarfs the user-admin shape by two orders of magnitude.
#[derive(Debug, Clone)]
pub enum AnyStmt {
    Sql(Box<Statement>),
    UserAdmin(crate::useradmin::UserAdminStmt),
    /// REFRESH MATERIALIZED VIEW (hand-parsed: sqlparser 0.62's generic
    /// dialect has no REFRESH statement). Carries the view name.
    RefreshMatview(String),
}

#[derive(Debug, Clone, PartialEq)]
pub struct QueryResult {
    pub columns: Vec<String>,
    pub rows: Vec<Vec<Value>>,
}

/// One column as seen by tooling (web console / drivers).
#[derive(Debug, Clone, PartialEq)]
pub struct ColumnInfo {
    pub name: String,
    pub nullable: bool,
    pub primary_key: bool,
    pub unique: bool,
    pub autoinc: bool,
    /// Declared type where the engine tracks one ("GUID" for auto-generated
    /// GUID columns, "ANY" otherwise). Tooling uses it to round-trip DDL.
    pub data_type: String,
    /// Declared DEFAULT expression as SQL text (None when the column has
    /// none). Tooling uses it to round-trip DDL.
    pub default_value: Option<String>,
}

/// Read-only catalog snapshot of one table.
#[derive(Debug, Clone, PartialEq)]
pub struct TableInfo {
    pub name: String,
    pub columns: Vec<ColumnInfo>,
    /// Constraint indexes: PRIMARY KEY column first, then UNIQUE columns.
    pub keys: Vec<String>,
    pub indexes: Vec<String>,
    /// CREATE INDEX definitions (name/column/unique) for tooling: the
    /// explorer and the console's script generator need the column and
    /// uniqueness behind each name, not just the name list.
    pub index_defs: Vec<IndexInfo>,
    pub pages: usize,
    /// Materialized view (CREATE MATERIALIZED VIEW): table reads, writes
    /// refused, REFRESH recomputes.
    pub matview: bool,
}

/// One CREATE INDEX definition as recorded in the catalog.
///
/// `columns.len() >= 1`; `len() > 1` is a composite index whose B+ tree keys
/// are `Value::Array` over the columns in order (ordered by
/// `Value::cmp_values` element-wise — no separate byte-order encoding).
/// `columns[0]` mirrors the legacy `column` field for tooling compatibility.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct IndexDef {
    pub name: String,
    pub columns: Vec<String>,
    pub unique: bool,
    /// JSON path index (design 005): the single column in `columns` holds
    /// JSON text; tree keys are values extracted at this path via the same
    /// lookup `JSON_EXTRACT` uses. None = a plain column index.
    pub path: Option<String>,
    /// Partial index (CREATE INDEX … WHERE): the predicate as SQL text. The
    /// tree holds ONLY the rows satisfying it, so every probe over the tree
    /// must first prove the query's WHERE implies the predicate
    /// ([`query_implies_pred`]) — an ungated probe would silently drop the
    /// pred-failing rows. Row-local only (no subqueries/aggregates),
    /// validated at CREATE time.
    pub pred: Option<String>,
}

impl IndexDef {
    /// Catalog/tuple-compat view: first column.
    pub fn column(&self) -> &str {
        &self.columns[0]
    }
}

/// One index as exposed to tooling (catalog snapshot): CREATE INDEX
/// definitions plus the derived `sqlite_autoindex_*` constraint indexes.
#[derive(Debug, Clone, PartialEq)]
pub struct IndexInfo {
    pub name: String,
    /// First indexed column (kept for tooling compatibility; `columns`
    /// carries the full list for composite indexes).
    pub column: String,
    /// Full column list in key order (single-column indexes: one entry).
    pub columns: Vec<String>,
    pub unique: bool,
    /// PRIMARY KEY / UNIQUE constraint index, auto-created with the table
    /// (SQLite-style `sqlite_autoindex_*` name). Derived, never persisted,
    /// and not droppable/editable through DROP INDEX / CREATE INDEX.
    pub auto: bool,
    /// Partial-index predicate text (None for full indexes).
    pub pred: Option<String>,
}

/// Outcome of a multi-statement batch: statements run in order and the run
/// stops at the first error (`error.statement` is the 0-based index).
#[derive(Debug, Clone, PartialEq)]
pub struct BatchResult {
    /// Total statements in the batch (parsed), even when the run stopped early.
    pub statements: usize,
    pub outcomes: Vec<ExecOutcome>,
    pub error: Option<BatchError>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct BatchError {
    pub statement: usize,
    pub message: String,
}

/// Session snapshot of all tables: (meta, docs) per table. Used by
/// transaction rollback and the SAVEPOINT stack.
/// Catalog state captured at BEGIN / SAVEPOINT: table metas are shared
/// behind `Arc`, so a snapshot clones pointers (and each later mutation
/// deep-copies just the one table it touches), not the database. Document
/// content is restored through the pager's page undo journal — the old
/// whole-database deep copy made every BEGIN an O(database) allocation.
#[derive(Clone)]
struct TableSnapshot {
    tables: std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
    autoinc: std::collections::HashMap<String, i64>,
}

#[derive(Debug, Clone, Default)]
pub(crate) struct TableMeta {
    /// Table name, mirroring the catalog key: constraint errors carry it so
    /// multi-table statements say WHICH table failed. Rebuilt on load (the
    /// catalog serializes the key itself, so this is never part of the
    /// on-disk format) and empty only for synthesized/test metas.
    name: String,
    columns: Vec<String>,
    pages: Vec<u32>,
    primary_key: Option<String>,
    unique: Vec<String>,
    not_null: Vec<String>,
    autoinc: Option<String>,
    /// Auto-generated GUID column (GUID/UUID/UNIQUEIDENTIFIER/UUIDV7 type
    /// plus AUTOINCREMENT/AUTOGENERATE): INSERT fills a time-ordered UUIDv7
    /// when the value is omitted or NULL.
    autoguid: Option<String>,
    /// Index names registered on this table (catalog-level v1; B+ tree
    /// backing arrives with the index-integration milestone).
    indexes: Vec<String>,
    /// CREATE INDEX definitions: name + ordered columns + uniqueness. Drives
    /// DROP INDEX cleanup (lifting UNIQUE enforced by a dropped unique index)
    /// and the sqlite_master index rows. Composite indexes key their tree by
    /// the index name; single-column indexes key by the column name (legacy
    /// layout, zero-migration for deployed databases).
    index_defs: Vec<IndexDef>,
    /// Columns declared UNIQUE via CREATE TABLE constraints. Dropping a
    /// UNIQUE INDEX only lifts meta.unique for columns NOT in this list.
    constraint_unique: Vec<String>,
    /// Column DEFAULT expressions as SQL text: (column, expr).
    defaults: Vec<(String, String)>,
    /// CHECK constraint expressions as SQL text (column- or table-level).
    checks: Vec<String>,
    /// Foreign keys: (local column, referenced table, referenced column).
    foreign_keys: Vec<(String, String, String)>,
    /// Indexed column -> B+ tree root page. PRIMARY KEY and UNIQUE columns
    /// always get trees (duplicates are enforced through them); CREATE
    /// INDEX adds non-unique trees. Lookups over these columns skip the
    /// heap scan.
    index_roots: std::collections::BTreeMap<String, u32>,
    /// Recycled overflow-chain page ids (documents larger than one page;
    /// see heap.rs / docs/design/002): reused by the next oversized insert.
    /// Persisted in the catalog; empty for tables without overflow history.
    overflow_free: Vec<u32>,
    /// Sticky marker: some stored document carries a literal dotted field
    /// name ("a.b" as ONE key). Eval resolves a qualified reference `a.b`
    /// by that exact key first, so on such a table a qualifier-stripped
    /// index probe is not a superset — probes and index-ordered windows
    /// must refuse stripped names while it is set. Written once when the
    /// first dotted field lands; never cleared (conservative is correct).
    dotted_keys: bool,
    /// User view: the AS query text (CREATE VIEW). `None` for real tables.
    /// Views live in the same catalog namespace (one name, one object); a
    /// SELECT naming one expands to this query's rows. No storage, no
    /// indexes, no writes.
    view_sql: Option<String>,
    /// Materialized view: the AS query text (CREATE MATERIALIZED VIEW).
    /// Unlike `view_sql` this object HAS storage — a real table materialized
    /// from the query at CREATE/REFRESH time, readable (and indexable) like
    /// any table, but not writable (REFRESH MATERIALIZED VIEW recomputes
    /// it). The stored query is determinism-validated at CREATE: REFRESH
    /// replays it on every node, and a RAND()/wall-clock result would
    /// silently fork the cluster.
    matview_sql: Option<String>,
}

impl TableMeta {
    /// True when this catalog entry is a user view (CREATE VIEW), not a
    /// stored table.
    pub(crate) fn is_view(&self) -> bool {
        self.view_sql.is_some()
    }

    /// True when this catalog entry is a materialized view: real storage,
    /// table reads, writes refused (REFRESH recomputes it).
    pub(crate) fn is_matview(&self) -> bool {
        self.matview_sql.is_some()
    }
}

impl TableMeta {
    /// Heap view over this table's storage: live pages plus the recycled
    /// overflow-chain free list.
    fn heap_of(&self) -> Heap {
        Heap {
            pages: self.pages.clone(),
            overflow_free: self.overflow_free.clone(),
            dropped: Vec::new(),
        }
    }

    /// Columns making up the index behind `root_key`: the definition's
    /// ordered column list for a named (possibly composite) index, or the
    /// key itself for legacy single-column entries (constraint trees and
    /// single-column CREATE INDEX key their tree by the column name).
    fn index_columns_of(&self, root_key: &str) -> Vec<String> {
        match self.index_defs.iter().find(|d| d.name == root_key) {
            Some(d) => d.columns.clone(),
            // Legacy/constraint single-column tree: the root key *is* the
            // column. Any other key is an orphaned composite tree (its index
            // was dropped, the def is gone): returning `[root_key]` would
            // make it look like a scalar column tree and mix scalar keys
            // into an Array-keyed tree.
            None => {
                if self.columns.iter().any(|c| c == root_key)
                    || self.primary_key.as_deref() == Some(root_key)
                    || self.unique.iter().any(|c| c == root_key)
                {
                    vec![root_key.to_string()]
                } else {
                    Vec::new()
                }
            }
        }
    }

    /// True when the tree behind `root_key` enforces uniqueness: a PK or
    /// UNIQUE constraint column (single-column constraint tree), or a
    /// `CREATE UNIQUE INDEX` definition (possibly composite).
    fn root_key_unique(&self, root_key: &str) -> bool {
        if self.primary_key.as_deref() == Some(root_key)
            || self.unique.contains(&root_key.to_string())
        {
            return true;
        }
        self.index_defs
            .iter()
            .any(|d| d.name == root_key && d.unique)
    }

    /// Qualify a column with the table name for constraint errors
    /// (`users.email`); synthesized metas without a name stay unqualified.
    fn qual(&self, col: &str) -> String {
        if self.name.is_empty() {
            col.to_string()
        } else {
            format!("{}.{}", self.name, col)
        }
    }

    /// Validate a document against declared constraints.
    fn check(&self, doc: &Object) -> Result<()> {
        for col in &self.not_null {
            if matches!(doc.get(col), Some(Value::Null) | None) {
                return err(format!("NOT NULL constraint failed: {}", self.qual(col)));
            }
        }
        for text in &self.checks {
            let e = parse_expr_text(text)?;
            // SQL three-valued CHECK semantics: only FALSE rejects; unknown
            // (a NULL operand) passes. A syntactic "any NULL column ref"
            // shortcut is wrong in both directions (`a BETWEEN …` with NULL
            // was rejected, `a > 0 AND b > 0` with one NULL accepted a
            // false conjunct), so the expression is evaluated with proper
            // unknown propagation.
            if matches!(check_expr_outcome(&e, doc)?, CheckOutcome::Fail) {
                return err(format!("CHECK constraint failed on {}: {text}", self.name));
            }
        }
        Ok(())
    }

    /// Enforce PRIMARY KEY / UNIQUE across the whole (rewritten) doc set.
    fn check_unique(&self, docs: &[Object]) -> Result<()> {
        for col in self.primary_key.iter().chain(self.unique.iter()) {
            let mut seen = std::collections::BTreeSet::new();
            for doc in docs {
                if let Some(v) = doc.get(col) {
                    if matches!(v, Value::Null) {
                        continue;
                    }
                    let key = encode::encode_to_vec(v).map_err(SqlError::Encode)?;
                    if !seen.insert(key) {
                        return err(format!("UNIQUE constraint failed: {}", self.qual(col)));
                    }
                }
            }
        }
        Ok(())
    }
}

/// Parse a standalone SQL expression (constraint/DEFAULT bodies stored in
/// the catalog as text).
pub fn parse_expr_text(s: &str) -> Result<SqlExpr> {
    let mut parser = Parser::new(&GenericDialect {})
        .try_with_sql(s)
        .map_err(|e| SqlError::Parse(e.to_string()))?;
    let expr = parser
        .parse_expr()
        .map_err(|e| SqlError::Parse(e.to_string()))?;
    // Trailing input is corruption of the stored body, not a suffix to
    // ignore: a row-filter predicate sliced as `region = 'east'; anything`
    // would otherwise be stored whole while every consumer evaluates only
    // the prefix.
    if parser.peek_token().token != sqlparser::tokenizer::Token::EOF {
        return Err(SqlError::Parse("trailing input after expression".into()));
    }
    Ok(expr)
}

/// Canonical enumeration of the direct child expressions of every `SqlExpr`
/// variant the engine can evaluate. Subquery-bearing nodes (Subquery /
/// Exists / InSubquery / AnyOp / AllOp) are excluded on purpose: every
/// tree-wide walker treats those nodes specially. Identifiers, literals and
/// other leaves fall through and yield nothing. The macro body uses plain
/// place matches only, so it expands identically over `&SqlExpr` and
/// `&mut SqlExpr`.
macro_rules! each_child_expr {
    ($e:expr, $($f:tt)+) => {
        match $e {
            SqlExpr::IsFalse(c)
            | SqlExpr::IsNotFalse(c)
            | SqlExpr::IsTrue(c)
            | SqlExpr::IsNotTrue(c)
            | SqlExpr::IsNull(c)
            | SqlExpr::IsNotNull(c)
            | SqlExpr::IsUnknown(c)
            | SqlExpr::IsNotUnknown(c)
            | SqlExpr::Nested(c) => $($f)*(c),
            SqlExpr::IsNormalized { expr: c, .. }
            | SqlExpr::Collate { expr: c, .. }
            | SqlExpr::Ceil { expr: c, .. }
            | SqlExpr::Floor { expr: c, .. }
            | SqlExpr::Extract { expr: c, .. }
            | SqlExpr::Cast { expr: c, .. }
            | SqlExpr::Prefixed { value: c, .. }
            | SqlExpr::Named { expr: c, .. } => $($f)*(c),
            SqlExpr::CompoundFieldAccess { root, .. } => $($f)*(root),
            SqlExpr::JsonAccess { value, .. } => $($f)*(value),
            SqlExpr::Convert { expr, styles, .. } => {
                $($f)*(expr);
                for c in styles {
                    $($f)*(c);
                }
            }
            SqlExpr::AtTimeZone { timestamp, time_zone } => {
                $($f)*(timestamp);
                $($f)*(time_zone);
            }
            SqlExpr::Position { expr, r#in } => {
                $($f)*(expr);
                $($f)*(r#in);
            }
            SqlExpr::Substring {
                expr,
                substring_from,
                substring_for,
                ..
            } => {
                $($f)*(expr);
                match substring_from {
                    Some(c) => $($f)*(c),
                    None => {}
                }
                match substring_for {
                    Some(c) => $($f)*(c),
                    None => {}
                }
            }
            SqlExpr::Trim {
                expr,
                trim_what,
                trim_characters,
                ..
            } => {
                $($f)*(expr);
                match trim_what {
                    Some(c) => $($f)*(c),
                    None => {}
                }
                match trim_characters {
                    Some(chars) => {
                        for c in chars {
                            $($f)*(c);
                        }
                    }
                    None => {}
                }
            }
            SqlExpr::Overlay {
                expr,
                overlay_what,
                overlay_from,
                overlay_for,
            } => {
                $($f)*(expr);
                $($f)*(overlay_what);
                $($f)*(overlay_from);
                match overlay_for {
                    Some(c) => $($f)*(c),
                    None => {}
                }
            }
            SqlExpr::BinaryOp { left, right, .. } => {
                $($f)*(left);
                $($f)*(right);
            }
            SqlExpr::UnaryOp { expr, .. } => $($f)*(expr),
            SqlExpr::Between {
                expr, low, high, ..
            } => {
                $($f)*(expr);
                $($f)*(low);
                $($f)*(high);
            }
            SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
                $($f)*(l);
                $($f)*(r);
            }
            SqlExpr::Like { expr, pattern, .. }
            | SqlExpr::ILike { expr, pattern, .. }
            | SqlExpr::SimilarTo { expr, pattern, .. }
            | SqlExpr::RLike { expr, pattern, .. } => {
                $($f)*(expr);
                $($f)*(pattern);
            }
            SqlExpr::InList { expr, list, .. } => {
                $($f)*(expr);
                for c in list {
                    $($f)*(c);
                }
            }
            SqlExpr::InUnnest { expr, array_expr, .. } => {
                $($f)*(expr);
                $($f)*(array_expr);
            }
            SqlExpr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => {
                match operand {
                    Some(c) => $($f)*(c),
                    None => {}
                }
                for w in conditions {
                    let sqlparser::ast::CaseWhen {
                        condition, result, ..
                    } = w;
                    $($f)*(condition);
                    $($f)*(result);
                }
                match else_result {
                    Some(c) => $($f)*(c),
                    None => {}
                }
            }
            SqlExpr::Function(func) => {
                let sqlparser::ast::Function { args, filter, .. } = func;
                match args {
                    sqlparser::ast::FunctionArguments::List(list) => {
                        let sqlparser::ast::FunctionArgumentList { args, .. } = list;
                        for a in args {
                            match a {
                                sqlparser::ast::FunctionArg::Unnamed(
                                    sqlparser::ast::FunctionArgExpr::Expr(c),
                                ) => $($f)*(c),
                                sqlparser::ast::FunctionArg::Named {
                                    arg: sqlparser::ast::FunctionArgExpr::Expr(c),
                                    ..
                                } => $($f)*(c),
                                sqlparser::ast::FunctionArg::ExprNamed {
                                    arg: sqlparser::ast::FunctionArgExpr::Expr(c),
                                    ..
                                } => $($f)*(c),
                                _ => {}
                            }
                        }
                    }
                    _ => {}
                }
                match filter {
                    Some(c) => $($f)*(c),
                    None => {}
                }
            }
            SqlExpr::GroupingSets(groups) | SqlExpr::Cube(groups) | SqlExpr::Rollup(groups) => {
                for g in groups {
                    for c in g {
                        $($f)*(c);
                    }
                }
            }
            SqlExpr::Tuple(items) => {
                for c in items {
                    $($f)*(c);
                }
            }
            SqlExpr::Struct { values, .. } => {
                for c in values {
                    $($f)*(c);
                }
            }
            SqlExpr::Dictionary(fields) => {
                for field in fields {
                    let sqlparser::ast::DictionaryField { value, .. } = field;
                    $($f)*(value);
                }
            }
            _ => {}
        }
    };
}

pub(crate) fn child_exprs(e: &SqlExpr) -> Vec<&SqlExpr> {
    let mut out: Vec<&SqlExpr> = Vec::new();
    each_child_expr!(e, out.push);
    out
}

pub(crate) fn child_exprs_mut(e: &mut SqlExpr) -> Vec<&mut SqlExpr> {
    let mut out: Vec<&mut SqlExpr> = Vec::new();
    each_child_expr!(e, out.push);
    out
}

/// True when the expression calls a non-deterministic function — the
/// wall-clock family (NOW/SYSDATE/CURRENT_TIMESTAMP/GETDATE/…) or the
/// random-id family (NEWID/NEWSEQUENTIALID): its value differs between
/// nodes and instants, so a stored DEFAULT or CHECK carrying it must be
/// resolved per row on the writing node and shipped as a literal (red
/// line: non-deterministic generated values are fixed by the writer).
pub(crate) fn expr_calls_wall_clock(e: &SqlExpr) -> bool {
    match e {
        SqlExpr::Function(f) => {
            let n = f.name.to_string().to_ascii_lowercase();
            if matches!(
                n.as_str(),
                "now"
                    | "now_ms"
                    | "sysdate"
                    | "current_timestamp"
                    | "getdate"
                    | "getutcdate"
                    | "sysdatetime"
                    | "sysutcdatetime"
                    | "sysdatetimeoffset"
                    | "newid"
                    | "newsequentialid"
                    | "rand"
            ) {
                return true;
            }
            child_exprs(e).into_iter().any(expr_calls_wall_clock)
        }
        // A wall-clock call inside a CASE branch or a CAST/FLOOR/… wrapper
        // (e.g. `CAST(GETDATE() AS TIMESTAMP)`, which the text-level fold
        // cannot reduce) must still trip this check — child_exprs is the
        // one shared traversal, so wrappers cannot slip past again.
        _ => child_exprs(e).into_iter().any(expr_calls_wall_clock),
    }
}

/// Three-valued outcome of a CHECK predicate (SQL: FALSE rejects, TRUE and
/// UNKNOWN pass).
enum CheckOutcome {
    Pass,
    Fail,
    Unknown,
}

/// Evaluate a CHECK predicate with SQL three-valued logic. Comparisons and
/// boolean operators propagate UNKNOWN structurally; predicates the engine
/// evaluates two-valued (BETWEEN/LIKE/IN/functions) fall back to the
/// null-reference walker so a NULL operand stays unknown instead of being
/// read as FALSE.
fn check_expr_outcome(e: &SqlExpr, doc: &Object) -> Result<CheckOutcome> {
    use CheckOutcome::*;
    let eval_boolish = |e: &SqlExpr, doc: &Object| -> Result<CheckOutcome> {
        // Generic fallback: NULL reference → unknown, else the engine's
        // two-valued evaluation (non-boolean results keep the historical
        // lenient pass).
        if expr_has_null_ref(e, doc) {
            return Ok(Unknown);
        }
        Ok(match eval_expr(e, doc)? {
            Value::Bool(false) => Fail,
            _ => Pass,
        })
    };
    match e {
        SqlExpr::Nested(inner) => check_expr_outcome(inner, doc),
        SqlExpr::UnaryOp {
            op: sqlparser::ast::UnaryOperator::Not,
            expr,
        } => Ok(match check_expr_outcome(expr, doc)? {
            Pass => Fail,
            Fail => Pass,
            Unknown => Unknown,
        }),
        SqlExpr::BinaryOp {
            left,
            op: BinaryOperator::And,
            right,
        } => {
            let l = check_expr_outcome(left, doc)?;
            let r = check_expr_outcome(right, doc)?;
            Ok(match (l, r) {
                (Fail, _) | (_, Fail) => Fail,
                (Pass, Pass) => Pass,
                _ => Unknown,
            })
        }
        SqlExpr::BinaryOp {
            left,
            op: BinaryOperator::Or,
            right,
        } => {
            let l = check_expr_outcome(left, doc)?;
            let r = check_expr_outcome(right, doc)?;
            Ok(match (l, r) {
                (Pass, _) | (_, Pass) => Pass,
                (Fail, Fail) => Fail,
                _ => Unknown,
            })
        }
        SqlExpr::BinaryOp { left, op, right } => {
            let l = eval_expr(left, doc)?;
            let r = eval_expr(right, doc)?;
            if matches!(l, Value::Null) || matches!(r, Value::Null) {
                return Ok(Unknown);
            }
            Ok(match binop(l, op, r)? {
                Value::Bool(false) => Fail,
                Value::Bool(true) => Pass,
                Value::Null => Unknown,
                _ => Pass,
            })
        }
        SqlExpr::IsNull(_)
        | SqlExpr::IsNotNull(_)
        | SqlExpr::IsDistinctFrom(..)
        | SqlExpr::IsNotDistinctFrom(..) => Ok(match eval_expr(e, doc)? {
            Value::Bool(false) => Fail,
            _ => Pass,
        }),
        SqlExpr::Between { .. }
        | SqlExpr::Like { .. }
        | SqlExpr::ILike { .. }
        | SqlExpr::InList { .. } => eval_boolish(e, doc),
        _ => eval_boolish(e, doc),
    }
}

/// True when any column reference in `e` resolves to NULL in `doc` (CHECK
/// semantics: unknown, so the constraint passes).
fn expr_references_ident(e: &SqlExpr, name: &str) -> bool {
    match e {
        SqlExpr::Identifier(i) => i.value == name,
        SqlExpr::CompoundIdentifier(parts) => parts.last().is_some_and(|p| p.value == name),
        SqlExpr::Nested(inner) => expr_references_ident(inner, name),
        SqlExpr::UnaryOp { expr, .. } => expr_references_ident(expr, name),
        SqlExpr::BinaryOp { left, right, .. } => {
            expr_references_ident(left, name) || expr_references_ident(right, name)
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            expr_references_ident(expr, name)
                || expr_references_ident(low, name)
                || expr_references_ident(high, name)
        }
        SqlExpr::InList { expr, list, .. } => {
            expr_references_ident(expr, name) || list.iter().any(|i| expr_references_ident(i, name))
        }
        SqlExpr::Cast { expr, .. } => expr_references_ident(expr, name),
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(|o| expr_references_ident(o, name))
                || conditions.iter().any(|w| {
                    expr_references_ident(&w.condition, name)
                        || expr_references_ident(&w.result, name)
                })
                || else_result
                    .as_deref()
                    .is_some_and(|r| expr_references_ident(r, name))
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                list.args.iter().any(|a| match a {
                    sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) => expr_references_ident(inner, name),
                    _ => false,
                })
            } else {
                false
            }
        }
        _ => false,
    }
}

fn expr_has_null_ref(e: &SqlExpr, doc: &Object) -> bool {
    match e {
        SqlExpr::Identifier(i) => matches!(doc.get(&i.value), Some(Value::Null) | None),
        SqlExpr::CompoundIdentifier(parts) => {
            let full = parts
                .iter()
                .map(|p| p.value.clone())
                .collect::<Vec<_>>()
                .join(".");
            matches!(doc.get(&full), Some(Value::Null)) || {
                let last = parts.last().map(|p| p.value.clone()).unwrap_or_default();
                matches!(doc.get(&last), Some(Value::Null) | None)
            }
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            expr_has_null_ref(left, doc) || expr_has_null_ref(right, doc)
        }
        SqlExpr::UnaryOp { expr, .. } => expr_has_null_ref(expr, doc),
        SqlExpr::Nested(inner) => expr_has_null_ref(inner, doc),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            expr_has_null_ref(expr, doc)
                || expr_has_null_ref(low, doc)
                || expr_has_null_ref(high, doc)
        }
        SqlExpr::InList { expr, list, .. } => {
            expr_has_null_ref(expr, doc) || list.iter().any(|i| expr_has_null_ref(i, doc))
        }
        SqlExpr::Cast { expr, .. } => expr_has_null_ref(expr, doc),
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(|o| expr_has_null_ref(o, doc))
                || conditions.iter().any(|w| {
                    expr_has_null_ref(&w.condition, doc) || expr_has_null_ref(&w.result, doc)
                })
                || else_result
                    .as_deref()
                    .is_some_and(|r| expr_has_null_ref(r, doc))
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                list.args.iter().any(|a| match a {
                    sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) => expr_has_null_ref(inner, doc),
                    _ => false,
                })
            } else {
                false
            }
        }
        _ => false,
    }
}

/// Replication fingerprint of one table (cluster rejoin repair): row
/// count, an order-independent hash over every row's documents, and a
/// hash over the catalog fields that shape replay.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct TableDigest {
    pub name: String,
    pub rows: u64,
    pub rows_hash: u64,
    pub schema_hash: u64,
}

/// Hash over every replay-relevant catalog field of a table. Physical
/// fields (heap page ids, index root pages) are deliberately excluded:
/// they legitimately differ between nodes holding identical data.
fn schema_hash(meta: &TableMeta) -> u64 {
    let mut h = DefaultHasher::new();
    meta.view_sql.hash(&mut h);
    meta.columns.hash(&mut h);
    meta.primary_key.hash(&mut h);
    meta.unique.hash(&mut h);
    meta.not_null.hash(&mut h);
    meta.autoinc.hash(&mut h);
    meta.autoguid.hash(&mut h);
    meta.indexes.hash(&mut h);
    meta.index_defs.hash(&mut h);
    meta.constraint_unique.hash(&mut h);
    meta.defaults.hash(&mut h);
    meta.checks.hash(&mut h);
    meta.foreign_keys.hash(&mut h);
    h.finish()
}

/// Owned catalog view for a guardless read (MVCC stage B): cloned under the
/// server's brief read lock as `Arc` bumps, then held outside every database
/// lock while the statement runs. Writers mutating a table's meta use
/// `Arc::make_mut`, so the deep clone only happens while a detached reader
/// actually holds the table's entry.
#[derive(Clone, Default)]
pub(crate) struct CatalogSnapshot(std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>);

/// Execution context for the SELECT chain: everything a read needs — pager,
/// catalog, deadline and optionally a snapshot — without borrowing the
/// `Database` itself. Stage A runs it under the server's read lock
/// (`snap: None`, current visibility); stage B runs it entirely outside the
/// database locks (`snap: Some`, as-of visibility), so reads never block
/// writes. The SELECT chain methods live on this type; the write path
/// reaches them through `Database::read_cx` and the `_cx` shims.
pub(crate) struct ReadCx<'a> {
    pub(crate) pager: &'a Pager,
    pub(crate) tables: &'a std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
    pub(crate) deadline: &'a StmtDeadline,
    pub(crate) snap: Option<&'a Snapshot>,
}

impl<'a> ReadCx<'a> {
    /// Page reader for this context: current visibility without a snapshot,
    /// as-of reconstruction with one.
    pub(crate) fn reader(&self) -> PageReader<'a> {
        match self.snap {
            Some(snap) => PageReader::Snapshot(self.pager, snap),
            None => PageReader::Current(self.pager),
        }
    }
}

/// A guardless read view (MVCC stage B): the server builds one under a
/// microsecond-scale read lock, then executes SELECTs with no database lock
/// held — reads never block writes. Page reads go through the pager snapshot
/// (as-of the commit head at creation); the catalog is the cloned snapshot.
/// Dropping the view ends the pager snapshot.
pub struct ReadView {
    pager: std::sync::Arc<Pager>,
    catalog: CatalogSnapshot,
    deadline: std::sync::Arc<StmtDeadline>,
    snap: Snapshot,
}

impl ReadView {
    /// Arm the cooperative statement deadline. The view owns its deadline,
    /// so concurrent readers never overwrite each other's arming.
    pub fn set_statement_deadline(&self, deadline: Option<std::time::Instant>) {
        self.deadline.set(deadline);
    }

    /// Execute a read-only statement as of this view's snapshot. Plain
    /// SELECT only — the same refusals as [`Database::execute_read`].
    pub fn execute(&self, sql: &str) -> Result<ExecOutcome> {
        let parsed = Database::parse_classified(sql)?;
        let cx = ReadCx {
            pager: &self.pager,
            tables: &self.catalog.0,
            deadline: &self.deadline,
            snap: Some(&self.snap),
        };
        // EXPLAIN is a pure read — a readonly role diagnosing a plan is
        // exactly the audience; the inner query's reads are what
        // `stmt_read_targets` classifies for authorization.
        if let AnyStmt::Sql(stmt) = &parsed.stmt {
            if let Statement::Explain {
                statement,
                analyze,
                estimate,
                format,
                options,
                ..
            } = stmt.as_ref()
            {
                return cx.explain_outer(statement, *analyze, *estimate, format, options);
            }
        }
        let q = Database::plain_read_query(&parsed)?;
        cx.exec_query(q)
    }
}

impl Drop for ReadView {
    fn drop(&mut self) {
        self.pager.end_snapshot(self.snap);
    }
}

/// View-expansion recursion budget. `CREATE OR REPLACE` makes catalog
/// cycles constructible (see `exec_create_view`'s transitive check), and a
/// chain deep enough would blow the thread stack — one expansion level
/// costs several engine frames, so the budget stays far under the 2 MiB
/// test-thread stack while exceeding any sane view stack. Creation refuses
/// chains past this depth too (the CREATE dry-run expands the body).
const MAX_VIEW_EXPANSION_DEPTH: usize = 16;

thread_local! {
    static VIEW_DEPTH: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// RAII for one level of view expansion (a `Drop` decrement paired with
/// the increment here, so early `?` returns unwind the count too).
struct ViewDepthGuard;

fn enter_view_expansion() -> Result<ViewDepthGuard> {
    let entered = VIEW_DEPTH.with(|d| {
        let n = d.get();
        if n < MAX_VIEW_EXPANSION_DEPTH {
            d.set(n + 1);
            true
        } else {
            false
        }
    });
    if entered {
        Ok(ViewDepthGuard)
    } else {
        err(format!(
            "view expansion too deep (view cycle or more than {MAX_VIEW_EXPANSION_DEPTH} nested views)"
        ))
    }
}

impl Drop for ViewDepthGuard {
    fn drop(&mut self) {
        VIEW_DEPTH.with(|d| d.set(d.get().saturating_sub(1)));
    }
}

/// Correlated-subquery evaluation budget. Each per-row correlated
/// evaluation re-enters the engine's SELECT chain (a correlated subquery
/// may itself contain one), so nesting depth costs real stack frames and
/// quadratic work; anything past this depth is a pathological shape, not a
/// query plan.
const MAX_CORRELATED_DEPTH: usize = 8;

thread_local! {
    static CORR_DEPTH: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

struct CorrDepthGuard;

fn enter_correlated_eval() -> Result<CorrDepthGuard> {
    let entered = CORR_DEPTH.with(|d| {
        let n = d.get();
        if n < MAX_CORRELATED_DEPTH {
            d.set(n + 1);
            true
        } else {
            false
        }
    });
    if entered {
        Ok(CorrDepthGuard)
    } else {
        err(format!(
            "correlated subquery nesting too deep (more than {MAX_CORRELATED_DEPTH} levels)"
        ))
    }
}

impl Drop for CorrDepthGuard {
    fn drop(&mut self) {
        CORR_DEPTH.with(|d| d.set(d.get().saturating_sub(1)));
    }
}

impl<'a> ReadCx<'a> {
    /// Evaluate one row-local expression; when it still holds subquery
    /// nodes (correlated — the pre-pass left them), resolve the outer
    /// references against this row first.
    fn eval_row_expr(
        &self,
        e: &SqlExpr,
        correlated: bool,
        doc: &Object,
        outer: &OuterFrom,
    ) -> Result<Value> {
        if correlated {
            let mut row_local = e.clone();
            self.subst_expr_row(&mut row_local, doc, outer)?;
            eval_expr(&row_local, doc)
        } else {
            eval_expr(e, doc)
        }
    }

    /// ORDER BY + LIMIT/OFFSET. Sort keys resolve in order of preference to
    /// an output column name, an ordinal position (`ORDER BY 2`), or — when
    /// the caller supplies the source docs — an arbitrary expression
    /// evaluated per row. `corr` supplies the outer scope for correlated
    /// ORDER BY expressions (plain-select path only).
    #[allow(clippy::too_many_arguments)]
    fn apply_order_limit(
        &self,
        query: Query,
        mut rows: Vec<Vec<Value>>,
        columns: &[String],
        docs: Option<Vec<Object>>,
        corr: Option<&OuterFrom>,
    ) -> Result<Vec<Vec<Value>>> {
        // (column index, asc, nulls_first); hidden key columns appended for
        // ORDER BY expressions that are not output columns stay until the
        // FETCH tie check has run.
        let mut keys: Vec<(usize, bool, Option<bool>)> = Vec::new();
        let mut extra_keys = 0usize;
        if let Some(order_by) = &query.order_by {
            let sqlparser::ast::OrderByKind::Expressions(exprs) = &order_by.kind else {
                return err("unsupported ORDER BY");
            };
            for o in exprs {
                let name = expr_name(&o.expr);
                let idx = columns.iter().position(|c| c == &name).or_else(|| {
                    // ORDER BY <ordinal>: 1-based output position.
                    name.parse::<usize>()
                        .ok()
                        .filter(|n| (1..=columns.len()).contains(n))
                        .map(|n| n - 1)
                });
                let idx = match idx {
                    Some(i) => i,
                    None => {
                        let Some(ds) = &docs else {
                            return err(format!("unknown ORDER BY key: {name}"));
                        };
                        if ds.len() != rows.len() {
                            return err(format!("unknown ORDER BY key: {name}"));
                        }
                        // Evaluate the expression against each source doc and
                        // append it as a hidden key column. Correlated nodes
                        // resolve their outer references per row (plain
                        // path, which is the only caller passing docs).
                        let sub = expr_has_subquery(&o.expr);
                        for (row, doc) in rows.iter_mut().zip(ds) {
                            row.push(match corr {
                                Some(outer) => self.eval_row_expr(&o.expr, sub, doc, outer)?,
                                None => eval_expr(&o.expr, doc)?,
                            });
                        }
                        let col = columns.len() + extra_keys;
                        extra_keys += 1;
                        col
                    }
                };
                keys.push((idx, o.options.asc.unwrap_or(true), o.options.nulls_first));
            }
            rows.sort_by(|a, b| {
                for (col, asc, nulls_first) in &keys {
                    let ord = cmp_maybe_null(&a[*col], &b[*col], *nulls_first);
                    if ord != std::cmp::Ordering::Equal {
                        return if *asc { ord } else { ord.reverse() };
                    }
                }
                std::cmp::Ordering::Equal
            });
        }
        if let Some(lc) = &query.limit_clause {
            rows = apply_limit_clause(lc, rows)?;
        }
        // Oracle 12c+/SQL-standard FETCH: `FETCH FIRST n ROWS ONLY` (and the
        // NEXT form). WITH TIES extends the window to the whole tie run of
        // the last kept row, so it needs an ORDER BY to define the peers.
        if let Some(fetch) = &query.fetch {
            if fetch.percent {
                return err("FETCH … PERCENT is not supported");
            }
            if fetch.with_ties && keys.is_empty() {
                return err("FETCH … WITH TIES requires ORDER BY");
            }
            let n = match fetch.quantity.as_ref().map(eval_const).transpose()? {
                Some(Value::Int(n)) if n >= 0 => n as usize,
                Some(Value::Int(n)) => {
                    return err(format!("FETCH quantity must be non-negative ({n})"))
                }
                Some(_) | None => return err("FETCH quantity must be an integer"),
            };
            if fetch.with_ties && n > 0 && n < rows.len() {
                let last = &rows[n - 1];
                let mut end = n;
                while end < rows.len()
                    && keys.iter().all(|(col, _, nulls_first)| {
                        cmp_maybe_null(&last[*col], &rows[end][*col], *nulls_first)
                            == Ordering::Equal
                    })
                {
                    end += 1;
                }
                rows.truncate(end);
            } else {
                rows.truncate(n);
            }
        }
        if extra_keys > 0 {
            for row in &mut rows {
                row.truncate(columns.len());
            }
        }
        Ok(rows)
    }

    /// Virtual information_schema tables from the catalog.
    fn information_schema(&self, which: &str) -> Vec<Object> {
        // Engine/internal tables stay out of the standard dictionaries —
        // same display rule as the object tree and the Oracle views (their
        // existence, names and shapes are not every user's business).
        let visible = self.tables.iter().filter(|(n, _)| !is_internal_table(n));
        let mut out = Vec::new();
        if which.ends_with("tables") {
            for (name, meta) in visible {
                out.push(Object::from([
                    ("table_name".into(), Value::Str(name.clone())),
                    ("pages".into(), Value::Int(meta.pages.len() as i64)),
                ]));
            }
        } else {
            for (name, meta) in visible {
                for col in &meta.columns {
                    out.push(Object::from([
                        ("table_name".into(), Value::Str(name.clone())),
                        ("column_name".into(), Value::Str(col.clone())),
                        (
                            "is_nullable".into(),
                            Value::Str(
                                if meta.not_null.contains(col) {
                                    "NO"
                                } else {
                                    "YES"
                                }
                                .into(),
                            ),
                        ),
                        (
                            "data_type".into(),
                            Value::Str(
                                if meta.autoguid.as_deref() == Some(col.as_str()) {
                                    "GUID"
                                } else {
                                    "ANY"
                                }
                                .into(),
                            ),
                        ),
                    ]));
                }
            }
        }
        out
    }

    /// CROSS/OUTER APPLY over a table function: evaluate the function's
    /// arguments against EACH left row (correlated lateral semantics),
    /// materialize the rowset, and merge. `outer` keeps the left row when
    /// the applied rowset is empty (right columns read as NULL — missing
    /// fields on the schemaless row shape).
    fn apply_table_function(
        &self,
        left: Vec<Object>,
        fname: &str,
        alias: &Option<sqlparser::ast::TableAlias>,
        args: &[sqlparser::ast::FunctionArg],
        outer: bool,
    ) -> Result<Vec<Object>> {
        let Some(alias_obj) = alias else {
            return err(format!(
                "{fname} requires a table alias (APPLY {fname}(...) AS t)"
            ));
        };
        let akey = alias_obj.name.value.clone();
        let fname_upper = fname.to_uppercase();
        // Static ordinal guess for the width check when no row ever
        // materializes; the argument is correlated so a non-constant
        // third argument falls back to the two-column shape.
        let ordinal_on = args.len() == 3
            && matches!(
                eval_const(match args.last() {
                    Some(sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(e),
                    )) => e,
                    _ => return err("table function arguments must be values"),
                }),
                Ok(Value::Int(n)) if n != 0
            );
        // Alias column renames apply to the produced rows (same rule as
        // derived tables).
        let mut out = Vec::with_capacity(left.len());
        let mut produced_cols: Option<Vec<String>> = None;
        for lrow in &left {
            self.deadline.check()?;
            let mut vals = Vec::new();
            for a in args {
                match a {
                    sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(e),
                    ) => vals.push(eval_expr(e, lrow)?),
                    _ => return err("table function arguments must be values"),
                }
            }
            let docs = match crate::tsql::table_function_checked(&fname_upper, &vals, &mut || {
                self.deadline.check()
            }) {
                Some(Ok(rows)) => rows,
                Some(Err(e)) => return Err(e),
                None => return err(format!("unknown table function: {fname}")),
            };
            if docs.is_empty() {
                if outer {
                    out.push(lrow.clone());
                }
                continue;
            }
            if produced_cols.is_none() {
                produced_cols = Some(docs[0].keys().cloned().collect());
            }
            for d in docs {
                let qright = qualify(&d, &akey);
                out.push(merged_row(lrow, &qright));
            }
        }
        // Actual output columns (bare names) for the rename and NULL pad.
        let cols: Vec<String> = produced_cols.unwrap_or_else(|| {
            tablefn_static_cols(&fname_upper, ordinal_on)
                .iter()
                .map(|s| s.to_string())
                .collect()
        });
        // A wrong column list must fail loudly, exactly like the derived
        // table path — swallowing it silently dropped the rename.
        let rename = table_alias_columns(&alias_obj.columns, cols.len())?;
        let final_names: Vec<String> = rename.clone().unwrap_or_else(|| cols.clone());
        let prefix = format!("{akey}.");
        for row in &mut out {
            if let Some(rename) = &rename {
                // Rename IN PLACE (move the value from the function's output
                // column to its alias). Inserting alongside would leak the
                // original column into SELECT *.
                for (new, old) in rename.iter().zip(cols.iter()) {
                    let old_key = format!("{akey}.{old}");
                    if let Some(v) = row.remove(&old_key) {
                        row.insert(format!("{akey}.{new}"), v);
                    }
                }
            }
            if outer && !row.keys().any(|k| k.starts_with(&prefix)) {
                // OUTER APPLY kept this left row because the applied rowset
                // was empty. Pad the right columns with explicit NULLs:
                // without keys, a same-named LEFT column would answer the
                // suffix fallback and masquerade as the right value.
                for c in &final_names {
                    row.insert(format!("{akey}.{c}"), Value::Null);
                }
            }
        }
        Ok(out)
    }

    /// Planned BARE column list of a table factor, when statically known:
    /// base tables/views from the catalog, table functions from their fixed
    /// shape. Used to pad explicit NULL keys when an OUTER join's other side
    /// is empty (no row to sample the key shape from). `None` = unknown
    /// (derived tables with non-trivial projections, CTEs, …) and the join
    /// keeps its historical behavior.
    fn table_factor_columns(
        &self,
        tf: &sqlparser::ast::TableFactor,
        ctes: &Ctes,
    ) -> Option<Vec<String>> {
        match tf {
            sqlparser::ast::TableFactor::Table { name, args, .. } => {
                if args.is_some() {
                    // Table-with-args = a table function whose output shape
                    // depends on evaluated arguments (STRING_SPLIT's ordinal
                    // toggle); let load_table_factor handle it and report no
                    // planned shape here.
                    return None;
                }
                let tname = obj_name(name);
                if is_compat_view(&tname) || ctes.contains_key(&tname) {
                    return None;
                }
                self.tables.get(&tname).map(|m| m.columns.clone())
            }
            sqlparser::ast::TableFactor::OpenJsonTable { .. } => Some(
                tablefn_static_cols("OPENJSON", false)
                    .iter()
                    .map(|s| s.to_string())
                    .collect(),
            ),
            _ => None,
        }
    }

    fn load_table_factor(
        &self,
        tf: &sqlparser::ast::TableFactor,
        ctes: &Ctes,
    ) -> Result<(String, Option<String>, Vec<Object>)> {
        let sqlparser::ast::TableFactor::Table {
            name,
            alias,
            args,
            with_hints,
            version,
            with_ordinality,
            partitions,
            json_path,
            sample,
            index_hints,
        } = tf
        else {
            // Derived table: FROM (SELECT ...) AS alias
            if let sqlparser::ast::TableFactor::Derived {
                lateral,
                subquery,
                alias,
                sample,
            } = tf
            {
                if *lateral {
                    return err("LATERAL derived tables are not supported");
                }
                if sample.is_some() {
                    return err("TABLESAMPLE is not supported");
                }
                // Chain the outer CTE scope through: a derived table is a
                // subquery of the statement it appears in, so `WITH t AS (…)
                // SELECT * FROM (SELECT * FROM t) d` must read the CTE —
                // and NOT fall through to a same-named base table. An own
                // WITH on the subquery materializes on top (its names
                // shadow, lexical nesting).
                let scoped = self.materialize_ctes(&subquery.with, ctes)?;
                let ExecOutcome::Rows(r) =
                    self.exec_query_body(subquery.as_ref().clone(), &scoped)?
                else {
                    return err("derived table must be a SELECT");
                };
                let alias_columns = match alias {
                    Some(a) => table_alias_columns(&a.columns, r.columns.len())?,
                    None => None,
                };
                let docs: Vec<Object> = r
                    .rows
                    .into_iter()
                    .map(|row| match &alias_columns {
                        Some(cols) => cols.iter().cloned().zip(row).collect(),
                        None => r.columns.iter().cloned().zip(row).collect(),
                    })
                    .collect();
                let alias = alias
                    .as_ref()
                    .map(|a| a.name.value.clone())
                    .unwrap_or_default();
                return Ok(("@derived".into(), Some(alias), docs));
            }
            // Bare function call in FROM: `FROM STRING_SPLIT('a,b', ',') AS s`
            // parses here, not into TableFactor::Table's args.
            if let sqlparser::ast::TableFactor::Function {
                lateral,
                name,
                args,
                with_ordinality,
                alias,
            } = tf
            {
                if *lateral {
                    return err("LATERAL table functions are not supported");
                }
                if *with_ordinality {
                    return err("WITH ORDINALITY is not supported");
                }
                let fname = obj_name(name).to_uppercase();
                if !matches!(
                    fname.as_str(),
                    "STRING_SPLIT" | "GENERATE_SERIES" | "OPENJSON"
                ) {
                    return err("table functions or FROM hints are not supported");
                }
                let mut vals = Vec::new();
                for a in args {
                    match a {
                        sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(e),
                        ) => vals.push(eval_const(e)?),
                        _ => return err("table function arguments must be values"),
                    }
                }
                let Some(alias_obj) = alias else {
                    return err(format!(
                        "{fname} requires a table alias (FROM {fname}(...) AS t)"
                    ));
                };
                let mut docs = match crate::tsql::table_function_checked(&fname, &vals, &mut || {
                    self.deadline.check()
                }) {
                    Some(Ok(rows)) => rows,
                    Some(Err(e)) => return Err(e),
                    None => return err(format!("unknown table function: {fname}")),
                };
                let ordinal_on = vals.len() == 3 && matches!(vals[2], Value::Int(n) if n != 0);
                rename_tablefn_docs(alias_obj, &fname, ordinal_on, &mut docs)?;
                return Ok(("@tablefn".into(), Some(alias_obj.name.value.clone()), docs));
            }
            // `OPENJSON(x)` parses into a dedicated factor (WITH shapes and
            // path arguments are not supported — default key/value/type
            // rows only).
            if let sqlparser::ast::TableFactor::OpenJsonTable {
                json_expr,
                json_path,
                columns,
                alias,
            } = tf
            {
                if !columns.is_empty() || json_path.is_some() {
                    return err("OPENJSON WITH (...) and path arguments are not supported");
                }
                let val = eval_const(json_expr)?;
                let Some(alias_obj) = alias else {
                    return err("OPENJSON requires a table alias (FROM OPENJSON(...) AS j)");
                };
                let mut docs =
                    match crate::tsql::table_function_checked("OPENJSON", &[val], &mut || {
                        self.deadline.check()
                    }) {
                        Some(Ok(rows)) => rows,
                        Some(Err(e)) => return Err(e),
                        None => return err("unknown table function: OPENJSON"),
                    };
                rename_tablefn_docs(alias_obj, "OPENJSON", false, &mut docs)?;
                return Ok(("@tablefn".into(), Some(alias_obj.name.value.clone()), docs));
            }
            // T-SQL PIVOT: implicit-group every column except the pivot
            // column and the aggregate's argument, then emit one column
            // per IN-list value holding the aggregate over the matching
            // rows (NULL when the group has none).
            if let sqlparser::ast::TableFactor::Pivot {
                table,
                aggregate_functions,
                value_column,
                value_source,
                default_on_null,
                alias,
            } = tf
            {
                if default_on_null.is_some() || aggregate_functions.len() != 1 {
                    return err("PIVOT supports one aggregate without DEFAULT ON NULL here");
                }
                let (inner_name, _inner_alias, docs) = self.load_table_factor(table, ctes)?;
                let pivot = pivot_factor(docs, aggregate_functions, value_column, value_source)?;
                // Same alias fallback as UNPIVOT: without it the sentinel
                // "@pivot" leaked into output column names on JOIN.
                return Ok((
                    "@pivot".into(),
                    alias
                        .as_ref()
                        .map(|a| a.name.value.clone())
                        .or(Some(inner_name)),
                    pivot,
                ));
            }
            // T-SQL UNPIVOT: one output row per (input row × listed
            // column); NULL values are excluded (T-SQL default).
            if let sqlparser::ast::TableFactor::Unpivot {
                table,
                value,
                name,
                columns,
                null_inclusion,
                alias,
            } = tf
            {
                if null_inclusion.is_some() {
                    return err(
                        "UNPIVOT INCLUDE|EXCLUDE NULLS is not supported (NULLs are excluded)",
                    );
                }
                let (inner_name, _inner_alias, docs) = self.load_table_factor(table, ctes)?;
                let out = unpivot_factor(docs, value, name, columns)?;
                return Ok((
                    "@unpivot".into(),
                    alias
                        .as_ref()
                        .map(|a| a.name.value.clone())
                        .or(Some(inner_name)),
                    out,
                ));
            }
            return err("unsupported FROM item (expected a table, derived table or VALUES)");
        };
        if let Some(args) = &args {
            // T-SQL/standard table-valued functions with a fixed, known
            // output shape (STRING_SPLIT, GENERATE_SERIES, OPENJSON):
            // constant arguments only — they materialize once per query.
            // Everything else keeps the loud table-function error.
            let fname = obj_name(name).to_uppercase();
            if !matches!(
                fname.as_str(),
                "STRING_SPLIT" | "GENERATE_SERIES" | "OPENJSON"
            ) {
                return err("table functions or FROM hints are not supported");
            }
            let list = &args.args;
            let mut vals = Vec::new();
            for a in list {
                match a {
                    sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(e),
                    ) => vals.push(eval_const(e)?),
                    _ => return err("table function arguments must be values"),
                }
            }
            let Some(alias_obj) = &alias else {
                return err(format!(
                    "{fname} requires a table alias (FROM {fname}(...) AS t)"
                ));
            };
            let alias = alias_obj.name.value.clone();
            let mut docs = match crate::tsql::table_function_checked(&fname, &vals, &mut || {
                self.deadline.check()
            }) {
                Some(Ok(rows)) => rows,
                Some(Err(e)) => return Err(e),
                None => return err(format!("unknown table function: {fname}")),
            };
            let ordinal_on = vals.len() == 3 && matches!(vals[2], Value::Int(n) if n != 0);
            rename_tablefn_docs(alias_obj, &fname, ordinal_on, &mut docs)?;
            return Ok(("@tablefn".into(), Some(alias), docs));
        }
        if sample.is_some() {
            return err("TABLESAMPLE is not supported");
        }
        if version.is_some() {
            return err("table time travel (AS OF / FOR SYSTEM_TIME) is not supported");
        }
        if !partitions.is_empty() {
            return err("partition selection (PARTITION (...)) is not supported");
        }
        if !with_hints.is_empty() {
            // MSSQL `WITH (NOLOCK)` and friends: reads are snapshot-isolated
            // here; silently accepting locking hints would misstate them.
            return err("table hints (WITH (...)) are not supported");
        }
        if !index_hints.is_empty() {
            return err("index hints are not supported");
        }
        if *with_ordinality {
            return err("WITH ORDINALITY is not supported");
        }
        if json_path.is_some() {
            return err("JSON path table sources are not supported");
        }
        if alias.as_ref().is_some_and(|a| !a.columns.is_empty()) {
            // Renaming a base table's columns is not implemented; ignoring
            // the list would silently keep the original names.
            return err("column aliases on a table alias are not supported");
        }
        let tname = obj_name(name);
        let alias = alias.as_ref().map(|a| a.name.value.clone());
        // Oracle DUAL: the one-row dummy table. Case-insensitive, works even
        // when no user table named DUAL exists (it always shadows).
        if tname.eq_ignore_ascii_case("DUAL") {
            return Ok(("DUAL".into(), alias, vec![Object::new()]));
        }
        // WITH (...) names shadow real tables for this statement.
        if let Some(docs) = ctes.get(&tname) {
            return Ok((tname, alias, docs.clone()));
        }
        let qualified: String = name
            .0
            .iter()
            .map(|p| match p {
                ObjectNamePart::Identifier(i) => i.value.clone(),
                other => other.to_string(),
            })
            .collect::<Vec<_>>()
            .join(".");
        // SQL Server-style catalog names: explicit guidance instead of the
        // confusing "table <last part> does not exist".
        let qualified_lower = qualified.to_ascii_lowercase();
        if qualified_lower.starts_with("sys.") || qualified_lower == "sysobjects" {
            return err(
                "SQL Server catalog views (sys.*/sysobjects) are not supported \
                 (use information_schema or sqlite_master)",
            );
        }
        if qualified.eq_ignore_ascii_case("sqlite_master")
            || qualified.eq_ignore_ascii_case("sqlite_temporal_master")
        {
            // SQLite-dialect compatibility view (EF Core probes it to learn
            // which tables exist). Index rows let clients enumerate CREATE
            // INDEX definitions for schema sync.
            let mut docs: Vec<Object> = self
                .tables
                .iter()
                // Same display rule as information_schema: engine/user
                // storage tables are not listed to readers.
                .filter(|(n, _)| !is_internal_table(n))
                .map(|(n, m)| {
                    Object::from([
                        ("type".into(), Value::Str("table".into())),
                        ("name".into(), Value::Str(n.clone())),
                        ("tbl_name".into(), Value::Str(n.clone())),
                        // Full DDL text (same generator as dump_script): the
                        // EF keep-data rebuild reads it to re-attach
                        // table-level UNIQUE/CHECK/FOREIGN KEY constraints
                        // the model does not know about — an empty text
                        // silently dropped them from every rebuilt table.
                        (
                            "sql".into(),
                            if m.is_view() {
                                Value::Str(String::new())
                            } else {
                                Value::Str(create_table_ddl(n, m))
                            },
                        ),
                    ])
                })
                .collect();
            for (tbl, meta) in self.tables.iter().filter(|(n, _)| !is_internal_table(n)) {
                for d in &meta.index_defs {
                    docs.push(Object::from([
                        ("type".into(), Value::Str("index".into())),
                        ("name".into(), Value::Str(d.name.clone())),
                        ("tbl_name".into(), Value::Str(tbl.clone())),
                        (
                            "sql".into(),
                            // Identifiers quoted: the EF provider replays
                            // this DDL verbatim during its keep-data rebuild,
                            // and a reserved-word table/column name (Order,
                            // Order) failed to parse there — taking the user's
                            // hand-made indexes down with it.
                            Value::Str(format!(
                                "CREATE {}INDEX {iname} ON {tbl} ({col}){pred}",
                                if d.unique { "UNIQUE " } else { "" },
                                iname = crate::stmt::sql_quote_ident(&d.name),
                                tbl = crate::stmt::sql_quote_ident(tbl),
                                col = d
                                    .columns
                                    .iter()
                                    .map(|c| crate::stmt::sql_quote_ident(c))
                                    .collect::<Vec<_>>()
                                    .join(", "),
                                pred = d
                                    .pred
                                    .as_deref()
                                    .map(|p| format!(" WHERE {p}"))
                                    .unwrap_or_default()
                            )),
                        ),
                    ]));
                }
            }
            return Ok(("sqlite_master".into(), alias, docs));
        }
        if qualified.eq_ignore_ascii_case("information_schema.tables")
            || qualified.eq_ignore_ascii_case("information_schema.columns")
        {
            let docs = self.information_schema(&qualified_lower);
            return Ok(("information_schema".into(), alias, docs));
        }
        // Oracle data-dictionary compatibility views (case-insensitive):
        // USER_* and ALL_* carry the same data — DocSQL has one global
        // namespace, so every owner sees every user table.
        let dq = qualified.to_ascii_uppercase();
        if matches!(
            dq.as_str(),
            "ALL_TABLES"
                | "USER_TABLES"
                | "ALL_TAB_COLUMNS"
                | "USER_TAB_COLUMNS"
                | "ALL_INDEXES"
                | "USER_INDEXES"
        ) {
            let owner = "DOCSQL";
            let mut docs: Vec<Object> = Vec::new();
            let user_tables: Vec<(&String, &std::sync::Arc<TableMeta>)> = self
                .tables
                .iter()
                .filter(|(n, _)| !is_internal_table(n))
                .collect();
            match dq.as_str() {
                "ALL_TABLES" | "USER_TABLES" => {
                    for (n, meta) in &user_tables {
                        docs.push(Object::from([
                            ("owner".into(), Value::Str(owner.into())),
                            ("table_name".into(), Value::Str((*n).clone())),
                            ("num_rows".into(), Value::Null),
                            ("blocks".into(), Value::Int(meta.pages.len() as i64)),
                        ]));
                    }
                }
                "ALL_TAB_COLUMNS" | "USER_TAB_COLUMNS" => {
                    for (n, meta) in &user_tables {
                        for (i, col) in meta.columns.iter().enumerate() {
                            docs.push(Object::from([
                                ("owner".into(), Value::Str(owner.into())),
                                ("table_name".into(), Value::Str((*n).clone())),
                                ("column_name".into(), Value::Str(col.clone())),
                                ("data_type".into(), Value::Str("TEXT".into())),
                                (
                                    "nullable".into(),
                                    Value::Str(
                                        if meta.not_null.contains(col) {
                                            "N"
                                        } else {
                                            "Y"
                                        }
                                        .into(),
                                    ),
                                ),
                                ("column_id".into(), Value::Int(i as i64 + 1)),
                            ]));
                        }
                    }
                }
                _ => {
                    for (tbl, meta) in &user_tables {
                        for d in &meta.index_defs {
                            docs.push(Object::from([
                                ("owner".into(), Value::Str(owner.into())),
                                ("index_name".into(), Value::Str(d.name.clone())),
                                ("table_name".into(), Value::Str((*tbl).clone())),
                                (
                                    "uniqueness".into(),
                                    Value::Str(
                                        if d.unique { "UNIQUE" } else { "NONUNIQUE" }.into(),
                                    ),
                                ),
                            ]));
                        }
                    }
                }
            }
            let view = match dq.as_str() {
                v if v.starts_with("ALL_") => v.to_string(),
                v => format!("USER_{}", &v[5..]),
            };
            return Ok((view, alias, docs));
        }
        // User view (CREATE VIEW): expand to the stored query's rows. The
        // expansion re-executes the view body as a plain SELECT over the
        // current catalog (a view of a view recurses naturally). CREATE
        // OR REPLACE can still produce a catalog cycle despite the
        // creation-time checks, so every expansion level is budgeted —
        // a cycle or an absurdly deep chain errors instead of blowing
        // the stack.
        if let Some(meta) = self.tables.get(&tname) {
            if meta.is_view() {
                let _guard = enter_view_expansion()?;
                let body = meta.view_sql.clone().unwrap_or_default();
                let q = Database::plain_read_query(&Database::parse_classified(&body)?)?;
                let ExecOutcome::Rows(r) = self.exec_query(q)? else {
                    return err(format!("view {tname} body must be a SELECT"));
                };
                let docs: Vec<Object> = r
                    .rows
                    .into_iter()
                    .map(|row| r.columns.iter().cloned().zip(row).collect())
                    .collect();
                return Ok((tname, alias, docs));
            }
        }
        let docs = self.table_docs(&tname)?;
        Ok((tname, alias, docs))
    }

    fn agg_spec(&self, e: &SqlExpr, group_exprs: &[SqlExpr]) -> Result<AggSpec> {
        // A projection item equal to a GROUP BY expression echoes its key.
        for (i, g) in group_exprs.iter().enumerate() {
            if format!("{g}") == format!("{e}") {
                return Ok(AggSpec::GroupKey { idx: i });
            }
        }
        if let SqlExpr::Identifier(i) = e {
            // Bare column: allowed only if some group expr is that column.
            for (i2, g) in group_exprs.iter().enumerate() {
                if matches!(g, SqlExpr::Identifier(gi) if gi.value == i.value) {
                    return Ok(AggSpec::GroupKey { idx: i2 });
                }
            }
            return err(format!(
                "column {} must appear in GROUP BY or an aggregate",
                i.value
            ));
        }
        if let SqlExpr::Function(f) = e {
            if f.name.to_string().eq_ignore_ascii_case("grouping") {
                // GROUPING(expr): expression must be one of the grouping-set
                // expressions (validated here, resolved per set at eval).
                let arg = match &f.args {
                    sqlparser::ast::FunctionArguments::List(list) if list.args.len() == 1 => {
                        match &list.args[0] {
                            sqlparser::ast::FunctionArg::Unnamed(
                                sqlparser::ast::FunctionArgExpr::Expr(inner),
                            ) => inner.clone(),
                            _ => return err("GROUPING argument must be a column expression"),
                        }
                    }
                    _ => return err("GROUPING takes exactly one argument"),
                };
                for (i, g) in group_exprs.iter().enumerate() {
                    let same = format!("{g}") == format!("{arg}")
                        || matches!((g, &arg),
                            (SqlExpr::Identifier(a), SqlExpr::Identifier(b)) if a.value == b.value);
                    if same {
                        return Ok(AggSpec::Grouping { idx: i });
                    }
                }
                return err(format!("GROUPING argument {arg} must appear in GROUP BY"));
            }
            if is_agg_fn(f) {
                let (op, inner, distinct, sep, filter) = agg_parts(f, false)?;
                return Ok(AggSpec::Agg {
                    op,
                    arg: inner,
                    distinct,
                    sep,
                    filter,
                });
            }
        }
        // Composite expressions containing aggregate calls.
        if contains_agg(e) {
            check_group_refs(e, group_exprs)?;
            return Ok(AggSpec::Composite { expr: e.clone() });
        }
        err(format!("unsupported aggregate projection: {e}"))
    }

    /// GROUP BY + aggregates (+ HAVING).
    /// GROUP BY + aggregates (+ HAVING) over one or more grouping sets
    /// (`GROUP BY` is one set; ROLLUP/CUBE/GROUPING SETS expand to several).
    /// Rows of a set that omits an expression emit NULL for it; GROUPING()
    /// distinguishes that from a NULL value.
    fn exec_grouped_select(
        &self,
        query: Query,
        select: sqlparser::ast::Select,
        rows: Vec<Object>,
        grouping_sets: Vec<Vec<SqlExpr>>,
    ) -> Result<ExecOutcome> {
        // Union of every set expression, in first-appearance order:
        // projection specs resolve against it, and each set resolves the
        // subset it carries.
        let mut all_exprs: Vec<SqlExpr> = Vec::new();
        for set in &grouping_sets {
            for e in set {
                if !all_exprs.iter().any(|g| format!("{g}") == format!("{e}")) {
                    all_exprs.push(e.clone());
                }
            }
        }
        // Projection must be aggregate functions or group exprs.
        let mut columns = Vec::new();
        let mut agg_specs = Vec::new(); // per column: AggSpec
        for item in &select.projection {
            match item {
                SelectItem::UnnamedExpr(e) => {
                    columns.push(expr_name(e));
                    agg_specs.push(self.agg_spec(e, &all_exprs)?);
                }
                SelectItem::ExprWithAlias { expr, alias, .. } => {
                    columns.push(alias.value.clone());
                    agg_specs.push(self.agg_spec(expr, &all_exprs)?);
                }
                _ => return err("unsupported item in aggregate SELECT"),
            }
        }
        let mut out: Vec<Vec<Value>> = Vec::new();
        if let Some(having) = &select.having {
            // Resolve references before evaluating: a bare column that is
            // neither grouped nor projected would silently read NULL and drop
            // every group instead of erroring.
            check_having_refs(having, &all_exprs, &columns)?;
        }
        for set in &grouping_sets {
            // Statement timeout reaches here too: the sets × rows × groups
            // loops below run outside the WHERE scan's own sampling.
            self.deadline.check()?;
            // Group the rows by this set's expressions. Groups hash by the
            // encoded key — the same byte identity DISTINCT uses — instead
            // of a linear scan per row (O(rows × groups)).
            let mut groups: Vec<(Vec<Value>, Vec<&Object>)> = Vec::new();
            let mut group_index: std::collections::HashMap<Vec<u8>, usize> =
                std::collections::HashMap::new();
            for doc in &rows {
                // Inside the row loop too: one set over a big table must
                // stay interruptible (the per-set check above samples only
                // once per set).
                self.deadline.check()?;
                let key: Vec<Value> = set
                    .iter()
                    .map(|e| eval_expr(e, doc))
                    .collect::<Result<_>>()?;
                let kb = row_key(&key);
                match group_index.get(&kb) {
                    Some(&gi) => groups[gi].1.push(doc),
                    None => {
                        group_index.insert(kb, groups.len());
                        groups.push((key, vec![doc]));
                    }
                }
            }
            // An empty set is one group over everything, even with no rows.
            if set.is_empty() && groups.is_empty() {
                groups.push((vec![], vec![]));
            }
            for (key, docs) in &groups {
                self.deadline.check()?;
                let mut row = Vec::with_capacity(agg_specs.len());
                for spec in &agg_specs {
                    row.push(eval_grouped_spec(spec, &all_exprs, set, key, docs)?);
                }
                // HAVING: aggregates evaluate over the group's rows directly;
                // everything else evaluates against the output columns, with
                // this set's expressions consulted before them so group keys
                // resolve and omitted ones read as NULL.
                if let Some(having) = &select.having {
                    let doc: Object = columns.iter().cloned().zip(row.iter().cloned()).collect();
                    if !matches!(eval_group_expr(having, &doc, docs, set)?, Value::Bool(true)) {
                        continue;
                    }
                }
                out.push(row);
            }
        }
        // DISTINCT applies to the projected rows here too: when GROUP BY
        // keys are finer than the projection (or GROUPING SETS repeat a
        // shape) duplicate output rows must fold — the plain path does the
        // same at this position, by encoded row identity. DISTINCT ON stays
        // an explicit unsupported feature instead of silently passing.
        let out = match &select.distinct {
            Some(sqlparser::ast::Distinct::On(cols)) => {
                return err(format!(
                    "DISTINCT ON is not supported: {}",
                    cols.iter().map(expr_name).collect::<Vec<_>>().join(", ")
                ));
            }
            Some(sqlparser::ast::Distinct::Distinct) => {
                let mut seen = std::collections::BTreeSet::new();
                let mut kept = Vec::with_capacity(out.len());
                for row in out {
                    self.deadline.check()?;
                    let key = encode::encode_to_vec(&Value::Array(row.clone()))
                        .map_err(SqlError::Encode)?;
                    if seen.insert(key) {
                        kept.push(row);
                    }
                }
                kept
            }
            None | Some(sqlparser::ast::Distinct::All) => out,
        };
        let out = self.apply_order_limit(query, out, &columns, None, None)?;
        Ok(ExecOutcome::Rows(QueryResult { columns, rows: out }))
    }

    /// No aggregation: project expressions over rows.
    fn exec_plain_select(
        &self,
        query: Query,
        mut select: sqlparser::ast::Select,
        rows: Vec<Object>,
        pre_windowed: bool,
    ) -> Result<ExecOutcome> {
        let mut want_star = false;
        let mut project: Vec<(String, SqlExpr)> = Vec::new();
        for item in &select.projection {
            match item {
                SelectItem::Wildcard(_) => want_star = true,
                SelectItem::UnnamedExpr(e) => project.push((expr_name(e), e.clone())),
                SelectItem::ExprWithAlias { expr, alias, .. } => {
                    project.push((alias.value.clone(), expr.clone()))
                }
                _ => return err("unsupported select item"),
            }
        }
        let columns_out: Vec<String> = if want_star {
            // SELECT *, expr: star fields first, then the explicit
            // projections (SQLite semantics) — dropping the exprs silently
            // returned fewer columns than the statement asked for. The
            // ROWNUM pseudo-column (if injected) is not part of * — Oracle
            // semantics.
            let mut cols: Vec<String> = union_of_fields(&rows)
                .into_iter()
                .filter(|c| c != "ROWNUM")
                .collect();
            if cols.is_empty() {
                // Empty rowset: `SELECT *` still owes its column metadata —
                // ADO readers (EF SchemaSync's ExistingColumns via
                // `SELECT * … LIMIT 0`) learn the shape from the names, and
                // a data-derived union left them with ZERO columns on an
                // empty table. Declared columns of the FROM factors are the
                // shape; the SAME qualification rule as load_from applies:
                // a solo table keeps bare names, anything joined carries
                // "alias.col" keys (the merged-row key shape) — matching
                // what the same query returns with rows present. Views keep
                // zero columns honestly (their shape is the stored query's,
                // not the catalog's).
                let joined = select.from.len() > 1
                    || select.from.first().is_some_and(|f| !f.joins.is_empty());
                let mut v: Vec<String> = Vec::new();
                for twj in &select.from {
                    collect_star_columns(&twj.relation, self.tables, &mut v, joined);
                    for j in &twj.joins {
                        collect_star_columns(&j.relation, self.tables, &mut v, true);
                    }
                }
                v.sort();
                v.dedup();
                cols = v;
            }
            cols.extend(project.iter().map(|(n, _)| n.clone()));
            cols
        } else {
            project.iter().map(|(n, _)| n.clone()).collect()
        };

        let mut docs = rows;
        // SELECT-list + QUALIFY window functions: compute over the filtered
        // rowset (SQL window semantics — after WHERE, before DISTINCT/ORDER
        // BY/QUALIFY), then rewrite each call site into a reference of its
        // private computed column so projection/QUALIFY evaluation is plain
        // column reads.
        let mut win_calls = window_calls_of(&select.projection);
        if let Some(q) = &select.qualify {
            for c in window_calls_of_expr(q) {
                if !win_calls.iter().any(|w| format!("{w}") == format!("{c}")) {
                    win_calls.push(c);
                }
            }
        }
        let mut win_tmps: Vec<String> = Vec::new();
        if !win_calls.is_empty() {
            if pre_windowed {
                return err("internal: window function reached the pre-windowed fast path");
            }
            // Declared columns of the FROM tables: a column ADDed without a
            // DEFAULT never appears in stored rows, so the row-key universe
            // alone would misjudge its window references as unknown.
            let mut from_cols: std::collections::HashSet<String> = std::collections::HashSet::new();
            for twj in &select.from {
                collect_factor_columns(&twj.relation, self.tables, &mut from_cols);
                for j in &twj.joins {
                    collect_factor_columns(&j.relation, self.tables, &mut from_cols);
                }
            }
            win_tmps = self.compute_windows(&win_calls, &mut docs, &from_cols)?;
            for (_, e) in project.iter_mut() {
                rewrite_windows(e, &win_calls, &win_tmps);
            }
        }
        // QUALIFY (SQL:1999 T618, Snowflake/DuckDB/Teradata spelling):
        // row-local filter over the windowed rowset — after windows, before
        // DISTINCT/ORDER BY. Identical window calls share the projection's
        // computed columns (dedupe by rendered key). A windowless QUALIFY
        // (plain columns only) is a late WHERE and filters the same way —
        // dropping the filter would silently return unqualified rows.
        if let Some(q) = &mut select.qualify {
            rewrite_windows(q, &win_calls, &win_tmps);
            let outer_from = {
                let mut s = OuterFrom::new();
                from_list_names(&select.from, &mut s);
                s
            };
            docs.retain(|doc| {
                matches!(
                    self.eval_row_expr(q, expr_has_subquery(q), doc, &outer_from),
                    Ok(Value::Bool(true))
                )
            });
        }
        let mut out: Vec<Vec<Value>> = Vec::new();
        // Correlated-subquery support: projection expressions still holding
        // subquery nodes resolve their outer references per row.
        let outer_from = {
            let mut s = OuterFrom::new();
            from_list_names(&select.from, &mut s);
            s
        };
        let corr: Vec<bool> = project.iter().map(|(_, e)| expr_has_subquery(e)).collect();
        for doc in &docs {
            // The projection loop is the only per-row work a WHERE-less
            // SELECT does over a big table — keep the statement timeout
            // armed here (the WHERE path samples inside matches_in).
            self.deadline.check()?;
            if want_star {
                let mut row: Vec<Value> = columns_out
                    .iter()
                    .map(|c| doc.get(c).cloned().unwrap_or(Value::Null))
                    .collect();
                // The trailing project.len() slots are the explicit exprs.
                let base = columns_out.len() - project.len();
                for (i, (_, e)) in project.iter().enumerate() {
                    row[base + i] = self.eval_row_expr(e, corr[i], doc, &outer_from)?;
                }
                out.push(row);
            } else {
                let mut row = Vec::with_capacity(project.len());
                for (i, (_, e)) in project.iter().enumerate() {
                    row.push(self.eval_row_expr(e, corr[i], doc, &outer_from)?);
                }
                out.push(row);
            }
        }
        // DISTINCT: drop duplicate projected rows; the first occurrence's
        // source doc stays for ORDER BY evaluation. DISTINCT ON (...) is a
        // different (unsupported) feature and must not pass silently.
        match &select.distinct {
            Some(sqlparser::ast::Distinct::On(cols)) => {
                return err(format!(
                    "DISTINCT ON is not supported: {}",
                    cols.iter().map(expr_name).collect::<Vec<_>>().join(", ")
                ));
            }
            Some(sqlparser::ast::Distinct::Distinct) => {
                let mut seen = std::collections::BTreeSet::new();
                let mut kept_docs = Vec::with_capacity(docs.len());
                let mut kept_rows = Vec::with_capacity(out.len());
                for (doc, row) in docs.into_iter().zip(out) {
                    self.deadline.check()?;
                    let key = encode::encode_to_vec(&Value::Array(row.clone()))
                        .map_err(SqlError::Encode)?;
                    if seen.insert(key) {
                        kept_docs.push(doc);
                        kept_rows.push(row);
                    }
                }
                docs = kept_docs;
                out = kept_rows;
            }
            None | Some(sqlparser::ast::Distinct::All) => {}
        }
        if !pre_windowed {
            out =
                self.apply_order_limit(query, out, &columns_out, Some(docs), Some(&outer_from))?;
        }
        Ok(ExecOutcome::Rows(QueryResult {
            columns: columns_out,
            rows: out,
        }))
    }

    /// Evaluate one SELECT list's window functions over the (already
    /// WHERE-filtered) rows and inject the results as private `__w<i>$`
    /// columns. Row order in `rows` is the stable scan order: it defines
    /// the arbitrary-but-deterministic order when the OVER spec carries no
    /// ORDER BY, and the tie order the stable sort preserves. Returns the
    /// private column chosen per call (collision-free against the rows' own
    /// fields) for the projection rewrite to reference.
    fn compute_windows(
        &self,
        calls: &[Function],
        rows: &mut [Object],
        from_cols: &std::collections::HashSet<String>,
    ) -> Result<Vec<String>> {
        // Column universe for the unknown-column guard below, doubling as
        // the name pool the private `__w<i>$` columns must not collide with.
        // Row keys carry the JOIN-qualified names; `from_cols` adds the
        // tables' declared columns (present in meta even when no stored row
        // carries them yet).
        let mut occupied: std::collections::HashSet<String> = std::collections::HashSet::new();
        let mut cols: std::collections::HashSet<String> = std::collections::HashSet::new();
        for r in rows.iter() {
            for k in r.keys() {
                occupied.insert(k.clone());
                cols.insert(k.clone());
            }
        }
        for c in from_cols {
            occupied.insert(c.clone());
            cols.insert(c.clone());
        }
        let mut tmp_names: Vec<String> = Vec::with_capacity(calls.len());
        for (ci, f) in calls.iter().enumerate() {
            self.deadline.check()?;
            let fname = f.name.to_string().to_uppercase();
            let aggregate = is_agg_name(f);
            let spec = validate_window_spec(f, &fname, aggregate)?;
            // Custom frame (ROWS/RANGE/GROUPS BETWEEN … AND …): structure
            // checked and offsets const-evaluated once per call.
            let frame_plan = match &spec.window_frame {
                Some(fr) => Some(parse_window_frame(fr, spec.order_by.len())?),
                None => None,
            };
            // Unknown columns evaluate to NULL on every row, which for a
            // window key silently collapses the whole computation (RANK all
            // 1s, running totals over the entire partition) — refuse the
            // statement instead. Resolution mirrors `lookup_col`: the exact
            // key, or any joined "alias.col" key with a matching leaf. An
            // EMPTY rowset carries no column universe — skip (there is
            // nothing to compute anyway) rather than rejecting everything.
            if !rows.is_empty() {
                for e in spec
                    .partition_by
                    .iter()
                    .chain(spec.order_by.iter().map(|o| &o.expr))
                {
                    check_window_columns(e, &cols)?;
                }
                for a in fn_args(f) {
                    check_window_columns(&a, &cols)?;
                }
                if let Some(flt) = &f.filter {
                    check_window_columns(flt, &cols)?;
                }
            }
            let ordered = !spec.order_by.is_empty();
            // Partition keys per row: groups hash by encoded key, the same
            // identity DISTINCT and GROUP BY use.
            let mut groups: Vec<(Vec<u8>, Vec<usize>)> = Vec::new();
            let mut part_index: std::collections::HashMap<Vec<u8>, usize> =
                std::collections::HashMap::new();
            for (i, doc) in rows.iter().enumerate() {
                self.deadline.check()?;
                let mut key = Vec::with_capacity(spec.partition_by.len());
                for p in &spec.partition_by {
                    key.push(eval_expr(p, doc)?);
                }
                let kb = row_key(&key);
                match part_index.get(&kb) {
                    Some(&gi) => groups[gi].1.push(i),
                    None => {
                        part_index.insert(kb.clone(), groups.len());
                        groups.push((kb, vec![i]));
                    }
                }
            }
            // Aggregates fold incrementally over the growing default frame
            // (RunningAgg below); scalar window functions are computed here.
            let agg = if aggregate {
                let (op, arg, distinct, sep, filter) = agg_parts(f, true)?;
                Some((op, arg, distinct, sep, filter))
            } else {
                None
            };
            let mut vals: Vec<Value> = vec![Value::Null; rows.len()];
            for (_, idxs) in &groups {
                self.deadline.check()?;
                // Sorted order within the partition: the outer ORDER BY
                // comparator (cmp_maybe_null + per-key ASC), stable so ties
                // keep scan order. `keyed` pairs each row index with its
                // order-key tuple; peer runs compare consecutive tuples.
                let mut keyed: Vec<(usize, Vec<Value>)> = Vec::with_capacity(idxs.len());
                for &i in idxs {
                    self.deadline.check()?;
                    let mut ks = Vec::with_capacity(spec.order_by.len());
                    for o in &spec.order_by {
                        ks.push(eval_expr(&o.expr, &rows[i])?);
                    }
                    keyed.push((i, ks));
                }
                if ordered {
                    keyed.sort_by(|a, b| {
                        for ((va, vb), o) in a.1.iter().zip(b.1.iter()).zip(&spec.order_by) {
                            let ord = cmp_maybe_null(va, vb, o.options.nulls_first);
                            if ord != Ordering::Equal {
                                return if o.options.asc.unwrap_or(true) {
                                    ord
                                } else {
                                    ord.reverse()
                                };
                            }
                        }
                        Ordering::Equal
                    });
                }
                let sorted: Vec<usize> = keyed.iter().map(|(i, _)| *i).collect();
                let n = sorted.len();
                // Peer runs: run_end[p] / run_start[p] bound the run holding
                // p (consecutive order-key tuples compare equal);
                // group_spans/group_of carry the same layout for GROUPS
                // frame units. Unordered partitions treat every row as its
                // own group.
                let mut run_end = vec![n - 1; n];
                let mut run_start = vec![0usize; n];
                let mut group_spans: Vec<(usize, usize)> = if ordered {
                    Vec::new()
                } else {
                    (0..n).map(|i| (i, i)).collect()
                };
                let mut group_of: Vec<usize> = if ordered {
                    vec![0; n]
                } else {
                    (0..n).collect()
                };
                if ordered {
                    let mut p = 0usize;
                    while p < n {
                        let mut q = p;
                        while q + 1 < n {
                            let equal = spec
                                .order_by
                                .iter()
                                .zip(&keyed[p].1)
                                .zip(&keyed[q + 1].1)
                                .all(|((o, ka), kb)| {
                                    cmp_maybe_null(ka, kb, o.options.nulls_first) == Ordering::Equal
                                });
                            if !equal {
                                break;
                            }
                            q += 1;
                        }
                        run_end[p..=q].fill(q);
                        run_start[p..=q].fill(p);
                        let gi = group_spans.len();
                        group_spans.push((p, q));
                        group_of[p..=q].fill(gi);
                        p = q + 1;
                    }
                }
                if let Some((op, arg, distinct, sep, filter)) = &agg {
                    let count_star =
                        matches!(arg, SqlExpr::Identifier(i) if i.value == "__count__");
                    // FILTER first, argument second — exactly the batch
                    // order in eval_agg: an argument expression that only
                    // errors on filtered-out rows (e.g. a bitwise op on a
                    // text row) must not fail the whole window.
                    let mut passes: Vec<bool> = Vec::with_capacity(n);
                    let mut argvals: Vec<Option<Value>> = Vec::with_capacity(n);
                    for &i in &sorted {
                        self.deadline.check()?;
                        let kept = match filter {
                            Some(flt) => matches!(eval_expr(flt, &rows[i])?, Value::Bool(true)),
                            None => true,
                        };
                        passes.push(kept);
                        argvals.push(if kept {
                            Some(eval_expr(arg, &rows[i])?)
                        } else {
                            None
                        });
                    }
                    // Custom frame: per-row [lo, hi] bounds over the sorted
                    // partition.
                    let bounds = match &frame_plan {
                        Some(p) => Some(frame_bounds(
                            p,
                            &keyed,
                            &spec.order_by,
                            &group_spans,
                            &group_of,
                            n,
                        )?),
                        None => None,
                    };
                    match bounds {
                        None => {
                            // Default frame = partition start through the
                            // current row's peer run (RANGE). Without ORDER
                            // BY the frame is the whole partition. Every
                            // frame is a PREFIX of the partition, so one
                            // left-to-right fold reproduces the batch
                            // `eval_agg` over each frame exactly (same
                            // evaluation order, same NULL/DISTINCT/FILTER
                            // and tie rules) in O(n) evaluations instead of
                            // re-folding each frame O(n²).
                            let mut run =
                                RunningAgg::new(op.clone(), sep.clone(), *distinct, count_star);
                            let mut pushed = 0usize; // sorted rows [0..pushed) are folded in
                            let mut p = 0usize;
                            while p < n {
                                let end = run_end[p];
                                while pushed <= end {
                                    run.push_row(passes[pushed], argvals[pushed].as_ref())?;
                                    pushed += 1;
                                }
                                let v = run.snapshot();
                                for r in p..=end {
                                    vals[sorted[r]] = v.clone();
                                }
                                p = end + 1;
                            }
                        }
                        Some(bounds) => {
                            // Additive aggregates and MIN/MAX invert: the
                            // frame slides in O(n) total. DISTINCT and
                            // GROUP_CONCAT cannot invert — a fresh fold per
                            // row (the GROUP_CONCAT text is inherently
                            // frame-sized anyway).
                            let invertible = matches!(
                                op,
                                AggOp::Count | AggOp::Sum | AggOp::Avg | AggOp::Min | AggOp::Max
                            ) && !distinct;
                            if invertible {
                                let mut win = SlidingFrameAgg::new(op.clone(), count_star);
                                let mut next = 0usize; // next sorted position to push
                                for p in 0..n {
                                    self.deadline.check()?;
                                    let (lo, hi) = bounds[p];
                                    if hi < lo || win.degraded {
                                        // Empty frame (a value interval that
                                        // excludes the key) or unrecoverable
                                        // sliding state: fresh fold of the
                                        // slice — an empty slice keeps the
                                        // empty aggregate value (COUNT 0,
                                        // SUM/AVG/MIN/MAX NULL).
                                        let mut run = RunningAgg::new(
                                            op.clone(),
                                            sep.clone(),
                                            false,
                                            count_star,
                                        );
                                        for r in lo..=hi {
                                            run.push_row(passes[r], argvals[r].as_ref())?;
                                        }
                                        vals[sorted[p]] = run.snapshot();
                                        continue;
                                    }
                                    while next <= hi {
                                        win.push(next, passes[next], argvals[next].as_ref())?;
                                        next += 1;
                                    }
                                    win.pop_to(lo);
                                    if win.degraded {
                                        // The retraction this very row triggered
                                        // was unrecoverable: fold the frame fresh
                                        // (future rows keep taking this branch).
                                        let mut run = RunningAgg::new(
                                            op.clone(),
                                            sep.clone(),
                                            false,
                                            count_star,
                                        );
                                        for r in lo..=hi {
                                            run.push_row(passes[r], argvals[r].as_ref())?;
                                        }
                                        vals[sorted[p]] = run.snapshot();
                                        continue;
                                    }
                                    vals[sorted[p]] = win.value();
                                }
                            } else {
                                for p in 0..n {
                                    self.deadline.check()?;
                                    let (lo, hi) = bounds[p];
                                    let mut run = RunningAgg::new(
                                        op.clone(),
                                        sep.clone(),
                                        *distinct,
                                        count_star,
                                    );
                                    for r in lo..=hi {
                                        run.push_row(passes[r], argvals[r].as_ref())?;
                                    }
                                    vals[sorted[p]] = run.snapshot();
                                }
                            }
                        }
                    }
                } else {
                    let args = fn_args(f);
                    // A frame clause rides only the value functions:
                    // ranking/offset functions have frame-independent
                    // semantics (SQL standard: they don't accept one).
                    let takes_frame = matches!(fname.as_str(), "FIRST_VALUE" | "LAST_VALUE");
                    if frame_plan.is_some() && !takes_frame {
                        return err(format!(
                            "window function {fname} does not accept a frame clause"
                        ));
                    }
                    // FIRST/LAST_VALUE walk the frame: default bounds are
                    // partition start .. peer-run end (the RANGE default).
                    let scalar_bounds = if takes_frame {
                        Some(match &frame_plan {
                            Some(p) => {
                                frame_bounds(p, &keyed, &spec.order_by, &group_spans, &group_of, n)?
                            }
                            None => (0..n).map(|p| (0, run_end[p])).collect(),
                        })
                    } else {
                        None
                    };
                    match fname.as_str() {
                        "ROW_NUMBER" | "RANK" | "DENSE_RANK" => {
                            if !args.is_empty() {
                                return err(format!("function {fname} takes no arguments"));
                            }
                            let mut dense = 0i64;
                            let mut p = 0usize;
                            while p < n {
                                self.deadline.check()?;
                                let end = run_end[p];
                                dense += 1;
                                for r in p..=end {
                                    vals[sorted[r]] = match fname.as_str() {
                                        "ROW_NUMBER" => Value::Int(r as i64 + 1),
                                        "RANK" => Value::Int(p as i64 + 1),
                                        _ => Value::Int(dense),
                                    };
                                }
                                p = end + 1;
                            }
                        }
                        "NTILE" => {
                            let buckets = match eval_const(args.first().ok_or_else(|| {
                                SqlError::Message(
                                    "function NTILE takes exactly 1 argument, got 0".into(),
                                )
                            })?)? {
                                Value::Int(b) if b >= 1 => b as usize,
                                other => {
                                    return err(format!(
                                        "NTILE buckets must be an integer >= 1, got {}",
                                        other.type_name()
                                    ));
                                }
                            };
                            let q = n / buckets;
                            let r = n % buckets;
                            for (p, &ri) in sorted.iter().enumerate() {
                                self.deadline.check()?;
                                let b = if q == 0 {
                                    p
                                } else if p < r * (q + 1) {
                                    p / (q + 1)
                                } else {
                                    r + (p - r * (q + 1)) / q
                                };
                                vals[ri] = Value::Int(b as i64 + 1);
                            }
                        }
                        "LAG" | "LEAD" => {
                            if args.is_empty() || args.len() > 3 {
                                return err(format!(
                                    "function {fname} takes 1 to 3 arguments, got {}",
                                    args.len()
                                ));
                            }
                            let offset = match args.get(1).map(eval_const).transpose()? {
                                None => 1i64,
                                Some(Value::Int(o)) if o >= 0 => o,
                                Some(other) => {
                                    return err(format!(
                                        "{fname} offset must be a non-negative integer, got {}",
                                        other.type_name()
                                    ));
                                }
                            };
                            for (p, &ri) in sorted.iter().enumerate() {
                                self.deadline.check()?;
                                let target: Option<usize> = if fname == "LAG" {
                                    p.checked_sub(offset as usize)
                                } else {
                                    p.checked_add(offset as usize).filter(|&t| t < n)
                                };
                                vals[ri] = match target {
                                    Some(t) => eval_expr(&args[0], &rows[sorted[t]])?,
                                    None => match args.get(2) {
                                        Some(d) => eval_expr(d, &rows[ri])?,
                                        None => Value::Null,
                                    },
                                };
                            }
                        }
                        "FIRST_VALUE" | "LAST_VALUE" => {
                            if args.len() != 1 {
                                return err(format!(
                                    "function {fname} takes exactly 1 argument, got {}",
                                    args.len()
                                ));
                            }
                            let bounds = scalar_bounds
                                .as_ref()
                                .expect("computed for the frame-taking functions");
                            for (p, &ri) in sorted.iter().enumerate() {
                                self.deadline.check()?;
                                let (lo, hi) = bounds[p];
                                let target = if fname == "FIRST_VALUE" { lo } else { hi };
                                vals[ri] = eval_expr(&args[0], &rows[sorted[target]])?;
                            }
                        }
                        other => {
                            return err(format!("unknown window function: {other}"));
                        }
                    }
                }
            }
            // Private column name: never collide with a user field — a
            // user column literally named `__w0$` would otherwise be
            // silently overwritten by the injected window value.
            let mut k = ci;
            let tmp = loop {
                let cand = window_tmp_col(k);
                if occupied.insert(cand.clone()) {
                    break cand;
                }
                k += 1;
            };
            tmp_names.push(tmp.clone());
            for (i, v) in vals.into_iter().enumerate() {
                rows[i].insert(tmp.clone(), v);
            }
        }
        Ok(tmp_names)
    }

    /// Load a FROM list into merged rows: the base table plus its JOINs,
    /// then comma-separated entries as cross joins. A lone base table keeps
    /// unqualified field names; anything joined gets "alias.col" keys.
    /// A solo real table with a probe-able WHERE skips the heap scan.
    fn load_from(
        &self,
        from: &[sqlparser::ast::TableWithJoins],
        selection: &Option<SqlExpr>,
        ctes: &Ctes,
    ) -> Result<Vec<Object>> {
        use sqlparser::ast::{JoinConstraint, JoinOperator};
        let base = &from[0];
        // Index fast path: solo base table, WHERE narrows to an indexed
        // column. Rows come straight from the B+ tree; the caller's residual
        // WHERE filter still runs over them.
        if base.joins.is_empty() && from.len() == 1 {
            if let sqlparser::ast::TableFactor::Table { name, alias, .. } = &base.relation {
                let tname = obj_name(name);
                // Same gates as the window paths: a non-plain table factor
                // (TABLESAMPLE / index hints / alias column lists / …) must
                // reach load_table_factor's loud rejections instead of being
                // silently executed as a plain scan, and compat views (dual,
                // sqlite_master, …) must not be shadowed by same-named user
                // tables depending on index presence.
                if plain_table_factor(&base.relation)
                    && !is_compat_view(&tname)
                    && self.tables.contains_key(&tname)
                    && !ctes.contains_key(&tname)
                {
                    let akey = alias.as_ref().map(|a| a.name.value.clone());
                    if let Some(pairs) =
                        self.index_probe(&tname, akey.as_deref(), selection, ctes)?
                    {
                        return Ok(pairs.into_iter().map(|(_, d)| d).collect());
                    }
                }
            }
        }
        let (bname, balias, mut bdocs) = self.load_table_factor(&base.relation, ctes)?;
        let bkey = balias.unwrap_or_else(|| bname.clone());
        let solo = base.joins.is_empty() && from.len() == 1;
        let mut rows: Vec<Object> = if solo {
            bdocs
        } else {
            bdocs.drain(..).map(|d| qualify(&d, &bkey)).collect()
        };
        // Accumulated LEFT key shape for RIGHT/FULL joins: rows carry bare
        // base columns plus qualified keys of earlier joins; an empty left
        // side cannot be sampled, so the planned list answers instead.
        let mut left_cols: Option<Vec<String>> = if solo {
            None
        } else {
            self.table_factor_columns(&base.relation, ctes)
                .map(|cs| cs.iter().map(|c| format!("{bkey}.{c}")).collect())
        };
        let mut all_joins: Vec<&sqlparser::ast::Join> = base.joins.iter().collect();
        if !solo {
            for twj in &from[1..] {
                // comma-separated FROM entries: cross join their base tables
                let (n, a, d) = self.load_table_factor(&twj.relation, ctes)?;
                let k = a.unwrap_or(n);
                let dcols = self.table_factor_columns(&twj.relation, ctes);
                rows = join_rows(
                    rows,
                    &d,
                    &k,
                    None,
                    false,
                    false,
                    self.deadline,
                    dcols.as_deref(),
                    left_cols.as_deref(),
                )?;
                if let (Some(lc), Some(dc)) = (&mut left_cols, &dcols) {
                    lc.extend(dc.iter().map(|c| format!("{k}.{c}")));
                } else {
                    left_cols = None;
                }
                all_joins.extend(twj.joins.iter());
            }
        }
        for j in all_joins {
            // CROSS/OUTER APPLY: the right side is evaluated per left row
            // (T-SQL lateral semantics). Supported over the table-function
            // family; an APPLY over a derived table is a correlated
            // subquery — refused loudly like every other correlation.
            if matches!(
                j.join_operator,
                JoinOperator::CrossApply | JoinOperator::OuterApply
            ) {
                let outer = matches!(j.join_operator, JoinOperator::OuterApply);
                // `CROSS APPLY f(..) AS t` parses as a Table factor with
                // args (same shape as `FROM f(..)`); a factor without args
                // is an APPLY over a subquery/table — a correlated shape
                // the engine refuses like every other correlation.
                if let sqlparser::ast::TableFactor::Table {
                    name,
                    alias,
                    args: Some(tf_args),
                    ..
                } = &j.relation
                {
                    rows = self.apply_table_function(
                        rows,
                        &obj_name(name),
                        alias,
                        &tf_args.args,
                        outer,
                    )?;
                    // Applied rows carry `{alias}.{fn-col}` keys; the base
                    // column shape no longer describes the left side.
                    left_cols = None;
                    continue;
                }
                // OPENJSON keeps its dedicated factor shape in APPLY
                // position (no WITH columns/path here — correlated per-row
                // evaluation of the default key/value/type form).
                if let sqlparser::ast::TableFactor::OpenJsonTable {
                    json_expr,
                    json_path,
                    columns,
                    alias,
                } = &j.relation
                {
                    if !columns.is_empty() || json_path.is_some() {
                        return err("OPENJSON WITH (...) and path arguments are not supported");
                    }
                    let Some(alias_obj) = alias else {
                        return err("OPENJSON requires a table alias (APPLY OPENJSON(...) AS j)");
                    };
                    let akey = alias_obj.name.value.clone();
                    let mut out = Vec::with_capacity(rows.len());
                    let mut produced_cols = false;
                    let mut cols: Vec<String> = tablefn_static_cols("OPENJSON", false)
                        .iter()
                        .map(|s| s.to_string())
                        .collect();
                    for lrow in &rows {
                        self.deadline.check()?;
                        let val = eval_expr(json_expr, lrow)?;
                        let docs = match crate::tsql::table_function("OPENJSON", &[val]) {
                            Some(Ok(docs)) => docs,
                            Some(Err(e)) => return Err(e),
                            None => return err("unknown table function: OPENJSON"),
                        };
                        if docs.is_empty() {
                            if outer {
                                out.push(lrow.clone());
                            }
                            continue;
                        }
                        if !produced_cols {
                            cols = docs[0].keys().cloned().collect();
                            produced_cols = true;
                        }
                        for d in docs {
                            out.push(merged_row(lrow, &qualify(&d, &akey)));
                        }
                    }
                    // Alias column renames (`APPLY OPENJSON(..) AS j(k, v, t)`)
                    // apply positionally over the qualified output keys; an
                    // empty rowset on OUTER APPLY pads explicit NULLs so the
                    // right columns cannot fall back onto same-named left
                    // fields.
                    let rename = table_alias_columns(&alias_obj.columns, cols.len())?;
                    let final_names: Vec<String> = rename.clone().unwrap_or_else(|| cols.clone());
                    let prefix = format!("{akey}.");
                    for row in &mut out {
                        if let Some(rename) = &rename {
                            for (new, old) in rename.iter().zip(cols.iter()) {
                                let old_key = format!("{akey}.{old}");
                                if let Some(v) = row.remove(&old_key) {
                                    row.insert(format!("{akey}.{new}"), v);
                                }
                            }
                        }
                        if outer && !row.keys().any(|k| k.starts_with(&prefix)) {
                            for c in &final_names {
                                row.insert(format!("{akey}.{c}"), Value::Null);
                            }
                        }
                    }
                    rows = out;
                    left_cols = None;
                    continue;
                }
                return err(
                    "APPLY over a subquery is not supported (correlated subqueries); \
                     apply a table function (STRING_SPLIT/GENERATE_SERIES/OPENJSON)",
                );
            }
            let (jname, jalias, jdocs) = self.load_table_factor(&j.relation, ctes)?;
            let jkey = jalias.unwrap_or(jname);
            let jcols = self.table_factor_columns(&j.relation, ctes);
            let (left_join, right_join, on) = match &j.join_operator {
                JoinOperator::Join(c)
                | JoinOperator::Inner(c)
                | JoinOperator::Left(c)
                | JoinOperator::LeftOuter(c)
                | JoinOperator::Right(c)
                | JoinOperator::RightOuter(c)
                | JoinOperator::FullOuter(c) => {
                    let on = match c {
                        JoinConstraint::On(e) => Some(e.clone()),
                        JoinConstraint::Using(cols) => {
                            // a USING b == ON left.b = right.b, with `left`
                            // resolved against the ACCUMULATED left rows: in
                            // a join chain the column may belong to a middle
                            // table, and binding it to the base table read
                            // the merged row as NULL (silently zero rows).
                            let mut e = None;
                            for c in cols {
                                let col = obj_name(c);
                                let suffix = format!(".{col}");
                                let owner = match rows.first() {
                                    Some(sample) => {
                                        let owners: Vec<&str> = sample
                                            .keys()
                                            .filter_map(|k| k.strip_suffix(&suffix))
                                            .collect();
                                        match owners.as_slice() {
                                            [] => {
                                                return err(format!(
                                                    "USING column {col} does not exist on the left side of the join"
                                                ))
                                            }
                                            [one] => (*one).to_string(),
                                            _ => {
                                                return err(format!(
                                                    "USING column {col} is ambiguous on the left side of the join"
                                                ))
                                            }
                                        }
                                    }
                                    // No rows yet: nothing to verify against;
                                    // keep the historical base-table binding.
                                    None => bkey.clone(),
                                };
                                let eq = SqlExpr::BinaryOp {
                                    left: Box::new(SqlExpr::Identifier(
                                        sqlparser::ast::Ident::new(format!("{owner}.{col}")),
                                    )),
                                    op: sqlparser::ast::BinaryOperator::Eq,
                                    right: Box::new(SqlExpr::Identifier(
                                        sqlparser::ast::Ident::new(format!("{jkey}.{col}")),
                                    )),
                                };
                                e = Some(match e {
                                    None => eq,
                                    Some(prev) => SqlExpr::BinaryOp {
                                        left: Box::new(prev),
                                        op: sqlparser::ast::BinaryOperator::And,
                                        right: Box::new(eq),
                                    },
                                });
                            }
                            e
                        }
                        // NATURAL would need the common-column set; the
                        // schemaless row shape has no schema to derive it at
                        // plan time, so refuse instead of cross-joining.
                        JoinConstraint::Natural => {
                            return err("NATURAL JOIN is not supported (use ON/USING)")
                        }
                        // JOIN without ON: MySQL-style cross join.
                        JoinConstraint::None => None,
                    };
                    let (mut left_join, mut right_join) = (false, false);
                    match &j.join_operator {
                        JoinOperator::Left(_) | JoinOperator::LeftOuter(_) => left_join = true,
                        JoinOperator::Right(_) | JoinOperator::RightOuter(_) => right_join = true,
                        JoinOperator::FullOuter(_) => {
                            left_join = true;
                            right_join = true;
                        }
                        _ => {}
                    }
                    (left_join, right_join, on)
                }
                JoinOperator::CrossJoin(_) => (false, false, None),
                other => return err(format!("unsupported join type: {}", join_op_name(other))),
            };
            rows = join_rows(
                rows,
                &jdocs,
                &jkey,
                on.as_ref(),
                left_join,
                right_join,
                self.deadline,
                jcols.as_deref(),
                left_cols.as_deref(),
            )?;
            if let (Some(lc), Some(jc)) = (&mut left_cols, &jcols) {
                lc.extend(jc.iter().map(|c| format!("{jkey}.{c}")));
            } else {
                left_cols = None;
            }
        }
        Ok(rows)
    }

    fn exec_select(
        &self,
        mut query: Query,
        mut select: sqlparser::ast::Select,
        ctes: &Ctes,
    ) -> Result<ExecOutcome> {
        reject_unsupported_select_clauses(&select)?;
        // Outer scope for correlated subqueries: this level's FROM names and
        // aliases. WHERE / projection / ORDER BY are row-local surfaces and
        // may keep correlated nodes for per-row evaluation; JOIN ON, GROUP BY
        // and HAVING evaluate outside a full row (partial join images, group
        // images), where correlation must stay a loud error.
        let outer_from = {
            let mut s = OuterFrom::new();
            from_list_names(&select.from, &mut s);
            s
        };
        // Resolve uncorrelated subqueries up front so the row-local
        // expression evaluator never sees them.
        if let Some(sel) = &mut select.selection {
            self.subst_expr_scoped(sel, &outer_from, true)?;
        }
        // QUALIFY is a row-local post-window surface (same phase as WHERE,
        // evaluated after window computation) — uncorrelated subqueries
        // resolve up front like WHERE's.
        if let Some(q) = &mut select.qualify {
            self.subst_expr_scoped(q, &outer_from, true)?;
        }
        // JOIN ON conditions can carry uncorrelated subqueries too
        // (`ON a.x = (SELECT MIN(y) FROM b)`); without the same substitution
        // the row-local evaluator misreports them as correlated.
        for twj in &mut select.from {
            for j in &mut twj.joins {
                if let Some(e) = join_on_expr_mut(&mut j.join_operator) {
                    self.subst_expr_scoped(e, &outer_from, false)?;
                }
            }
        }
        // ORDER BY expressions too: EF Core emits `ORDER BY (SELECT 1)` for
        // Skip/Take without an explicit ordering key.
        if let Some(ob) = &mut query.order_by {
            if let sqlparser::ast::OrderByKind::Expressions(exprs) = &mut ob.kind {
                for o in exprs.iter_mut() {
                    self.subst_expr_scoped(&mut o.expr, &outer_from, true)?;
                }
            }
        }
        for item in &mut select.projection {
            match item {
                SelectItem::UnnamedExpr(e) => self.subst_expr_scoped(e, &outer_from, true)?,
                SelectItem::ExprWithAlias { expr, .. } => {
                    self.subst_expr_scoped(expr, &outer_from, true)?
                }
                _ => {}
            }
        }
        if let sqlparser::ast::GroupByExpr::Expressions(es, _) = &mut select.group_by {
            for e in es {
                self.subst_expr_scoped(e, &outer_from, false)?;
            }
        }
        if let Some(having) = &mut select.having {
            self.subst_expr_scoped(having, &outer_from, false)?;
        }

        if select.from.is_empty() {
            if select.qualify.is_some() {
                return err("QUALIFY requires a FROM clause (it filters windowed rows)");
            }
            // FROM-less SELECT: one row of constant expressions; WHERE
            // filters that single row.
            let mut project: Vec<(String, SqlExpr)> = Vec::new();
            for item in &select.projection {
                match item {
                    SelectItem::UnnamedExpr(e) => project.push((expr_name(e), e.clone())),
                    SelectItem::ExprWithAlias { expr, alias, .. } => {
                        project.push((alias.value.clone(), expr.clone()))
                    }
                    _ => return err("unsupported select item"),
                }
            }
            let empty = Object::new();
            let columns = project.iter().map(|(n, _)| n.clone()).collect();
            if let Some(cond) = &select.selection {
                if !matches!(eval_expr(cond, &empty)?, Value::Bool(true)) {
                    return Ok(ExecOutcome::Rows(QueryResult {
                        columns,
                        rows: vec![],
                    }));
                }
            }
            let row = project
                .iter()
                .map(|(_, e)| eval_expr(e, &empty))
                .collect::<Result<Vec<_>>>()?;
            // FROM-less SELECT still honors LIMIT/OFFSET (`SELECT 1 LIMIT 0`
            // must return zero rows, not one) and the standard FETCH clause
            // (same truncation semantics). ORDER BY over a single row cannot
            // reorder anything.
            let mut rows = vec![row];
            if let Some(lc) = &query.limit_clause {
                rows = apply_limit_clause(lc, rows)?;
            }
            if let Some(fetch) = &query.fetch {
                if fetch.percent {
                    return err("FETCH … PERCENT is not supported");
                }
                if fetch.with_ties {
                    return err("FETCH … WITH TIES requires ORDER BY");
                }
                let n = match fetch.quantity.as_ref().map(eval_const).transpose()? {
                    Some(Value::Int(n)) if n >= 0 => n as usize,
                    Some(Value::Int(n)) => {
                        return err(format!("FETCH quantity must be non-negative ({n})"))
                    }
                    Some(_) | None => return err("FETCH quantity must be an integer"),
                };
                rows.truncate(n);
            }
            return Ok(ExecOutcome::Rows(QueryResult { columns, rows }));
        }
        // Oracle ROWNUM pseudo-column: number each row right after it is
        // retrieved (before WHERE and before ORDER BY — Oracle semantics).
        // Injected only when the statement references it, and only for the
        // non-aggregated path (aggregates + ROWNUM is refused below).
        let group_exprs: Vec<SqlExpr> = match &select.group_by {
            sqlparser::ast::GroupByExpr::Expressions(e, modifiers) => {
                // MySQL `WITH ROLLUP` / ClickHouse `WITH TOTALS` modifiers
                // would be silently dropped; the standard spellings are
                // GROUP BY ROLLUP(...) / CUBE(...) / GROUPING SETS.
                if !modifiers.is_empty() {
                    return err(
                        "GROUP BY modifiers (WITH ROLLUP/CUBE/TOTALS) are not supported \
                         (use GROUP BY ROLLUP(...)/CUBE(...))",
                    );
                }
                e.clone()
            }
            sqlparser::ast::GroupByExpr::All(_) => return err("GROUP BY ALL is not supported"),
        };
        let grouping_sets = expand_grouping_sets(&group_exprs)?;
        let is_aggregate = !group_exprs.is_empty() || select.projection.iter().any(is_agg_item);
        // With GROUP BY/aggregates ROWNUM has no row stream to number — the
        // schemaless NULL read silently passed `ROWNUM <= n` filters, so
        // refuse loudly instead.
        let refs_rownum = select_refs_rownum(&select);
        if refs_rownum && is_aggregate {
            return err("ROWNUM is not supported combined with GROUP BY or aggregate projections");
        }
        let rownum_wanted = refs_rownum && !is_aggregate;
        let distinct_all = matches!(&select.distinct, None | Some(sqlparser::ast::Distinct::All));
        // SELECT-list window functions (`… OVER (…)`) need the full
        // filtered rowset: the ORDER BY+LIMIT fast paths below would hand
        // them a truncated window, so they are gated off, and mixing with
        // GROUP BY/aggregates is refused up front (window-over-groups is
        // unsupported; refusals stay loud).
        let has_window = !window_calls_of(&select.projection).is_empty()
            || select
                .qualify
                .as_ref()
                .is_some_and(|q| !window_calls_of_expr(q).is_empty());
        if has_window && is_aggregate {
            return err("window functions (OVER) are not supported combined with \
                 GROUP BY or aggregate projections");
        }
        if select.qualify.is_some() && is_aggregate {
            return err("QUALIFY is not supported combined with \
                 GROUP BY or aggregate projections");
        }

        // `SELECT COUNT(*) FROM t` without WHERE/GROUP BY: count live heap
        // slots instead of decoding every document.
        if is_aggregate {
            if let Some(out) = self.try_count_star(&query, &select, ctes)? {
                return Ok(out);
            }
        }

        // ORDER BY <index key> + LIMIT: index-ordered window, skipping the
        // full heap scan and sort. Already filtered and windowed; the WHERE
        // pass below would be a no-op, so it is skipped too.
        let mut pre_windowed = false;
        let mut rows = if !is_aggregate
            && !rownum_wanted
            && select.having.is_none()
            && distinct_all
            && !has_window
        {
            match self.ordered_index_window(
                &select,
                &select.from,
                &select.selection,
                &query.order_by,
                &query,
                ctes,
            )? {
                Some(rows) => {
                    pre_windowed = true;
                    rows
                }
                None => match self.unindexed_order_window(&select, &query, ctes)? {
                    Some(rows) => {
                        pre_windowed = true;
                        rows
                    }
                    None => self.load_from(&select.from, &select.selection, ctes)?,
                },
            }
        } else {
            self.load_from(&select.from, &select.selection, ctes)?
        };

        if rownum_wanted {
            for (i, row) in rows.iter_mut().enumerate() {
                row.insert("ROWNUM".into(), Value::Int(i as i64 + 1));
            }
        }

        // WHERE — consuming pass: matching docs move into the kept vec
        // instead of being whole-document cloned (the filtered set is
        // often the whole table).
        if !pre_windowed && select.selection.is_some() {
            let mut kept = Vec::with_capacity(rows.len());
            for doc in rows.drain(..) {
                if self.matches_in(&select.selection, &doc, &outer_from)? {
                    kept.push(doc);
                }
            }
            rows = kept;
        }

        // Aggregation path: aggregate functions in projection or GROUP BY.
        if is_aggregate {
            return self.exec_grouped_select(query, select, rows, grouping_sets);
        }
        if select.having.is_some() {
            // Silently dropping the filter would return unfiltered rows.
            return err("HAVING requires GROUP BY or an aggregate");
        }
        self.exec_plain_select(query, select, rows, pre_windowed)
    }

    /// Execute the query body (no WITH: it was materialized by the caller
    /// into `ctes`).
    fn exec_query_body(&self, query: Query, ctes: &Ctes) -> Result<ExecOutcome> {
        let query = rewrite_tsql_top(query)?;
        reject_unsupported_query_clauses(&query)?;
        let body = query.body.clone();
        match *body {
            SetExpr::Select(select) => self.exec_select(query.clone(), *select, ctes),
            SetExpr::SetOperation {
                left,
                op,
                set_quantifier,
                right,
            } => {
                use sqlparser::ast::{SetOperator, SetQuantifier};
                if !matches!(
                    op,
                    SetOperator::Union
                        | SetOperator::Except
                        | SetOperator::Minus
                        | SetOperator::Intersect
                ) {
                    return err(format!("unsupported set operation: {op}"));
                }
                // BY NAME alignment is not implemented: silently running it
                // positionally would pair unrelated columns (and ALL BY NAME
                // would additionally lose the bag semantics to the implicit
                // DISTINCT below).
                if matches!(
                    set_quantifier,
                    SetQuantifier::ByName
                        | SetQuantifier::AllByName
                        | SetQuantifier::DistinctByName
                ) {
                    return err(
                        "UNION/INTERSECT/EXCEPT ... BY NAME is not supported (columns align positionally)".to_string(),
                    );
                }
                // Set operations combine whole result sets: strip per-arm
                // ORDER BY/LIMIT/FETCH so they apply to the combination only.
                // (Leaving `fetch` in applied `FETCH FIRST n ROWS ONLY` to
                // each arm *and* the combination, truncating the result.)
                // The WITH clause is dropped here too: the CTEs are already
                // materialized in `ctes` — re-entering exec_query per arm
                // would re-run every CTE body 2k-1 times on a k-arm chain.
                let bare = Query {
                    order_by: None,
                    limit_clause: None,
                    fetch: None,
                    with: None,
                    ..query.clone()
                };
                let l = self.exec_query_body(
                    Query {
                        body: left,
                        ..bare.clone()
                    },
                    ctes,
                )?;
                let r = self.exec_query_body(
                    Query {
                        body: right,
                        ..bare
                    },
                    ctes,
                )?;
                let (ExecOutcome::Rows(mut lr), ExecOutcome::Rows(rr)) = (l, r) else {
                    return err("set operations require SELECT on both sides");
                };
                // Column *counts* must match; names may differ (left wins).
                if lr.columns.len() != rr.columns.len() {
                    return err(format!(
                        "set operation arms have different column counts (left {}, right {})",
                        lr.columns.len(),
                        rr.columns.len()
                    ));
                }
                let all = set_quantifier == SetQuantifier::All;
                match op {
                    SetOperator::Union => {
                        lr.rows.extend(rr.rows);
                        if !all {
                            dedup_rows(&mut lr.rows);
                        }
                    }
                    SetOperator::Intersect => {
                        let mut counts = row_counts(&rr.rows);
                        let mut out = Vec::new();
                        for row in lr.rows {
                            if consume_one(&mut counts, &row) {
                                out.push(row);
                            }
                        }
                        if !all {
                            let mut out2 = out;
                            dedup_rows(&mut out2);
                            out = out2;
                        }
                        lr.rows = out;
                    }
                    // EXCEPT / MINUS share semantics.
                    SetOperator::Except | SetOperator::Minus => {
                        let mut counts = row_counts(&rr.rows);
                        let mut out = Vec::new();
                        for row in lr.rows {
                            if consume_one(&mut counts, &row) {
                                continue; // matched on the right: removed
                            }
                            out.push(row);
                        }
                        if !all {
                            let mut out2 = out;
                            dedup_rows(&mut out2);
                            out = out2;
                        }
                        lr.rows = out;
                    }
                }
                // ORDER BY / LIMIT now apply to the combined result.
                let cols = lr.columns.clone();
                let rows = self.apply_order_limit(query, lr.rows, &cols, None, None)?;
                Ok(ExecOutcome::Rows(QueryResult {
                    columns: cols,
                    rows,
                }))
            }
            SetExpr::Values(mut values) => {
                // Row-value constructor (standard SQL): constant expressions,
                // one row per parenthesized list, `column1..n` by default.
                let width = values.rows.first().map_or(0, |r| r.content.len());
                let columns: Vec<String> = (1..=width).map(|i| format!("column{i}")).collect();
                let empty = Object::new();
                let mut rows = Vec::with_capacity(values.rows.len());
                for parens in values.rows.drain(..) {
                    let mut exprs = parens.content;
                    if exprs.len() != width {
                        return err("VALUES rows must all have the same column count");
                    }
                    for e in &mut exprs {
                        self.subst_expr(e)?;
                    }
                    rows.push(
                        exprs
                            .iter()
                            .map(|e| eval_expr(e, &empty))
                            .collect::<Result<Vec<_>>>()?,
                    );
                }
                let rows = self.apply_order_limit(query, rows, &columns, None, None)?;
                Ok(ExecOutcome::Rows(QueryResult { columns, rows }))
            }
            SetExpr::Query(inner) => {
                // Parenthesized query body, e.g. `((SELECT 1))`: re-dispatch
                // the inner query (its ORDER BY/LIMIT apply) instead of
                // rejecting the shape. The parenthesized body may carry its
                // OWN WITH — materialize it on top of the current scope
                // rather than dropping it (dropping made `(WITH x AS …
                // SELECT * FROM x)` resolve x to a same-named base table or
                // fail outright).
                let mut q = *inner;
                let inner_with = q.with.take();
                let scoped = self.materialize_ctes(&inner_with, ctes)?;
                self.exec_query_body(q, &scoped)
            }
            other => err(format!("unsupported query body: {other}")),
        }
    }

    fn exec_query(&self, query: Query) -> Result<ExecOutcome> {
        let ctes = self.materialize_ctes(&query.with, &Ctes::new())?;
        self.exec_query_body(query, &ctes)
    }

    /// WITH <cte> AS (...), ...: materialize each CTE (they can reference
    /// earlier ones) into a statement-local map on top of `base` — owned by
    /// this call, so the whole SELECT execution chain can run on
    /// `&Database` (MVCC stage A concurrent readers). Extracted so derived
    /// tables and parenthesized bodies can chain the OUTER scope through
    /// instead of rebuilding an empty one (a `WITH t AS (…) SELECT * FROM
    /// (SELECT * FROM t) d` used to lose t inside the derived table and
    /// silently read a same-named base table).
    fn materialize_ctes(&self, with: &Option<sqlparser::ast::With>, base: &Ctes) -> Result<Ctes> {
        let mut ctes = base.clone();
        let Some(with) = with else {
            return Ok(ctes);
        };
        for cte in &with.cte_tables {
            let name = cte.alias.name.value.clone();
            // T-SQL spells recursion without a keyword: any CTE whose
            // UNION body references its own name recurses. The standard
            // RECURSIVE flag just makes that explicit (and is no longer
            // a rejection).
            if cte_references(&cte.query, &name) {
                let docs = self.materialize_recursive_cte(cte, &name, &ctes, with.recursive)?;
                ctes.insert(name, docs);
                continue;
            }
            let ExecOutcome::Rows(r) = self.exec_query_body(cte.query.as_ref().clone(), &ctes)?
            else {
                return err("CTE body must be a SELECT");
            };
            let alias_columns = table_alias_columns(&cte.alias.columns, r.columns.len())?;
            let docs: Vec<Object> = r
                .rows
                .into_iter()
                .map(|row| match &alias_columns {
                    Some(cols) => cols.iter().cloned().zip(row).collect(),
                    None => r.columns.iter().cloned().zip(row).collect(),
                })
                .collect();
            ctes.insert(name, docs);
        }
        Ok(ctes)
    }

    /// Semi-naive recursive CTE evaluation: run the anchor arm (which must
    /// not reference the CTE itself), then feed each iteration's rows back
    /// as the CTE's binding for the recursive arm until it produces no new
    /// rows (UNION semantics) or the caps trip (UNION ALL cycles). The
    /// working-table semantics match SQL Server: each iteration sees only
    /// the previous iteration's rows.
    fn materialize_recursive_cte(
        &self,
        cte: &sqlparser::ast::Cte,
        name: &str,
        outer: &Ctes,
        _declared_recursive: bool,
    ) -> Result<Vec<Object>> {
        const MAX_ITERATIONS: usize = 100;
        const MAX_ROWS: usize = 100_000;
        // The CTE body's own top-level ORDER BY / LIMIT / FETCH cannot ride
        // along: the anchor and recursive arms are evaluated per iteration
        // and only the outer query's clauses apply to the merged result.
        // Silently dropping them made the same CTE return different row
        // sets with and without a self-reference — reject instead.
        if cte.query.order_by.is_some()
            || cte.query.limit_clause.is_some()
            || cte.query.fetch.is_some()
        {
            return err(format!(
                "recursive CTE {name} does not support ORDER BY / LIMIT / FETCH on the \
                 CTE body (apply them in the outer query)"
            ));
        }
        let sqlparser::ast::SetExpr::SetOperation {
            left,
            op: sqlparser::ast::SetOperator::Union,
            set_quantifier,
            right,
        } = cte.query.body.as_ref()
        else {
            return err(format!(
                "recursive CTE {name} must be <anchor> UNION [ALL] <recursive arm>"
            ));
        };
        // Anchor: evaluated WITHOUT the CTE bound — a self-reference here
        // is the classic "recursive reference in an anchor" mistake.
        let ExecOutcome::Rows(anchor) = self.exec_query_body(
            sqlparser::ast::Query {
                with: None,
                body: Box::new(left.as_ref().clone()),
                order_by: None,
                limit_clause: None,
                fetch: None,
                locks: vec![],
                for_clause: None,
                settings: None,
                format_clause: None,
                pipe_operators: vec![],
            },
            outer,
        )?
        else {
            return err("recursive CTE anchor must be a SELECT");
        };
        let alias_columns = table_alias_columns(&cte.alias.columns, anchor.columns.len())?;
        let to_docs = |rows: Vec<Vec<Value>>, columns: &[String]| -> Vec<Object> {
            rows.into_iter()
                .map(|row| match &alias_columns {
                    Some(cols) => cols.iter().cloned().zip(row).collect(),
                    None => columns.iter().cloned().zip(row).collect(),
                })
                .collect()
        };
        let columns = anchor.columns.clone();
        // UNION (distinct) keeps a seen-set over encoded bytes; UNION ALL
        // appends everything and relies on the caps. The anchor dedupes
        // through the same set — UNION semantics cover the seed rows too,
        // not just the recursive arm's output.
        let distinct = !matches!(set_quantifier, sqlparser::ast::SetQuantifier::All);
        let doc_key = |d: &Object| -> Vec<u8> {
            let mut buf = Vec::new();
            crate::encode::encode_object(d, &mut buf).unwrap_or_default();
            buf
        };
        let mut seen: std::collections::BTreeSet<Vec<u8>> = std::collections::BTreeSet::new();
        let mut all: Vec<Object> = Vec::new();
        for d in to_docs(anchor.rows, &columns) {
            if distinct && !seen.insert(doc_key(&d)) {
                continue;
            }
            all.push(d);
        }
        let arm_query = |binding: Vec<Object>| -> Result<QueryResult> {
            let mut scope = outer.clone();
            scope.insert(name.to_string(), binding);
            let ExecOutcome::Rows(r) = self.exec_query_body(
                sqlparser::ast::Query {
                    with: None,
                    body: Box::new(right.as_ref().clone()),
                    order_by: None,
                    limit_clause: None,
                    fetch: None,
                    locks: vec![],
                    for_clause: None,
                    settings: None,
                    format_clause: None,
                    pipe_operators: vec![],
                },
                &scope,
            )?
            else {
                return err("recursive CTE arm must be a SELECT");
            };
            Ok(r)
        };
        let mut working = all.clone();
        let mut converged = true;
        for _ in 0..MAX_ITERATIONS {
            if working.is_empty() {
                converged = true;
                break;
            }
            converged = false;
            self.deadline.check()?;
            let r = arm_query(std::mem::take(&mut working))?;
            if r.columns.len() != columns.len() {
                return err(format!(
                    "recursive arm produces {} columns but the anchor produces {}",
                    r.columns.len(),
                    columns.len()
                ));
            }
            let docs = to_docs(r.rows, &columns);
            let mut next_working = Vec::new();
            for d in docs {
                if distinct {
                    let key = doc_key(&d);
                    if !seen.insert(key) {
                        continue;
                    }
                }
                next_working.push(d.clone());
                all.push(d);
                if all.len() > MAX_ROWS {
                    return err(format!(
                        "recursive CTE {name} exceeded the {MAX_ROWS}-row budget (UNION ALL cycle?)"
                    ));
                }
            }
            working = next_working;
        }
        if !converged && !working.is_empty() {
            return err(format!(
                "recursive CTE {name} did not converge within {MAX_ITERATIONS} iterations \
                 (UNION ALL cycle?)"
            ));
        }
        Ok(all)
    }

    /// Rewrite uncorrelated subqueries inside `e` into row-local
    /// expressions (IN-lists / literals) before row iteration.
    fn subst_expr(&self, e: &mut SqlExpr) -> Result<()> {
        self.subst_expr_scoped(e, &OuterFrom::new(), false)
    }

    /// [`subst_expr`] with an outer scope: `outer` names this query level's
    /// FROM names/aliases, and `allow_rowcorr` marks the row-local surfaces
    /// (WHERE / projection / ORDER BY / UPDATE·DELETE predicates and SET)
    /// where a correlated subquery node may stay in place for per-row
    /// evaluation. Everywhere else correlation must keep erroring loudly —
    /// the row-local evaluator would read an outer column as NULL and
    /// silently mis-filter (`NOT IN ()` over an empty list is vacuously
    /// true, a row-deleting shape).
    fn subst_expr_scoped(
        &self,
        e: &mut SqlExpr,
        outer: &OuterFrom,
        allow_rowcorr: bool,
    ) -> Result<()> {
        let corr = |q: &Query| query_mentions_outer(q, outer);
        let reject = || {
            err(
                "correlated subqueries are not supported here \
                 (supported: WHERE / SELECT projection / ORDER BY / UPDATE·DELETE predicates and SET)",
            )
        };
        match e {
            SqlExpr::Subquery(q) => {
                if corr(q) {
                    if allow_rowcorr {
                        return Ok(());
                    }
                    return reject();
                }
                let r = self.subquery_result(q)?;
                single_col_rows(&r)?;
                if r.rows.len() > 1 {
                    // Silently taking the first row makes the result depend
                    // on scan order — a wrong answer that looks plausible.
                    return err("scalar subquery returned more than one row");
                }
                let v = r
                    .rows
                    .first()
                    .and_then(|row| row.first().cloned())
                    .unwrap_or(Value::Null);
                *e = value_to_literal(v)?;
            }
            SqlExpr::InSubquery {
                expr,
                subquery,
                negated,
            } => {
                if corr(subquery) {
                    if allow_rowcorr {
                        return self.subst_expr_scoped(expr, outer, allow_rowcorr);
                    }
                    return reject();
                }
                let r = self.subquery_result(subquery)?;
                single_col_rows(&r)?;
                let list = r
                    .rows
                    .iter()
                    .map(|row| value_to_literal(row.first().cloned().unwrap_or(Value::Null)))
                    .collect::<Result<Vec<_>>>()?;
                *e = SqlExpr::InList {
                    expr: expr.clone(),
                    list,
                    negated: *negated,
                };
            }
            SqlExpr::Exists { subquery, negated } => {
                if corr(subquery) {
                    if allow_rowcorr {
                        return Ok(());
                    }
                    return reject();
                }
                let r = self.subquery_result(subquery)?;
                *e = value_to_literal(Value::Bool(!r.rows.is_empty() != *negated))?;
            }
            SqlExpr::AnyOp {
                left,
                compare_op,
                right,
                ..
            } => {
                self.subst_expr_scoped(left, outer, allow_rowcorr)?;
                let SqlExpr::Subquery(q) = right.as_ref() else {
                    return err("ANY/ALL requires a subquery operand");
                };
                if corr(q) {
                    if allow_rowcorr {
                        return Ok(());
                    }
                    return reject();
                }
                if *compare_op == sqlparser::ast::BinaryOperator::Eq {
                    // `= ANY` is an IN list: cheaper than an OR chain and
                    // the shape the planner already understands.
                    let r = self.subquery_result(q)?;
                    single_col_rows(&r)?;
                    let list = r
                        .rows
                        .iter()
                        .map(|row| value_to_literal(row.first().cloned().unwrap_or(Value::Null)))
                        .collect::<Result<Vec<_>>>()?;
                    *e = SqlExpr::InList {
                        expr: left.clone(),
                        list,
                        negated: false,
                    };
                } else {
                    *e = self.quantified_chain(q, left, compare_op, true)?;
                }
            }
            SqlExpr::AllOp {
                left,
                compare_op,
                right,
            } => {
                self.subst_expr_scoped(left, outer, allow_rowcorr)?;
                let SqlExpr::Subquery(q) = right.as_ref() else {
                    return err("ANY/ALL requires a subquery operand");
                };
                if corr(q) {
                    if allow_rowcorr {
                        return Ok(());
                    }
                    return reject();
                }
                *e = self.quantified_chain(q, left, compare_op, false)?;
            }
            // Recurse into composite expressions.
            SqlExpr::BinaryOp { left, right, .. } => {
                self.subst_expr_scoped(left, outer, allow_rowcorr)?;
                self.subst_expr_scoped(right, outer, allow_rowcorr)?;
            }
            SqlExpr::UnaryOp { expr, .. } => self.subst_expr_scoped(expr, outer, allow_rowcorr)?,
            SqlExpr::Nested(inner) => self.subst_expr_scoped(inner, outer, allow_rowcorr)?,
            SqlExpr::Between {
                expr, low, high, ..
            } => {
                self.subst_expr_scoped(expr, outer, allow_rowcorr)?;
                self.subst_expr_scoped(low, outer, allow_rowcorr)?;
                self.subst_expr_scoped(high, outer, allow_rowcorr)?;
            }
            SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
                self.subst_expr_scoped(l, outer, allow_rowcorr)?;
                self.subst_expr_scoped(r, outer, allow_rowcorr)?;
            }
            SqlExpr::Rollup(groups) | SqlExpr::Cube(groups) | SqlExpr::GroupingSets(groups) => {
                for g in groups {
                    for e in g {
                        self.subst_expr_scoped(e, outer, allow_rowcorr)?;
                    }
                }
            }
            SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
                self.subst_expr_scoped(expr, outer, allow_rowcorr)?;
                self.subst_expr_scoped(pattern, outer, allow_rowcorr)?;
            }
            SqlExpr::InList { expr, list, .. } => {
                self.subst_expr_scoped(expr, outer, allow_rowcorr)?;
                for item in list {
                    self.subst_expr_scoped(item, outer, allow_rowcorr)?;
                }
            }
            SqlExpr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => {
                if let Some(op) = operand {
                    self.subst_expr_scoped(op, outer, allow_rowcorr)?;
                }
                for w in conditions.iter_mut() {
                    self.subst_expr_scoped(&mut w.condition, outer, allow_rowcorr)?;
                    self.subst_expr_scoped(&mut w.result, outer, allow_rowcorr)?;
                }
                if let Some(el) = else_result {
                    self.subst_expr_scoped(el, outer, allow_rowcorr)?;
                }
            }
            SqlExpr::Cast { expr, .. } => self.subst_expr_scoped(expr, outer, allow_rowcorr)?,
            SqlExpr::Function(f) => {
                if let sqlparser::ast::FunctionArguments::List(list) = &mut f.args {
                    for a in &mut list.args {
                        if let sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(inner),
                        ) = a
                        {
                            self.subst_expr_scoped(inner, outer, allow_rowcorr)?;
                        }
                    }
                }
                if let Some(filter) = &mut f.filter {
                    self.subst_expr_scoped(filter, outer, allow_rowcorr)?;
                }
            }
            _ => {
                // Shared traversal: subqueries under wrapper nodes
                // (FLOOR/IS NULL/SUBSTRING/…) resolve here instead of
                // erroring at row level.
                for child in child_exprs_mut(e) {
                    self.subst_expr_scoped(child, outer, allow_rowcorr)?;
                }
            }
        }
        Ok(())
    }

    /// Per-row resolution of the correlated subquery nodes the pre-pass
    /// left in place: substitute outer references with this row's values
    /// (precise scoping — inner FROM names shadow the outer scope), then
    /// run the standard once-eval substitution over the now-self-contained
    /// node. Non-correlated leftovers (nested one level below a skipped
    /// node) resolve through the same delegation.
    fn subst_expr_row(&self, e: &mut SqlExpr, doc: &Object, outer: &OuterFrom) -> Result<()> {
        let resolve_node = |e: &mut SqlExpr| -> Result<()> {
            let _g = enter_correlated_eval()?;
            if let Some(q) = subquery_of_mut(e) {
                self.deadline.check()?;
                subst_outer_refs_query(q, &OuterFrom::new(), outer, doc);
            }
            self.subst_expr(e)
        };
        match e {
            SqlExpr::Subquery(_) | SqlExpr::Exists { .. } => resolve_node(e)?,
            SqlExpr::InSubquery { expr, .. } => {
                // The left side may itself nest a correlated subquery.
                self.subst_expr_row(expr, doc, outer)?;
                resolve_node(e)?;
            }
            SqlExpr::AnyOp { left, .. } | SqlExpr::AllOp { left, .. } => {
                self.subst_expr_row(left, doc, outer)?;
                resolve_node(e)?;
            }
            // Same composite recursion as the pre-pass.
            SqlExpr::BinaryOp { left, right, .. } => {
                self.subst_expr_row(left, doc, outer)?;
                self.subst_expr_row(right, doc, outer)?;
            }
            SqlExpr::UnaryOp { expr, .. } => self.subst_expr_row(expr, doc, outer)?,
            SqlExpr::Nested(inner) => self.subst_expr_row(inner, doc, outer)?,
            SqlExpr::Between {
                expr, low, high, ..
            } => {
                self.subst_expr_row(expr, doc, outer)?;
                self.subst_expr_row(low, doc, outer)?;
                self.subst_expr_row(high, doc, outer)?;
            }
            SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
                self.subst_expr_row(l, doc, outer)?;
                self.subst_expr_row(r, doc, outer)?;
            }
            SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
                self.subst_expr_row(expr, doc, outer)?;
                self.subst_expr_row(pattern, doc, outer)?;
            }
            SqlExpr::InList { expr, list, .. } => {
                self.subst_expr_row(expr, doc, outer)?;
                for item in list {
                    self.subst_expr_row(item, doc, outer)?;
                }
            }
            SqlExpr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => {
                if let Some(op) = operand {
                    self.subst_expr_row(op, doc, outer)?;
                }
                for w in conditions.iter_mut() {
                    self.subst_expr_row(&mut w.condition, doc, outer)?;
                    self.subst_expr_row(&mut w.result, doc, outer)?;
                }
                if let Some(el) = else_result {
                    self.subst_expr_row(el, doc, outer)?;
                }
            }
            SqlExpr::Cast { expr, .. } => self.subst_expr_row(expr, doc, outer)?,
            SqlExpr::Function(f) => {
                if let sqlparser::ast::FunctionArguments::List(list) = &mut f.args {
                    for a in &mut list.args {
                        if let sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(inner),
                        ) = a
                        {
                            self.subst_expr_row(inner, doc, outer)?;
                        }
                    }
                }
                if let Some(filter) = &mut f.filter {
                    self.subst_expr_row(filter, doc, outer)?;
                }
            }
            _ => {
                // Same shared traversal as the pre-pass: correlated
                // subqueries left under wrapper nodes resolve per row.
                for child in child_exprs_mut(e) {
                    self.subst_expr_row(child, doc, outer)?;
                }
            }
        }
        Ok(())
    }

    /// Rewrite `x op ANY|ALL (subquery)` into an OR/AND chain of literal
    /// comparisons. DocSQL comparisons are two-valued (no UNKNOWN), so
    /// boolean quantification over the chain is exact. Empty ANY → FALSE,
    /// empty ALL → TRUE (SQL standard).
    fn quantified_chain(
        &self,
        q: &Query,
        left: &SqlExpr,
        compare_op: &BinaryOperator,
        any: bool,
    ) -> Result<SqlExpr> {
        fn lit_bool(b: bool) -> SqlExpr {
            SqlExpr::Value(sqlparser::ast::Value::Boolean(b).into())
        }
        fn lit_null() -> SqlExpr {
            SqlExpr::Value(sqlparser::ast::Value::Null.into())
        }
        let r = self.subquery_result(q)?;
        single_col_rows(&r)?;
        if r.rows.is_empty() {
            // ANY over the empty set is FALSE, ALL is TRUE (standard).
            return value_to_literal(Value::Bool(!any));
        }
        let mut cmps = Vec::with_capacity(r.rows.len());
        for row in &r.rows {
            let v = value_to_literal(row.first().cloned().unwrap_or(Value::Null))?;
            cmps.push(SqlExpr::BinaryOp {
                left: Box::new(left.clone()),
                op: compare_op.clone(),
                right: Box::new(v),
            });
        }
        // Three-valued quantification. The engine's boolean AND/OR reject
        // Null, and the old COALESCE-to-FALSE fold was only WHERE-visible:
        // under NOT it admitted rows three-valued logic filters
        // (`NOT (x > ALL (…, NULL))` must stay UNKNOWN, not become TRUE).
        // `c = TRUE` / `c = FALSE` are Null-safe (a Null comparison is
        // FALSE under the engine's total order, never an error), so a CASE
        // over the folded chains reproduces the exact ANY/ALL truth table
        // under any nesting.
        let eq_bool = |c: SqlExpr, b: bool| -> SqlExpr {
            SqlExpr::BinaryOp {
                left: Box::new(c),
                op: BinaryOperator::Eq,
                right: Box::new(lit_bool(b)),
            }
        };
        let fold = |mut v: Vec<SqlExpr>, op: BinaryOperator| -> SqlExpr {
            let mut acc = v.swap_remove(0);
            for e in v {
                acc = SqlExpr::BinaryOp {
                    left: Box::new(acc),
                    op: op.clone(),
                    right: Box::new(e),
                };
            }
            acc
        };
        let mut t_eqs = Vec::with_capacity(cmps.len());
        let mut f_eqs = Vec::with_capacity(cmps.len());
        for c in cmps {
            t_eqs.push(eq_bool(c.clone(), true));
            f_eqs.push(eq_bool(c, false));
        }
        // ANY: TRUE if some comparison is TRUE, FALSE if all are FALSE,
        // else UNKNOWN. ALL mirrors it.
        let (c1, r1, c2, r2) = if any {
            (
                fold(t_eqs, BinaryOperator::Or),
                lit_bool(true),
                fold(f_eqs, BinaryOperator::And),
                lit_bool(false),
            )
        } else {
            (
                fold(f_eqs, BinaryOperator::Or),
                lit_bool(false),
                fold(t_eqs, BinaryOperator::And),
                lit_bool(true),
            )
        };
        Ok(SqlExpr::Case {
            case_token: sqlparser::ast::helpers::attached_token::AttachedToken::empty(),
            end_token: sqlparser::ast::helpers::attached_token::AttachedToken::empty(),
            operand: None,
            conditions: vec![
                sqlparser::ast::CaseWhen {
                    condition: c1,
                    result: r1,
                },
                sqlparser::ast::CaseWhen {
                    condition: c2,
                    result: r2,
                },
            ],
            else_result: Some(Box::new(lit_null())),
        })
    }

    /// Run a subquery and return its rows (first column only matters for
    /// IN/ANY lists, but scalar casts use the full first cell).
    fn subquery_result(&self, q: &Query) -> Result<QueryResult> {
        // Correlated references (`outer_table.column`) must error instead of
        // falling into the inner query's schemaless column lookup, where a
        // missing column reads as NULL and silently mis-filters (NOT IN ()
        // over an empty list is vacuously true — that shape deletes rows).
        let mut from_names = std::collections::BTreeSet::new();
        collect_from_names(q, &mut from_names);
        let mut hits = Vec::new();
        self.collect_correlated_in_body(&q.body, &from_names, &mut hits);
        if let Some(qualifier) = hits.first() {
            return err(format!(
                "correlated subqueries are not supported (reference to outer table {qualifier})"
            ));
        }
        match self.exec_query(q.clone())? {
            ExecOutcome::Rows(r) => Ok(r),
            _ => err("subquery must be a SELECT"),
        }
    }

    /// Scan every expression surface of a subquery body for outer references.
    /// Set-operation arms, parenthesized query bodies, GROUP BY keys and JOIN
    /// ON conditions all evaluate in the inner scope — a shape the old
    /// Select-only scan skipped silently read the outer column as NULL.
    fn collect_correlated_in_body(
        &self,
        body: &sqlparser::ast::SetExpr,
        from_names: &std::collections::BTreeSet<String>,
        hits: &mut Vec<String>,
    ) {
        use sqlparser::ast::SetExpr;
        match body {
            SetExpr::Select(sel) => {
                for twj in &sel.from {
                    for j in &twj.joins {
                        if let Some(e) = join_on_expr(&j.join_operator) {
                            collect_correlated_refs(e, from_names, self.tables, hits);
                        }
                    }
                }
                if let Some(sel_expr) = &sel.selection {
                    collect_correlated_refs(sel_expr, from_names, self.tables, hits);
                }
                if let Some(having) = &sel.having {
                    collect_correlated_refs(having, from_names, self.tables, hits);
                }
                if let sqlparser::ast::GroupByExpr::Expressions(es, _) = &sel.group_by {
                    for e in es {
                        collect_correlated_refs(e, from_names, self.tables, hits);
                    }
                }
                for item in &sel.projection {
                    match item {
                        sqlparser::ast::SelectItem::UnnamedExpr(e)
                        | sqlparser::ast::SelectItem::ExprWithAlias { expr: e, .. } => {
                            collect_correlated_refs(e, from_names, self.tables, hits);
                        }
                        _ => {}
                    }
                }
            }
            SetExpr::SetOperation { left, right, .. } => {
                // Each arm's own FROM names shadow at its level (mirror of
                // the Query arm): passing the parent set straight through
                // misread a qualified arm-local reference as correlated.
                for arm in [left, right] {
                    let mut nested = from_names.clone();
                    collect_setexpr_from_names(arm, &mut nested);
                    self.collect_correlated_in_body(arm, &nested, hits);
                }
            }
            SetExpr::Query(inner) => {
                let mut nested = from_names.clone();
                collect_setexpr_from_names(&inner.body, &mut nested);
                self.collect_correlated_in_body(&inner.body, &nested, hits);
            }
            _ => {}
        }
    }

    /// Row filter with correlated-subquery support: `outer` names the
    /// enclosing FROM scopes whose row values `doc` carries. A selection
    /// still holding subquery nodes at row time means the pre-pass skipped
    /// them as correlated — substitute this row's outer values, then
    /// evaluate.
    fn matches_in(
        &self,
        selection: &Option<SqlExpr>,
        doc: &Object,
        outer: &OuterFrom,
    ) -> Result<bool> {
        self.deadline.check()?;
        match selection {
            None => Ok(true),
            Some(e) if expr_has_subquery(e) => {
                let mut row_local = e.clone();
                self.subst_expr_row(&mut row_local, doc, outer)?;
                Ok(matches!(eval_expr(&row_local, doc)?, Value::Bool(true)))
            }
            Some(e) => Ok(matches!(eval_expr(e, doc)?, Value::Bool(true))),
        }
    }

    pub(crate) fn table_docs(&self, table: &str) -> Result<Vec<Object>> {
        let Some(meta) = self.tables.get(table) else {
            return err(format!("table {table} does not exist"));
        };
        let heap = meta.heap_of();
        heap.scan(&self.reader()).map_err(Into::into)
    }

    fn index_probe(
        &self,
        table: &str,
        alias: Option<&str>,
        selection: &Option<SqlExpr>,
        ctes: &Ctes,
    ) -> Result<Option<Vec<(u64, Object)>>> {
        let Some(cond) = selection else {
            return Ok(None);
        };
        let Some(meta) = self.tables.get(table) else {
            return Ok(None);
        };
        if meta.index_roots.is_empty() || !ctes.is_empty() {
            return Ok(None);
        }
        let Some((col, plan, _)) = probe_plan(cond, meta, table, alias) else {
            return Ok(None);
        };
        let root = meta.index_roots[&col];
        let heap = meta.heap_of();
        let tx = self.pager.begin_tx(); // read-only handle: nothing staged, dropping it is the cleanup
        let tree = BTree::open(root);
        let pairs = match self.probe_pairs(&col, &tree, &tx, &plan, None)? {
            Some(pairs) => pairs,
            // 混合带不可安全探测:回退通用扫描,结果不能依赖索引存在性。
            None => return Ok(None),
        };
        // Read-only tx: no staged pages, dropping it is the cleanup.
        drop(tx);
        let mut out: Vec<(u64, Object)> = Vec::with_capacity(pairs.len());
        for (_, loc) in pairs {
            if let Some(doc) = heap.doc_at(&self.reader(), loc)? {
                out.push((loc, doc));
            }
        }
        // Heap order (page, slot) — loc packing already sorts that way.
        out.sort_by_key(|(loc, _)| *loc);
        Ok(Some(out))
    }

    /// Promote a probe plan's string bounds into the tree's key band: a
    /// parseable timestamp string against a TIMESTAMP-keyed tree must
    /// compare chronologically — the raw cmp_values band ranks Str above
    /// every Timestamp, which would silently turn `WHERE ts > '2026-…'`
    /// into an empty result. Sampling min+max keys decides the band (two
    /// leaf reads). Returns `None` when the band is NOT safely probeable:
    ///
    /// * a MIXED band (extremes disagree — Timestamps and Strs coexist in
    ///   the tree): keeping the string literal probes only the Str band and
    ///   silently loses every Timestamp row, while promoting it pulls the
    ///   whole Str band into the range — either way the result set depends
    ///   on whether the index exists. The generic scan path (cmp_coerced)
    ///   is the only correct answer, so callers fall back to it.
    /// * an Eq/Prefix composite bound whose element beyond position 0 would
    ///   be promoted: element purity is only provable at position 0 (the
    ///   primary sort key); a middle key holding the literal STRING at that
    ///   position would be missed by the promoted seek.
    ///
    /// The bool flag reports whether any bound was actually lifted; callers
    /// owning an "exact" plan must demote exactness then (promoted bounds
    /// admit candidates the coercing predicate would exclude).
    fn promote_plan_bounds(
        &self,
        tree: &BTree,
        tx: &crate::pager::Tx,
        plan: &ProbePlan,
    ) -> Result<Option<(ProbePlan, bool)>> {
        // ANY string bound (parseable or not) enters the band analysis: an
        // unparseable one used to short-circuit the pre-check as "cannot
        // promote", leaving an exact plan whose raw `k < Str` filter passes
        // EVERY Timestamp key (Timestamps rank below Strs) — the coercing
        // predicate evaluates such a comparison as NULL/unknown and excludes
        // the row, so the window silently returned rows WHERE should have
        // dropped. Whether the string can actually lift is decided per band
        // below.
        let is_str = |v: &Value| -> bool { matches!(v, Value::Str(_)) };
        fn bound_elements(v: &Value) -> Option<&[Value]> {
            match v {
                Value::Array(items) if !items.is_empty() => Some(items),
                _ => None,
            }
        }
        // Cheap pre-check: no string bound anywhere (scalar or in a
        // composite Array) → the plan is untouched and the two leaf reads
        // are not paid.
        let has_str_bound =
            match plan {
                ProbePlan::Eq(v) | ProbePlan::Prefix(v) => {
                    is_str(v) || bound_elements(v).is_some_and(|items| items.iter().any(is_str))
                }
                ProbePlan::In(vals) => vals.iter().any(is_str),
                ProbePlan::Range { lo, hi } => [lo.as_ref(), hi.as_ref()]
                    .into_iter()
                    .flatten()
                    .any(|(v, _)| {
                        is_str(v) || bound_elements(v).is_some_and(|items| items.iter().any(is_str))
                    }),
            };
        // A TIMESTAMP-typed bound (TIMESTAMP '…' literal / CAST fold) needs
        // the same band check from the other side: the coercing predicate
        // (cmp_coerced) lifts Str KEYS to Timestamps, so a raw-band probe
        // against a Str or mixed band silently loses rows (Eq probes match
        // nothing — Timestamps rank below every Str; exact windows return
        // the whole Str band). Only a pure-Timestamp band keeps the probe.
        let ts_positions = |v: &Value| -> Vec<usize> {
            match v {
                Value::Array(items) => items
                    .iter()
                    .enumerate()
                    .filter(|(_, e)| matches!(e, Value::Timestamp(_)))
                    .map(|(i, _)| i)
                    .collect(),
                Value::Timestamp(_) => vec![0],
                _ => Vec::new(),
            }
        };
        let has_ts_bound = match plan {
            ProbePlan::Eq(v) | ProbePlan::Prefix(v) => !ts_positions(v).is_empty(),
            ProbePlan::In(vals) => vals.iter().any(|v| !ts_positions(v).is_empty()),
            ProbePlan::Range { lo, hi } => [lo.as_ref(), hi.as_ref()]
                .into_iter()
                .flatten()
                .any(|(v, _)| !ts_positions(v).is_empty()),
        };
        // Range sweeps with NUMERIC bounds need the band looked at too (Eq /
        // Prefix / In probes with numeric elements are safe without it: a
        // seek that matches nothing mirrors the predicate excluding every
        // row, so only the sweeping shapes can diverge). The predicate's
        // Timestamp↔numeric comparison is NULL — the row is excluded — while
        // the raw band order ranks Timestamps ABOVE numerics, so a numeric
        // bound over a Timestamp(-containing) band admits keys the predicate
        // must exclude (`WHERE ts > 0 ORDER BY ts LIMIT 1` would return a
        // row whose correct answer is zero rows).
        let is_num = |v: &Value| -> bool {
            matches!(v, Value::Int(_) | Value::Float(_) | Value::Decimal(_))
        };
        let num_positions = |v: &Value| -> Vec<usize> {
            match v {
                Value::Array(items) => items
                    .iter()
                    .enumerate()
                    .filter(|(_, e)| is_num(e))
                    .map(|(i, _)| i)
                    .collect(),
                other if is_num(other) => vec![0],
                _ => Vec::new(),
            }
        };
        let has_num_range_bound = match plan {
            ProbePlan::Range { lo, hi } => [lo.as_ref(), hi.as_ref()]
                .into_iter()
                .flatten()
                .any(|(v, _)| !num_positions(v).is_empty()),
            _ => false,
        };
        if !has_str_bound && !has_ts_bound && !has_num_range_bound {
            return Ok(Some((plan.clone(), false)));
        }
        let reader = self.reader();
        let sample = |rev: bool| -> Result<Vec<(Value, u64)>> {
            if rev {
                tree.scan_limited_rev(&reader, tx, Some(1))
                    .map_err(|e| index_err("probe bound", e))
            } else {
                tree.scan_limited(&reader, tx, Some(1))
                    .map_err(|e| index_err("probe bound", e))
            }
        };
        let min_key = sample(false)?.into_iter().next().map(|(k, _)| k);
        let max_key = sample(true)?.into_iter().next().map(|(k, _)| k);
        // Position i of the tree band is Timestamp when both sampled keys
        // carry a Timestamp there (scalar keys are position 0). Because the
        // tree is totally ordered and Timestamps rank below every Str, both
        // extremes being Timestamp PROVES a pure band at the primary sort
        // position; the same holds for both-Str (no Timestamps exist).
        let band_ts_at = |i: usize| -> bool {
            let at = |k: &Option<Value>| -> bool {
                k.as_ref().is_some_and(|k| match k {
                    Value::Timestamp(_) if i == 0 => true,
                    Value::Array(items) => items
                        .get(i)
                        .is_some_and(|e| matches!(e, Value::Timestamp(_))),
                    _ => false,
                })
            };
            at(&min_key) && at(&max_key)
        };
        let band_str_at = |i: usize| -> bool {
            let at = |k: &Option<Value>| -> bool {
                k.as_ref().is_some_and(|k| match k {
                    Value::Str(_) if i == 0 => true,
                    Value::Array(items) => items.get(i).is_some_and(|e| matches!(e, Value::Str(_))),
                    _ => false,
                })
            };
            at(&min_key) && at(&max_key)
        };
        let band_num_at = |i: usize| -> bool {
            let at = |k: &Option<Value>| -> bool {
                k.as_ref().is_some_and(|k| match k {
                    Value::Int(_) | Value::Float(_) | Value::Decimal(_) if i == 0 => true,
                    Value::Array(items) => items.get(i).is_some_and(|e| {
                        matches!(e, Value::Int(_) | Value::Float(_) | Value::Decimal(_))
                    }),
                    _ => false,
                })
            };
            at(&min_key) && at(&max_key)
        };
        // 一致才可判:该位要么纯 Timestamp(提升)、要么纯 Str(保留字面量,
        // 与 cmp_coerced 的 Str↔Str 明文比较一致);两极不一致 = 混合带。
        // 只需检查边界里携带字符串的位 —— 其它位的带型与该边界的比较
        // 语义无关(Int 位永远不会被提升)。
        let str_positions = |v: &Value| -> Vec<usize> {
            match v {
                Value::Array(items) => items
                    .iter()
                    .enumerate()
                    .filter(|(_, e)| is_str(e))
                    .map(|(i, _)| i)
                    .collect(),
                other if is_str(other) => vec![0],
                _ => Vec::new(),
            }
        };
        // Can the string at position i of `v` actually lift to a Timestamp?
        let parseable_at = |v: &Value, i: usize| -> bool {
            match v {
                Value::Array(items) => items.get(i).is_some_and(
                    |e| matches!(e, Value::Str(s) if crate::value::parse_timestamp_ms(s).is_some()),
                ),
                Value::Str(s) => i == 0 && crate::value::parse_timestamp_ms(s).is_some(),
                _ => false,
            }
        };
        let safe_at = |i: usize| band_ts_at(i) || band_str_at(i);
        match plan {
            ProbePlan::Eq(v) | ProbePlan::Prefix(v) => {
                for i in str_positions(v) {
                    if i > 0 {
                        // 复合 Eq/Prefix 的非首元素:纯 Str 带保留字面量即可,
                        // 其它带型(含纯 Timestamp —— 元素纯度不可证)回退。
                        if !band_str_at(i) {
                            return Ok(None);
                        }
                    } else if !(band_str_at(0) || (band_ts_at(0) && parseable_at(v, 0))) {
                        // Timestamp 带上的字符串边界只有真提升成
                        // Timestamp 才与谓词同义;不可解析字符串对每个
                        // Timestamp 键都判 NULL/未知 —— 原样保留字面量会让
                        // 探针/窗口放进谓词必然排除的行,只能整体回退。
                        return Ok(None);
                    }
                }
                for i in ts_positions(v) {
                    // Timestamp 边界只在纯 Timestamp 带上与谓词同义;
                    // Str/混合带回退全扫。
                    if !band_ts_at(i) {
                        return Ok(None);
                    }
                }
            }
            // IN 的每个元素都是一次独立 Eq 探测(位置 0),逐元素套用
            // Eq 的首元素规则:任一元素与带型不谐即整体回退。
            ProbePlan::In(vals) => {
                for v in vals {
                    for i in str_positions(v) {
                        if !(band_str_at(i) || (band_ts_at(i) && parseable_at(v, i))) {
                            return Ok(None);
                        }
                    }
                    for i in ts_positions(v) {
                        if !band_ts_at(i) {
                            return Ok(None);
                        }
                    }
                }
            }
            ProbePlan::Range { lo, hi } => {
                for (v, _) in [lo.as_ref(), hi.as_ref()].into_iter().flatten() {
                    for i in str_positions(v) {
                        if !safe_at(i) {
                            return Ok(None);
                        }
                        // Timestamp 带上的字符串边界必须真能提升;不可解析
                        // 字符串对每个 Timestamp 键判 NULL/未知,原样保留
                        // 会让探针放进(或吃掉)谓词必然排除/包含的行。
                        // 纯 Str 带保留字面量即可,与谓词的 Str↔Str 比较一致。
                        if band_ts_at(i) && !parseable_at(v, i) {
                            return Ok(None);
                        }
                    }
                }
                for i in [lo.as_ref(), hi.as_ref()]
                    .into_iter()
                    .flatten()
                    .flat_map(|(v, _)| ts_positions(v))
                {
                    if !band_ts_at(i) {
                        return Ok(None);
                    }
                }
                // A numeric bound may only sweep a band PROVABLY free of
                // Timestamps. Purity is provable when both extremes agree
                // on one family (anything else ranks strictly outside
                // [min, max]); a band whose extremes disagree may still
                // hold Timestamps in between (numeric … Timestamp … Str),
                // and Str↔numeric stays raw on both sides so a pure Str
                // band is as safe as a pure numeric one.
                for i in [lo.as_ref(), hi.as_ref()]
                    .into_iter()
                    .flatten()
                    .flat_map(|(v, _)| num_positions(v))
                {
                    if !(band_num_at(i) || band_str_at(i)) {
                        return Ok(None);
                    }
                }
            }
        }
        let any_band_ts = match min_key.as_ref() {
            Some(Value::Array(items)) => (0..items.len()).any(band_ts_at),
            Some(_) => band_ts_at(0),
            None => false,
        };
        if !any_band_ts {
            return Ok(Some((plan.clone(), false)));
        }
        let mut promoted_any = false;
        let promote = |v: &Value, promoted_any: &mut bool| -> Value {
            match v {
                Value::Str(s) => {
                    if band_ts_at(0) {
                        if let Some(ms) = crate::value::parse_timestamp_ms(s) {
                            *promoted_any = true;
                            return Value::Timestamp(ms);
                        }
                    }
                    v.clone()
                }
                Value::Array(items) => Value::Array(
                    items
                        .iter()
                        .enumerate()
                        .map(|(i, e)| {
                            if let Value::Str(s) = e {
                                if band_ts_at(i) {
                                    if let Some(ms) = crate::value::parse_timestamp_ms(s) {
                                        *promoted_any = true;
                                        return Value::Timestamp(ms);
                                    }
                                }
                            }
                            e.clone()
                        })
                        .collect(),
                ),
                other => other.clone(),
            }
        };
        let out = match &plan {
            ProbePlan::Eq(v) => ProbePlan::Eq(promote(v, &mut promoted_any)),
            ProbePlan::Prefix(v) => ProbePlan::Prefix(promote(v, &mut promoted_any)),
            ProbePlan::In(vals) => {
                ProbePlan::In(vals.iter().map(|v| promote(v, &mut promoted_any)).collect())
            }
            ProbePlan::Range { lo, hi } => ProbePlan::Range {
                lo: lo
                    .as_ref()
                    .map(|(v, incl)| (promote(v, &mut promoted_any), *incl)),
                hi: hi
                    .as_ref()
                    .map(|(v, incl)| (promote(v, &mut promoted_any), *incl)),
            },
        };
        Ok(Some((out, promoted_any)))
    }

    /// Index entries selected by `plan`, in key order. `max` caps the walk to
    /// the first `max` entries; pass it only when every entry the plan can
    /// return is a result (exact probes), since a non-unique run must not
    /// spend the cap on entries a filter would drop.
    fn probe_pairs(
        &self,
        col: &str,
        tree: &BTree,
        tx: &crate::pager::Tx,
        plan: &ProbePlan,
        max: Option<usize>,
    ) -> Result<Option<Vec<(Value, u64)>>> {
        let reader = self.reader();
        let plan = match self.promote_plan_bounds(tree, tx, plan)? {
            Some((p, _)) => p,
            None => return Ok(None),
        };
        let pairs = match &plan {
            ProbePlan::Eq(v) => {
                // Bounded range + equal filter so non-unique trees return
                // every duplicate match (get() would yield one entry).
                // The hi bound lets the tree stop at the first key past v
                // instead of walking the whole right side. For composite
                // indexes v is the full Array key — element-wise cmp_values
                // equality is exactly a key match.
                let mut p = tree
                    .range_bounded_limited(&reader, tx, v, Some((v, true)), max)
                    .map_err(|e| index_err(col, e))?;
                p.retain(|(k, _)| Value::cmp_values(k, v) == Ordering::Equal);
                p
            }
            ProbePlan::Prefix(prefix) => {
                // Composite prefix probe: walk from the prefix (its rank makes
                // Array(prefix) sort right before every key extending it) and
                // stop at the first key that leaves the run — the walk itself
                // yields only prefix matches, so neither a `retain` nor the
                // tail beyond the run is needed. `max` stays ignored, as
                // before: the cap exists for plans whose every entry is a
                // result, and this one keeps nothing else. Walking to the end
                // of the tree and filtering afterwards (the old shape) made
                // `WHERE leading = 'x'` cost the whole index in time and in
                // materialized pairs, however few rows matched.
                let Value::Array(pfx) = prefix else {
                    // Only a composite Array key has a prefix run; no other
                    // shape is probeable — generic path, never a wrong answer.
                    return Ok(None);
                };
                tree.range_prefix_limited(&reader, tx, pfx, None)
                    .map_err(|e| index_err(col, e))?
            }
            ProbePlan::In(vals) => {
                // Multi-probe equality set: one bounded Eq walk per element
                // (the cap per element still covers the global first `max` —
                // each element contributes its smallest keys), merged back
                // into key order because window plans trust it. Distinct
                // elements probe disjoint runs; repeated list entries
                // double-report the same run and dedupe away here.
                let mut pairs: Vec<(Value, u64)> = Vec::new();
                for v in vals {
                    self.deadline.check()?;
                    let mut p = tree
                        .range_bounded_limited(&reader, tx, v, Some((v, true)), max)
                        .map_err(|e| index_err(col, e))?;
                    p.retain(|(k, _)| Value::cmp_values(k, v) == Ordering::Equal);
                    pairs.append(&mut p);
                }
                // 按 (键, locator) 全对排序:重复列表元素探出的同键同
                // locator 对必须相邻才能去重;cmp_values 相等的键可以是
                // 两行(Int(3)/Float(3.0) 同判等,AGENTS 红线 #2),按键
                // 单独去重会丢掉非唯一树的合法同行键。
                pairs.sort_by(|a, b| Value::cmp_values(&a.0, &b.0).then_with(|| a.1.cmp(&b.1)));
                pairs.dedup_by(|a, b| a.0 == b.0 && a.1 == b.1);
                if let Some(m) = max {
                    pairs.truncate(m);
                }
                pairs
            }
            ProbePlan::Range { lo, hi } => {
                let hi_ref = hi.as_ref().map(|(v, incl)| (v, *incl));
                let mut pairs = match &lo {
                    Some((v, true)) => tree
                        .range_bounded_limited(&reader, tx, v, hi_ref, max)
                        .map_err(|e| index_err(col, e))?,
                    // Strict lower bound: the walk drops the equal run itself
                    // so the cap counts kept entries only.
                    Some((v, false)) => tree
                        .range_bounded_excl_limited(&reader, tx, v, hi_ref, max)
                        .map_err(|e| index_err(col, e))?,
                    // No lower bound: in-range keys are a prefix of the scan,
                    // so a cap collects them all (or exactly `max` of them).
                    None => tree
                        .scan_limited(&reader, tx, max)
                        .map_err(|e| index_err(col, e))?,
                };
                if let Some((v, incl)) = &hi {
                    pairs.retain(|(k, _)| {
                        let o = Value::cmp_values(k, v);
                        o == std::cmp::Ordering::Less || (*incl && o == std::cmp::Ordering::Equal)
                    });
                }
                pairs
            }
        };
        Ok(Some(pairs))
    }

    /// [`Database::probe_pairs`] walking in descending key order — the
    /// `ORDER BY … DESC` window. Same `max` caveats; a prefix scan ignores
    /// it.
    fn probe_pairs_rev(
        &self,
        col: &str,
        tree: &BTree,
        tx: &crate::pager::Tx,
        plan: &ProbePlan,
        max: Option<usize>,
    ) -> Result<Option<Vec<(Value, u64)>>> {
        let reader = self.reader();
        let plan = match self.promote_plan_bounds(tree, tx, plan)? {
            Some((p, _)) => p,
            None => return Ok(None),
        };
        let pairs = match &plan {
            ProbePlan::Eq(v) => tree
                .range_bounded_rev_limited(&reader, tx, Some((v, true)), Some((v, true)), max)
                .map_err(|e| index_err(col, e))?,
            ProbePlan::Prefix(prefix) => {
                // Descending mirror of the prefix probe: the same bounded
                // forward run, reversed. `max` stays ignored, as above.
                let Value::Array(pfx) = prefix else {
                    return Ok(None);
                };
                tree.range_prefix_rev_limited(&reader, tx, pfx, None)
                    .map_err(|e| index_err(col, e))?
            }
            ProbePlan::In(vals) => {
                // Descending mirror of the In probe: one bounded Eq walk per
                // element (each takes the element's LAST keys under the cap —
                // their union covers the global last `max`), merged into
                // descending key order for the DESC window.
                let mut pairs: Vec<(Value, u64)> = Vec::new();
                for v in vals {
                    self.deadline.check()?;
                    let mut p = tree
                        .range_bounded_rev_limited(
                            &reader,
                            tx,
                            Some((v, true)),
                            Some((v, true)),
                            max,
                        )
                        .map_err(|e| index_err(col, e))?;
                    p.retain(|(k, _)| Value::cmp_values(k, v) == Ordering::Equal);
                    pairs.append(&mut p);
                }
                // 降序镜像:同键段内按 locator 定序,同对相邻可去重。
                pairs.sort_by(|a, b| Value::cmp_values(&b.0, &a.0).then_with(|| a.1.cmp(&b.1)));
                pairs.dedup_by(|a, b| a.0 == b.0 && a.1 == b.1);
                if let Some(m) = max {
                    pairs.truncate(m);
                }
                pairs
            }
            ProbePlan::Range { lo, hi } => {
                let lo_ref = lo.as_ref().map(|(v, incl)| (v, *incl));
                let hi_ref = hi.as_ref().map(|(v, incl)| (v, *incl));
                tree.range_bounded_rev_limited(&reader, tx, lo_ref, hi_ref, max)
                    .map_err(|e| index_err(col, e))?
            }
        };
        Ok(Some(pairs))
    }

    /// `SELECT COUNT(*) FROM t` with no WHERE/GROUP BY/window: count the
    /// heap's live slots without decoding documents. `None` sends anything
    /// more complex down the generic aggregate path.
    fn try_count_star(
        &self,
        query: &Query,
        select: &sqlparser::ast::Select,
        ctes: &Ctes,
    ) -> Result<Option<ExecOutcome>> {
        if !ctes.is_empty()
            || select.selection.is_some()
            || select.having.is_some()
            || select.top.is_some()
            || !matches!(&select.distinct, None | Some(sqlparser::ast::Distinct::All))
            || query.order_by.is_some()
            || query.limit_clause.is_some()
            || query.fetch.is_some()
            || select.projection.len() != 1
            || select.from.len() != 1
            || !select.from[0].joins.is_empty()
            || !matches!(&select.group_by, sqlparser::ast::GroupByExpr::Expressions(e, _) if e.is_empty())
        {
            return Ok(None);
        }
        if !plain_table_factor(&select.from[0].relation) {
            return Ok(None);
        }
        let sqlparser::ast::TableFactor::Table { name, .. } = &select.from[0].relation else {
            return Ok(None);
        };
        let Some(meta) = self.real_table_meta(name) else {
            return Ok(None);
        };
        let (column, expr) = match &select.projection[0] {
            SelectItem::UnnamedExpr(e) => (expr_name(e), e),
            SelectItem::ExprWithAlias { expr, alias, .. } => (alias.value.clone(), expr),
            _ => return Ok(None),
        };
        let SqlExpr::Function(f) = expr else {
            return Ok(None);
        };
        if !f.name.to_string().eq_ignore_ascii_case("count")
            || f.filter.is_some()
            || f.over.is_some()
        {
            return Ok(None);
        }
        use sqlparser::ast::{DuplicateTreatment, FunctionArg, FunctionArgExpr, FunctionArguments};
        let is_star = match &f.args {
            FunctionArguments::List(list) => {
                !matches!(list.duplicate_treatment, Some(DuplicateTreatment::Distinct))
                    && list.args.len() == 1
                    && matches!(
                        list.args[0],
                        FunctionArg::Unnamed(FunctionArgExpr::Wildcard)
                    )
            }
            _ => false,
        };
        if !is_star {
            return Ok(None);
        }
        let count = meta.heap_of().live_count(&self.reader())?;
        Ok(Some(ExecOutcome::Rows(QueryResult {
            columns: vec![column],
            rows: vec![vec![Value::Int(count as i64)]],
        })))
    }

    /// A FROM relation that resolves to a real heap table: single-part name,
    /// present in the catalog, and neither a compatibility view that shadows
    /// user tables of the same name in `load_table_factor` nor a user view
    /// (views resolve by expanding their stored SELECT — their own empty
    /// storage must never satisfy a heap fast path).
    fn real_table_meta(
        &self,
        name: &sqlparser::ast::ObjectName,
    ) -> Option<&std::sync::Arc<TableMeta>> {
        if name.0.len() != 1 {
            return None;
        }
        let tname = obj_name(name);
        if is_compat_view(&tname) {
            return None;
        }
        self.tables.get(&tname).filter(|m| !m.is_view())
    }
}

/// True when a table factor is a plain `t` / `t AS x` relation with no
/// per-factor clauses. The window/count fast paths test only the variant, so
/// without this `SELECT COUNT(*) FROM t TABLESAMPLE (10)`, table functions
/// (`FROM t(1)`), alias column lists and index hints would be silently
/// ignored instead of rejected like the general path does.
fn plain_table_factor(tf: &sqlparser::ast::TableFactor) -> bool {
    let sqlparser::ast::TableFactor::Table {
        args,
        with_hints,
        version,
        with_ordinality,
        partitions,
        json_path,
        sample,
        index_hints,
        alias,
        ..
    } = tf
    else {
        return false;
    };
    args.is_none()
        && with_hints.is_empty()
        && version.is_none()
        && !*with_ordinality
        && partitions.is_empty()
        && json_path.is_none()
        && sample.is_none()
        && index_hints.is_empty()
        && alias.as_ref().is_none_or(|a| a.columns.is_empty())
}

/// Plan of the unindexed top-K window ([`ReadCx::unindexed_order_window`]):
/// the planning prefix shared with EXPLAIN — no rows are touched.
struct UnindexedWindowPlan {
    table: String,
    /// Per ORDER BY key: candidate field names (first hit wins), ASC?,
    /// NULLS FIRST override.
    keys: Vec<(Vec<String>, bool, Option<bool>)>,
    skip: usize,
    take: usize,
}

/// Plan of the ordered index window ([`ReadCx::ordered_index_window`]):
/// the planning prefix (through the band-promoted probe bounds) shared
/// with EXPLAIN — no rows are touched.
struct OrderedWindowPlan {
    table: String,
    root_key: String,
    asc: bool,
    skip: usize,
    take: usize,
    /// The probe subsumes the whole WHERE: OFFSET rows are only counted,
    /// never decoded.
    exact: bool,
    /// Band-promoted probe bounds; None = whole-tree walk.
    probe: Option<ProbePlan>,
}

impl<'a> ReadCx<'a> {
    /// Planning prefix of [`Self::unindexed_order_window`], shared with
    /// EXPLAIN: every gate from the fast path's entry through the ORDER BY
    /// key extraction — no row loading. `None` = this query does not take
    /// the top-K window (caller falls through to the generic scan).
    fn unindexed_window_plan(
        &self,
        select: &sqlparser::ast::Select,
        query: &Query,
        ctes: &Ctes,
    ) -> Result<Option<UnindexedWindowPlan>> {
        if !ctes.is_empty()
            || select.selection.is_some()
            || select.from.len() != 1
            || !select.from[0].joins.is_empty()
        {
            return Ok(None);
        }
        if !plain_table_factor(&select.from[0].relation) {
            return Ok(None);
        }
        let sqlparser::ast::TableFactor::Table { name, .. } = &select.from[0].relation else {
            return Ok(None);
        };
        if self.real_table_meta(name).is_none() {
            return Ok(None);
        }
        let table = obj_name(name);
        let Some(order_by) = &query.order_by else {
            return Ok(None);
        };
        let sqlparser::ast::OrderByKind::Expressions(exprs) = &order_by.kind else {
            return Ok(None);
        };
        if exprs.is_empty() {
            return Ok(None);
        }
        let Some((skip, take)) = constant_limit_window(query) else {
            return Ok(None);
        };
        if take == usize::MAX {
            return Ok(None); // unbounded: every row is materialized anyway
        }
        // take == 0 carries through: the executor returns an empty window.
        // Resolve every ORDER BY key to a source field, mirroring
        // `apply_order_limit`: an output-column name wins over the raw
        // expression, and a bare column ref (possibly qualified, with the
        // bare name as fallback) is the only extractable shape.
        let mut project: Vec<(String, &SqlExpr)> = Vec::new();
        for item in &select.projection {
            match item {
                SelectItem::UnnamedExpr(e) => project.push((expr_name(e), e)),
                SelectItem::ExprWithAlias { expr, alias, .. } => {
                    project.push((alias.value.clone(), expr))
                }
                _ => return Ok(None), // wildcard / unsupported item
            }
        }
        let mut keys: Vec<(Vec<String>, bool, Option<bool>)> = Vec::new();
        for o in exprs {
            let name = expr_name(&o.expr);
            let src = match project.iter().find(|(c, _)| *c == name) {
                Some((_, e)) => *e,
                None => {
                    if name.parse::<usize>().is_ok() {
                        return Ok(None); // ordinal position: generic path
                    }
                    &o.expr
                }
            };
            let fields = match src {
                SqlExpr::Identifier(i) => vec![i.value.clone()],
                SqlExpr::CompoundIdentifier(parts) => {
                    // Same resolution order as `eval_expr` for qualified
                    // names: the full dotted key first (schemaless docs can
                    // hold a literal "t.name" field), then the bare column.
                    let dotted = parts
                        .iter()
                        .map(|p| p.value.clone())
                        .collect::<Vec<_>>()
                        .join(".");
                    let mut fields = vec![dotted];
                    if let Some(last) = parts.last() {
                        fields.push(last.value.clone());
                    }
                    fields
                }
                _ => return Ok(None),
            };
            keys.push((fields, o.options.asc.unwrap_or(true), o.options.nulls_first));
        }
        Ok(Some(UnindexedWindowPlan {
            table,
            keys,
            skip,
            take,
        }))
    }
}

impl<'a> ReadCx<'a> {
    /// Unindexed `ORDER BY <fields> LIMIT/OFFSET`: extract only the sort
    /// fields from each document's encoded bytes (no full decode), keep the
    /// best `skip+take` rows in a bounded heap, then materialize just those
    /// documents. `None` (generic decode + sort) unless every ORDER BY key
    /// is a bare top-level field, there is no WHERE, and the window is
    /// bounded. Ties keep scan order, matching the stable generic sort.
    fn unindexed_order_window(
        &self,
        select: &sqlparser::ast::Select,
        query: &Query,
        ctes: &Ctes,
    ) -> Result<Option<Vec<Object>>> {
        let Some(p) = self.unindexed_window_plan(select, query, ctes)? else {
            return Ok(None);
        };
        if p.take == 0 {
            return Ok(Some(Vec::new()));
        }
        let keys = p.keys;
        let skip = p.skip;
        let take = p.take;
        // Plan resolved the table through real_table_meta; re-fetch by name.
        let Some(meta) = self.tables.get(&p.table) else {
            return Ok(None);
        };
        let dirs: Vec<(bool, Option<bool>)> = keys.iter().map(|(_, asc, nf)| (*asc, *nf)).collect();
        let cap = skip.saturating_add(take);
        let heap = meta.heap_of();
        let reader = self.reader();
        let mut top: std::collections::BinaryHeap<OrderKeyed> =
            std::collections::BinaryHeap::with_capacity(cap.min(64));
        let mut seq = 0u64;
        heap.for_each_doc::<SqlError>(&reader, |loc, bytes| {
            // Extract the first key; when the window is full, reject before
            // decoding the remaining keys (the common case).
            let mut first = Value::Null;
            for field in &keys[0].0 {
                if let Some(v) = encode::extract_field_lookup(bytes, field)? {
                    first = v;
                    break;
                }
            }
            if top.len() >= cap {
                let worst = top.peek().expect("cap > 0");
                let ord = cmp_maybe_null(&first, &worst.keys[0], dirs[0].1);
                let worse = if dirs[0].0 {
                    ord == Ordering::Greater
                } else {
                    ord == Ordering::Less
                };
                if worse {
                    seq += 1;
                    return Ok(());
                }
            }
            let mut key_vals = Vec::with_capacity(keys.len());
            key_vals.push(first);
            for (fields, _, _) in keys.iter().skip(1) {
                let mut v = Value::Null;
                for field in fields {
                    if let Some(found) = encode::extract_field_lookup(bytes, field)? {
                        v = found;
                        break;
                    }
                }
                key_vals.push(v);
            }
            let entry = OrderKeyed {
                keys: key_vals,
                loc,
                seq,
                dirs: &dirs,
            };
            seq += 1;
            if top.len() < cap {
                top.push(entry);
            } else if top.peek().is_some_and(|worst| entry < *worst) {
                top.pop();
                top.push(entry);
            }
            Ok(())
        })?;
        // Only the window needs ordering: partition the skipped prefix off
        // in O(cap) and sort just the suffix (at most `take` rows — the
        // heap holds at most `skip+take`), so deep OFFSET no longer sorts
        // the whole candidate set.
        let mut entries = top.into_vec();
        if skip < entries.len() {
            entries.select_nth_unstable(skip);
            let mut window = entries.split_off(skip);
            window.sort();
            entries = window;
        } else {
            entries.clear();
        }
        let mut out = Vec::with_capacity(entries.len());
        for e in entries {
            if let Some(doc) = heap.doc_at(&reader, e.loc)? {
                out.push(doc);
            }
        }
        Ok(Some(out))
    }

    /// `ORDER BY <index key> LIMIT/OFFSET` window: walk one B+ tree in key
    /// order (forward for ASC, reverse for DESC) and load only the documents
    /// in the requested window — no full heap scan, no sort. `None` (generic
    /// path) unless the plan applies: solo real table, ORDER BY the tree's
    /// columns in order with a single direction, all key columns declared
    /// NOT NULL (trees omit NULL keys), a constant LIMIT/OFFSET, and a WHERE
    /// that either is absent or probes the same tree (residual conjuncts
    /// still filter while walking). An exact probe (one that subsumes the
    /// whole WHERE) lets the walk stop at the window's end and count OFFSET
    /// rows without reading them.
    fn ordered_index_window(
        &self,
        select: &sqlparser::ast::Select,
        from: &[sqlparser::ast::TableWithJoins],
        selection: &Option<SqlExpr>,
        order_by: &Option<sqlparser::ast::OrderBy>,
        query: &Query,
        ctes: &Ctes,
    ) -> Result<Option<Vec<Object>>> {
        let Some(p) = self.ordered_window_plan(select, from, selection, order_by, query, ctes)?
        else {
            return Ok(None);
        };
        if p.take == 0 {
            return Ok(Some(Vec::new()));
        }
        let Some(meta) = self.tables.get(&p.table) else {
            return Ok(None);
        };
        let root = meta.index_roots[&p.root_key];
        let tree = BTree::open(root);
        let tx = self.pager.begin_tx();
        // An exact walk yields exactly the window rows in the ORDER BY
        // direction, so it can stop collecting keys at the window's end;
        // residual filters need the whole candidate range first.
        let cap = p.exact.then(|| p.skip.saturating_add(p.take));
        let pairs = match &p.probe {
            None if p.asc => tree
                .scan_limited(&self.reader(), &tx, cap)
                .map_err(|e| index_err(&p.root_key, e))?,
            None => tree
                .scan_limited_rev(&self.reader(), &tx, cap)
                .map_err(|e| index_err(&p.root_key, e))?,
            // promote_plan_bounds 已在 plan 阶段把边界提升过,这里幂等无操作。
            Some(plan) if p.asc => match self.probe_pairs(&p.root_key, &tree, &tx, plan, cap)? {
                Some(pairs) => pairs,
                None => {
                    drop(tx);
                    return Ok(None);
                }
            },
            Some(plan) => match self.probe_pairs_rev(&p.root_key, &tree, &tx, plan, cap)? {
                Some(pairs) => pairs,
                None => {
                    drop(tx);
                    return Ok(None);
                }
            },
        };
        drop(tx);
        let heap = meta.heap_of();
        let reader = self.reader();
        // Both walkers already yield pairs in the ORDER BY direction.
        let locs: Vec<u64> = pairs.iter().map(|(_, loc)| *loc).collect();
        let mut out = Vec::new();
        let mut skipped = 0usize;
        for loc in locs {
            // Exact walks return rows straight from the window: OFFSET rows
            // need only be counted, never decoded.
            if p.exact && skipped < p.skip {
                skipped += 1;
                continue;
            }
            let Some(doc) = heap.doc_at(&reader, loc)? else {
                continue;
            };
            if !p.exact {
                // Residual-filter scope (inexact probes re-check WHERE per
                // row): built once, lazily, on the first residual row.
                let outer_from = {
                    let mut set = OuterFrom::new();
                    from_list_names(from, &mut set);
                    set
                };
                if !self.matches_in(selection, &doc, &outer_from)? {
                    continue;
                }
            }
            if skipped < p.skip {
                skipped += 1;
                continue;
            }
            out.push(doc);
            if out.len() >= p.take {
                break;
            }
        }
        Ok(Some(out))
    }

    /// Planning prefix of [`Self::ordered_index_window`], shared with
    /// EXPLAIN: every gate from the fast path's entry through the
    /// band-promoted probe bounds — no row loading (the band sampling
    /// reads two leaf pages, mirroring the executor's fallback decision).
    /// `None` = this query does not take the ordered window.
    fn ordered_window_plan(
        &self,
        select: &sqlparser::ast::Select,
        from: &[sqlparser::ast::TableWithJoins],
        selection: &Option<SqlExpr>,
        order_by: &Option<sqlparser::ast::OrderBy>,
        query: &Query,
        ctes: &Ctes,
    ) -> Result<Option<OrderedWindowPlan>> {
        if !ctes.is_empty() || from.len() != 1 {
            return Ok(None);
        }
        let base = &from[0];
        if !base.joins.is_empty() {
            return Ok(None);
        }
        if !plain_table_factor(&base.relation) {
            return Ok(None);
        }
        let sqlparser::ast::TableFactor::Table { name, alias, .. } = &base.relation else {
            return Ok(None);
        };
        let tname = obj_name(name);
        if is_compat_view(&tname) {
            return Ok(None);
        }
        let Some(meta) = self.tables.get(&tname) else {
            return Ok(None);
        };
        let Some(order_by) = order_by else {
            return Ok(None);
        };
        let sqlparser::ast::OrderByKind::Expressions(exprs) = &order_by.kind else {
            return Ok(None);
        };
        if exprs.is_empty() {
            return Ok(None);
        }
        // `SELECT *`(含 `*, expr`)的输出列集是「全部过滤行」的字段并集
        // (通用路径在 LIMIT 之前推导,空集时退化为声明列);窗口快路径
        // 只装载 skip+take 行,并集会丢掉只存在于窗口之外行的字段——列
        // 形状随 ORDER BY 列有无索引而漂移。通配符一律回退通用路径(与
        // unindexed top-K 窗口同一门禁)。
        if select.projection.iter().any(|i| {
            matches!(
                i,
                sqlparser::ast::SelectItem::Wildcard(_)
                    | sqlparser::ast::SelectItem::QualifiedWildcard(_, _)
            )
        }) {
            return Ok(None);
        }
        // 输出列名优先(与 apply_order_limit 同一解析序):ORDER BY 键名命中
        // 投影别名时,通用路径按该输出列的值排序;索引窗口按同名表列走
        // 树序 —— 只有输出列表达式恰是同一裸列引用时两者才一致,否则
        // 必须回退通用路径,别让别名遮蔽带索引列静默给出错误行序。
        // 通配符项展开为全部表列的恒等映射(position() 首个命中即表列),
        // 无需逐项判定。
        let mut effective: Vec<&SqlExpr> = Vec::with_capacity(exprs.len());
        if !select.projection.iter().all(|i| {
            matches!(
                i,
                sqlparser::ast::SelectItem::UnnamedExpr(_)
                    | sqlparser::ast::SelectItem::ExprWithAlias { .. }
            )
        }) {
            for o in exprs {
                effective.push(&o.expr);
            }
        } else {
            let mut project: Vec<(String, &SqlExpr)> = Vec::new();
            for item in &select.projection {
                match item {
                    sqlparser::ast::SelectItem::UnnamedExpr(e) => project.push((expr_name(e), e)),
                    sqlparser::ast::SelectItem::ExprWithAlias { expr, alias, .. } => {
                        project.push((alias.value.clone(), expr))
                    }
                    _ => unreachable!("gated above"),
                }
            }
            for o in exprs {
                let name = expr_name(&o.expr);
                effective.push(match project.iter().find(|(c, _)| *c == name) {
                    Some((_, e)) => *e,
                    None => {
                        // 序号键(`ORDER BY 2`)按输出位置排序:树序无法
                        // 保证一致,回退。
                        if name.parse::<usize>().is_ok() {
                            return Ok(None);
                        }
                        &o.expr
                    }
                });
            }
        }
        let akey = alias.as_ref().map(|a| a.name.value.clone());
        let Some((root_key, asc)) =
            order_walk_index(meta, &tname, akey.as_deref(), selection, exprs, &effective)
        else {
            return Ok(None);
        };
        let Some((skip, take)) = constant_limit_window(query) else {
            return Ok(None);
        };
        if take == 0 {
            return Ok(Some(OrderedWindowPlan {
                table: tname,
                root_key,
                asc,
                skip,
                take: 0,
                exact: true,
                probe: None,
            }));
        }
        let root = meta.index_roots[&root_key];
        let tree = BTree::open(root);
        let tx = self.pager.begin_tx();
        let (plan, exact) = match selection {
            None => (None, true),
            Some(cond) => match probe_plan(cond, meta, &tname, akey.as_deref()) {
                Some((plan_root, plan, exact)) if plan_root == root_key => {
                    // 混合带不可安全探测:整体回退通用路径;边界被实际
                    // 提升时计划降级为非 exact(残余过滤兜住多拉的候选)。
                    match self.promote_plan_bounds(&tree, &tx, &plan)? {
                        None => {
                            drop(tx);
                            return Ok(None);
                        }
                        Some((p, promoted)) => (Some(p), exact && !promoted),
                    }
                }
                _ => {
                    drop(tx);
                    return Ok(None);
                }
            },
        };
        drop(tx);
        Ok(Some(OrderedWindowPlan {
            table: tname,
            root_key,
            asc,
            skip,
            take,
            exact,
            probe: plan,
        }))
    }

    fn table_pairs(&self, table: &str) -> Result<Vec<(u64, Object)>> {
        let Some(meta) = self.tables.get(table) else {
            return err(format!("table {table} does not exist"));
        };
        let heap = meta.heap_of();
        let mut out = Vec::new();
        let rtx = self.pager.begin_tx();
        for &pid in &heap.pages {
            // The heap walk is the first cost a WHERE-less SELECT pays over a
            // big table — keep the statement timeout armed here too.
            self.deadline.check()?;
            out.extend(heap.page_docs(&self.reader(), &rtx, pid)?);
        }
        // The read-only tx has no staged pages: dropping it is the cleanup.
        Ok(out)
    }
}

// ---- EXPLAIN SELECT -------------------------------------------------
//
// The plan ladder without execution: the rows describe what `exec_select`
// WOULD do for this shape — same gates, same planning helpers — so an
// operator can see index use / window eligibility / join strategy without
// running an O(table) query. The mirrors are load-bearing: a gate added
// to `exec_select` or the window planners must be mirrored here, and the
// differential window tests plus the EXPLAIN suite pin both sides.

/// Render a probe plan as an EXPLAIN `PROBE` row's detail text.
fn probe_plan_text(root: &str, plan: &ProbePlan) -> String {
    let lit = |v: &Value| value_literal(v).unwrap_or_else(|_| "?".to_string());
    match plan {
        ProbePlan::Eq(v) => format!("{root} = {}", lit(v)),
        ProbePlan::Prefix(v) => format!("{root} key prefix {}", lit(v)),
        ProbePlan::In(vals) => {
            // A rewritten IN (SELECT …) can carry thousands of literals —
            // the EXPLAIN row summarizes instead of echoing them all.
            const SHOW: usize = 16;
            let items = vals.iter().map(&lit).collect::<Vec<_>>();
            if items.len() <= SHOW {
                format!("{root} IN ({})", items.join(", "))
            } else {
                format!(
                    "{root} IN ({}, … +{} more)",
                    items[..SHOW].join(", "),
                    items.len() - SHOW
                )
            }
        }
        ProbePlan::Range { lo, hi } => {
            let mut parts: Vec<String> = Vec::new();
            match lo {
                Some((v, true)) => parts.push(format!(">= {}", lit(v))),
                Some((v, false)) => parts.push(format!("> {}", lit(v))),
                None => {}
            }
            match hi {
                Some((v, true)) => parts.push(format!("<= {}", lit(v))),
                Some((v, false)) => parts.push(format!("< {}", lit(v))),
                None => {}
            }
            if parts.is_empty() {
                format!("{root} (full range)")
            } else {
                format!("{root} {}", parts.join(" AND "))
            }
        }
    }
}

impl<'a> ReadCx<'a> {
    /// EXPLAIN entry (both dispatch sites: the write-path parser match and
    /// the guardless read view): validates the EXPLAIN modifiers, then
    /// plans the inner SELECT without executing it.
    pub(crate) fn explain_outer(
        &self,
        statement: &Statement,
        analyze: bool,
        estimate: bool,
        format: &Option<sqlparser::ast::AnalyzeFormatKind>,
        options: &Option<Vec<sqlparser::ast::UtilityOption>>,
    ) -> Result<ExecOutcome> {
        if analyze {
            return err("EXPLAIN ANALYZE is not supported (plan only)");
        }
        if estimate {
            return err("EXPLAIN ESTIMATE is not supported");
        }
        if format.is_some() {
            return err("EXPLAIN FORMAT is not supported");
        }
        if options.is_some() {
            return err("EXPLAIN utility options are not supported");
        }
        // `EXPLAIN QUERY PLAN` (SQLite) and `verbose` are accepted as the
        // same plan output; `DESC <stmt>` parses into the same variant.
        match statement {
            Statement::Query(q) => self.explain_query((**q).clone()),
            _ => err("EXPLAIN supports SELECT queries only"),
        }
    }

    fn explain_query(&self, query: Query) -> Result<ExecOutcome> {
        // Same preprocessing order as `exec_query_body`: `SELECT TOP (n)`
        // rewrites into LIMIT before the clause gates run, so EXPLAIN must
        // not reject (by skipping the rewrite) a statement that executes
        // fine.
        let query = rewrite_tsql_top(query)?;
        reject_unsupported_query_clauses(&query)?;
        if query.with.is_some() {
            return err("EXPLAIN: WITH (CTE) planning is not supported");
        }
        let select = match &*query.body {
            sqlparser::ast::SetExpr::Select(select) => (**select).clone(),
            // A parenthesized body re-dispatches at execution time; explain
            // the inner query instead of refusing with a set-operations
            // message that describes a query that never ran.
            sqlparser::ast::SetExpr::Query(inner) => {
                return self.explain_query((**inner).clone());
            }
            _ => return err("EXPLAIN supports a single SELECT (set operations are not planned)"),
        };
        let mut rows: Vec<Vec<Value>> = Vec::new();
        self.explain_select(&query, select, &mut rows)?;
        Ok(ExecOutcome::Rows(QueryResult {
            columns: vec!["plan".to_string(), "detail".to_string()],
            rows,
        }))
    }

    fn explain_row(out: &mut Vec<Vec<Value>>, op: &str, detail: String) {
        out.push(vec![Value::Str(op.to_string()), Value::Str(detail)]);
    }

    fn explain_select(
        &self,
        query: &Query,
        select: sqlparser::ast::Select,
        out: &mut Vec<Vec<Value>>,
    ) -> Result<()> {
        reject_unsupported_select_clauses(&select)?;
        let row = |out: &mut Vec<Vec<Value>>, op: &str, detail: String| {
            Self::explain_row(out, op, detail);
        };

        // Aggregate detection mirrors exec_select.
        let group_exprs: Vec<SqlExpr> = match &select.group_by {
            sqlparser::ast::GroupByExpr::Expressions(e, modifiers) => {
                // Mirror the executor's refusal: exec_select rejects
                // non-empty modifiers, so a plan that silently dropped them
                // would describe a query that never runs.
                if !modifiers.is_empty() {
                    return err(
                        "GROUP BY modifiers (WITH ROLLUP/CUBE/TOTALS) are not supported \
                         (use GROUP BY ROLLUP(...)/CUBE(...))",
                    );
                }
                e.clone()
            }
            sqlparser::ast::GroupByExpr::All(_) => return err("GROUP BY ALL is not supported"),
        };
        let is_aggregate = !group_exprs.is_empty() || select.projection.iter().any(is_agg_item);
        let distinct_all = matches!(&select.distinct, None | Some(sqlparser::ast::Distinct::All));
        let has_window = !window_calls_of(&select.projection).is_empty();
        let rownum_wanted = select_refs_rownum(&select) && !is_aggregate;

        if select.from.is_empty() {
            row(out, "SCAN", "no FROM — one constant row".to_string());
            return Ok(());
        }

        let where_text = select.selection.as_ref().map(|c| format!("WHERE ({c})"));
        let solo = select.from.len() == 1 && select.from[0].joins.is_empty();

        if solo {
            if let sqlparser::ast::TableFactor::Table {
                name, alias, args, ..
            } = &select.from[0].relation
            {
                let tname = obj_name(name);
                if args.is_some() {
                    // Table-valued function factor: the executor
                    // materializes it at runtime; there is no stored table
                    // to plan against (refusing with "table does not
                    // exist" described a query that runs fine).
                    row(
                        out,
                        "SCAN",
                        format!(
                            "table function {tname} — materialized at runtime (plan not detailed)"
                        ),
                    );
                } else if !plain_table_factor(&select.from[0].relation) {
                    // TABLESAMPLE / index hints / alias column lists / VERSION
                    // AS OF …: load_table_factor rejects these at runtime —
                    // printing an INDEX PROBE plan for a statement that
                    // cannot execute breaks the EXPLAIN/exec mirror.
                    return err("table factor carries clauses the executor rejects \
                         (TABLESAMPLE / index hints / alias columns / VERSION AS OF)");
                } else if is_compat_view(&tname) {
                    row(
                        out,
                        "SCAN",
                        format!("compatibility view {tname} (virtual, no heap)"),
                    );
                } else if let Some(meta) = self.tables.get(&tname) {
                    if meta.is_view() {
                        row(
                            out,
                            "VIEW",
                            format!(
                                "{tname} — stored definition expanded at runtime; \
                                 the base-table plan is not detailed"
                            ),
                        );
                    } else if self.explain_count_star_gate(query, &select)? {
                        row(
                            out,
                            "SCAN",
                            format!("COUNT(*) ON {tname} — live slot count, no document decode"),
                        );
                        return Ok(());
                    } else {
                        self.explain_real_table_scan(
                            query,
                            &select,
                            &tname,
                            alias.as_ref().map(|a| a.name.value.clone()),
                            is_aggregate,
                            distinct_all,
                            has_window,
                            rownum_wanted,
                            out,
                        )?;
                    }
                } else {
                    return err(format!("table {tname} does not exist"));
                }
            } else {
                row(
                    out,
                    "SCAN",
                    "non-plain FROM factor — executed at runtime (plan not detailed)".to_string(),
                );
            }
        } else {
            self.explain_join_shape(&select, out)?;
        }

        // Post-scan clause rows (the window paths consume WHERE + ORDER +
        // LIMIT, which their SCAN rows already say).
        let windowed = out
            .iter()
            .any(|r| r[1].as_str().is_some_and(|d| d.contains("WINDOW")));
        if let Some(w) = &where_text {
            if !windowed {
                row(out, "FILTER", format!("{w} (row-local evaluation)"));
            }
        }
        if query.order_by.is_some() && !windowed {
            row(out, "SORT", "in-memory generic sort".to_string());
        }
        if (query.limit_clause.is_some() || query.fetch.is_some()) && !windowed {
            row(out, "LIMIT", "applied after scanning/sorting".to_string());
        }
        if !distinct_all {
            row(out, "DISTINCT", "dedup after scan".to_string());
        }
        if select.having.is_some() {
            row(out, "HAVING", "post-aggregate filter".to_string());
        }
        if is_aggregate {
            row(
                out,
                "AGGREGATE",
                "grouped/aggregate execution path".to_string(),
            );
        }
        if has_window {
            row(
                out,
                "WINDOW",
                "window functions force full rowset materialization (fast paths off)".to_string(),
            );
        }
        if rownum_wanted {
            row(
                out,
                "ROWNUM",
                "numbered before WHERE (Oracle semantics)".to_string(),
            );
        }
        Ok(())
    }

    /// The scan rows for a solo REAL table: window fast paths, then the
    /// index probe, then the full-scan fallback — in exec order.
    #[allow(clippy::too_many_arguments)]
    fn explain_real_table_scan(
        &self,
        query: &Query,
        select: &sqlparser::ast::Select,
        tname: &str,
        alias: Option<String>,
        is_aggregate: bool,
        distinct_all: bool,
        has_window: bool,
        rownum_wanted: bool,
        out: &mut Vec<Vec<Value>>,
    ) -> Result<()> {
        let row = |out: &mut Vec<Vec<Value>>, op: &str, detail: String| {
            Self::explain_row(out, op, detail);
        };
        let meta = self.tables.get(tname).expect("caller resolved the table");
        let ctes = Ctes::new();
        let fast_eligible = !is_aggregate
            && !rownum_wanted
            && select.having.is_none()
            && distinct_all
            && !has_window;
        if fast_eligible {
            if let Some(p) = self.ordered_window_plan(
                select,
                &select.from,
                &select.selection,
                &query.order_by,
                query,
                &ctes,
            )? {
                row(
                    out,
                    "SCAN",
                    format!(
                        "ORDERED INDEX WINDOW ON {tname} USING {} {} SKIP {} LIMIT {}{}",
                        p.root_key,
                        if p.asc { "ASC" } else { "DESC" },
                        p.skip,
                        p.take,
                        if p.exact { "" } else { " + residual WHERE" }
                    ),
                );
                if let Some(plan) = &p.probe {
                    row(out, "PROBE", probe_plan_text(&p.root_key, plan));
                }
                return Ok(());
            }
            if let Some(up) = self.unindexed_window_plan(select, query, &ctes)? {
                let fields = up
                    .keys
                    .iter()
                    .map(|(f, _, _)| f.first().cloned().unwrap_or_default())
                    .collect::<Vec<_>>()
                    .join(", ");
                row(
                    out,
                    "SCAN",
                    format!(
                        "TOP-K WINDOW ON {} BY {fields} SKIP {} LIMIT {} \
                         (encoded-byte key extraction)",
                        up.table, up.skip, up.take
                    ),
                );
                return Ok(());
            }
        }
        // Index probe (load_from's fast path): solo plain real table with a
        // WHERE whose AND-conjuncts the planner can subsume.
        let akey = alias.as_deref();
        if let Some(cond) = &select.selection {
            if let Some((root, plan, exact)) = probe_plan(cond, meta, tname, akey) {
                // Mirror the executor exactly: probe_pairs falls back to a
                // full scan when promote_plan_bounds cannot lift the bounds
                // into the tree's key type (mixed Str/Timestamp column). A
                // plan line promising an index probe the executor never
                // takes would mislead tuning.
                let tree = BTree::open(meta.index_roots[&root]);
                let tx = self.pager.begin_tx();
                let liftable = self.promote_plan_bounds(&tree, &tx, &plan)?.is_some();
                drop(tx);
                if liftable {
                    row(
                        out,
                        "SCAN",
                        format!(
                            "INDEX PROBE ON {tname} USING {root}{}",
                            if exact { "" } else { " + residual WHERE" }
                        ),
                    );
                    row(out, "PROBE", probe_plan_text(&root, &plan));
                    return Ok(());
                }
            }
        }
        row(out, "SCAN", format!("FULL HEAP SCAN ON {tname}"));
        Ok(())
    }

    /// Join shapes: every side loads fully, then combines — the per-join
    /// strategy (equi/hash vs nested loop) mirrors `join_rows`.
    fn explain_join_shape(
        &self,
        select: &sqlparser::ast::Select,
        out: &mut Vec<Vec<Value>>,
    ) -> Result<()> {
        let row = |out: &mut Vec<Vec<Value>>, op: &str, detail: String| {
            Self::explain_row(out, op, detail);
        };
        for twj in &select.from {
            let desc = self.explain_factor_desc(&twj.relation)?;
            row(out, "SCAN", format!("JOIN SIDE FULL LOAD — {desc}"));
            for j in &twj.joins {
                let kind = match &j.join_operator {
                    sqlparser::ast::JoinOperator::Inner(_) => "INNER",
                    sqlparser::ast::JoinOperator::LeftOuter(_) => "LEFT",
                    sqlparser::ast::JoinOperator::RightOuter(_) => "RIGHT",
                    sqlparser::ast::JoinOperator::FullOuter(_) => "FULL",
                    sqlparser::ast::JoinOperator::CrossJoin(_) => "CROSS",
                    sqlparser::ast::JoinOperator::CrossApply => {
                        row(
                            out,
                            "JOIN",
                            "CROSS APPLY — right side per left row".to_string(),
                        );
                        continue;
                    }
                    sqlparser::ast::JoinOperator::OuterApply => {
                        row(
                            out,
                            "JOIN",
                            "OUTER APPLY — right side per left row".to_string(),
                        );
                        continue;
                    }
                    _ => "JOIN",
                };
                let right_desc = self.explain_factor_desc(&j.relation)?;
                let right_key = match &j.relation {
                    sqlparser::ast::TableFactor::Table { name, alias, .. } => alias
                        .as_ref()
                        .map(|a| a.name.value.clone())
                        .unwrap_or_else(|| obj_name(name)),
                    sqlparser::ast::TableFactor::Derived { alias, .. } => alias
                        .as_ref()
                        .map(|a| a.name.value.clone())
                        .unwrap_or_else(|| "?".to_string()),
                    _ => "?".to_string(),
                };
                // Same extraction the executor uses (the plain JOIN
                // keyword parses as JoinOperator::Join).
                let on = join_on_expr(&j.join_operator);
                let strategy = match on {
                    None => "nested loop (no ON)".to_string(),
                    Some(e) => {
                        if equi_plan(&right_key, e).is_some() {
                            "hash join (equi ON)".to_string()
                        } else {
                            "nested loop (non-equi or unqualified ON)".to_string()
                        }
                    }
                };
                let on_text = on.map(|e| format!(" ON ({e})")).unwrap_or_default();
                row(
                    out,
                    "JOIN",
                    format!("{kind} {strategy}{on_text} — right side: {right_desc}"),
                );
            }
        }
        Ok(())
    }

    fn explain_factor_desc(&self, tf: &sqlparser::ast::TableFactor) -> Result<String> {
        // Mirror `load_table_factor`'s rejection gates: a factor carrying
        // clauses the executor refuses must not be described as a runnable
        // plan — EXPLAIN used to print "JOIN SIDE FULL LOAD" for
        // TABLESAMPLE / index-hint / time-travel factors that then failed
        // on execution (same red line the solo branch enforces).
        match tf {
            sqlparser::ast::TableFactor::Table {
                sample,
                version,
                partitions,
                with_hints,
                index_hints,
                with_ordinality,
                json_path,
                alias,
                ..
            } => {
                if sample.is_some() {
                    return err("TABLESAMPLE is not supported");
                }
                if version.is_some() {
                    return err("table time travel (AS OF / FOR SYSTEM_TIME) is not supported");
                }
                if !partitions.is_empty() {
                    return err("partition selection (PARTITION (...)) is not supported");
                }
                if !with_hints.is_empty() {
                    return err("table hints (WITH (...)) are not supported");
                }
                if !index_hints.is_empty() {
                    return err("index hints are not supported");
                }
                if *with_ordinality {
                    return err("WITH ORDINALITY is not supported");
                }
                if json_path.is_some() {
                    return err("JSON path table sources are not supported");
                }
                if alias.as_ref().is_some_and(|a| !a.columns.is_empty()) {
                    return err("column aliases on a table alias are not supported");
                }
            }
            sqlparser::ast::TableFactor::Derived {
                lateral, sample, ..
            } => {
                if *lateral {
                    return err("LATERAL derived tables are not supported");
                }
                if sample.is_some() {
                    return err("TABLESAMPLE is not supported");
                }
            }
            _ => {}
        }
        Ok(match tf {
            sqlparser::ast::TableFactor::Table { name, alias, .. } => {
                let tname = obj_name(name);
                if is_compat_view(&tname) {
                    format!("compatibility view {tname} (virtual)")
                } else if self.tables.get(&tname).is_some_and(|m| m.is_view()) {
                    format!("view {tname} (expanded at runtime)")
                } else {
                    let a = alias
                        .as_ref()
                        .map(|a| format!(" AS {}", a.name.value))
                        .unwrap_or_default();
                    format!("table {tname}{a}")
                }
            }
            sqlparser::ast::TableFactor::Derived { alias, .. } => {
                let a = alias
                    .as_ref()
                    .map(|a| a.name.value.clone())
                    .unwrap_or_else(|| "?".to_string());
                format!("derived table {a} (subquery executed at runtime)")
            }
            sqlparser::ast::TableFactor::TableFunction { .. } => {
                "table function (executed at runtime)".to_string()
            }
            _ => "subquery/NESTED factor (executed at runtime)".to_string(),
        })
    }

    /// Pure-AST mirror of `try_count_star`'s eligibility gates (no heap
    /// access): true when `SELECT COUNT(*) FROM <solo real table>` takes
    /// the live-count fast path.
    fn explain_count_star_gate(
        &self,
        query: &Query,
        select: &sqlparser::ast::Select,
    ) -> Result<bool> {
        if select.selection.is_some()
            || select.having.is_some()
            || select.top.is_some()
            || !matches!(&select.distinct, None | Some(sqlparser::ast::Distinct::All))
            || query.order_by.is_some()
            || query.limit_clause.is_some()
            || query.fetch.is_some()
            || select.projection.len() != 1
            || select.from.len() != 1
            || !select.from[0].joins.is_empty()
            || !matches!(&select.group_by, sqlparser::ast::GroupByExpr::Expressions(e, _) if e.is_empty())
        {
            return Ok(false);
        }
        if !plain_table_factor(&select.from[0].relation) {
            return Ok(false);
        }
        let sqlparser::ast::TableFactor::Table { name, .. } = &select.from[0].relation else {
            return Ok(false);
        };
        let tname = obj_name(name);
        let Some(meta) = self.tables.get(&tname).filter(|m| !m.is_view()) else {
            return Ok(false);
        };
        let _ = meta;
        let expr = match &select.projection[0] {
            SelectItem::UnnamedExpr(e) => e,
            SelectItem::ExprWithAlias { expr, .. } => expr,
            _ => return Ok(false),
        };
        let SqlExpr::Function(f) = expr else {
            return Ok(false);
        };
        if !f.name.to_string().eq_ignore_ascii_case("count")
            || f.filter.is_some()
            || f.over.is_some()
        {
            return Ok(false);
        }
        use sqlparser::ast::{DuplicateTreatment, FunctionArg, FunctionArgExpr, FunctionArguments};
        Ok(matches!(&f.args, FunctionArguments::List(list) if {
            !matches!(list.duplicate_treatment, Some(DuplicateTreatment::Distinct))
                && list.args.len() == 1
                && matches!(list.args[0], FunctionArg::Unnamed(FunctionArgExpr::Wildcard))
        }))
    }
}

/// One row trigger's definition (`CREATE TRIGGER`). Stored in the catalog
/// (`triggers` key) and re-parsed from the AST at CREATE time; replication
/// replays the creating DDL verbatim on every node, so the body must be
/// deterministic — enforced by [`Database::exec_create_trigger`], never
/// assumed.
#[derive(Clone, Debug)]
pub(crate) struct TriggerDef {
    /// Global unique name (one namespace with tables/views/indexes is NOT
    /// enforced — SQLite likewise scopes nothing; uniqueness among triggers
    /// is what DROP TRIGGER resolves).
    pub(crate) name: String,
    /// Target table (never a view, never a system/internal table).
    pub(crate) table: String,
    /// BEFORE or AFTER (INSTEAD OF is rejected at CREATE time).
    pub(crate) before: bool,
    pub(crate) insert: bool,
    pub(crate) delete: bool,
    /// UPDATE trigger. `Some(cols)` = UPDATE OF: fire only when the
    /// statement assigns at least one listed column.
    pub(crate) update: bool,
    pub(crate) update_of: Option<Vec<String>>,
    /// WHEN predicate over NEW./OLD. references, stored as SQL text.
    /// Evaluated per row after substitution; false/NULL skips the body.
    pub(crate) when: Option<String>,
    pub(crate) body: Vec<TriggerAction>,
}

/// One statement of a trigger body. `Sql` re-executes verbatim with
/// NEW./OLD. references substituted per row; `Raise` aborts the statement.
#[derive(Clone, Debug)]
pub(crate) enum TriggerAction {
    Sql(String),
    /// `SELECT RAISE(ABORT|FAIL, 'msg')` — both spellings abort the
    /// statement (DocSQL statement atomicity makes them equivalent; SQLite's
    /// FAIL would leave prior rows of the statement applied, which this
    /// engine's all-or-nothing statements never do). `RAISE(IGNORE)` and
    /// `RAISE(ROLLBACK)` are rejected at CREATE time.
    Raise {
        fail: bool,
        msg: String,
    },
}

/// Max trigger cascade depth (a trigger body statement firing further
/// triggers). SQLite allows deep cascades and dies on its own budget; ours
/// is loud at 16 so an infinite `t1 → t2 → t1` cycle errors instead of
/// hanging the single writer.
const MAX_TRIGGER_DEPTH: u8 = 16;

pub struct Database {
    pager: std::sync::Arc<Pager>,
    tables: std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
    /// Row triggers by name (see [`TriggerDef`]). Only the write path ever
    /// reads this map, always under the engine write lock — no snapshot
    /// plumbing (unlike `tables`, catalog snapshots don't carry triggers;
    /// trigger bodies never read triggers).
    triggers: std::collections::BTreeMap<String, TriggerDef>,
    /// Trigger-body execution depth (> 0 = a triggering statement is
    /// mid-flight under its statement guard; nested DML joins that guard
    /// instead of opening its own).
    trigger_depth: u8,
    /// Async-commit mode (MongoDB-style journal interval): every statement
    /// commit skips the WAL fsync; a background flusher batches fsyncs.
    /// Trades bounded (ms) loss window on power failure for throughput.
    async_commit: bool,
    /// True when deferred commits are waiting for a WAL fsync.
    pending_sync: bool,
    /// Open fused write units (see [`Database::write_unit`]); depth-counted
    /// because the guard borrows the database. While non-zero, statement
    /// commits defer their WAL fsync to the unit's `end`, so a statement and
    /// its replication bookkeeping (journal append / position update) share
    /// one fsync and are atomic on crash.
    write_unit: u8,
    /// SAVEPOINT stack inside the open transaction: (name, snapshot, undo
    /// journal mark). Each ROLLBACK TO restores its snapshot and drops
    /// everything above it, including the journal tail.
    savepoints: Vec<(String, TableSnapshot, usize)>,
    /// Session transaction snapshot: full table state at BEGIN. Rollback
    /// restores it; commit just discards it (durability is the WAL's job).
    tx_snapshot: Option<TableSnapshot>,
    /// Cooperative deadline for the statement currently executing (see
    /// [`StmtDeadline`]); armed per client statement by the server, never
    /// set for replication apply / restore replay.
    stmt_deadline: StmtDeadline,
    /// Lazily-computed AUTOINCREMENT next id per table (max(id)+1 over the
    /// heap). Invalidated by rewrites/deletes; not persisted — recomputed
    /// after restart, preserving max(existing)+1 semantics.
    autoinc_cache: std::collections::HashMap<String, i64>,
    /// Canonical rewrite of the last executed statement when it auto-filled
    /// GUID values (explicit generated ids embedded). Replicating callers
    /// must forward this text instead of the original: random GUIDs cannot
    /// be re-derived on peers the way AUTOINCREMENT's deterministic max+1
    /// can. Reset at the start of every statement; see `take_resolved_sql`.
    resolved_sql: Option<String>,
    /// AUTOINCREMENT id assigned by the last INSERT (max over inserted
    /// rows; explicit values count). Lets callers that must know the
    /// assigned id — protocol INSERTs, the pub/sub store — read it back
    /// without a second `SELECT MAX(id)` statement, which is a full heap
    /// scan. Reset at the start of every statement.
    last_insert_id: Option<i64>,
    /// Next seq for the catch-up journal ([`Database::journal_append`]).
    /// Seeded lazily from MAX(seq)+1 (in-memory counter under the write
    /// lock; gaps from failed statements are harmless — positions pull
    /// ranges, not counts).
    journal_next: Option<u64>,
    /// Running total of journal SQL bytes (None = recompute lazily with one
    /// SUM scan on the next [`Database::journal_trim_bytes`]). Drives the
    /// byte cap: a count-only window lets a big-document workload grow
    /// `_cluster_log` without bound (single documents reach 16 MiB).
    journal_bytes: Option<u64>,
    /// This node's persistent random identity (see CLUSTER_ID_TABLE),
    /// cached after first read.
    cluster_id: Option<String>,
    /// Set only while `ensure_user_tables` runs its own DDL: the reserved
    /// user/role table names are otherwise rejected in CREATE TABLE so
    /// clients cannot shadow them.
    pub(crate) internal_ddl: bool,
}

impl Database {
    /// Commit a statement's pager tx: while an explicit SQL transaction or a
    /// fused write unit is open the WAL fsync is deferred — the whole batch
    /// pays one flush at COMMIT / [`WriteUnit::end`], turning N fsyncs per
    /// transaction into one.
    fn commit_pager_tx(&mut self, tx: crate::pager::Tx) -> Result<u64> {
        if self.async_commit || self.tx_snapshot.is_some() || self.write_unit > 0 {
            self.pending_sync = true;
            self.pager.commit_tx_deferred(tx).map_err(SqlError::from)
        } else {
            // The synchronous commit fsyncs the WAL and flushes every page
            // image queued before it, so earlier deferred commits are durable
            // too — nothing is left pending. On failure the flag stays set:
            // the earlier deferred commits may not be durable yet.
            let result = self.pager.commit_tx(tx).map_err(SqlError::from);
            if result.is_ok() {
                self.pending_sync = false;
            }
            result
        }
    }

    /// Open fused write unit: every statement committed until
    /// [`WriteUnit::end`] defers its WAL fsync, and the unit's single `end`
    /// fsync makes them durable together — a crash mid-unit loses them all,
    /// never a prefix. Servers use this to land a write and its replication
    /// bookkeeping (catch-up journal entry on the origin, position update on
    /// the receiver) in one fsync instead of two, closing the
    /// "bookkeeping lags the data" crash window entirely.
    ///
    /// Unlike BEGIN it takes no rollback snapshot; a failed trailing
    /// statement leaves the earlier ones applied-but-unsynced, so callers
    /// that want the prefix to survive must call `end` on error paths too.
    /// Dropping the guard without `end` only forgets the fusion (the flag
    /// clears on drop; the next durable statement fsyncs anything deferred
    /// before it), so a leaked unit can never wedge durability.
    pub fn write_unit(&mut self) -> WriteUnit<'_> {
        self.write_unit += 1;
        WriteUnit { db: self }
    }

    /// Enable async-commit mode: statement commits skip the WAL fsync and a
    /// caller-provided flusher (see `sync_pending`) batches them.
    pub fn set_async_commit(&mut self, on: bool) {
        self.async_commit = on;
    }

    /// True when deferred commits still need a WAL fsync.
    pub fn has_pending_sync(&self) -> bool {
        self.pending_sync
    }

    /// Flush deferred commits (the background flusher's entry point).
    pub fn sync_pending(&mut self) -> Result<()> {
        if !self.pending_sync {
            return Ok(());
        }
        if self.tx_snapshot.is_some() {
            // Mid-transaction: these deferred commits belong to an open SQL
            // transaction. Appending the durable fence now would make a
            // crash replay a prefix of it; the transaction's own COMMIT
            // fences the whole batch, ROLLBACK discards it.
            return Ok(());
        }
        self.pager.sync_wal().map_err(SqlError::from)?;
        self.pending_sync = false;
        Ok(())
    }
    pub fn open(path: &std::path::Path) -> Result<Database> {
        let pager = Pager::open(path)?;
        // Reserve pages 0 (header) and 1 (catalog); allocate 1 if missing.
        while pager.num_pages() <= CATALOG_PAGE {
            let mut tx = pager.begin_tx();
            let _ = pager.num_pages();
            pager.allocate_page(&mut tx)?;
            pager.commit_tx(tx)?;
        }
        let mut tables = std::collections::BTreeMap::new();
        let mut triggers = std::collections::BTreeMap::new();
        // New format: a magic-headed chain of pages. Legacy databases keep a
        // raw encoded catalog on page 1 — decode it in place; the first
        // catalog save rewrites it in the new format.
        let raw = pager.read_page(CATALOG_PAGE)?.to_vec();
        let cat_bytes: Option<Vec<u8>> = if raw.starts_with(CATALOG_MAGIC) {
            let total = u32::from_le_bytes(raw[8..12].try_into().expect("header fits")) as usize;
            let mut data = raw[CATALOG_HDR..].to_vec();
            let mut next = u32::from_le_bytes(raw[12..16].try_into().expect("header fits"));
            // A cyclic chain of valid page ids would loop forever appending
            // 4 KB per hop, so bound the walk by the page count.
            let mut hops = 0usize;
            while next != 0 {
                if next >= pager.num_pages() {
                    return err("catalog chain is corrupt (dangling overflow page)");
                }
                hops += 1;
                if hops > pager.num_pages() as usize {
                    return err("catalog chain is corrupt (cycle)");
                }
                let page = pager.read_page(next)?.to_vec();
                if !page.starts_with(CATALOG_MAGIC) {
                    return err("catalog chain is corrupt (overflow page without magic)");
                }
                data.extend_from_slice(&page[CATALOG_HDR..]);
                next = u32::from_le_bytes(page[12..16].try_into().expect("header fits"));
            }
            if data.len() < total {
                return err("catalog chain is corrupt (payload shorter than header length)");
            }
            data.truncate(total);
            Some(data)
        } else if raw.iter().any(|&b| b != 0) {
            Some(raw)
        } else {
            None
        };
        if let Some(bytes) = cat_bytes {
            let (v, _) = encode::decode_prefix(&bytes)?;
            if let Value::Object(o) = v {
                if let Some(Value::Object(t)) = o.get("tables") {
                    for (name, meta) in t {
                        if let Value::Object(m) = meta {
                            let columns = match m.get("columns") {
                                Some(Value::Array(a)) => a
                                    .iter()
                                    .filter_map(|x| x.as_str().map(String::from))
                                    .collect(),
                                _ => vec![],
                            };
                            let pages = match m.get("pages") {
                                Some(Value::Array(a)) => a
                                    .iter()
                                    .filter_map(|x| x.as_i64().map(|i| i as u32))
                                    .collect(),
                                _ => vec![],
                            };
                            let primary_key = m
                                .get("primary_key")
                                .and_then(|v| v.as_str())
                                .map(String::from);
                            let unique = str_list(m, "unique");
                            let not_null = str_list(m, "not_null");
                            let autoinc =
                                m.get("autoinc").and_then(|v| v.as_str()).map(String::from);
                            let autoguid =
                                m.get("autoguid").and_then(|v| v.as_str()).map(String::from);
                            let view_sql =
                                m.get("view_sql").and_then(|v| v.as_str()).map(String::from);
                            let matview_sql = m
                                .get("matview_sql")
                                .and_then(|v| v.as_str())
                                .map(String::from);
                            let index_defs = match m.get("index_defs") {
                                Some(Value::Array(a)) => a
                                    .iter()
                                    .filter_map(|x| match x {
                                        Value::Array(t) => match (
                                            t.first().and_then(|v| v.as_str()),
                                            t.get(1).and_then(|v| v.as_str()),
                                            t.get(2).and_then(|v| v.as_bool()),
                                        ) {
                                            (Some(n), Some(c), Some(u)) => {
                                                // Fourth element (optional,
                                                // new-format catalogs): the
                                                // full ordered column list of
                                                // a possibly composite index.
                                                // Legacy three-element entries
                                                // are single-column.
                                                let columns = match t.get(3) {
                                                    Some(Value::Array(a)) => {
                                                        // An EMPTY array must
                                                        // not survive: IndexDef
                                                        // assumes columns
                                                        // non-empty (`column()`
                                                        // indexes [0]) and
                                                        // panics on the next
                                                        // catalog save.
                                                        let cols: Vec<_> = a
                                                            .iter()
                                                            .filter_map(|v| {
                                                                v.as_str().map(String::from)
                                                            })
                                                            .collect();
                                                        if cols.is_empty() {
                                                            vec![c.to_string()]
                                                        } else {
                                                            cols
                                                        }
                                                    }
                                                    _ => vec![c.to_string()],
                                                };
                                                // Optional 5th element (design
                                                // 005): the JSON path. Older
                                                // catalogs lack it; readers
                                                // that predate path indexes
                                                // ignore the extra element, so
                                                // the tuple stays bidirectionally
                                                // compatible with zero migration.
                                                let path = t
                                                    .get(4)
                                                    .and_then(|v| v.as_str())
                                                    .map(String::from);
                                                // Optional 6th element: the
                                                // partial-index predicate text.
                                                let pred = t
                                                    .get(5)
                                                    .and_then(|v| v.as_str())
                                                    .map(String::from);
                                                Some(IndexDef {
                                                    name: n.to_string(),
                                                    columns,
                                                    unique: u,
                                                    path,
                                                    pred,
                                                })
                                            }
                                            _ => None,
                                        },
                                        _ => None,
                                    })
                                    .collect(),
                                _ => vec![],
                            };
                            // Index names derive from the persisted defs.
                            let indexes = index_defs
                                .iter()
                                .map(|d| d.name.clone())
                                .collect::<Vec<_>>();
                            let constraint_unique = str_list(m, "constraint_unique");
                            let defaults = match m.get("defaults") {
                                Some(Value::Array(a)) => a
                                    .iter()
                                    .filter_map(|x| match x {
                                        Value::Array(pair) => match (
                                            pair.first().and_then(|c| c.as_str()),
                                            pair.get(1).and_then(|e| e.as_str()),
                                        ) {
                                            (Some(c), Some(e)) => {
                                                Some((c.to_string(), e.to_string()))
                                            }
                                            _ => None,
                                        },
                                        _ => None,
                                    })
                                    .collect(),
                                _ => vec![],
                            };
                            let checks = str_list(m, "checks");
                            let index_roots = match m.get("index_roots") {
                                Some(Value::Object(o)) => o
                                    .iter()
                                    .filter_map(|(c, v)| v.as_i64().map(|i| (c.clone(), i as u32)))
                                    .collect(),
                                _ => std::collections::BTreeMap::new(),
                            };
                            // Recycled overflow-chain pages (optional key:
                            // catalogs predating overflow documents lack it).
                            let overflow_free = match m.get("overflow_free") {
                                Some(Value::Array(a)) => a
                                    .iter()
                                    .filter_map(|v| v.as_i64().map(|i| i as u32))
                                    .collect(),
                                _ => vec![],
                            };
                            let foreign_keys = match m.get("foreign_keys") {
                                Some(Value::Array(a)) => a
                                    .iter()
                                    .filter_map(|x| match x {
                                        Value::Array(t) => match (
                                            t.first().and_then(|v| v.as_str()),
                                            t.get(1).and_then(|v| v.as_str()),
                                            t.get(2).and_then(|v| v.as_str()),
                                        ) {
                                            (Some(c), Some(rt), Some(rc)) => Some((
                                                c.to_string(),
                                                rt.to_string(),
                                                rc.to_string(),
                                            )),
                                            _ => None,
                                        },
                                        _ => None,
                                    })
                                    .collect(),
                                _ => vec![],
                            };
                            tables.insert(
                                name.clone(),
                                std::sync::Arc::new(TableMeta {
                                    name: name.clone(),
                                    columns,
                                    pages,
                                    primary_key,
                                    unique,
                                    not_null,
                                    autoinc,
                                    autoguid,
                                    view_sql,
                                    matview_sql,
                                    indexes,
                                    index_defs,
                                    constraint_unique,
                                    defaults,
                                    checks,
                                    foreign_keys,
                                    index_roots,
                                    overflow_free,
                                    dotted_keys: matches!(
                                        m.get("dotted_keys"),
                                        Some(Value::Bool(true))
                                    ),
                                }),
                            );
                        }
                    }
                }
                // Row triggers (see [`TriggerDef`]). Same tolerant decode as
                // the table metas: a malformed entry is skipped, not fatal —
                // the encoder above only ever writes the shapes decoded here.
                if let Some(Value::Object(ts)) = o.get("triggers") {
                    for (name, td) in ts {
                        let Some(Value::Object(t)) = Some(td) else {
                            continue;
                        };
                        let (Some(table), Some(before), Some(insert), Some(delete), Some(update)) = (
                            t.get("table").and_then(|v| v.as_str()),
                            t.get("before").and_then(|v| v.as_bool()),
                            t.get("insert").and_then(|v| v.as_bool()),
                            t.get("delete").and_then(|v| v.as_bool()),
                            t.get("update").and_then(|v| v.as_bool()),
                        ) else {
                            continue;
                        };
                        let update_of = match t.get("update_of") {
                            Some(Value::Array(a)) => Some(
                                a.iter()
                                    .filter_map(|v| v.as_str().map(String::from))
                                    .collect(),
                            ),
                            _ => None,
                        };
                        let when = t.get("when").and_then(|v| v.as_str()).map(String::from);
                        let body = match t.get("body") {
                            Some(Value::Array(a)) => a
                                .iter()
                                .filter_map(|x| match x {
                                    Value::Array(parts) => match (
                                        parts.first().and_then(|v| v.as_str()),
                                        parts.get(1).and_then(|v| v.as_str()),
                                    ) {
                                        (Some("sql"), Some(text)) => {
                                            Some(TriggerAction::Sql(text.to_string()))
                                        }
                                        (Some("raise"), Some(msg)) => Some(TriggerAction::Raise {
                                            fail: matches!(parts.get(2), Some(Value::Bool(true))),
                                            msg: msg.to_string(),
                                        }),
                                        _ => None,
                                    },
                                    _ => None,
                                })
                                .collect(),
                            _ => vec![],
                        };
                        triggers.insert(
                            name.clone(),
                            TriggerDef {
                                name: name.clone(),
                                table: table.to_string(),
                                before,
                                insert,
                                delete,
                                update,
                                update_of,
                                when,
                                body,
                            },
                        );
                    }
                }
            }
        }
        Ok(Database {
            pager: std::sync::Arc::new(pager),
            tables,
            triggers,
            trigger_depth: 0,
            async_commit: false,
            pending_sync: false,
            write_unit: 0,
            savepoints: Vec::new(),
            tx_snapshot: None,
            stmt_deadline: StmtDeadline::default(),
            autoinc_cache: std::collections::HashMap::new(),
            resolved_sql: None,
            last_insert_id: None,
            journal_next: None,
            journal_bytes: None,
            cluster_id: None,
            internal_ddl: false,
        })
    }

    pub fn in_memory() -> Result<Database> {
        let dir = tempfile::tempdir().map_err(|e| SqlError::Message(e.to_string()))?;
        // Leak: process-lifetime scratch DB, fine for embedded use/tests.
        let path = dir.keep().join("mem.db");
        Database::open(&path)
    }

    /// Record a statement's resulting heap layout and index roots in the
    /// catalog inside `tx`. On save failure the catalog map is restored to
    /// the pre-statement truth: the tx is dropped on that path, so its
    /// staged pages never reach the data file, and a map left pointing at
    /// them would let a later successful save persist ghost pages.
    fn sync_table_layout(
        &mut self,
        tx: &mut crate::pager::Tx,
        tname: &str,
        pages: Vec<u32>,
        roots: std::collections::BTreeMap<String, u32>,
        overflow_free: Vec<u32>,
    ) -> Result<()> {
        let prev = self.tables.get(tname).map(|m| {
            (
                m.pages.clone(),
                m.index_roots.clone(),
                m.overflow_free.clone(),
            )
        });
        if let Some(m) = self.catalog_mut(tname) {
            m.pages = pages;
            m.index_roots = roots;
            m.overflow_free = overflow_free;
        }
        if let Err(e) = self.save_catalog_into(tx) {
            if let Some((pages, index_roots, overflow_free)) = prev {
                if let Some(m) = self.catalog_mut(tname) {
                    m.pages = pages;
                    m.index_roots = index_roots;
                    // Restoring the free list matters as much as the page
                    // list: leaving recycled chain pages in it would let a
                    // later oversized insert overwrite live documents.
                    m.overflow_free = overflow_free;
                }
            }
            return Err(e);
        }
        Ok(())
    }

    fn save_catalog_into(&mut self, tx: &mut crate::pager::Tx) -> Result<()> {
        let mut tables = Object::new();
        for (name, meta) in &self.tables {
            let mut m = Object::new();
            m.insert(
                "columns".into(),
                Value::Array(meta.columns.iter().map(|c| Value::Str(c.clone())).collect()),
            );
            m.insert(
                "pages".into(),
                Value::Array(meta.pages.iter().map(|p| Value::Int(*p as i64)).collect()),
            );
            if let Some(pk) = &meta.primary_key {
                m.insert("primary_key".into(), Value::Str(pk.clone()));
            }
            // AUTOINCREMENT column must survive reopen: dropping it silently
            // turns the column into a plain nullable INT (inserts stop
            // assigning ids after a restart).
            if let Some(col) = &meta.autoinc {
                m.insert("autoinc".into(), Value::Str(col.clone()));
            }
            // Auto-generated GUID column must survive reopen for the same
            // reason as AUTOINCREMENT.
            if let Some(col) = &meta.autoguid {
                m.insert("autoguid".into(), Value::Str(col.clone()));
            }
            if let Some(sql) = &meta.view_sql {
                m.insert("view_sql".into(), Value::Str(sql.clone()));
            }
            if !meta.unique.is_empty() {
                m.insert(
                    "unique".into(),
                    Value::Array(meta.unique.iter().map(|c| Value::Str(c.clone())).collect()),
                );
            }
            if !meta.not_null.is_empty() {
                m.insert(
                    "not_null".into(),
                    Value::Array(
                        meta.not_null
                            .iter()
                            .map(|c| Value::Str(c.clone()))
                            .collect(),
                    ),
                );
            }
            if !meta.defaults.is_empty() {
                m.insert(
                    "defaults".into(),
                    Value::Array(
                        meta.defaults
                            .iter()
                            .map(|(c, e)| {
                                Value::Array(vec![Value::Str(c.clone()), Value::Str(e.clone())])
                            })
                            .collect(),
                    ),
                );
            }
            if !meta.checks.is_empty() {
                m.insert(
                    "checks".into(),
                    Value::Array(meta.checks.iter().map(|c| Value::Str(c.clone())).collect()),
                );
            }
            if !meta.foreign_keys.is_empty() {
                m.insert(
                    "foreign_keys".into(),
                    Value::Array(
                        meta.foreign_keys
                            .iter()
                            .map(|(c, rt, rc)| {
                                Value::Array(vec![
                                    Value::Str(c.clone()),
                                    Value::Str(rt.clone()),
                                    Value::Str(rc.clone()),
                                ])
                            })
                            .collect(),
                    ),
                );
            }
            if !meta.constraint_unique.is_empty() {
                m.insert(
                    "constraint_unique".into(),
                    Value::Array(
                        meta.constraint_unique
                            .iter()
                            .map(|c| Value::Str(c.clone()))
                            .collect(),
                    ),
                );
            }
            if !meta.index_defs.is_empty() {
                m.insert(
                    "index_defs".into(),
                    Value::Array(
                        meta.index_defs
                            .iter()
                            .map(|d| {
                                let mut entry = vec![
                                    Value::Str(d.name.clone()),
                                    Value::Str(d.column().to_string()),
                                    Value::Bool(d.unique),
                                    Value::Array(
                                        d.columns.iter().map(|c| Value::Str(c.clone())).collect(),
                                    ),
                                ];
                                // 5th element only for path indexes, 6th only
                                // for partial indexes: older readers ignore
                                // the tail, so the tuple stays compatible in
                                // both directions (design 005).
                                if let Some(p) = &d.path {
                                    entry.push(Value::Str(p.clone()));
                                }
                                if let Some(p) = &d.pred {
                                    entry.push(Value::Str(p.clone()));
                                }
                                Value::Array(entry)
                            })
                            .collect(),
                    ),
                );
            }
            if !meta.index_roots.is_empty() {
                m.insert(
                    "index_roots".into(),
                    Value::Object(
                        meta.index_roots
                            .iter()
                            .map(|(c, r)| (c.clone(), Value::Int(*r as i64)))
                            .collect(),
                    ),
                );
            }
            if !meta.overflow_free.is_empty() {
                m.insert(
                    "overflow_free".into(),
                    Value::Array(
                        meta.overflow_free
                            .iter()
                            .map(|p| Value::Int(*p as i64))
                            .collect(),
                    ),
                );
            }
            if let Some(q) = &meta.matview_sql {
                m.insert("matview_sql".into(), Value::Str(q.clone()));
            }
            if meta.dotted_keys {
                m.insert("dotted_keys".into(), Value::Bool(true));
            }
            tables.insert(name.clone(), Value::Object(m));
        }
        let mut cat = Object::new();
        cat.insert("tables".into(), Value::Object(tables));
        // Row triggers: absent when none exist, so a trigger-free catalog
        // keeps its exact historical byte shape (older readers ignore the
        // key; trigger-free volumes never gain one).
        if !self.triggers.is_empty() {
            let mut ts = Object::new();
            for d in self.triggers.values() {
                ts.insert(
                    d.name.clone(),
                    Value::Object(Object::from([
                        ("table".into(), Value::Str(d.table.clone())),
                        ("before".into(), Value::Bool(d.before)),
                        ("insert".into(), Value::Bool(d.insert)),
                        ("delete".into(), Value::Bool(d.delete)),
                        ("update".into(), Value::Bool(d.update)),
                        (
                            "update_of".into(),
                            match &d.update_of {
                                Some(cols) => Value::Array(
                                    cols.iter().map(|c| Value::Str(c.clone())).collect(),
                                ),
                                None => Value::Null,
                            },
                        ),
                        (
                            "when".into(),
                            match &d.when {
                                Some(w) => Value::Str(w.clone()),
                                None => Value::Null,
                            },
                        ),
                        (
                            "body".into(),
                            Value::Array(
                                d.body
                                    .iter()
                                    .map(|a| match a {
                                        TriggerAction::Sql(text) => Value::Array(vec![
                                            Value::Str("sql".into()),
                                            Value::Str(text.clone()),
                                        ]),
                                        TriggerAction::Raise { fail, msg } => Value::Array(vec![
                                            Value::Str("raise".into()),
                                            Value::Str(msg.clone()),
                                            Value::Bool(*fail),
                                        ]),
                                    })
                                    .collect(),
                            ),
                        ),
                    ])),
                );
            }
            cat.insert("triggers".into(), Value::Object(ts));
        }
        let bytes = encode::encode_to_vec(&Value::Object(cat))?;
        self.write_catalog_pages(tx, &bytes)?;
        Ok(())
    }

    /// Walk the committed catalog chain, starting at `CATALOG_PAGE`. A page 1
    /// without the magic (a legacy single-page catalog, or an empty database)
    /// is treated as a fresh one-page chain — its content is about to be
    /// rewritten in the new format anyway.
    fn catalog_chain(&mut self) -> Result<Vec<u32>> {
        let first = self.pager.read_page(CATALOG_PAGE)?;
        if !first.starts_with(CATALOG_MAGIC) {
            return Ok(vec![CATALOG_PAGE]);
        }
        let mut chain = vec![CATALOG_PAGE];
        loop {
            let last = *chain.last().expect("seeded above");
            let page = self.pager.read_page(last)?;
            let next = u32::from_le_bytes(page[12..16].try_into().expect("header fits"));
            if next == 0 {
                return Ok(chain);
            }
            chain.push(next);
            // A damaged chain must surface as an error, not loop forever:
            // every link is a distinct page in the file.
            if chain.len() > self.pager.num_pages() as usize {
                return err("catalog chain is corrupt (cycle or dangling overflow page)");
            }
        }
    }

    /// Stage the catalog payload across its page chain inside `tx`, growing
    /// the chain by freshly allocated pages when the payload outgrew it.
    fn write_catalog_pages(&mut self, tx: &mut crate::pager::Tx, bytes: &[u8]) -> Result<()> {
        let need = bytes.len().div_ceil(CATALOG_CHUNK).max(1);
        let mut chain = self.catalog_chain()?;
        while chain.len() < need {
            let id = self.pager.allocate_page(tx)?;
            chain.push(id);
        }
        // A shrinking catalog releases its tail pages for reuse (they are no
        // longer linked into the chain the save below writes).
        for &extra in &chain[need..] {
            self.pager.free_page(tx, extra)?;
        }
        chain.truncate(need);
        for i in 0..need {
            let start = i * CATALOG_CHUNK;
            let end = (start + CATALOG_CHUNK).min(bytes.len());
            let mut page = vec![0u8; PAGE_SIZE];
            page[..8].copy_from_slice(CATALOG_MAGIC);
            if i == 0 {
                page[8..12].copy_from_slice(&(bytes.len() as u32).to_le_bytes());
            }
            let next = if i + 1 < need { chain[i + 1] } else { 0 };
            page[12..16].copy_from_slice(&next.to_le_bytes());
            page[CATALOG_HDR..CATALOG_HDR + (end - start)].copy_from_slice(&bytes[start..end]);
            self.pager.write_page(tx, chain[i], 0, &page)?;
        }
        Ok(())
    }
    fn save_catalog(&mut self) -> Result<()> {
        let mut tx = self.pager.begin_tx();
        self.save_catalog_into(&mut tx)?;
        self.commit_pager_tx(tx)?;
        Ok(())
    }

    /// Cheap catalog snapshot (Arc clones + the autoinc cache): document
    /// rollback rides the pager's page undo journal instead of a deep copy.
    fn catalog_snapshot(&self) -> TableSnapshot {
        TableSnapshot {
            tables: self.tables.clone(),
            autoinc: self.autoinc_cache.clone(),
        }
    }

    /// Restore the catalog from `snap` and replay `undo` in reverse into one
    /// commit: `Set` writes the pre-image back, `Alloc` returns the page to
    /// the reusable pool, `Free` reserves it (the restored catalog owns it
    /// again), `Realloc` needs nothing (its pre-image was recorded when the
    /// transaction freed it).
    ///
    /// Recording is paused for the replay (`pause_undo`): a replayed `Set`
    /// for a page first written after the savepoint must not treat the
    /// current dirty image as a new pre-image — that would let a later full
    /// ROLLBACK resurrect and commit the changes being rolled back here.
    /// The restored image *is* the transaction-start state, so future writes
    /// re-record it naturally.
    fn restore_transaction(
        &mut self,
        snap: TableSnapshot,
        undo: &mut [crate::pager::UndoOp],
        sync_catalog: bool,
    ) -> Result<()> {
        self.pager.pause_undo();
        let replay = || -> Result<()> {
            let mut tx = self.pager.begin_tx();
            // By index, never consuming: a mid-replay failure must leave the
            // journal intact so a retried ROLLBACK still restores the pages.
            // `into_iter()` here used to drop every op on the first error —
            // the retry then "restored" only the catalog snapshot while the
            // transaction's page images stayed applied.
            for idx in (0..undo.len()).rev() {
                match &undo[idx] {
                    crate::pager::UndoOp::Set(id, image) => {
                        self.pager.write_page(&mut tx, *id, 0, image)?;
                    }
                    crate::pager::UndoOp::Alloc(id) => {
                        self.pager.free_page(&mut tx, *id)?;
                    }
                    crate::pager::UndoOp::Free(id) => {
                        self.pager.reserve_page(*id);
                    }
                    crate::pager::UndoOp::Realloc(_) => {}
                }
            }
            // Publish AFTER durability (the mirror of COMMIT's
            // durability-first order): the restored view must be installed
            // for the catalog write below, but a failed commit reverts it —
            // otherwise the in-memory catalog leads the pager with a view
            // whose rollback never became durable, and the next
            // `save_catalog` would persist the mix.
            let prev_tables = std::mem::replace(&mut self.tables, snap.tables);
            let prev_autoinc = std::mem::replace(&mut self.autoinc_cache, snap.autoinc);
            let result = if sync_catalog {
                self.save_catalog_into(&mut tx)
                    .and_then(|_| self.commit_pager_tx(tx))
            } else {
                self.commit_pager_tx(tx)
            };
            if result.is_err() {
                self.tables = prev_tables;
                self.autoinc_cache = prev_autoinc;
            }
            result.map(|_| ())
        };
        let result = replay();
        self.pager.resume_undo();
        result
    }

    fn rollback_tx(&mut self) -> Result<ExecOutcome> {
        if self.tx_snapshot.is_none() {
            return err("no transaction in progress");
        }
        // Durability FIRST, teardown after (mirrors COMMIT above): taking
        // the snapshot before the undo-replay commit used to leave a failed
        // ROLLBACK wedged — retry hit "no transaction in progress" while
        // the engine held neither the rolled-back pages nor a consistent
        // catalog. On failure the transaction stays open and the error is
        // loud; teardown only runs once the restore is durable.
        // Take the journal only AFTER the deferred commits are voided:
        // abort_deferred failing (I/O error on the ABORT append) used to
        // drop the just-taken undo journal — a retried ROLLBACK then found
        // an empty journal and "succeeded" after restoring nothing but the
        // in-memory catalog, leaving the transaction's page images applied.
        // 先把本事务各语句的 deferred 提交显式作废:没有这组 ABORT 帧,
        // 恢复事务的同步提交会先落 FENCE,撕裂崩溃停在「FENCE 已持久、
        // 恢复事务 COMMIT 未持久」窗口时,整个已回滚事务会复活。
        self.pager.abort_deferred()?;
        let mut undo = self.pager.take_undo();
        let snap = self
            .tx_snapshot
            .clone()
            .expect("checked above; single writer keeps it in place");
        if let Err(e) = self.restore_transaction(snap, &mut undo, true) {
            // Put the journal back: the transaction stays open and the
            // retry must replay the same ops, not an empty tail.
            self.pager.restore_undo_journal(undo);
            return Err(e);
        }
        let _ = self.tx_snapshot.take();
        self.savepoints.clear();
        // The restore transaction committed DEFERRED (the snapshot was still
        // in place during it): fence + fsync now. ROLLBACK is a terminal
        // statement — no later COMMIT exists to trigger the WAL cap — so
        // without this a BEGIN/INSERT/ROLLBACK workload grew the log and
        // pending_writes without bound. The fence is also the durability
        // boundary for the undo-replayed page images. On failure the error
        // is loud and a retried ROLLBACK is idempotent (the undo journal is
        // empty by then; the catalog is already at the snapshot state).
        self.pager.sync_wal()?;
        Ok(ExecOutcome::Affected(0))
    }

    /// SAVEPOINT name: mark the current transaction state so a later
    /// ROLLBACK TO can restore it (the transaction stays open). Holds Arc
    /// pointers plus a journal mark — cost is O(tables), not O(database).
    /// Capped so a savepoint flood cannot pin unbounded journal memory.
    fn savepoint(&mut self, name: &str) -> Result<ExecOutcome> {
        const MAX_SAVEPOINTS: usize = 64;
        if self.tx_snapshot.is_none() {
            return err("SAVEPOINT requires an active transaction");
        }
        if self.savepoints.len() >= MAX_SAVEPOINTS {
            return err(format!(
                "too many savepoints (max {MAX_SAVEPOINTS}); release or roll back some first"
            ));
        }
        let snap = self.catalog_snapshot();
        // Mark BEFORE the baseline images: the tail a later ROLLBACK TO
        // replays must include them.
        let mark = self.pager.undo_mark();
        self.pager.undo_savepoint()?;
        self.savepoints.push((name.to_string(), snap, mark));
        Ok(ExecOutcome::Affected(0))
    }

    /// RELEASE SAVEPOINT name: forget the savepoint (changes stay). With
    /// duplicate names the most recent one is released (SQLite semantics).
    fn release_savepoint(&mut self, name: &str) -> Result<ExecOutcome> {
        let Some(pos) = self.savepoints.iter().rposition(|(n, _, _)| n == name) else {
            return err(format!("savepoint {name} does not exist"));
        };
        self.savepoints.truncate(pos);
        Ok(ExecOutcome::Affected(0))
    }

    /// ROLLBACK TO SAVEPOINT name: restore that savepoint's state; the
    /// outer transaction continues and later savepoints are discarded.
    /// The named savepoint itself is discarded too (a documented divergence
    /// from SQLite/PG, pinned by duplicate_savepoint_names_resolve_to_newest:
    /// a second ROLLBACK TO the same name resolves to the OLDER same-named
    /// savepoint, not an error).
    fn rollback_to_savepoint(&mut self, name: &str) -> Result<ExecOutcome> {
        let Some(pos) = self.savepoints.iter().rposition(|(n, _, _)| n == name) else {
            return err(format!("savepoint {name} does not exist"));
        };
        let snap = self.savepoints[pos].1.clone();
        let mark = self.savepoints[pos].2;
        self.savepoints.truncate(pos);
        let mut undo = self.pager.take_undo_to(mark);
        // The transaction stays open: no catalog save is needed (the journal
        // replay already restored the catalog pages; the in-memory map comes
        // from the snapshot). `sync_catalog=false` keeps this cheap.
        if let Err(e) = self.restore_transaction(snap, &mut undo, false) {
            // Reattach the tail: a failed ROLLBACK TO must leave the journal
            // whole for the retry (and a later full ROLLBACK), exactly like
            // the full-ROLLBACK path.
            self.pager.reattach_undo_tail(undo);
            return Err(e);
        }
        Ok(ExecOutcome::Affected(0))
    }

    /// True when the statement mutates data (used by replicas to reject
    /// client writes while accepting replicated ones).
    pub fn is_write_statement(sql: &str) -> bool {
        match Parser::parse_sql(&GenericDialect {}, sql) {
            Ok(stmts) => match stmts.first() {
                Some(stmt) => Self::stmt_is_write(stmt),
                // An empty batch writes nothing.
                None => false,
            },
            Err(_) => true,
        }
    }

    /// Write classification of an already-parsed statement: everything
    /// except queries, PRAGMA shims and session-local transaction control
    /// mutates data (transaction control replicates only its inner data
    /// statements, never BEGIN/COMMIT/ROLLBACK themselves).
    fn stmt_is_write(stmt: &Statement) -> bool {
        !matches!(
            stmt,
            Statement::Query(_)
                | Statement::Explain { .. }
                | Statement::Pragma { .. }
                | Statement::StartTransaction { .. }
                | Statement::Commit { .. }
                | Statement::Rollback { .. }
                | Statement::Savepoint { .. }
                | Statement::ReleaseSavepoint { .. }
        )
    }

    /// Table names a mutating statement writes to (its targets, not the
    /// tables it merely reads in a subquery). The server's system-table
    /// gate classifies on this instead of a substring scan, so a user
    /// write that merely MENTIONS a system table in a literal is not
    /// rejected while any write aimed at one still is.
    /// Tables declaring a FOREIGN KEY into any of `targets` (one closure
    /// step; callers iterate for transitivity). Authorization input for
    /// `TRUNCATE ... CASCADE`, whose execution clears the FK children —
    /// those children must be authorization input too.
    pub fn table_foreign_keys_of(&self, targets: &[String]) -> Vec<String> {
        self.tables
            .iter()
            .filter(|(t, m)| {
                !targets.contains(t) && m.foreign_keys.iter().any(|(_, rt, _)| targets.contains(rt))
            })
            .map(|(t, _)| t.clone())
            .collect()
    }

    pub fn stmt_write_targets(stmt: &Statement) -> Vec<String> {
        fn factor_name(factor: &sqlparser::ast::TableFactor) -> Option<String> {
            match factor {
                sqlparser::ast::TableFactor::Table { name, .. } => Some(obj_name(name)),
                _ => None,
            }
        }
        match stmt {
            Statement::Insert(insert) => match &insert.table {
                TableObject::TableName(n) => vec![obj_name(n)],
                _ => vec![],
            },
            Statement::Merge(m) => factor_name(&m.table).into_iter().collect(),
            Statement::Update(u) => factor_name(&u.table.relation).into_iter().collect(),
            Statement::Delete(d) => match &d.from {
                sqlparser::ast::FromTable::WithFromKeyword(tables) => tables
                    .iter()
                    .filter_map(|t| factor_name(&t.relation))
                    .collect(),
                sqlparser::ast::FromTable::WithoutKeyword(tables) => tables
                    .iter()
                    .filter_map(|t| factor_name(&t.relation))
                    .collect(),
            },
            Statement::CreateTable(create) => vec![obj_name(&create.name)],
            Statement::CreateView(view) => vec![obj_name(&view.name)],
            Statement::CreateIndex(idx) => vec![obj_name(&idx.table_name)],
            Statement::Drop { names, .. } => names.iter().map(obj_name).collect(),
            Statement::AlterTable(alter) => {
                let mut out = vec![obj_name(&alter.name)];
                for op in &alter.operations {
                    if let sqlparser::ast::AlterTableOperation::RenameTable { table_name } = op {
                        match table_name {
                            sqlparser::ast::RenameTableNameKind::As(n)
                            | sqlparser::ast::RenameTableNameKind::To(n) => out.push(obj_name(n)),
                        }
                    }
                }
                out
            }
            Statement::Truncate(tr) => tr.table_names.iter().map(|t| obj_name(&t.name)).collect(),
            _ => vec![],
        }
    }

    /// Transaction-control classification of an already-parsed statement.
    fn classify_tx(stmt: &Statement) -> TxControl {
        match stmt {
            Statement::StartTransaction { .. } => TxControl::Begin,
            Statement::Commit { .. } => TxControl::Commit,
            Statement::Rollback { savepoint, .. } => TxControl::Rollback {
                savepoint: savepoint.as_ref().map(|i| i.value.clone()),
            },
            Statement::Savepoint { name } => TxControl::Savepoint(name.value.clone()),
            Statement::ReleaseSavepoint { name } => TxControl::Release(name.value.clone()),
            _ => TxControl::None,
        }
    }

    /// Base tables a view's body reads (one level). `None` when `name` is
    /// not a view or the body cannot be classified — authorization callers
    /// must fail closed on None. Views are a SELECT permission boundary
    /// (a grant on the view hides its bases), but a write reading THROUGH
    /// a view still needs the base grants.
    /// True when the named catalog object is a view (view definition
    /// present). Missing objects are not views.
    pub fn object_is_view(&self, name: &str) -> bool {
        self.tables.get(name).is_some_and(|m| m.is_view())
    }

    pub fn view_base_tables(&self, name: &str) -> Option<Vec<String>> {
        let meta = self.tables.get(name)?;
        let sql = meta.view_sql.as_ref()?;
        let mut stmts = Parser::parse_sql(&GenericDialect {}, sql).ok()?;
        let stmt = stmts.swap_remove(0);
        let objects = |n: &str| self.tables.contains_key(n);
        let mut out = Vec::new();
        match stmt {
            Statement::Query(q) => walk_query(&q, &mut out, &objects)?,
            _ => return None,
        }
        Some(out)
    }

    /// Views whose bodies directly read any of `targets` (one level).
    /// Unparseable bodies contribute no edge — the CREATE would have
    /// failed, and a corrupt catalog must not turn DROP into a panic.
    fn direct_view_dependents(&self, targets: &[String]) -> Vec<String> {
        self.tables
            .iter()
            .filter(|(n, m)| m.is_view() && !targets.contains(n))
            .filter(|(n, _)| {
                self.view_base_tables(n)
                    .is_some_and(|bases| bases.iter().any(|b| targets.contains(b)))
            })
            .map(|(n, _)| n.clone())
            .collect()
    }

    /// Expand a DROP target list with dependent views. Without CASCADE a
    /// dependent refuses the drop — the old code dropped the base object
    /// and left the view dangling, failing only when someone SELECTed it.
    /// With CASCADE the dependents join the drop set transitively (views
    /// form a DAG), so restoring the schema order is never needed.
    fn expand_view_dependents(&self, targets: &mut Vec<String>, cascade: bool) -> Result<()> {
        loop {
            let deps = self.direct_view_dependents(targets);
            if deps.is_empty() {
                return Ok(());
            }
            if !cascade {
                return err(format!(
                    "cannot drop {}: referenced by VIEW {} \
                     (drop the view first or use CASCADE)",
                    targets.join(", "),
                    deps.join(", ")
                ));
            }
            targets.extend(deps);
        }
    }

    /// Tables a statement READS (authorization input for user connections):
    /// every table referenced in a query's FROM/JOINs (derived tables and
    /// subqueries included — inside CTE bodies, projections and predicates
    /// too), the source of an INSERT ... SELECT, the tables read by a
    /// write's expressions (UPDATE assignment subqueries, MERGE WHEN
    /// predicates, aggregate FILTER conditions) and a CTAS/CREATE VIEW
    /// source query. Fails CLOSED: a query shape the walker cannot fully
    /// classify returns `None`, and the caller must deny rather than guess.
    pub fn stmt_read_targets(
        stmt: &Statement,
        objects: &dyn Fn(&str) -> bool,
    ) -> Option<Vec<String>> {
        let mut out = Self::stmt_read_target_occurrences(stmt, objects)?;
        out.sort();
        out.dedup();
        Some(out)
    }

    /// Same walk as [`Self::stmt_read_targets`] WITHOUT sort+dedup: the
    /// row-filter coverage proof counts DEEP occurrences per appearance —
    /// a filtered table read twice (outer FROM + a subquery) must count
    /// twice, but the deduped set collapsed it to one and made deep ==
    /// top, letting the subquery position escape filtering entirely.
    pub fn stmt_read_target_occurrences(
        stmt: &Statement,
        objects: &dyn Fn(&str) -> bool,
    ) -> Option<Vec<String>> {
        let mut out = Vec::new();
        match stmt {
            Statement::Query(q) => walk_query(q, &mut out, objects)?,
            // EXPLAIN reads exactly what its inner query reads (fail-closed
            // on any inner shape the walker cannot classify).
            Statement::Explain { statement, .. } => match statement.as_ref() {
                Statement::Query(q) => walk_query(q, &mut out, objects)?,
                _ => return None,
            },
            Statement::Insert(insert) => {
                if let Some(source) = &insert.source {
                    walk_query(source, &mut out, objects)?;
                }
            }
            Statement::Update(u) => {
                // Assignment values may carry subqueries (`SET v =
                // (SELECT pw FROM docsql_users …)`); exec_update
                // substitutes and evaluates them, so they are reads.
                for a in &u.assignments {
                    walk_expr(&a.value, &mut out, objects)?;
                }
                // The update target itself is a WRITE target; extra FROM
                // tables are reads.
                if let Some(kind) = &u.from {
                    let list = match kind {
                        sqlparser::ast::UpdateTableFromKind::BeforeSet(v)
                        | sqlparser::ast::UpdateTableFromKind::AfterSet(v) => v,
                    };
                    for twj in list {
                        walk_factor(&twj.relation, &mut out, objects)?;
                    }
                }
                if let Some(sel) = &u.selection {
                    walk_expr(sel, &mut out, objects)?;
                }
            }
            Statement::Delete(d) => {
                // USING tables are reads; the delete targets come from
                // stmt_write_targets.
                if let Some(using) = &d.using {
                    for twj in using {
                        walk_factor(&twj.relation, &mut out, objects)?;
                    }
                }
                if let Some(sel) = &d.selection {
                    walk_expr(sel, &mut out, objects)?;
                }
            }
            Statement::Merge(m) => {
                // The USING side is a read; the merge target comes from
                // stmt_write_targets. ON/assignments referencing the target
                // are writes, not reads. WHEN predicates are evaluated per
                // row and may carry subqueries — walk them too.
                walk_factor(&m.source, &mut out, objects)?;
                for clause in &m.clauses {
                    if let Some(pred) = &clause.predicate {
                        walk_expr(pred, &mut out, objects)?;
                    }
                }
            }
            Statement::CreateTable(create) => {
                // CTAS: the source query executes at creation time and is
                // authorization input (the admin-only DDL gate shadows this
                // today, but the classification must stay honest).
                if let Some(q) = &create.query {
                    walk_query(q, &mut out, objects)?;
                }
            }
            Statement::CreateView(view) => walk_query(&view.query, &mut out, objects)?,
            _ => {}
        }
        Some(out)
    }

    /// Parse a single statement once and classify it in the same pass: the
    /// AST feeds [`Database::execute_parsed`], the flags route the request
    /// (write path, transaction control) without re-parsing the text.
    /// User-management statements are hand-parsed first (sqlparser 0.62
    /// rejects their grammar) and always classify as writes.
    ///
    /// Results go through the process-wide statement cache: parsing is pure
    /// syntax — nothing catalog- or connection-dependent — so entries never
    /// go stale and no invalidation exists to get wrong. Every tier parses
    /// through here (write path, MVCC read views, routing probes), so a
    /// repeated point query skips the ~4 µs sqlparser pass.
    pub fn parse_classified(sql: &str) -> Result<ParsedStatement> {
        const CACHE_MAX_SQL: usize = 4096;
        const CACHE_ENTRIES: usize = 256;
        const SEEN_CAP: usize = 1024;
        let cacheable = sql.len() <= CACHE_MAX_SQL;
        if cacheable {
            let hit = stmt_cache()
                .lock()
                .unwrap_or_else(|p| p.into_inner())
                .get(sql)
                .cloned();
            if let Some(parsed) = hit {
                return Ok(parsed);
            }
        }
        let parsed = Self::parse_classified_uncached(sql)?;
        // User-management statements carry the plaintext password in the AST
        // (the resolved hash rewrite happens at execution): caching them
        // would pin credentials in process-wide memory beyond the statement
        // and outlive the "plaintext never leaves the executing path"
        // contract.
        let cacheable = cacheable && !matches!(parsed.stmt, AnyStmt::UserAdmin(_));
        if cacheable {
            // Second-sight gate: pay the cache-write cost (an AST clone)
            // only for text seen before, so distinct-literal workloads —
            // per-row generated lookups, rendered bindings — skip it. The
            // u64 hash is a heuristic only: a false positive merely writes
            // the cache early (the cache key is the exact text, so
            // correctness never depends on the hash), a false negative
            // just delays caching by one sight.
            let mut seen = stmt_seen().lock().unwrap_or_else(|p| p.into_inner());
            let mut hasher = std::collections::hash_map::DefaultHasher::new();
            sql.hash(&mut hasher);
            let h = hasher.finish();
            if seen.contains(&h) {
                drop(seen);
                let mut cache = stmt_cache().lock().unwrap_or_else(|p| p.into_inner());
                if cache.len() >= CACHE_ENTRIES {
                    cache.clear();
                }
                cache.insert(sql.to_string(), parsed.clone());
            } else {
                if seen.len() >= SEEN_CAP {
                    seen.clear();
                }
                seen.insert(h);
            }
        }
        Ok(parsed)
    }

    /// The uncached parse behind [`Self::parse_classified`].
    fn parse_classified_uncached(sql: &str) -> Result<ParsedStatement> {
        // REFRESH MATERIALIZED VIEW [CONCURRENTLY] name — the generic
        // dialect has no REFRESH statement; hand-parse the fixed shape
        // (same pattern as the user-management statements).
        {
            let up = sql.trim_start().to_ascii_uppercase();
            let body = up
                .strip_prefix("REFRESH MATERIALIZED VIEW ")
                .or_else(|| up.strip_prefix("REFRESH MATERIALIZED VIEW	"));
            if let Some(rest) = body {
                let mut parts = rest.split_ascii_whitespace();
                let mut name_part = parts.next().unwrap_or("");
                if name_part == "CONCURRENTLY" {
                    // PG's CONCURRENTLY needs a unique index to delta-apply;
                    // this engine rewrites wholesale — accept and ignore.
                    name_part = parts.next().unwrap_or("");
                }
                if parts.next().is_some() || name_part.is_empty() {
                    return err("REFRESH MATERIALIZED VIEW takes exactly one view name");
                }
                // Recover the original spelling from the source text: the
                // name is the last token of the statement (after the
                // optional CONCURRENTLY).
                let tokens: Vec<&str> = sql.trim().split_ascii_whitespace().collect();
                let name = tokens
                    .last()
                    .copied()
                    .unwrap_or("")
                    .trim_end_matches(';')
                    .to_string();
                if name.is_empty()
                    || !name
                        .chars()
                        .next()
                        .map(|c| c.is_alphanumeric() || c == '_' || c == '"' || c == '#')
                        .unwrap_or(false)
                {
                    return err("REFRESH MATERIALIZED VIEW takes exactly one view name");
                }
                return Ok(ParsedStatement {
                    stmt: AnyStmt::RefreshMatview(name),
                    tx: TxControl::None,
                    is_write: true,
                    source: sql.to_string(),
                });
            }
        }
        match crate::useradmin::parse(sql) {
            Some(Ok(ua)) => {
                return Ok(ParsedStatement {
                    stmt: AnyStmt::UserAdmin(ua),
                    tx: TxControl::None,
                    is_write: true,
                    source: sql.to_string(),
                })
            }
            Some(Err(m)) => return err(m),
            None => {}
        }
        // T-SQL notations the generic parser cannot express ([brackets],
        // CONVERT/PARSE argument order, SET/USE/PRINT shims) are rewritten
        // on a text copy; `source` keeps the original text so journals and
        // logs carry what the user wrote (the rewrite is deterministic and
        // re-applies on every replay).
        let parsed_sql = crate::tsql::preprocess(sql);
        let parsed_sql = parsed_sql.as_str();
        let mut stmts = Parser::parse_sql(&GenericDialect {}, parsed_sql)
            .map_err(|e| SqlError::Parse(e.to_string()))?;
        let stmt = match stmts.len() {
            0 => return err("empty statement"),
            1 => stmts.swap_remove(0),
            _ => return err("exactly one statement per execute() call"),
        };
        let tx = Self::classify_tx(&stmt);
        let is_write = Self::stmt_is_write(&stmt);
        Ok(ParsedStatement {
            stmt: AnyStmt::Sql(Box::new(stmt)),
            tx,
            is_write,
            source: sql.to_string(),
        })
    }

    /// True when the catalog holds a table with this exact name.
    pub fn table_exists(&self, name: &str) -> bool {
        self.tables.contains_key(name)
    }

    /// ASCII-case-insensitive catalog probe: the server-side compat-view
    /// rewrites (docsql_pubsub / docsql_log) must not shadow a user table
    /// under ANY spelling of the name — an exact-only probe let
    /// `DocSQL_PubSub` INSERT land in the real table while the SELECT was
    /// silently rewritten onto the system view.
    pub fn table_exists_ci(&self, name: &str) -> bool {
        self.tables
            .keys()
            .any(|k| k.len() == name.len() && k.eq_ignore_ascii_case(name))
    }

    /// Arm the cooperative deadline for the statement about to execute
    /// (server-side statement timeout). Engine-global, not per connection:
    /// the caller MUST clear it (`set_statement_deadline(None)`) once the
    /// statement finished, on every path.
    pub fn set_statement_deadline(&self, deadline: Option<std::time::Instant>) {
        self.stmt_deadline.set(deadline);
    }

    /// True when a session transaction is open.
    pub fn in_transaction(&self) -> bool {
        self.tx_snapshot.is_some()
    }

    /// Build a guardless read view (MVCC stage B): clones the catalog as
    /// `Arc` bumps and begins a pager snapshot at the current commit head.
    /// The caller must hold *a* database lock while calling this; the view
    /// is executed after the guard is released, so long SELECTs never block
    /// writers. Dropping the view ends the snapshot.
    pub fn read_view(&self) -> ReadView {
        ReadView {
            pager: self.pager.clone(),
            catalog: CatalogSnapshot(self.tables.clone()),
            deadline: std::sync::Arc::new(StmtDeadline::default()),
            snap: self.pager.begin_snapshot(),
        }
    }

    /// Borrowed read context under the current lock: current visibility,
    /// no snapshot. Write paths and the census use this to share the SELECT
    /// chain with the guardless stage-B views.
    pub(crate) fn read_cx(&self) -> ReadCx<'_> {
        ReadCx {
            pager: &self.pager,
            tables: &self.tables,
            deadline: &self.stmt_deadline,
            snap: None,
        }
    }

    /// The plain-SELECT gate shared by both read paths (stage A
    /// [`Database::execute_read`] and stage B [`ReadView::execute`]):
    /// writes, transaction control and WITH queries are refused — the
    /// server tiers them to the write lock (WITH materialization is
    /// statement-local mutable state). Returns the query to execute.
    fn plain_read_query(parsed: &ParsedStatement) -> Result<Query> {
        if parsed.is_write {
            return err("read path refused a write statement");
        }
        if parsed.tx != TxControl::None {
            return err("read path refused a transaction statement");
        }
        match &parsed.stmt {
            AnyStmt::Sql(stmt) => match &**stmt {
                Statement::Query(q) if q.with.is_none() => Ok((**q).clone()),
                Statement::Query(_) => err("read path: WITH queries must use the write path"),
                _ => err("read path: statement is not a query"),
            },
            _ => err("read path: statement is not a query"),
        }
    }

    /// Read-only execution path (MVCC stage A): plain SELECT only, callable
    /// on `&Database` under the server's read lock so read-only statements
    /// run concurrently. Guardless reads (stage B) go through
    /// [`Database::read_view`] instead.
    ///
    /// No statement deadline here: this path shares the engine-global slot
    /// the write path arms (a concurrent arming would be overwritten), so
    /// stage-A reads are not preemptible. Stage-B views carry their own
    /// deadline (see `ReadView::set_statement_deadline`).
    pub fn execute_read(&self, sql: &str) -> Result<ExecOutcome> {
        let q = Self::plain_read_query(&Self::parse_classified(sql)?)?;
        self.exec_query_cx(q)
    }

    // Write-path shims: run the shared SELECT-chain helpers under a borrowed
    // context (current visibility — the write lock already excludes snapshot
    // readers from mutating anything mid-statement).
    /// Mutable catalog entry for the write path: `Arc::make_mut` deep-clones
    /// the meta only while a detached stage-B reader still holds the previous
    /// version (a concurrent long SELECT); single-writer idle runs mutate in
    /// place exactly as before.
    fn catalog_mut(&mut self, name: &str) -> Option<&mut TableMeta> {
        match self.tables.get_mut(name) {
            Some(a) => Some(std::sync::Arc::make_mut(a)),
            None => None,
        }
    }

    /// Feed every NEW document image a write statement produced: the first
    /// literal dotted field name ("a.b" as ONE key) sticks the table's
    /// `dotted_keys` marker (see TableMeta). Returns true when the marker
    /// was just set — callers fold that into their layout-sync condition so
    /// the marker reaches the catalog in the same transaction.
    fn note_dotted_fields<'a>(
        &mut self,
        table: &str,
        mut docs: impl Iterator<Item = &'a Object>,
    ) -> bool {
        if self.tables.get(table).is_some_and(|m| m.dotted_keys) {
            return false;
        }
        if !docs.any(|d| d.keys().any(|k| k.contains('.'))) {
            return false;
        }
        if let Some(m) = self.catalog_mut(table) {
            m.dotted_keys = true;
            return true;
        }
        false
    }

    pub(crate) fn table_docs_cx(&self, table: &str) -> Result<Vec<Object>> {
        self.read_cx().table_docs(table)
    }
    fn table_pairs_cx(&self, table: &str) -> Result<Vec<(u64, Object)>> {
        self.read_cx().table_pairs(table)
    }
    /// Write-path pre-pass with the outer scope of the target statement
    /// (UPDATE/DELETE target + FROM/USING tables): correlated subqueries on
    /// row-local surfaces (WHERE, SET) stay in place for per-row evaluation.
    fn subst_expr_cx_scoped(&self, e: &mut SqlExpr, outer: &OuterFrom) -> Result<()> {
        self.read_cx().subst_expr_scoped(e, outer, true)
    }
    fn index_probe_cx(
        &self,
        table: &str,
        alias: Option<&str>,
        selection: &Option<SqlExpr>,
        ctes: &Ctes,
    ) -> Result<Option<Vec<(u64, Object)>>> {
        self.read_cx().index_probe(table, alias, selection, ctes)
    }
    fn matches_cx_in(
        &self,
        selection: &Option<SqlExpr>,
        doc: &Object,
        outer: &OuterFrom,
    ) -> Result<bool> {
        self.read_cx().matches_in(selection, doc, outer)
    }
    /// [`eval_assignments`] with correlated-subquery support: SET values
    /// still holding subquery nodes resolve their outer references per row.
    fn eval_assignments_cx(
        &self,
        assignments: &[sqlparser::ast::Assignment],
        doc: &Object,
        outer: &OuterFrom,
    ) -> Result<Vec<(String, Value)>> {
        if !assignments.iter().any(|a| expr_has_subquery(&a.value)) {
            return eval_assignments(assignments, doc);
        }
        let mut subst = assignments.to_vec();
        for a in &mut subst {
            self.read_cx().subst_expr_row(&mut a.value, doc, outer)?;
        }
        eval_assignments(&subst, doc)
    }
    fn load_from_cx(
        &self,
        from: &[sqlparser::ast::TableWithJoins],
        selection: &Option<SqlExpr>,
        ctes: &Ctes,
    ) -> Result<Vec<Object>> {
        self.read_cx().load_from(from, selection, ctes)
    }
    fn exec_query_cx(&self, query: Query) -> Result<ExecOutcome> {
        self.read_cx().exec_query(query)
    }

    /// Execute exactly one SQL statement.
    pub fn execute(&mut self, sql: &str) -> Result<ExecOutcome> {
        match Self::parse_classified(sql) {
            Ok(parsed) => self.execute_parsed(parsed),
            Err(e) => Err(e),
        }
    }

    /// Execute an already-parsed statement — the parse-once path servers
    /// use after [`Database::parse_classified`] routed the request.
    pub fn execute_parsed(&mut self, parsed: ParsedStatement) -> Result<ExecOutcome> {
        self.resolved_sql = None;
        self.last_insert_id = None;
        // Wall-clock fold (journaled-write red line): a write carrying
        // NOW()/SYSDATE()/CURRENT_TIMESTAMP resolves the instant ONCE here
        // and ships the literal through resolved_sql — a replica replaying
        // the text would stamp its own clock and silently diverge. The
        // re-parsed statement carries the folded literal, so the INSERT
        // canonical rewrite below (if any) renders folded values too.
        //
        // Exception — statements that only DECLARE future behavior (plain
        // CREATE TABLE / ALTER): folding `DEFAULT NOW()` would freeze the
        // DDL-time instant into every future row. The call text stays; at
        // INSERT time exec_insert resolves the instant per row and rewrites
        // the journaled INSERT with explicit values (the auto-GUID
        // mechanism). CTAS still folds — its query is row data created now.
        if parsed.is_write && crate::stmt::mentions_wall_clock(&parsed.source) {
            let declares_defaults = match &parsed.stmt {
                AnyStmt::Sql(stmt) => match stmt.as_ref() {
                    Statement::CreateTable(create) => create.query.is_none(),
                    Statement::AlterTable(_) => true,
                    // A MATERIALIZED view stores the query text and replays
                    // it at REFRESH: the fold would freeze one instant into
                    // every future refresh, silently changing the semantics.
                    // The determinism gate in exec_create_matview refuses
                    // the raw call instead.
                    Statement::CreateView(v) if v.materialized => true,
                    _ => false,
                },
                _ => false,
            };
            if !declares_defaults {
                if let Some(folded) =
                    crate::stmt::fold_wall_clocks(&parsed.source, crate::now_ms() as i64)
                {
                    let reparsed = Self::parse_classified(&folded)?;
                    let outcome = self.execute_parsed(reparsed)?;
                    if self.resolved_sql.is_none() {
                        self.resolved_sql = Some(folded);
                    }
                    return Ok(outcome);
                }
            }
        }
        // T-SQL wall clocks are per-STATEMENT on the READ path too: the
        // scalar arm re-samples now_ms() per call site, so every row (and
        // two GETDATE()s in one projection) drifted across the scan. Fold
        // reads exactly like RAND below — one instant per statement.
        if !parsed.is_write && crate::stmt::mentions_wall_clock(&parsed.source) {
            if let Some(folded) =
                crate::stmt::fold_wall_clocks(&parsed.source, crate::now_ms() as i64)
            {
                let reparsed = Self::parse_classified(&folded)?;
                return self.execute_parsed(reparsed);
            }
        }
        // T-SQL RAND(): evaluated ONCE per statement — every row of the
        // result sees the same value. Reads (and CTAS, whose query is row
        // data created now) fold the calls into one literal before
        // executing; other writes keep the call in the text so exec_insert's
        // rewrite ships resolved values and UPDATE/DELETE/MERGE keep their
        // loud refusal below.
        let is_ctas = matches!(
            &parsed.stmt,
            AnyStmt::Sql(s) if matches!(
                s.as_ref(),
                Statement::CreateTable(c) if c.query.is_some()
            )
        );
        if (!parsed.is_write || is_ctas) && crate::stmt::mentions_nondet_call(&parsed.source) {
            let lit = crate::engine::value_literal(&crate::value::Value::Float(
                crate::tsql::rand_unit(),
            ))?;
            if let Some(folded) = crate::stmt::fold_rand_calls(&parsed.source, &lit) {
                let reparsed = Self::parse_classified(&folded)?;
                let outcome = self.execute_parsed(reparsed)?;
                if is_ctas && self.resolved_sql.is_none() {
                    self.resolved_sql = Some(folded);
                }
                return Ok(outcome);
            }
        }
        // NEWID()/NEWSEQUENTIALID() in writes: only INSERT has the canonical
        // per-row rewrite that ships generated ids as literals (exec_insert).
        // UPDATE/DELETE/MERGE journal their original text, so a random id
        // there would be re-rolled on every replaying peer — refuse loudly.
        // AST-level: a substring scan over the source would match the words
        // inside string literals ('x-newid-y') and unrelated identifiers
        // (a column named newid), rejecting perfectly legal writes.
        if parsed.is_write {
            if let AnyStmt::Sql(stmt) = &parsed.stmt {
                if stmt_calls_newid(stmt) {
                    return err(
                        "NEWID()/NEWSEQUENTIALID()/RAND() are only supported in SELECT and INSERT",
                    );
                }
            }
        }
        match parsed.stmt {
            AnyStmt::Sql(stmt) => self.exec_stmt(*stmt),
            AnyStmt::UserAdmin(ua) => self.exec_user_admin(&ua),
            AnyStmt::RefreshMatview(name) => self.exec_refresh_matview(&name),
        }
    }

    /// Parse-check a statement batch without executing anything (the web
    /// console's "parse" button).
    pub fn parse_check(sql: &str) -> std::result::Result<(), String> {
        match crate::useradmin::parse(sql) {
            Some(Ok(_)) => Ok(()),
            Some(Err(m)) => Err(m),
            None => match Parser::parse_sql(&GenericDialect {}, &crate::tsql::preprocess(sql)) {
                Ok(stmts) if !stmts.is_empty() => Ok(()),
                Ok(_) => Err("empty statement".into()),
                Err(e) => Err(e.to_string()),
            },
        }
    }

    /// Execute every statement in `sql`, in order, stopping at the first
    /// error. Successfully executed prefixes are still reported so callers
    /// (e.g. the web console) can render partial results. Splitting first
    /// lets a batch mix plain SQL with the hand-parsed user-management
    /// statements (join snapshots and backups embed them).
    pub fn execute_batch(&mut self, sql: &str) -> BatchResult {
        let parts = match crate::stmt::split_statements(sql) {
            Ok(p) => p,
            Err(m) => {
                return BatchResult {
                    statements: 0,
                    outcomes: vec![],
                    error: Some(BatchError {
                        statement: 0,
                        message: m,
                    }),
                }
            }
        };
        let statements = parts.len();
        let mut outcomes = Vec::new();
        for (i, part) in parts.into_iter().enumerate() {
            match self.execute(&part) {
                Ok(o) => outcomes.push(o),
                Err(e) => {
                    return BatchResult {
                        statements,
                        outcomes,
                        error: Some(BatchError {
                            statement: i,
                            message: e.to_string(),
                        }),
                    }
                }
            }
        }
        BatchResult {
            statements,
            outcomes,
            error: None,
        }
    }

    /// Take the canonical rewrite of the last statement: the auto-GUID
    /// INSERT rewrite or the canonical user-management form (password in
    /// stored-hash form). Replicating callers replace the original
    /// statement text with this one so peers apply the exact same values.
    pub fn take_resolved_sql(&mut self) -> Option<String> {
        self.resolved_sql.take()
    }

    /// Publish the canonical rewrite of the executing statement (used by
    /// the user-management family; auto-GUID INSERTs write the field
    /// directly inside `exec_insert`).
    pub(crate) fn set_resolved_sql(&mut self, sql: String) {
        self.resolved_sql = Some(sql);
    }

    /// AUTOINCREMENT id the last INSERT assigned (max over inserted rows,
    /// explicit values included; None when the last statement was not an
    /// inserting one or the table has no AUTOINCREMENT column). The
    /// statement-scoped readback avoids a second `SELECT MAX(id)` — a full
    /// heap scan — on every insert-and-learn-the-id caller.
    pub fn last_insert_id(&self) -> Option<i64> {
        self.last_insert_id
    }

    /// Current MAX(id) of a table's AUTOINCREMENT column via the counter
    /// cache: O(1) warm, one heap scan when an UPDATE/DELETE/restart
    /// invalidated it. None when the table is unknown or has no
    /// AUTOINCREMENT column — callers fall back to the SQL aggregate.
    pub fn max_autoinc(&mut self, table: &str) -> Option<i64> {
        let meta = self.tables.get(table)?.clone();
        meta.autoinc.as_ref()?;
        self.autoinc_next_for(table, &meta).ok()?;
        self.autoinc_cache.get(table).map(|next| next - 1)
    }

    /// PRIMARY KEY / UNIQUE constraint indexes as named entries,
    /// SQLite-style: `sqlite_autoindex_<table>_<n>`, PK column first.
    /// Derived from table-declared constraints only — columns that got a
    /// UNIQUE index through CREATE INDEX already have a named definition —
    /// and never written to the catalog, so already-deployed databases
    /// gain them on upgrade with no migration, and the names are identical
    /// on every peer (recomputed from the replicated DDL).
    fn autoindex_defs(table: &str, meta: &TableMeta) -> Vec<IndexInfo> {
        let mut cols: Vec<&String> = Vec::new();
        for c in meta.primary_key.iter().chain(meta.constraint_unique.iter()) {
            if !cols.contains(&c) {
                cols.push(c);
            }
        }
        cols.into_iter()
            .enumerate()
            .map(|(i, c)| IndexInfo {
                name: format!("sqlite_autoindex_{table}_{}", i + 1),
                column: (*c).clone(),
                columns: vec![(*c).clone()],
                unique: true,
                auto: true,
                pred: None,
            })
            .collect()
    }

    /// Read-only catalog snapshot for tooling (object explorer, drivers).
    pub fn catalog(&self) -> Vec<TableInfo> {
        self.tables
            .iter()
            .map(|(name, meta)| {
                let auto = Self::autoindex_defs(name, meta);
                TableInfo {
                    name: name.clone(),
                    columns: meta
                        .columns
                        .iter()
                        .map(|c| ColumnInfo {
                            name: c.clone(),
                            nullable: !meta.not_null.contains(c),
                            primary_key: meta.primary_key.as_deref() == Some(c.as_str()),
                            unique: meta.unique.contains(c),
                            autoinc: meta.autoinc.as_deref() == Some(c.as_str())
                                || meta.autoguid.as_deref() == Some(c.as_str()),
                            data_type: if meta.autoguid.as_deref() == Some(c.as_str()) {
                                "GUID".to_string()
                            } else {
                                "ANY".to_string()
                            },
                            default_value: meta
                                .defaults
                                .iter()
                                .find(|(dc, _)| dc == c)
                                .map(|(_, t)| t.clone()),
                        })
                        .collect(),
                    keys: meta
                        .primary_key
                        .iter()
                        .chain(meta.unique.iter())
                        .cloned()
                        .collect(),
                    indexes: auto
                        .iter()
                        .map(|i| i.name.clone())
                        .chain(meta.indexes.iter().cloned())
                        .collect(),
                    index_defs: auto
                        .into_iter()
                        .chain(meta.index_defs.iter().map(|d| IndexInfo {
                            name: d.name.clone(),
                            column: d.column().to_string(),
                            columns: d.columns.clone(),
                            unique: d.unique,
                            auto: false,
                            pred: d.pred.clone(),
                        }))
                        .collect(),
                    pages: meta.pages.len(),
                    matview: meta.is_matview(),
                }
            })
            .collect()
    }

    /// Observed (data-derived) column names for one table: the union of
    /// top-level field names across its documents — the same projection
    /// `SELECT *` builds for a non-empty table. Declared columns
    /// (`catalog()`) are the constraint/introspection surface and never
    /// auto-sync with data; this is the data-side counterpart. It scans
    /// the table, so only deliberate introspection surfaces (object
    /// explorer) should call it. Unknown tables yield an empty list.
    pub fn observed_columns(&self, table: &str) -> Vec<String> {
        if !self.tables.contains_key(table) {
            return Vec::new();
        }
        self.table_docs_cx(table)
            .map(|d| union_of_fields(&d))
            .unwrap_or_default()
    }

    /// Replication fingerprints for every user table, sorted by name;
    /// `_pubsub_messages` is skipped (node-local queue state, like
    /// [Database::dump_script]). `rows_hash` is a wrapping sum of
    /// per-row hashes over the documents' canonical encoded bytes, so it
    /// is independent of heap layout: nodes holding the same logical
    /// data agree regardless of which node applied a row first. The
    /// cluster rejoin repair compares these to decide whether a node
    /// that was offline missed writes.
    pub fn digests(&mut self) -> Result<Vec<TableDigest>> {
        let mut names: Vec<String> = self
            .tables
            .keys()
            .filter(|n| !is_system_table(n))
            .cloned()
            .collect();
        names.sort();
        let mut out = Vec::with_capacity(names.len());
        for name in &names {
            let meta = self.tables.get(name).cloned().unwrap();
            let docs = self.table_docs_cx(name)?;
            let mut rows_hash: u64 = 0;
            for doc in &docs {
                let mut h = DefaultHasher::new();
                for (k, v) in doc {
                    k.hash(&mut h);
                    let mut buf = Vec::new();
                    encode::encode(v, &mut buf)?;
                    h.write(&buf);
                }
                rows_hash = rows_hash.wrapping_add(h.finish());
            }
            out.push(TableDigest {
                name: name.clone(),
                rows: docs.len() as u64,
                rows_hash,
                schema_hash: schema_hash(&meta),
            });
        }
        Ok(out)
    }

    /// Remove every user table from the catalog, bypassing DROP TABLE's
    /// FOREIGN KEY guards. Cluster rejoin repair replaces the node's
    /// whole state with the cluster snapshot inside one transaction:
    /// tables the snapshot no longer contains must go too, and no
    /// removal order satisfies DROP's "referenced by FOREIGN KEY" check
    /// for every mixed state (cycles included). Runs inside the
    /// caller's transaction — rollback restores the pre-wipe catalog.
    /// Engine-managed system tables survive: the journal and positions
    /// describe stream-applied ops, which the snapshot adoption
    /// accounting (positions reset to the sampled heads) keeps valid.
    pub fn wipe_user_tables(&mut self) -> Result<()> {
        let doomed: Vec<String> = self
            .tables
            .keys()
            .filter(|n| !is_system_table(n))
            .cloned()
            .collect();
        let mut tx = self.pager.begin_tx();
        for name in doomed {
            if let Some(meta) = self.tables.get(&name) {
                self.free_table_storage(&mut tx, meta)?;
            }
            self.tables.remove(&name);
        }
        // Wiped tables may be recreated from a snapshot: drop their
        // AUTOINCREMENT watermarks with them or the recreated table resumes
        // from a stale counter (see DROP TABLE). Triggers die too — the
        // snapshot replay recreates them from its own CREATE TRIGGER block
        // (emitted after the data, pg_dump style).
        self.autoinc_cache.clear();
        self.triggers.clear();
        self.save_catalog_into(&mut tx)?;
        self.commit_pager_tx(tx)?;
        Ok(())
    }

    /// Release every page a table's storage occupies: heap pages, index-tree
    /// pages and recycled overflow-chain pages. Called for tables being
    /// dropped or wiped (a `rewrite_table` keeps `overflow_free`, which its
    /// next incarnation reuses for chains, so it frees only heap/tree pages).
    fn free_table_storage(&self, tx: &mut crate::pager::Tx, meta: &TableMeta) -> Result<()> {
        // Live overflow chains are anchored only by the slots' head pointers
        // (recycled ones sit in `overflow_free`); free them before the heap
        // pages themselves go away.
        crate::heap::free_overflow_chains(&self.pager, tx, &meta.pages)?;
        for &p in &meta.pages {
            self.pager.free_page(tx, p)?;
        }
        for &p in &meta.overflow_free {
            self.pager.free_page(tx, p)?;
        }
        for (root_key, &root) in &meta.index_roots {
            for p in BTree::open(root)
                .collect_pages(&PageReader::current(&self.pager), tx)
                .map_err(|e| index_err(root_key, e))?
            {
                self.pager.free_page(tx, p)?;
            }
        }
        Ok(())
    }

    // ---- catch-up replication: journal + positions ----

    /// Create the catch-up system tables if missing. Called by the server
    /// at startup, before any journal or position access.
    pub fn ensure_cluster_tables(&mut self) -> Result<()> {
        if self.tables.contains_key(CLUSTER_LOG_TABLE)
            && self.tables.contains_key(CLUSTER_POS_TABLE)
            && self.tables.contains_key(CLUSTER_ID_TABLE)
        {
            return Ok(());
        }
        // Reserved engine names: the internal-ddl flag is the sanctioned
        // way past the CREATE TABLE guard (same pattern as
        // ensure_user_tables; always cleared on the way out).
        self.internal_ddl = true;
        let result = self.ensure_cluster_tables_inner();
        self.internal_ddl = false;
        result
    }

    fn ensure_cluster_tables_inner(&mut self) -> Result<()> {
        let preexisting = self.tables.contains_key(CLUSTER_LOG_TABLE);
        self.execute(&format!(
            "CREATE TABLE IF NOT EXISTS {CLUSTER_LOG_TABLE} (seq INT PRIMARY KEY, sql TEXT, ts INT)"
        ))?;
        // Migration: journals created before PITR have no ts column. Entries
        // migrated this way keep ts NULL — PITR export skips NULL-ts rows
        // (they predate the feature and always sit before the first
        // post-upgrade base backup's journal position).
        if preexisting {
            let has_ts = self
                .execute(&format!("SELECT ts FROM {CLUSTER_LOG_TABLE} LIMIT 1"))
                .is_ok();
            if !has_ts {
                self.execute(&format!(
                    "ALTER TABLE {CLUSTER_LOG_TABLE} ADD COLUMN ts INT"
                ))?;
            }
        }
        self.execute(&format!(
            "CREATE TABLE IF NOT EXISTS {CLUSTER_POS_TABLE} (node_id TEXT PRIMARY KEY, seq INT)"
        ))?;
        self.execute(&format!(
            "CREATE TABLE IF NOT EXISTS {CLUSTER_ID_TABLE} (id TEXT)"
        ))?;
        Ok(())
    }

    /// Create the pub/sub backing table (idempotent). Lives in core so the
    /// server's pubsub store and every test use the same sanctioned path
    /// past the reserved-name guard in CREATE TABLE.
    pub fn ensure_pubsub_table(&mut self) -> Result<()> {
        self.internal_ddl = true;
        let result = self
            .execute(&format!(
                "CREATE TABLE IF NOT EXISTS {PUBSUB_TABLE} \
             (id INT PRIMARY KEY AUTOINCREMENT, channel TEXT, ts_ms INT, payload TEXT)"
            ))
            .map(|_| ());
        self.internal_ddl = false;
        result
    }

    /// This node's persistent random identity: the key other nodes store
    /// this node's journal position under. Generated once, then stable.
    pub fn cluster_id(&mut self) -> Result<String> {
        self.ensure_cluster_tables()?;
        if let Some(id) = &self.cluster_id {
            return Ok(id.clone());
        }
        let existing = self.execute(&format!("SELECT id FROM {CLUSTER_ID_TABLE} LIMIT 1"))?;
        if let ExecOutcome::Rows(r) = existing {
            if let Some(row) = r.rows.first() {
                if let Some(Value::Str(id)) = row.first() {
                    self.cluster_id = Some(id.clone());
                    return Ok(id.clone());
                }
            }
        }
        let id = crate::guid::uuidv7();
        self.execute(&format!(
            "INSERT INTO {CLUSTER_ID_TABLE} VALUES ({})",
            value_literal(&Value::Str(id.clone()))?
        ))?;
        self.cluster_id = Some(id.clone());
        Ok(id)
    }

    /// MAX/MIN(seq) over the journal (0 when empty or negative somehow).
    fn journal_seq_boundary(&mut self, agg: &str) -> Result<u64> {
        self.ensure_cluster_tables()?;
        let r = self.execute(&format!("SELECT {agg}(seq) FROM {CLUSTER_LOG_TABLE}"))?;
        Ok(match r {
            ExecOutcome::Rows(rows) => rows
                .rows
                .first()
                .and_then(|row| row.first())
                .and_then(Value::as_i64)
                .unwrap_or(0)
                .max(0) as u64,
            _ => 0,
        })
    }

    /// Append one locally-committed write to the journal and return its
    /// seq. Call immediately after the write commits, before fanning out:
    /// the entry then exists for every peer that ever pulls catch-up,
    /// whatever happens to the fan-out itself. The insert is its own
    /// statement (a crash between the data commit and this append loses
    /// the entry — the repair's digest re-check catches the resulting
    /// divergence and falls back to a snapshot).
    pub fn journal_append(&mut self, sql: &str) -> Result<u64> {
        self.ensure_cluster_tables()?;
        let next = match self.journal_next {
            Some(n) => n,
            None => self.journal_seq_boundary("MAX")? + 1,
        };
        // ts = entry commit time (ms): the PITR replay watermark. One clock
        // read per journaled write is nothing next to the write itself.
        let ts = crate::now_ms() as i64;
        self.execute(&format!(
            "INSERT INTO {CLUSTER_LOG_TABLE} (seq, sql, ts) VALUES ({next}, {}, {ts})",
            value_literal(&Value::Str(sql.to_string()))?
        ))?;
        self.journal_next = Some(next + 1);
        if let Some(bytes) = self.journal_bytes.as_mut() {
            *bytes += sql.len() as u64 + 64;
        }
        Ok(next)
    }

    /// Highest journal seq (0 when empty).
    pub fn journal_head(&mut self) -> Result<u64> {
        self.journal_seq_boundary("MAX")
    }

    /// Lowest journal seq still retained (0 when empty). A position below
    /// this minus one means the needed range was trimmed away and the
    /// peer must fall back to a full snapshot.
    pub fn journal_oldest(&mut self) -> Result<u64> {
        self.journal_seq_boundary("MIN")
    }

    /// Journal entries with seq > `after`, in order, capped at `limit`
    /// entries per call. Callers loop, advancing `after` to the last
    /// returned seq, until the result is empty.
    pub fn journal_range(&mut self, after: u64, limit: usize) -> Result<Vec<(u64, String)>> {
        self.ensure_cluster_tables()?;
        let r = self.execute(&format!(
            "SELECT seq, sql FROM {CLUSTER_LOG_TABLE} WHERE seq > {after} \
             ORDER BY seq ASC LIMIT {limit}"
        ))?;
        let mut out = Vec::new();
        let mut bytes = 0usize;
        if let ExecOutcome::Rows(rows) = r {
            for row in &rows.rows {
                let (Some(Value::Int(seq)), Some(Value::Str(sql))) = (row.first(), row.get(1))
                else {
                    return err("journal row has unexpected shape");
                };
                bytes = bytes.saturating_add(sql.len());
                if !out.is_empty() && bytes > JOURNAL_RANGE_MAX_BYTES {
                    // Byte budget for the catch-up batch: rows can carry
                    // ~16MiB documents, so a 512-row page could otherwise
                    // materialize gigabytes in one Vec on the serving node.
                    break;
                }
                out.push((*seq as u64, sql.clone()));
            }
        }
        Ok(out)
    }

    /// Drop journal entries beyond the newest `keep` — the catch-up
    /// window. Peers positioned older than the window's start fall back
    /// to a full snapshot. `keep == 0` keeps everything.
    pub fn journal_trim(&mut self, keep: u64) -> Result<()> {
        self.ensure_cluster_tables()?;
        if keep == 0 {
            return Ok(());
        }
        let head = self.journal_head()?;
        if head <= keep {
            return Ok(());
        }
        self.journal_bytes = None; // rows deleted; recompute lazily
        self.execute(&format!(
            "DELETE FROM {CLUSTER_LOG_TABLE} WHERE seq <= {}",
            head - keep
        ))
        .map(|_| ())
    }

    /// Byte-dimension journal cap alongside the count window: drop oldest
    /// entries until the journal's SQL text fits `max_bytes`. The count
    /// window alone bounds nothing for big-document workloads (a single
    /// journal entry can reach 16 MiB, so 100k entries ≈ 100 GB), and the
    /// PITR-recommended `DOCSQL_CATCHUP_WINDOW=0` removes the count cap
    /// entirely. Cheap when under the cap: the running total is cached in
    /// memory (one SUM scan after open, then incremented per append).
    pub fn journal_trim_bytes(&mut self, max_bytes: u64) -> Result<()> {
        self.ensure_cluster_tables()?;
        let total = match self.journal_bytes {
            Some(b) => b,
            None => {
                let r =
                    self.execute(&format!("SELECT SUM(LENGTH(sql)) FROM {CLUSTER_LOG_TABLE}"))?;
                let b = match r {
                    ExecOutcome::Rows(rows) => rows
                        .rows
                        .first()
                        .and_then(|row| row.first())
                        .and_then(Value::as_i64)
                        .unwrap_or(0)
                        .max(0) as u64,
                    _ => 0,
                };
                self.journal_bytes = Some(b);
                b
            }
        };
        if total <= max_bytes {
            return Ok(());
        }
        // Delete oldest seqs until the removed bytes cover the excess. One
        // ordered scan (rows are already seq-ordered in the heap) plus one
        // ranged DELETE — both amortized against the many appends that let
        // the total drift past the cap.
        let r = self.execute(&format!(
            "SELECT seq, LENGTH(sql) FROM {CLUSTER_LOG_TABLE} ORDER BY seq ASC"
        ))?;
        let excess = total - max_bytes;
        let mut acc = 0u64;
        let mut cutoff = 0u64;
        if let ExecOutcome::Rows(rows) = r {
            for row in &rows.rows {
                let (Some(Value::Int(seq)), Some(Value::Int(n))) = (row.first(), row.get(1)) else {
                    continue;
                };
                acc += (*n).max(0) as u64;
                cutoff = *seq as u64;
                if acc >= excess {
                    break;
                }
            }
        }
        if cutoff > 0 {
            self.journal_bytes = None; // recompute exactly after the delete
            self.execute(&format!(
                "DELETE FROM {CLUSTER_LOG_TABLE} WHERE seq <= {cutoff}"
            ))?;
        }
        Ok(())
    }

    /// Void every journal entry's text, keeping the seqs allocated. Used
    /// when a snapshot adoption overrules this node's own recent writes:
    /// the adjudicated entries must never replay again (a later repair on
    /// some peer would pull them back and resurrect discarded writes), but
    /// the seq space and every recorded position must keep their meaning.
    /// Replays of a voided entry are a parsed no-op.
    /// Journal entries with `seq > after`, in seq order, capped at `limit`:
    /// the PITR incremental export source. `ts` is the entry's commit time
    /// (None for rows migrated from the pre-PITR journal shape).
    pub fn journal_entries_after(
        &mut self,
        after: u64,
        limit: usize,
    ) -> Result<Vec<(u64, Option<i64>, String)>> {
        self.ensure_cluster_tables()?;
        let r = self.execute(&format!(
            "SELECT seq, ts, sql FROM {CLUSTER_LOG_TABLE} WHERE seq > {after} \
             ORDER BY seq LIMIT {limit}"
        ))?;
        let mut out = Vec::new();
        if let ExecOutcome::Rows(rows) = r {
            for row in rows.rows {
                let seq = row.first().and_then(Value::as_i64).unwrap_or(0).max(0) as u64;
                let ts = row.get(1).and_then(Value::as_i64);
                if let Some(Value::Str(sql)) = row.get(2) {
                    out.push((seq, ts, sql.clone()));
                }
            }
        }
        Ok(out)
    }

    pub fn journal_void_all(&mut self) -> Result<()> {
        self.ensure_cluster_tables()?;
        self.journal_bytes = None; // text shrinks to the sentinel; recompute lazily
        self.execute(&format!(
            "UPDATE {CLUSTER_LOG_TABLE} SET sql = 'PRAGMA discarded_by_snapshot_adoption;'"
        ))
        .map(|_| ())
    }

    /// Last applied journal seq for the origin `node_id`.
    pub fn position_get(&mut self, node_id: &str) -> Result<Option<u64>> {
        self.ensure_cluster_tables()?;
        let r = self.execute(&format!(
            "SELECT seq FROM {CLUSTER_POS_TABLE} WHERE node_id = {}",
            value_literal(&Value::Str(node_id.to_string()))?
        ))?;
        Ok(match r {
            ExecOutcome::Rows(rows) => rows
                .rows
                .first()
                .and_then(|row| row.first())
                .and_then(Value::as_i64)
                .map(|s| s as u64),
            _ => None,
        })
    }

    /// Record that everything up to `seq` from origin `node_id` is
    /// applied here. Called after a replicated write commits (advancing)
    /// and after an adoption samples the origin's head (establishing).
    pub fn position_set(&mut self, node_id: &str, seq: u64) -> Result<()> {
        self.ensure_cluster_tables()?;
        let key = value_literal(&Value::Str(node_id.to_string()))?;
        let updated = match self.execute(&format!(
            "UPDATE {CLUSTER_POS_TABLE} SET seq = {seq} WHERE node_id = {key}"
        ))? {
            ExecOutcome::Affected(n) => n,
            ExecOutcome::Rows(_) => 0,
        };
        if updated == 0 {
            self.execute(&format!(
                "INSERT INTO {CLUSTER_POS_TABLE} (node_id, seq) VALUES ({key}, {seq})"
            ))?;
        }
        Ok(())
    }

    /// Forget all positions: used when an adoption replaces the state in
    /// a way the sampled heads cannot account for.
    pub fn positions_clear(&mut self) -> Result<()> {
        self.ensure_cluster_tables()?;
        self.execute(&format!("DELETE FROM {CLUSTER_POS_TABLE}"))
            .map(|_| ())
    }

    /// Full logical dump as a SQL script: all DDL first, then all data.
    /// System storage (`_pubsub_messages`) is skipped — its ids are
    /// node-local and it is not user data. The join protocol replays this
    /// inside one transaction on a fresh node to bootstrap the cluster's
    /// current state; every CREATE precedes every INSERT, so FOREIGN KEY
    /// declarations are safe in the DDL phase (referential checks run at
    /// insert time). Applying the script replaces tables wholesale
    /// (DROP + CREATE prefix), so re-applying is idempotent.
    ///
    /// All user tables are dropped by ONE statement: the DROP guard
    /// exempts tables dropped by the same statement, so the drop cannot
    /// be blocked by FK references — per-table drops interleaved with
    /// CREATEs would deadlock against the restored schema (the new child
    /// referencing a parent whose old copy is still to be dropped), and
    /// backup restore replays this script over LIVE data, not a fresh
    /// node.
    pub fn dump_script(&mut self) -> Result<String> {
        let names: Vec<String> = self
            .tables
            .keys()
            .filter(|n| !is_internal_table(n))
            .cloned()
            .collect();
        // Views drop with their own statement kind: DROP TABLE on a view is
        // a wrong-kind error (restore replays the prelude verbatim).
        let view_names: Vec<String> = names
            .iter()
            .filter(|n| self.tables.get(*n).is_some_and(|m| m.is_view()))
            .cloned()
            .collect();
        // Materialized views are third kind: real storage but dumped as
        // CREATE MATERIALIZED VIEW (the replay re-runs the stored query —
        // deterministic, validated at CREATE — so the restored content is
        // a fresh recompute over the restored base data, never the
        // possibly-stale origin rows).
        let matview_names: Vec<String> = names
            .iter()
            .filter(|n| self.tables.get(*n).is_some_and(|m| m.is_matview()))
            .cloned()
            .collect();
        let table_names: Vec<String> = names
            .iter()
            .filter(|n| {
                !self
                    .tables
                    .get(*n)
                    .is_some_and(|m| m.is_view() || m.is_matview())
            })
            .cloned()
            .collect();
        // CREATE order must respect FK dependencies: the engine (rightly)
        // rejects a CREATE whose referenced table does not exist yet, so
        // alphabetical DDL order fails the replay whenever the child sorts
        // before its parent. Drops go the opposite way (children first).
        let ordered_tables = fk_dependency_order(&table_names, &self.tables);
        let drop_order: Vec<String> = {
            let mut v = ordered_tables.clone();
            v.reverse();
            v
        };
        let mut ddl = String::new();
        if !view_names.is_empty() {
            let drops = view_names
                .iter()
                .map(|n| quote_ident(n))
                .collect::<Vec<_>>()
                .join(", ");
            ddl.push_str(&format!("DROP VIEW IF EXISTS {drops};\n"));
        }
        if !table_names.is_empty() {
            let drops = drop_order
                .iter()
                .map(|n| quote_ident(n))
                .collect::<Vec<_>>()
                .join(", ");
            ddl.push_str(&format!("DROP TABLE IF EXISTS {drops};\n"));
        }
        for name in &ordered_tables {
            let meta = self.tables.get(name).cloned().unwrap();
            ddl.push_str(&create_table_ddl(name, &meta));
            ddl.push('\n');
            for d in &meta.index_defs {
                // Path indexes (design 005) re-emit as the JSON_EXTRACT
                // expression they were created from — replay parses it back
                // through the same CREATE INDEX path.
                let col_text = match &d.path {
                    Some(p) => format!("JSON_EXTRACT({}, '{}')", quote_ident(&d.columns[0]), p),
                    None => d
                        .columns
                        .iter()
                        .map(|c| quote_ident(c))
                        .collect::<Vec<_>>()
                        .join(", "),
                };
                ddl.push_str(&format!(
                    "CREATE {}INDEX {} ON {} ({}){};\n",
                    if d.unique { "UNIQUE " } else { "" },
                    quote_ident(&d.name),
                    quote_ident(name),
                    col_text,
                    d.pred
                        .as_deref()
                        .map(|p| format!(" WHERE {p}"))
                        .unwrap_or_default()
                ));
            }
        }
        // Insert order must respect FK dependencies: referenced tables
        // first. Catalog iteration is alphabetical, so without this a
        // child table's rows could replay before its parent's and fail
        // the per-row FK check.
        let mut dml = String::new();
        for name in fk_dependency_order(&table_names, &self.tables) {
            let docs = self.table_docs_cx(&name)?;
            // 自引用表按行级依赖序出:存储序的前向引用曾让回放必败。
            let docs = match self.tables.get(&name) {
                Some(meta) => self_ref_row_order(&name, meta, docs),
                None => docs,
            };
            for doc in docs {
                let cols: Vec<String> = doc.keys().cloned().collect();
                let vals = cols
                    .iter()
                    .map(|c| value_literal(&doc[c]))
                    .collect::<Result<Vec<_>>>()?;
                dml.push_str(&format!(
                    "INSERT INTO {} ({}) VALUES ({});\n",
                    quote_ident(&name),
                    cols.iter()
                        .map(|c| quote_ident(c))
                        .collect::<Vec<_>>()
                        .join(", "),
                    vals.join(", ")
                ));
            }
        }
        // Append in place instead of `ddl + &dml`: the dump is taken under
        // the engine lock, so a third full-size copy would double the peak
        // memory for nothing.
        ddl.push_str(&dml);
        // Views: their bodies reference restored tables (the CREATE
        // dry-runs the body, so the table must exist by then), and a view
        // of a view needs its base view restored first — dependency order,
        // not catalog (alphabetical) order.
        for name in &view_dependency_order(&view_names, &self.tables) {
            if let Some(meta) = self.tables.get(name) {
                if let Some(body) = &meta.view_sql {
                    ddl.push_str(&format!("CREATE VIEW {} AS {body};\n", quote_ident(name)));
                }
            }
        }
        // Triggers come AFTER the data (pg_dump semantics): the dumped rows
        // already include every effect their firing ever produced, and
        // replaying the INSERTs with live triggers would fire them again —
        // duplicated audit rows, doubled cascades. Created post-data, the
        // restore reproduces the snapshot byte-for-byte and the triggers arm
        // only for statements that run after it.
        for d in self.triggers.values() {
            ddl.push_str(&create_trigger_sql(d));
            ddl.push_str(";\n");
        }
        // Materialized views after views (a matview query may read a view;
        // the CREATE re-runs the query over the restored data — REFRESH
        // semantics — so the possibly-stale stored rows are deliberately
        // NOT dumped) and before users.
        for name in &matview_names {
            let meta = self.tables.get(name).cloned().unwrap();
            let q = meta.matview_sql.as_deref().expect("matview has a query");
            ddl.push_str(&format!(
                "CREATE MATERIALIZED VIEW {} AS {q};\n",
                quote_ident(name)
            ));
            for d in &meta.index_defs {
                let col_text = d
                    .columns
                    .iter()
                    .map(|c| quote_ident(c))
                    .collect::<Vec<_>>()
                    .join(", ");
                ddl.push_str(&format!(
                    "CREATE {}INDEX {} ON {} ({}){};\n",
                    if d.unique { "UNIQUE " } else { "" },
                    quote_ident(&d.name),
                    quote_ident(name),
                    col_text,
                    d.pred
                        .as_deref()
                        .map(|p| format!(" WHERE {p}"))
                        .unwrap_or_default()
                ));
            }
        }
        // Users/roles last of all: `GRANT … ON <object>` validates that the
        // target exists, and a grant on a VIEW must replay after that view
        // is created (emitting them before the view block made every dump
        // from a mesh with view grants unrestorable). Passwords ride in
        // stored-hash form; plain INSERTs against the reserved tables are
        // rejected by the write gate, so the statement family is the one
        // replication form everywhere. The DROP prelude above does not
        // cover the reserved tables — restoring a backup with fewer users
        // must still remove the extras — so drop them here; the replaying
        // node re-creates them via ensure_user_tables before the first
        // CREATE USER applies.
        ddl.push_str(&format!(
            "DROP TABLE IF EXISTS {}, {}, {}, {};\n",
            crate::useradmin::USERS_TABLE,
            crate::useradmin::ROLES_TABLE,
            crate::useradmin::MEMBERS_TABLE,
            crate::useradmin::GRANTS_TABLE
        ));
        for s in crate::useradmin::dump_user_statements(self)? {
            ddl.push_str(&s);
            ddl.push_str(";\n");
        }
        Ok(ddl)
    }

    /// Page size of the underlying storage file.
    pub fn page_size(&self) -> usize {
        PAGE_SIZE
    }

    /// Number of allocated pages.
    pub fn num_pages(&self) -> u32 {
        self.pager.num_pages()
    }

    /// Last WAL LSN known durable; nodes that received the same writes should
    /// report converging values.
    pub fn durable_lsn(&self) -> u64 {
        self.pager.durable_lsn()
    }

    /// Table/view grants for a dropped object are garbage: delete them
    /// before the catalog change (recreating the same name must not
    /// resurrect the old privileges). Autocommit statements; replay order
    /// on peers is identical. The deleted ROWS come back to the caller:
    /// a failure of the main DDL after this point must restore them, or
    /// the node keeps a grants divergence no journal entry explains.
    /// Errors propagate — the old `.ok()` swallowed disk failures into a
    /// silent half-drop.
    fn delete_grants_for(&mut self, names: &[String]) -> Result<Vec<Object>> {
        // The grants table is created lazily on the first user-admin write;
        // a node with no users has no grants to clean.
        if !self.tables.contains_key(crate::useradmin::GRANTS_TABLE) {
            return Ok(Vec::new());
        }
        let mut deleted = Vec::new();
        for name in names {
            if !is_internal_table(name) {
                let lit_name = crate::stmt::sql_string_literal(name);
                if let Ok(ExecOutcome::Rows(r)) = self.execute(&format!(
                    "SELECT * FROM {} WHERE tbl = {}",
                    crate::useradmin::GRANTS_TABLE,
                    lit_name
                )) {
                    for row in &r.rows {
                        let mut obj = Object::new();
                        for (c, v) in r.columns.iter().zip(row.iter()) {
                            obj.insert(c.clone(), v.clone());
                        }
                        deleted.push(obj);
                    }
                }
                self.execute(&format!(
                    "DELETE FROM {} WHERE tbl = {}",
                    crate::useradmin::GRANTS_TABLE,
                    lit_name
                ))?;
            }
        }
        Ok(deleted)
    }

    /// Best-effort restore of grant rows a failed DDL must put back. Only
    /// reachable on a main-DDL failure after the grants autocommit landed;
    /// a restore failure is shouted to stderr (the alternative — silence —
    /// is the divergence this helper exists to close).
    fn restore_grant_rows(&mut self, rows: &[Object]) {
        for row in rows {
            let cols: Vec<String> = row.keys().cloned().collect();
            let vals: Vec<String> = row
                .values()
                .map(|v| value_literal(v).unwrap_or_else(|_| "NULL".to_string()))
                .collect();
            let sql = format!(
                "INSERT INTO {} ({}) VALUES ({})",
                crate::useradmin::GRANTS_TABLE,
                cols.iter()
                    .map(|c| quote_ident(c))
                    .collect::<Vec<_>>()
                    .join(", "),
                vals.join(", ")
            );
            if let Err(e) = self.execute(&sql) {
                eprintln!(
                    "warning: failed to restore grant rows after a failed DDL ({e}); \
                     run the DDL again or REVOKE manually"
                );
            }
        }
    }

    fn exec_stmt_inner(&mut self, stmt: Statement) -> Result<ExecOutcome> {
        match stmt {
            Statement::CreateTable(create) => self.exec_create(create),
            Statement::CreateTrigger(ct) => self.exec_create_trigger(ct),
            Statement::DropTrigger(dt) => {
                if dt.option.is_some() {
                    return err("DROP TRIGGER CASCADE / RESTRICT is not supported");
                }
                let names: Vec<ObjectName> = std::iter::once(dt.trigger_name.clone()).collect();
                self.exec_drop_trigger(&names, dt.if_exists)
            }
            Statement::CreateView(view) => self.exec_create_view(view),
            Statement::Drop {
                object_type,
                names,
                if_exists,
                cascade,
                purge,
                ..
            } => {
                if purge {
                    // Hive's PURGE has no meaning for a database that always
                    // reclaims storage; accepting it would imply a recycle
                    // bin this engine does not have.
                    return err("DROP ... PURGE is not supported");
                }
                if !self.internal_ddl
                    && (object_type == sqlparser::ast::ObjectType::Table
                        || object_type == sqlparser::ast::ObjectType::View)
                {
                    for name in names.iter().map(obj_name) {
                        // Engine SYSTEM tables only: the user tables must
                        // stay droppable — the dump prelude drops them in
                        // every wholesale snapshot replay (the network path
                        // still refuses user-table DDL via
                        // stmt_write_targets).
                        if crate::engine::is_system_table(&name) {
                            return err(format!("cannot DROP the internal table {name}"));
                        }
                    }
                }
                if object_type == sqlparser::ast::ObjectType::Index {
                    // Composites roots removed below release their tree in
                    // the same catalog transaction; pages staged here never
                    // fight the readers (write lock held, snapshots use WAL).
                    //
                    // Validate the whole list first: the mutation loop below
                    // edits the in-memory catalog, so a mid-list failure must
                    // not strand uncommitted changes (a later save would
                    // persist them without a journal entry).
                    for n in &names {
                        let iname = obj_name(n);
                        // Constraint indexes are derived from the table's
                        // PRIMARY KEY/UNIQUE declarations (SQLite semantics).
                        if iname.starts_with("sqlite_autoindex_") {
                            return err("index associated with UNIQUE or PRIMARY KEY constraint \
                                 cannot be dropped");
                        }
                        let owner = self
                            .tables
                            .iter()
                            .any(|(_, m)| m.indexes.iter().any(|i| i == &iname));
                        if !owner && !if_exists {
                            return err(format!("index {iname} does not exist"));
                        }
                    }
                    // Same catalog snapshot as DROP TABLE/VIEW: a failure in
                    // the page-free loop or the catalog save must restore the
                    // in-memory catalog, or the next successful write would
                    // persist the (unjournalled) half-drop.
                    let catalog_prev = self.tables.clone();
                    let mut dropped_roots: Vec<(String, u32)> = Vec::new();
                    for n in &names {
                        let iname = obj_name(n);
                        // Index names are database-wide, so at most one table
                        // owns the index. Locate it read-only first, then
                        // write-clone just that entry (`catalog_mut` →
                        // `Arc::make_mut`) — mapping make_mut over every
                        // table would deep-clone the whole catalog whenever
                        // any detached reader holds an old version.
                        let owner = self
                            .tables
                            .iter()
                            .find(|(_, m)| m.indexes.iter().any(|i| i == &iname))
                            .map(|(t, _)| t.clone());
                        if let Some(owner) = owner {
                            let Some(meta) = self.catalog_mut(&owner) else {
                                return err(format!("table {owner} does not exist"));
                            };
                            if let Some(pos) = meta.indexes.iter().position(|i| i == &iname) {
                                meta.indexes.remove(pos);
                                // The B+ tree itself stays in index_roots:
                                // non-unique lookups still benefit from
                                // it — but only for single-column trees
                                // (keyed by the column itself). A
                                // composite tree is keyed by the index
                                // *name*; with the definition gone
                                // nothing can address it, and leaving it
                                // behind would let a column that shares
                                // the name look like a scalar tree.
                                if let Some(dpos) = meta
                                    .index_defs
                                    .iter()
                                    .position(|d| d.name == iname.as_str())
                                {
                                    let def = meta.index_defs.remove(dpos);
                                    // Trees keyed by the index NAME (composite
                                    // or JSON-path indexes) are unaddressable
                                    // once the definition is gone — and a
                                    // path tree left behind gets mistaken for
                                    // the column's own scalar tree, silently
                                    // hijacking probes and ORDER BY walks.
                                    if def.columns.len() > 1
                                        || def.path.is_some()
                                        || def.pred.is_some()
                                    {
                                        if let Some(root) = meta.index_roots.remove(&iname) {
                                            dropped_roots.push((iname.clone(), root));
                                        }
                                    }
                                    // Lift UNIQUE only when this index was
                                    // the sole source: table-declared
                                    // constraints and other unique indexes
                                    // on the same column keep it enforced.
                                    // Composite unique indexes never join
                                    // meta.unique, so single-column lift
                                    // rules cover everything here. The
                                    // "other source" test must name the
                                    // column AS ITS SINGLE key: a composite
                                    // unique index containing the column
                                    // never guaranteed single-column
                                    // uniqueness, and counting it kept the
                                    // dropped constraint enforced forever
                                    // (schema hash divergence included).
                                    if def.unique
                                        && def.columns.len() == 1
                                        && !meta.constraint_unique.contains(&def.columns[0])
                                        && meta.primary_key.as_deref()
                                            != Some(def.columns[0].as_str())
                                        && !meta.index_defs.iter().any(|d| {
                                            d.unique
                                                && d.columns.len() == 1
                                                && d.columns[0] == def.columns[0]
                                        })
                                    {
                                        meta.unique.retain(|c| c != &def.columns[0]);
                                    }
                                }
                            }
                        }
                    }
                    let mut tx = self.pager.begin_tx();
                    let drop_result: Result<()> = (|| {
                        for (root_key, root) in &dropped_roots {
                            for p in BTree::open(*root)
                                .collect_pages(&PageReader::current(&self.pager), &tx)
                                .map_err(|e| index_err(root_key, e))?
                            {
                                self.pager.free_page(&mut tx, p)?;
                            }
                        }
                        self.save_catalog_into(&mut tx)
                    })();
                    match drop_result {
                        Ok(()) => {
                            self.commit_pager_tx(tx)?;
                            return Ok(ExecOutcome::Affected(0));
                        }
                        Err(e) => {
                            self.pager.abort_tx(tx)?;
                            self.tables = catalog_prev;
                            return Err(e);
                        }
                    }
                }
                if object_type == sqlparser::ast::ObjectType::View {
                    // Views have no storage: drop the catalog entries only.
                    // DROP TABLE on a view errors (wrong-kind mismatch), and
                    // so does DROP VIEW on a table. Validate the whole list
                    // before touching the catalog — a mid-list failure must
                    // not leave earlier names already dropped and committed.
                    let mut dropping: Vec<String> = names.iter().map(obj_name).collect();
                    for name in &dropping {
                        match self.tables.get(name) {
                            None if if_exists => {}
                            None => return err(format!("view {name} does not exist")),
                            Some(meta) if !meta.is_view() => {
                                return err(format!(
                                    "{name} is a table, not a view (use DROP TABLE)"
                                ));
                            }
                            Some(_) => {}
                        }
                    }
                    // A dependent view left behind used to fail only at the
                    // next SELECT; refuse without CASCADE, join with it.
                    self.expand_view_dependents(&mut dropping, cascade)?;
                    // Same snapshot discipline as DROP TABLE: a failed
                    // save_catalog_into must not leave the views gone from
                    // the in-memory catalog (the next successful write would
                    // persist a half-drop that never freed anything).
                    let catalog_prev = self.tables.clone();
                    let grants_deleted = self.delete_grants_for(&dropping)?;
                    let mut tx = self.pager.begin_tx();
                    for name in &dropping {
                        self.tables.remove(name);
                    }
                    match self.save_catalog_into(&mut tx) {
                        Ok(()) => {
                            self.commit_pager_tx(tx)?;
                            return Ok(ExecOutcome::Affected(0));
                        }
                        Err(e) => {
                            self.pager.abort_tx(tx)?;
                            self.tables = catalog_prev;
                            self.restore_grant_rows(&grants_deleted);
                            return Err(e);
                        }
                    }
                }
                if object_type != sqlparser::ast::ObjectType::Table
                    && object_type != sqlparser::ast::ObjectType::MaterializedView
                {
                    return err("only DROP TABLE/VIEW/INDEX are supported");
                }
                // Mixed-kind target: DROP TABLE on a view must not silently
                // drop the rest.
                for name in names.iter().map(obj_name) {
                    if self.tables.get(&name).is_some_and(|m| m.is_view()) {
                        return err(format!("{name} is a view, not a table (use DROP VIEW)"));
                    }
                }
                // Validate every target before touching the catalog: a missing
                // name mid-list must not leave earlier drops applied in memory
                // only, and dropping a table other tables still reference
                // leaves dangling FKs (their inserts fail and the join
                // snapshot can never replay).
                let mut dropping: Vec<String> = names.iter().map(obj_name).collect();
                // Dependent views: refuse without CASCADE (the dangling view
                // used to fail only at SELECT time), join the drop set with
                // it. Views are catalog-only, so they never hit the FK or
                // storage paths below. Missing targets (IF EXISTS) cannot
                // block a drop — their legacy dangling views join a CASCADE
                // instead.
                if cascade {
                    self.expand_view_dependents(&mut dropping, true)?;
                } else {
                    let mut existing: Vec<String> = dropping
                        .iter()
                        .filter(|n| self.tables.contains_key(*n))
                        .cloned()
                        .collect();
                    self.expand_view_dependents(&mut existing, false)?;
                }
                let view_dropping: Vec<String> = dropping
                    .iter()
                    .filter(|n| self.tables.get(*n).is_some_and(|m| m.is_view()))
                    .cloned()
                    .collect();
                let table_dropping: Vec<String> = dropping
                    .iter()
                    .filter(|n| !self.tables.get(*n).is_some_and(|m| m.is_view()))
                    .cloned()
                    .collect();
                let drop_set: std::collections::BTreeSet<&str> =
                    table_dropping.iter().map(|s| s.as_str()).collect();
                let mut fk_removals: Vec<String> = Vec::new();
                for name in &table_dropping {
                    if !self.tables.contains_key(name) {
                        if if_exists {
                            continue;
                        }
                        return err(format!("table {name} does not exist"));
                    }
                    let referencing: Vec<String> = self
                        .tables
                        .iter()
                        .filter(|(t, m)| {
                            t.as_str() != name.as_str()
                                && !drop_set.contains(t.as_str())
                                && m.foreign_keys.iter().any(|(_, rt, _)| rt == name)
                        })
                        .map(|(t, _)| t.clone())
                        .collect();
                    if !referencing.is_empty() {
                        if !cascade {
                            return err(format!(
                                "cannot drop table {name}: referenced by FOREIGN KEY in {}",
                                referencing.join(", ")
                            ));
                        }
                        fk_removals.extend(referencing);
                    }
                }
                fk_removals.sort();
                fk_removals.dedup();
                // Snapshot the catalog: any failure between here and the
                // commit must leave the in-memory catalog untouched (the
                // pager tx undoes the pages; without this the removed
                // entries stayed gone while nothing was journaled, and the
                // next successful write would persist a half-drop whose
                // pages were never freed).
                let catalog_prev = self.tables.clone();
                let grants_deleted = self.delete_grants_for(&dropping)?;
                let mut tx = self.pager.begin_tx();
                // CASCADE drops the referencing FK declarations along with
                // the table (PostgreSQL semantics): the child table stays,
                // its constraint on the vanished parent goes.
                let drop_result: Result<()> = (|| {
                    for child in &fk_removals {
                        if let Some(meta) = self.catalog_mut(child) {
                            meta.foreign_keys
                                .retain(|(_, rt, _)| !drop_set.contains(rt.as_str()));
                        }
                    }
                    for name in &table_dropping {
                        if let Some(meta) = self.tables.get(name) {
                            self.free_table_storage(&mut tx, meta)?;
                        }
                        self.tables.remove(name);
                        // A recreated table must start its AUTOINCREMENT counter
                        // from its own rows (max+1), not inherit the dropped
                        // table's watermark — replicas that restarted compute a
                        // different value and the nodes diverge.
                        self.autoinc_cache.remove(name);
                    }
                    for name in &view_dropping {
                        self.tables.remove(name);
                    }
                    // A dropped table's triggers die with it (SQLite
                    // semantics) — a surviving trigger would dangle on the
                    // table name and misfire when a new table takes it.
                    self.triggers
                        .retain(|_, d| !drop_set.contains(d.table.as_str()));
                    self.save_catalog_into(&mut tx)?;
                    Ok(())
                })();
                match drop_result {
                    Ok(()) => {
                        self.commit_pager_tx(tx)?;
                        Ok(ExecOutcome::Affected(0))
                    }
                    Err(e) => {
                        self.pager.abort_tx(tx)?;
                        self.tables = catalog_prev;
                        self.restore_grant_rows(&grants_deleted);
                        Err(e)
                    }
                }
            }
            Statement::Insert(insert) => self.exec_insert(insert),
            Statement::Update(update) => {
                if update.output.is_some() {
                    return err("OUTPUT is not supported (use RETURNING)");
                }
                if update.or.is_some() {
                    return err("UPDATE OR ... is not supported");
                }
                if !update.order_by.is_empty() || update.limit.is_some() {
                    return err("UPDATE ... ORDER BY/LIMIT is not supported");
                }
                let sqlparser::ast::Update {
                    table,
                    assignments,
                    from,
                    selection,
                    returning,
                    ..
                } = update;
                self.exec_update(table, assignments, from, selection, returning)
            }
            Statement::Delete(delete) => {
                if delete.output.is_some() {
                    return err("OUTPUT is not supported (use RETURNING)");
                }
                if !delete.order_by.is_empty() || delete.limit.is_some() {
                    return err("DELETE ... ORDER BY/LIMIT is not supported");
                }
                if !delete.tables.is_empty() {
                    return err(
                        "DELETE target lists are not supported (use DELETE FROM ... USING ...)",
                    );
                }
                let sqlparser::ast::Delete {
                    from,
                    using,
                    selection,
                    returning,
                    ..
                } = delete;
                self.exec_delete(from, using, selection, returning)
            }
            Statement::AlterTable(alter) => self.exec_alter(alter),
            Statement::StartTransaction { .. } => {
                if self.tx_snapshot.is_some() {
                    return err("transaction already in progress");
                }
                self.pager.begin_undo();
                self.tx_snapshot = Some(self.catalog_snapshot());
                Ok(ExecOutcome::Affected(0))
            }
            Statement::Commit { .. } => {
                if self.tx_snapshot.is_none() {
                    return err("no transaction in progress");
                }
                // Durability FIRST, teardown after: consuming the undo
                // journal and catalog snapshot before the fsync used to
                // leave a failed COMMIT unrecoverable — the transaction's
                // deferred frames sat unfenced with no undo left, and the
                // NEXT unrelated commit's fence would silently persist the
                // "failed" transaction while the client retried it. With
                // this order a failed fsync keeps the transaction open
                // (rollback and retry both still possible); the teardown
                // only runs once the boundary is durable (async-commit
                // mode defers that to the background flusher).
                if !self.async_commit {
                    self.pager.sync_wal().map_err(SqlError::from)?;
                    self.pending_sync = false;
                }
                let _ = self.tx_snapshot.take();
                // The page undo journal dies with the transaction.
                self.pager.end_undo();
                // Savepoints die with their transaction: a stale mark must
                // not be reachable from a later transaction's ROLLBACK TO.
                self.savepoints.clear();
                Ok(ExecOutcome::Affected(0))
            }
            Statement::Rollback {
                savepoint: Some(name),
                ..
            } => self.rollback_to_savepoint(&name.value),
            Statement::Rollback {
                savepoint: None, ..
            } => self.rollback_tx(),
            Statement::Savepoint { name } => self.savepoint(&name.value),
            Statement::ReleaseSavepoint { name } => self.release_savepoint(&name.value),
            Statement::CreateIndex(idx) => self.exec_create_index(idx),
            Statement::Merge(m) => {
                if m.output.is_some() {
                    return err("MERGE OUTPUT is not supported (use RETURNING on the statements)");
                }
                self.exec_merge(m.clone())
            }
            Statement::Query(q) => self.exec_query_cx(*q),
            Statement::Explain {
                statement,
                analyze,
                estimate,
                format,
                options,
                ..
            } => self
                .read_cx()
                .explain_outer(&statement, analyze, estimate, &format, &options),
            Statement::Truncate(tr) => {
                // Empty the tables; shape (columns/constraints) is kept.
                // Validate every target (existence, kind, FK children)
                // BEFORE truncating: a mid-list failure must not leave
                // earlier tables already emptied and committed while the
                // failed statement never reaches the journal — replicas
                // would keep rows the origin lost.
                if tr.partitions.is_some() || tr.on_cluster.is_some() {
                    return err("TRUNCATE partitions/ON CLUSTER are not supported");
                }
                if tr.identity == Some(sqlparser::ast::TruncateIdentityOption::Continue) {
                    // The AUTOINCREMENT watermark is derived from the live
                    // rows, so truncation necessarily restarts it; honoring
                    // CONTINUE IDENTITY would require a sequence store the
                    // engine does not have.
                    return err("TRUNCATE ... CONTINUE IDENTITY is not supported");
                }
                let mut targets: Vec<String> =
                    tr.table_names.iter().map(|t| obj_name(&t.name)).collect();
                for t in &tr.table_names {
                    if t.only {
                        return err("TRUNCATE ... ONLY is not supported (no inheritance)");
                    }
                }
                // CASCADE used to be accepted and ignored (the FK guard then
                // rejected the truncate whenever child rows existed). Honor
                // it: referencing tables join the target list transitively,
                // PostgreSQL-style; RESTRICT/no clause keeps the old guard.
                if tr.cascade == Some(sqlparser::ast::CascadeOption::Cascade) {
                    loop {
                        let referencing: Vec<String> = self
                            .tables
                            .iter()
                            .filter(|(t, m)| {
                                !targets.contains(t)
                                    && m.foreign_keys.iter().any(|(_, rt, _)| targets.contains(rt))
                            })
                            .map(|(t, _)| t.clone())
                            .collect();
                        if referencing.is_empty() {
                            break;
                        }
                        targets.extend(referencing);
                    }
                }
                for name in &targets {
                    if !self.tables.contains_key(name) && !tr.if_exists {
                        return err(format!("table {name} does not exist"));
                    }
                    if self.tables.get(name).is_some_and(|m| m.is_view()) {
                        return err(format!(
                            "cannot TRUNCATE view {name} (it is a view, not a table)"
                        ));
                    }
                    if self.tables.get(name).is_some_and(|m| m.is_matview()) {
                        return err(format!(
                            "cannot TRUNCATE materialized view {name} \
                             (REFRESH MATERIALIZED VIEW {name} recomputes it)"
                        ));
                    }
                    if self.tables.contains_key(name) {
                        // TRUNCATE is a full-table DELETE: child rows must
                        // not be orphaned silently (same guard as DELETE).
                        // Co-truncated tables are excluded — the whole list
                        // is validated before any table is emptied, so
                        // `TRUNCATE parent, child` must not fail on the
                        // parent's rows the child still references.
                        let removed = self.table_docs_cx(name)?;
                        self.check_fk_parent_delete_skipping(name, &removed, &[], &targets, None)?;
                    }
                }
                // One pager transaction for the WHOLE batch: each table's
                // rewrite used to commit its own transaction, so a mid-list
                // failure left earlier tables emptied AND committed while
                // the failed statement never reached the journal — replicas
                // kept rows the origin lost. Any failure now aborts the
                // batch and restores the in-memory catalog snapshot.
                let touched: Vec<String> = targets
                    .iter()
                    .filter(|n| self.tables.contains_key(*n))
                    .cloned()
                    .collect();
                let catalog_snapshot: Vec<(String, Option<std::sync::Arc<TableMeta>>)> = touched
                    .iter()
                    .map(|n| (n.clone(), self.tables.get(n).cloned()))
                    .collect();
                let mut tx = self.pager.begin_tx();
                let batch = (|| -> Result<()> {
                    for name in &touched {
                        let mut meta = self
                            .tables
                            .get(name)
                            .map(|a| a.as_ref().clone())
                            .unwrap_or_default();
                        self.rewrite_table_tx(
                            &mut tx,
                            name,
                            &mut meta,
                            Vec::new(),
                            true,
                            Vec::new(),
                        )?;
                    }
                    Ok(())
                })();
                match batch {
                    Ok(()) => {
                        self.commit_pager_tx(tx)?;
                    }
                    Err(e) => {
                        for (name, old) in catalog_snapshot {
                            match old {
                                Some(m) => {
                                    self.tables.insert(name, m);
                                }
                                None => {
                                    self.tables.remove(&name);
                                }
                            }
                        }
                        self.pager.abort_tx(tx)?;
                        return Err(e);
                    }
                }
                Ok(ExecOutcome::Affected(0))
            }
            Statement::Pragma { .. } => {
                // Compatibility shim: accept and ignore PRAGMA statements
                // (SQLite-dialect callers, e.g. EF Core startup probes).
                Ok(ExecOutcome::Affected(0))
            }
            other => err(format!("unsupported statement: {other}")),
        }
    }

    /// Rewrite the whole table from `docs` (delete+reinsert). Rebuilds every
    /// index tree for the table, updates `meta` in place, and re-inserts it
    /// into the catalog. The old heap pages and index-tree pages are released
    /// into the pager's reusable pool inside the same transaction, so a
    /// rebuild reuses its own storage instead of growing the file.
    fn rewrite_table(
        &mut self,
        table: &str,
        meta: &mut TableMeta,
        docs: Vec<Object>,
    ) -> Result<()> {
        self.rewrite_table_with_dead(table, meta, docs, Vec::new())
    }

    /// Like [`Self::rewrite_table`], but also releases the page trees of
    /// indexes that were removed from `meta` BEFORE this rebuild (DROP
    /// COLUMN): their roots are no longer in `meta.index_roots`, so the
    /// generic free loop below would skip them and the pages would leak for
    /// good — nothing else ever references them. Freed in the SAME write
    /// unit as the catalog switch, so a crash can never leave a committed
    /// catalog pointing at recycled pages.
    fn rewrite_table_with_dead(
        &mut self,
        table: &str,
        meta: &mut TableMeta,
        docs: Vec<Object>,
        dead_trees: Vec<(String, u32)>,
    ) -> Result<()> {
        self.rewrite_table_inner(table, meta, docs, true, dead_trees)
    }

    fn rewrite_table_inner(
        &mut self,
        table: &str,
        meta: &mut TableMeta,
        docs: Vec<Object>,
        free_old: bool,
        dead_trees: Vec<(String, u32)>,
    ) -> Result<()> {
        let mut tx = self.pager.begin_tx();
        if let Err(e) = self.rewrite_table_tx(&mut tx, table, meta, docs, free_old, dead_trees) {
            // Same failure semantics as the old inline body: the staged
            // pages never reach the data file (Tx's drop restores them),
            // and the in-memory catalog entry was already restored by
            // rewrite_table_tx's save-failure path or never swapped.
            self.pager.abort_tx(tx)?;
            return Err(e);
        }
        self.commit_pager_tx(tx)?;
        Ok(())
    }

    /// [`Self::rewrite_table_inner`] on a CALLER-OWNED transaction: the
    /// TRUNCATE batch rewrites several tables inside ONE pager transaction
    /// so a mid-list failure rolls the whole statement back (each table
    /// used to commit its own rebuild, leaving earlier tables emptied and
    /// committed while the failed statement never reached the journal —
    /// replicas kept rows the origin lost).
    fn rewrite_table_tx(
        &mut self,
        tx: &mut crate::pager::Tx,
        table: &str,
        meta: &mut TableMeta,
        docs: Vec<Object>,
        free_old: bool,
        dead_trees: Vec<(String, u32)>,
    ) -> Result<()> {
        let mut heap = Heap {
            pages: Vec::new(),
            overflow_free: meta.overflow_free.clone(),
            dropped: Vec::new(),
        };
        let cols: Vec<String> = meta.index_roots.keys().cloned().collect();
        // Release old storage BEFORE the rebuild: allocations below then pop
        // those pages back (same transaction, so the catalog switch and the
        // page rewrites are atomic; snapshots rebuild old versions from the
        // WAL and never observe the reuse).
        if free_old {
            // The docs being rewritten carried live overflow chains anchored
            // only by the old slots' head pointers; free them too or every
            // rewrite/TRUNCATE of a table with oversized documents orphans
            // the chains (the file grows without bound under churn).
            crate::heap::free_overflow_chains(&self.pager, tx, &meta.pages)?;
            for &p in &meta.pages {
                self.pager.free_page(tx, p)?;
            }
            for (root_key, &root) in &meta.index_roots {
                for p in BTree::open(root)
                    .collect_pages(&PageReader::current(&self.pager), tx)
                    .map_err(|e| index_err(root_key, e))?
                {
                    self.pager.free_page(tx, p)?;
                }
            }
            for (root_key, root) in &dead_trees {
                for p in BTree::open(*root)
                    .collect_pages(&PageReader::current(&self.pager), tx)
                    .map_err(|e| index_err(root_key, e))?
                {
                    self.pager.free_page(tx, p)?;
                }
            }
        }
        let mut pairs: Vec<(u64, Object)> = Vec::with_capacity(docs.len());
        for doc in &docs {
            // Rebuilds walk every row (ALTER/RENAME on a large table must
            // stay interruptible like every other long row loop).
            self.stmt_deadline.check()?;
            let loc = heap.insert(&self.pager, tx, doc)?;
            pairs.push((loc, doc.clone()));
        }
        let roots = self.build_trees(
            tx,
            &pairs,
            &cols,
            &cols
                .iter()
                .map(|c| meta.index_columns_of(c))
                .collect::<Vec<_>>(),
            &cols
                .iter()
                .map(|k| {
                    meta.index_defs
                        .iter()
                        .find(|d| d.name == *k)
                        .and_then(|d| d.path.clone())
                })
                .collect::<Vec<_>>(),
            &cols
                .iter()
                .map(|c| meta.root_key_unique(c))
                .collect::<Vec<_>>(),
            // Partial-index predicates: the rebuilt tree must hold exactly
            // the qualifying rows or every gated probe reads wrong.
            &cols
                .iter()
                .map(|k| {
                    meta.index_defs
                        .iter()
                        .find(|d| d.name == *k)
                        .and_then(|d| d.pred.as_deref())
                        .and_then(|p| parse_expr_text(p).ok())
                })
                .collect::<Vec<_>>(),
        )?;
        // Keep the previous catalog entry so a failed persist can restore the
        // in-memory map — after `?` below the tx is dropped and its staged
        // pages never reach the data file; the map must not keep pointing at
        // them, or a later successful save would persist the ghost pages and
        // orphan the real data.
        let prev_meta = self.tables.get(table).cloned();
        meta.pages = heap.pages;
        meta.index_roots = roots;
        // The rebuild drained the recycled-chain free list above: every
        // oversized document popped a page from it. Persist what is left —
        // keeping the pre-rebuild list would advertise pages the rebuild just
        // made live, and the next oversized insert would overwrite a live
        // document's chain (reads then fail with "overflow chain corrupt" or
        // return another row's bytes). The DML paths have always written the
        // heap's list back through `sync_table_layout`; the rebuild is the
        // one that did not.
        meta.overflow_free = heap.overflow_free;
        self.autoinc_cache.remove(table);
        self.tables
            .insert(table.to_string(), std::sync::Arc::new(meta.clone()));
        if let Err(e) = self.save_catalog_into(tx) {
            match prev_meta {
                Some(old) => {
                    *meta = old.as_ref().clone();
                    self.tables.insert(table.to_string(), old);
                }
                None => {
                    self.tables.remove(table);
                }
            }
            return Err(e);
        }
        Ok(())
    }

    /// Build one B+ tree per (root_key, columns, unique) spec, populated
    /// from the table's (locator, document) pairs. Single-column specs key
    /// by the bare value (legacy layout); multi-column specs key by
    /// `Value::Array` over the columns in order. Unique specs reject
    /// duplicates at insert time.
    #[allow(clippy::too_many_arguments)]
    fn build_trees(
        &mut self,
        tx: &mut crate::pager::Tx,
        pairs: &[(u64, Object)],
        root_keys: &[String],
        cols_per_key: &[Vec<String>],
        paths_per_key: &[Option<String>],
        unique_keys: &[bool],
        preds_per_key: &[Option<SqlExpr>],
    ) -> Result<std::collections::BTreeMap<String, u32>> {
        let mut roots = std::collections::BTreeMap::new();
        for i in 0..root_keys.len() {
            let root_key = &root_keys[i];
            let cols = &cols_per_key[i];
            let path = paths_per_key[i].as_deref();
            let unique = unique_keys[i];
            let pred = preds_per_key[i].as_ref();
            let mut tree = BTree::create(&self.pager, tx).map_err(|e| index_err(root_key, e))?;
            for (loc, doc) in pairs {
                // The backfill is the expensive half of CREATE INDEX on a big
                // table (the materialization before it samples already) —
                // without a check here the statement was uninterruptible
                // once it entered the tree builds.
                self.stmt_deadline.check()?;
                // Partial index: only pred-satisfying rows enter the tree
                // (NULL/missing fields fail the predicate like any WHERE).
                if let Some(p) = pred {
                    if !matches!(eval_expr(p, doc)?, Value::Bool(true)) {
                        continue;
                    }
                }
                let key = match path {
                    // JSON path index: extract from the column's JSON text
                    // with the exact lookup JSON_EXTRACT uses (design 005).
                    Some(p) => json_path_key(doc, &cols[0], p),
                    None => index_key_of(doc, cols),
                };
                if let Some(v) = key {
                    tree.insert(&self.pager, tx, v, *loc, unique)
                        .map_err(|e| index_err(root_key, e))?;
                }
            }
            roots.insert(root_key.clone(), tree.root);
        }
        Ok(roots)
    }

    fn autoinc_next_for(&mut self, table: &str, meta: &TableMeta) -> Result<i64> {
        if let Some(&n) = self.autoinc_cache.get(table) {
            return Ok(n);
        }
        let mut max: i64 = 0;
        if let Some(col) = &meta.autoinc {
            // Propagate read errors: defaulting to an empty scan would cache
            // a reset counter and hand out ids that collide after restart.
            let docs = Heap {
                pages: meta.pages.clone(),
                overflow_free: meta.overflow_free.clone(),
                dropped: Vec::new(),
            }
            .scan(&PageReader::current(&self.pager))?;
            for d in &docs {
                if let Some(Value::Int(i)) = d.get(col) {
                    max = max.max(*i);
                }
            }
        }
        let next = max + 1;
        self.autoinc_cache.insert(table.to_string(), next);
        Ok(next)
    }

    #[allow(clippy::too_many_arguments)]
    fn exec_update(
        &mut self,
        table: sqlparser::ast::TableWithJoins,
        mut assignments: Vec<sqlparser::ast::Assignment>,
        from: Option<sqlparser::ast::UpdateTableFromKind>,
        mut selection: Option<SqlExpr>,
        update_returning: Option<Vec<SelectItem>>,
    ) -> Result<ExecOutcome> {
        let sqlparser::ast::TableFactor::Table { name, alias, .. } = table.relation else {
            return err("only simple table names in UPDATE");
        };
        // MySQL-style `UPDATE t JOIN u ON … SET …` parses with the join in
        // `table.joins`; ignoring it would update every row of `t` with
        // values evaluated without `u`. Reject loudly instead.
        if !table.joins.is_empty() {
            return err("UPDATE ... JOIN is not supported (use UPDATE ... FROM)");
        }
        let tname = obj_name(&name);
        if self.tables.get(&tname).is_some_and(|m| m.is_view()) {
            return err(format!(
                "cannot UPDATE view {tname} (it is a view, not a table)"
            ));
        }
        if self.tables.get(&tname).is_some_and(|m| m.is_matview()) {
            return err(format!(
                "cannot UPDATE materialized view {tname} \
                 (REFRESH MATERIALIZED VIEW {tname} recomputes it)"
            ));
        }
        let tkey = alias
            .as_ref()
            .map(|a| a.name.value.clone())
            .unwrap_or_else(|| tname.clone());
        // ROWNUM has no row stream to number in an UPDATE's own SET/WHERE:
        // it reads NULL, and `NULL <= n` is TRUE under the documented total
        // order — an Oracle-style `UPDATE ... WHERE ROWNUM <= 1` would
        // silently rewrite every row. Fail loudly instead.
        if assignments.iter().any(|a| refs_rownum(&a.value))
            || selection.as_ref().is_some_and(refs_rownum)
        {
            return err("ROWNUM is not supported in UPDATE (use a subquery: WHERE id IN (SELECT ... WHERE ROWNUM <= n))");
        }
        // Outer scope for correlated subqueries: the target (name + alias)
        // plus the FROM tables (the FROM form evaluates WHERE/SET over the
        // merged image).
        let mut outer = OuterFrom::new();
        outer.insert(tname.clone());
        outer.insert(tkey.clone());
        if let Some(kind) = &from {
            match kind {
                sqlparser::ast::UpdateTableFromKind::BeforeSet(twjs)
                | sqlparser::ast::UpdateTableFromKind::AfterSet(twjs) => {
                    from_list_names(twjs, &mut outer);
                }
            }
        }
        for a in &mut assignments {
            self.subst_expr_cx_scoped(&mut a.value, &outer)?;
        }
        if let Some(sel) = &mut selection {
            self.subst_expr_cx_scoped(sel, &outer)?;
        }
        let mut meta = self
            .tables
            .get(&tname)
            .map(|a| a.as_ref().clone())
            .unwrap_or_default();

        // Fast path: probe-able WHERE on an indexed column — update the
        // affected rows in place instead of rewriting the whole table.
        if from.is_none() {
            if let Some(matches) =
                self.index_probe_cx(&tname, Some(tkey.as_str()), &selection, &Ctes::new())?
            {
                return self.exec_update_fast(
                    tname,
                    meta,
                    matches,
                    &assignments,
                    &selection,
                    &update_returning,
                    &outer,
                );
            }
        }

        let docs = self.table_docs_cx(&tname)?;
        let (out, changed_docs, old_changed, count) = match from {
            None => {
                // Plain UPDATE: assignments and WHERE see only target columns.
                let mut out = Vec::new();
                let mut changed_docs: Vec<Object> = Vec::new();
                let mut old_changed: Vec<Object> = Vec::new();
                let mut count = 0u64;
                for doc in docs {
                    if self.matches_cx_in(&selection, &doc, &outer)? {
                        old_changed.push(doc.clone());
                        let new_vals = self.eval_assignments_cx(&assignments, &doc, &outer)?;
                        let mut doc = doc;
                        for (col_name, v) in new_vals {
                            doc.insert(col_name, v);
                        }
                        count += 1;
                        changed_docs.push(doc.clone());
                        out.push(doc);
                    } else {
                        out.push(doc);
                    }
                }
                (out, changed_docs, old_changed, count)
            }
            Some(kind) => {
                // UPDATE ... FROM: each target row is matched against the
                // FROM tables' joined rows; the first qualifying match
                // supplies the values.
                let extra = match kind {
                    sqlparser::ast::UpdateTableFromKind::BeforeSet(v)
                    | sqlparser::ast::UpdateTableFromKind::AfterSet(v) => v,
                };
                let mut from_list = vec![sqlparser::ast::TableWithJoins {
                    relation: sqlparser::ast::TableFactor::Table {
                        name: name.clone(),
                        alias: alias.clone(),
                        args: None,
                        with_hints: vec![],
                        version: None,
                        with_ordinality: false,
                        partitions: vec![],
                        json_path: None,
                        sample: None,
                        index_hints: vec![],
                    },
                    joins: vec![],
                }];
                from_list.extend(extra);
                let merged = self.load_from_cx(&from_list, &None, &Ctes::new())?;
                let prefix = format!("{tkey}.");
                // First qualifying match per target content: every output
                // row with that content receives that image — including
                // byte-identical duplicate rows, which are distinct rows
                // despite sharing a key.
                let mut updates: std::collections::HashMap<Vec<u8>, Object> =
                    std::collections::HashMap::new();
                let mut changed_docs: Vec<Object> = Vec::new();
                let mut old_changed: Vec<Object> = Vec::new();
                for m in &merged {
                    let tdoc = target_doc_from_merged(m, &prefix);
                    let key = object_key(&tdoc);
                    if updates.contains_key(&key) {
                        continue; // first qualifying match wins
                    }
                    if !self.matches_cx_in(&selection, m, &outer)? {
                        continue;
                    }
                    old_changed.push(tdoc.clone());
                    let new_vals = self.eval_assignments_cx(&assignments, m, &outer)?;
                    let mut tdoc = tdoc;
                    for (col_name, v) in new_vals {
                        tdoc.insert(col_name, v);
                    }
                    changed_docs.push(tdoc.clone());
                    updates.insert(key, tdoc);
                }
                let mut count = 0u64;
                let out: Vec<Object> = docs
                    .into_iter()
                    .map(|doc| match updates.get(&object_key(&doc)) {
                        Some(img) => {
                            count += 1;
                            img.clone()
                        }
                        None => doc,
                    })
                    .collect();
                (out, changed_docs, old_changed, count)
            }
        };
        // Validate BEFORE writing: a failed UPDATE must not change data.
        // 自引用 FK 的父候选是本语句的最终像集合(不只是表里的旧像)。
        for doc in &out {
            // Full-table UPDATEs walk this loop (plus a parent-table scan
            // per FK inside check_fks_in) — keep the timeout armed.
            self.stmt_deadline.check()?;
            meta.check(doc)?;
            self.check_fks_in(&tname, &meta, doc, &out, Some(&out))?;
        }
        meta.check_unique(&out)?;
        // Parent-side FK: key values that disappear must not be referenced.
        // The self-reference child scan runs over the final images (`out`
        // IS the whole final table here — untouched rows included).
        self.check_fk_parent_delete_skipping(&tname, &old_changed, &out, &[], Some(&out))?;
        let changed = changed_docs.clone();
        // Row triggers: BEFORE over the pre/post image pairs while the old
        // state is still the committed truth, AFTER once the rewrite landed.
        let changed_cols: Vec<String> = assignments
            .iter()
            .filter_map(|a| match &a.target {
                sqlparser::ast::AssignmentTarget::ColumnName(c) => Some(obj_name(c)),
                _ => None,
            })
            .collect();
        let fire_update = !changed_docs.is_empty() && self.triggers_exist_for(&tname);
        if fire_update {
            for (old, new) in old_changed.iter().zip(changed_docs.iter()) {
                self.fire_row_triggers(
                    &tname,
                    true,
                    TriggerFireEvent::Update(Some(&changed_cols)),
                    Some(old),
                    Some(new),
                )?;
            }
        }
        // Sticky dotted-field marker on the LOCAL meta clone: rewrite_table
        // persists exactly this meta, so a self.tables write here would be
        // overwritten by the rewrite's own catalog save.
        if !meta.dotted_keys && out.iter().any(|d| d.keys().any(|k| k.contains('.'))) {
            meta.dotted_keys = true;
        }
        self.rewrite_table(&tname, &mut meta, out)?;
        if fire_update {
            for (old, new) in old_changed.iter().zip(changed_docs.iter()) {
                self.fire_row_triggers(
                    &tname,
                    false,
                    TriggerFireEvent::Update(Some(&changed_cols)),
                    Some(old),
                    Some(new),
                )?;
            }
        }
        if let Some(ret) = &update_returning {
            return project_returning(ret, &changed);
        }
        Ok(ExecOutcome::Affected(count))
    }

    #[allow(clippy::too_many_arguments)]
    fn exec_update_fast(
        &mut self,
        tname: String,
        meta: TableMeta,
        matches: Vec<(u64, Object)>,
        assignments: &[sqlparser::ast::Assignment],
        selection: &Option<SqlExpr>,
        update_returning: &Option<Vec<SelectItem>>,
        outer: &OuterFrom,
    ) -> Result<ExecOutcome> {
        let mut updates: Vec<(u64, Object, Object)> = Vec::new(); // (loc, old, new)
        for (loc, doc) in matches {
            if !self.matches_cx_in(selection, &doc, outer)? {
                continue; // probe col matched; some other conjunct did not
            }
            let mut doc = doc;
            // The pre-update image must be captured before assignments run —
            // it drives the old-key removal in the apply loop below; pushing
            // the mutated doc as both old and new leaves stale entries.
            let old_doc = doc.clone();
            let new_vals = self.eval_assignments_cx(assignments, &doc, outer)?;
            for (col_name, v) in new_vals {
                doc.insert(col_name, v);
            }
            meta.check(&doc)?;
            updates.push((loc, old_doc, doc));
        }
        // 子侧 FK 在收集完本语句全部最终像之后统一校验:自引用/行间引用
        // 的父候选包含批次自身。零命中在下方早退(空批次检查是 no-op)。
        if updates.is_empty() {
            if let Some(ret) = update_returning {
                return project_returning(ret, &[]);
            }
            return Ok(ExecOutcome::Affected(0));
        }
        // Self-referential FKs resolve parents against the statement's
        // COMPLETE final state (pre-state minus replaced old images plus the
        // new images); the pre-state heap alone would satisfy keys this
        // statement vacates (`SET id = 3, p = 1 WHERE id = 1`). Only
        // self-FK tables pay the extra table load.
        let self_final: Option<Vec<Object>> =
            if meta.foreign_keys.iter().any(|(_, rt, _)| rt == &tname) {
                let old_keys: std::collections::BTreeSet<Vec<u8>> =
                    updates.iter().map(|(_, o, _)| object_key(o)).collect();
                let mut final_state = self.table_docs_cx(&tname)?;
                final_state.retain(|d| !old_keys.contains(&object_key(d)));
                final_state.extend(updates.iter().map(|(_, _, n)| n.clone()));
                Some(final_state)
            } else {
                None
            };
        {
            let batch: Vec<Object> = updates.iter().map(|(_, _, n)| n.clone()).collect();
            for doc in &batch {
                // Big UPDATEs (with a FK, check_fks_in also scans the parent
                // table per row) must stay interruptible.
                self.stmt_deadline.check()?;
                self.check_fks_in(&tname, &meta, doc, &batch, self_final.as_deref())?;
            }
        }
        // Parent-side FK check before any page is touched. `updates` rows
        // are the only ones whose key values can disappear; their new docs
        // are the survivors (referenced columns are unique in practice).
        let old_docs: Vec<Object> = updates.iter().map(|(_, o, _)| o.clone()).collect();
        let new_docs: Vec<Object> = updates.iter().map(|(_, _, n)| n.clone()).collect();
        self.check_fk_parent_delete_skipping(
            &tname,
            &old_docs,
            &new_docs,
            &[],
            self_final.as_deref(),
        )?;
        // Pre-statement docs for the legacy whole-set unique check below —
        // loaded only when that check can actually run (a constraint column
        // without a tree). Tables with full trees enforce uniqueness in the
        // apply loop; loading every doc here made single-row UPDATE loops
        // quadratic.
        let legacy_check = (meta.primary_key.is_some() || !meta.unique.is_empty())
            && meta
                .primary_key
                .iter()
                .chain(meta.unique.iter())
                .any(|c| !meta.index_roots.contains_key(c));
        let all_docs: Option<Vec<Object>> = if legacy_check {
            Some(self.table_docs_cx(&tname)?)
        } else {
            None
        };
        let mut heap = Heap {
            pages: meta.pages.clone(),
            overflow_free: meta.overflow_free.clone(),
            dropped: Vec::new(),
        };
        let mut roots = meta.index_roots.clone();
        let idx_specs = idx_specs(&meta, &roots);
        // BEFORE UPDATE over the pre/post pairs while the old images are
        // still the committed truth (rows update in place below).
        let update_changed_cols: Vec<String> = assignments
            .iter()
            .filter_map(|a| match &a.target {
                sqlparser::ast::AssignmentTarget::ColumnName(c) => Some(obj_name(c)),
                _ => None,
            })
            .collect();
        let fire_update = self.triggers_exist_for(&tname);
        if fire_update {
            for (_, old, new) in &updates {
                self.fire_row_triggers(
                    &tname,
                    true,
                    TriggerFireEvent::Update(Some(&update_changed_cols)),
                    Some(old),
                    Some(new),
                )?;
            }
        }
        let mut tx = self.pager.begin_tx();
        // Pass 1: drop every updated row's old index entries before any
        // replacement lands — a multi-row unique-key shift (SET id = id + 1,
        // key swaps between rows) must not collide with a not-yet-replaced
        // row's still-present old key.
        for (loc, old_doc, _) in &updates {
            if let Err(e) =
                reindex_remove(&self.pager, &mut tx, &idx_specs, &mut roots, old_doc, *loc)
            {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // Pass 2: apply the new images.
        for i in 0..updates.len() {
            let (loc, new_doc) = (updates[i].0, updates[i].2.clone());
            let page = crate::heap::unpack_loc(loc).0;
            let before = heap.page_docs(&PageReader::current(&self.pager), &tx, page)?;
            // Locators of the rows not yet processed *before* the repack
            // fixup below mutates them: a survivor move naming one of these
            // slots is the pending row's own image, and repointing it would
            // resurrect the old-key entry pass 1 just removed.
            let pending_locs: Vec<u64> = updates.iter().skip(i + 1).map(|(l, _, _)| *l).collect();
            let out = heap.replace(&self.pager, &mut tx, loc, &new_doc)?;
            // An in-page re-pack moved this page's survivors: pending locators
            // must follow, or a later update would target whatever document
            // now occupies the stale slot.
            if !out.moved.is_empty() {
                for pending in updates.iter_mut().skip(i + 1) {
                    if let Some((_, new_l)) = out.moved.iter().find(|(old, _)| *old == pending.0) {
                        pending.0 = *new_l;
                    }
                }
            }
            for (old_l, new_l) in &out.moved {
                // Current row: entries removed in pass 1, new entry lands at
                // `out.placed` below. Pending row: same, in its own
                // iteration. Already-processed rows (and untouched rows)
                // must be repointed — their new/current image is what sat in
                // that slot, and skipping them leaves a stale index entry.
                if *old_l == loc || pending_locs.contains(old_l) {
                    continue;
                }
                if let Err(e) = reindex_repoint(
                    &self.pager,
                    &mut tx,
                    &idx_specs,
                    &mut roots,
                    &before,
                    *old_l,
                    *new_l,
                ) {
                    self.pager.abort_tx(tx)?;
                    return Err(e);
                }
            }
            if let Err(e) = reindex_insert(
                &self.pager,
                &mut tx,
                &idx_specs,
                &mut roots,
                &new_doc,
                out.placed,
            ) {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // Legacy files whose constraint columns predate trees keep the
        // whole-set duplicate check (mirrors the INSERT path); tables with
        // trees enforce uniqueness through the apply loop above.
        if legacy_check {
            let combined: Vec<Object> = all_docs
                .expect("pre-statement docs loaded for the legacy check")
                .into_iter()
                .map(|d| match updates.iter().find(|(_, old, _)| *old == d) {
                    Some((_, _, new)) => new.clone(),
                    None => d,
                })
                .collect();
            if let Err(e) = meta.check_unique(&combined) {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // Emptied heap pages are released inside this transaction so later
        // statements reuse them instead of growing the file.
        for p in std::mem::take(&mut heap.dropped) {
            self.pager.free_page(&mut tx, p)?;
        }
        let dotted_now = self.note_dotted_fields(&tname, updates.iter().map(|(_, _, new)| new));
        if dotted_now
            || heap.pages != meta.pages
            || roots != meta.index_roots
            || heap.overflow_free != meta.overflow_free
        {
            self.sync_table_layout(
                &mut tx,
                &tname,
                heap.pages.clone(),
                roots,
                heap.overflow_free.clone(),
            )?;
        }
        self.commit_pager_tx(tx)?;
        // AFTER UPDATE once the new images are committed.
        if fire_update {
            for (_, old, new) in &updates {
                self.fire_row_triggers(
                    &tname,
                    false,
                    TriggerFireEvent::Update(Some(&update_changed_cols)),
                    Some(old),
                    Some(new),
                )?;
            }
        }
        // Explicit ids may bump the AUTOINCREMENT watermark.
        if let Some(col) = &meta.autoinc {
            if assignments
                .iter()
                .any(|a| matches!(&a.target, sqlparser::ast::AssignmentTarget::ColumnName(c) if obj_name(c) == *col))
            {
                self.autoinc_cache.remove(&tname);
            }
        }
        let changed: Vec<Object> = updates.into_iter().map(|(_, _, d)| d).collect();
        if let Some(ret) = update_returning {
            return project_returning(ret, &changed);
        }
        Ok(ExecOutcome::Affected(changed.len() as u64))
    }

    fn exec_delete(
        &mut self,
        from: sqlparser::ast::FromTable,
        using: Option<Vec<sqlparser::ast::TableWithJoins>>,
        mut selection: Option<SqlExpr>,
        returning: Option<Vec<SelectItem>>,
    ) -> Result<ExecOutcome> {
        let sqlparser::ast::FromTable::WithFromKeyword(tables) = from else {
            return err("unsupported DELETE form");
        };
        if tables.len() != 1 {
            return err("DELETE from exactly one table");
        }
        // `DELETE t FROM t JOIN u …` / `DELETE FROM t JOIN u …` parse with
        // the join in `tables[0].joins`; dropping it would delete every row
        // regardless of the join condition. Reject loudly (use USING).
        if !tables[0].joins.is_empty() {
            return err("DELETE ... JOIN is not supported (use DELETE ... USING)");
        }
        let sqlparser::ast::TableFactor::Table { name, alias, .. } = tables[0].relation.clone()
        else {
            return err("only simple table names in DELETE");
        };
        let tname = obj_name(&name);
        if self.tables.get(&tname).is_some_and(|m| m.is_view()) {
            return err(format!(
                "cannot DELETE from view {tname} (it is a view, not a table)"
            ));
        }
        if self.tables.get(&tname).is_some_and(|m| m.is_matview()) {
            return err(format!(
                "cannot DELETE from materialized view {tname} \
                 (REFRESH MATERIALIZED VIEW {tname} recomputes it)"
            ));
        }
        let tkey = alias
            .as_ref()
            .map(|a| a.name.value.clone())
            .unwrap_or_else(|| tname.clone());
        // ROWNUM has no row stream to number in a DELETE's own WHERE: it
        // reads NULL, and `NULL <= n` is TRUE under the documented total
        // order — an Oracle-style `DELETE ... WHERE ROWNUM <= 1` would
        // silently mass-delete. Fail loudly instead.
        if selection.as_ref().is_some_and(refs_rownum) {
            return err("ROWNUM is not supported in DELETE (use a subquery: WHERE id IN (SELECT ... WHERE ROWNUM <= n))");
        }
        // Outer scope for correlated subqueries: the target (name + alias)
        // plus the USING tables (the USING form evaluates WHERE over the
        // merged image).
        let mut outer = OuterFrom::new();
        outer.insert(tname.clone());
        outer.insert(tkey.clone());
        if let Some(using) = &using {
            from_list_names(using, &mut outer);
        }
        if let Some(sel) = &mut selection {
            self.subst_expr_cx_scoped(sel, &outer)?;
        }
        let mut meta = self
            .tables
            .get(&tname)
            .map(|a| a.as_ref().clone())
            .unwrap_or_default();
        // Fast path: probe-able WHERE on an indexed column — remove the
        // matching rows in place (page re-pack) instead of rewriting the
        // whole table.
        if using.is_none() {
            if let Some(matches) =
                self.index_probe_cx(&tname, Some(tkey.as_str()), &selection, &Ctes::new())?
            {
                return self.exec_delete_fast(tname, meta, matches, &selection, &returning, &outer);
            }
        }
        let docs = self.table_docs_cx(&tname)?;
        let (kept, removed) = if let Some(using) = using {
            // DELETE ... USING: qualify over the joined rows and mark the
            // target docs whose combination satisfies WHERE.
            let mut from_list = vec![tables[0].clone()];
            from_list.extend(using);
            let merged = self.load_from_cx(&from_list, &None, &Ctes::new())?;
            let prefix = format!("{tkey}.");
            let mut rm: std::collections::BTreeSet<Vec<u8>> = std::collections::BTreeSet::new();
            for m in &merged {
                if !self.matches_cx_in(&selection, m, &outer)? {
                    continue;
                }
                let tdoc = target_doc_from_merged(m, &prefix);
                rm.insert(object_key(&tdoc));
            }
            let mut kept = Vec::new();
            let mut removed = Vec::new();
            for doc in docs {
                if rm.contains(&object_key(&doc)) {
                    removed.push(doc);
                } else {
                    kept.push(doc);
                }
            }
            (kept, removed)
        } else {
            let mut kept = Vec::new();
            let mut removed = Vec::new();
            for doc in docs {
                if self.matches_cx_in(&selection, &doc, &outer)? {
                    removed.push(doc);
                } else {
                    kept.push(doc);
                }
            }
            (kept, removed)
        };
        let count = removed.len() as u64;
        // The self-reference child scan runs over the FINAL state (`kept`):
        // rows deleted by this same statement cannot end up orphaned, so
        // `DELETE FROM self_ref_table` may clear parent and child rows
        // together (SQLite/PG statement-final semantics).
        self.check_fk_parent_delete_skipping(&tname, &removed, &[], &[], Some(&kept))?;
        // BEFORE DELETE while the rows are still the committed truth.
        let fire_delete = !removed.is_empty() && self.triggers_exist_for(&tname);
        if fire_delete {
            for doc in &removed {
                self.fire_row_triggers(&tname, true, TriggerFireEvent::Delete, Some(doc), None)?;
            }
        }
        self.rewrite_table(&tname, &mut meta, kept)?;
        if fire_delete {
            for doc in &removed {
                self.fire_row_triggers(&tname, false, TriggerFireEvent::Delete, Some(doc), None)?;
            }
        }
        if let Some(ret) = &returning {
            return project_returning(ret, &removed);
        }
        Ok(ExecOutcome::Affected(count))
    }

    fn exec_delete_fast(
        &mut self,
        tname: String,
        meta: TableMeta,
        matches: Vec<(u64, Object)>,
        selection: &Option<SqlExpr>,
        returning: &Option<Vec<SelectItem>>,
        outer: &OuterFrom,
    ) -> Result<ExecOutcome> {
        let mut targets: Vec<(u64, Object)> = Vec::new();
        for (loc, doc) in matches {
            if self.matches_cx_in(selection, &doc, outer)? {
                targets.push((loc, doc));
            }
        }
        if targets.is_empty() {
            if let Some(ret) = returning {
                return project_returning(ret, &[]);
            }
            return Ok(ExecOutcome::Affected(0));
        }
        // Parent-side FK check before any page is touched. The self-reference
        // child scan runs over the final state (pre-state minus the removed
        // rows), so deleting parent and child rows of a self-FK table in one
        // statement is legal; only self-FK tables pay the extra table load.
        let removed_docs: Vec<Object> = targets.iter().map(|(_, d)| d.clone()).collect();
        let self_final: Option<Vec<Object>> =
            if meta.foreign_keys.iter().any(|(_, rt, _)| rt == &tname) {
                let rm: std::collections::BTreeSet<Vec<u8>> =
                    targets.iter().map(|(_, d)| object_key(d)).collect();
                Some(
                    self.table_docs_cx(&tname)?
                        .into_iter()
                        .filter(|d| !rm.contains(&object_key(d)))
                        .collect(),
                )
            } else {
                None
            };
        self.check_fk_parent_delete_skipping(
            &tname,
            &removed_docs,
            &[],
            &[],
            self_final.as_deref(),
        )?;
        let mut heap = Heap {
            pages: meta.pages.clone(),
            overflow_free: meta.overflow_free.clone(),
            dropped: Vec::new(),
        };
        let mut roots = meta.index_roots.clone();
        let idx_specs = idx_specs(&meta, &roots);
        // BEFORE DELETE while the rows are still the committed truth.
        let fire_delete = self.triggers_exist_for(&tname);
        if fire_delete {
            for (_, doc) in &targets {
                self.fire_row_triggers(&tname, true, TriggerFireEvent::Delete, Some(doc), None)?;
            }
        }
        let mut tx = self.pager.begin_tx();
        let affected: std::collections::BTreeSet<u32> = targets
            .iter()
            .map(|(l, _)| crate::heap::unpack_loc(*l).0)
            .collect();
        let mut before = Vec::new();
        for pid in affected {
            before.extend(heap.page_docs(&PageReader::current(&self.pager), &tx, pid)?);
        }
        let locs: Vec<u64> = targets.iter().map(|(l, _)| *l).collect();
        let moves = heap.remove_many(&self.pager, &mut tx, &locs)?;
        for (loc, doc) in &targets {
            reindex_remove(&self.pager, &mut tx, &idx_specs, &mut roots, doc, *loc)?;
        }
        for (old_l, new_l) in &moves {
            reindex_repoint(
                &self.pager,
                &mut tx,
                &idx_specs,
                &mut roots,
                &before,
                *old_l,
                *new_l,
            )?;
        }
        // Emptied heap pages are released inside this transaction so later
        // statements reuse them instead of growing the file.
        for p in std::mem::take(&mut heap.dropped) {
            self.pager.free_page(&mut tx, p)?;
        }
        if heap.pages != meta.pages
            || roots != meta.index_roots
            || heap.overflow_free != meta.overflow_free
        {
            self.sync_table_layout(
                &mut tx,
                &tname,
                heap.pages.clone(),
                roots,
                heap.overflow_free.clone(),
            )?;
        }
        self.commit_pager_tx(tx)?;
        // Deleted rows may have held the AUTOINCREMENT watermark.
        self.autoinc_cache.remove(&tname);
        let removed: Vec<Object> = targets.into_iter().map(|(_, d)| d).collect();
        if fire_delete {
            for doc in &removed {
                self.fire_row_triggers(&tname, false, TriggerFireEvent::Delete, Some(doc), None)?;
            }
        }
        let count = removed.len() as u64;
        if let Some(ret) = returning {
            return project_returning(ret, &removed);
        }
        Ok(ExecOutcome::Affected(count))
    }

    fn exec_create_index(&mut self, idx: sqlparser::ast::CreateIndex) -> Result<ExecOutcome> {
        // Clause-level guard: every index option the engine cannot honor must
        // be refused, not dropped (a filtered/INCLUDE index silently becomes
        // a different index).
        if !idx.include.is_empty() {
            return err("CREATE INDEX INCLUDE is not supported");
        }
        // Partial index (CREATE INDEX … WHERE): the predicate is validated
        // against the table below; the tree then holds only the qualifying
        // rows and every read must prove the query implies the predicate
        // before probing (superset safety, see [`query_implies_pred`]).
        let pred_expr = match &idx.predicate {
            Some(e) => {
                let p = validate_partial_pred(e)?;
                Some(p)
            }
            None => None,
        };
        if idx.using.is_some() {
            return err("index types (USING ...) are not supported");
        }
        if idx.nulls_distinct.is_some() {
            return err("NULLS [NOT] DISTINCT is not supported");
        }
        if idx.concurrently {
            return err("CREATE INDEX CONCURRENTLY is not supported");
        }
        if !idx.with.is_empty() || !idx.index_options.is_empty() {
            return err("index storage options are not supported");
        }
        let table = obj_name(&idx.table_name);
        if !self.internal_ddl
            && (crate::useradmin::is_user_table(&table) || crate::engine::is_system_table(&table))
        {
            // An index built on the internal user tables is invisible to
            // dumps (user tables replay through their own statement
            // channel) yet lands in the table's schema hash — an embedded
            // node would silently diverge from its cluster's digest.
            return err(format!("cannot index the internal table {table}"));
        }
        if self.tables.get(&table).is_some_and(|m| m.is_view()) {
            return err(format!(
                "cannot index view {table} (it is a view, not a table)"
            ));
        }
        let iname = idx
            .name
            .as_ref()
            .map(obj_name)
            .unwrap_or_else(|| format!("idx_{}", table));
        // Reserved for the table's own PRIMARY KEY/UNIQUE constraint
        // indexes; a user index with such a name would shadow them.
        if iname.starts_with("sqlite_autoindex_") {
            return err(
                "index names beginning with sqlite_autoindex_ are reserved for \
                 PRIMARY KEY/UNIQUE constraint indexes",
            );
        }
        // System/internal table names are unusable as index names: the
        // server's write gate classifies DROP INDEX by name and would
        // refuse to ever drop it (no other DROP INDEX entry point exists).
        if is_system_table(&iname) || is_internal_table(&iname) {
            return err(format!(
                "index name {iname} is reserved for a system/internal table"
            ));
        }
        // Index names share a database-wide namespace (SQLite semantics):
        // a name taken by any table blocks reuse elsewhere.
        let owner = self.tables.values().find(|m| m.indexes.contains(&iname));
        if owner.is_some() {
            if idx.if_not_exists {
                return Ok(ExecOutcome::Affected(0));
            }
            return err(format!("index {iname} already exists"));
        }
        let Some(mut meta) = self.tables.get(&table).map(|a| a.as_ref().clone()) else {
            return err(format!("table {table} does not exist"));
        };
        // Partial-predicate columns must be declared: a ghost name would
        // read NULL on every row and silently empty the tree.
        if let Some(p) = &pred_expr {
            let mut refs = std::collections::BTreeSet::new();
            pred_columns(p, &mut refs);
            for c in &refs {
                if !meta.columns.contains(c) {
                    return err(format!("column {c} does not exist"));
                }
            }
        }
        // Parse the indexed columns: plain identifiers only (expression
        // indexes stay unsupported), each must exist, duplicates rejected.
        if idx.columns.is_empty() {
            return err("CREATE INDEX requires at least one column");
        }
        let mut cols: Vec<String> = Vec::with_capacity(idx.columns.len());
        // JSON path index (design 005): exactly one column of the form
        // JSON_EXTRACT(col, '$.path'). Tree keys are values extracted from
        // the column's JSON text — the same lookup JSON_EXTRACT evaluates
        // at query time, so probes and inline evaluation cannot diverge.
        let mut path: Option<String> = None;
        for c in &idx.columns {
            // Direction is part of the index definition: accepting DESC here
            // and silently building ASC (as before) creates an index whose
            // ORDER BY optimization direction is the opposite of what was
            // declared. Same refusal discipline as INCLUDE/WHERE/USING.
            if c.column.options.asc == Some(false) {
                return err("descending indexes (CREATE INDEX ... DESC) are not supported");
            }
            if let SqlExpr::Function(f) = &c.column.expr {
                let fname = f.name.to_string().to_uppercase();
                if fname == "JSON_EXTRACT" {
                    if path.is_some() || cols.len() > 1 {
                        return err("a JSON path index is single-column: one JSON_EXTRACT(col, \
                             '$.path') term per index");
                    }
                    let (col, p) = parse_json_index_column(f)?;
                    if !meta.columns.contains(&col) {
                        return err(format!("column {col} does not exist"));
                    }
                    cols.push(col);
                    path = Some(p);
                    continue;
                }
                return err(
                    "expression indexes are not supported (only JSON_EXTRACT(col, '$.path'))",
                );
            }
            let col = match &c.column.expr {
                SqlExpr::Identifier(i) => i.value.clone(),
                other => expr_name(other),
            };
            if !meta.columns.contains(&col) {
                return err(format!("column {col} does not exist"));
            }
            if cols.contains(&col) {
                return err(format!("duplicate column name: {col} (in index {iname})"));
            }
            cols.push(col);
        }
        // UNIQUE path indexes are refused, not degraded: uniqueness
        // enforcement is column-based (meta.unique / constraint_unique and
        // the OR REPLACE displacement machinery do not know paths), and a
        // tree-level-only unique would leave UPDATE displacements unguarded.
        if idx.unique && path.is_some() {
            return err(
                "UNIQUE JSON path indexes are not supported (uniqueness enforcement \
                 is column-based)",
            );
        }
        if path.is_some() && pred_expr.is_some() {
            return err("a partial index cannot combine with a JSON path index");
        }
        let root_key = if path.is_some() {
            // Path trees are keyed by extracted values, never column values:
            // they always key by the index name and never reuse a column
            // tree (a scalar tree on the same column has a different key
            // shape; sharing one would mix value kinds in one tree).
            iname.clone()
        } else if cols.len() > 1 {
            iname.clone()
        } else if pred_expr.is_some() {
            // A partial tree holds a SUBSET of the column's rows — it must
            // never occupy the column-name root slot where ungated readers
            // (conflict probes, constraint lookups) expect a full tree.
            iname.clone()
        } else {
            cols[0].clone()
        };
        // root_key collision guard: `index_roots` is a mixed pool — column-
        // named constraint/single-column trees plus index-name-keyed
        // composite trees — and `BTreeMap::append` silently OVERWRITES an
        // existing key. A collision with a DIFFERENTLY-keyed tree (an index
        // named exactly like the PK column, a single-column index on a
        // column whose root holds a composite tree) would replace a live
        // tree: uniqueness enforcement would probe a tree keyed with a
        // different shape, old and new rows would mix key types in one
        // tree, and the overwritten tree's pages would leak — refuse.
        // The one benign case REUSES the existing tree instead: a second
        // index over exactly the same single column (e.g. UNIQUE INDEX on a
        // constraint column). Both indexes read the same tree; single-
        // column uniqueness is enforced through `meta.unique` (pushed
        // below), never through tree-level rejection. `IF NOT EXISTS` does
        // not apply: it is about the index NAME, and the colliding index
        // is a different one.
        let mut reuse_root: Option<u32> = None;
        if let Some(&root) = meta.index_roots.get(&root_key) {
            if path.is_none() && pred_expr.is_none() && meta.index_columns_of(&root_key) == cols {
                reuse_root = Some(root);
            } else {
                return err(format!(
                    "index root key {root_key} is already in use by another index or \
                     constraint; choose a different index name or column"
                ));
            }
        }
        // Single-column UNIQUE INDEX rides the constraint machinery: the
        // column joins meta.unique, so inserts/updates enforce duplicates
        // from here on. Composite unique indexes cannot use the per-column
        // container — their tree enforces uniqueness itself (unique insert).
        // A PARTIAL unique enforces only among its qualifying rows via the
        // tree; the column must NOT join meta.unique (that would enforce
        // globally, far beyond the predicate's scope).
        let composite = cols.len() > 1;
        if idx.unique && !composite && pred_expr.is_none() && !meta.unique.contains(&cols[0]) {
            let docs = self.table_docs_cx(&table)?;
            meta.unique.push(cols[0].clone());
            meta.check_unique(&docs)?;
        }
        // Build the B+ tree over the existing rows. Single-column trees are
        // non-unique at the tree level (duplicates allowed, lookups collect
        // every match); composite UNIQUE trees enforce duplicates on insert.
        let mut tx = self.pager.begin_tx();
        match reuse_root {
            // Same-semantics reuse: no tree build, the existing root stays
            // authoritative for both indexes.
            Some(root) => {
                meta.index_roots.insert(root_key.clone(), root);
            }
            None => {
                let pairs = self.table_pairs_cx(&table)?;
                let mut roots = self.build_trees(
                    &mut tx,
                    &pairs,
                    std::slice::from_ref(&root_key),
                    std::slice::from_ref(&cols),
                    std::slice::from_ref(&path),
                    std::slice::from_ref(&idx.unique),
                    std::slice::from_ref(&pred_expr),
                )?;
                meta.index_roots.append(&mut roots);
            }
        }
        meta.index_defs.push(IndexDef {
            name: iname.clone(),
            columns: cols,
            unique: idx.unique,
            path: path.clone(),
            pred: pred_expr.as_ref().map(|p| p.to_string()),
        });
        meta.indexes.push(iname);
        let prev_meta = self.tables.get(&table).cloned();
        self.tables.insert(table.clone(), std::sync::Arc::new(meta));
        // The catalog rides the SAME write unit as the tree pages: committing
        // the tree first and saving the catalog in a second transaction left
        // a crash window holding a committed tree no catalog references (the
        // pages would leak for good — nothing would ever free them).
        let persisted = self
            .save_catalog_into(&mut tx)
            .and_then(|()| self.commit_pager_tx(tx));
        if let Err(e) = persisted {
            // The tx dropped without committing: its staged tree pages went
            // back to the reusable pool. The in-memory entry must not keep
            // pointing at them — a later write would land index entries on
            // pages a concurrent allocation may hand to someone else.
            match prev_meta {
                Some(old) => {
                    self.tables.insert(table, old);
                }
                None => {
                    self.tables.remove(&table);
                }
            }
            return Err(e);
        }
        Ok(ExecOutcome::Affected(0))
    }

    /// All-or-nothing validation for ALTER TABLE: every operation is checked
    /// against a simulated meta (columns / PK / CHECKs evolve op by op) so a
    /// failure in a later operation cannot leave earlier ones committed —
    /// each rewrite persists its own write unit, so a mid-statement failure
    /// used to leave the statement half-applied (with no journal entry for
    /// the applied part, diverging replicas until repair). Also fronts the
    /// per-op existence/duplication checks the apply loop historically
    /// skipped (DROP of a missing column silently "succeeded").
    #[allow(clippy::too_many_lines)]
    fn validate_alter_ops(
        &self,
        base: &TableMeta,
        tname: &str,
        ops: &[sqlparser::ast::AlterTableOperation],
    ) -> Result<()> {
        use sqlparser::ast::AlterTableOperation as Op;
        // RENAME TABLE returns from the apply loop early; anything after it
        // in the same statement was silently discarded.
        if ops.iter().any(|o| matches!(o, Op::RenameTable { .. })) && ops.len() > 1 {
            return err(
                "ALTER TABLE ... RENAME TO must be the only operation in the statement".to_string(),
            );
        }
        let mut columns: Vec<String> = base.columns.clone();
        let mut pk: Option<String> = base.primary_key.clone();
        let mut checks: Vec<String> = base.checks.clone();
        // Index namespaces evolve too (DROP COLUMN kills trees over the
        // dropped column); kept as owned copies so the rename-collision
        // check sees the state earlier operations produced.
        let mut roots: std::collections::BTreeSet<String> =
            base.index_roots.keys().cloned().collect();
        let mut index_defs: Vec<IndexDef> = base.index_defs.clone();
        // Column renames applied so far in this statement, so a later DROP
        // COLUMN matches FK references under their post-rename spelling
        // (`RENAME COLUMN a TO b, DROP COLUMN b` must still see the child
        // FKs that the apply loop will rewrite a→b).
        let mut renamed: Vec<(String, String)> = Vec::new();
        for op in ops {
            match op {
                Op::AddColumn { column_def, .. } => {
                    let col = &column_def.name.value;
                    if columns.contains(col) {
                        return err(format!("duplicate column name: {col}"));
                    }
                    let mut add_not_null = false;
                    let mut default_text: Option<String> = None;
                    for opt in &column_def.options {
                        use sqlparser::ast::ColumnOption as CO;
                        match &opt.option {
                            CO::Check(c) => {
                                if expr_calls_wall_clock(&c.expr) {
                                    return err(
                                        "CHECK constraints cannot call wall-clock or random \
                                         functions (NOW/SYSDATE/CURRENT_TIMESTAMP/GETDATE/RAND); \
                                         every node would evaluate a different value",
                                    );
                                }
                                // Column references must resolve (the new
                                // column itself is in scope for its own
                                // CHECK): the apply loop rejects unknown
                                // references MID-STATEMENT, after earlier
                                // operations of the same ALTER already
                                // committed — catch it here instead.
                                let mut refs = Vec::new();
                                check_expr_column_refs(&c.expr, &mut refs)?;
                                for r in refs {
                                    if r != *col && !columns.contains(&r) {
                                        return err(format!(
                                            "CHECK constraint references unknown column {r}"
                                        ));
                                    }
                                }
                                // Mirror the apply loop: later operations in
                                // the same statement must see this CHECK in
                                // the simulated state, or `DROP COLUMN` of
                                // the just-added column passes validation and
                                // half-applies.
                                checks.push(format!("{}", c.expr));
                            }
                            CO::Default(e) => {
                                // The apply loop constant-folds every new
                                // DEFAULT for the backfill; pre-empt the same
                                // failure here so a later operation failing
                                // on it can never leave an earlier one
                                // committed.
                                let text = default_expr_text(e);
                                let expr = parse_expr_text(&text)?;
                                eval_const(&expr)?;
                                default_text = Some(text);
                            }
                            CO::NotNull => add_not_null = true,
                            CO::PrimaryKey { .. }
                            | CO::Unique { .. }
                            | CO::ForeignKey(_)
                            | CO::DialectSpecific(_) => {
                                return err(format!(
                                    "constraint options are not supported on ADD COLUMN {col}"
                                ));
                            }
                            // Same parity as the apply loop (and CREATE
                            // TABLE): swallowing these silently degraded the
                            // column to a plain one.
                            CO::Generated { .. }
                            | CO::Materialized(_)
                            | CO::Ephemeral(_)
                            | CO::Alias(_) => {
                                return err(format!(
                                    "generated/computed columns are not supported \
                                     (ADD COLUMN {col})"
                                ));
                            }
                            CO::Null => {}
                            _ => {
                                return err(format!(
                                    "unsupported column option on ADD COLUMN {col}"
                                ))
                            }
                        }
                    }
                    // A new column's default can only arrive in this very
                    // definition (the apply loop registers it in the same
                    // pass, before the NOT NULL rule is judged).
                    if add_not_null
                        && !column_def
                            .options
                            .iter()
                            .any(|o| matches!(o.option, sqlparser::ast::ColumnOption::Default(_)))
                    {
                        return err(format!(
                            "cannot add NOT NULL column {col} without a DEFAULT"
                        ));
                    }
                    // Backfill-vs-CHECK parity with the apply loop: every
                    // check — including one riding on THIS ADD COLUMN — is
                    // evaluated against the backfilled rows there; without
                    // this simulation a later operation in the same ALTER
                    // commits first and the statement half-applies.
                    if let Some(text) = &default_text {
                        if !checks.is_empty() {
                            let fill = eval_const(&parse_expr_text(text)?)?;
                            for d in self.table_docs_cx(tname)? {
                                let mut filled = d;
                                if !filled.contains_key(col) {
                                    filled.insert(col.clone(), fill.clone());
                                }
                                for c in &checks {
                                    let e = parse_expr_text(c)?;
                                    if matches!(
                                        check_expr_outcome(&e, &filled)?,
                                        CheckOutcome::Fail
                                    ) {
                                        return err(format!("CHECK constraint failed: {c}"));
                                    }
                                }
                            }
                        }
                    }
                    columns.push(col.clone());
                }
                Op::DropColumn { column_names, .. } => {
                    for id in column_names {
                        let name = &id.value;
                        if !columns.contains(name) {
                            return err(format!("column {name} does not exist"));
                        }
                        if pk.as_deref() == Some(name.as_str()) {
                            return err("cannot drop a PRIMARY KEY column");
                        }
                        // A partial-index predicate naming the column would
                        // silently read NULL after the drop — every row would
                        // fall out of the tree at the next rewrite. Refuse
                        // like CHECK constraints do (drop the index first).
                        if let Some(bad) = index_defs.iter().find_map(|d| {
                            d.pred.as_deref().and_then(|p| {
                                parse_expr_text(p)
                                    .map(|e| {
                                        let mut cols = std::collections::BTreeSet::new();
                                        pred_columns(&e, &mut cols);
                                        cols.contains(name).then(|| d.name.clone())
                                    })
                                    .unwrap_or(None)
                            })
                        }) {
                            return err(format!(
                                "cannot drop column {name}: partial index {bad} references it \
                                 in its WHERE predicate"
                            ));
                        }
                        if let Some(bad) = checks.iter().find(|c| {
                            parse_expr_text(c)
                                .map(|e| expr_references_ident(&e, name))
                                .unwrap_or(true)
                        }) {
                            return err(format!(
                                "cannot drop column {name}: CHECK constraint {bad} references it"
                            ));
                        }
                        // Stored view SQL is not rewritten: dropping a column
                        // a view still names breaks the view (its missing
                        // column reads NULL — for a WHERE that is silently
                        // wrong rows) while the dump replays "fine". Refuse
                        // like RENAME does, scoped to views that actually
                        // name the column. The chain is TRANSITIVE: a
                        // `SELECT *` middle layer carries the column upward
                        // without naming it, so direct dependents alone
                        // would let v2 = SELECT v FROM v1 degrade to NULL.
                        let mut dep_chain = vec![tname.to_string()];
                        loop {
                            let deps = self.direct_view_dependents(&dep_chain);
                            if deps.is_empty() {
                                break;
                            }
                            dep_chain.extend(deps);
                        }
                        let view_refs: Vec<String> = dep_chain
                            .into_iter()
                            .filter(|v| {
                                v != tname
                                    && self
                                        .tables
                                        .get(v)
                                        .and_then(|m| m.view_sql.clone())
                                        .is_some_and(|sql| text_references_ident(&sql, name))
                            })
                            .collect();
                        if !view_refs.is_empty() {
                            return err(format!(
                                "cannot drop column {tname}.{name}: referenced by VIEW {} \
                                 (drop the view first; its stored SQL is not rewritten)",
                                view_refs.join(", ")
                            ));
                        }
                        let referencing: Vec<String> = self
                            .tables
                            .iter()
                            .filter(|(_, m)| {
                                m.foreign_keys.iter().any(|(_, rt, rc)| {
                                    if rt != tname {
                                        return false;
                                    }
                                    // Match under the rc spelling the apply
                                    // loop will have produced by the time
                                    // this DROP runs (renames earlier in the
                                    // same statement rewrote it).
                                    let evolved = renamed.iter().fold(rc.clone(), |cur, (o, n)| {
                                        if cur == *o {
                                            n.clone()
                                        } else {
                                            cur
                                        }
                                    });
                                    evolved == *name
                                })
                            })
                            .map(|(t, _)| t.clone())
                            .collect();
                        if !referencing.is_empty() {
                            return err(format!(
                                "cannot drop column {tname}.{name}: referenced by FOREIGN KEY in {}",
                                referencing.join(", ")
                            ));
                        }
                        columns.retain(|c| c != name);
                        // Mirror the apply loop's index teardown on the
                        // simulated state: the dropped column's single-column
                        // tree dies, and every index over the column dies with
                        // it. RenameColumn later in the statement must check
                        // collisions against this EVOLVED state, or
                        // `DROP COLUMN x, RENAME COLUMN y TO x` is wrongly
                        // refused for x's dead index.
                        roots.remove(name);
                        index_defs.retain(|d| !d.columns.iter().any(|c| c == name));
                    }
                }
                Op::RenameColumn {
                    old_column_name,
                    new_column_name,
                } => {
                    let (old, new) = (&old_column_name.value, &new_column_name.value);
                    if !columns.contains(old) {
                        return err(format!("column {old} does not exist"));
                    }
                    // Stored view SQL is not rewritten: renaming a column of
                    // a referenced table breaks the view (and makes its
                    // dump_script unreplayable). Refuse like DROP does.
                    let deps = self.direct_view_dependents(&[tname.to_string()]);
                    if !deps.is_empty() {
                        return err(format!(
                            "cannot rename column {tname}.{old}: table is referenced by VIEW {} \
                             (drop the view first; its stored SQL is not rewritten)",
                            deps.join(", ")
                        ));
                    }
                    if old != new {
                        // Every namespace the new name can collide with: a
                        // duplicate column collapses two columns' data into
                        // one key, and an index root-key (single-column roots
                        // key by column name, composites by index name) would
                        // be silently overwritten by the rename. Both checks
                        // run on the EVOLVED state (earlier DROP COLUMNs may
                        // have removed trees/defs).
                        if columns.contains(new) {
                            return err(format!("duplicate column name: {new}"));
                        }
                        if roots.contains(new) || index_defs.iter().any(|d| d.name == *new) {
                            return err(format!("name {new} is already used by an index"));
                        }
                        // Same collapse through the schemaless door: an
                        // undeclared field already present in the stored
                        // documents. The apply loop's remove(old)+insert(new)
                        // would silently overwrite those values.
                        if self
                            .table_docs_cx(tname)?
                            .iter()
                            .any(|d| d.contains_key(new.as_str()))
                        {
                            return err(format!(
                                "cannot rename column {tname}.{old} to {new}: \
                                 {new} already exists as a data field"
                            ));
                        }
                    }
                    renamed.push((old.clone(), new.clone()));
                    columns = columns
                        .iter()
                        .map(|c| if c == old { new.clone() } else { c.clone() })
                        .collect();
                    if pk.as_deref() == Some(old.as_str()) {
                        pk = Some(new.clone());
                    }
                    // The apply loop rekeys the single-column tree from the
                    // old column name to the new one — evolve the simulated
                    // roots the same way, or a later rename falsely reports
                    // a collision with the vacated name. Same ownership rule
                    // as the apply loop: a composite/path def NAMED like the
                    // column owns the def-name root and blocks the rekey.
                    let own_tree = !index_defs
                        .iter()
                        .any(|d| d.name == *old && (d.path.is_some() || d.columns.len() > 1));
                    if own_tree && roots.remove(old.as_str()) {
                        roots.insert(new.clone());
                    }
                    for d in index_defs.iter_mut() {
                        for c in d.columns.iter_mut() {
                            if c == old {
                                *c = new.clone();
                            }
                        }
                    }
                    checks = checks
                        .iter()
                        .map(|c| rename_ident_in_text(c, old, &ident_spelling(new)))
                        .collect();
                }
                Op::RenameTable { table_name } => {
                    let new_name = match table_name {
                        sqlparser::ast::RenameTableNameKind::As(n)
                        | sqlparser::ast::RenameTableNameKind::To(n) => obj_name(n),
                    };
                    if self.tables.contains_key(&new_name) {
                        return err(format!("table {new_name} already exists"));
                    }
                    // Reserved names are filtered out of dump/snapshot or
                    // collide with internal tables; CREATE refuses them, so
                    // rename must too (a renamed-away table would silently
                    // vanish from every backup).
                    if is_system_table(&new_name) || crate::useradmin::is_user_table(&new_name) {
                        return err(format!("table name {new_name} is reserved for the engine"));
                    }
                    // Same parity as CREATE TABLE: a # temp-table name is
                    // refused outright, and a compat dictionary name would
                    // shadow the table at FROM-resolution — writes would
                    // land but SELECTs would read the dictionary instead,
                    // and dump_script would emit a CREATE the replay guard
                    // rejects (backup/restore and join snapshots fail).
                    if new_name.starts_with('#') {
                        return err("temp tables (#name/##name) are not supported");
                    }
                    if is_compat_view(&new_name) {
                        return err(format!(
                            "table name {new_name} is reserved for the compatibility dictionary views"
                        ));
                    }
                    // Stored view SQL is not rewritten: a view left pointing
                    // at the old name breaks every SELECT and — worse — makes
                    // dump_script unreplayable (backup/restore and join/repair
                    // snapshots all fail). Refuse like DROP does.
                    let deps = self.direct_view_dependents(&[tname.to_string()]);
                    if !deps.is_empty() {
                        return err(format!(
                            "cannot rename table {tname}: referenced by VIEW {} \
                             (drop the view first; its stored SQL is not rewritten)",
                            deps.join(", ")
                        ));
                    }
                }
                other => return err(format!("unsupported ALTER TABLE operation: {other}")),
            }
        }
        Ok(())
    }

    fn exec_alter(&mut self, alter: sqlparser::ast::AlterTable) -> Result<ExecOutcome> {
        use sqlparser::ast::AlterTableOperation as Op;
        let tname = obj_name(&alter.name);
        if !self.internal_ddl
            && (crate::useradmin::is_user_table(&tname) || crate::engine::is_system_table(&tname))
        {
            // The network path already classifies these writes away
            // (stmt_write_targets); an embedded/in-process caller could
            // ALTER the replicated user tables directly, and the altered
            // schema would diverge from every peer's digest.
            return err(format!("cannot ALTER the internal table {tname}"));
        }
        if self.tables.get(&tname).is_some_and(|m| m.is_matview()) && !self.internal_ddl {
            return err(format!(
                "cannot ALTER materialized view {tname} (it is refreshed, not altered)"
            ));
        }
        let Some(mut meta) = self.tables.get(&tname).map(|a| a.as_ref().clone()) else {
            return err(format!("table {tname} does not exist"));
        };
        ensure_not_view("ALTER", &tname, &meta)?;
        self.validate_alter_ops(&meta, &tname, &alter.operations)?;
        // rewrite_table persists the catalog in its own transaction; only
        // metadata-only ALTERs (plain ADD COLUMN) need the tail save.
        // Trees detached from `meta.index_roots` by DROP COLUMN below; freed
        // inside the rebuild's write unit (see rewrite_table_with_dead).
        let mut dead_trees: Vec<(String, u32)> = Vec::new();
        for op in &alter.operations {
            match op {
                Op::AddColumn { column_def, .. } => {
                    let col = column_def.name.value.clone();
                    if !meta.columns.contains(&col) {
                        meta.columns.push(col.clone());
                    }
                    // Column-level DEFAULT / CHECK ride along with ADD COLUMN.
                    // NOT NULL is validated after the loop: the conventional
                    // spelling `NOT NULL DEFAULT x` registers the default in
                    // a later option, so the "NOT NULL needs a DEFAULT" rule
                    // can only be judged once all options are in.
                    let mut add_not_null = false;
                    for opt in &column_def.options {
                        use sqlparser::ast::ColumnOption as CO;
                        match &opt.option {
                            CO::Default(e) => {
                                meta.defaults.push((col.clone(), default_expr_text(e)))
                            }
                            CO::Check(c) => {
                                if expr_calls_wall_clock(&c.expr) {
                                    return err(
                                        "CHECK constraints cannot call wall-clock or random \
                                         functions (NOW/SYSDATE/CURRENT_TIMESTAMP/GETDATE/RAND); \
                                         every node would evaluate a different value",
                                    );
                                }
                                let mut refs = Vec::new();
                                check_expr_column_refs(&c.expr, &mut refs)?;
                                for r in refs {
                                    if !meta.columns.contains(&r) {
                                        return err(format!(
                                            "CHECK constraint references unknown column {r}"
                                        ));
                                    }
                                }
                                meta.checks.push(format!("{}", c.expr))
                            }
                            CO::NotNull => add_not_null = true,
                            // Same parity as CREATE TABLE: these options on
                            // ADD COLUMN would dangle (no tree, no backfill).
                            CO::PrimaryKey { .. }
                            | CO::Unique { .. }
                            | CO::ForeignKey(_)
                            | CO::DialectSpecific(_) => {
                                return err(format!(
                                    "constraint options are not supported on ADD COLUMN {col}"
                                ));
                            }
                            // Swallowing these silently degraded the column
                            // to a plain one (the CREATE TABLE path rejects
                            // the same spellings).
                            CO::Generated { .. }
                            | CO::Materialized(_)
                            | CO::Ephemeral(_)
                            | CO::Alias(_) => {
                                return err(format!(
                                    "generated/computed columns are not supported \
                                     (ADD COLUMN {col})"
                                ));
                            }
                            CO::Null => {}
                            _ => {
                                return err(format!(
                                    "unsupported column option on ADD COLUMN {col}"
                                ))
                            }
                        }
                    }
                    // SQLite rule: a NOT NULL column needs a default to
                    // backfill existing rows, else every later UPDATE of a
                    // pre-existing row would fail.
                    if add_not_null && !meta.defaults.iter().any(|(c, _)| c == &col) {
                        return err(format!(
                            "cannot add NOT NULL column {col} without a DEFAULT"
                        ));
                    }
                    if add_not_null {
                        meta.not_null.push(col.clone());
                    }
                    // ADD COLUMN with DEFAULT backfills existing rows.
                    if let Some((_, text)) = meta.defaults.iter().find(|(c, _)| c == &col).cloned()
                    {
                        let e = parse_expr_text(&text)?;
                        // A wall-clock/random default would backfill THIS
                        // node's clock/roll into every existing row with no
                        // resolved-text rewrite — replaying peers stamp
                        // their own values and the tables diverge. Refuse
                        // while there are rows to backfill (an empty table
                        // keeps the default text for future INSERTs, which
                        // do rewrite deterministically).
                        if expr_calls_wall_clock(&e) && !self.table_docs_cx(&tname)?.is_empty() {
                            return err(
                                "ADD COLUMN cannot backfill a wall-clock or random DEFAULT \
                                 (NOW/SYSDATE/CURRENT_TIMESTAMP/GETDATE/RAND) into existing \
                                 rows; supply the column explicitly on INSERT instead",
                            );
                        }
                        let fill = eval_const(&e)?;
                        let docs = self.table_docs_cx(&tname)?;
                        let filled: Vec<Object> = docs
                            .into_iter()
                            .map(|mut d| {
                                if !d.contains_key(&col) {
                                    d.insert(col.clone(), fill.clone());
                                }
                                d
                            })
                            .collect();
                        // The backfilled image must satisfy the checks —
                        // including one riding along on THIS ADD COLUMN:
                        // `ADD COLUMN c INT DEFAULT -5 CHECK (c > 0)` used
                        // to backfill violating values while later INSERTs
                        // were correctly rejected.
                        for d in &filled {
                            meta.check(d)?;
                        }
                        self.rewrite_table(&tname, &mut meta, filled)?;
                    }
                }
                Op::DropColumn { column_names, .. } => {
                    for id in column_names {
                        let name = id.value.clone();
                        if meta.primary_key.as_deref() == Some(name.as_str()) {
                            return err("cannot drop a PRIMARY KEY column");
                        }
                        // A CHECK text still naming the column would read it
                        // as NULL afterwards and silently stop enforcing
                        // (the rename path already guards against this).
                        if let Some(bad) = meta.checks.iter().find(|c| {
                            parse_expr_text(c)
                                .map(|e| expr_references_ident(&e, &name))
                                .unwrap_or(true)
                        }) {
                            return err(format!(
                                "cannot drop column {name}: CHECK constraint {bad} references it"
                            ));
                        }
                        // Another table's (or this table's own) FK pointing
                        // at the column would leave every future child insert
                        // failing with a dangling reference.
                        let referencing: Vec<String> = self
                            .tables
                            .iter()
                            .filter(|(_, m)| {
                                m.foreign_keys
                                    .iter()
                                    .any(|(_, rt, rc)| rt == &tname && rc == &name)
                            })
                            .map(|(t, _)| t.clone())
                            .collect();
                        if !referencing.is_empty() {
                            return err(format!(
                                "cannot drop column {tname}.{name}: referenced by FOREIGN KEY in {}",
                                referencing.join(", ")
                            ));
                        }
                        meta.columns.retain(|c| c != &name);
                        meta.unique.retain(|c| c != &name);
                        meta.constraint_unique.retain(|c| c != &name);
                        meta.not_null.retain(|c| c != &name);
                        meta.defaults.retain(|(c, _)| c != &name);
                        meta.foreign_keys.retain(|(c, _, _)| c != &name);
                        if let Some(root) = meta.index_roots.remove(&name) {
                            // Capture the tree BEFORE dropping it from the
                            // map: the rebuild below only frees trees still
                            // listed in `index_roots`, so these roots must
                            // ride `dead_trees` or their pages leak forever.
                            dead_trees.push((name.clone(), root));
                        }
                        if meta.autoinc.as_deref() == Some(name.as_str()) {
                            meta.autoinc = None;
                        }
                        if meta.autoguid.as_deref() == Some(name.as_str()) {
                            meta.autoguid = None;
                        }
                        // Indexes over the dropped column lose their
                        // definitions (trees above were already removed).
                        // A composite index over the column dies with it too.
                        let dead: Vec<String> = meta
                            .index_defs
                            .iter()
                            .filter(|d| d.columns.iter().any(|c| c == name.as_str()))
                            .map(|d| d.name.clone())
                            .collect();
                        for n in &dead {
                            meta.indexes.retain(|i| i != n);
                        }
                        for (k, root) in meta.index_roots.iter() {
                            if dead.contains(k) {
                                dead_trees.push((k.clone(), *root));
                            }
                        }
                        meta.index_roots.retain(|k, _| !dead.contains(k));
                        meta.index_defs.retain(|d| !dead.contains(&d.name));
                    }
                    let docs = self.table_docs_cx(&tname)?;
                    let stripped: Vec<Object> = docs
                        .into_iter()
                        .map(|mut d| {
                            for id in column_names {
                                d.remove(&id.value);
                            }
                            d
                        })
                        .collect();
                    self.rewrite_table_with_dead(
                        &tname,
                        &mut meta,
                        stripped,
                        std::mem::take(&mut dead_trees),
                    )?;
                }
                Op::RenameColumn {
                    old_column_name,
                    new_column_name,
                } => {
                    let (old, new) = (&old_column_name.value, &new_column_name.value);
                    if !meta.columns.contains(old) {
                        return err(format!("column {old} does not exist"));
                    }
                    meta.columns = meta
                        .columns
                        .iter()
                        .map(|c| if c == old { new.clone() } else { c.clone() })
                        .collect();
                    if meta.primary_key.as_deref() == Some(old.as_str()) {
                        meta.primary_key = Some(new.clone());
                    }
                    meta.unique = meta
                        .unique
                        .iter()
                        .map(|c| if c == old { new.clone() } else { c.clone() })
                        .collect();
                    meta.not_null = meta
                        .not_null
                        .iter()
                        .map(|c| if c == old { new.clone() } else { c.clone() })
                        .collect();
                    if meta.autoinc.as_deref() == Some(old.as_str()) {
                        meta.autoinc = Some(new.clone());
                    }
                    if meta.autoguid.as_deref() == Some(old.as_str()) {
                        meta.autoguid = Some(new.clone());
                    }
                    // Only the column's OWN single-column tree rekeys with
                    // the rename. A composite or JSON-path index NAMED like
                    // the column owns the def-name root (root_key = index
                    // name) — the def name does not follow the column, and
                    // rekeying would graft an Array/path-keyed tree onto
                    // the new column key where DML would mix scalar keys
                    // into it. A SINGLE-column def named like the column
                    // but built on ANOTHER column owns that other column's
                    // root, not `old` — the column's own tree still rekeys
                    // (stranding it let duplicate PKs in silently and
                    // diverged replicas whose dump replay enforced them).
                    let own_tree = !meta
                        .index_defs
                        .iter()
                        .any(|d| d.name == *old && (d.path.is_some() || d.columns.len() > 1));
                    if own_tree {
                        if let Some(root) = meta.index_roots.remove(old) {
                            meta.index_roots.insert(new.clone(), root);
                        }
                    }
                    meta.defaults = meta
                        .defaults
                        .iter()
                        .map(|(c, t)| {
                            if c == old {
                                (new.clone(), t.clone())
                            } else {
                                (c.clone(), t.clone())
                            }
                        })
                        .collect();
                    meta.constraint_unique = meta
                        .constraint_unique
                        .iter()
                        .map(|c| if c == old { new.clone() } else { c.clone() })
                        .collect();
                    meta.index_defs = meta
                        .index_defs
                        .iter()
                        .map(|d| {
                            if d.columns.iter().any(|c| c == old) {
                                IndexDef {
                                    name: d.name.clone(),
                                    columns: d
                                        .columns
                                        .iter()
                                        .map(|c| if c == old { new.clone() } else { c.clone() })
                                        .collect(),
                                    unique: d.unique,
                                    path: d.path.clone(),
                                    pred: d.pred.clone(),
                                }
                            } else if d.pred.is_some() {
                                // The predicate is SQL text over row fields:
                                // a renamed column must not leave it naming a
                                // ghost (its rows would silently read NULL
                                // and drop out of the tree). Same rewrite the
                                // CHECK texts get.
                                IndexDef {
                                    name: d.name.clone(),
                                    columns: d.columns.clone(),
                                    unique: d.unique,
                                    path: d.path.clone(),
                                    pred: d.pred.as_deref().map(|p| {
                                        rename_ident_in_text(p, old, &ident_spelling(new))
                                    }),
                                }
                            } else {
                                d.clone()
                            }
                        })
                        .collect();
                    // FK columns on this table follow the rename, and so does
                    // the remote column of a same-table FK (self-references
                    // and sibling references): a dangling rc would fail every
                    // subsequent child write with FK errors.
                    meta.foreign_keys = meta
                        .foreign_keys
                        .iter()
                        .map(|(c, rt, rc)| {
                            (
                                if c == old { new.clone() } else { c.clone() },
                                rt.clone(),
                                if rt == &tname && rc == old {
                                    new.clone()
                                } else {
                                    rc.clone()
                                },
                            )
                        })
                        .collect();
                    // CHECK texts reference the old column name; leaving them
                    // stale silently disables the constraint (a missing column
                    // reads as NULL -> unknown -> check skipped).
                    meta.checks = meta
                        .checks
                        .iter()
                        .map(|c| rename_ident_in_text(c, old, &ident_spelling(new)))
                        .collect();
                    let docs = self.table_docs_cx(&tname)?;
                    let renamed: Vec<Object> = docs
                        .into_iter()
                        .map(|mut d| {
                            if let Some(v) = d.remove(old) {
                                d.insert(new.clone(), v);
                            }
                            d
                        })
                        .collect();
                    self.rewrite_table(&tname, &mut meta, renamed)?;
                    // Referencing tables' remote columns follow too (the same
                    // rule RENAME TABLE applies to their rt, also after the
                    // commit so the failure path stays atomic): a dangling rc
                    // makes every child write fail FK checks and aborts dump
                    // replay mid-script (backup/restore, join snapshots).
                    // Only tables actually referencing the old name get a
                    // targeted make_mut — never a whole-catalog deep copy.
                    let referrers: Vec<String> = self
                        .tables
                        .iter()
                        .filter(|(n, m)| {
                            n.as_str() != tname.as_str()
                                && m.foreign_keys
                                    .iter()
                                    .any(|(_, rt, rc)| rt == &tname && rc == old)
                        })
                        .map(|(n, _)| n.clone())
                        .collect();
                    if !referrers.is_empty() {
                        // Snapshot the referrer entries: a failed catalog
                        // save must leave memory matching disk — the next
                        // successful write persists whatever sits in memory,
                        // so a diverged (rewritten-but-unsaved) entry would
                        // silently drift to peers.
                        let before: Vec<(String, std::sync::Arc<TableMeta>)> = referrers
                            .iter()
                            .filter_map(|n| self.tables.get(n).map(|m| (n.clone(), m.clone())))
                            .collect();
                        for name in referrers {
                            if let Some(entry) = self.tables.get_mut(&name) {
                                let m = std::sync::Arc::make_mut(entry);
                                for (_, rt, rc) in m.foreign_keys.iter_mut() {
                                    if rt == &tname && rc == old {
                                        *rc = new.clone();
                                    }
                                }
                            }
                        }
                        if let Err(e) = self.save_catalog() {
                            for (n, m) in before {
                                self.tables.insert(n, m);
                            }
                            return Err(e);
                        }
                    }
                }
                Op::RenameTable { table_name } => {
                    let new_name = match table_name {
                        sqlparser::ast::RenameTableNameKind::As(n)
                        | sqlparser::ast::RenameTableNameKind::To(n) => obj_name(n),
                    };
                    // rewrite_table would silently replace the target's entry
                    // and orphan its data pages.
                    if self.tables.contains_key(&new_name) {
                        return err(format!("table {new_name} already exists"));
                    }
                    let docs = self.table_docs_cx(&tname)?;
                    let old_entry = self.tables.get(&tname).cloned();
                    // The mirrored catalog key follows the rename; constraint
                    // errors keep naming the table users actually see.
                    meta.name = new_name.clone();
                    // 自引用外键的 rt 跟随新名(与其它引用方一并改写)。
                    for (_, rt, _) in meta.foreign_keys.iter_mut() {
                        if *rt == tname {
                            *rt = new_name.clone();
                        }
                    }
                    self.tables.remove(&tname);
                    // The old name must not keep a stale AUTOINCREMENT
                    // watermark for a table created under it later.
                    self.autoinc_cache.remove(&tname);
                    // Grants follow the rename: a row left on the old name
                    // would (a) resurrect onto a future same-named table —
                    // silent privilege escalation across unrelated data —
                    // and (b) break dump replay (GRANT on a table that no
                    // longer exists aborts the whole restore). A failure of
                    // the UPDATE fails the whole rename BEFORE the rewrite
                    // (the catalog entry is restored below like every other
                    // failure path); a rewrite failure reverts the grants
                    // rows the same way.
                    let lit_old = crate::stmt::sql_string_literal(&tname);
                    let lit_new = crate::stmt::sql_string_literal(&new_name);
                    let grants_update = if self.tables.contains_key(crate::useradmin::GRANTS_TABLE)
                    {
                        self.execute(&format!(
                            "UPDATE {} SET tbl = {} WHERE tbl = {}",
                            crate::useradmin::GRANTS_TABLE,
                            lit_new,
                            lit_old
                        ))
                    } else {
                        Ok(ExecOutcome::Affected(0))
                    };
                    if let Err(e) = grants_update {
                        if let Some(old) = old_entry {
                            self.tables.insert(tname.clone(), old);
                        }
                        return Err(e);
                    }
                    if let Err(e) = self.rewrite_table(&new_name, &mut meta, docs) {
                        // rewrite_table's own failure restore only covers the
                        // NEW name's entry (absent here) — without this the
                        // old entry would stay removed and the table (and its
                        // data pages) would vanish from the catalog.
                        if let Some(old) = old_entry {
                            self.tables.insert(tname.clone(), old);
                        }
                        // The grants UPDATE above already landed (autocommit):
                        // point the rows back at the old name or the next
                        // same-named table would inherit them.
                        if let Err(e2) = self.execute(&format!(
                            "UPDATE {} SET tbl = {} WHERE tbl = {}",
                            crate::useradmin::GRANTS_TABLE,
                            lit_old,
                            lit_new
                        )) {
                            eprintln!(
                                "warning: failed to revert grant rows after a failed \
                                 RENAME ({e2}); re-run the RENAME or fix grants manually"
                            );
                        }
                        return Err(e);
                    }
                    // 引用方的外键表名跟随改写:悬挂 rt 会让子表的一切写
                    // 路径报 "table does not exist",dump/restore 还会把
                    // 坏状态原样带回(旧条目尚未动,失败路径保持原子)。
                    // 只对真正引用旧名的表定点 make_mut——全库逐表 make_mut
                    // 会在有 detached 读者时深拷每一张表的 meta。
                    let referrers: Vec<String> = self
                        .tables
                        .iter()
                        .filter(|(_, m)| m.foreign_keys.iter().any(|(_, rt, _)| rt == &tname))
                        .map(|(n, _)| n.clone())
                        .collect();
                    // Snapshot first: a failed catalog save must restore the
                    // referrer entries, or memory diverges from disk (the
                    // next successful write would persist the divergence).
                    let before: Vec<(String, std::sync::Arc<TableMeta>)> = referrers
                        .iter()
                        .filter_map(|n| self.tables.get(n).map(|m| (n.clone(), m.clone())))
                        .collect();
                    for name in referrers {
                        if let Some(m) = self.tables.get_mut(&name) {
                            let m = std::sync::Arc::make_mut(m);
                            for (_, rt, _) in m.foreign_keys.iter_mut() {
                                if *rt == tname {
                                    *rt = new_name.clone();
                                }
                            }
                        }
                    }
                    if let Err(e) = self.save_catalog() {
                        for (n, m) in before {
                            self.tables.insert(n, m);
                        }
                        return Err(e);
                    }
                    return Ok(ExecOutcome::Affected(0));
                }
                other => return err(format!("unsupported ALTER TABLE operation: {other}")),
            }
        }
        // A rewrite persists the meta CLONE it saw; any metadata-only
        // operations after it in the same statement (ADD COLUMN without a
        // DEFAULT, a CHECK) only touched the local `meta` and were silently
        // dropped. Save the final state unconditionally — the extra save
        // after a bare rewrite is idempotent. A failed save restores the
        // in-memory entry: the next successful write persists whatever is
        // in memory, so leaving the new meta would diverge from disk.
        let prev = self.tables.get(&tname).cloned();
        self.tables.insert(tname.clone(), std::sync::Arc::new(meta));
        if let Err(e) = self.save_catalog() {
            match prev {
                Some(old) => {
                    self.tables.insert(tname.clone(), old);
                }
                None => {
                    self.tables.remove(&tname);
                }
            }
            return Err(e);
        }
        Ok(ExecOutcome::Affected(0))
    }

    /// Validate FOREIGN KEY constraints of `meta` for one candidate doc:
    /// non-null values must exist in the referenced table's column.
    /// Child-side FK check. `same_batch` carries the statement's own new
    /// images for `table` — when an FK targets the SAME table (self- or
    /// intra-statement references: `UPDATE emp SET mgr = 1 WHERE id = 1`,
    /// multi-row inserts whose later rows reference earlier ones), those
    /// images are legitimate parent candidates. Without them such rows were
    /// rejected (or, via UPDATE, created rows that dump/restore could never
    /// replay) even though SQLite/PG immediate FKs accept them.
    ///
    /// `self_final` is the statement's COMPLETE final state of `table` (the
    /// pre-statement rows minus replaced old images plus the new images).
    /// When provided, self-referential lookups use it ALONE: `same_batch`
    /// plus the pre-statement heap would still satisfy values this very
    /// statement removes (`UPDATE t SET id = 3, p = 1 WHERE id = 1`).
    #[allow(clippy::too_many_arguments)]
    fn check_fks_in(
        &mut self,
        table: &str,
        meta: &TableMeta,
        doc: &Object,
        same_batch: &[Object],
        self_final: Option<&[Object]>,
    ) -> Result<()> {
        for (col, rtable, rcol) in &meta.foreign_keys {
            let Some(v) = doc.get(col) else {
                continue;
            };
            if matches!(v, Value::Null) {
                continue; // NULL passes (MATCH SIMPLE semantics)
            }
            // cmp_values (not PartialEq): the engine's comparison semantics
            // treat Int(1)/Float(1.0)/Decimal(1) as equal; a join would
            // match them, so the FK must not reject what the rest of the
            // engine considers the same key.
            let matches_parent = |rd: &Object| {
                rd.get(rcol)
                    .map(|rv| Value::cmp_values(rv, v) == Ordering::Equal)
                    .unwrap_or(false)
            };
            if rtable == table {
                if let Some(final_state) = self_final {
                    if !final_state.iter().any(matches_parent) {
                        return err(format!(
                            "FOREIGN KEY constraint failed: {table}.{col} references \
                             {rtable}.{rcol}"
                        ));
                    }
                    continue;
                }
                if same_batch.iter().any(matches_parent) {
                    continue;
                }
            }
            let ref_docs = self.table_docs_cx(rtable)?;
            if !ref_docs.iter().any(matches_parent) {
                return err(format!(
                    "FOREIGN KEY constraint failed: {table}.{col} references {rtable}.{rcol}"
                ));
            }
        }
        Ok(())
    }

    /// Referential integrity on the *parent* side (RESTRICT): rows removed
    /// from `table` (DELETE, or UPDATE rows whose key value changes) may be
    /// referenced by child tables. `replacement_docs` carries the statement's
    /// surviving/updated rows of `table`: a parent-key value kept by any of
    /// them stays referenceable.
    /// [`check_fk_parent_delete_skipping`] with a child-table exclusion list: children
    /// named in `skip` are also being emptied by the same statement (e.g.
    /// `TRUNCATE parent, child`), so their rows cannot end up orphaned.
    /// `self_children` overrides the scan of `table`'s own rows with the
    /// statement's FINAL images (MERGE: the heap still shows pre-statement
    /// rows, so a self-reference created by the INSERT arm would be missed
    /// and one removed by the UPDATE arm wrongly reported).
    #[allow(clippy::too_many_arguments)]
    fn check_fk_parent_delete_skipping(
        &mut self,
        table: &str,
        removed_docs: &[Object],
        replacement_docs: &[Object],
        skip: &[String],
        self_children: Option<&[Object]>,
    ) -> Result<()> {
        if removed_docs.is_empty() {
            return Ok(());
        }
        // Child FKs referencing `table`: (child_table, child_col, parent_col).
        let children: Vec<(String, String, String)> = self
            .tables
            .iter()
            .filter(|(child_name, _)| !skip.iter().any(|s| s.as_str() == child_name.as_str()))
            .flat_map(|(child_name, m)| {
                m.foreign_keys
                    .iter()
                    .filter(|(_, rt, _)| rt == table)
                    .map(|(c, _, rc)| (child_name.clone(), c.clone(), rc.clone()))
                    .collect::<Vec<_>>()
            })
            .collect();
        if children.is_empty() {
            return Ok(());
        }
        let parent_cols: Vec<&String> = {
            let mut v: Vec<&String> = children.iter().map(|(_, _, rc)| rc).collect();
            v.sort();
            v.dedup();
            v
        };
        // Parent-key values that disappear with this statement.
        let mut lost: Vec<&Value> = Vec::new();
        for doc in removed_docs {
            for rc in &parent_cols {
                if let Some(v) = doc.get(rc.as_str()) {
                    let kept = replacement_docs.iter().any(|d| {
                        d.get(rc.as_str())
                            .map(|rv| Value::cmp_values(rv, v) == Ordering::Equal)
                            .unwrap_or(false)
                    });
                    if !matches!(v, Value::Null) && !kept && !lost.contains(&v) {
                        lost.push(v);
                    }
                }
            }
        }
        if lost.is_empty() {
            return Ok(());
        }
        // Non-unique referenced columns: a value can survive in rows this
        // statement never touched. `replacement_docs` only carries the
        // statement's own rows, so screen `lost` against the whole
        // pre-statement table: a value the removed set does not exhaust
        // (current count > removed count) is still referenceable. For
        // PK/UNIQUE referenced columns the counts are equal and this is a
        // no-op; for anything else it un-rejects legitimate deletes.
        {
            let current = self.table_docs_cx(table)?;
            let count_in = |docs: &[Object], rc: &str, v: &Value| {
                docs.iter()
                    .filter(|d| {
                        d.get(rc)
                            .map(|rv| Value::cmp_values(rv, v) == Ordering::Equal)
                            .unwrap_or(false)
                    })
                    .count()
            };
            lost.retain(|v| {
                !parent_cols
                    .iter()
                    .any(|rc| count_in(&current, rc, v) > count_in(removed_docs, rc, v))
            });
        }
        if lost.is_empty() {
            return Ok(());
        }
        for (child_table, child_col, rc) in &children {
            let fallback;
            let child_docs: &[Object] = if child_table == table {
                match self_children {
                    Some(docs) => docs,
                    None => {
                        fallback = self.table_docs_cx(child_table)?;
                        &fallback
                    }
                }
            } else {
                fallback = self.table_docs_cx(child_table)?;
                &fallback
            };
            let offender = child_docs.iter().any(|cd| {
                cd.get(child_col)
                    .map(|cv| {
                        !matches!(cv, Value::Null)
                            && lost
                                .iter()
                                .any(|lv| Value::cmp_values(cv, lv) == Ordering::Equal)
                    })
                    .unwrap_or(false)
            });
            if offender {
                return err(format!(
                    "FOREIGN KEY constraint failed: {child_table}.{child_col} references \
                     {table}.{rc}; delete/update the child rows first"
                ));
            }
        }
        Ok(())
    }

    /// CREATE VIEW: a named SELECT stored in the catalog namespace. Views
    /// have no storage, no indexes and no declared columns — a SELECT naming
    /// one expands to the stored query's rows (see `load_table_factor`).
    /// The body is dry-run once at create time so missing tables/columns
    /// fail loudly, and `CREATE OR REPLACE` re-points an existing view.
    // ===== Row triggers (CREATE TRIGGER / DROP TRIGGER) =====
    //
    // Replication red line: the creating DDL rides the journal like every
    // other write and every node fires the same bodies over the same rows,
    // so a body may contain NOTHING nondeterministic — no NEWID()/RAND(),
    // no wall-clock calls, no INSERT omitting an auto-GUID column, no
    // INSERT leaving a wall-clock DEFAULT to be filled. Each is refused at
    // CREATE time: at fire time the divergence has already happened by the
    // time anyone could notice.
    fn exec_create_trigger(&mut self, ct: sqlparser::ast::CreateTrigger) -> Result<ExecOutcome> {
        if ct.or_alter {
            return err("CREATE OR ALTER TRIGGER is not supported (use CREATE OR REPLACE TRIGGER)");
        }
        if ct.temporary {
            return err("TEMP triggers are not supported");
        }
        if ct.is_constraint {
            return err("CONSTRAINT triggers are not supported");
        }
        if !ct.referencing.is_empty() {
            return err("REFERENCING (transition tables) is not supported");
        }
        if ct.characteristics.is_some() {
            return err("trigger characteristics (DEFERRABLE / INITIALLY …) are not supported");
        }
        if ct.exec_body.is_some() {
            return err("EXECUTE FUNCTION triggers are not supported (use a BEGIN … END body)");
        }
        if ct.statements_as {
            return err("AS trigger bodies are not supported (use BEGIN … END)");
        }
        let before = match ct.period {
            Some(sqlparser::ast::TriggerPeriod::Before) => true,
            Some(sqlparser::ast::TriggerPeriod::After) => false,
            Some(sqlparser::ast::TriggerPeriod::InsteadOf) => {
                return err("INSTEAD OF triggers are not supported (views are not writable)");
            }
            Some(sqlparser::ast::TriggerPeriod::For) | None => {
                return err("trigger requires BEFORE or AFTER");
            }
        };
        match ct.trigger_object {
            None => {}
            Some(sqlparser::ast::TriggerObjectKind::ForEach(
                sqlparser::ast::TriggerObject::Row,
            ))
            | Some(sqlparser::ast::TriggerObjectKind::For(sqlparser::ast::TriggerObject::Row)) => {}
            Some(_) => {
                return err(
                    "statement-level triggers (FOR EACH STATEMENT) are not supported (triggers are row-level)",
                );
            }
        }
        if ct.events.len() != 1 {
            return err("exactly one event (INSERT / UPDATE / DELETE) per trigger");
        }
        let (insert, delete, update, update_of) = match ct
            .events
            .into_iter()
            .next()
            .expect("checked above")
        {
            sqlparser::ast::TriggerEvent::Insert => (true, false, false, None),
            sqlparser::ast::TriggerEvent::Delete => (false, true, false, None),
            sqlparser::ast::TriggerEvent::Update(cols) => (
                false,
                false,
                true,
                if cols.is_empty() {
                    None
                } else {
                    Some(cols.iter().map(|i| i.value.clone()).collect())
                },
            ),
            sqlparser::ast::TriggerEvent::Truncate => {
                return err(
                    "TRUNCATE triggers are not supported (row triggers fire on DELETE; TRUNCATE itself fires none)",
                );
            }
        };
        let name = obj_name(&ct.name);
        let table = obj_name(&ct.table_name);
        if crate::engine::is_system_table(&table) || is_internal_table(&table) {
            return err(format!("triggers cannot target the internal table {table}"));
        }
        let Some(tmeta) = self.tables.get(&table).cloned() else {
            return err(format!("table {table} does not exist"));
        };
        if tmeta.is_view() {
            return err(format!("cannot create a trigger on view {table}"));
        }
        // WHEN: only NEW./OLD. references over literals and operators — an
        // unqualified column name would silently read NULL and skip every
        // firing.
        let when = match &ct.condition {
            Some(e) => {
                validate_trigger_when(e)?;
                Some(e.to_string())
            }
            None => None,
        };
        let body_statements = match &ct.statements {
            Some(cs) => cs.statements().clone(),
            None => return err("trigger body is required (BEGIN … END)"),
        };
        if body_statements.is_empty() {
            return err("trigger body is empty");
        }
        let mut body = Vec::with_capacity(body_statements.len());
        for s in &body_statements {
            body.push(self.validate_trigger_body_stmt(s)?);
        }
        if self.triggers.contains_key(&name) && !ct.or_replace {
            return err(format!("trigger {name} already exists"));
        }
        self.triggers.insert(
            name.clone(),
            TriggerDef {
                name,
                table,
                before,
                insert,
                delete,
                update,
                update_of,
                when,
                body,
            },
        );
        self.save_catalog()?;
        Ok(ExecOutcome::Affected(0))
    }

    /// CREATE-time validation of one trigger body statement: the accepted
    /// shapes (INSERT / UPDATE / DELETE / `SELECT RAISE(ABORT|FAIL, …)`)
    /// plus the determinism gates that keep every replaying node in
    /// agreement. Returns the catalog form.
    fn validate_trigger_body_stmt(&self, stmt: &Statement) -> Result<TriggerAction> {
        match stmt {
            Statement::Insert(i) => {
                let sqlparser::ast::TableObject::TableName(n) = &i.table else {
                    return err("trigger body INSERT must target a simple table");
                };
                let t = obj_name(n);
                self.validate_trigger_target(&t)?;
                let tmeta = self.tables.get(&t).cloned().unwrap_or_default();
                // INSERT would otherwise rewrite NEWID per row, and RAND()
                // would re-roll on every replaying node — same gate the
                // direct path applies to INSERT ... SELECT sources.
                let text = stmt.to_string();
                if crate::stmt::mentions_nondet_call(&text) {
                    return err(
                        "NEWID()/NEWSEQUENTIALID()/RAND() are not allowed in trigger bodies \
                         (each node would generate different values)",
                    );
                }
                if crate::stmt::mentions_wall_clock(&text) {
                    return err(
                        "wall-clock functions are not allowed in trigger bodies (each node would stamp its own clock)",
                    );
                }
                // A wall-clock DEFAULT on the TARGET table would be filled
                // per node at fire time even though the body text is clean:
                // the body must supply those columns explicitly.
                let cols: Vec<String> = i.columns.iter().map(obj_name).collect();
                let positional = cols.is_empty();
                for (col, text) in &tmeta.defaults {
                    let Ok(e) = parse_expr_text(text) else {
                        continue;
                    };
                    if expr_calls_wall_clock(&e) && (positional || !cols.iter().any(|c| c == col)) {
                        return err(format!(
                            "trigger body INSERT into {t} omits column {col}, whose DEFAULT is a \
                             wall-clock call (each node would stamp its own clock); supply the \
                             column explicitly"
                        ));
                    }
                }
                // An auto-GUID fill is a random id per node. The body must
                // carry an explicit non-NULL value for that column.
                if let Some(gcol) = &tmeta.autoguid {
                    // Positional INSERT maps values onto the DECLARED column
                    // list; an explicit list must name the column itself.
                    let idx: Option<usize> = if positional {
                        tmeta.columns.iter().position(|c| c == gcol)
                    } else {
                        cols.iter().position(|c| c == gcol)
                    };
                    let values: Option<&Vec<SqlExpr>> =
                        i.source.as_ref().and_then(|q| match &*q.body {
                            SetExpr::Values(v) => v.rows.first().map(|r| &r.content),
                            _ => None,
                        });
                    let supplied: Option<&SqlExpr> = match (idx, values) {
                        (Some(i), Some(vals)) => vals.get(i),
                        _ => None,
                    };
                    let explicit = match supplied {
                        // NULL literal still triggers the fill at fire time.
                        Some(SqlExpr::Value(v)) => !matches!(v.value, sqlparser::ast::Value::Null),
                        // NEW.col / OLD.col references and expressions cannot
                        // be proven non-NULL here; the runtime NULL-fill is a
                        // documented edge (substitute a literal to be safe).
                        Some(_) => true,
                        None => false,
                    };
                    if !explicit {
                        return err(format!(
                            "trigger body INSERT into {t} must supply the auto-generated GUID \
                             column {gcol} explicitly (each node would generate a different id)"
                        ));
                    }
                }
            }
            Statement::Update(u) => {
                let sqlparser::ast::TableFactor::Table { name, .. } = &u.table.relation else {
                    return err("trigger body UPDATE must target a simple table");
                };
                let t = obj_name(name);
                self.validate_trigger_target(&t)?;
                if crate::stmt::mentions_nondet_call(&stmt.to_string()) {
                    return err(
                        "NEWID()/NEWSEQUENTIALID()/RAND() are not allowed in trigger bodies \
                         (each node would generate different values)",
                    );
                }
                if crate::stmt::mentions_wall_clock(&stmt.to_string()) {
                    return err(
                        "wall-clock functions are not allowed in trigger bodies (each node would stamp its own clock)",
                    );
                }
            }
            Statement::Delete(d) => {
                let sqlparser::ast::FromTable::WithFromKeyword(twjs) = &d.from else {
                    return err("trigger body DELETE must target a simple table");
                };
                let Some(sqlparser::ast::TableFactor::Table { name, .. }) =
                    twjs.first().map(|t| &t.relation)
                else {
                    return err("trigger body DELETE must target a simple table");
                };
                let t = obj_name(name);
                self.validate_trigger_target(&t)?;
                if crate::stmt::mentions_nondet_call(&stmt.to_string()) {
                    return err(
                        "NEWID()/NEWSEQUENTIALID()/RAND() are not allowed in trigger bodies \
                         (each node would generate different values)",
                    );
                }
                if crate::stmt::mentions_wall_clock(&stmt.to_string()) {
                    return err(
                        "wall-clock functions are not allowed in trigger bodies (each node would stamp its own clock)",
                    );
                }
            }
            Statement::Query(q) => return raise_action(q),
            other => {
                return err(format!(
                    "unsupported trigger body statement ({other}); INSERT / UPDATE / DELETE / \
                     SELECT RAISE(ABORT|FAIL, …) only"
                ));
            }
        }
        Ok(TriggerAction::Sql(stmt.to_string()))
    }

    fn validate_trigger_target(&self, t: &str) -> Result<()> {
        if crate::engine::is_system_table(t) || is_internal_table(t) {
            return err(format!(
                "trigger bodies cannot write the internal table {t}"
            ));
        }
        let Some(m) = self.tables.get(t) else {
            return err(format!("table {t} does not exist"));
        };
        if m.is_view() {
            return err(format!("trigger bodies cannot write view {t}"));
        }
        Ok(())
    }

    fn exec_drop_trigger(&mut self, names: &[ObjectName], if_exists: bool) -> Result<ExecOutcome> {
        for n in names {
            let t = obj_name(n);
            if !self.triggers.contains_key(&t) && !if_exists {
                return err(format!("trigger {t} does not exist"));
            }
        }
        for n in names {
            self.triggers.remove(&obj_name(n));
        }
        self.save_catalog()?;
        Ok(ExecOutcome::Affected(0))
    }

    /// True when any trigger targets `table` — the zero-cost gate for the
    /// statement guard on deployments without triggers.
    fn triggers_exist_for(&self, table: &str) -> bool {
        self.triggers.values().any(|d| d.table == table)
    }

    /// Trigger names defined on `table` (object explorer / console meta),
    /// catalog (name) order.
    pub fn trigger_names_of(&self, table: &str) -> Vec<String> {
        self.triggers
            .values()
            .filter(|d| d.table == table)
            .map(|d| d.name.clone())
            .collect()
    }

    /// Fire matching row triggers for one row image. `old`/`new` carry the
    /// OLD./NEW. images (None where the event has none: INSERT has no OLD,
    /// DELETE no NEW). `changed` names the columns an UPDATE assigns — an
    /// UPDATE OF trigger fires only when they intersect.
    fn fire_row_triggers(
        &mut self,
        table: &str,
        before: bool,
        ev: TriggerFireEvent<'_>,
        old: Option<&Object>,
        new: Option<&Object>,
    ) -> Result<()> {
        if self.triggers.is_empty() {
            return Ok(());
        }
        let matched: Vec<TriggerDef> = self
            .triggers
            .values()
            .filter(|d| {
                d.table == table
                    && d.before == before
                    && match ev {
                        TriggerFireEvent::Insert => d.insert,
                        TriggerFireEvent::Delete => d.delete,
                        TriggerFireEvent::Update(changed) => {
                            d.update
                                && match (&d.update_of, changed) {
                                    (None, _) | (_, None) => true,
                                    (Some(of), Some(ch)) => {
                                        ch.iter().any(|c| of.iter().any(|o| o == c))
                                    }
                                }
                        }
                    }
            })
            .cloned()
            .collect();
        if matched.is_empty() {
            return Ok(());
        }
        if self.trigger_depth >= MAX_TRIGGER_DEPTH {
            return err(format!(
                "trigger nesting too deep (>{MAX_TRIGGER_DEPTH}); likely an infinite trigger cycle"
            ));
        }
        self.trigger_depth += 1;
        // The triggering statement's canonical rewrite and assigned id are
        // ITS replication state — body statements get their own (validated
        // deterministic, so discarded) and the outer values come back.
        let saved_resolved = self.resolved_sql.take();
        let saved_last_id = self.last_insert_id.take();
        let r = self.run_trigger_bodies(&matched, table, old, new);
        self.resolved_sql = saved_resolved;
        self.last_insert_id = saved_last_id;
        self.trigger_depth -= 1;
        r
    }

    fn run_trigger_bodies(
        &mut self,
        defs: &[TriggerDef],
        firing_table: &str,
        old: Option<&Object>,
        new: Option<&Object>,
    ) -> Result<()> {
        for d in defs {
            if let Some(w) = &d.when {
                let mut e = parse_expr_text(w)?;
                subst_new_old_expr(&mut e, old, new)?;
                // WHEN passes only on TRUE (false and NULL skip, SQL
                // semantics).
                if !matches!(eval_expr(&e, &Object::new())?, Value::Bool(true)) {
                    continue;
                }
            }
            for a in &d.body {
                self.stmt_deadline.check()?;
                match a {
                    TriggerAction::Raise { msg, .. } => {
                        return err(format!("RAISE in trigger {}: {msg}", d.name));
                    }
                    TriggerAction::Sql(text) => {
                        let stmts = Parser::parse_sql(&GenericDialect {}, text)
                            .map_err(|e| SqlError::Parse(e.to_string()))?;
                        let Some(mut stmt) = stmts.into_iter().next() else {
                            continue;
                        };
                        // MySQL's rule, for the same reason: the triggering
                        // statement's row images are staged in ITS pager
                        // transaction until it commits — a body write to the
                        // same table would apply against the pre-statement
                        // pages and be overwritten when the outer statement
                        // commits. Reads stay legal (they see the committed
                        // pre-statement state deterministically, origin and
                        // replays alike).
                        if let Some(t) = trigger_dml_target(&stmt) {
                            if t == firing_table {
                                return err(format!(
                                    "cannot modify table {t} from a trigger on {t} while a \
                                     statement on {t} is in progress (split the write onto a \
                                     second table)"
                                ));
                            }
                        }
                        subst_new_old_stmt(&mut stmt, old, new)?;
                        let text = stmt.to_string();
                        if text_has_trigger_ref_outside_literals(&text) {
                            return err(
                                "NEW./OLD. references inside a subquery are not supported in \
                                 trigger bodies",
                            );
                        }
                        let parsed = Self::parse_classified(&text)?;
                        self.execute_parsed(parsed)?;
                    }
                }
            }
        }
        Ok(())
    }

    /// Statement guard for DML aimed at a trigger-carrying table: the
    /// statement and every trigger it fires commit or vanish together.
    /// Zero cost when no trigger targets the statement's table (the guard
    /// never opens) — trigger-less deployments keep their exact write path.
    fn exec_stmt(&mut self, stmt: Statement) -> Result<ExecOutcome> {
        if self.trigger_depth == 0 {
            if let Some(t) = trigger_dml_target(&stmt) {
                if self.triggers_exist_for(&t) {
                    return self.run_with_trigger_guard(move |slf| slf.exec_stmt_inner(stmt));
                }
            }
        }
        self.exec_stmt_inner(stmt)
    }

    fn run_with_trigger_guard(
        &mut self,
        run: impl FnOnce(&mut Self) -> Result<ExecOutcome>,
    ) -> Result<ExecOutcome> {
        if self.tx_snapshot.is_some() {
            // Inside an explicit transaction the statement-local revert is a
            // savepoint (page-undo mark + catalog snapshot): the transaction
            // and its earlier statements stay.
            let mark = self.pager.undo_mark();
            self.pager.undo_savepoint()?;
            let snap = self.catalog_snapshot();
            let r = run(self);
            if r.is_err() {
                let mut undo = self.pager.take_undo_to(mark);
                // sync_catalog=false — the journal replay already restored
                // the catalog pages (same cheap path as ROLLBACK TO).
                self.restore_transaction(snap, &mut undo, false)?;
            }
            return r;
        }
        // Autocommit: statement + triggers fuse into one write unit (one
        // WAL fsync, crash loses all of them together), and any failure
        // reverts pages (undo journal) and catalog (snapshot) exactly like
        // a transaction ROLLBACK — a half-fired statement never survives.
        self.pager.begin_undo();
        let snap = self.catalog_snapshot();
        let mut unit = self.write_unit();
        let r = run(&mut unit);
        match r {
            Ok(out) => {
                unit.end()?;
                self.pager.end_undo();
                Ok(out)
            }
            Err(e) => {
                // Mirror ROLLBACK: void the deferred frames BEFORE writing
                // the revert, or the revert's fence would commit the failed
                // work on a torn crash.
                let db: &mut Database = &mut unit;
                db.pager.abort_deferred()?;
                let mut undo = db.pager.take_undo();
                db.restore_transaction(snap, &mut undo, true)?;
                unit.end()?;
                Err(e)
            }
        }
    }

    /// CREATE MATERIALIZED VIEW: materialize the query into real storage
    /// and record the query for REFRESH. The query must be deterministic
    /// (no NEWID/RAND/wall-clock): REFRESH replays it on every node, and a
    /// nondeterministic result would silently fork the cluster's derived
    /// tables.
    fn exec_create_matview(&mut self, view: sqlparser::ast::CreateView) -> Result<ExecOutcome> {
        if view.secure || view.with_no_schema_binding {
            return err("SECURE / WITH NO SCHEMA BINDING is not supported");
        }
        if !view.columns.is_empty() {
            return err("CREATE MATERIALIZED VIEW column list is not supported                  (alias the SELECT outputs)");
        }
        let name = obj_name(&view.name);
        if name.starts_with('#') {
            return err("temp materialized views (#name) are not supported");
        }
        if crate::useradmin::is_user_table(&name) {
            return err(format!(
                "materialized view name {name} is reserved for the user/role subsystem"
            ));
        }
        if crate::engine::is_system_table(&name) || is_internal_table(&name) {
            return err(format!(
                "materialized view name {name} is reserved for the engine"
            ));
        }
        if is_compat_view(&name) {
            return err(format!(
                "materialized view name {name} is reserved for the compatibility \
                 dictionary views"
            ));
        }
        if let Some(existing) = self.tables.get(&name) {
            if !view.or_replace {
                if view.if_not_exists {
                    return Ok(ExecOutcome::Affected(0));
                }
                return err(format!("materialized view {name} already exists"));
            }
            if !existing.is_matview() {
                return err(format!(
                    "{name} is not a materialized view; use DROP {} before \
                     CREATE OR REPLACE MATERIALIZED VIEW",
                    if existing.is_view() { "VIEW" } else { "TABLE" }
                ));
            }
        }
        let query = view.query.to_string();
        // Determinism gates — REFRESH replays this text on every node over
        // the same base data; a nondeterministic result diverges silently.
        if crate::stmt::mentions_wall_clock(&query) {
            return err(
                "materialized view queries cannot call wall-clock functions \
                 (NOW/SYSDATE/CURRENT_TIMESTAMP/GETDATE): every node would \
                 recompute a different value at REFRESH",
            );
        }
        if crate::stmt::mentions_nondet_call(&query) {
            return err(
                "materialized view queries cannot call NEWID()/NEWSEQUENTIALID()/RAND(): \
                 every node would recompute a different value at REFRESH",
            );
        }
        // A materialized view over another materialized view would make the
        // dump's replay order (and every refresh cascade) a dependency
        // puzzle; v1 refuses the nesting — query base tables (or views).
        {
            let objects = |n: &str| self.tables.contains_key(n);
            let stmt = sqlparser::ast::Statement::Query(view.query.clone());
            let Some(targets) = Database::stmt_read_targets(&stmt, &objects) else {
                return err("materialized view queries must be plain SELECTs over base tables");
            };
            if let Some(mv) = targets
                .iter()
                .find(|t| self.tables.get(*t).is_some_and(|m| m.is_matview()))
            {
                return err(format!(
                    "materialized view {name} cannot query materialized view {mv} \
                     (refresh cascades and dump ordering are not supported)"
                ));
            }
        }
        // Materialize now (same shape CTAS produces: columns from the query
        // outputs, schemaless rows).
        let ExecOutcome::Rows(r) = self.exec_query_cx((*view.query).clone())? else {
            return err("CREATE MATERIALIZED VIEW requires a SELECT");
        };
        {
            let mut seen = std::collections::BTreeSet::new();
            if let Some(dup) = r.columns.iter().find(|c| !seen.insert((*c).clone())) {
                return err(format!("duplicate column name: {dup}"));
            }
        }
        let docs: Vec<Object> = r
            .rows
            .into_iter()
            .map(|row| r.columns.iter().cloned().zip(row).collect())
            .collect();
        let columns = r.columns;
        // OR REPLACE swaps the definition and the content in one statement:
        // reuse the storage (rewrite_table frees + rebuilds), never drop and
        // recreate (a mid-statement failure would leave nothing behind).
        let mut meta = match self.tables.get(&name).cloned() {
            Some(prev) if prev.is_matview() => {
                let mut m = prev.as_ref().clone();
                m.columns = columns;
                m
            }
            Some(prev) => prev.as_ref().clone(),
            None => TableMeta {
                name: name.clone(),
                columns,
                ..Default::default()
            },
        };
        meta.matview_sql = Some(query.clone());
        self.rewrite_table(&name, &mut meta, docs)?;
        Ok(ExecOutcome::Affected(0))
    }

    /// REFRESH MATERIALIZED VIEW: re-execute the stored query and replace
    /// the stored rows wholesale (one rewrite = one atomic statement). The
    /// stored text was determinism-validated at CREATE; re-validate at
    /// REFRESH so a pre-validation volume cannot replay a divergent query.
    fn exec_refresh_matview(&mut self, name: &str) -> Result<ExecOutcome> {
        let Some(meta) = self.tables.get(name).cloned() else {
            return err(format!("materialized view {name} does not exist"));
        };
        if !meta.is_matview() {
            return err(format!(
                "{name} is not a materialized view (it is a {})",
                if meta.is_view() { "view" } else { "table" }
            ));
        }
        let query = meta.matview_sql.clone().expect("checked above");
        if crate::stmt::mentions_wall_clock(&query) {
            return err("materialized view query calls wall-clock functions");
        }
        if crate::stmt::mentions_nondet_call(&query) {
            return err("materialized view query calls NEWID()/NEWSEQUENTIALID()/RAND()");
        }
        let parsed = Self::parse_classified(&query)?;
        let AnyStmt::Sql(stmt) = parsed.stmt else {
            return err("materialized view query must be a SELECT");
        };
        let Statement::Query(q) = *stmt else {
            return err("materialized view query must be a SELECT");
        };
        let ExecOutcome::Rows(r) = self.exec_query_cx(*q)? else {
            return err("materialized view query must be a SELECT");
        };
        {
            let mut seen = std::collections::BTreeSet::new();
            if let Some(dup) = r.columns.iter().find(|c| !seen.insert((*c).clone())) {
                return err(format!("duplicate column name: {dup}"));
            }
        }
        let docs: Vec<Object> = r
            .rows
            .into_iter()
            .map(|row| r.columns.iter().cloned().zip(row).collect())
            .collect();
        let mut meta = meta.as_ref().clone();
        meta.columns = r.columns;
        // One rewrite = one atomic statement: the old content and every
        // index tree rebuild together, readers never see a half-refreshed
        // view (MVCC snapshot reads see the pre-refresh content throughout).
        self.rewrite_table(name, &mut meta, docs)?;
        Ok(ExecOutcome::Affected(0))
    }

    fn exec_create_view(&mut self, view: sqlparser::ast::CreateView) -> Result<ExecOutcome> {
        if view.materialized {
            return self.exec_create_matview(view);
        }
        if view.secure || view.with_no_schema_binding {
            return err("SECURE / WITH NO SCHEMA BINDING views are not supported");
        }
        if !view.columns.is_empty() {
            // Column aliases would need per-row projection renaming; the
            // projection's own aliases already name the columns.
            return err("CREATE VIEW column list is not supported (alias the projection)");
        }
        let name = obj_name(&view.name);
        if name.starts_with('#') {
            return err("temp views (#name) are not supported");
        }
        if crate::useradmin::is_user_table(&name) {
            return err(format!(
                "view name {name} is reserved for the user/role subsystem"
            ));
        }
        if crate::engine::is_system_table(&name) {
            return err(format!("view name {name} is reserved for the engine"));
        }
        if is_compat_view(&name) {
            // Same shadow rule as CREATE TABLE: the compatibility dictionary
            // views always win at FROM-resolution, so a view created under
            // one of these names would be unreachable.
            return err(format!(
                "view name {name} is reserved for the compatibility dictionary views"
            ));
        }
        let exists = self.tables.contains_key(&name);
        if exists && !view.or_replace {
            if view.if_not_exists {
                return Ok(ExecOutcome::Affected(0));
            }
            return err(format!("view {name} already exists"));
        }
        // Views over the user/role tables are NOT refused here: dumps and
        // join snapshots from older volumes may legitimately contain one,
        // and refusing would break the whole replay. The leak is closed on
        // the READ side instead — the server's authorize expands view base
        // tables and refuses user-table bases to non-admins (same rule the
        // write path applies), so such a view is admin-readable only.
        if exists {
            let meta = self.tables.get(&name).expect("checked just above");
            if !meta.is_view() {
                return err(format!(
                    "{name} is a table; use DROP TABLE before CREATE VIEW"
                ));
            }
        }
        let body = format!("{}", view.query);
        // Cycle guard: with OR REPLACE the old view still resolves during
        // the dry-run below, and a replacement body can point back at
        // itself through other views (a→b, then `CREATE OR REPLACE VIEW
        // a AS SELECT * FROM b`). A direct self-reference is rejected up
        // front; for OR REPLACE the view→view edges reachable from the
        // new body must never return to `name` — otherwise every later
        // SELECT would recurse until the expansion budget trips.
        {
            let objects = |n: &str| self.tables.contains_key(n);
            let mut refs = Vec::new();
            let mut stmts = Parser::parse_sql(&GenericDialect {}, &body)
                .map_err(|e| SqlError::Parse(e.to_string()))?;
            if let Statement::Query(q) = stmts.swap_remove(0) {
                if walk_query(&q, &mut refs, &objects).is_none() {
                    return err("view body cannot be classified");
                }
                if refs.iter().any(|r| r == &name) {
                    return err(format!("view {name} cannot reference itself"));
                }
                if exists {
                    let mut stack = refs.clone();
                    let mut seen = std::collections::BTreeSet::new();
                    while let Some(next) = stack.pop() {
                        if next == name {
                            return err(format!(
                                "view {name} cannot reference itself (through {next})"
                            ));
                        }
                        if !seen.insert(next.clone()) {
                            continue;
                        }
                        if let Some(deeper) = self.view_base_tables(&next) {
                            stack.extend(deeper);
                        }
                    }
                }
            } else {
                return err("view body must be a SELECT");
            }
        }
        // Dry-run the body once: missing tables/columns/unsupported shapes
        // fail at CREATE time, not at first SELECT. The body executes as a
        // plain SELECT over the CURRENT catalog (a self-reference errors —
        // the name does not resolve yet — which is exactly the cycle check).
        // The view under construction consumes one expansion level of its
        // own, so a chain that would be too deep to SELECT is also too deep
        // to CREATE (creatable implies selectable).
        {
            let _guard = enter_view_expansion()?;
            let q = Self::plain_read_query(&Self::parse_classified(&body)?)?;
            self.exec_query_cx(q)?;
        }
        let meta = TableMeta {
            name: name.clone(),
            view_sql: Some(body),
            ..Default::default()
        };
        // Keep the old entry (or absence) so a failed catalog save leaves
        // the in-memory catalog untouched — a ghost view that only exists
        // here would persist on the next unrelated write and diverge every
        // peer (same snapshot discipline as exec_create/exec_drop).
        let prev = self.tables.insert(name.clone(), std::sync::Arc::new(meta));
        if let Err(e) = self.save_catalog() {
            match prev {
                Some(old) => {
                    self.tables.insert(name, old);
                }
                None => {
                    self.tables.remove(&name);
                }
            }
            return Err(e);
        }
        Ok(ExecOutcome::Affected(0))
    }

    fn exec_create(&mut self, create: sqlparser::ast::CreateTable) -> Result<ExecOutcome> {
        use sqlparser::ast::ColumnOption as CO;
        let name = obj_name(&create.name);
        if name.starts_with('#') {
            // T-SQL temp tables are session-scoped; making them persistent
            // global tables would silently change their lifetime/visibility.
            return err("temp tables (#name/##name) are not supported");
        }
        if crate::useradmin::is_user_table(&name) && !self.internal_ddl {
            return err(format!(
                "table name {name} is reserved for the user/role subsystem"
            ));
        }
        if crate::engine::is_system_table(&name) && !self.internal_ddl {
            // Squatting an engine system name would break replication,
            // digests and pub/sub on this database (the tables are excluded
            // from dumps by name). Only the internal replay path may create
            // reserved names, and it never creates these.
            return err(format!("table name {name} is reserved for the engine"));
        }
        if is_compat_view(&name) && !self.internal_ddl {
            // The dictionary/compat views always shadow a same-named table
            // at FROM-resolution (DUAL/sqlite_master/information_schema and
            // the Oracle dictionary spellings): a table created under one of
            // these names accepts writes but every SELECT reads the
            // dictionary instead — data that can never be read back. Refuse
            // at CREATE instead (existing pre-guard tables keep their
            // shadowed behavior).
            return err(format!(
                "table name {name} is reserved for the compatibility dictionary views"
            ));
        }
        if self.tables.contains_key(&name) {
            if create.if_not_exists {
                return Ok(ExecOutcome::Affected(0));
            }
            return err(format!("table {name} already exists"));
        }
        // Clause-level guard: a CREATE TABLE shape the engine cannot honor
        // must be refused, not silently degraded (`LIKE` used to create a
        // zero-column table; OR REPLACE ignored the replacement semantics).
        if create.like.is_some() || create.clone.is_some() {
            return err("CREATE TABLE ... LIKE/CLONE is not supported");
        }
        if create.or_replace {
            return err("CREATE OR REPLACE TABLE is not supported (drop the table first)");
        }
        if create.external
            || create.global.is_some()
            || create.transient
            || create.volatile
            || create.iceberg
            || !matches!(
                create.table_options,
                sqlparser::ast::CreateTableOptions::None
            )
            || create.cluster_by.is_some()
            || create.partition_by.is_some()
            || create.order_by.is_some()
        {
            return err("CREATE TABLE storage/partitioning options are not supported");
        }
        if create.strict || create.comment.is_some() {
            return err("CREATE TABLE engine/comment options are not supported");
        }
        // Storage/layout clauses the GenericDialect parses but the engine
        // cannot honor. They used to be dropped silently (same red-line
        // class as the options above): inheriting columns, rowid layout,
        // Hive/Redshift placement and partition bounds all change what the
        // statement means, so refusing loudly is the only honest answer.
        if create.inherits.is_some()
            || create.without_rowid
            || create.on_commit.is_some()
            || create.on_cluster.is_some()
            || create.partition_of.is_some()
            || create.for_values.is_some()
            || create.location.is_some()
            || create.file_format.is_some()
            || create.clustered_by.is_some()
            || !matches!(
                create.hive_distribution,
                sqlparser::ast::HiveDistributionStyle::NONE
            )
            || create.hive_formats.is_some()
            || create.diststyle.is_some()
            || create.distkey.is_some()
            || create.sortkey.is_some()
            || create.backup.is_some()
        {
            return err("CREATE TABLE storage/partitioning options are not supported");
        }
        // CREATE TABLE ... AS SELECT: shape and rows come from the query.
        // (`temporary` is accepted and treated as a regular table.)
        if let Some(q) = &create.query {
            let ExecOutcome::Rows(r) = self.exec_query_cx(q.as_ref().clone())? else {
                return err("CREATE TABLE AS requires a SELECT");
            };
            // An explicit column list alongside AS SELECT would rename the
            // outputs (and its constraints would apply) — silently dropping
            // it shaped the table after the query instead. Refuse loudly
            // rather than ignore half the statement.
            if !create.columns.is_empty() {
                return err(
                    "CREATE TABLE (…) AS SELECT with an explicit column list is not supported \
                     (omit the list, or alias the SELECT outputs)",
                );
            }
            let docs: Vec<Object> = r
                .rows
                .into_iter()
                .map(|row| r.columns.iter().cloned().zip(row).collect())
                .collect();
            // Duplicate output names would collapse two logical columns into
            // one document key (the later value silently wins) — same rule
            // as the explicit column list below.
            {
                let mut seen = std::collections::BTreeSet::new();
                if let Some(dup) = r.columns.iter().find(|c| !seen.insert((*c).clone())) {
                    return err(format!("duplicate column name: {dup}"));
                }
            }
            let mut meta = TableMeta {
                name: name.clone(),
                columns: r.columns,
                ..Default::default()
            };
            self.rewrite_table(&name, &mut meta, docs)?;
            return Ok(ExecOutcome::Affected(0));
        }
        let columns: Vec<String> = create
            .columns
            .iter()
            .map(|c| c.name.value.clone())
            .collect();
        // Duplicate column names collapse two logical columns into one
        // document key (the later one silently wins); reject like SQLite.
        {
            let mut seen = std::collections::BTreeSet::new();
            if let Some(dup) = columns.iter().find(|c| !seen.insert((*c).clone())) {
                return err(format!("duplicate column name: {dup}"));
            }
        }
        let mut meta = TableMeta {
            name: name.clone(),
            columns,
            ..Default::default()
        };
        for col in &create.columns {
            for opt in &col.options {
                match &opt.option {
                    CO::PrimaryKey(pk) => {
                        reject_constraint_decorations(
                            "PRIMARY KEY",
                            pk.characteristics.as_ref(),
                            None,
                            None,
                        )?;
                        // A second PK declaration silently replaced the
                        // first (its uniqueness tree was never built).
                        if meta.primary_key.replace(col.name.value.clone()).is_some() {
                            return err("table has more than one primary key".to_string());
                        }
                    }
                    CO::Unique(u) => {
                        reject_constraint_decorations(
                            "UNIQUE",
                            u.characteristics.as_ref(),
                            Some(&u.nulls_distinct),
                            None,
                        )?;
                        // Deduplicate like the table-level constraint below:
                        // `a INT UNIQUE UNIQUE` pushed the column twice, the
                        // tree-maintenance loop inserted the same key twice,
                        // and the table was permanently unwritable.
                        let col = col.name.value.clone();
                        if !meta.unique.contains(&col) {
                            meta.unique.push(col.clone());
                        }
                        if !meta.constraint_unique.contains(&col) {
                            meta.constraint_unique.push(col);
                        }
                    }
                    CO::NotNull => meta.not_null.push(col.name.value.clone()),
                    CO::Null => {}
                    CO::Default(e) => {
                        meta.defaults
                            .push((col.name.value.clone(), default_expr_text(e)));
                    }
                    CO::Check(c) => {
                        if expr_calls_wall_clock(&c.expr) {
                            return err("CHECK constraints cannot call wall-clock or random \
                                 functions (NOW/SYSDATE/CURRENT_TIMESTAMP/GETDATE/RAND); \
                                 every node would evaluate a different value");
                        }
                        // Unknown column references resolve to NULL at
                        // evaluation time, so a typo'd CHECK would never
                        // fire — validate at DDL time.
                        let mut refs = Vec::new();
                        check_expr_column_refs(&c.expr, &mut refs)?;
                        for r in refs {
                            if !meta.columns.contains(&r) {
                                return err(format!(
                                    "CHECK constraint references unknown column {r}"
                                ));
                            }
                        }
                        meta.checks.push(format!("{}", c.expr))
                    }
                    CO::ForeignKey(fk) => {
                        reject_constraint_decorations(
                            "FOREIGN KEY",
                            fk.characteristics.as_ref(),
                            None,
                            fk.match_kind.as_ref(),
                        )?;
                        if fk.on_delete.is_some() || fk.on_update.is_some() {
                            return err(
                                "FOREIGN KEY ON DELETE/ON UPDATE actions are not supported \
                                 (declare the constraint and keep parent keys stable)",
                            );
                        }
                        if fk.referred_columns.len() != 1 {
                            // Silently taking the first referred column
                            // quietly changed the constraint's meaning.
                            return err("column-level FOREIGN KEY must reference a single column");
                        }
                        let (Some(rt), Some(rc)) = (
                            fk.foreign_table.0.last().map(|p| match p {
                                ObjectNamePart::Identifier(i) => i.value.clone(),
                                other => other.to_string(),
                            }),
                            fk.referred_columns.first().map(|c| c.value.clone()),
                        ) else {
                            return err("FOREIGN KEY requires a table and column");
                        };
                        meta.foreign_keys.push((col.name.value.clone(), rt, rc));
                    }
                    CO::DialectSpecific(tokens) => {
                        let text = tokens
                            .iter()
                            .map(|t| t.to_string().to_uppercase())
                            .collect::<Vec<_>>()
                            .join(" ");
                        if text.contains("AUTOINCREMENT") || text.contains("AUTO_INCREMENT") {
                            if is_guid_type(&col.data_type) {
                                // GUID columns treat the auto flag as
                                // UUIDv7 generation instead of max+1.
                                meta.autoguid = Some(col.name.value.clone());
                            } else {
                                meta.autoinc = Some(col.name.value.clone());
                            }
                        } else {
                            return err("unsupported column constraint");
                        }
                    }
                    _ => return err("unsupported column constraint"),
                }
            }
        }
        // Table-level constraints.
        for c in &create.constraints {
            use sqlparser::ast::TableConstraint as TC;
            match c {
                TC::Unique(u) => {
                    reject_constraint_decorations(
                        "UNIQUE",
                        u.characteristics.as_ref(),
                        Some(&u.nulls_distinct),
                        None,
                    )?;
                    // A multi-column constraint would need a composite unique
                    // tree; declaring it as per-column uniques silently
                    // changes the semantics (any single column becomes
                    // unique), so refuse and point at the supported form.
                    if u.columns.len() != 1 {
                        return err("composite UNIQUE table constraints are not supported \
                             (use CREATE UNIQUE INDEX)");
                    }
                    for ic in &u.columns {
                        if !matches!(ic.column.expr, SqlExpr::Identifier(_)) {
                            return err("expression UNIQUE constraints are not supported \
                                 (constraint a plain column)");
                        }
                        let col = expr_name(&ic.column.expr);
                        if !meta.columns.contains(&col) {
                            // A ghost column builds a constraint tree that can
                            // never fire and vanishes from dump_script.
                            return err(format!("UNIQUE column {col} does not exist"));
                        }
                        if !meta.unique.contains(&col) {
                            meta.unique.push(col.clone());
                            meta.constraint_unique.push(col);
                        }
                    }
                }
                TC::PrimaryKey(pk) => {
                    reject_constraint_decorations(
                        "PRIMARY KEY",
                        pk.characteristics.as_ref(),
                        None,
                        None,
                    )?;
                    // DocSQL has single-column primary keys; a composite key
                    // must not silently degrade to its first column.
                    if pk.columns.len() != 1 {
                        return err("composite PRIMARY KEY is not supported \
                             (declare a single-column PRIMARY KEY or use CREATE UNIQUE INDEX)");
                    }
                    if let Some(ic) = pk.columns.first() {
                        if !matches!(ic.column.expr, SqlExpr::Identifier(_)) {
                            return err("expression PRIMARY KEY constraints are not supported \
                                 (constraint a plain column)");
                        }
                        let name = expr_name(&ic.column.expr);
                        if !meta.columns.contains(&name) {
                            return err(format!("PRIMARY KEY column {name} does not exist"));
                        }
                        if meta.primary_key.replace(name).is_some() {
                            return err("table has more than one primary key".to_string());
                        }
                    }
                }
                TC::Check(chk) => {
                    if expr_calls_wall_clock(&chk.expr) {
                        return err("CHECK constraints cannot call wall-clock functions \
                             (NOW/SYSDATE/CURRENT_TIMESTAMP); every node would \
                             evaluate a different instant");
                    }
                    let mut refs = Vec::new();
                    check_expr_column_refs(&chk.expr, &mut refs)?;
                    for r in refs {
                        if !meta.columns.contains(&r) {
                            return err(format!("CHECK constraint references unknown column {r}"));
                        }
                    }
                    meta.checks.push(format!("{}", chk.expr))
                }
                TC::ForeignKey(fk) => {
                    reject_constraint_decorations(
                        "FOREIGN KEY",
                        fk.characteristics.as_ref(),
                        None,
                        fk.match_kind.as_ref(),
                    )?;
                    if fk.on_delete.is_some() || fk.on_update.is_some() {
                        return err("FOREIGN KEY ON DELETE/ON UPDATE actions are not supported \
                             (declare the constraint and keep parent keys stable)");
                    }
                    let Some(rt) = fk.foreign_table.0.last().map(|p| match p {
                        ObjectNamePart::Identifier(i) => i.value.clone(),
                        other => other.to_string(),
                    }) else {
                        return err("FOREIGN KEY requires a table");
                    };
                    // A composite FK silently split into per-column pairs
                    // enforces a different (weaker) constraint — each column
                    // independently instead of the tuple. Refuse like the
                    // composite PK/UNIQUE forms.
                    if fk.columns.len() != 1 {
                        return err("composite FOREIGN KEY constraints are not supported");
                    }
                    // zip 会静默截断较短的列清单,约束悄悄少一列 —— 列数
                    // 不匹配必须显式报错(子句级静默忽略是红线)。
                    if fk.columns.len() != fk.referred_columns.len() {
                        return err(format!(
                            "FOREIGN KEY column count mismatch: {} referencing columns \
                             vs {} referred columns",
                            fk.columns.len(),
                            fk.referred_columns.len()
                        ));
                    }
                    for (lc, rc) in fk.columns.iter().zip(fk.referred_columns.iter()) {
                        if !meta.columns.contains(&lc.value) {
                            return err(format!("FOREIGN KEY column {} does not exist", lc.value));
                        }
                        meta.foreign_keys
                            .push((lc.value.clone(), rt.clone(), rc.value.clone()));
                    }
                }
                other => return err(format!("unsupported table constraint: {other}")),
            }
        }
        // Constraint columns get their B+ trees right away: duplicate
        // enforcement and index probes depend on them existing. The trees
        // ride the SAME write unit as the catalog entry (the shape
        // `exec_create_index` settled on): committing the tree first and
        // Forward-declared FKs (referencing a table that does not exist
        // yet) can form DECLARATION cycles the dump's topological order
        // cannot break — the fallback emits cycle members in catalog
        // order, and a replay then inserts child rows before their
        // parents exist (restore fails mid-flight). Self-references are
        // fine: the table being created is its own parent. When the
        // parent exists, the referenced column must be one of its
        // declared columns — an undeclared field would silently match
        // nothing and every child write would fail the constraint.
        for (fc, rt, rc) in &meta.foreign_keys {
            if rt == &name {
                continue;
            }
            let Some(parent) = self.tables.get(rt) else {
                return err(format!(
                    "FOREIGN KEY on {name}.{fc} references table {rt}, which does not exist \
                     (create {rt} first)"
                ));
            };
            if parent.is_view() {
                return err(format!(
                    "FOREIGN KEY on {name}.{fc} cannot reference the VIEW {rt}"
                ));
            }
            if !parent.columns.contains(rc) {
                return err(format!(
                    "FOREIGN KEY on {name}.{fc} references unknown column {rt}.{rc}"
                ));
            }
        }
        // saving the catalog in a second transaction left a crash window
        // holding a committed tree no catalog references — those pages would
        // leak for good, nothing would ever free them.
        let constraint_cols: Vec<String> = meta
            .primary_key
            .iter()
            .chain(meta.unique.iter())
            .cloned()
            .collect();
        let mut tx = self.pager.begin_tx();
        if !constraint_cols.is_empty() {
            let roots = self.build_trees(
                &mut tx,
                &[],
                &constraint_cols,
                &constraint_cols
                    .iter()
                    .map(|c| vec![c.clone()])
                    .collect::<Vec<_>>(),
                &vec![None; constraint_cols.len()],
                &vec![true; constraint_cols.len()],
                &vec![None; constraint_cols.len()],
            )?;
            meta.index_roots = roots;
        }
        self.tables.insert(name.clone(), std::sync::Arc::new(meta));
        if let Err(e) = self
            .save_catalog_into(&mut tx)
            .and_then(|()| self.commit_pager_tx(tx))
        {
            // The tx dropped without committing: staged tree pages went back
            // to the reusable pool, and the in-memory entry must not keep
            // pointing at them.
            self.tables.remove(&name);
            return Err(e);
        }
        Ok(ExecOutcome::Affected(0))
    }

    fn exec_insert(&mut self, insert: sqlparser::ast::Insert) -> Result<ExecOutcome> {
        if insert.output.is_some() {
            return err("OUTPUT is not supported (use RETURNING)");
        }
        let TableObject::TableName(name) = &insert.table else {
            return err("unsupported INSERT target");
        };
        let table = obj_name(name);
        // Arc bump, not a meta deep clone: INSERT only ever reads the meta,
        // and this is the hottest write path.
        let Some(meta) = self.tables.get(&table).cloned() else {
            return err(format!("table {table} does not exist"));
        };
        ensure_not_view("INSERT into", &table, &meta)?;
        let mut columns: Vec<String> = if insert.columns.is_empty() {
            meta.columns.clone()
        } else {
            // A repeated name makes the later zip().collect() silently
            // overwrite the earlier value — reject like mainstream engines.
            let cols: Vec<String> = insert.columns.iter().map(obj_name).collect();
            let mut seen = std::collections::BTreeSet::new();
            if let Some(dup) = cols.iter().find(|c| !seen.insert((*c).clone())) {
                return err(format!("duplicate column name: {dup}"));
            }
            // Deliberately NOT validated against meta.columns: this is a
            // document store — an explicit list may name schemaless fields
            // the declared columns have not seen yet (observed-columns
            // tracking and the schemaless SELECT * union depend on it;
            // useradmin's own grants rows ride the same behavior).
            cols
        };
        let Some(source) = &insert.source else {
            return err("INSERT requires VALUES");
        };
        let rows: Vec<Vec<Value>> = match &*source.body {
            SetExpr::Values(value_rows) => {
                let mut rows = Vec::new();
                for parens in &value_rows.rows {
                    rows.push(
                        parens
                            .content
                            .iter()
                            .map(eval_const)
                            .collect::<Result<_>>()?,
                    );
                }
                rows
            }
            // INSERT INTO t (cols...) SELECT ...: take the SELECT's rows.
            // Without a column list the mapping is POSITIONAL onto the
            // target table's declared columns (standard SQL) — the query's
            // output NAMES used to redefine the keys, silently dropping
            // every value into ghost fields whenever the projection wasn't
            // bare same-named identifiers (aliases, literals, `SELECT *`
            // from a differently-named source).
            SetExpr::Select(_) => {
                let ExecOutcome::Rows(r) = self.exec_query_cx(source.as_ref().clone())? else {
                    return err("INSERT source must be VALUES or SELECT");
                };
                if r.columns.len() != columns.len() {
                    return err(format!(
                        "INSERT SELECT has {} columns but {} are expected",
                        r.columns.len(),
                        columns.len()
                    ));
                }
                r.rows
            }
            other => return err(format!("unsupported INSERT source: {other}")),
        };
        // An empty VALUES list is a syntax-level mistake; an empty SELECT
        // source (WHERE filtered everything) inserts 0 rows like every
        // mainstream engine — ETL batches legitimately hit it.
        if rows.is_empty() && matches!(&*source.body, SetExpr::Values(_)) {
            return err("INSERT has no rows");
        }
        // INSERT ... SELECT into an auto-GUID table cannot be replicated:
        // peers re-run the SELECT and would each fill their own random
        // GUIDs, silently diverging. VALUES is required.
        if meta.autoguid.is_some() && matches!(&*source.body, SetExpr::Select(_)) {
            return err(
                "auto-generated GUID columns do not support INSERT ... SELECT \
                 (use INSERT ... VALUES, with or without explicit ids)",
            );
        }
        // Build all documents first, validate, and only then write — a
        // failed statement must leave the table untouched.
        // AUTOINCREMENT: append the column when the INSERT omits it, then
        // assign max(id)+1 to missing/NULL values per row. Auto-generated
        // GUID columns follow the same omitted/NULL fill with fresh
        // time-ordered UUIDv7 values.
        let autoinc_appended = match &meta.autoinc {
            Some(col) if !columns.contains(col) => {
                columns.push(col.clone());
                true
            }
            _ => false,
        };
        let autoguid_appended = match &meta.autoguid {
            Some(col) if !columns.contains(col) => {
                columns.push(col.clone());
                true
            }
            _ => false,
        };
        let mut guid_filled = autoguid_appended;
        // A wall-clock DEFAULT (`DEFAULT NOW()`) resolved per row on THIS
        // node: the journaled INSERT must carry the explicit value or every
        // peer would stamp its own clock at replay (same rewrite trigger as
        // auto-GUID below).
        let mut default_clock_filled = false;
        let mut next_autoinc = self.autoinc_next_for(&table, &meta)?;
        // DEFAULT texts parsed once per statement (was re-parsed by
        // sqlparser for every row that omitted the column).
        let mut default_exprs: std::collections::HashMap<String, SqlExpr> =
            std::collections::HashMap::new();
        let mut new_docs: Vec<Object> = Vec::new();
        for row in rows {
            // INSERT … SELECT walks every source row (millions on a big
            // backfill): the timeout must be able to interrupt it.
            self.stmt_deadline.check()?;
            let mut row = row;
            if autoinc_appended {
                row.push(Value::Int(next_autoinc));
                next_autoinc = next_autoinc.saturating_add(1);
            }
            if autoguid_appended {
                row.push(Value::Str(crate::guid::uuidv7()));
            }
            if row.len() != columns.len() {
                return err(format!(
                    "INSERT has {} values but {} columns",
                    row.len(),
                    columns.len()
                ));
            }
            if !autoinc_appended {
                if let Some(col) = &meta.autoinc {
                    if let Some(idx) = columns.iter().position(|c| c == col) {
                        match row.get(idx) {
                            Some(Value::Null) | None => {
                                row[idx] = Value::Int(next_autoinc);
                                next_autoinc = next_autoinc.saturating_add(1);
                            }
                            // An explicit id at/above the statement-start
                            // watermark must advance the watermark *within*
                            // the statement, or a later row of the same
                            // INSERT that omits the id reuses it and dies on
                            // UNIQUE.
                            Some(Value::Int(v)) => {
                                next_autoinc = next_autoinc.max(v.saturating_add(1));
                            }
                            _ => {}
                        }
                    }
                }
            }
            if !autoguid_appended {
                if let Some(col) = &meta.autoguid {
                    if let Some(idx) = columns.iter().position(|c| c == col) {
                        if matches!(row.get(idx), Some(Value::Null) | None) {
                            row[idx] = Value::Str(crate::guid::uuidv7());
                            guid_filled = true;
                        }
                    }
                }
            }
            let mut doc: Object = columns.iter().cloned().zip(row).collect();
            // DEFAULT: fill declared columns the INSERT omitted (parse once
            // per statement; evaluation stays per row).
            for (col, text) in &meta.defaults {
                if !doc.contains_key(col) {
                    let e = match default_exprs.get(col) {
                        Some(e) => e,
                        None => {
                            let e = parse_expr_text(text)?;
                            default_exprs.insert(col.clone(), e);
                            default_exprs.get(col).expect("just inserted")
                        }
                    };
                    if expr_calls_wall_clock(e) {
                        default_clock_filled = true;
                    }
                    doc.insert(col.clone(), eval_const(e)?);
                }
            }
            meta.check(&doc)?;
            new_docs.push(doc);
        }
        // Conflict policy: plain (error on duplicates), REPLACE INTO /
        // OR REPLACE (drop conflicting rows first), ON CONFLICT DO NOTHING /
        // OR IGNORE (skip conflicting new rows), and the upsert-UPDATE
        // forms: ON CONFLICT <target> DO UPDATE SET … [WHERE …]
        // (PostgreSQL) / ON DUPLICATE KEY UPDATE … (MySQL) — the
        // conflicting row is updated in place.
        let replace = insert.replace_into
            || matches!(insert.or, Some(sqlparser::ast::SqliteOnConflict::Replace));
        let do_nothing = matches!(
            insert.on,
            Some(sqlparser::ast::OnInsert::OnConflict(ref c))
                if matches!(c.action, sqlparser::ast::OnConflictAction::DoNothing)
        ) || matches!(insert.or, Some(sqlparser::ast::SqliteOnConflict::Ignore));
        let (do_update, du_assignments, du_selection) = match &insert.on {
            Some(sqlparser::ast::OnInsert::OnConflict(c)) => match &c.action {
                sqlparser::ast::OnConflictAction::DoUpdate(du) => {
                    (true, du.assignments.clone(), du.selection.clone())
                }
                _ => (false, Vec::new(), None),
            },
            Some(sqlparser::ast::OnInsert::DuplicateKeyUpdate(assignments)) => {
                (true, assignments.clone(), None)
            }
            _ => (false, Vec::new(), None),
        };
        if replace && do_nothing {
            // Displacement deletes the conflicting old rows first, then DO
            // NOTHING skips every incoming row — a silent net delete. Reject
            // the mix like the DO UPDATE combination below.
            return err("OR REPLACE / REPLACE INTO cannot combine with ON CONFLICT DO NOTHING");
        }
        if do_update {
            if replace || do_nothing {
                return err(
                    "OR REPLACE / REPLACE INTO / OR IGNORE cannot combine with an upsert-UPDATE clause",
                );
            }
            // Non-deterministic values in the update arm would diverge the
            // cluster: peers replay the statement text verbatim (INSERT
            // defaults are rewritten with resolved literals, the UPDATE arm
            // has no such rewrite — same rule as UPDATE/DELETE/MERGE;
            // wall clocks are exempt because the fold covers them).
            for e in du_assignments
                .iter()
                .map(|a| &a.value)
                .chain(du_selection.iter())
            {
                if calls_newid(e) {
                    return err(
                        "NEWID()/NEWSEQUENTIALID() is not supported in DO UPDATE SET/WHERE \
                         (replication replay would diverge)",
                    );
                }
            }
            // Wall-clock functions in the arm are FOLDED to literals by the
            // statement-level preprocessing (fold_wall_clocks rewrites the
            // whole text, on-clause included), so they are accepted with
            // deterministic replay — no guard here.
            if refs_rownum_in(&du_assignments, &du_selection) {
                return err("ROWNUM is not supported in DO UPDATE SET/WHERE");
            }
            // PostgreSQL requires the conflict target for DO UPDATE; the
            // MySQL spelling is untargeted by definition (any unique key).
            if matches!(
                insert.on,
                Some(sqlparser::ast::OnInsert::OnConflict(ref c))
                    if c.conflict_target.is_none()
            ) {
                return err(
                    "ON CONFLICT DO UPDATE requires a conflict target (PostgreSQL semantics) — \
                     name the unique key with ON CONFLICT (cols) / ON CONSTRAINT, or use the \
                     MySQL spelling ON DUPLICATE KEY UPDATE for any-key matching",
                );
            }
            // EXCLUDED / VALUES() are rewritten only in the direct SET/WHERE
            // trees; inside a subquery they would mis-resolve to the
            // existing row's column — reject loudly instead.
            for e in du_assignments
                .iter()
                .map(|a| &a.value)
                .chain(du_selection.iter())
            {
                if upsert_proposed_in_subquery(e) {
                    return err(
                        "EXCLUDED / VALUES() inside a subquery of DO UPDATE SET/WHERE is not supported",
                    );
                }
            }
        }
        // Replication-safe rewrite: the statement as written would let every
        // peer fill its own random GUIDs — or stamp its own clock for a
        // wall-clock DEFAULT. Emit a canonical INSERT carrying the generated
        // ids / resolved instants explicitly — with the conflict clause
        // preserved so peers resolve the same conflicts against identical
        // state. NEWID()/NEWSEQUENTIALID() in the source (VALUES or SELECT)
        // are the same class: the writing node rolls the ids and ships the
        // literal values.
        let source_calls_nondet = insert
            .source
            .as_ref()
            .is_some_and(|s| crate::stmt::mentions_nondet_call(&s.to_string()));
        // A zero-row INSERT ... SELECT (e.g. NEWID() in the source under a
        // false WHERE) must NOT enter the rewrite: with no documents the
        // canonical form below degenerates to `INSERT INTO t () VALUES ` —
        // unparseable text that rode the journal and broke every replaying
        // peer. The original statement replays identically (deterministically
        // empty) on each node, so keeping it is replication-safe.
        if (guid_filled || default_clock_filled || source_calls_nondet) && !new_docs.is_empty() {
            let policy = if replace {
                "OR REPLACE "
            } else if do_nothing {
                "OR IGNORE "
            } else {
                ""
            };
            let mut sql = format!("INSERT {}INTO {} (", policy, quote_ident(&table));
            let cols: Vec<String> = new_docs
                .first()
                .map(|d| d.keys().cloned().collect())
                .unwrap_or_default();
            sql.push_str(
                &cols
                    .iter()
                    .map(|c| quote_ident(c))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            sql.push_str(") VALUES ");
            let mut rendered = Vec::with_capacity(new_docs.len());
            for doc in &new_docs {
                let vals = cols
                    .iter()
                    .map(|c| value_literal(doc.get(c).unwrap_or(&Value::Null)))
                    .collect::<Result<Vec<_>>>()?;
                rendered.push(format!("({})", vals.join(", ")));
            }
            sql.push_str(&rendered.join(", "));
            // Preserve the conflict clause verbatim: the OR-prefix only
            // covers the SQLite spellings, and a targeted ON CONFLICT scope
            // must not widen to OR IGNORE on replaying peers.
            if let Some(on) = &insert.on {
                sql.push_str(&on.to_string());
            }
            self.resolved_sql = Some(sql);
        } else if source_calls_nondet && new_docs.is_empty() {
            // Zero rows from a NONDETERMINISTIC source: replaying the
            // original text re-rolls RAND()/NEWID() on every peer — an
            // empty draw here can be non-empty there, silently forking the
            // cluster. Ship a deterministically-empty statement instead.
            // (INSERT ... SELECT is safe to emit: an auto-GUID table never
            // reaches this point — that shape is rejected above.)
            let col = meta.columns.first().cloned().unwrap_or_else(|| "v".into());
            let q = quote_ident(&col);
            self.resolved_sql = Some(format!(
                "INSERT INTO {} ({q}) SELECT {q} FROM (VALUES (NULL)) AS __empty__({q}) WHERE 1 = 0",
                quote_ident(&table)
            ));
        }

        // One pager transaction for heap pages and index trees alike: a
        // statement is either fully applied or not at all, and commits once.
        let mut heap = Heap {
            pages: meta.pages.clone(),
            overflow_free: meta.overflow_free.clone(),
            dropped: Vec::new(),
        };
        let mut roots = meta.index_roots.clone();
        let mut tx = self.pager.begin_tx();

        // Constraint columns with a usable tree: duplicates are detected and
        // enforced through the trees (O(log n) per row) instead of scanning
        // and cloning the whole table.
        let indexed: Vec<String> = meta
            .primary_key
            .iter()
            .chain(meta.unique.iter())
            .filter(|c| roots.contains_key(*c))
            .cloned()
            .collect();
        // Every indexed column (constraint trees + plain CREATE INDEX trees),
        // hoisted once so the per-row maintenance loops below do not clone
        // the roots map per row.
        let idx_specs = idx_specs(&meta, &roots);
        // Composite UNIQUE trees (CREATE UNIQUE INDEX over several columns)
        // take part in the *undirected* conflict policies (OR IGNORE /
        // REPLACE INTO / ON DUPLICATE KEY UPDATE = "any unique key") exactly
        // like the single-column constraint trees — probing only `indexed`
        // let those conflicts fall through to the tree-level insert and
        // error instead of skipping/replacing/updating.
        let composite_uniques: Vec<&IdxSpec> = idx_specs
            .iter()
            .filter(|s| s.unique && s.cols.len() > 1)
            .collect();
        // PARTIAL UNIQUE trees (CREATE UNIQUE INDEX … WHERE): their
        // conflicts are predicate-scoped — a candidate row conflicts only
        // when it ITSELF satisfies the predicate (then the hit row is in
        // the tree by construction). Probed for the undirected policies and
        // OR REPLACE displacement; never an ON CONFLICT target scope
        // (resolve_conflict_columns knows constraint columns only).
        let partial_uniques: Vec<&IdxSpec> = idx_specs
            .iter()
            .filter(|s| s.unique && s.pred.is_some())
            .collect();

        // ON CONFLICT [target]: the target names one unique constraint whose
        // conflicts are skipped; without it every unique constraint takes
        // part (SQLite/PG semantics). An unresolvable target errors instead
        // of silently widening the scope.
        let conflict_scope: Option<String> = match &insert.on {
            Some(sqlparser::ast::OnInsert::OnConflict(c)) => match &c.conflict_target {
                None => None,
                Some(sqlparser::ast::ConflictTarget::Columns(cols)) => {
                    let cols: Vec<String> = cols.iter().map(|i| i.value.clone()).collect();
                    Some(resolve_conflict_columns(&meta, &cols)?)
                }
                Some(sqlparser::ast::ConflictTarget::OnConstraint(name)) => {
                    let iname = obj_name(name);
                    Some(resolve_conflict_constraint(&meta, &table, &iname)?)
                }
            },
            _ => None,
        };
        // The targeted conflict root's column list, resolved once per
        // statement (was a fresh `index_columns_of` allocation per row).
        let scope_cols: Option<Vec<String>> = conflict_scope
            .as_deref()
            .map(|root| meta.index_columns_of(root));

        // 批内重复键:后者胜(SQLite/MySQL 的 OR REPLACE 逐行语义)。位移
        // 扫描只看语句前的树,批内冲突随后被树级 unique 检查整条打报错;
        // 先按唯一键把「被更晚的行覆盖」的早行去掉,再走位移扫描。判重用
        // 编码字节,与树查找同源。
        if replace
            && (!indexed.is_empty() || !composite_uniques.is_empty() || !partial_uniques.is_empty())
            && new_docs.len() > 1
        {
            let mut last_at: std::collections::BTreeMap<(String, Vec<u8>), usize> =
                std::collections::BTreeMap::new();
            for (i, doc) in new_docs.iter().enumerate() {
                for col in &indexed {
                    if let Some(k) = doc
                        .get(col)
                        .filter(|v| !matches!(v, Value::Null))
                        .and_then(|v| encode::encode_to_vec(v).ok())
                    {
                        last_at.insert((col.clone(), k), i);
                    }
                }
                for spec in &composite_uniques {
                    if let Some(k) =
                        index_key_of_spec(doc, spec).and_then(|v| encode::encode_to_vec(&v).ok())
                    {
                        last_at.insert((spec.root_key.clone(), k), i);
                    }
                }
                for spec in &partial_uniques {
                    if !matches!(
                        eval_expr(spec.pred.as_ref().expect("pred set"), doc)?,
                        Value::Bool(true)
                    ) {
                        continue;
                    }
                    if let Some(k) =
                        index_key_of_spec(doc, spec).and_then(|v| encode::encode_to_vec(&v).ok())
                    {
                        last_at.insert((spec.root_key.clone(), k), i);
                    }
                }
            }
            let mut kept: Vec<Object> = Vec::with_capacity(new_docs.len());
            for (i, doc) in new_docs.iter().enumerate() {
                let shadowed = indexed.iter().any(|col| {
                    doc.get(col)
                        .filter(|v| !matches!(v, Value::Null))
                        .and_then(|v| encode::encode_to_vec(v).ok())
                        .and_then(|k| last_at.get(&(col.clone(), k)))
                        .is_some_and(|&j| j > i)
                }) || composite_uniques.iter().any(|spec| {
                    index_key_of_spec(doc, spec)
                        .and_then(|v| encode::encode_to_vec(&v).ok())
                        .and_then(|k| last_at.get(&(spec.root_key.clone(), k)))
                        .is_some_and(|&j| j > i)
                }) || partial_uniques.iter().any(|spec| {
                    matches!(
                        eval_expr(spec.pred.as_ref().expect("pred set"), doc),
                        Ok(Value::Bool(true))
                    ) && index_key_of_spec(doc, spec)
                        .and_then(|v| encode::encode_to_vec(&v).ok())
                        .and_then(|k| last_at.get(&(spec.root_key.clone(), k)))
                        .is_some_and(|&j| j > i)
                });
                if !shadowed {
                    kept.push(doc.clone());
                }
            }
            new_docs = kept;
        }

        // Rows displaced by REPLACE INTO / OR REPLACE.
        let mut displaced: Vec<u64> = Vec::new();
        let mut displaced_docs: Vec<Object> = Vec::new();
        if replace
            && (!indexed.is_empty() || !composite_uniques.is_empty() || !partial_uniques.is_empty())
        {
            for n in &new_docs {
                for col in &indexed {
                    let Some(v) = n.get(col) else { continue };
                    if matches!(v, Value::Null) {
                        continue;
                    }
                    if let Some(loc) = BTree::open(roots[col])
                        .get(&PageReader::current(&self.pager), &tx, v)
                        .map_err(|e| index_err(col, e))?
                    {
                        displaced.push(loc);
                    }
                }
                for spec in &composite_uniques {
                    let Some(k) = index_key_of_spec(n, spec) else {
                        continue;
                    };
                    if let Some(loc) = BTree::open(roots[&spec.root_key])
                        .get(&PageReader::current(&self.pager), &tx, &k)
                        .map_err(|e| index_err(&spec.root_key, e))?
                    {
                        displaced.push(loc);
                    }
                }
                // Predicate-scoped displacement: only a qualifying candidate
                // can conflict with the partial tree (a non-qualifying row
                // inserts beside it, displacing nothing).
                for spec in &partial_uniques {
                    if !matches!(
                        eval_expr(spec.pred.as_ref().expect("pred set"), n)?,
                        Value::Bool(true)
                    ) {
                        continue;
                    }
                    let Some(k) = index_key_of_spec(n, spec) else {
                        continue;
                    };
                    if let Some(loc) = BTree::open(roots[&spec.root_key])
                        .get(&PageReader::current(&self.pager), &tx, &k)
                        .map_err(|e| index_err(&spec.root_key, e))?
                    {
                        displaced.push(loc);
                    }
                }
            }
        } else if replace
            && indexed.is_empty()
            && composite_uniques.is_empty()
            && (meta.primary_key.is_some() || !meta.unique.is_empty())
            && !new_docs.is_empty()
        {
            // Legacy layout: the constraint columns predate trees, so no
            // probe can locate the rows OR REPLACE displaces — the rows
            // survived into the whole-set unique check and failed the very
            // keys they were replacing. Find them by content instead
            // (new tables always build trees; only legacy volumes land
            // here). Intra-batch duplicates keep the tree path's
            // "later row wins" semantics.
            let constraint_cols: Vec<&String> =
                meta.primary_key.iter().chain(meta.unique.iter()).collect();
            let key_of = |d: &Object| -> Option<Vec<Vec<u8>>> {
                let mut parts = Vec::with_capacity(constraint_cols.len());
                for c in &constraint_cols {
                    let v = d.get(*c)?;
                    // NULL keys never displace (trees hold no NULL keys).
                    if matches!(v, Value::Null) {
                        return None;
                    }
                    parts.push(encode::encode_to_vec(v).ok()?);
                }
                Some(parts)
            };
            let mut last_at: std::collections::BTreeMap<Vec<Vec<u8>>, usize> =
                std::collections::BTreeMap::new();
            for (i, d) in new_docs.iter().enumerate() {
                if let Some(k) = key_of(d) {
                    last_at.insert(k, i);
                }
            }
            let kept: Vec<Object> = new_docs
                .iter()
                .enumerate()
                .filter(|(i, d)| {
                    let Some(k) = key_of(d) else {
                        return true;
                    };
                    last_at.get(&k).is_some_and(|&j| j == *i)
                })
                .map(|(_, d)| d.clone())
                .collect();
            let old_pairs = self.table_pairs_cx(&table)?;
            for (loc, od) in old_pairs {
                if let Some(k) = key_of(&od) {
                    if kept.iter().any(|n| key_of(n).as_deref() == Some(&k[..])) {
                        displaced.push(loc);
                    }
                }
            }
            new_docs = kept;
        }
        if !displaced.is_empty() {
            // One old row can be hit through several constraints at once
            // (its PK by one new row and its UNIQUE key by another — or one
            // new row matching both). Duplicates would double-count in the
            // FK parent-side scan (`count_in(removed)`) and un-defuse a
            // lost key that surviving rows still carry, rejecting a legal
            // replace; remove_many would also see the locator twice.
            displaced.sort_unstable();
            displaced.dedup();
            let affected: std::collections::BTreeSet<u32> = displaced
                .iter()
                .map(|l| crate::heap::unpack_loc(*l).0)
                .collect();
            let mut before = Vec::new();
            for pid in affected {
                before.extend(heap.page_docs(&PageReader::current(&self.pager), &tx, pid)?);
            }
            // Rows displaced by OR REPLACE are parent-side deletions: their
            // referenced keys must not vanish silently (same contract as
            // DELETE). New rows that keep the same key are replacements.
            displaced_docs = displaced
                .iter()
                .filter_map(|loc| {
                    before
                        .iter()
                        .find(|(l, _)| l == loc)
                        .map(|(_, d)| d.clone())
                })
                .collect();
            // Self-referential FKs must see the statement's FINAL state —
            // pre-state minus the displaced rows plus the placed rows. The
            // committed-state fallback would count references that vanish
            // together with their parent and reject a legal replace.
            let displaced_set: std::collections::BTreeSet<u64> =
                displaced.iter().copied().collect();
            let mut final_rows: Vec<Object> = self
                .table_pairs_cx(&table)?
                .into_iter()
                .filter(|(l, _)| !displaced_set.contains(l))
                .map(|(_, d)| d)
                .collect();
            final_rows.extend(new_docs.iter().cloned());
            self.check_fk_parent_delete_skipping(
                &table,
                &displaced_docs,
                &new_docs,
                &[],
                Some(&final_rows),
            )?;
            // OR REPLACE displacement is a real row deletion: DELETE
            // triggers fire for it (SQLite semantics), BEFORE before the
            // removal lands, AFTER once the row is gone.
            for d in &displaced_docs {
                self.fire_row_triggers(&table, true, TriggerFireEvent::Delete, Some(d), None)?;
            }
            let moves = heap.remove_many(&self.pager, &mut tx, &displaced)?;
            for loc in &displaced {
                let Some((_, doc)) = before.iter().find(|(l, _)| l == loc) else {
                    continue;
                };
                reindex_remove(&self.pager, &mut tx, &idx_specs, &mut roots, doc, *loc)?;
            }
            for (old_l, new_l) in &moves {
                reindex_repoint(
                    &self.pager,
                    &mut tx,
                    &idx_specs,
                    &mut roots,
                    &before,
                    *old_l,
                    *new_l,
                )?;
            }
            for d in &displaced_docs {
                self.fire_row_triggers(&table, false, TriggerFireEvent::Delete, Some(d), None)?;
            }
        }

        // Append the surviving rows and maintain the trees. Tree inserts
        // with unique=true ARE the duplicate check (within-batch duplicates
        // included: staged pages are visible to tree reads).
        let mut placed: Vec<(u64, Object)> = Vec::with_capacity(new_docs.len());
        let mut insert_failed: Option<SqlError> = None;
        // Upsert-UPDATE state: rows updated in place during this statement
        // (locator, pre-image, post-image) plus the RETURNING projection in
        // input order (inserted and updated rows alike).
        let mut updated: Vec<(u64, Object, Object)> = Vec::new();
        // heap.replace can MOVE a row past its page budget (tombstone +
        // append at the heap tail): a later touch of the same logical row
        // then finds it at the NEW locator, and the locator-keyed collapse
        // below would keep two entries — leaking the intermediate image
        // into the FK/unique checks and RETURNING. Map each relocated
        // locator back to the row's first-seen locator.
        let mut origin_of: std::collections::BTreeMap<u64, u64> = std::collections::BTreeMap::new();
        let mut ret_docs: Vec<Object> = Vec::with_capacity(new_docs.len());
        let mut du_outer = OuterFrom::new();
        du_outer.insert(table.clone());
        // Upsert arms fire UPDATE triggers with the arm's assigned columns
        // (UPDATE OF gating applies to them too).
        let du_changed: Option<Vec<String>> = if do_update {
            Some(
                du_assignments
                    .iter()
                    .filter_map(|a| match &a.target {
                        sqlparser::ast::AssignmentTarget::ColumnName(c) => Some(obj_name(c)),
                        _ => None,
                    })
                    .collect(),
            )
        } else {
            None
        };
        'outer: for doc in new_docs.into_iter() {
            // BEFORE INSERT fires before conflict resolution, per candidate
            // row (SQLite ordering: triggers, then constraints).
            self.fire_row_triggers(&table, true, TriggerFireEvent::Insert, None, Some(&doc))?;
            // Conflict probe shared by skip (DO NOTHING / OR IGNORE) and
            // upsert (DO UPDATE): locate the conflicting row's locator.
            // Untargeted = any unique constraint (first hit wins, PK probes
            // first); targeted = the named constraint's tree only — other
            // keys' conflicts still error at the insert below.
            let conflict_loc: Option<u64> = if !do_nothing && !do_update {
                None
            } else {
                match &conflict_scope {
                    None => {
                        let mut hit = None;
                        for col in &indexed {
                            let Some(v) = doc.get(col) else { continue };
                            if matches!(v, Value::Null) {
                                continue;
                            }
                            if let Some(loc) = BTree::open(roots[col])
                                .get(&PageReader::current(&self.pager), &tx, v)
                                .map_err(|e| index_err(col, e))?
                            {
                                hit = Some(loc);
                                break;
                            }
                        }
                        // Composite unique indexes resolve "any unique key"
                        // for the undirected policies too.
                        if hit.is_none() {
                            for spec in &composite_uniques {
                                let Some(k) = index_key_of_spec(&doc, spec) else {
                                    continue;
                                };
                                if let Some(loc) = BTree::open(roots[&spec.root_key])
                                    .get(&PageReader::current(&self.pager), &tx, &k)
                                    .map_err(|e| index_err(&spec.root_key, e))?
                                {
                                    hit = Some(loc);
                                    break;
                                }
                            }
                        }
                        // Predicate-scoped conflicts: only a qualifying
                        // candidate probes the partial tree.
                        if hit.is_none() {
                            for spec in &partial_uniques {
                                if !matches!(
                                    eval_expr(spec.pred.as_ref().expect("pred set"), &doc)?,
                                    Value::Bool(true)
                                ) {
                                    continue;
                                }
                                let Some(k) = index_key_of_spec(&doc, spec) else {
                                    continue;
                                };
                                if let Some(loc) = BTree::open(roots[&spec.root_key])
                                    .get(&PageReader::current(&self.pager), &tx, &k)
                                    .map_err(|e| index_err(&spec.root_key, e))?
                                {
                                    hit = Some(loc);
                                    break;
                                }
                            }
                        }
                        hit
                    }
                    Some(root) => {
                        if let Some(key) = index_key_of(&doc, scope_cols.as_deref().unwrap()) {
                            BTree::open(roots[root.as_str()])
                                .get(&PageReader::current(&self.pager), &tx, &key)
                                .map_err(|e| index_err(root, e))?
                        } else {
                            None
                        }
                    }
                }
            };
            if let Some(loc) = conflict_loc {
                if do_nothing {
                    continue 'outer; // conflict: skip this row
                }
                // ---- upsert arm: update the conflicting row in place ----
                // PostgreSQL semantics: WHERE and SET see the OLD row for
                // bare column references; EXCLUDED.col (and MySQL's
                // VALUES(col)) carry the candidate row's values.
                let page = crate::heap::unpack_loc(loc).0;
                let before = heap.page_docs(&PageReader::current(&self.pager), &tx, page)?;
                let Some((_, existing)) = before.iter().find(|(l, _)| *l == loc) else {
                    self.pager.abort_tx(tx)?;
                    return err(format!(
                        "upsert: conflicting row vanished mid-statement (locator {loc:#x})"
                    ));
                };
                if let Some(sel) = &du_selection {
                    let mut sel = sel.clone();
                    subst_upsert_proposed(&mut sel, &doc)?;
                    if !self.matches_cx_in(&Some(sel), existing, &du_outer)? {
                        // WHERE filtered the update out: the row keeps its
                        // image and the candidate is not inserted (PG).
                        continue 'outer;
                    }
                }
                let mut subst = du_assignments.clone();
                for a in &mut subst {
                    subst_upsert_proposed(&mut a.value, &doc)?;
                }
                let new_vals = match self.eval_assignments_cx(&subst, existing, &du_outer) {
                    Ok(v) => v,
                    Err(e) => {
                        self.pager.abort_tx(tx)?;
                        return Err(e);
                    }
                };
                let mut merged = existing.clone();
                for (col_name, v) in new_vals {
                    merged.insert(col_name, v);
                }
                if let Err(e) = meta.check(&merged) {
                    self.pager.abort_tx(tx)?;
                    return Err(e);
                }
                // Two-phase index maintenance for THIS row: drop its old
                // entries, write the new image, repoint the in-page repack's
                // moved survivors, insert the new entries. Later batch rows
                // see the updated trees (sequential upsert semantics, as in
                // MySQL; PostgreSQL would reject a second touch instead).
                if let Err(e) =
                    reindex_remove(&self.pager, &mut tx, &idx_specs, &mut roots, existing, loc)
                {
                    self.pager.abort_tx(tx)?;
                    return Err(e);
                }
                let out = match heap.replace(&self.pager, &mut tx, loc, &merged) {
                    Ok(o) => o,
                    Err(e) => {
                        self.pager.abort_tx(tx)?;
                        return Err(e.into());
                    }
                };
                for (old_l, new_l) in &out.moved {
                    if *old_l == loc {
                        continue; // this row's own slot: entries removed above
                    }
                    if let Err(e) = reindex_repoint(
                        &self.pager,
                        &mut tx,
                        &idx_specs,
                        &mut roots,
                        &before,
                        *old_l,
                        *new_l,
                    ) {
                        self.pager.abort_tx(tx)?;
                        return Err(e);
                    }
                }
                if let Err(e) = reindex_insert(
                    &self.pager,
                    &mut tx,
                    &idx_specs,
                    &mut roots,
                    &merged,
                    out.placed,
                ) {
                    self.pager.abort_tx(tx)?;
                    return Err(e);
                }
                if out.placed != loc {
                    let origin = origin_of.get(&loc).copied().unwrap_or(loc);
                    origin_of.insert(out.placed, origin);
                }
                let collapse_key = origin_of.get(&loc).copied().unwrap_or(loc);
                updated.push((collapse_key, existing.clone(), merged.clone()));
                ret_docs.push(merged);
                // An upsert that updated in place fires the UPDATE triggers
                // (SQLite/PostgreSQL semantics), not the INSERT ones.
                let changed = du_changed.as_deref();
                let fired_new = ret_docs.last().expect("just pushed");
                self.fire_row_triggers(
                    &table,
                    true,
                    TriggerFireEvent::Update(changed),
                    Some(existing),
                    Some(fired_new),
                )?;
                self.fire_row_triggers(
                    &table,
                    false,
                    TriggerFireEvent::Update(changed),
                    Some(existing),
                    Some(fired_new),
                )?;
                continue 'outer;
            }
            let loc = match heap.insert(&self.pager, &mut tx, &doc) {
                Ok(l) => l,
                Err(e) => {
                    self.pager.abort_tx(tx)?;
                    return Err(e.into());
                }
            };
            for col in &indexed {
                let Some(v) = doc.get(col) else { continue };
                if matches!(v, Value::Null) {
                    continue;
                }
                let root = roots[col];
                let mut tree = BTree::open(root);
                if let Err(e) = tree.insert(&self.pager, &mut tx, v.clone(), loc, true) {
                    insert_failed = Some(index_err(col, e));
                    break 'outer;
                }
                if tree.root != root {
                    roots.insert(col.clone(), tree.root);
                }
            }
            // Non-constraint CREATE INDEX trees. Composite unique trees
            // (CREATE UNIQUE INDEX over several columns) enforce their
            // duplicates right here, at tree-insert time.
            for spec in &idx_specs {
                if indexed.contains(&spec.root_key) {
                    continue;
                }
                // Partial index: only qualifying rows enter the tree.
                if let Some(p) = &spec.pred {
                    if !matches!(eval_expr(p, &doc)?, Value::Bool(true)) {
                        continue;
                    }
                }
                let Some(v) = index_key_of_spec(&doc, spec) else {
                    continue;
                };
                let root = roots[&spec.root_key];
                let mut tree = BTree::open(root);
                tree.insert(&self.pager, &mut tx, v, loc, spec.unique)
                    .map_err(|e| index_err(&spec.root_key, e))?;
                if tree.root != root {
                    roots.insert(spec.root_key.clone(), tree.root);
                }
            }
            if insert.returning.is_some() {
                ret_docs.push(doc.clone());
            }
            placed.push((loc, doc));
            // AFTER INSERT: the row (and its tree entries) is in place.
            self.fire_row_triggers(
                &table,
                false,
                TriggerFireEvent::Insert,
                None,
                Some(&placed.last().expect("just pushed").1),
            )?;
        }
        if let Some(e) = insert_failed {
            self.pager.abort_tx(tx)?;
            return Err(e);
        }
        // Child-side FK over the FINAL row set. ON CONFLICT DO NOTHING /
        // OR IGNORE filter rows out after the batch was built — validating
        // against the pre-filter batch let a skipped parent candidate
        // legitimize a child that lands alone (dangling reference).
        // Self-references resolve against the placed batch itself;
        // statement-internal references count, including forward ones.
        // Upsert-UPDATE rows join the final set: their new images must
        // reference existing parents like any inserted row.
        // A multi-row batch may touch the SAME row twice (sequential
        // upsert semantics: later rows can route onto an earlier row
        // through either unique key). Every touch pushed (old, merged),
        // but only the FIRST old image and the LAST merged image of a
        // locator are real — intermediate images were overwritten and do
        // not exist in the final table. Feeding them into the FK/unique
        // checks below could validate (or reject) against keys no
        // surviving row carries, e.g. a parent key vacated by touch one
        // and re-supply-shaped by touch two's intermediate image.
        if updated.len() > 1 {
            let mut collapsed: std::collections::BTreeMap<u64, (usize, usize)> =
                std::collections::BTreeMap::new();
            for (i, (loc, _, _)) in updated.iter().enumerate() {
                match collapsed.get_mut(loc) {
                    Some((_, last)) => *last = i,
                    None => {
                        collapsed.insert(*loc, (i, i));
                    }
                }
            }
            if collapsed.len() < updated.len() {
                updated = collapsed
                    .into_iter()
                    .map(|(loc, (first, last))| {
                        (loc, updated[first].1.clone(), updated[last].2.clone())
                    })
                    .collect();
            }
        }
        if !meta.foreign_keys.is_empty() && (!placed.is_empty() || !updated.is_empty()) {
            let mut final_docs: Vec<Object> = placed.iter().map(|(_, d)| d.clone()).collect();
            final_docs.extend(updated.iter().map(|(_, _, n)| n.clone()));
            // Self-referential FKs need the statement's COMPLETE final state
            // (pre-state minus the replaced old images plus these images):
            // the pre-state heap still carries keys an upsert-UPDATE vacates
            // (`VALUES (1,1) ON CONFLICT (id) DO UPDATE SET id = 3, p = 1`).
            // Plain INSERT keeps `None`: nothing is replaced, so same_batch
            // plus the pre-state heap is already the final state.
            let self_final: Option<Vec<Object>> =
                if !updated.is_empty() && meta.foreign_keys.iter().any(|(_, rt, _)| rt == &table) {
                    let old_keys: std::collections::BTreeSet<Vec<u8>> =
                        updated.iter().map(|(_, o, _)| object_key(o)).collect();
                    let mut final_state = self.table_docs_cx(&table)?;
                    final_state.retain(|d| !old_keys.contains(&object_key(d)));
                    final_state.extend(final_docs.iter().cloned());
                    Some(final_state)
                } else {
                    None
                };
            for doc in &final_docs {
                // A big INSERT ... SELECT walks this per placed row: keep the
                // statement timeout armed like every other row loop.
                self.stmt_deadline.check()?;
                if let Err(e) =
                    self.check_fks_in(&table, &meta, doc, &final_docs, self_final.as_deref())
                {
                    self.pager.abort_tx(tx)?;
                    return Err(e);
                }
            }
        }
        // Parent-side FK for upsert-updated rows: the old image's key
        // values disappear exactly like a DELETE's and must not be
        // referenced by children (new images already checked above). This
        // runs OUTSIDE the target's own-FK gate — the referencing children
        // belong to OTHER tables, which do not care whether the target
        // declares FKs of its own.
        if !updated.is_empty() {
            let has_self_fk = meta.foreign_keys.iter().any(|(_, rt, _)| rt == &table);
            let self_final: Option<Vec<Object>> = if has_self_fk {
                let old_keys: std::collections::BTreeSet<Vec<u8>> =
                    updated.iter().map(|(_, o, _)| object_key(o)).collect();
                let mut final_state = self.table_docs_cx(&table)?;
                final_state.retain(|d| !old_keys.contains(&object_key(d)));
                final_state.extend(updated.iter().map(|(_, _, n)| n.clone()));
                final_state.extend(placed.iter().map(|(_, d)| d.clone()));
                Some(final_state)
            } else {
                None
            };
            let olds: Vec<Object> = updated.iter().map(|(_, o, _)| o.clone()).collect();
            // `news` is the "keys that still exist after this statement"
            // set: rows PLACED by the same batch can re-supply a key the
            // updated rows vacated (INSERT INTO p VALUES (1),(1) ON CONFLICT
            // (id) DO UPDATE SET id = 99 — the second (1) no longer conflicts
            // and lands as a plain insert). Counting only the updated images
            // false-errored children referencing a key that is still present
            // through the placed row.
            let mut news: Vec<Object> = updated.iter().map(|(_, _, n)| n.clone()).collect();
            news.extend(placed.iter().map(|(_, d)| d.clone()));
            if let Err(e) = self.check_fk_parent_delete_skipping(
                &table,
                &olds,
                &news,
                &[],
                self_final.as_deref(),
            ) {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // Legacy files whose constraint columns predate trees keep the
        // whole-set duplicate check; tables with no constraints skip it.
        // ANY untreed constraint column triggers it (same gate as the
        // UPDATE fast path): an all-or-nothing gate used to skip the check
        // whenever a sibling column had a tree, silently admitting
        // duplicates on the treeless one.
        let has_constraints = meta.primary_key.is_some() || !meta.unique.is_empty();
        let all_treed = meta
            .primary_key
            .iter()
            .chain(meta.unique.iter())
            .all(|c| indexed.contains(c));
        if has_constraints && !all_treed && (!placed.is_empty() || !updated.is_empty()) {
            // A failed scan must abort, not silently skip the unique check.
            let mut combined = match (Heap {
                pages: meta.pages.clone(),
                overflow_free: meta.overflow_free.clone(),
                dropped: Vec::new(),
            }
            .scan(&PageReader::current(&self.pager)))
            {
                Ok(docs) => docs,
                Err(e) => {
                    self.pager.abort_tx(tx)?;
                    return Err(e.into());
                }
            };
            if !updated.is_empty() {
                // The scan sees the PRE-statement table: updated rows carry
                // their old images here. Swap them for the new images
                // (encoding-compare removes exactly the one old row — its
                // unique-key values are distinct per row, so byte-identical
                // duplicates of an old image cannot exist).
                let olds: std::collections::HashSet<Vec<u8>> = updated
                    .iter()
                    .filter_map(|(_, o, _)| encode::encode_to_vec(&Value::Object(o.clone())).ok())
                    .collect();
                combined.retain(|d| {
                    !encode::encode_to_vec(&Value::Object(d.clone()))
                        .map(|k| olds.contains(&k))
                        .unwrap_or(false)
                });
                combined.extend(updated.iter().map(|(_, _, n)| n.clone()));
            }
            if !displaced_docs.is_empty() {
                // The no-tx scan also still sees OR REPLACE's displaced rows
                // (their deletions are staged in THIS tx): keep them and the
                // displaced old image pairs with its own replacement, making
                // check_unique false-error on the very keys REPLACE displaced.
                // Same encoding-compare argument as `updated`: byte-identical
                // duplicates of a displaced image cannot coexist in a table
                // that has constraints at all.
                let gone: std::collections::HashSet<Vec<u8>> = displaced_docs
                    .iter()
                    .filter_map(|d| encode::encode_to_vec(&Value::Object(d.clone())).ok())
                    .collect();
                combined.retain(|d| {
                    !encode::encode_to_vec(&Value::Object(d.clone()))
                        .map(|k| gone.contains(&k))
                        .unwrap_or(false)
                });
            }
            combined.extend(placed.iter().map(|(_, d)| d.clone()));
            if let Err(e) = meta.check_unique(&combined) {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // Affected = inserted + upsert-updated rows (PostgreSQL reports the
        // union the same way).
        let count = (placed.len() + updated.len()) as u64;
        // Emptied heap pages are released inside this transaction so later
        // statements reuse them instead of growing the file.
        for p in std::mem::take(&mut heap.dropped) {
            self.pager.free_page(&mut tx, p)?;
        }
        let dotted_now = self.note_dotted_fields(
            &table,
            placed
                .iter()
                .map(|(_, d)| d)
                .chain(updated.iter().map(|(_, _, new)| new)),
        );
        if dotted_now
            || heap.pages != meta.pages
            || roots != meta.index_roots
            || heap.overflow_free != meta.overflow_free
        {
            self.sync_table_layout(
                &mut tx,
                &table,
                heap.pages.clone(),
                roots,
                heap.overflow_free.clone(),
            )?;
        }
        self.commit_pager_tx(tx)?;
        // AUTOINCREMENT counter: never regress, follow explicit max.
        if let Some(col) = &meta.autoinc {
            // The upsert-UPDATE arm can raise the live max past every placed
            // id (SET id = <higher>) — invalidate like the UPDATE fast path,
            // or the stale cache keeps issuing already-taken ids and every
            // subsequent autoincrement INSERT fails on the unique tree.
            let du_touched = do_update
                && du_assignments.iter().any(|a| {
                    matches!(&a.target, sqlparser::ast::AssignmentTarget::ColumnName(c) if obj_name(c) == *col)
                });
            if du_touched {
                self.autoinc_cache.remove(&table);
            } else {
                let used = placed
                    .iter()
                    .filter_map(|(_, d)| match d.get(col) {
                        Some(Value::Int(i)) => Some((*i).saturating_add(1)),
                        _ => None,
                    })
                    .max()
                    .unwrap_or(next_autoinc)
                    .max(next_autoinc);
                self.autoinc_cache.insert(table.clone(), used);
            }
            // Max id this statement actually placed (explicit values count;
            // an INSERT that placed no rows leaves the previous value).
            self.last_insert_id = placed
                .iter()
                .filter_map(|(_, d)| d.get(col))
                .filter_map(|v| v.as_i64())
                .max();
        }
        if let Some(ret) = &insert.returning {
            return project_returning(ret, &ret_docs);
        }
        Ok(ExecOutcome::Affected(count))
    }

    /// MERGE INTO target USING source ON (cond) — Oracle/SQL-standard
    /// upsert over arbitrary match conditions (ON CONFLICT only covers
    /// unique-key conflicts). Execution: load the source rows, evaluate ON
    /// against every (target, source) pair, then apply per pair —
    /// WHEN MATCHED THEN UPDATE SET …, WHEN NOT MATCHED THEN INSERT ….
    /// Determinism: the merge walks target storage order, so replication
    /// replays converge. Two source rows matching one target row is an
    /// error (Oracle ORA-30926 semantics).
    fn exec_merge(&mut self, merge: sqlparser::ast::Merge) -> Result<ExecOutcome> {
        use sqlparser::ast::{MergeAction, MergeClauseKind};

        // Target: a simple table.
        let sqlparser::ast::TableFactor::Table {
            name: tname_ident,
            alias: talias,
            ..
        } = &merge.table
        else {
            return err("MERGE target must be a simple table");
        };
        let tname = obj_name(tname_ident);
        let tkey = talias
            .as_ref()
            .map(|a| a.name.value.clone())
            .unwrap_or_else(|| tname.clone());
        let Some(meta) = self.tables.get(&tname).cloned() else {
            return err(format!("table {tname} does not exist"));
        };
        // Views have no storage: every other write shape rejects them here
        // (exec_insert/update/delete, TRUNCATE, ALTER, CREATE INDEX);
        // without this a MERGE inserts into the view's private empty
        // heap — invisible rows and a dump that cannot replay.
        ensure_not_view("MERGE into", &tname, &meta)?;

        // Exactly one WHEN MATCHED (UPDATE) and one WHEN NOT MATCHED
        // (INSERT) clause; per-clause predicates, BY SOURCE, DELETE WHERE
        // and UPDATE WHERE are rejected loudly (v1 surface).
        let mut matched_upd: Option<Vec<sqlparser::ast::Assignment>> = None;
        let mut not_matched_ins: Option<(Vec<String>, Vec<SqlExpr>)> = None;
        for cl in &merge.clauses {
            if cl.predicate.is_some() {
                return err("MERGE WHEN … AND <predicate> is not supported");
            }
            match cl.clause_kind {
                MergeClauseKind::NotMatchedBySource => {
                    return err("WHEN … BY SOURCE is not supported");
                }
                MergeClauseKind::Matched | MergeClauseKind::NotMatchedByTarget => {
                    if matched_upd.is_some() {
                        return err("duplicate WHEN MATCHED clause");
                    }
                    let MergeAction::Update(upd) = &cl.action else {
                        return err("WHEN MATCHED supports only UPDATE \
                             (DELETE/other actions are not supported)");
                    };
                    if upd.update_predicate.is_some() || upd.delete_predicate.is_some() {
                        return err("MERGE UPDATE WHERE/DELETE WHERE is not supported");
                    }
                    matched_upd = Some(upd.assignments.clone());
                }
                MergeClauseKind::NotMatched => {
                    if not_matched_ins.is_some() {
                        return err("duplicate WHEN NOT MATCHED clause");
                    }
                    let MergeAction::Insert(ins) = &cl.action else {
                        return err("WHEN NOT MATCHED THEN UPDATE is not supported");
                    };
                    if ins.insert_predicate.is_some() {
                        return err("MERGE INSERT predicate is not supported");
                    }
                    let sqlparser::ast::MergeInsertKind::Values(values) = &ins.kind else {
                        return err("MERGE INSERT ROW is not supported");
                    };
                    if values.rows.len() != 1 {
                        return err("MERGE INSERT VALUES must have exactly one row");
                    }
                    let mut cols = Vec::new();
                    for c in &ins.columns {
                        let col = obj_name(c);
                        if !meta.columns.contains(&col) {
                            return err(format!("column {col} does not exist"));
                        }
                        if cols.contains(&col) {
                            return err(format!("duplicate column name: {col}"));
                        }
                        cols.push(col);
                    }
                    if cols.is_empty() {
                        // No column list: the VALUES map onto the table's
                        // declared column order (the INSERT rule). Zipping
                        // against the empty list used to silently drop the
                        // values and append an all-NULL row.
                        if values.rows[0].content.len() != meta.columns.len() {
                            return err(format!(
                                "MERGE INSERT has {} values but the table has {} \
                                 columns; use an explicit column list",
                                values.rows[0].content.len(),
                                meta.columns.len()
                            ));
                        }
                        cols = meta.columns.clone();
                    }
                    let mut exprs = Vec::new();
                    for row in &values.rows {
                        for e in row.content.iter() {
                            exprs.push(e.clone());
                        }
                    }
                    not_matched_ins = Some((cols, exprs));
                }
            }
        }
        // Source rows: plain table or derived subquery (no CTE access in
        // v1 — the MERGE statement is not a SELECT statement).
        let (_, src_alias, src_rows) = self
            .read_cx()
            .load_table_factor(&merge.source, &Ctes::new())?;
        // Source-column qualifier: the alias for a plain table (falling back
        // to its name), the derived-table alias when given, else `source`.
        // Losing the derived alias here would make `feed.col` resolve to the
        // target's bare column via fallback and every source row would match
        // the same target row (spurious "multiple source rows matched").
        let skey = match &merge.source {
            sqlparser::ast::TableFactor::Table { name, alias, .. } => alias
                .as_ref()
                .map(|a| a.name.value.clone())
                .unwrap_or_else(|| obj_name(name)),
            _ => src_alias
                .filter(|a| !a.is_empty())
                .unwrap_or_else(|| "source".to_string()),
        };
        // Same alias for source and target: the join row keys collide and
        // the TARGET qualifier overwrites the source's, so `ON x.id =
        // x.id` is trivially true and SET reads the target's own pre-image
        // — every target row matches every source row (mass wrong updates
        // or a spurious "cannot update the same row twice"). MySQL and SQL
        // Server reject the shape; so do we.
        if skey == tkey {
            return err(format!(
                "MERGE source and target aliases must differ (both are '{skey}')"
            ));
        }

        // Target rows with locators (storage order — deterministic replay
        // on replication peers).
        let tdocs = self.table_pairs_cx(&tname)?;

        // ROWNUM has no row stream to number in MERGE's ON / arms: it reads
        // NULL and `NULL <= n` is TRUE under the documented total order, so
        // every pair would silently match. Fail loudly (subquery sources may
        // still use ROWNUM — that stream is their own).
        if refs_rownum(&merge.on)
            || matched_upd
                .as_ref()
                .is_some_and(|asg| asg.iter().any(|a| refs_rownum(&a.value)))
            || not_matched_ins
                .as_ref()
                .is_some_and(|(_, exprs)| exprs.iter().any(refs_rownum))
        {
            return err("ROWNUM is not supported in MERGE ON / WHEN arms");
        }

        // Pair every source row with its matching target row: ON evaluates
        // on the merged namespace (target columns first; source columns are
        // additionally available qualified as `skey.col`).
        let mut pairs: Vec<(u64, Object, usize)> = Vec::new(); // (t_loc, t_doc, s_idx)
        let mut s_consumed = vec![false; src_rows.len()];
        for (t_loc, t_doc) in &tdocs {
            let mut hits = 0;
            for (si, s_doc) in src_rows.iter().enumerate() {
                // O(target×source) pairing must stay interruptible under
                // the statement timeout like every other row loop.
                self.stmt_deadline.check()?;
                let row = Self::merge_join_row(t_doc, tkey.as_str(), s_doc, &skey);
                if matches!(eval_expr(&merge.on, &row)?, Value::Bool(true)) {
                    hits += 1;
                    if hits > 1 && matched_upd.is_some() {
                        // Only an UPDATE arm makes a second match a conflict
                        // (it would update the row twice). With no WHEN
                        // MATCHED clause every source row that matched is
                        // simply consumed — nothing to update.
                        return err(format!(
                            "MERGE cannot update the same row of {tname} twice \
                             (multiple source rows matched)"
                        ));
                    }
                    pairs.push((*t_loc, t_doc.clone(), si));
                    s_consumed[si] = true;
                }
            }
        }

        // Build the matched updates: assignments evaluate on the merged
        // namespace (target columns and qualified source columns).
        let mut updates: Vec<(u64, Object, Object)> = Vec::new();
        // An explicit autoinc id (INSERT arm) or an assignment touching the
        // autoinc column (UPDATE arm) invalidates the session's high-water
        // cache: `merge_next_autoinc` only tracks engine-generated ids, and
        // keeping the stale cache made the next plain INSERT collide with
        // the explicit value (UNIQUE constraint failed).
        let mut autoinc_mutated = false;
        if let Some(assignments) = &matched_upd {
            for (t_loc, t_doc, si) in &pairs {
                let s_doc = &src_rows[*si];
                let row = Self::merge_join_row(t_doc, tkey.as_str(), s_doc, &skey);
                let mut new_doc = t_doc.clone();
                for a in assignments {
                    let col = match &a.target {
                        sqlparser::ast::AssignmentTarget::ColumnName(c) => obj_name(c),
                        other => {
                            return err(format!("unsupported MERGE assignment target: {other}"))
                        }
                    };
                    if Some(&col) == meta.autoinc.as_ref() {
                        autoinc_mutated = true;
                    }
                    let v = eval_expr(&a.value, &row)?;
                    new_doc.insert(col, v);
                }
                // Same constraint gate as UPDATE: NOT NULL/CHECK and the
                // child-side FK must hold for the merged image (FK check
                // runs after the batch is collected — self/intra-statement
                // references count as parent candidates).
                meta.check(&new_doc)?;
                updates.push((*t_loc, t_doc.clone(), new_doc));
            }
            // NOTE: both FK directions are validated against the statement's
            // FINAL state after the INSERT arm below — checking here (against
            // pre-statement data) let a MERGE land a dangling self-reference
            // (UPDATE removes the parent the INSERT arm still points at) and
            // wrongly reject parents the other arm had just created.
        }

        // One pager transaction for heap pages and index trees alike.
        let mut heap = Heap {
            pages: meta.pages.clone(),
            overflow_free: meta.overflow_free.clone(),
            dropped: Vec::new(),
        };
        let mut roots = meta.index_roots.clone();
        let idx_specs = idx_specs(&meta, &roots);
        let mut tx = self.pager.begin_tx();

        // Pass 1: drop every matched row's old index entries before any
        // replacement lands (a multi-row key shift must not collide with a
        // not-yet-replaced row's still-present old key).
        for (loc, old_doc, _) in &updates {
            if let Err(e) =
                reindex_remove(&self.pager, &mut tx, &idx_specs, &mut roots, old_doc, *loc)
            {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // Pass 2: replace the matched rows, following in-page repacks.
        for i in 0..updates.len() {
            let (loc, new_doc) = (updates[i].0, updates[i].2.clone());
            let page = crate::heap::unpack_loc(loc).0;
            let before = heap.page_docs(&PageReader::current(&self.pager), &tx, page)?;
            // Pre-fixup pending locators; see the identical logic in the
            // UPDATE fast path.
            let pending_locs: Vec<u64> = updates.iter().skip(i + 1).map(|(l, _, _)| *l).collect();
            let out = heap.replace(&self.pager, &mut tx, loc, &new_doc)?;
            if !out.moved.is_empty() {
                for pending in updates.iter_mut().skip(i + 1) {
                    if let Some((_, new_l)) = out.moved.iter().find(|(old, _)| *old == pending.0) {
                        pending.0 = *new_l;
                    }
                }
            }
            for (old_l, new_l) in &out.moved {
                // Same rule as the UPDATE fast path: pending rows were
                // stripped in pass 1 and get their new entries in their own
                // iteration; already-processed rows must follow the repack.
                if *old_l == loc || pending_locs.contains(old_l) {
                    continue;
                }
                if let Err(e) = reindex_repoint(
                    &self.pager,
                    &mut tx,
                    &idx_specs,
                    &mut roots,
                    &before,
                    *old_l,
                    *new_l,
                ) {
                    self.pager.abort_tx(tx)?;
                    return Err(e);
                }
            }
            if let Err(e) = reindex_insert(
                &self.pager,
                &mut tx,
                &idx_specs,
                &mut roots,
                &new_doc,
                out.placed,
            ) {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // WHEN NOT MATCHED THEN INSERT: appended rows go through the same
        // tree inserts (unique trees reject duplicates) and FK checks as
        // plain inserts. Only source rows that matched no target row are
        // inserted.
        let mut inserted = 0usize;
        let mut inserted_docs: Vec<Object> = Vec::new();
        // 本语句插入行的最大自增 id 与下一个自增值:提交成功后才写进会话
        // 状态(与 INSERT 路径对齐),失败回滚不留幻影 SCOPE_IDENTITY。
        let mut merge_last_id: Option<i64> = None;
        let mut merge_next_autoinc = if meta.autoinc.is_some() {
            self.autoinc_next_for(&tname, &meta)?
        } else {
            0
        };
        if let Some((cols, exprs)) = &not_matched_ins {
            // Auto-generated GUIDs are random: letting each node generate its
            // own would silently diverge replicas (the INSERT path rewrites
            // the statement with the values; a MERGE rewrite would have to
            // rewrite the whole branching statement).
            if meta.autoguid.is_some() {
                return err(
                    "MERGE ... WHEN NOT MATCHED THEN INSERT is not supported on \
                     tables with an auto-generated GUID column",
                );
            }
            let mut next_autoinc = merge_next_autoinc;
            let mut default_exprs: std::collections::HashMap<String, SqlExpr> =
                std::collections::HashMap::new();
            for (si, s_doc) in src_rows.iter().enumerate() {
                if s_consumed[si] {
                    continue;
                }
                self.stmt_deadline.check()?;
                let mut doc = Object::new();
                for (c, e) in cols.iter().zip(exprs.iter()) {
                    let v = eval_expr(e, s_doc)?;
                    doc.insert(c.clone(), v);
                }
                // Same generation rules as INSERT: missing/NULL AUTOINCREMENT
                // gets max+1, declared DEFAULTs fill omitted columns.
                if let Some(col) = &meta.autoinc {
                    match doc.get(col) {
                        Some(Value::Null) | None => {
                            doc.insert(col.clone(), Value::Int(next_autoinc));
                            next_autoinc = next_autoinc.saturating_add(1);
                        }
                        // Explicit id: advance the in-statement watermark so a
                        // later source row that omits the id doesn't reuse it
                        // (same rule as INSERT); the engine didn't allocate
                        // it, so the cache is still dropped at commit and the
                        // next statement recomputes max+1.
                        Some(Value::Int(v)) => {
                            next_autoinc = next_autoinc.max(v.saturating_add(1));
                            autoinc_mutated = true;
                        }
                        _ => {
                            autoinc_mutated = true;
                        }
                    }
                }
                for (col, text) in &meta.defaults {
                    if !doc.contains_key(col) {
                        let e = match default_exprs.get(col) {
                            Some(e) => e,
                            None => {
                                let e = parse_expr_text(text)?;
                                default_exprs.insert(col.clone(), e);
                                default_exprs.get(col).expect("just inserted")
                            }
                        };
                        if expr_calls_wall_clock(e) {
                            // MERGE has no canonical resolved-text rewrite
                            // (unlike INSERT); replaying the statement on a
                            // peer would stamp a different clock. Fail loudly
                            // instead of silently diverging.
                            return err(
                                "MERGE INSERT cannot apply a wall-clock or random DEFAULT \
                                 (NOW/SYSDATE/CURRENT_TIMESTAMP/GETDATE/RAND); \
                                 supply the column explicitly",
                            );
                        }
                        doc.insert(col.clone(), eval_const(e)?);
                    }
                }
                meta.check(&doc)?;
                // FK child-side validation moved to the unified post-statement
                // check below (final state, both arms included).
                inserted_docs.push(doc.clone());
                let loc = heap.insert(&self.pager, &mut tx, &doc)?;
                reindex_insert(&self.pager, &mut tx, &idx_specs, &mut roots, &doc, loc)?;
                if let Some(col) = &meta.autoinc {
                    if let Some(Value::Int(i)) = doc.get(col) {
                        // 只累计,提交成功后才落到 last_insert_id/autoinc_cache:
                        // 循环中途失败回滚后,SCOPE_IDENTITY 不得读到幻影 id。
                        let cur = merge_last_id.unwrap_or(i64::MIN);
                        merge_last_id = Some(cur.max(*i));
                    }
                }
                inserted += 1;
            }
            merge_next_autoinc = next_autoinc;
        }
        // Legacy files whose constraint columns predate trees keep the
        // whole-set duplicate check (same gate as the INSERT path): with no
        // constraint tree, the reindex inserts above cannot reject
        // duplicates, and a MERGE could silently write a repeated business
        // key. Everything so far is staged in `tx` — the abort paths below
        // discard it (all-or-nothing).
        let has_constraints = meta.primary_key.is_some() || !meta.unique.is_empty();
        // ALL constraint columns must be treed to skip the whole-set check —
        // `any` here would let a mixed state (one treed, one treeless
        // constraint) skip the check and silently admit duplicates on the
        // treeless one (same all-or-nothing gate as the INSERT path).
        let constraint_treed = meta
            .primary_key
            .iter()
            .chain(meta.unique.iter())
            .all(|c| roots.contains_key(c));
        if has_constraints && !constraint_treed && (updates.len() + inserted) > 0 {
            let mut combined: Vec<Object> = match (Heap {
                pages: meta.pages.clone(),
                overflow_free: meta.overflow_free.clone(),
                dropped: Vec::new(),
            }
            .scan(&PageReader::current(&self.pager)))
            {
                Ok(docs) => docs,
                Err(e) => {
                    self.pager.abort_tx(tx)?;
                    return Err(e.into());
                }
            };
            // Swap the updated rows' pre-images for their post-images
            // (unambiguous: a pre-image's PK value is unique in committed
            // data), then add the not-matched inserts.
            for (_, old, _) in &updates {
                combined.retain(|d| d != old);
            }
            combined.extend(updates.iter().map(|(_, _, n)| n.clone()));
            combined.extend(inserted_docs.iter().cloned());
            if let Err(e) = meta.check_unique(&combined) {
                self.pager.abort_tx(tx)?;
                return Err(e);
            }
        }
        // FK validation against the statement's FINAL state: pre-state −
        // updated pre-images + updated post-images + inserted rows. Both
        // directions used to be checked per-arm against pre-statement data,
        // which let a MERGE land a dangling self-reference (UPDATE removes
        // the parent the INSERT arm points at) or wrongly reject a parent
        // the other arm had just created.
        if !updates.is_empty() || !inserted_docs.is_empty() {
            let final_docs: Vec<Object> = {
                let mut docs = match self.table_docs_cx(&tname) {
                    Ok(d) => d,
                    Err(e) => {
                        self.pager.abort_tx(tx)?;
                        return Err(e);
                    }
                };
                for (_, old, _) in &updates {
                    docs.retain(|d| d != old);
                }
                docs.extend(updates.iter().map(|(_, _, n)| n.clone()));
                docs.extend(inserted_docs.iter().cloned());
                docs
            };
            // Child side: every FK value in a new/inserted image must exist
            // in the final state. For self-references the candidate set is
            // EXACTLY the final images — `check_fks_in`'s same_batch is only
            // an ADDITIONAL parent source, so the pre-state heap would still
            // satisfy values this very statement removes.
            for (col, rtable, rcol) in &meta.foreign_keys {
                for doc in updates
                    .iter()
                    .map(|(_, _, n)| n)
                    .chain(inserted_docs.iter())
                {
                    self.stmt_deadline.check()?;
                    let Some(v) = doc.get(col) else { continue };
                    if matches!(v, Value::Null) {
                        continue; // NULL passes (MATCH SIMPLE semantics)
                    }
                    let matches_parent = |rd: &Object| {
                        rd.get(rcol)
                            .map(|rv| Value::cmp_values(rv, v) == Ordering::Equal)
                            .unwrap_or(false)
                    };
                    let hit = if rtable == &tname {
                        final_docs.iter().any(matches_parent)
                    } else {
                        match self.table_docs_cx(rtable) {
                            Ok(d) => d.iter().any(matches_parent),
                            Err(e) => {
                                self.pager.abort_tx(tx)?;
                                return Err(e);
                            }
                        }
                    };
                    if !hit {
                        self.pager.abort_tx(tx)?;
                        return err(format!(
                            "FOREIGN KEY constraint failed: {tname}.{col} references \
                             {rtable}.{rcol}"
                        ));
                    }
                }
            }
            // Parent side: removed values must not stay referenced — the
            // self-reference child scan runs over the final images.
            let removed: Vec<Object> = updates.iter().map(|(_, o, _)| o.clone()).collect();
            if !removed.is_empty() {
                if let Err(e) = self.check_fk_parent_delete_skipping(
                    &tname,
                    &removed,
                    &final_docs,
                    &[],
                    Some(&final_docs),
                ) {
                    self.pager.abort_tx(tx)?;
                    return Err(e);
                }
            }
        }
        // Emptied heap pages are released inside this transaction so later
        // statements reuse them instead of growing the file.
        for p in std::mem::take(&mut heap.dropped) {
            self.pager.free_page(&mut tx, p)?;
        }
        let dotted_now = self.note_dotted_fields(
            &tname,
            inserted_docs
                .iter()
                .chain(updates.iter().map(|(_, _, new)| new)),
        );
        if dotted_now
            || heap.pages != meta.pages
            || roots != meta.index_roots
            || heap.overflow_free != meta.overflow_free
        {
            self.sync_table_layout(
                &mut tx,
                &tname,
                heap.pages.clone(),
                roots,
                heap.overflow_free.clone(),
            )?;
        }
        self.commit_pager_tx(tx)?;
        if let Some(id) = merge_last_id {
            let cur = self.last_insert_id.unwrap_or(i64::MIN);
            self.last_insert_id = Some(cur.max(id));
        }
        if autoinc_mutated {
            // Same recovery rule as the plain UPDATE path: an id this
            // statement set explicitly (or reassigned) is invisible to
            // `merge_next_autoinc`, so only a recompute stays correct.
            self.autoinc_cache.remove(&tname);
        } else if merge_last_id.is_some() {
            self.autoinc_cache.insert(tname.clone(), merge_next_autoinc);
        }
        Ok(ExecOutcome::Affected((updates.len() + inserted) as u64))
    }

    /// Merge-namespaced evaluation row: target columns (unqualified) plus
    /// source columns (qualified `skey.col`, and unqualified when the name
    /// is not taken by the target). Qualified target refs resolve to the
    /// target's own columns only — a column the target row lacks pins to
    /// NULL instead of falling back to the source's bare-name value.
    fn merge_join_row(t_doc: &Object, t_key: &str, s_doc: &Object, s_key: &str) -> Object {
        let mut row = t_doc.clone();
        for (k, v) in s_doc {
            row.insert(format!("{s_key}.{k}"), v.clone());
            if !row.contains_key(k.as_str()) {
                row.insert(k.clone(), v.clone());
            }
        }
        for k in t_doc.keys() {
            row.insert(format!("{t_key}.{k}"), t_doc[k].clone());
        }
        for k in s_doc.keys() {
            row.entry(format!("{t_key}.{k}")).or_insert(Value::Null);
        }
        row
    }
}

/// Borrow-guarded fused write unit ([`Database::write_unit`]). Statements
/// run through the guard (it derefs to [`Database`]); [`WriteUnit::end`]
/// makes the whole unit durable with one WAL fsync.
pub struct WriteUnit<'a> {
    db: &'a mut Database,
}

impl std::ops::Deref for WriteUnit<'_> {
    type Target = Database;
    fn deref(&self) -> &Database {
        self.db
    }
}

impl std::ops::DerefMut for WriteUnit<'_> {
    fn deref_mut(&mut self) -> &mut Database {
        self.db
    }
}

impl WriteUnit<'_> {
    /// Close the unit and make its statements durable with one WAL fsync.
    /// No-op when nothing deferred a commit. Async-commit mode never fsyncs
    /// here: durability belongs to the background flusher's batching, and a
    /// per-unit sync would defeat it — the unit then only groups the
    /// statements' commits (the same deferred path they take anyway).
    pub fn end(self) -> Result<()> {
        let result = {
            self.db.write_unit = self.db.write_unit.saturating_sub(1);
            if self.db.async_commit || !self.db.pending_sync {
                Ok(())
            } else {
                self.db
                    .pager
                    .sync_wal()
                    .map_err(SqlError::from)
                    .map(|_| self.db.pending_sync = false)
            }
        };
        // The depth was already decremented above; skip Drop's.
        std::mem::forget(self);
        result
    }
}

impl Drop for WriteUnit<'_> {
    fn drop(&mut self) {
        self.db.write_unit = self.db.write_unit.saturating_sub(1);
    }
}

#[derive(Clone)]
enum AggOp {
    Count,
    Sum,
    Avg,
    Min,
    Max,
    GroupConcat,
}

// Short-lived, built per statement; size difference is fine here.
#[allow(clippy::large_enum_variant)]
enum AggSpec {
    GroupKey {
        idx: usize,
    },
    /// `GROUPING(expr)`: 1 when the current grouping set omits `expr`, else
    /// 0 (SQL:2016). `idx` indexes the union of all set expressions.
    Grouping {
        idx: usize,
    },
    Agg {
        op: AggOp,
        arg: SqlExpr,
        distinct: bool,
        sep: Option<String>,
        /// Aggregate FILTER (WHERE …): rows that do not evaluate true are
        /// excluded before DISTINCT and aggregation.
        filter: Option<SqlExpr>,
    },
    /// Aggregate arithmetic in the projection (`SUM(x) + 1`, `-COUNT(*)`,
    /// `COALESCE(SUM(x), 0)`): the whole expression evaluates over the
    /// group with aggregate subcalls resolved.
    Composite {
        expr: SqlExpr,
    },
}

/// Parse a scalar-aggregate call (`COUNT(*)`, `SUM(DISTINCT x)`, ...) into
/// its operator, argument, DISTINCT flag and — for GROUP_CONCAT/STRING_AGG —
/// the optional constant separator. `COUNT(*)` rewrites to a sentinel column
/// so the executor counts rows instead of non-null values. The window
/// aggregate path (`SUM(x) OVER (...)`) passes `for_window` to reuse the
/// same argument parsing over a frame slice.
#[allow(clippy::type_complexity)]
fn agg_parts(
    f: &sqlparser::ast::Function,
    for_window: bool,
) -> Result<(AggOp, SqlExpr, bool, Option<String>, Option<SqlExpr>)> {
    let fname = f.name.to_string().to_uppercase();
    // A window frame silently changes the result shape (one row per
    // partition); refusing is better than returning wrong numbers.
    if f.over.is_some() && !for_window {
        return err(format!(
            "window functions (OVER) are not supported: {fname}"
        ));
    }
    // ORDER BY inside the aggregate's own argument list (e.g.
    // STRING_AGG(x, ',' ORDER BY y)) is only meaningful for order-sensitive
    // aggregates; dropping it silently would concatenate in scan order.
    // WITHIN GROUP is the same request spelled as a clause.
    let arg_order = match &f.args {
        sqlparser::ast::FunctionArguments::List(list) => list.clauses.iter().any(|c| {
            matches!(
                c,
                sqlparser::ast::FunctionArgumentClause::OrderBy(_)
                    | sqlparser::ast::FunctionArgumentClause::Limit(_)
                    | sqlparser::ast::FunctionArgumentClause::OnOverflow(_)
            )
        }),
        _ => false,
    };
    if arg_order || !f.within_group.is_empty() {
        return err(format!(
            "ORDER BY inside aggregate arguments is not supported: {fname}"
        ));
    }
    let (distinct, inner, second) = match &f.args {
        sqlparser::ast::FunctionArguments::List(list) => {
            let distinct = matches!(
                list.duplicate_treatment,
                Some(sqlparser::ast::DuplicateTreatment::Distinct)
            );
            let as_expr = |a: &sqlparser::ast::FunctionArg| match a {
                sqlparser::ast::FunctionArg::Unnamed(sqlparser::ast::FunctionArgExpr::Expr(e)) => {
                    Some(e.clone())
                }
                _ => None,
            };
            let inner = list.args.first().and_then(|a| match a {
                sqlparser::ast::FunctionArg::Unnamed(sqlparser::ast::FunctionArgExpr::Wildcard) => {
                    Some(SqlExpr::Identifier(sqlparser::ast::Ident::new("__count__")))
                }
                other => as_expr(other),
            });
            let second = list.args.get(1).and_then(as_expr);
            (distinct, inner, second)
        }
        _ => (false, None, None),
    };
    let Some(arg) = inner else {
        return err(format!("unsupported aggregate arguments: {fname}"));
    };
    let op = match fname.as_str() {
        // COUNT_BIG is T-SQL's COUNT returning bigint; same semantics here.
        "COUNT" | "COUNT_BIG" => AggOp::Count,
        "SUM" => AggOp::Sum,
        "AVG" => AggOp::Avg,
        "MIN" => AggOp::Min,
        "MAX" => AggOp::Max,
        "GROUP_CONCAT" | "STRING_AGG" => AggOp::GroupConcat,
        other => return err(format!("unknown function: {other}")),
    };
    let sep = if matches!(op, AggOp::GroupConcat) {
        match second {
            Some(e) => match eval_const(&e)? {
                Value::Str(s) => Some(s),
                Value::Null => None,
                other => {
                    return err(format!(
                        "group_concat separator must be a string literal, got {}",
                        other.type_name()
                    ))
                }
            },
            None => None,
        }
    } else {
        None
    };
    // FILTER (WHERE …) is an aggregate-row filter, applied before DISTINCT
    // and the aggregate itself (SQL:2003).
    let filter = f.filter.as_deref().cloned();
    Ok((op, arg, distinct, sep, filter))
}

/// Root key of the unique constraint an `ON CONFLICT (cols)` target names:
/// a single-column spelling resolves through the constraint containers, a
/// multi-column one must match a UNIQUE index (column sets compare
/// order-insensitively, as in PostgreSQL).
fn resolve_conflict_columns(meta: &TableMeta, cols: &[String]) -> Result<String> {
    if cols.len() == 1 {
        let col = &cols[0];
        let constraint =
            meta.primary_key.as_deref() == Some(col.as_str()) || meta.unique.contains(col);
        if constraint && meta.index_roots.contains_key(col) {
            return Ok(col.clone());
        }
    }
    // Partial unique indexes are not targetable: their conflicts are
    // predicate-scoped and the untargeted policies handle them; a targeted
    // scope would need per-row predicate evaluation against the target.
    if let Some(def) = meta.index_defs.iter().find(|d| {
        d.pred.is_none()
            && d.unique
            && d.columns.len() == cols.len()
            && cols.iter().all(|c| d.columns.contains(c))
    }) {
        return Ok(if def.columns.len() == 1 {
            def.columns[0].clone()
        } else {
            def.name.clone()
        });
    }
    err(format!(
        "there is no unique constraint matching the ON CONFLICT target ({})",
        cols.join(", ")
    ))
}

/// Root key of the unique index `ON CONFLICT ON CONSTRAINT name` names.
fn resolve_conflict_constraint(meta: &TableMeta, table: &str, name: &str) -> Result<String> {
    // PK / table-declared UNIQUE constraints surface as derived
    // `sqlite_autoindex_<table>_<n>` names (PK first) — resolvable here
    // even though they are never persisted in the catalog.
    let prefix = format!("sqlite_autoindex_{table}_");
    if let Some(n) = name.strip_prefix(&prefix) {
        if let Some(i) = n.parse::<usize>().ok().filter(|i| *i >= 1) {
            let mut cols: Vec<&String> = Vec::new();
            for c in meta.primary_key.iter().chain(meta.constraint_unique.iter()) {
                if !cols.contains(&c) {
                    cols.push(c);
                }
            }
            if let Some(c) = cols.get(i - 1) {
                return Ok((*c).clone());
            }
        }
        return err(format!("constraint {name} does not exist"));
    }
    let Some(def) = meta.index_defs.iter().find(|d| d.name == name) else {
        return err(format!("constraint {name} does not exist"));
    };
    if !def.unique {
        return err(format!("constraint {name} is not unique"));
    }
    Ok(if def.columns.len() == 1 {
        def.columns[0].clone()
    } else {
        def.name.clone()
    })
}

fn add_values(a: Value, b: Value) -> Result<Value> {
    // NULL is sticky: an overflowed partial (see the Int/Int arm below) must
    // keep the whole SUM NULL instead of erroring "non-numeric" on the next
    // addition — the result used to depend on where the overflow landed.
    if matches!(a, Value::Null) || matches!(b, Value::Null) {
        return Ok(Value::Null);
    }
    // Decimal poisons the sum toward exactness: Int/Float operands convert
    // losslessly (a Float contributes its exact binary value).
    if matches!(a, Value::Decimal(_)) || matches!(b, Value::Decimal(_)) {
        let (x, y) = (as_decimal(&a)?, as_decimal(&b)?);
        return Ok(x.checked_add(y).map(Value::Decimal).unwrap_or(Value::Null));
    }
    match (a, b) {
        // Overflow yields NULL, matching the scalar `+` path (a wrapped
        // negative SUM would silently book a huge total as a loss).
        (Value::Int(x), Value::Int(y)) => {
            Ok(x.checked_add(y).map(Value::Int).unwrap_or(Value::Null))
        }
        (Value::Int(x), Value::Float(y)) => Ok(Value::Float(x as f64 + y)),
        (Value::Float(x), Value::Int(y)) => Ok(Value::Float(x + y as f64)),
        (Value::Float(x), Value::Float(y)) => Ok(Value::Float(x + y)),
        _ => err("SUM of non-numeric values"),
    }
}

fn row_key(row: &[Value]) -> Vec<u8> {
    encode::encode_to_vec(&Value::Array(row.to_vec())).unwrap_or_default()
}

/// Keep the first occurrence of each distinct row.
fn dedup_rows(rows: &mut Vec<Vec<Value>>) {
    let mut seen = std::collections::BTreeSet::new();
    rows.retain(|row| seen.insert(row_key(row)));
}

/// Multiset of rows for ALL-quantified set operations.
fn row_counts(rows: &[Vec<Value>]) -> std::collections::BTreeMap<Vec<u8>, usize> {
    let mut counts = std::collections::BTreeMap::new();
    for row in rows {
        *counts.entry(row_key(row)).or_insert(0) += 1;
    }
    counts
}

/// If `row` has a remaining occurrence in `counts`, consume one and return
/// true; otherwise return false.
fn consume_one(counts: &mut std::collections::BTreeMap<Vec<u8>, usize>, row: &[Value]) -> bool {
    match counts.get_mut(&row_key(row)) {
        Some(n) if *n > 0 => {
            *n -= 1;
            true
        }
        _ => false,
    }
}

fn eval_agg(
    spec: &AggSpec,
    docs: &[&Object],
    key: &[Value],
    group_exprs: &[SqlExpr],
) -> Result<Value> {
    match spec {
        AggSpec::GroupKey { idx } => Ok(key.get(*idx).cloned().unwrap_or(Value::Null)),
        // Resolved per grouping set by `eval_grouped_spec` before reaching
        // the aggregate evaluator.
        AggSpec::Grouping { .. } => err("GROUPING is only supported in the SELECT list"),
        AggSpec::Composite { expr } => {
            let empty = Object::new();
            eval_group_expr(expr, &empty, docs, group_exprs)
        }
        AggSpec::Agg {
            op,
            arg,
            distinct,
            sep,
            filter,
        } => {
            // FILTER applies first: only rows whose predicate is TRUE take
            // part in DISTINCT and the aggregate.
            let kept: Vec<&Object> = match filter {
                Some(f) => {
                    let mut kept = Vec::with_capacity(docs.len());
                    for d in docs {
                        if matches!(eval_expr(f, d)?, Value::Bool(true)) {
                            kept.push(*d);
                        }
                    }
                    kept
                }
                None => docs.to_vec(),
            };
            let mut vals: Vec<Value> = Vec::new();
            for d in &kept {
                let v = eval_expr(arg, d)?;
                if !matches!(v, Value::Null) {
                    vals.push(v);
                }
            }
            // DISTINCT aggregates dedup before combining.
            if *distinct {
                let mut seen = std::collections::BTreeSet::new();
                vals.retain(|v| seen.insert(encode::encode_to_vec(v).unwrap_or_default()));
            }
            Ok(match op {
                AggOp::Count => {
                    // COUNT(*) is rewritten to a sentinel column that never
                    // exists, so count rows instead of non-null values.
                    if matches!(arg, SqlExpr::Identifier(i) if i.value == "__count__") {
                        Value::Int(kept.len() as i64)
                    } else {
                        Value::Int(vals.len() as i64)
                    }
                }
                AggOp::Sum => {
                    if vals.is_empty() {
                        Value::Null
                    } else {
                        // Fold from a numeric zero so a lone value goes
                        // through add_values' type check too: SUM over a
                        // single BLOB/text used to return the value itself
                        // and only erroed once a second row arrived.
                        let mut sum = Value::Int(0);
                        for v in vals {
                            sum = add_values(sum, v)?;
                        }
                        sum
                    }
                }
                AggOp::Avg => {
                    if vals.is_empty() {
                        Value::Null
                    } else if vals.iter().any(|v| matches!(v, Value::Decimal(_))) {
                        // Exact averaging when any input is decimal: sum first
                        // (exact), then divide once.
                        let mut acc = Decimal::ZERO;
                        for v in &vals {
                            acc = acc
                                .checked_add(as_decimal(v)?)
                                .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                        }
                        match acc.checked_div(Decimal::from(vals.len() as i64)) {
                            Some(d) => Value::Decimal(d),
                            None => Value::Null,
                        }
                    } else {
                        let n = vals.len() as f64;
                        let mut acc = 0.0f64;
                        for v in &vals {
                            acc += match v {
                                Value::Int(i) => *i as f64,
                                Value::Float(f) => *f,
                                _ => return err("AVG of non-numeric"),
                            };
                        }
                        Value::Float(acc / n)
                    }
                }
                AggOp::Min => vals
                    .into_iter()
                    .reduce(|a, b| {
                        if Value::cmp_values(&a, &b) != std::cmp::Ordering::Greater {
                            a
                        } else {
                            b
                        }
                    })
                    .unwrap_or(Value::Null),
                AggOp::Max => vals
                    .into_iter()
                    .reduce(|a, b| {
                        if Value::cmp_values(&a, &b) != std::cmp::Ordering::Less {
                            a
                        } else {
                            b
                        }
                    })
                    .unwrap_or(Value::Null),
                AggOp::GroupConcat => {
                    // Zero contributing rows (or all-NULL input) is NULL, not
                    // the empty string — IS NULL checks depend on it.
                    if vals.is_empty() {
                        Value::Null
                    } else {
                        Value::Str(
                            vals.iter()
                                .map(value_to_text)
                                .collect::<Vec<_>>()
                                .join(sep.as_deref().unwrap_or(",")),
                        )
                    }
                }
            })
        }
    }
}

/// Expand GROUP BY into grouping sets. Plain expressions belong to every
/// set; `ROLLUP(a, b)` contributes `(a,b), (a), ()`; `CUBE(a, b)` all
/// subsets; `GROUPING SETS` its explicit list. Several super-grouping items
/// combine as a cartesian product (SQL:2016).
fn expand_grouping_sets(exprs: &[SqlExpr]) -> Result<Vec<Vec<SqlExpr>>> {
    let mut sets: Vec<Vec<SqlExpr>> = vec![Vec::new()];
    for e in exprs {
        let alternatives: Vec<Vec<SqlExpr>> = match e {
            SqlExpr::Rollup(groups) => (0..=groups.len())
                .rev()
                .map(|n| groups[..n].iter().flatten().cloned().collect())
                .collect(),
            SqlExpr::Cube(groups) => {
                if groups.len() > 12 {
                    return err("CUBE supports at most 12 elements");
                }
                (0..(1u32 << groups.len()))
                    .map(|mask| {
                        groups
                            .iter()
                            .enumerate()
                            .filter(|(i, _)| mask & (1 << i) != 0)
                            .flat_map(|(_, g)| g.iter().cloned())
                            .collect()
                    })
                    .collect()
            }
            SqlExpr::GroupingSets(lists) => lists.clone(),
            other => vec![vec![other.clone()]],
        };
        // Super-grouping items multiply (SQL:2016 cartesian semantics);
        // cap the product so `CUBE(a1..a12), CUBE(b1..b12), …` cannot turn
        // into an astronomic allocation before the error surfaces.
        let product = match sets.len().checked_mul(alternatives.len()) {
            Some(p) => p,
            None => return err("GROUP BY expands past the supported grouping set limit"),
        };
        if product > MAX_GROUPING_SETS {
            return err(format!(
                "GROUP BY expands to more than {MAX_GROUPING_SETS} grouping sets"
            ));
        }
        let mut next = Vec::with_capacity(product);
        for base in &sets {
            for alt in &alternatives {
                let mut combined = base.clone();
                combined.extend(alt.iter().cloned());
                next.push(combined);
            }
        }
        sets = next;
    }
    let mut seen = std::collections::BTreeSet::new();
    for set in &sets {
        for e in set {
            if matches!(
                e,
                SqlExpr::Rollup(_) | SqlExpr::Cube(_) | SqlExpr::GroupingSets(_)
            ) {
                return err("nested grouping sets are not supported");
            }
            // Inside GROUPING SETS the parser turns ROLLUP/CUBE/GROUPING
            // into function calls; they are still nested super-grouping.
            if let SqlExpr::Function(f) = e {
                let name = f.name.to_string().to_uppercase();
                if name == "ROLLUP" || name == "CUBE" || name == "GROUPING" {
                    return err("nested grouping sets are not supported");
                }
            }
        }
        // Duplicate sets would emit duplicate rows; the standard forbids them.
        let key: Vec<String> = set.iter().map(|e| e.to_string()).collect();
        if !seen.insert(key) {
            return err("duplicate grouping set");
        }
    }
    Ok(sets)
}

/// Position of `all_exprs[idx]` inside one grouping set, by expression text
/// (the same identity `agg_spec` resolves group keys with).
fn set_position(all_exprs: &[SqlExpr], set: &[SqlExpr], idx: usize) -> Option<usize> {
    let target = &all_exprs[idx];
    set.iter()
        .position(|s| format!("{s}") == format!("{target}"))
}

/// Evaluate one projection spec for a group of one grouping set: keys that
/// this set omits read as NULL, GROUPING() reports the omission, and the
/// aggregates run over the group's rows.
fn eval_grouped_spec(
    spec: &AggSpec,
    all_exprs: &[SqlExpr],
    set: &[SqlExpr],
    key: &[Value],
    docs: &[&Object],
) -> Result<Value> {
    match spec {
        AggSpec::GroupKey { idx } => Ok(set_position(all_exprs, set, *idx)
            .and_then(|p| key.get(p).cloned())
            .unwrap_or(Value::Null)),
        AggSpec::Grouping { idx } => Ok(Value::Int(
            if set_position(all_exprs, set, *idx).is_some() {
                0
            } else {
                1
            },
        )),
        AggSpec::Agg { .. } => eval_agg(spec, docs, key, set),
        AggSpec::Composite { expr } => {
            let empty = Object::new();
            eval_group_expr(expr, &empty, docs, set)
        }
    }
}

/// Prefix every field with the source alias: "col" -> "alias.col".
/// True when the query's FROM factors mention `name` (recursive CTE
/// detection; T-SQL omits the RECURSIVE keyword, so shape + self-reference
/// is the signal). Rendered-text scan over the query AST is enough here —
/// a false positive merely routes a non-recursive CTE through the
/// recursive path, whose anchor evaluation then fails loudly naming it.
/// Does this CTE body reference `name` in a TABLE position (FROM/JOIN,
/// derived tables, subqueries)? Only those positions make the CTE
/// self-referential (recursion); the old whole-text word scan also hit the
/// CTE's own column names and output aliases — `WITH region AS (SELECT
/// region FROM … UNION ALL …)` is NOT recursive, but was misdiagnosed:
/// either rejected as "must be anchor UNION arm", or its non-recursive
/// UNION ALL body was iterated as recursion until the convergence caps
/// tripped on a perfectly legal query.
fn cte_references(q: &sqlparser::ast::Query, name: &str) -> bool {
    let mut refs = Vec::new();
    // `objects` = always-true keeps every WITH name out of the shadow set,
    // so factor names inside nested WITH bodies are still collected —
    // over-detecting costs a loud materialization error at worst, while
    // under-detecting silently reads a same-named base table instead.
    let _ = walk_query(q, &mut refs, &|_: &str| true);
    refs.iter().any(|r| r.eq_ignore_ascii_case(name))
}

/// PIVOT core: group docs by every field except the pivot column and the
/// aggregate argument's column, then emit `group keys + one column per
/// IN-value` holding the aggregate over the matching rows.
fn pivot_factor(
    docs: Vec<Object>,
    aggs: &[sqlparser::ast::ExprWithAlias],
    value_column: &[SqlExpr],
    value_source: &sqlparser::ast::PivotValueSource,
) -> Result<Vec<Object>> {
    let agg = &aggs[0];
    // The aggregate must be a plain single-argument function call
    // (`SUM(qty)`); its argument names the aggregated field.
    let sqlparser::ast::Expr::Function(f) = &agg.expr else {
        return err("PIVOT aggregate must be a function call like SUM(qty)");
    };
    let agg_name = f.name.to_string().to_uppercase();
    let arg_expr = match &f.args {
        sqlparser::ast::FunctionArguments::List(list) if list.args.len() == 1 => {
            match &list.args[0] {
                sqlparser::ast::FunctionArg::Unnamed(sqlparser::ast::FunctionArgExpr::Expr(e)) => {
                    e.clone()
                }
                _ => return err("PIVOT aggregate must take one expression argument"),
            }
        }
        _ => return err("PIVOT aggregate must take one expression argument"),
    };
    // The pivot column: one bare identifier (`FOR yr IN …`).
    let pivot_col = match value_column {
        [SqlExpr::Identifier(i)] => i.value.clone(),
        _ => return err("PIVOT supports a single FOR column"),
    };
    // IN-list of literals (the output column names).
    let sqlparser::ast::PivotValueSource::List(values) = value_source else {
        return err("PIVOT IN (<subquery>) is not supported (list the values)");
    };
    let mut pivot_vals: Vec<(String, Value)> = Vec::new();
    for v in values {
        let expr = match v {
            sqlparser::ast::ExprWithAlias { expr, alias: None } => expr.clone(),
            sqlparser::ast::ExprWithAlias {
                expr,
                alias: Some(a),
            } => {
                // `[2024] AS q1`: the alias names the output column.
                let val = eval_const(expr)?;
                pivot_vals.push((a.value.clone(), val));
                continue;
            }
        };
        let val = eval_const(&expr)?;
        pivot_vals.push((value_to_text(&val), val));
    }
    // Output column names must be unique AND must not collide with a group
    // key field: `row.insert` writes straight into the group-key row, so a
    // collision silently replaced the grouping value (or an earlier pivot
    // cell) instead of erroring like every other duplicate-column shape.
    {
        let mut seen = std::collections::BTreeSet::new();
        for (name, _) in &pivot_vals {
            if !seen.insert(name.clone()) {
                return err(format!(
                    "PIVOT IN list produces duplicate output column '{name}'"
                ));
            }
        }
    }
    // Which fields does the aggregate argument read? Group by every other
    // field (T-SQL's implicit grouping). Single bare column only.
    let agg_col = match &arg_expr {
        SqlExpr::Identifier(i) => i.value.clone(),
        _ => return err("PIVOT aggregate argument must be a bare column"),
    };
    // First-seen group order. Members are bucketed by the group key at
    // partition time — the buckets ARE the grouping. Matching rows back
    // with a field predicate instead would be asymmetric (it would only
    // constrain the doc's fields against the key, not the key's fields
    // against the doc), so schemaless rows with differing field sets could
    // land in several groups at once and their aggregates would double-count.
    let mut groups: Vec<(Object, Vec<usize>)> = Vec::new();
    let mut index: std::collections::BTreeMap<String, usize> = Default::default();
    for (di, d) in docs.iter().enumerate() {
        let mut key = Object::new();
        for (k, v) in d {
            if suffix_eq(k, &pivot_col) || suffix_eq(k, &agg_col) {
                continue;
            }
            key.insert(k.clone(), v.clone());
        }
        let key_text = value_to_text(&Value::Object(key.clone()));
        match index.get(&key_text) {
            Some(&i) => groups[i].1.push(di),
            None => {
                index.insert(key_text, groups.len());
                groups.push((key, vec![di]));
            }
        }
    }
    // A pivot cell writes into the group-key row; a name that collides with
    // a grouping field would silently replace that field's value.
    for (name, _) in &pivot_vals {
        if groups
            .iter()
            .any(|(key, _)| key.keys().any(|k| suffix_eq(k, name)))
        {
            return err(format!(
                "PIVOT output column '{name}' collides with a grouping column; alias it"
            ));
        }
    }
    // Reduce per group × pivot value.
    let mut out = Vec::with_capacity(groups.len());
    for (key, member_idx) in &groups {
        let members: Vec<&Object> = member_idx.iter().map(|&i| &docs[i]).collect();
        let mut row = key.clone();
        for (name, want) in &pivot_vals {
            let matched: Vec<Value> = members
                .iter()
                .filter(|d| {
                    d.iter().any(|(k, v)| {
                        suffix_eq(k, &pivot_col) && Value::cmp_values(v, want) == Ordering::Equal
                    })
                })
                .map(|d| eval_expr(&arg_expr, d).unwrap_or(Value::Null))
                .collect();
            let cell = reduce_aggregate(&agg_name, &matched)?;
            row.insert(name.clone(), cell);
        }
        out.push(row);
    }
    Ok(out)
}

/// True when `key` equals `col` or ends with `.col` (schemaless suffix
/// rule, same as column lookup).
fn suffix_eq(key: &str, col: &str) -> bool {
    key == col || key.ends_with(&format!(".{col}"))
}

/// SUM/AVG/MIN/MAX/COUNT over evaluated values (PIVOT's local reducer).
/// Empty input (no rows matched the pivot value, or every matched value is
/// NULL) follows SQL aggregate semantics: COUNT → 0, everything else → NULL.
fn reduce_aggregate(name: &str, vals: &[Value]) -> Result<Value> {
    let non_null: Vec<&Value> = vals.iter().filter(|v| !matches!(v, Value::Null)).collect();
    match name {
        "COUNT" | "COUNT_BIG" => Ok(Value::Int(non_null.len() as i64)),
        "MIN" => Ok(non_null
            .iter()
            .min_by(|a, b| Value::cmp_values(a, b))
            .map(|v| (*v).clone())
            .unwrap_or(Value::Null)),
        "MAX" => Ok(non_null
            .iter()
            .max_by(|a, b| Value::cmp_values(a, b))
            .map(|v| (*v).clone())
            .unwrap_or(Value::Null)),
        "SUM" | "AVG" => {
            if non_null.is_empty() {
                return Ok(Value::Null);
            }
            if name == "AVG" {
                // Mirror eval_agg's AVG (float, or exact when decimal input):
                // `arith`'s Int/Int Divide truncates, so PIVOT(AVG) used to
                // disagree with a plain AVG over the same rows.
                if non_null.iter().any(|v| matches!(v, Value::Decimal(_))) {
                    let mut acc = Decimal::ZERO;
                    for v in &non_null {
                        acc = acc
                            .checked_add(as_decimal(v)?)
                            .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                    }
                    return Ok(acc
                        .checked_div(Decimal::from(non_null.len() as i64))
                        .map(Value::Decimal)
                        .unwrap_or(Value::Null));
                }
                let n = non_null.len() as f64;
                let mut acc = 0.0f64;
                for v in &non_null {
                    acc += match v {
                        Value::Int(i) => *i as f64,
                        Value::Float(f) => *f,
                        _ => return err("AVG of non-numeric"),
                    };
                }
                return Ok(Value::Float(acc / n));
            }
            let mut acc = Value::Int(0);
            for v in &non_null {
                acc = arith(acc, &BinaryOperator::Plus, (*v).clone())?;
            }
            Ok(acc)
        }
        other => err(format!(
            "PIVOT aggregate {other} is not supported (SUM/AVG/MIN/MAX/COUNT)"
        )),
    }
}

/// UNPIVOT core: for each row, one output row per listed column with the
/// remaining fields plus {name_col: column, value_col: value}; NULL cells
/// are dropped (T-SQL default).
fn unpivot_factor(
    docs: Vec<Object>,
    value: &SqlExpr,
    name: &sqlparser::ast::Ident,
    columns: &[sqlparser::ast::ExprWithAlias],
) -> Result<Vec<Object>> {
    let value_col = match value {
        SqlExpr::Identifier(i) => i.value.clone(),
        _ => return err("UNPIVOT value must be a bare column name"),
    };
    let name_col = name.value.clone();
    let mut wanted: Vec<(String, String)> = Vec::new();
    for c in columns {
        let src = match &c.expr {
            SqlExpr::Identifier(i) => i.value.clone(),
            _ => return err("UNPIVOT IN-list must be bare column names"),
        };
        let out_name = c
            .alias
            .as_ref()
            .map(|a| a.value.clone())
            .unwrap_or_else(|| src.clone());
        wanted.push((src, out_name));
    }
    let mut out = Vec::new();
    for d in &docs {
        for (src, label) in &wanted {
            let v = d
                .iter()
                .find(|(k, _)| suffix_eq(k, src))
                .map(|(_, v)| v.clone())
                .unwrap_or(Value::Null);
            if matches!(v, Value::Null) {
                continue;
            }
            let mut row = Object::new();
            for (k, val) in d {
                if wanted.iter().any(|(s, _)| suffix_eq(k, s)) {
                    continue;
                }
                row.insert(k.clone(), val.clone());
            }
            row.insert(name_col.clone(), Value::Str(label.clone()));
            row.insert(value_col.clone(), v);
            out.push(row);
        }
    }
    Ok(out)
}

fn qualify(doc: &Object, alias: &str) -> Object {
    doc.iter()
        .map(|(k, v)| (format!("{alias}.{k}"), v.clone()))
        .collect()
}

/// Canonical join key for the hash-join path. Equality under
/// [`Value::cmp_values`] implies equality here, which is the only contract
/// the index needs: candidates re-evaluate the full ON, so the key may
/// over-merge (Int vs Int beyond f64's 2^53 exact range collapses to the
/// same bits, mirroring `cmp_values`' cross-type numeric branch) but must
/// never split a matching pair. NULL is a key like any other — `binop`'s `=`
/// is `cmp_values`-based, so NULL = NULL joins.
#[derive(PartialEq, Eq, PartialOrd, Ord, Hash, Clone, Debug)]
enum JoinKey {
    Null,
    Bool(bool),
    /// f64 bit pattern, NaN collapsed to one payload and ±0.0 to +0.0 so
    /// `cmp_values`-equal numerics hash equal.
    Num(u64),
    Str(String),
    Bytes(Vec<u8>),
    Array(Vec<JoinKey>),
}

fn join_key_of(v: &Value) -> Option<JoinKey> {
    Some(match v {
        Value::Null => JoinKey::Null,
        Value::Bool(b) => JoinKey::Bool(*b),
        Value::Int(i) => JoinKey::Num(num_key(*i as f64)),
        Value::Float(f) => JoinKey::Num(num_key(*f)),
        // Decimal hashes through its nearest f64: over-merging only in the
        // ultra-wide-integer range, mirroring Int/Float (cmp_values then
        // terminates candidates exactly).
        Value::Decimal(d) => JoinKey::Num(num_key(d.to_f64()?)),
        Value::Timestamp(ms) => JoinKey::Num(num_key(*ms as f64)),
        Value::Str(s) => {
            // A parseable timestamp string joins against TIMESTAMP values —
            // binop coerces the pair before comparing — so both sides must
            // land in the same bucket or the hash path would drop a match
            // the nested loop finds. Keying parseable strings by their
            // instant only ever over-merges (string≠string pairs become
            // candidates the ON re-evaluation rejects); it never splits.
            match crate::value::parse_timestamp_ms(s) {
                Some(ms) => JoinKey::Num(num_key(ms as f64)),
                None => JoinKey::Str(s.clone()),
            }
        }
        Value::Bytes(b) => JoinKey::Bytes(b.clone()),
        Value::Array(items) => {
            let mut out = Vec::with_capacity(items.len());
            for it in items {
                out.push(join_key_of(it)?);
            }
            JoinKey::Array(out)
        }
        // Documents as join keys have no practical shape; the join falls
        // back to the nested loop instead.
        Value::Object(_) => return None,
    })
}

fn num_key(f: f64) -> u64 {
    if f.is_nan() {
        f64::NAN.to_bits()
    } else if f == 0.0 {
        0.0f64.to_bits()
    } else {
        f.to_bits()
    }
}

/// Flatten `e` into its AND-conjuncts (parenthesized groups unwrapped).
fn and_conjuncts<'e>(e: &'e SqlExpr, out: &mut Vec<&'e SqlExpr>) {
    match e {
        SqlExpr::BinaryOp {
            left,
            op: sqlparser::ast::BinaryOperator::And,
            right,
        } => {
            and_conjuncts(left, out);
            and_conjuncts(right, out);
        }
        SqlExpr::Nested(inner) => and_conjuncts(inner, out),
        other => out.push(other),
    }
}

/// Column references inside `e`, as the dotted names the row-local evaluator
/// resolves (`Identifier("a.id")` and `CompoundIdentifier[a, id]` both yield
/// `"a.id"`). `None` = the tree contains something the collector does not
/// model (subqueries, exotic nodes) — the caller then leaves the conjunct in
/// the residual instead of indexing on it.
fn column_refs(e: &SqlExpr, out: &mut Vec<String>) -> Option<()> {
    use sqlparser::ast::{FunctionArg, FunctionArgExpr, FunctionArguments};
    match e {
        SqlExpr::Identifier(i) => out.push(i.value.clone()),
        SqlExpr::CompoundIdentifier(parts) => {
            out.push(
                parts
                    .iter()
                    .map(|p| p.value.clone())
                    .collect::<Vec<_>>()
                    .join("."),
            );
        }
        SqlExpr::Value(_) => {}
        SqlExpr::UnaryOp { expr, .. } => column_refs(expr, out)?,
        SqlExpr::BinaryOp { left, right, .. } => {
            column_refs(left, out)?;
            column_refs(right, out)?;
        }
        SqlExpr::Nested(inner) => column_refs(inner, out)?,
        SqlExpr::IsNull(inner) | SqlExpr::IsNotNull(inner) => column_refs(inner, out)?,
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            column_refs(expr, out)?;
            column_refs(low, out)?;
            column_refs(high, out)?;
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            column_refs(expr, out)?;
            column_refs(pattern, out)?;
        }
        SqlExpr::InList { expr, list, .. } => {
            column_refs(expr, out)?;
            for item in list {
                column_refs(item, out)?;
            }
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                column_refs(o, out)?;
            }
            for w in conditions {
                column_refs(&w.condition, out)?;
                column_refs(&w.result, out)?;
            }
            if let Some(r) = else_result {
                column_refs(r, out)?;
            }
        }
        SqlExpr::Cast { expr, .. } => column_refs(expr, out)?,
        SqlExpr::Substring {
            expr,
            substring_from,
            substring_for,
            ..
        } => {
            column_refs(expr, out)?;
            if let Some(f) = substring_from {
                column_refs(f, out)?;
            }
            if let Some(l) = substring_for {
                column_refs(l, out)?;
            }
        }
        SqlExpr::Function(f) => {
            match &f.args {
                FunctionArguments::List(list) => {
                    for a in &list.args {
                        match a {
                            FunctionArg::Unnamed(FunctionArgExpr::Expr(inner)) => {
                                column_refs(inner, out)?
                            }
                            // `COUNT(*)` and friends reference no column; named or
                            // wildcard argument shapes stay unmodeled.
                            FunctionArg::Unnamed(FunctionArgExpr::Wildcard) => {}
                            _ => return None,
                        }
                    }
                }
                FunctionArguments::None => {}
                _ => return None,
            }
            // Aggregate FILTER (WHERE …): the engine evaluates the predicate
            // per row (agg_parts/eval_agg), so its columns are read exactly
            // like a projection's — a column-restricted grant that skips
            // them leaks the filtered column's boolean information
            // (`COUNT(id) FILTER (WHERE secret = …)`). WITHIN GROUP's order
            // keys are unmodeled → fail closed like any unknown shape.
            if let Some(flt) = &f.filter {
                column_refs(flt, out)?;
            }
            if !f.within_group.is_empty() {
                return None;
            }
        }
        // Subqueries and anything unmodeled keep the conjunct in the residual.
        _ => return None,
    }
    Some(())
}

/// Which side of the join boundary an expression's column refs touch.
enum Side {
    Left,
    Right,
    /// Refs from both sides — never indexable, the conjunct stays residual.
    Both,
}

/// One indexed equi condition: `left = right`, with the left expression
/// evaluated against the left row and the right expression against the
/// qualified right row. The ref lists are the exact keys a row must contain
/// for that single-side evaluation to agree with merged-row evaluation:
/// `eval_expr` falls back to suffix matching when the exact key is missing,
/// which can bind `r.x` to `l.x` only on the merged row — so a missing key
/// degrades that row to "probe everything" instead of keying it.
struct EquiPair {
    left: Box<SqlExpr>,
    right: Box<SqlExpr>,
    left_refs: Vec<String>,
    right_refs: Vec<String>,
}

/// The equi-join plan for `on`: `left_expr = right_expr` pairs whose sides
/// cleanly split across the join boundary. Only qualified references
/// participate — unqualified names resolve through `lookup_col`'s suffix
/// fallback and can silently bind to either side, so they stay in the
/// residual. Same-side (`l.x = l.y`), mixed-side (`l.a = r.b + l.c`) and
/// unmodelable conjuncts stay in the residual too; the plan is `None` only
/// when nothing extractable remains.
fn equi_plan(right_key: &str, on: &SqlExpr) -> Option<Vec<EquiPair>> {
    let mut conjuncts = Vec::new();
    and_conjuncts(on, &mut conjuncts);
    let jprefix = format!("{right_key}.");
    let classify = |e: &SqlExpr| -> Option<(Vec<String>, Side)> {
        let mut refs = Vec::new();
        column_refs(e, &mut refs)?;
        let (mut saw_left, mut saw_right) = (false, false);
        for r in &refs {
            if r.starts_with(&jprefix) {
                saw_right = true;
            } else if r.contains('.') {
                saw_left = true;
            } else {
                // Unqualified refs are ambiguous under suffix resolution.
                return None;
            }
        }
        let side = match (saw_left, saw_right) {
            (true, false) => Side::Left,
            (false, true) => Side::Right,
            // Literal-only keys evaluate identically on either side; treat
            // them as left so `r.x = 5` pairs probe a constant.
            (false, false) => Side::Left,
            (true, true) => Side::Both,
        };
        Some((refs, side))
    };
    let mut plan = Vec::new();
    for c in conjuncts {
        let SqlExpr::BinaryOp {
            left,
            op: sqlparser::ast::BinaryOperator::Eq,
            right,
        } = c
        else {
            continue; // residual predicate: re-evaluated per candidate
        };
        let (l, r) = match (classify(left), classify(right)) {
            (Some(l), Some(r)) => (l, r),
            // Unmodelable conjunct stays in the residual; the remaining
            // conjuncts still form a plan.
            _ => continue,
        };
        let (le, le_refs, re, re_refs) = match (l.1, r.1) {
            (Side::Left, Side::Right) => (left, l.0, right, r.0),
            (Side::Right, Side::Left) => (right, r.0, left, l.0),
            // Same-side filters and side-mixing expressions.
            _ => continue,
        };
        // SqlExpr has no PartialEq; identical printed forms are duplicates.
        if plan.iter().any(|p: &EquiPair| {
            p.left.to_string() == le.to_string() && p.right.to_string() == re.to_string()
        }) {
            continue; // duplicate conjunct adds no key component
        }
        plan.push(EquiPair {
            left: le.clone(),
            right: re.clone(),
            left_refs: le_refs,
            right_refs: re_refs,
        });
    }
    if plan.is_empty() {
        None
    } else {
        Some(plan)
    }
}

/// Merged join row: `l` plus the right row's fields. `right` keys must
/// already be qualified (`r.k`).
fn merged_row(l: &Object, right: &Object) -> Object {
    let mut merged = l.clone();
    for (k, v) in right {
        merged.insert(k.clone(), v.clone());
    }
    merged
}

/// LEFT/INNER join's unmatched left row: the right side's columns padded
/// with NULL. The pad set is the union of every qualified right row's keys
/// (row schemas vary in a schemaless store — padding only the FIRST row's
/// keys left a column only later rows carry unpadded, and the suffix
/// fallback answered it with the left side's same-named value). An EMPTY
/// right side has no sample, so `right_cols` (the factor's planned columns)
/// pads the keys — without them a same-named left column answers the
/// suffix fallback and masquerades as the right value (`WHERE r.id IS
/// NULL` never fires).
fn null_extended_left(
    l: &Object,
    qright: &[Object],
    right_key: &str,
    right_cols: Option<&[String]>,
) -> Object {
    let mut merged = l.clone();
    if qright.is_empty() {
        if let Some(cols) = right_cols {
            for c in cols {
                merged.insert(format!("{right_key}.{c}"), Value::Null);
            }
        }
    } else {
        for row in qright {
            for k in row.keys() {
                merged.insert(k.clone(), Value::Null);
            }
        }
    }
    merged
}

/// RIGHT/FULL join's unmatched right row: the left side's columns padded
/// with NULL. `right` keys must already be qualified. `left_cols` is the
/// planned left key shape used when the left side produced no rows at all
/// (bare base columns plus the qualified keys of earlier joins).
fn null_extended_right(
    left_fields: &[String],
    right: &Object,
    left_cols: Option<&[String]>,
) -> Object {
    let mut merged = Object::new();
    if left_fields.is_empty() {
        // The left side produced no rows: its key shape cannot be read off
        // data, so pad the PLANNED columns instead (without them a
        // same-named right column answers the suffix fallback and leaks the
        // right value into a left-side reference).
        for k in left_cols.unwrap_or(&[]) {
            merged.insert(k.clone(), Value::Null);
        }
    }
    for k in left_fields {
        merged.insert(k.clone(), Value::Null);
    }
    for (k, v) in right {
        merged.insert(k.clone(), v.clone());
    }
    merged
}

/// Equi-join over a canonical-key index: right rows are bucketed by their
/// key, each left row probes its bucket, and every candidate still passes
/// the full ON on the merged row (the index is a superset filter, the ON is
/// the decider). Rows whose key expressions do not resolve to exact keys
/// (missing columns, which suffix fallback could rebind across the boundary
/// on the merged row) or produce unmodelable values (documents) degrade
/// only their own row to "probe everything" instead of falling back for the
/// whole join. Emission order matches the nested loop: left order, then
/// right order within a left row.
#[allow(clippy::too_many_arguments)]
fn hash_join(
    left: &[Object],
    qright: &[Object],
    on: &SqlExpr,
    plan: &[EquiPair],
    left_join: bool,
    right_join: bool,
    deadline: &StmtDeadline,
    right_key: &str,
    right_cols: Option<&[String]>,
    left_cols: Option<&[String]>,
) -> Result<Vec<Object>> {
    let mut map: std::collections::HashMap<Vec<JoinKey>, Vec<usize>> =
        std::collections::HashMap::new();
    let mut always: Vec<usize> = Vec::new();
    for (i, qr) in qright.iter().enumerate() {
        deadline.check()?;
        let mut key = Vec::with_capacity(plan.len());
        let mut indexed = true;
        for p in plan {
            if p.right_refs.iter().all(|r| qr.get(r).is_some()) {
                match join_key_of(&eval_expr(&p.right, qr)?) {
                    Some(k) => key.push(k),
                    None => indexed = false,
                }
            } else {
                indexed = false;
            }
            if !indexed {
                break;
            }
        }
        if indexed {
            map.entry(key).or_default().push(i);
        } else {
            always.push(i);
        }
    }
    let mut right_matched = vec![false; qright.len()];
    let mut out = Vec::new();
    for l in left {
        deadline.check()?;
        let mut lkey = Vec::with_capacity(plan.len());
        let mut unindexed = false;
        for p in plan {
            if p.left_refs.iter().all(|r| l.get(r).is_some()) {
                match join_key_of(&eval_expr(&p.left, l)?) {
                    Some(k) => lkey.push(k),
                    None => unindexed = true,
                }
            } else {
                unindexed = true;
            }
            if unindexed {
                break;
            }
        }
        let mut cands: Vec<usize> = Vec::new();
        if unindexed {
            cands.extend(0..qright.len());
        } else {
            // The bucket and `always` are each ascending (built in right-row
            // order) and disjoint, so a linear merge restores overall right
            // order in O(k) instead of sorting per left row.
            let empty: &[usize] = &[];
            let bucket = map.get(&lkey).map(Vec::as_slice).unwrap_or(empty);
            cands.reserve(bucket.len() + always.len());
            let (mut bi, mut ai) = (0usize, 0usize);
            while bi < bucket.len() || ai < always.len() {
                let take_bucket =
                    ai >= always.len() || (bi < bucket.len() && bucket[bi] < always[ai]);
                if take_bucket {
                    cands.push(bucket[bi]);
                    bi += 1;
                } else {
                    cands.push(always[ai]);
                    ai += 1;
                }
            }
        }
        let mut matched = false;
        for &ri in &cands {
            deadline.check()?;
            let merged = merged_row(l, &qright[ri]);
            if matches!(eval_expr(on, &merged)?, Value::Bool(true)) {
                matched = true;
                right_matched[ri] = true;
                out.push(merged);
            }
        }
        if !matched && left_join {
            out.push(null_extended_left(l, qright, right_key, right_cols));
        }
    }
    if right_join {
        let left_fields = union_of_fields(left);
        for (ri, r) in qright.iter().enumerate() {
            if !right_matched[ri] {
                out.push(null_extended_right(&left_fields, r, left_cols));
            }
        }
    }
    Ok(out)
}

/// Nested-loop join and hash-join dispatcher. ON is evaluated over the
/// merged (qualified) row; LEFT/RIGHT joins null-extend the unmatched side.
/// `right_cols`/`left_cols` are the factors' planned (bare / row-shape)
/// column lists, used to pad NULL keys when a side is EMPTY (no row to
/// sample the key shape from).
#[allow(clippy::too_many_arguments)]
fn join_rows(
    left: Vec<Object>,
    right: &[Object],
    right_key: &str,
    on: Option<&SqlExpr>,
    left_join: bool,
    right_join: bool,
    deadline: &StmtDeadline,
    right_cols: Option<&[String]>,
    left_cols: Option<&[String]>,
) -> Result<Vec<Object>> {
    // Qualify the right rows once: both paths merge them into left rows as
    // pre-qualified key-value pairs, so assembly stays byte-identical
    // between the hash path and the nested loop.
    let qright: Vec<Object> = right.iter().map(|r| qualify(r, right_key)).collect();
    // Equi-join fast path: an ON whose conjuncts split cleanly across the
    // join boundary (qualified `l.x = r.y` pairs) indexes the right side and
    // probes per left row instead of walking every pair. Everything else —
    // cross joins, non-equi predicates, unqualified/ambiguous ON — keeps the
    // nested loop below.
    if let Some(on) = on {
        if let Some(plan) = equi_plan(right_key, on) {
            return hash_join(
                &left, &qright, on, &plan, left_join, right_join, deadline, right_key, right_cols,
                left_cols,
            );
        }
    }
    let mut right_matched = vec![false; qright.len()];
    let mut out = Vec::new();
    for l in &left {
        deadline.check()?;
        let mut matched = false;
        for (ri, qr) in qright.iter().enumerate() {
            deadline.check()?;
            let merged = merged_row(l, qr);
            let ok = match on {
                None => true,
                Some(e) => matches!(eval_expr(e, &merged)?, Value::Bool(true)),
            };
            if ok {
                matched = true;
                right_matched[ri] = true;
                out.push(merged);
            }
        }
        if !matched && left_join {
            out.push(null_extended_left(l, &qright, right_key, right_cols));
        }
    }
    if right_join {
        let left_fields = union_of_fields(&left);
        for (ri, qr) in qright.iter().enumerate() {
            if !right_matched[ri] {
                out.push(null_extended_right(&left_fields, qr, left_cols));
            }
        }
    }
    Ok(out)
}

fn is_agg_item(item: &SelectItem) -> bool {
    let e = match item {
        SelectItem::UnnamedExpr(e) => e,
        SelectItem::ExprWithAlias { expr, .. } => expr,
        _ => return false,
    };
    contains_agg(e)
}

/// True for the aggregate functions the executor knows (`COUNT`/`SUM`/...),
/// regardless of window usage: the window aggregate path reuses the same
/// argument parsing.
fn is_agg_name(f: &sqlparser::ast::Function) -> bool {
    matches!(
        f.name.to_string().to_uppercase().as_str(),
        "COUNT" | "COUNT_BIG" | "SUM" | "AVG" | "MIN" | "MAX" | "GROUP_CONCAT" | "STRING_AGG"
    )
}

/// True for the aggregate functions the executor knows (`COUNT`/`SUM`/...).
/// Window forms (`OVER`) are never aggregates here.
fn is_agg_fn(f: &sqlparser::ast::Function) -> bool {
    !f.over.is_some() && is_agg_name(f)
}

/// True when the expression calls NEWID()/NEWSEQUENTIALID() at any depth.
/// Mirrors the expression shapes `rewrite_windows`/`walk_expr` cover.
pub(crate) fn calls_newid(e: &SqlExpr) -> bool {
    match e {
        SqlExpr::Function(f) => {
            let n = f.name.to_string().to_uppercase();
            if matches!(n.as_str(), "NEWID" | "NEWSEQUENTIALID" | "RAND") {
                return true;
            }
            child_exprs(e).into_iter().any(calls_newid)
        }
        SqlExpr::Nested(inner) => calls_newid(inner),
        SqlExpr::BinaryOp { left, right, .. } => calls_newid(left) || calls_newid(right),
        SqlExpr::UnaryOp { expr, .. } => calls_newid(expr),
        SqlExpr::IsNull(inner)
        | SqlExpr::IsNotNull(inner)
        | SqlExpr::IsTrue(inner)
        | SqlExpr::IsNotTrue(inner)
        | SqlExpr::IsFalse(inner)
        | SqlExpr::IsNotFalse(inner)
        | SqlExpr::IsUnknown(inner)
        | SqlExpr::IsNotUnknown(inner) => calls_newid(inner),
        SqlExpr::Between {
            expr, low, high, ..
        } => calls_newid(expr) || calls_newid(low) || calls_newid(high),
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            calls_newid(l) || calls_newid(r)
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            calls_newid(expr) || calls_newid(pattern)
        }
        SqlExpr::InList { expr, list, .. } => calls_newid(expr) || list.iter().any(calls_newid),
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand.as_deref().is_some_and(calls_newid)
                || conditions
                    .iter()
                    .any(|w| calls_newid(&w.condition) || calls_newid(&w.result))
                || else_result.as_deref().is_some_and(calls_newid)
        }
        SqlExpr::Cast { expr, .. } => calls_newid(expr),
        // Subqueries must recurse too: a NEWID() inside a subquery of an
        // UPDATE/DELETE/MERGE predicate would evaluate per node on replay
        // and silently diverge replicas — the same reason the statement is
        // rejected at the top level.
        SqlExpr::Subquery(q) | SqlExpr::Exists { subquery: q, .. } => query_calls_newid(q),
        SqlExpr::InSubquery { expr, subquery, .. } => {
            calls_newid(expr) || query_calls_newid(subquery)
        }
        SqlExpr::AnyOp { left, right, .. } | SqlExpr::AllOp { left, right, .. } => {
            calls_newid(left) || calls_newid(right)
        }
        // Same shared traversal as the other tree-wide predicates: wrappers
        // (CAST/FLOOR/IS NULL/…) must not hide a NEWID()/RAND() from the
        // write-path rejection.
        _ => child_exprs(e).into_iter().any(calls_newid),
    }
}

/// `calls_newid` over every scope-local surface of a query (mirrors the
/// outer-reference walkers' surface set).
fn query_calls_newid(q: &Query) -> bool {
    if let Some(w) = &q.with {
        for cte in &w.cte_tables {
            if query_calls_newid(&cte.query) {
                return true;
            }
        }
    }
    if setexpr_calls_newid(&q.body) {
        return true;
    }
    if let Some(ob) = &q.order_by {
        if let sqlparser::ast::OrderByKind::Expressions(exprs) = &ob.kind {
            if exprs.iter().any(|o| calls_newid(&o.expr)) {
                return true;
            }
        }
    }
    false
}

/// A FROM factor carrying nondeterministic calls: derived-table
/// subqueries and table-function arguments evaluate per execution — a
/// journal replay of the original text would re-roll them on every peer
/// and silently fork the cluster. Covers the relation itself and every
/// joined relation.
fn factor_calls_newid(factor: &sqlparser::ast::TableFactor) -> bool {
    match factor {
        sqlparser::ast::TableFactor::Derived { subquery, .. } => query_calls_newid(subquery),
        sqlparser::ast::TableFactor::TableFunction { expr, .. } => calls_newid(expr),
        _ => false,
    }
}

fn twj_calls_newid(twj: &sqlparser::ast::TableWithJoins) -> bool {
    factor_calls_newid(&twj.relation) || twj.joins.iter().any(|j| factor_calls_newid(&j.relation))
}

fn setexpr_calls_newid(body: &sqlparser::ast::SetExpr) -> bool {
    use sqlparser::ast::SetExpr;
    match body {
        SetExpr::Select(sel) => {
            for twj in &sel.from {
                if twj_calls_newid(twj) {
                    return true;
                }
                for j in &twj.joins {
                    if let Some(e) = join_on_expr(&j.join_operator) {
                        if calls_newid(e) {
                            return true;
                        }
                    }
                }
            }
            if sel.selection.as_ref().is_some_and(calls_newid) {
                return true;
            }
            if sel.having.as_ref().is_some_and(calls_newid) {
                return true;
            }
            if let sqlparser::ast::GroupByExpr::Expressions(es, _) = &sel.group_by {
                if es.iter().any(calls_newid) {
                    return true;
                }
            }
            sel.projection.iter().any(|item| match item {
                sqlparser::ast::SelectItem::UnnamedExpr(e)
                | sqlparser::ast::SelectItem::ExprWithAlias { expr: e, .. } => calls_newid(e),
                _ => false,
            })
        }
        SetExpr::SetOperation { left, right, .. } => {
            setexpr_calls_newid(left) || setexpr_calls_newid(right)
        }
        SetExpr::Query(inner) => query_calls_newid(inner),
        SetExpr::Values(rows) => rows
            .rows
            .iter()
            .flat_map(|parens| parens.content.iter())
            .any(calls_newid),
        _ => false,
    }
}

/// NEWID()/NEWSEQUENTIALID() anywhere in an UPDATE/DELETE/MERGE statement
/// (assignments, predicates, join conditions, MERGE clause actions).
fn stmt_calls_newid(stmt: &Statement) -> bool {
    use sqlparser::ast::{FromTable, JoinConstraint, JoinOperator};
    let join_ons = |twj: &sqlparser::ast::TableWithJoins| -> bool {
        twj.joins.iter().any(|j| {
            matches!(
                &j.join_operator,
                JoinOperator::Join(c)
                    | JoinOperator::Inner(c)
                    | JoinOperator::Left(c)
                    | JoinOperator::LeftOuter(c)
                    | JoinOperator::Right(c)
                    | JoinOperator::RightOuter(c)
                    | JoinOperator::FullOuter(c)
                    if matches!(c, JoinConstraint::On(e) if calls_newid(e))
            )
        })
    };
    match stmt {
        Statement::Update(u) => {
            u.assignments.iter().any(|a| calls_newid(&a.value))
                || u.selection.as_ref().is_some_and(calls_newid)
                || join_ons(&u.table)
                || twj_calls_newid(&u.table)
                || u.from.as_ref().is_some_and(|f| match f {
                    sqlparser::ast::UpdateTableFromKind::BeforeSet(twjs)
                    | sqlparser::ast::UpdateTableFromKind::AfterSet(twjs) => {
                        twjs.iter().any(|t| join_ons(t) || twj_calls_newid(t))
                    }
                })
        }
        Statement::Delete(d) => {
            d.selection.as_ref().is_some_and(calls_newid)
                || d.using
                    .as_ref()
                    .is_some_and(|twjs| twjs.iter().any(|t| join_ons(t) || twj_calls_newid(t)))
                || match &d.from {
                    FromTable::WithFromKeyword(twjs) | FromTable::WithoutKeyword(twjs) => {
                        twjs.iter().any(|t| join_ons(t) || twj_calls_newid(t))
                    }
                }
        }
        Statement::CreateTable(c) => {
            // CTAS journals its original text: a NEWID()/RAND() in the
            // query has no per-row rewrite here (unlike INSERT), so each
            // replaying peer would roll its own values and silently
            // diverge the cluster — refuse like UPDATE/DELETE/MERGE.
            c.query.as_ref().is_some_and(|q| query_calls_newid(q))
        }
        Statement::Merge(m) => {
            factor_calls_newid(&m.source)
                || calls_newid(&m.on)
                || m.clauses.iter().any(|c| {
                    c.predicate.as_ref().is_some_and(calls_newid)
                        || match &c.action {
                            sqlparser::ast::MergeAction::Insert(ins) => {
                                ins.insert_predicate.as_ref().is_some_and(calls_newid)
                                    || match &ins.kind {
                                        sqlparser::ast::MergeInsertKind::Values(v) => v
                                            .rows
                                            .iter()
                                            .any(|row| row.content.iter().any(calls_newid)),
                                        _ => false,
                                    }
                            }
                            sqlparser::ast::MergeAction::Update(up) => {
                                up.assignments.iter().any(|a| calls_newid(&a.value))
                                    || up.update_predicate.as_ref().is_some_and(calls_newid)
                                    || up.delete_predicate.as_ref().is_some_and(calls_newid)
                            }
                            sqlparser::ast::MergeAction::Delete { .. } => false,
                        }
                })
        }
        _ => false,
    }
}

fn contains_agg(e: &SqlExpr) -> bool {
    match e {
        SqlExpr::Function(f) => {
            if is_agg_fn(f) {
                return true;
            }
            // Aggregate calls wrapped in scalar functions or arithmetic
            // (`COALESCE(SUM(x), 0)`, `SUM(x) + 1`) count too.
            match &f.args {
                sqlparser::ast::FunctionArguments::List(list) => list.args.iter().any(|a| {
                    matches!(
                        a,
                        sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(inner),
                        ) if contains_agg(inner)
                    )
                }),
                _ => false,
            }
        }
        SqlExpr::Nested(inner) => contains_agg(inner),
        SqlExpr::BinaryOp { left, right, .. } => contains_agg(left) || contains_agg(right),
        SqlExpr::UnaryOp { expr, .. } => contains_agg(expr),
        // Wrappers the projection router must see through: `CAST(SUM(x))`,
        // `SUM(x) BETWEEN …`, `SUM(x) IS NULL`, `SUM(x) LIKE …`,
        // `SUM(x) IN (…)` — all evaluate aggregates (check_group_refs and
        // eval_group_expr implement the arms; only the routing predicate
        // was missing, which turned these into loud errors).
        SqlExpr::Cast { expr, .. } => contains_agg(expr),
        SqlExpr::Between {
            expr, low, high, ..
        } => contains_agg(expr) || contains_agg(low) || contains_agg(high),
        SqlExpr::IsNull(expr) => contains_agg(expr),
        SqlExpr::IsNotNull(expr) => contains_agg(expr),
        SqlExpr::IsDistinctFrom(a, b) | SqlExpr::IsNotDistinctFrom(a, b) => {
            contains_agg(a) || contains_agg(b)
        }
        SqlExpr::InList { expr, list, .. } => contains_agg(expr) || list.iter().any(contains_agg),
        SqlExpr::Like { .. } | SqlExpr::ILike { .. } => {
            // negated/any flags and the char escape cannot carry aggregates;
            // only the two operand expressions can.
            let (expr, pattern) = match e {
                SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
                    (expr, pattern)
                }
                _ => unreachable!(),
            };
            contains_agg(expr) || contains_agg(pattern)
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand.as_deref().is_some_and(contains_agg)
                || conditions
                    .iter()
                    .any(|w| contains_agg(&w.condition) || contains_agg(&w.result))
                || else_result.as_deref().is_some_and(contains_agg)
        }
        _ => false,
    }
}

// ---------- Window functions (OVER …) ----------
//
// SELECT-list window computation: calls are collected in first-appearance
// order (deduplicated by full text — two identical calls share one column),
// evaluated per row right after WHERE (SQL semantics: windows see the
// filtered rowset, before DISTINCT/ORDER BY/LIMIT), injected into the row
// docs as private `__w<i>$` columns and each call site rewritten to a
// reference of that column — DISTINCT / ORDER BY / LIMIT then run unchanged.
// Frames other than the default (RANGE UNBOUNDED PRECEDING AND CURRENT ROW)
// are refused explicitly, never silently narrowed.

fn window_tmp_col(i: usize) -> String {
    format!("__w{i}$")
}

/// Running (prefix-frame) fold for aggregate OVER with the default frame.
/// Mirrors `eval_agg`'s Agg arm exactly — same left-to-right evaluation
/// order, same FILTER/NULL/DISTINCT handling, same tie rules, same AVG
/// decimal-mode selection — so each snapshot equals the batch aggregate
/// evaluated over the frame ending at the current peer run, while the whole
/// partition costs O(n) evaluations instead of O(n²) re-folds.
struct RunningAgg {
    op: AggOp,
    sep: Option<String>,
    distinct: bool,
    seen: std::collections::BTreeSet<Vec<u8>>,
    /// COUNT(*): the arg is the `__count__` sentinel — count rows, not
    /// non-null arg values.
    count_star: bool,
    /// Rows passing FILTER (COUNT(*) counts them even when the arg is NULL).
    kept: i64,
    /// Non-null, post-DISTINCT argument values (COUNT(x); SUM/AVG empty).
    nonnull: i64,
    sum: Option<Value>,
    /// AVG exact-decimal mode flips on permanently at the first Decimal
    /// input (batch AVG picks its mode from the whole frame); the pre-flip
    /// prefix stays buffered for the one-time exact conversion.
    avg_dec_mode: bool,
    avg_vals: Vec<Value>,
    avg_dec: Decimal,
    avg_f64: f64,
    min: Option<Value>,
    max: Option<Value>,
    concat: String,
    concat_any: bool,
}

impl RunningAgg {
    fn new(op: AggOp, sep: Option<String>, distinct: bool, count_star: bool) -> Self {
        Self {
            op,
            sep,
            distinct,
            seen: std::collections::BTreeSet::new(),
            count_star,
            kept: 0,
            nonnull: 0,
            sum: None,
            avg_dec_mode: false,
            avg_vals: Vec::new(),
            avg_dec: Decimal::ZERO,
            avg_f64: 0.0,
            min: None,
            max: None,
            concat: String::new(),
            concat_any: false,
        }
    }

    /// Fold one partition row (in frame order) into the running state.
    /// `argval` is None for FILTER-excluded rows (their argument was never
    /// evaluated, matching the batch evaluator's filter-first order).
    fn push_row(&mut self, kept: bool, argval: Option<&Value>) -> Result<()> {
        if kept {
            self.kept += 1;
        }
        let Some(argval) = argval else {
            return Ok(());
        };
        if matches!(argval, Value::Null) {
            return Ok(());
        }
        if self.distinct
            && !self
                .seen
                .insert(encode::encode_to_vec(argval).map_err(SqlError::Encode)?)
        {
            return Ok(());
        }
        self.nonnull += 1;
        match self.op {
            AggOp::Count => {}
            AggOp::Sum => {
                let next = match self.sum.take() {
                    None => add_values(Value::Int(0), argval.clone())?,
                    Some(s) => add_values(s, argval.clone())?,
                };
                self.sum = Some(next);
            }
            AggOp::Avg => match argval {
                Value::Decimal(d) => {
                    if !self.avg_dec_mode {
                        self.avg_dec_mode = true;
                        self.avg_dec = Decimal::ZERO;
                        for v in std::mem::take(&mut self.avg_vals) {
                            self.avg_dec = self
                                .avg_dec
                                .checked_add(as_decimal(&v)?)
                                .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                        }
                    }
                    self.avg_dec = self
                        .avg_dec
                        .checked_add(*d)
                        .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                }
                other => {
                    if self.avg_dec_mode {
                        self.avg_dec = self
                            .avg_dec
                            .checked_add(as_decimal(other)?)
                            .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                    } else {
                        self.avg_vals.push(other.clone());
                        self.avg_f64 += match other {
                            Value::Int(i) => *i as f64,
                            Value::Float(f) => *f,
                            _ => return err("AVG of non-numeric"),
                        };
                    }
                }
            },
            AggOp::Min => match &self.min {
                // Ties keep the first value, exactly like the batch reduce.
                Some(m) if Value::cmp_values(m, argval) != std::cmp::Ordering::Greater => {}
                _ => self.min = Some(argval.clone()),
            },
            AggOp::Max => match &self.max {
                Some(m) if Value::cmp_values(m, argval) != std::cmp::Ordering::Less => {}
                _ => self.max = Some(argval.clone()),
            },
            AggOp::GroupConcat => {
                // The separator must precede every element after the FIRST
                // pushed one (an element rendering as "" still counts).
                if self.concat_any {
                    self.concat.push_str(self.sep.as_deref().unwrap_or(","));
                } else {
                    self.concat_any = true;
                }
                self.concat.push_str(&value_to_text(argval));
            }
        }
        Ok(())
    }

    /// Value of the aggregate over everything folded so far — the frame
    /// ending at the current peer run.
    fn snapshot(&self) -> Value {
        match self.op {
            AggOp::Count => Value::Int(if self.count_star {
                self.kept
            } else {
                self.nonnull
            }),
            AggOp::Sum => self.sum.clone().unwrap_or(Value::Null),
            AggOp::Avg => {
                if self.nonnull == 0 {
                    Value::Null
                } else if self.avg_dec_mode {
                    match self.avg_dec.checked_div(Decimal::from(self.nonnull)) {
                        Some(d) => Value::Decimal(d),
                        None => Value::Null,
                    }
                } else {
                    Value::Float(self.avg_f64 / self.nonnull as f64)
                }
            }
            AggOp::Min => self.min.clone().unwrap_or(Value::Null),
            AggOp::Max => self.max.clone().unwrap_or(Value::Null),
            // Zero contributing rows (or an all-NULL frame) is NULL, not the
            // empty string — the batch reduce keeps the same contract and
            // IS NULL checks depend on it.
            AggOp::GroupConcat => {
                if self.concat_any {
                    Value::Str(self.concat.clone())
                } else {
                    Value::Null
                }
            }
        }
    }
}

/// Sliding-frame aggregate for custom window frames (ROWS/RANGE/GROUPS
/// BETWEEN): the frame's rows live in a FIFO deque and every aggregate is
/// maintained incrementally — push advances the frame's high edge, `pop_to`
/// its low edge. Both edges only move forward (frame bounds are monotone
/// over the sorted partition), so the whole computation is O(n) pushes and
/// pops. SUM/AVG removal mirrors [`add_values`]; an unrecoverable inverse
/// (Int overflow — the batch fold NULLs there too) sets `degraded` and the
/// caller refolds that partition's remaining rows from the frame slice.
/// DISTINCT and GROUP_CONCAT cannot invert and never route here.
struct SlidingFrameAgg {
    op: AggOp,
    count_star: bool,
    kept: i64,
    nonnull: i64,
    sum: Option<Value>,
    avg_dec_mode: bool,
    avg_vals: std::collections::VecDeque<Value>,
    avg_dec: Decimal,
    avg_f64: f64,
    /// Monotone candidate deque for MIN/MAX: (sorted position, value).
    /// The front is the current extremum, earliest on ties — exactly the
    /// batch reduce's first-wins rule.
    extreme: std::collections::VecDeque<(usize, Value)>,
    /// The frame's rows in order: (sorted position, FILTER-kept, argument).
    window: std::collections::VecDeque<(usize, bool, Option<Value>)>,
    degraded: bool,
}

impl SlidingFrameAgg {
    fn new(op: AggOp, count_star: bool) -> Self {
        Self {
            op,
            count_star,
            kept: 0,
            nonnull: 0,
            sum: None,
            avg_dec_mode: false,
            avg_vals: std::collections::VecDeque::new(),
            avg_dec: Decimal::ZERO,
            avg_f64: 0.0,
            extreme: std::collections::VecDeque::new(),
            window: std::collections::VecDeque::new(),
            degraded: false,
        }
    }

    /// Fold the row at sorted position `pos` into the state (frame high edge
    /// advances). Same fold order and NULL/FILTER rules as
    /// [`RunningAgg::push_row`].
    fn push(&mut self, pos: usize, kept: bool, argval: Option<&Value>) -> Result<()> {
        self.window.push_back((pos, kept, argval.cloned()));
        if kept {
            self.kept += 1;
        }
        let Some(argval) = argval else {
            return Ok(());
        };
        if matches!(argval, Value::Null) {
            return Ok(());
        }
        match self.op {
            AggOp::Min => {
                while self
                    .extreme
                    .back()
                    .is_some_and(|(_, b)| Value::cmp_values(b, argval) == Ordering::Greater)
                {
                    self.extreme.pop_back();
                }
                self.extreme.push_back((pos, argval.clone()));
                return Ok(());
            }
            AggOp::Max => {
                while self
                    .extreme
                    .back()
                    .is_some_and(|(_, b)| Value::cmp_values(b, argval) == Ordering::Less)
                {
                    self.extreme.pop_back();
                }
                self.extreme.push_back((pos, argval.clone()));
                return Ok(());
            }
            _ => {}
        }
        self.nonnull += 1;
        match self.op {
            AggOp::Count => {}
            AggOp::Sum => {
                let next = match self.sum.take() {
                    None => add_values(Value::Int(0), argval.clone())?,
                    Some(s) => add_values(s, argval.clone())?,
                };
                self.sum = Some(next);
            }
            AggOp::Avg => match argval {
                Value::Decimal(d) => {
                    if !self.avg_dec_mode {
                        self.avg_dec_mode = true;
                        self.avg_dec = Decimal::ZERO;
                        for v in std::mem::take(&mut self.avg_vals) {
                            self.avg_dec = self
                                .avg_dec
                                .checked_add(as_decimal(&v)?)
                                .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                        }
                    }
                    self.avg_dec = self
                        .avg_dec
                        .checked_add(*d)
                        .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                }
                other => {
                    if self.avg_dec_mode {
                        self.avg_dec = self
                            .avg_dec
                            .checked_add(as_decimal(other)?)
                            .ok_or_else(|| SqlError::Message("AVG sum overflow".into()))?;
                    } else {
                        self.avg_vals.push_back(other.clone());
                        self.avg_f64 += match other {
                            Value::Int(i) => *i as f64,
                            Value::Float(f) => *f,
                            _ => return err("AVG of non-numeric"),
                        };
                    }
                }
            },
            AggOp::Min | AggOp::Max | AggOp::GroupConcat => {}
        }
        Ok(())
    }

    /// Retract the frame's low edge: pop every row left of sorted position
    /// `lo` and undo its contribution. `Min`/`Max` drop their deque fronts.
    fn pop_to(&mut self, lo: usize) {
        while self.window.front().is_some_and(|(pos, _, _)| *pos < lo) {
            let (pos, kept, arg) = self.window.pop_front().expect("checked above");
            if matches!(self.op, AggOp::Min | AggOp::Max) {
                if self.extreme.front().is_some_and(|(p, _)| *p == pos) {
                    self.extreme.pop_front();
                }
                continue;
            }
            if kept {
                self.kept -= 1;
            }
            let Some(v) = arg else { continue };
            if matches!(v, Value::Null) {
                continue;
            }
            self.nonnull -= 1;
            match self.op {
                AggOp::Count => {}
                AggOp::Sum => match self.sum.take() {
                    // A sticky-NULL (Int overflow) or absent sum cannot be
                    // inverted — the caller refolds from the slice.
                    None | Some(Value::Null) => {
                        self.degraded = true;
                        self.sum = Some(Value::Null);
                    }
                    Some(s) => match sub_values(s, v.clone()) {
                        Ok(next) => {
                            if matches!(next, Value::Null) {
                                self.degraded = true;
                            }
                            self.sum = Some(next);
                        }
                        Err(_) => self.degraded = true,
                    },
                },
                AggOp::Avg => match v {
                    Value::Decimal(d) => {
                        // A Decimal push flips the mode permanently; undoing
                        // one before any flip means state is inconsistent.
                        if !self.avg_dec_mode {
                            self.degraded = true;
                        } else {
                            match self.avg_dec.checked_sub(d) {
                                Some(nd) => self.avg_dec = nd,
                                None => self.degraded = true,
                            }
                        }
                    }
                    other => {
                        if self.avg_dec_mode {
                            match as_decimal(&other)
                                .ok()
                                .and_then(|d| self.avg_dec.checked_sub(d))
                            {
                                Some(nd) => self.avg_dec = nd,
                                None => self.degraded = true,
                            }
                        } else {
                            match self.avg_vals.pop_front() {
                                Some(front) => {
                                    let f = match front {
                                        Value::Int(i) => i as f64,
                                        Value::Float(f) => f,
                                        _ => {
                                            self.degraded = true;
                                            0.0
                                        }
                                    };
                                    self.avg_f64 -= f;
                                }
                                None => self.degraded = true,
                            }
                        }
                    }
                },
                AggOp::Min | AggOp::Max | AggOp::GroupConcat => {}
            }
        }
    }

    /// Aggregate value over the current frame — mirrors
    /// [`RunningAgg::snapshot`] field for field.
    fn value(&self) -> Value {
        match self.op {
            AggOp::Count => Value::Int(if self.count_star {
                self.kept
            } else {
                self.nonnull
            }),
            AggOp::Sum => self.sum.clone().unwrap_or(Value::Null),
            AggOp::Avg => {
                if self.nonnull == 0 {
                    Value::Null
                } else if self.avg_dec_mode {
                    self.avg_dec
                        .checked_div(Decimal::from(self.nonnull))
                        .map(Value::Decimal)
                        .unwrap_or(Value::Null)
                } else {
                    Value::Float(self.avg_f64 / self.nonnull as f64)
                }
            }
            AggOp::Min | AggOp::Max => self
                .extreme
                .front()
                .map(|(_, v)| v.clone())
                .unwrap_or(Value::Null),
            AggOp::GroupConcat => Value::Null,
        }
    }
}

/// Declared column names of a real-table table factor (views and CTEs have
/// no meta columns — their rows carry the keys already).
fn collect_factor_columns(
    factor: &sqlparser::ast::TableFactor,
    catalog: &std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
    out: &mut std::collections::HashSet<String>,
) {
    if let sqlparser::ast::TableFactor::Table { name, .. } = factor {
        let tname = obj_name(name);
        if let Some(meta) = catalog.get(&tname) {
            if !meta.is_view() {
                out.extend(meta.columns.iter().cloned());
            }
        }
    }
}

/// `SELECT *` column metadata for an EMPTY rowset: declared columns of one
/// FROM factor, qualified as the merged rows would be (`key` = bare column
/// for a solo table, "alias.col" / "table.col" once rows get joined — the
/// exact shape `load_from` produces). Views contribute nothing (their shape
/// belongs to the stored query, not the catalog).
fn collect_star_columns(
    factor: &sqlparser::ast::TableFactor,
    catalog: &std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
    out: &mut Vec<String>,
    qualify: bool,
) {
    if let sqlparser::ast::TableFactor::Table { name, alias, .. } = factor {
        let tname = obj_name(name);
        let Some(meta) = catalog.get(&tname) else {
            return;
        };
        if meta.is_view() {
            return;
        }
        for c in &meta.columns {
            if qualify {
                let key = alias
                    .as_ref()
                    .map(|a| a.name.value.clone())
                    .unwrap_or_else(|| tname.clone());
                out.push(format!("{key}.{c}"));
            } else {
                out.push(c.clone());
            }
        }
    }
}

/// Refuse unknown columns inside window PARTITION BY / ORDER BY / arguments:
/// `eval_expr` resolves a missing column to NULL, which silently collapses
/// the whole window computation (see compute_windows). Resolution mirrors
/// `lookup_col` (exact key or joined "alias.col" leaf). Walks the shapes
/// `rewrite_windows` knows; anything else keeps the legacy NULL behavior
/// rather than risking a false reject.
fn check_window_columns(e: &SqlExpr, cols: &std::collections::HashSet<String>) -> Result<()> {
    let resolvable = |leaf: &str| -> bool {
        if cols.contains(leaf) {
            return true;
        }
        let suffix = format!(".{leaf}");
        cols.iter().any(|k| k.ends_with(&suffix))
    };
    match e {
        // `__count__` is the COUNT(*) sentinel (never a real column); T-SQL
        // `@var` names get their own loud refusal inside eval_expr.
        SqlExpr::Identifier(i) if i.value != "__count__" && !i.value.starts_with('@') => {
            if resolvable(&i.value) {
                Ok(())
            } else {
                err(format!("column {} does not exist", i.value))
            }
        }
        SqlExpr::CompoundIdentifier(parts) => {
            let leaf = parts.last().map(|p| p.value.as_str()).unwrap_or("");
            if resolvable(leaf) {
                Ok(())
            } else {
                err(format!("column {leaf} does not exist"))
            }
        }
        SqlExpr::Nested(inner) => check_window_columns(inner, cols),
        SqlExpr::BinaryOp { left, right, .. } => {
            check_window_columns(left, cols)?;
            check_window_columns(right, cols)
        }
        SqlExpr::UnaryOp { expr, .. } => check_window_columns(expr, cols),
        SqlExpr::IsNull(inner)
        | SqlExpr::IsNotNull(inner)
        | SqlExpr::IsTrue(inner)
        | SqlExpr::IsNotTrue(inner)
        | SqlExpr::IsFalse(inner)
        | SqlExpr::IsNotFalse(inner)
        | SqlExpr::IsUnknown(inner)
        | SqlExpr::IsNotUnknown(inner) => check_window_columns(inner, cols),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            check_window_columns(expr, cols)?;
            check_window_columns(low, cols)?;
            check_window_columns(high, cols)
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            check_window_columns(l, cols)?;
            check_window_columns(r, cols)
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            check_window_columns(expr, cols)?;
            check_window_columns(pattern, cols)
        }
        SqlExpr::InList { expr, list, .. } => {
            check_window_columns(expr, cols)?;
            for item in list {
                check_window_columns(item, cols)?;
            }
            Ok(())
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(op) = operand {
                check_window_columns(op, cols)?;
            }
            for w in conditions {
                check_window_columns(&w.condition, cols)?;
                check_window_columns(&w.result, cols)?;
            }
            if let Some(el) = else_result {
                check_window_columns(el, cols)?;
            }
            Ok(())
        }
        SqlExpr::Cast { expr, .. } => check_window_columns(expr, cols),
        SqlExpr::Function(f) => {
            // Mirror `eval_fn_arg`: the datepart family's FIRST argument is
            // a bare datepart keyword (`DATEDIFF(day, a, b)`), never a
            // column reference — validating it as a column would reject
            // every windowed DATEDIFF/DATEADD.
            let fname = f.name.to_string().to_uppercase();
            let skip_first = takes_datepart_name(&fname);
            let mut first_unnamed = true;
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        let skip = skip_first && first_unnamed;
                        first_unnamed = false;
                        if !skip {
                            check_window_columns(inner, cols)?;
                        }
                    }
                }
            }
            if let Some(flt) = &f.filter {
                check_window_columns(flt, cols)?;
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

/// Window functions in one SELECT's projection, first-appearance order.
/// Window calls inside a single expression (QUALIFY predicate): same
/// dedupe-by-rendered-key as [`window_calls_of`], so an identical call in
/// the projection and QUALIFY shares one computed column.
fn window_calls_of_expr(e: &SqlExpr) -> Vec<Function> {
    let mut out: Vec<Function> = Vec::new();
    let mut seen: Vec<String> = Vec::new();
    scan_windows(e, &mut out, &mut seen);
    out
}

fn window_calls_of(items: &[SelectItem]) -> Vec<Function> {
    let mut out: Vec<Function> = Vec::new();
    let mut seen: Vec<String> = Vec::new();
    for item in items {
        let e = match item {
            SelectItem::UnnamedExpr(e) => e,
            SelectItem::ExprWithAlias { expr, .. } => expr,
            _ => continue,
        };
        scan_windows(e, &mut out, &mut seen);
    }
    out
}

/// Mirrors `subst_expr`'s recursion: descend into the composite expression
/// shapes the executor evaluates, so a window call wrapped in arithmetic /
/// CASE / COALESCE is still found. Subquery-shaped nodes are never descended
/// into — `subst_expr` has already rewritten them, and anything surviving is
/// a loud evaluation error, not a silently dropped window call.
fn scan_windows(e: &SqlExpr, out: &mut Vec<Function>, seen: &mut Vec<String>) {
    match e {
        SqlExpr::Function(f) => {
            if f.over.is_some() {
                let key = format!("{f}");
                if !seen.contains(&key) {
                    seen.push(key);
                    out.push(f.clone());
                }
            }
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        scan_windows(inner, out, seen);
                    }
                }
            }
            if let Some(filter) = &f.filter {
                scan_windows(filter, out, seen);
            }
        }
        SqlExpr::Nested(inner) => scan_windows(inner, out, seen),
        SqlExpr::BinaryOp { left, right, .. } => {
            scan_windows(left, out, seen);
            scan_windows(right, out, seen);
        }
        SqlExpr::UnaryOp { expr, .. } => scan_windows(expr, out, seen),
        SqlExpr::IsNull(inner)
        | SqlExpr::IsNotNull(inner)
        | SqlExpr::IsTrue(inner)
        | SqlExpr::IsNotTrue(inner)
        | SqlExpr::IsFalse(inner)
        | SqlExpr::IsNotFalse(inner)
        | SqlExpr::IsUnknown(inner)
        | SqlExpr::IsNotUnknown(inner) => scan_windows(inner, out, seen),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            scan_windows(expr, out, seen);
            scan_windows(low, out, seen);
            scan_windows(high, out, seen);
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            scan_windows(l, out, seen);
            scan_windows(r, out, seen);
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            scan_windows(expr, out, seen);
            scan_windows(pattern, out, seen);
        }
        SqlExpr::InList { expr, list, .. } => {
            scan_windows(expr, out, seen);
            for item in list {
                scan_windows(item, out, seen);
            }
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(op) = operand {
                scan_windows(op, out, seen);
            }
            for w in conditions {
                scan_windows(&w.condition, out, seen);
                scan_windows(&w.result, out, seen);
            }
            if let Some(el) = else_result {
                scan_windows(el, out, seen);
            }
        }
        SqlExpr::Cast { expr, .. } => scan_windows(expr, out, seen),
        _ => {}
    }
}

/// Replace every window call with a reference to its computed column; the
/// dedup key (full text) matches [`scan_windows`], so indices agree.
fn rewrite_windows(e: &mut SqlExpr, calls: &[Function], names: &[String]) {
    match e {
        SqlExpr::Function(f) if f.over.is_some() => {
            let key = format!("{f}");
            if let Some(i) = calls.iter().position(|c| format!("{c}") == key) {
                *e = SqlExpr::Identifier(sqlparser::ast::Ident::new(
                    names.get(i).cloned().unwrap_or_else(|| window_tmp_col(i)),
                ));
            }
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &mut f.args {
                for a in &mut list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        rewrite_windows(inner, calls, names);
                    }
                }
            }
            if let Some(filter) = &mut f.filter {
                rewrite_windows(filter, calls, names);
            }
        }
        SqlExpr::Nested(inner) => rewrite_windows(inner, calls, names),
        SqlExpr::BinaryOp { left, right, .. } => {
            rewrite_windows(left, calls, names);
            rewrite_windows(right, calls, names);
        }
        SqlExpr::UnaryOp { expr, .. } => rewrite_windows(expr, calls, names),
        SqlExpr::IsNull(inner)
        | SqlExpr::IsNotNull(inner)
        | SqlExpr::IsTrue(inner)
        | SqlExpr::IsNotTrue(inner)
        | SqlExpr::IsFalse(inner)
        | SqlExpr::IsNotFalse(inner)
        | SqlExpr::IsUnknown(inner)
        | SqlExpr::IsNotUnknown(inner) => rewrite_windows(inner, calls, names),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            rewrite_windows(expr, calls, names);
            rewrite_windows(low, calls, names);
            rewrite_windows(high, calls, names);
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            rewrite_windows(l, calls, names);
            rewrite_windows(r, calls, names);
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            rewrite_windows(expr, calls, names);
            rewrite_windows(pattern, calls, names);
        }
        SqlExpr::InList { expr, list, .. } => {
            rewrite_windows(expr, calls, names);
            for item in list {
                rewrite_windows(item, calls, names);
            }
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(op) = operand {
                rewrite_windows(op, calls, names);
            }
            for w in conditions {
                rewrite_windows(&mut w.condition, calls, names);
                rewrite_windows(&mut w.result, calls, names);
            }
            if let Some(el) = else_result {
                rewrite_windows(el, calls, names);
            }
        }
        SqlExpr::Cast { expr, .. } => rewrite_windows(expr, calls, names),
        _ => {}
    }
}

/// Unnamed-argument exprs of a function call (`LAG(v, 1, 0)` → `[v, 1, 0]`).
fn fn_args(f: &Function) -> Vec<SqlExpr> {
    match &f.args {
        sqlparser::ast::FunctionArguments::List(list) => list
            .args
            .iter()
            .filter_map(|a| match a {
                sqlparser::ast::FunctionArg::Unnamed(sqlparser::ast::FunctionArgExpr::Expr(
                    inner,
                )) => Some(inner.clone()),
                _ => None,
            })
            .collect(),
        _ => Vec::new(),
    }
}

/// Supported window specification shape: no named window, no frame beyond
/// the default, no IGNORE NULLS. Refusals stay explicit — an unsupported
/// frame would silently change the result shape (one row per partition vs
/// one value per row).
fn validate_window_spec<'a>(
    f: &'a Function,
    fname: &str,
    aggregate: bool,
) -> Result<&'a sqlparser::ast::WindowSpec> {
    // FILTER is meaningful only for aggregate window functions (it rides the
    // frame); for the scalar family it is not defined (Postgres/SQLite both
    // refuse) and silently ignoring it would return unfiltered numbers.
    if f.filter.is_some() && !aggregate {
        return err(format!(
            "FILTER is not supported for non-aggregate window functions: {fname}"
        ));
    }
    let spec = match &f.over {
        Some(sqlparser::ast::WindowType::WindowSpec(s)) => s,
        Some(sqlparser::ast::WindowType::NamedWindow(n)) => {
            return err(format!(
                "named window \"{}\" requires a WINDOW clause, which is not supported; \
                 write the OVER (...) inline",
                n.value
            ));
        }
        None => return err("window call without OVER"),
    };
    if let Some(n) = &spec.window_name {
        // `OVER (name)` references a WINDOW clause definition, which the
        // engine refuses; anything else would silently ignore the name.
        return err(format!(
            "named window \"{}\" requires a WINDOW clause, which is not supported; \
             write the OVER (...) inline",
            n.value
        ));
    }
    // Frames are accepted (SQL:2003 ROWS/RANGE/GROUPS BETWEEN … AND …);
    // the structural rules and offset shapes are checked by
    // [`parse_window_frame`] in `compute_windows`.
    if matches!(
        f.null_treatment,
        Some(sqlparser::ast::NullTreatment::IgnoreNulls)
    ) {
        return err(format!("IGNORE NULLS is not supported: {fname}"));
    }
    Ok(spec)
}

/// Parsed custom window frame ([`parse_window_frame`]): bounds are checked
/// and offsets const-evaluated once per window call, not per partition.
#[derive(Clone, Debug)]
enum WindowFramePlan {
    /// `ROWS BETWEEN … AND …`: bounds are row counts within the (sorted)
    /// partition.
    Rows {
        start: FrameRowBound,
        end: FrameRowBound,
    },
    /// `GROUPS BETWEEN … AND …`: bounds count PEER GROUPS, mapped back to
    /// row spans through the partition's run layout.
    Groups {
        start: FrameRowBound,
        end: FrameRowBound,
    },
    /// `RANGE BETWEEN … AND …`: value bounds are arithmetic shifts of the
    /// single ORDER BY key.
    Range {
        start: FrameValueBound,
        end: FrameValueBound,
    },
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum FrameRowBound {
    Unbounded,
    Preceding(u64),
    CurrentRow,
    Following(u64),
    UnboundedFollowing,
}

/// One RANGE offset: the constant value plus whether the source spelling
/// was `INTERVAL 'n' UNIT` — an interval offset shifts only a TIMESTAMP
/// key (by the converted milliseconds), never a numeric one.
#[derive(Clone, Debug)]
struct FrameRangeOffset {
    off: Value,
    interval: bool,
}

#[derive(Clone, Debug)]
enum FrameValueBound {
    Unbounded,
    Preceding(FrameRangeOffset),
    CurrentRow,
    Following(FrameRangeOffset),
    UnboundedFollowing,
}

/// Rank bounds in frame order (a start must not come after its end).
fn frame_row_rank(b: &FrameRowBound) -> u8 {
    match b {
        FrameRowBound::Unbounded => 0,
        FrameRowBound::Preceding(_) => 1,
        FrameRowBound::CurrentRow => 2,
        FrameRowBound::Following(_) => 3,
        FrameRowBound::UnboundedFollowing => 4,
    }
}

fn frame_value_rank(b: &FrameValueBound) -> u8 {
    match b {
        FrameValueBound::Unbounded => 0,
        FrameValueBound::Preceding(_) => 1,
        FrameValueBound::CurrentRow => 2,
        FrameValueBound::Following(_) => 3,
        FrameValueBound::UnboundedFollowing => 4,
    }
}

/// Validate structure and const-eval offsets. `order_len` is the ORDER BY
/// key count — RANGE value bounds shift THE sort key, so they demand
/// exactly one (SQL standard).
fn parse_window_frame(
    frame: &sqlparser::ast::WindowFrame,
    order_len: usize,
) -> Result<WindowFramePlan> {
    // The bare `ROWS 3 PRECEDING` spelling means `BETWEEN … AND CURRENT ROW`.
    let end_default = frame
        .end_bound
        .clone()
        .unwrap_or(sqlparser::ast::WindowFrameBound::CurrentRow);
    let row_bound = |b: &sqlparser::ast::WindowFrameBound| -> Result<FrameRowBound> {
        Ok(match b {
            sqlparser::ast::WindowFrameBound::Preceding(None) => FrameRowBound::Unbounded,
            sqlparser::ast::WindowFrameBound::Preceding(Some(e)) => {
                FrameRowBound::Preceding(row_offset(e)?)
            }
            sqlparser::ast::WindowFrameBound::CurrentRow => FrameRowBound::CurrentRow,
            sqlparser::ast::WindowFrameBound::Following(Some(e)) => {
                FrameRowBound::Following(row_offset(e)?)
            }
            sqlparser::ast::WindowFrameBound::Following(None) => FrameRowBound::UnboundedFollowing,
        })
    };
    Ok(match frame.units {
        sqlparser::ast::WindowFrameUnits::Rows => {
            let (start, end) = (row_bound(&frame.start_bound)?, row_bound(&end_default)?);
            if frame_row_rank(&start) > frame_row_rank(&end)
                || match (start, end) {
                    (FrameRowBound::Preceding(a), FrameRowBound::Preceding(b)) => a < b,
                    (FrameRowBound::Following(a), FrameRowBound::Following(b)) => a > b,
                    _ => false,
                }
            {
                return err("window frame start cannot be after its end");
            }
            WindowFramePlan::Rows { start, end }
        }
        sqlparser::ast::WindowFrameUnits::Groups => {
            let (start, end) = (row_bound(&frame.start_bound)?, row_bound(&end_default)?);
            if frame_row_rank(&start) > frame_row_rank(&end)
                || match (start, end) {
                    (FrameRowBound::Preceding(a), FrameRowBound::Preceding(b)) => a < b,
                    (FrameRowBound::Following(a), FrameRowBound::Following(b)) => a > b,
                    _ => false,
                }
            {
                return err("window frame start cannot be after its end");
            }
            WindowFramePlan::Groups { start, end }
        }
        sqlparser::ast::WindowFrameUnits::Range => {
            let value_bound = |b: &sqlparser::ast::WindowFrameBound| -> Result<FrameValueBound> {
                Ok(match b {
                    sqlparser::ast::WindowFrameBound::Preceding(None) => FrameValueBound::Unbounded,
                    sqlparser::ast::WindowFrameBound::Preceding(Some(e)) => {
                        FrameValueBound::Preceding(range_offset(e)?)
                    }
                    sqlparser::ast::WindowFrameBound::CurrentRow => FrameValueBound::CurrentRow,
                    sqlparser::ast::WindowFrameBound::Following(Some(e)) => {
                        FrameValueBound::Following(range_offset(e)?)
                    }
                    sqlparser::ast::WindowFrameBound::Following(None) => {
                        FrameValueBound::UnboundedFollowing
                    }
                })
            };
            let (start, end) = (value_bound(&frame.start_bound)?, value_bound(&end_default)?);
            // Structural order: UNBOUNDED PRECEDING < n PRECEDING < CURRENT
            // ROW < n FOLLOWING < UNBOUNDED FOLLOWING, with equal-shape
            // offset comparisons (`5 PRECEDING` to `2 PRECEDING` is legal,
            // the reverse frames nothing and the standard refuses it).
            let misplaced = match (&start, &end) {
                (FrameValueBound::Preceding(a), FrameValueBound::Preceding(b)) => {
                    Value::cmp_values(&a.off, &b.off) == Ordering::Less
                }
                (FrameValueBound::Following(a), FrameValueBound::Following(b)) => {
                    Value::cmp_values(&a.off, &b.off) == Ordering::Greater
                }
                _ => false,
            };
            if frame_value_rank(&start) > frame_value_rank(&end) || misplaced {
                return err("window frame start cannot be after its end");
            }
            // A value offset shifts the single sort key; without exactly one
            // ORDER BY key there is nothing to shift. UNBOUNDED / CURRENT ROW
            // spellings stay legal unordered (they degenerate to the whole
            // partition / the peer set, which unordered makes everything).
            let has_offset = |b: &FrameValueBound| {
                matches!(
                    b,
                    FrameValueBound::Preceding(_) | FrameValueBound::Following(_)
                )
            };
            if (has_offset(&start) || has_offset(&end)) && order_len != 1 {
                return err(
                    "RANGE with a value offset requires exactly one ORDER BY key                      (the frame shifts THE sort key)",
                );
            }
            WindowFramePlan::Range { start, end }
        }
    })
}

/// ROWS/GROUPS offsets: non-negative integer constants.
fn row_offset(e: &SqlExpr) -> Result<u64> {
    match eval_const(e)? {
        Value::Int(k) if k >= 0 => Ok(k as u64),
        other => err(format!(
            "ROWS/GROUPS frame offsets must be non-negative integers, got {}",
            other.type_name()
        )),
    }
}

/// RANGE offsets: non-negative numeric constants (Int/Float/Decimal).
/// INTERVAL spellings are rejected — TIMESTAMP keys shift by integer
/// milliseconds, mirroring the engine's TIMESTAMP ± INTEGER arithmetic.
fn range_offset(e: &SqlExpr) -> Result<FrameRangeOffset> {
    if let SqlExpr::Interval(iv) = e {
        let unit = match iv.leading_field {
            Some(sqlparser::ast::DateTimeField::Day) => 86_400_000i64,
            Some(sqlparser::ast::DateTimeField::Hour) => 3_600_000,
            Some(sqlparser::ast::DateTimeField::Minute) => 60_000,
            Some(sqlparser::ast::DateTimeField::Second) => 1_000,
            _ => {
                return err(
                    "INTERVAL frame offsets support DAY/HOUR/MINUTE/SECOND only \
                     (YEAR/MONTH calendar arithmetic is not supported)",
                );
            }
        };
        if iv.last_field.is_some() || iv.leading_field.is_none() {
            return err(
                "INTERVAL frame offsets take a single unit: INTERVAL 'n' DAY/HOUR/MINUTE/SECOND",
            );
        }
        let SqlExpr::Value(v) = iv.value.as_ref() else {
            return err("INTERVAL frame offset value must be a string literal");
        };
        let sqlparser::ast::Value::SingleQuotedString(text) = &v.value else {
            return err("INTERVAL frame offset value must be a string literal");
        };
        let secs: f64 = text
            .trim()
            .parse()
            .map_err(|_| SqlError::Message(format!("invalid INTERVAL value '{text}'")))?;
        if !secs.is_finite() || secs < 0.0 {
            return err("INTERVAL frame offsets must be non-negative");
        }
        let ms = (secs * unit as f64) as i64;
        if ms == 0 && secs > 0.0 {
            return err("INTERVAL frame offset is smaller than one millisecond");
        }
        return Ok(FrameRangeOffset {
            off: Value::Int(ms),
            interval: true,
        });
    }
    match eval_const(e)? {
        v @ (Value::Int(_) | Value::Float(_) | Value::Decimal(_)) => {
            if Value::cmp_values(&v, &Value::Int(0)) == Ordering::Less {
                return err("RANGE frame offsets must be non-negative");
            }
            Ok(FrameRangeOffset {
                off: v,
                interval: false,
            })
        }
        other => err(format!(
            "RANGE frame offsets must be numeric constants, got {}",
            other.type_name()
        )),
    }
}

fn frame_offset_f64(off: &Value) -> Result<f64> {
    match off {
        Value::Int(k) => Ok(*k as f64),
        Value::Float(f) => Ok(*f),
        Value::Decimal(d) => Ok(d.to_f64().unwrap_or(f64::NAN)),
        _ => err("RANGE frame offset must be numeric"),
    }
}

/// Shift a RANGE frame endpoint: `key ± off`, direction-aware, mirroring the
/// engine's arithmetic (Decimal exact, Int checked, TIMESTAMP ± integer ms
/// with the 0001..=9999 domain). `None` = the endpoint fell outside the
/// value domain (Int/Timestamp overflow) — the interval is unbounded on
/// that side, never a silent truncation.
fn shift_range_key(key: &Value, off: &FrameRangeOffset, up: bool) -> Result<Option<Value>> {
    // An INTERVAL spelling shifts only a TIMESTAMP key: DAY/HOUR/… are time
    // units, and applying them to a number would silently reinterpret them.
    if off.interval && !matches!(key, Value::Timestamp(_) | Value::Null) {
        return err("INTERVAL frame offsets require a TIMESTAMP ORDER BY key \
             (numeric keys take a plain constant offset)");
    }
    shift_range_key_value(key, &off.off, up)
}

fn shift_range_key_value(key: &Value, off: &Value, up: bool) -> Result<Option<Value>> {
    match (key, off) {
        (Value::Null, _) => Ok(None),
        (Value::Int(k), Value::Int(o)) => {
            let v = if up {
                k.checked_add(*o)
            } else {
                k.checked_sub(*o)
            };
            Ok(v.map(Value::Int))
        }
        (Value::Float(k), _) => {
            let f = frame_offset_f64(off)?;
            Ok(Some(Value::Float(if up { k + f } else { k - f })))
        }
        (Value::Int(_), Value::Float(_)) => {
            let f = frame_offset_f64(off)?;
            let k = match key {
                Value::Int(k) => *k as f64,
                _ => unreachable!("matched above"),
            };
            Ok(Some(Value::Float(if up { k + f } else { k - f })))
        }
        (Value::Decimal(_), _) | (Value::Int(_), Value::Decimal(_)) => {
            let (a, b) = (as_decimal(key)?, as_decimal(off)?);
            let v = if up {
                a.checked_add(b)
            } else {
                a.checked_sub(b)
            };
            Ok(v.map(Value::Decimal))
        }
        (Value::Timestamp(t), Value::Int(o)) => {
            let v = if up {
                t.checked_add(*o)
            } else {
                t.checked_sub(*o)
            };
            // Outside 0001..=9999 there is no canonical instant: the bound
            // covers everything up to the domain edge.
            Ok(v.filter(|ms| crate::value::is_valid_timestamp_ms(*ms))
                .map(Value::Timestamp))
        }
        _ => err("RANGE value offsets need a numeric or TIMESTAMP ORDER BY key"),
    }
}

/// Inverse of [`add_values`] for sliding-window SUM removal: the same type
/// rules mirrored (Decimal exact, Int checked, Float binary). `None` where
/// the inverse is unrecoverable (Int overflow — the batch fold NULLs there
/// too), so the caller can fall back to a fresh fold of the frame.
fn sub_values(a: Value, b: Value) -> Result<Value> {
    if matches!(a, Value::Null) || matches!(b, Value::Null) {
        return Ok(Value::Null);
    }
    if matches!(a, Value::Decimal(_)) || matches!(b, Value::Decimal(_)) {
        let (x, y) = (as_decimal(&a)?, as_decimal(&b)?);
        return Ok(x.checked_sub(y).map(Value::Decimal).unwrap_or(Value::Null));
    }
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => {
            Ok(x.checked_sub(y).map(Value::Int).unwrap_or(Value::Null))
        }
        (Value::Int(x), Value::Float(y)) => Ok(Value::Float(x as f64 - y)),
        (Value::Float(x), Value::Int(y)) => Ok(Value::Float(x - y as f64)),
        (Value::Float(x), Value::Float(y)) => Ok(Value::Float(x - y)),
        _ => err("SUM of non-numeric values"),
    }
}

/// First partition position whose ORDER BY key is at-or-after `target` in
/// sort order (`upper = false`), or strictly after it (`upper = true`). The
/// partition's keys are monotone under the sort comparator, so a plain
/// binary search applies; direction (ASC/DESC) and NULL placement ride the
/// same [`cmp_maybe_null`] the sort used.
fn window_key_search(
    keyed: &[(usize, Vec<Value>)],
    target: &Value,
    nulls_first: Option<bool>,
    asc: bool,
    upper: bool,
) -> usize {
    let pred = |v: &Value| {
        let o = cmp_maybe_null(v, target, nulls_first);
        if upper {
            if asc {
                o == Ordering::Greater
            } else {
                o == Ordering::Less
            }
        } else if asc {
            o != Ordering::Less
        } else {
            o != Ordering::Greater
        }
    };
    let (mut lo, mut hi) = (0usize, keyed.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if pred(&keyed[mid].1[0]) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    lo
}

/// Per-row frame bounds `[lo, hi]` (inclusive sorted positions) for one
/// partition. `group_spans`/`group_of` carry the peer-group layout for
/// GROUPS units. Monotone by construction — bounds only move forward as the
/// current row advances, which the sliding aggregators rely on.
fn frame_bounds(
    plan: &WindowFramePlan,
    keyed: &[(usize, Vec<Value>)],
    order_by: &[sqlparser::ast::OrderByExpr],
    group_spans: &[(usize, usize)],
    group_of: &[usize],
    n: usize,
) -> Result<Vec<(usize, usize)>> {
    let clamp = |k: u64| (k as usize).min(n);
    Ok(match plan {
        WindowFramePlan::Rows { start, end } => (0..n)
            .map(|p| {
                // `lo` may legally exceed `n - 1` (an offset frame past the
                // partition end) — that is an EMPTY frame, aggregate-of-
                // nothing, never a clamp onto the last row.
                let lo = match start {
                    FrameRowBound::Unbounded => 0,
                    FrameRowBound::Preceding(k) => p.saturating_sub(clamp(*k)),
                    FrameRowBound::CurrentRow => p,
                    FrameRowBound::Following(k) => p + clamp(*k),
                    FrameRowBound::UnboundedFollowing => n,
                };
                let hi = match end {
                    FrameRowBound::Unbounded => 0,
                    FrameRowBound::Preceding(k) => p.saturating_sub(clamp(*k)),
                    FrameRowBound::CurrentRow => p,
                    FrameRowBound::Following(k) => (p + clamp(*k)).min(n - 1),
                    FrameRowBound::UnboundedFollowing => n - 1,
                };
                (lo, hi)
            })
            .collect(),
        WindowFramePlan::Groups { start, end } => {
            let groups = group_spans.len();
            (0..n)
                .map(|p| {
                    let g = group_of[p];
                    let g_lo = match start {
                        FrameRowBound::Unbounded => 0,
                        FrameRowBound::Preceding(k) => g.saturating_sub(*k as usize),
                        FrameRowBound::CurrentRow => g,
                        FrameRowBound::Following(k) => (g + *k as usize).min(groups - 1),
                        FrameRowBound::UnboundedFollowing => groups - 1,
                    };
                    let g_hi = match end {
                        FrameRowBound::Unbounded => 0,
                        FrameRowBound::Preceding(k) => g.saturating_sub(*k as usize),
                        FrameRowBound::CurrentRow => g,
                        FrameRowBound::Following(k) => (g + *k as usize).min(groups - 1),
                        FrameRowBound::UnboundedFollowing => groups - 1,
                    };
                    let lo = if matches!(start, FrameRowBound::Following(_)) {
                        // A start past the last group: empty frame.
                        group_spans.get(g_lo).map(|s| s.0).unwrap_or(n)
                    } else {
                        group_spans[g_lo].0
                    };
                    (lo, group_spans[g_hi].1)
                })
                .collect()
        }
        WindowFramePlan::Range { start, end } => {
            if order_by.is_empty() {
                // Unordered RANGE: every row is a peer of every other, so
                // any frame covers the whole partition.
                return Ok(vec![(0, n - 1); n]);
            }
            let nf = order_by[0].options.nulls_first;
            let asc = order_by[0].options.asc.unwrap_or(true);
            let mut out = Vec::with_capacity(n);
            for p in 0..n {
                let key = &keyed[p].1[0];
                if matches!(key, Value::Null) {
                    // NULL keys have no arithmetic: the frame is their peer
                    // run (NULLs equal only NULLs, SQL semantics).
                    let lo = window_key_search(keyed, key, nf, asc, false);
                    let hi = window_key_search(keyed, key, nf, asc, true).saturating_sub(1);
                    out.push((lo, hi));
                    continue;
                }
                // PRECEDING/FOLLOWING are SORT-ORDER relative: ASC `n
                // PRECEDING` = n value units DOWN, DESC `n PRECEDING` = n
                // value units UP. The value interval [vlo, vhi] reads the
                // START bound on one side and the END bound on the other,
                // per direction; the position search then targets the
                // matching endpoint (ASC keys ascend: lo hunts vlo, hi vhi;
                // DESC keys descend: lo hunts vhi, hi vlo).
                let bound_value = |b: &FrameValueBound| -> Result<Option<Value>> {
                    match b {
                        FrameValueBound::Unbounded | FrameValueBound::UnboundedFollowing => {
                            Ok(None)
                        }
                        FrameValueBound::CurrentRow => Ok(Some(key.clone())),
                        FrameValueBound::Preceding(v) => shift_range_key(key, v, !asc),
                        FrameValueBound::Following(v) => shift_range_key(key, v, asc),
                    }
                };
                let (lo_v, hi_v) = if asc {
                    (bound_value(start)?, bound_value(end)?)
                } else {
                    (bound_value(end)?, bound_value(start)?)
                };
                let (mut lo, mut hi) = if asc {
                    (
                        match lo_v {
                            None => 0,
                            Some(t) => window_key_search(keyed, &t, nf, true, false),
                        },
                        match hi_v {
                            None => n - 1,
                            Some(t) => window_key_search(keyed, &t, nf, true, true),
                        },
                    )
                } else {
                    (
                        match hi_v {
                            None => 0,
                            Some(t) => window_key_search(keyed, &t, nf, false, false),
                        },
                        match lo_v {
                            None => n - 1,
                            Some(t) => window_key_search(keyed, &t, nf, false, true),
                        },
                    )
                };
                // `hi` is the first-strictly-after search position; the
                // inclusive end is one before it. Zero means NO key reached
                // the far endpoint: an empty frame, which the consumers read
                // as `hi < lo` — drop `hi` to 0 and push `lo` past it.
                if hi == 0 {
                    hi = 0;
                    lo = lo.max(1);
                } else {
                    hi -= 1;
                }
                out.push((lo, hi));
            }
            out
        }
    })
}

/// Build a rows result from RETURNING items over the affected documents.
fn project_returning(items: &[SelectItem], docs: &[Object]) -> Result<ExecOutcome> {
    let mut want_star = false;
    let mut columns = Vec::new();
    let mut exprs = Vec::new();
    for item in items {
        match item {
            SelectItem::Wildcard(_) => want_star = true,
            SelectItem::UnnamedExpr(e) => {
                columns.push(expr_name(e));
                exprs.push(e.clone());
            }
            SelectItem::ExprWithAlias { expr, alias, .. } => {
                columns.push(alias.value.clone());
                exprs.push(expr.clone());
            }
            _ => return err("unsupported RETURNING item"),
        }
    }
    // `RETURNING *` projects like `SELECT *`: the returned documents' field
    // union, ordered, missing fields as NULL. It used to be documented but
    // rejected here because only the expression arms were wired up.
    if want_star {
        let mut star_cols = union_of_fields(docs);
        star_cols.extend(columns);
        columns = star_cols;
    }
    let base = columns.len() - exprs.len();
    let mut rows = Vec::new();
    for doc in docs {
        let mut row = Vec::with_capacity(columns.len());
        if want_star {
            row.extend(
                columns[..base]
                    .iter()
                    .map(|c| doc.get(c).cloned().unwrap_or(Value::Null)),
            );
        }
        for e in &exprs {
            row.push(eval_expr(e, doc)?);
        }
        rows.push(row);
    }
    Ok(ExecOutcome::Rows(QueryResult { columns, rows }))
}

fn str_list(m: &Object, key: &str) -> Vec<String> {
    match m.get(key) {
        Some(Value::Array(a)) => a
            .iter()
            .filter_map(|x| x.as_str().map(String::from))
            .collect(),
        _ => vec![],
    }
}

/// Column types that declare a GUID. Values live as canonical lowercase
/// UUID strings, so string order equals UUIDv7 time order.
fn is_guid_type(dt: &sqlparser::ast::DataType) -> bool {
    let t = dt.to_string().trim().to_uppercase();
    matches!(t.as_str(), "GUID" | "UUID" | "UNIQUEIDENTIFIER" | "UUIDV7")
}

/// Reject constraint decorations the engine cannot honor instead of silently
/// dropping them (house red line). `DEFERRABLE` / `INITIALLY DEFERRED`
/// promise check-at-commit, `NOT ENFORCED` promises no checking, `NULLS NOT
/// DISTINCT` changes duplicate handling and `MATCH FULL/PARTIAL` changes null
/// treatment — all semantics this engine does not implement, so accepting
/// them would lie about what the constraint does. No-op spellings that
/// describe the existing behavior (`NOT DEFERRABLE`, `INITIALLY IMMEDIATE`,
/// `ENFORCED`, `MATCH SIMPLE`, `NULLS DISTINCT`) stay accepted.
fn reject_constraint_decorations(
    what: &str,
    characteristics: Option<&sqlparser::ast::ConstraintCharacteristics>,
    nulls_distinct: Option<&sqlparser::ast::NullsDistinctOption>,
    match_kind: Option<&sqlparser::ast::ConstraintReferenceMatchKind>,
) -> Result<()> {
    use sqlparser::ast::{
        ConstraintReferenceMatchKind as MatchKind, DeferrableInitial, NullsDistinctOption,
    };
    if let Some(ch) = characteristics {
        if ch.deferrable == Some(true) {
            return err(format!(
                "{what}: DEFERRABLE constraints are not supported (checks are immediate)"
            ));
        }
        if ch.initially == Some(DeferrableInitial::Deferred) {
            return err(format!(
                "{what}: INITIALLY DEFERRED constraints are not supported (checks are immediate)"
            ));
        }
        if ch.enforced == Some(false) {
            return err(format!(
                "{what}: NOT ENFORCED constraints are not supported (checks always run)"
            ));
        }
    }
    if matches!(nulls_distinct, Some(NullsDistinctOption::NotDistinct)) {
        return err(format!("{what}: NULLS NOT DISTINCT is not supported"));
    }
    if matches!(match_kind, Some(MatchKind::Full) | Some(MatchKind::Partial)) {
        return err(format!(
            "{what}: MATCH FULL/PARTIAL is not supported (MATCH SIMPLE semantics)"
        ));
    }
    Ok(())
}

/// SQL literal for a value carried over into a replicated statement.
pub(crate) fn value_literal(v: &Value) -> Result<String> {
    match v {
        Value::Null => Ok("NULL".into()),
        Value::Bool(b) => Ok(if *b { "TRUE" } else { "FALSE" }.into()),
        Value::Int(i) => Ok(i.to_string()),
        Value::Float(f) => {
            // Non-finite floats have no bare literal: CAST('NaN'/'inf' AS
            // REAL) parses back to the same value, so a dump or replication
            // rewrite round-trips instead of failing or degrading to Float.
            // Debug formatting keeps integral floats distinguishable from Int
            // ("3.0" vs "3"), preserving the type across resolved-INSERT
            // replay.
            if !f.is_finite() {
                return Ok(format!(
                    "CAST({} AS REAL)",
                    crate::stmt::sql_string_literal(crate::json::float_marker_text(*f))
                ));
            }
            Ok(format!("{f:?}"))
        }
        // Exact text form wrapped in a CAST: bare decimal text would re-parse
        // as Float on replay and silently lose precision.
        Value::Decimal(d) => Ok(format!(
            "CAST({} AS DECIMAL)",
            crate::stmt::sql_string_literal(&d.to_string())
        )),
        Value::Bytes(b) => {
            let mut hex = String::with_capacity(b.len() * 2 + 3);
            hex.push_str("x'");
            for byte in b {
                hex.push_str(&format!("{byte:02x}"));
            }
            hex.push('\'');
            Ok(hex)
        }
        Value::Str(s) => Ok(crate::stmt::sql_string_literal(s)),
        // TIMESTAMP '…' form: bare ISO text would re-parse as Str on replay.
        Value::Timestamp(ms) => {
            // Construction sites keep Timestamps inside 0001..=9999, but a
            // legacy volume written before that guard could still hold an
            // out-of-domain instant — fail the DUMP loudly here instead of
            // emitting a literal the restore would reject half-way through.
            if !crate::value::is_valid_timestamp_ms(*ms) {
                return err(format!(
                    "TIMESTAMP value {ms} is outside 0001-01-01..=9999-12-31 and cannot be dumped"
                ));
            }
            Ok(format!(
                "CAST({} AS TIMESTAMP)",
                crate::stmt::sql_string_literal(&crate::value::format_timestamp_ms(*ms))
            ))
        }
        // Structured values (JSON_EXTRACT output, INSERT ... SELECT from a
        // JSON function, etc.) have no literal syntax in this dialect: the
        // engine's canonical JSON text wrapped in JSON_EXTRACT round-trips
        // exactly (including `$dec`/`$bytes`/`$float` markers), so backups
        // and join snapshots can carry them.
        Value::Array(_) | Value::Object(_) => Ok(format!(
            "JSON_EXTRACT({})",
            crate::stmt::sql_string_literal(&crate::json::to_string(v))
        )),
    }
}

/// Canonical text for a stored DEFAULT expression. sqlparser keeps
/// redundant parentheses as `Expr::Nested`, so `DEFAULT ('anon')` from a
/// replayed dump would otherwise be stored as `('anon')` and grow one
/// layer per dump/restore cycle — silently poisoning `schema_hash` and
/// permanently degrading digest equality (every rejoin falls back to a
/// snapshot). Strip the nesting so the stored form is a fixed point of
/// dump → parse → store.
fn default_expr_text(e: &SqlExpr) -> String {
    match e {
        SqlExpr::Nested(inner) => default_expr_text(inner),
        _ => format!("{e}"),
    }
}

/// Double-quoted SQL identifier.
fn quote_ident(name: &str) -> String {
    crate::stmt::sql_quote_ident(name)
}

/// Views reject every write and every schema change: they are named SELECTs
/// with no storage. The guard names the offending kind explicitly (SQLite:
/// "cannot modify X because it is a view").
fn ensure_not_view(kind: &str, table: &str, meta: &TableMeta) -> Result<()> {
    if meta.is_view() {
        return Err(SqlError::Message(format!(
            "cannot {kind} view {table} (it is a view, not a table)"
        )));
    }
    if meta.is_matview() {
        return Err(SqlError::Message(format!(
            "cannot {kind} materialized view {table} (it is refreshed, not written: \
             REFRESH MATERIALIZED VIEW {table})"
        )));
    }
    Ok(())
}

/// Leaf table name of an ObjectName (last part). Crate-internal callers
/// use [`obj_name`]; the server's row-filter rewrite reaches it through
/// [`table_ref_name`].
pub fn table_ref_name(name: &ObjectName) -> String {
    obj_name(name)
}

fn obj_name(name: &ObjectName) -> String {
    name.0
        .last()
        .map(|p| match p {
            ObjectNamePart::Identifier(i) => i.value.clone(),
            other => other.to_string(),
        })
        .unwrap_or_default()
}

/// Which event a [`Database::fire_row_triggers`] call is firing for; the
/// UPDATE arm carries the columns the statement assigns (UPDATE OF gating).
enum TriggerFireEvent<'a> {
    Insert,
    Delete,
    Update(Option<&'a [String]>),
}

/// Target table of a DML statement, for the trigger statement guard in
/// [`Database::exec_stmt`]. `None` for shapes the guard does not cover
/// (multi-table FROM lists etc. — those never had row images to fire over).
fn trigger_dml_target(stmt: &Statement) -> Option<String> {
    match stmt {
        Statement::Insert(i) => match &i.table {
            sqlparser::ast::TableObject::TableName(n) => Some(obj_name(n)),
            _ => None,
        },
        Statement::Update(u) => match &u.table.relation {
            sqlparser::ast::TableFactor::Table { name, .. } => Some(obj_name(name)),
            _ => None,
        },
        Statement::Delete(d) => match &d.from {
            sqlparser::ast::FromTable::WithFromKeyword(twjs) => {
                twjs.first().and_then(|t| match &t.relation {
                    sqlparser::ast::TableFactor::Table { name, .. } => Some(obj_name(name)),
                    _ => None,
                })
            }
            sqlparser::ast::FromTable::WithoutKeyword(_) => None,
        },
        Statement::Merge(m) => match &m.table {
            sqlparser::ast::TableFactor::Table { name, .. } => Some(obj_name(name)),
            _ => None,
        },
        _ => None,
    }
}

/// WHEN validation: only NEW./OLD. references over literals and operators.
/// An unqualified column would silently read NULL (schemaless semantics)
/// and skip every firing — refuse instead.
fn validate_trigger_when(e: &SqlExpr) -> Result<()> {
    match e {
        SqlExpr::Identifier(_) => err(
            "WHEN must reference columns as NEW.col / OLD.col (an unqualified name would read NULL)",
        ),
        SqlExpr::CompoundIdentifier(parts) => {
            let head = parts
                .first()
                .map(|p| p.value.to_ascii_uppercase())
                .unwrap_or_default();
            if head != "NEW" && head != "OLD" {
                return err("WHEN must reference columns as NEW.col / OLD.col");
            }
            Ok(())
        }
        SqlExpr::Subquery(_) | SqlExpr::Exists { .. } | SqlExpr::InSubquery { .. } => {
            err("subqueries are not supported in a trigger WHEN clause")
        }
        SqlExpr::Nested(e) => validate_trigger_when(e),
        SqlExpr::UnaryOp { expr, .. } => validate_trigger_when(expr),
        SqlExpr::BinaryOp { left, right, .. } => {
            validate_trigger_when(left)?;
            validate_trigger_when(right)
        }
        SqlExpr::Between { expr, low, high, .. } => {
            validate_trigger_when(expr)?;
            validate_trigger_when(low)?;
            validate_trigger_when(high)
        }
        SqlExpr::InList { expr, list, .. } => {
            validate_trigger_when(expr)?;
            for item in list {
                validate_trigger_when(item)?;
            }
            Ok(())
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            validate_trigger_when(l)?;
            validate_trigger_when(r)
        }
        SqlExpr::IsNull(e) | SqlExpr::IsNotNull(e) => validate_trigger_when(e),
        SqlExpr::Cast { expr, .. } => validate_trigger_when(expr),
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            validate_trigger_when(expr)?;
            validate_trigger_when(pattern)
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                validate_trigger_when(o)?;
            }
            for w in conditions {
                validate_trigger_when(&w.condition)?;
                validate_trigger_when(&w.result)?;
            }
            if let Some(r) = else_result {
                validate_trigger_when(r)?;
            }
            Ok(())
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        validate_trigger_when(inner)?;
                    }
                }
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

/// Recognize the trigger-body `SELECT RAISE(ABORT|FAIL, 'msg')` statement
/// (SQLite spelling). Everything else in a SELECT-shaped body is refused —
/// a bare SELECT has no effect in a trigger body and only ever meant
/// RAISE here.
fn raise_action(q: &sqlparser::ast::Query) -> Result<TriggerAction> {
    if q.with.is_some() || !q.limit_clause.is_none() || !matches!(&*q.body, SetExpr::Select(_)) {
        return err(
            "only SELECT RAISE(ABORT|FAIL, 'msg') is supported in trigger bodies (other SELECTs have no effect)",
        );
    }
    let SetExpr::Select(sel) = &*q.body else {
        unreachable!("checked above");
    };
    if !sel.from.is_empty() || sel.selection.is_some() {
        return err("RAISE must be a plain SELECT RAISE(ABORT|FAIL, 'msg') (no FROM / WHERE)");
    }
    if sel.projection.len() != 1 {
        return err("RAISE takes exactly one projection");
    }
    let sqlparser::ast::SelectItem::UnnamedExpr(SqlExpr::Function(f)) = &sel.projection[0] else {
        return err("only SELECT RAISE(ABORT|FAIL, 'msg') is supported in trigger bodies");
    };
    if !f.name.to_string().eq_ignore_ascii_case("RAISE") {
        return err("only SELECT RAISE(ABORT|FAIL, 'msg') is supported in trigger bodies");
    }
    let list = match &f.args {
        sqlparser::ast::FunctionArguments::List(l) => l,
        _ => return err("RAISE requires (ABORT|FAIL, 'message')"),
    };
    if list.args.len() != 2 {
        return err(
            "RAISE(IGNORE)/RAISE(ROLLBACK) are not supported — use RAISE(ABORT|FAIL, 'message')",
        );
    }
    let kind = match &list.args[0] {
        sqlparser::ast::FunctionArg::Unnamed(sqlparser::ast::FunctionArgExpr::Expr(
            SqlExpr::Identifier(i),
        )) => i.value.to_ascii_uppercase(),
        _ => {
            return err("RAISE first argument must be ABORT or FAIL");
        }
    };
    if kind != "ABORT" && kind != "FAIL" {
        return err(format!(
            "RAISE({kind}) is not supported (use ABORT or FAIL; DocSQL statements are \
             atomic so both roll the statement back — IGNORE/ROLLBACK have no separate effect)"
        ));
    }
    let msg = match &list.args[1] {
        sqlparser::ast::FunctionArg::Unnamed(sqlparser::ast::FunctionArgExpr::Expr(
            SqlExpr::Value(v),
        )) => match &v.value {
            sqlparser::ast::Value::SingleQuotedString(s) => s.clone(),
            _ => return err("RAISE message must be a string literal"),
        },
        _ => return err("RAISE message must be a string literal"),
    };
    Ok(TriggerAction::Raise {
        fail: kind == "FAIL",
        msg,
    })
}

/// Substitute NEW.col / OLD.col references with the row image's values
/// (recursively through the expression shapes a trigger body uses).
/// References to the image the event does not have (NEW on DELETE, OLD on
/// INSERT — SQLite semantics) read NULL.
fn subst_new_old_expr(e: &mut SqlExpr, old: Option<&Object>, new: Option<&Object>) -> Result<()> {
    match e {
        SqlExpr::CompoundIdentifier(parts)
            if parts.len() >= 2
                && matches!(parts[0].value.to_ascii_uppercase().as_str(), "NEW" | "OLD") =>
        {
            let head = parts[0].value.to_ascii_uppercase();
            let leaf = parts.last().map(|p| p.value.clone()).unwrap_or_default();
            let img = match (head.as_str(), old, new) {
                ("NEW", _, Some(n)) => n,
                ("OLD", Some(o), _) => o,
                _ => {
                    // No such image for this event: NULL, like SQLite.
                    *e = value_to_literal(Value::Null)?;
                    return Ok(());
                }
            };
            let v = img.get(&leaf).cloned().unwrap_or(Value::Null);
            *e = value_to_literal(v)?;
        }
        SqlExpr::Nested(inner) => subst_new_old_expr(inner, old, new)?,
        SqlExpr::UnaryOp { expr, .. } => subst_new_old_expr(expr, old, new)?,
        SqlExpr::BinaryOp { left, right, .. } => {
            subst_new_old_expr(left, old, new)?;
            subst_new_old_expr(right, old, new)?;
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            subst_new_old_expr(expr, old, new)?;
            subst_new_old_expr(low, old, new)?;
            subst_new_old_expr(high, old, new)?;
        }
        SqlExpr::InList { expr, list, .. } => {
            subst_new_old_expr(expr, old, new)?;
            for item in list {
                subst_new_old_expr(item, old, new)?;
            }
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            subst_new_old_expr(l, old, new)?;
            subst_new_old_expr(r, old, new)?;
        }
        SqlExpr::IsNull(e) | SqlExpr::IsNotNull(e) => subst_new_old_expr(e, old, new)?,
        SqlExpr::Cast { expr, .. } => subst_new_old_expr(expr, old, new)?,
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            subst_new_old_expr(expr, old, new)?;
            subst_new_old_expr(pattern, old, new)?;
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                subst_new_old_expr(o, old, new)?;
            }
            for w in conditions {
                subst_new_old_expr(&mut w.condition, old, new)?;
                subst_new_old_expr(&mut w.result, old, new)?;
            }
            if let Some(r) = else_result {
                subst_new_old_expr(r, old, new)?;
            }
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &mut f.args {
                for a in &mut list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        subst_new_old_expr(inner, old, new)?;
                    }
                }
            }
        }
        // Subquery interiors are NOT substituted — a NEW./OLD. that
        // survived down there is caught by the literal-skipping scan on the
        // rendered text (loud error, never a silent NULL read).
        _ => {}
    }
    Ok(())
}

/// Apply [`subst_new_old_expr`] over a trigger body statement's expression
/// surfaces (INSERT VALUES / upsert arm, UPDATE SET + WHERE, DELETE WHERE).
fn subst_new_old_stmt(
    stmt: &mut Statement,
    old: Option<&Object>,
    new: Option<&Object>,
) -> Result<()> {
    match stmt {
        Statement::Insert(i) => {
            if let Some(q) = &mut i.source {
                if let SetExpr::Values(v) = &mut *q.body {
                    for row in &mut v.rows {
                        for e in row.content.iter_mut() {
                            subst_new_old_expr(e, old, new)?;
                        }
                    }
                }
            }
            if let Some(sqlparser::ast::OnInsert::OnConflict(c)) = &mut i.on {
                if let sqlparser::ast::OnConflictAction::DoUpdate(du) = &mut c.action {
                    for a in &mut du.assignments {
                        subst_new_old_expr(&mut a.value, old, new)?;
                    }
                    if let Some(sel) = &mut du.selection {
                        subst_new_old_expr(sel, old, new)?;
                    }
                }
            }
        }
        Statement::Update(u) => {
            for a in &mut u.assignments {
                subst_new_old_expr(&mut a.value, old, new)?;
            }
            if let Some(s) = &mut u.selection {
                subst_new_old_expr(s, old, new)?;
            }
        }
        Statement::Delete(d) => {
            if let Some(s) = &mut d.selection {
                subst_new_old_expr(s, old, new)?;
            }
        }
        _ => {}
    }
    Ok(())
}

/// True when the rendered statement still carries a NEW. / OLD. reference
/// outside a string literal — the catch-all for substitution walkers that
/// deliberately do not descend into subqueries. Quote-aware via
/// [`crate::stmt::sql_literal_end`] so a literal mentioning "NEW." never
/// false-positives.
fn text_has_trigger_ref_outside_literals(sql: &str) -> bool {
    let bytes = sql.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\'' => {
                let (end, _) = crate::stmt::sql_literal_end(sql, i);
                i = end;
            }
            b'"' | b'`' => {
                let q = bytes[i];
                i += 1;
                while i < bytes.len() {
                    if bytes[i] == q {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
            }
            b'N' | b'n' | b'O' | b'o' => {
                let word_start =
                    i > 0 && (bytes[i - 1].is_ascii_alphanumeric() || bytes[i - 1] == b'_');
                if !word_start
                    && i + 4 <= bytes.len()
                    && (sql[i..i + 3].eq_ignore_ascii_case("new")
                        || sql[i..i + 3].eq_ignore_ascii_case("old"))
                    && bytes[i + 3] == b'.'
                {
                    return true;
                }
                i += 1;
            }
            _ => i += 1,
        }
    }
    false
}

/// Canonical CREATE TRIGGER text for a stored definition (dump/join
/// snapshots). Body statements re-emit verbatim (they were stored from the
/// parsed AST's own rendering), so replay parses exactly what was accepted.
fn create_trigger_sql(d: &TriggerDef) -> String {
    use std::fmt::Write as _;
    let mut s = String::new();
    let _ = write!(
        s,
        "CREATE TRIGGER {} {} {} ON {} ",
        crate::stmt::sql_quote_ident(&d.name),
        if d.before { "BEFORE" } else { "AFTER" },
        if d.insert {
            "INSERT".to_string()
        } else if d.delete {
            "DELETE".to_string()
        } else {
            match &d.update_of {
                Some(cols) => format!(
                    "UPDATE OF {}",
                    cols.iter()
                        .map(|c| crate::stmt::sql_quote_ident(c))
                        .collect::<Vec<_>>()
                        .join(", ")
                ),
                None => "UPDATE".to_string(),
            }
        },
        crate::stmt::sql_quote_ident(&d.table)
    );
    if let Some(w) = &d.when {
        let _ = write!(s, "WHEN {w} ");
    }
    s.push_str("BEGIN ");
    for a in &d.body {
        match a {
            TriggerAction::Sql(text) => {
                s.push_str(text.trim_end().trim_end_matches(';'));
                s.push_str("; ");
            }
            TriggerAction::Raise { fail, msg } => {
                let _ = write!(
                    s,
                    "SELECT RAISE({}, {}); ",
                    if *fail { "FAIL" } else { "ABORT" },
                    crate::stmt::sql_string_literal(msg)
                );
            }
        }
    }
    s.push_str("END");
    s
}

fn expr_name(e: &SqlExpr) -> String {
    match e {
        SqlExpr::Identifier(i) => i.value.clone(),
        SqlExpr::CompoundIdentifier(parts) => parts
            .iter()
            .map(|p| p.value.clone())
            .collect::<Vec<_>>()
            .join("."),
        other => other.to_string(),
    }
}

/// Column references of a CHECK constraint expression (bare identifiers and
/// the leaf of qualified names). Subqueries are rejected outright — the
/// runtime evaluator resolves unknown columns to NULL, so without this DDL
/// gate a typo'd CHECK would be created and never fire.
fn check_expr_column_refs(e: &SqlExpr, out: &mut Vec<String>) -> Result<()> {
    use SqlExpr::*;
    match e {
        Identifier(i) => {
            out.push(i.value.clone());
            Ok(())
        }
        CompoundIdentifier(parts) => {
            if let Some(last) = parts.last() {
                out.push(last.value.clone());
            }
            Ok(())
        }
        Value(_) | TypedString { .. } => Ok(()),
        Nested(i) | IsNull(i) | IsNotNull(i) | Cast { expr: i, .. } => {
            check_expr_column_refs(i, out)
        }
        UnaryOp { expr, .. } => check_expr_column_refs(expr, out),
        BinaryOp { left, right, .. } => {
            check_expr_column_refs(left, out)?;
            check_expr_column_refs(right, out)
        }
        IsDistinctFrom(a, b) | IsNotDistinctFrom(a, b) => {
            check_expr_column_refs(a, out)?;
            check_expr_column_refs(b, out)
        }
        Between {
            expr, low, high, ..
        } => {
            check_expr_column_refs(expr, out)?;
            check_expr_column_refs(low, out)?;
            check_expr_column_refs(high, out)
        }
        Like { expr, pattern, .. } | ILike { expr, pattern, .. } => {
            check_expr_column_refs(expr, out)?;
            check_expr_column_refs(pattern, out)
        }
        InList { expr, list, .. } => {
            check_expr_column_refs(expr, out)?;
            for item in list {
                check_expr_column_refs(item, out)?;
            }
            Ok(())
        }
        Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                check_expr_column_refs(o, out)?;
            }
            for w in conditions {
                check_expr_column_refs(&w.condition, out)?;
                check_expr_column_refs(&w.result, out)?;
            }
            if let Some(r) = else_result {
                check_expr_column_refs(r, out)?;
            }
            Ok(())
        }
        Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        check_expr_column_refs(inner, out)?;
                    }
                }
            }
            Ok(())
        }
        Subquery(_) | Exists { .. } | InSubquery { .. } => {
            err("CHECK constraints cannot contain subqueries")
        }
        _ => Ok(()),
    }
}

/// Encoded identity of a document (UPDATE ... FROM / DELETE ... USING match
/// target rows by content).
fn object_key(doc: &Object) -> Vec<u8> {
    let mut out = Vec::new();
    match encode::encode_object(doc, &mut out) {
        Ok(()) => out,
        Err(_) => Vec::new(),
    }
}

/// Rebuild a target table's document from its qualified slice of a merged
/// FROM row (UPDATE ... FROM / DELETE ... USING).
fn target_doc_from_merged(m: &Object, prefix: &str) -> Object {
    let mut tdoc = Object::new();
    for (k, v) in m {
        if let Some(col) = k.strip_prefix(prefix) {
            tdoc.insert(col.to_string(), v.clone());
        }
    }
    tdoc
}

/// Evaluate SET assignments against the pre-update image and return them as
/// (column, value) pairs. SQL binds every right-hand side before any column
/// is written: in `SET a = a + 1, b = a`, `b` must observe the old `a`.
fn eval_assignments(
    assignments: &[sqlparser::ast::Assignment],
    doc: &Object,
) -> Result<Vec<(String, Value)>> {
    assignments
        .iter()
        .map(|a| {
            let sqlparser::ast::AssignmentTarget::ColumnName(col) = &a.target else {
                return err("unsupported assignment target");
            };
            Ok((obj_name(col), eval_expr(&a.value, doc)?))
        })
        .collect()
}

/// Replace identifier `old` with `new` in SQL text, matching whole
/// identifiers only (adjacent identifier characters disqualify the match).
/// String literals are copied through verbatim — a CHECK like
/// `name <> 'name'` must not have its *literal* rewritten when the column
/// `name` is renamed, or the constraint silently changes meaning. Walks char
/// boundaries — a byte walk would panic slicing into a multibyte identifier,
/// and non-ASCII chars count as identifier characters so the `a` inside
/// `éa` can never match.
/// Replacement spelling for a renamed identifier inside stored SQL text
/// (CHECK expressions): bare when the name is a plain word, quoted (with
/// `""` escaping) otherwise — a `"` in the new name must not break the
/// lexical structure of the stored text (dump replays it verbatim).
fn ident_spelling(name: &str) -> String {
    let plain = !name.is_empty()
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$');
    if plain {
        name.to_string()
    } else {
        crate::stmt::sql_quote_ident(name)
    }
}

fn rename_ident_in_text(text: &str, old: &str, new: &str) -> String {
    fn is_word(c: char) -> bool {
        !c.is_ascii() || c.is_ascii_alphanumeric() || c == '_' || c == '$'
    }
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let old_chars = old.chars().count();
    let mut out = String::with_capacity(text.len());
    let mut i = 0;
    while i < chars.len() {
        let (byte_i, c) = chars[i];
        if c == '\'' {
            // Copy the literal span untouched (same scanner the bind/redact/
            // lexing paths share — never a hand-rolled replacement walk).
            let (end, _) = crate::stmt::sql_literal_end(text, byte_i);
            out.push_str(&text[byte_i..end]);
            i += text[byte_i..end].chars().count();
            continue;
        }
        let prev_word = i > 0 && is_word(chars[i - 1].1);
        let next_word = chars
            .get(i + old_chars)
            .copied()
            .map(|(_, c2)| is_word(c2))
            .unwrap_or(false);
        if !prev_word && !next_word && text[byte_i..].starts_with(old) {
            out.push_str(new);
            i += old_chars;
        } else {
            out.push(c);
            i += 1;
        }
    }
    out
}

/// Literal-aware word-boundary test: does `name` occur as a bare identifier
/// outside string literals? Dependency checks over stored SQL text that a
/// full parse-walk is not worth it — a false positive only over-refuses a
/// DDL, a false negative would silently degrade a view. Same char-boundary
/// walk (and word rule) as [`rename_ident_in_text`].
fn text_references_ident(text: &str, name: &str) -> bool {
    fn is_word(c: char) -> bool {
        !c.is_ascii() || c.is_ascii_alphanumeric() || c == '_' || c == '$'
    }
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let name_chars = name.chars().count();
    let mut i = 0;
    while i < chars.len() {
        let (byte_i, c) = chars[i];
        if c == '\'' {
            let (end, _) = crate::stmt::sql_literal_end(text, byte_i);
            i += text[byte_i..end].chars().count();
            continue;
        }
        let prev_word = i > 0 && is_word(chars[i - 1].1);
        let next_word = chars
            .get(i + name_chars)
            .copied()
            .map(|(_, c2)| is_word(c2))
            .unwrap_or(false);
        if !prev_word && !next_word && text[byte_i..].starts_with(name) {
            return true;
        }
        i += 1;
    }
    false
}

/// Collect the table names and aliases a query reads in its own FROM, so
/// qualified references to anything else can be flagged as correlated.
fn collect_from_names(q: &Query, out: &mut std::collections::BTreeSet<String>) {
    collect_setexpr_from_names(&q.body, out);
}

/// FROM names of a subquery body, recursing through set-operation arms and
/// nested query bodies — a body-level Select-only scan collected nothing
/// for `SELECT … FROM a UNION SELECT … FROM b`, making every qualified arm
/// reference look correlated.
fn collect_setexpr_from_names(
    body: &sqlparser::ast::SetExpr,
    out: &mut std::collections::BTreeSet<String>,
) {
    use sqlparser::ast::SetExpr;
    match body {
        SetExpr::Select(sel) => from_list_names(&sel.from, out),
        SetExpr::SetOperation { left, right, .. } => {
            collect_setexpr_from_names(left, out);
            collect_setexpr_from_names(right, out);
        }
        SetExpr::Query(inner) => collect_setexpr_from_names(&inner.body, out),
        _ => {}
    }
}

/// FROM names + aliases of a FROM list — the qualifiers legal at that query
/// level, and the outer scope a correlated subquery may reference.
fn from_list_names(from: &[sqlparser::ast::TableWithJoins], out: &mut OuterFrom) {
    for twj in from {
        if let sqlparser::ast::TableFactor::Table { name, alias, .. } = &twj.relation {
            out.insert(obj_name(name));
            if let Some(a) = alias {
                out.insert(a.name.value.clone());
            }
        }
        // Joined tables are inner-scope names too: a reference to them
        // from inside the subquery is NOT a correlation (the old
        // base-relation-only scan misrejected legitimate subqueries).
        for j in &twj.joins {
            if let sqlparser::ast::TableFactor::Table { name, alias, .. } = &j.relation {
                out.insert(obj_name(name));
                if let Some(a) = alias {
                    out.insert(a.name.value.clone());
                }
            }
        }
    }
}

/// The outer scope of a query level: its FROM names and aliases. A
/// correlated subquery's outer references must be qualified with one of
/// these (`alias.col` / `table.col`); unqualified outer references stay
/// out of scope on purpose — in a schemaless engine "inner doc lacks the
/// field" and "outer column" are indistinguishable, so binding misses to
/// the outer row would silently change sparse-document semantics.
type OuterFrom = std::collections::BTreeSet<String>;

/// Does `e` contain a subquery-bearing node anywhere (the shapes the
/// pre-pass resolves)? Row-local sites use this to decide whether the
/// per-row correlated pass must run.
fn expr_has_subquery(e: &SqlExpr) -> bool {
    match e {
        SqlExpr::Subquery(_)
        | SqlExpr::InSubquery { .. }
        | SqlExpr::Exists { .. }
        | SqlExpr::AnyOp { .. }
        | SqlExpr::AllOp { .. } => true,
        SqlExpr::BinaryOp { left, right, .. } => {
            expr_has_subquery(left) || expr_has_subquery(right)
        }
        SqlExpr::UnaryOp { expr, .. } => expr_has_subquery(expr),
        SqlExpr::Nested(inner) => expr_has_subquery(inner),
        SqlExpr::Between {
            expr, low, high, ..
        } => expr_has_subquery(expr) || expr_has_subquery(low) || expr_has_subquery(high),
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            expr_has_subquery(l) || expr_has_subquery(r)
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            expr_has_subquery(expr) || expr_has_subquery(pattern)
        }
        SqlExpr::InList { expr, list, .. } => {
            expr_has_subquery(expr) || list.iter().any(expr_has_subquery)
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand.as_deref().is_some_and(expr_has_subquery)
                || conditions
                    .iter()
                    .any(|w| expr_has_subquery(&w.condition) || expr_has_subquery(&w.result))
                || else_result.as_deref().is_some_and(expr_has_subquery)
        }
        SqlExpr::Cast { expr, .. } => expr_has_subquery(expr),
        SqlExpr::Function(_) => child_exprs(e).into_iter().any(expr_has_subquery),
        // Shared traversal: a subquery under a wrapper node (FLOOR/IS
        // NULL/SUBSTRING/…) must be seen here so the pre-pass can resolve
        // it instead of erroring at row level.
        _ => child_exprs(e).into_iter().any(expr_has_subquery),
    }
}

/// Conservative correlation probe: any qualified reference in `e` whose
/// qualifier belongs to `outer`. Deliberately ignores inner-FROM shadowing
/// — a false positive only routes the node through the per-row path (the
/// substitution itself scopes precisely), while a false negative would
/// silently read the outer column as NULL.
fn expr_mentions_outer(e: &SqlExpr, outer: &OuterFrom) -> bool {
    match e {
        SqlExpr::CompoundIdentifier(parts) => parts.len() >= 2 && outer.contains(&parts[0].value),
        SqlExpr::Subquery(q) => query_mentions_outer(q, outer),
        SqlExpr::InSubquery { expr, subquery, .. } => {
            expr_mentions_outer(expr, outer) || query_mentions_outer(subquery, outer)
        }
        SqlExpr::Exists { subquery, .. } => query_mentions_outer(subquery, outer),
        SqlExpr::AnyOp { left, right, .. } | SqlExpr::AllOp { left, right, .. } => {
            expr_mentions_outer(left, outer) || expr_mentions_outer(right, outer)
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            expr_mentions_outer(left, outer) || expr_mentions_outer(right, outer)
        }
        SqlExpr::UnaryOp { expr, .. } => expr_mentions_outer(expr, outer),
        SqlExpr::Nested(inner) => expr_mentions_outer(inner, outer),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            expr_mentions_outer(expr, outer)
                || expr_mentions_outer(low, outer)
                || expr_mentions_outer(high, outer)
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            expr_mentions_outer(l, outer) || expr_mentions_outer(r, outer)
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            expr_mentions_outer(expr, outer) || expr_mentions_outer(pattern, outer)
        }
        SqlExpr::InList { expr, list, .. } => {
            expr_mentions_outer(expr, outer) || list.iter().any(|e| expr_mentions_outer(e, outer))
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(|o| expr_mentions_outer(o, outer))
                || conditions.iter().any(|w| {
                    expr_mentions_outer(&w.condition, outer)
                        || expr_mentions_outer(&w.result, outer)
                })
                || else_result
                    .as_deref()
                    .is_some_and(|o| expr_mentions_outer(o, outer))
        }
        SqlExpr::Cast { expr, .. } => expr_mentions_outer(expr, outer),
        SqlExpr::Function(_) => child_exprs(e)
            .into_iter()
            .any(|c| expr_mentions_outer(c, outer)),
        // Shared traversal: an outer reference under a wrapper node
        // (FLOOR/IS NULL/SUBSTRING/…) is still correlated — missing it
        // would silently resolve the subquery once with NULL outer values.
        _ => child_exprs(e)
            .into_iter()
            .any(|c| expr_mentions_outer(c, outer)),
    }
}

/// `expr_mentions_outer` over a query: every surface that evaluates in the
/// query's own scope (mirrors `collect_correlated_in_body` plus ORDER BY).
fn query_mentions_outer(q: &Query, outer: &OuterFrom) -> bool {
    if let Some(w) = &q.with {
        for cte in &w.cte_tables {
            if query_mentions_outer(&cte.query, outer) {
                return true;
            }
        }
    }
    if body_mentions_outer(&q.body, outer) {
        return true;
    }
    if let Some(ob) = &q.order_by {
        if let sqlparser::ast::OrderByKind::Expressions(exprs) = &ob.kind {
            if exprs.iter().any(|o| expr_mentions_outer(&o.expr, outer)) {
                return true;
            }
        }
    }
    false
}

fn body_mentions_outer(body: &sqlparser::ast::SetExpr, outer: &OuterFrom) -> bool {
    use sqlparser::ast::SetExpr;
    match body {
        SetExpr::Select(sel) => {
            for twj in &sel.from {
                for j in &twj.joins {
                    if let Some(e) = join_on_expr(&j.join_operator) {
                        if expr_mentions_outer(e, outer) {
                            return true;
                        }
                    }
                }
            }
            if sel
                .selection
                .as_ref()
                .is_some_and(|e| expr_mentions_outer(e, outer))
            {
                return true;
            }
            if sel
                .having
                .as_ref()
                .is_some_and(|e| expr_mentions_outer(e, outer))
            {
                return true;
            }
            if let sqlparser::ast::GroupByExpr::Expressions(es, _) = &sel.group_by {
                if es.iter().any(|e| expr_mentions_outer(e, outer)) {
                    return true;
                }
            }
            sel.projection.iter().any(|item| match item {
                sqlparser::ast::SelectItem::UnnamedExpr(e)
                | sqlparser::ast::SelectItem::ExprWithAlias { expr: e, .. } => {
                    expr_mentions_outer(e, outer)
                }
                _ => false,
            })
        }
        SetExpr::SetOperation { left, right, .. } => {
            body_mentions_outer(left, outer) || body_mentions_outer(right, outer)
        }
        SetExpr::Query(inner) => query_mentions_outer(inner, outer),
        SetExpr::Values(rows) => rows
            .rows
            .iter()
            .flat_map(|parens| parens.content.iter())
            .any(|e| expr_mentions_outer(e, outer)),
        _ => false,
    }
}

/// The subquery payload of a subquery-bearing node (`Subquery`,
/// `InSubquery`, `Exists`, `ANY/ALL right side), for per-row outer-ref
/// substitution.
fn subquery_of_mut(e: &mut SqlExpr) -> Option<&mut Query> {
    match e {
        SqlExpr::Subquery(q) => Some(q),
        SqlExpr::InSubquery { subquery, .. } => Some(subquery),
        SqlExpr::Exists { subquery, .. } => Some(subquery),
        SqlExpr::AnyOp { right, .. } | SqlExpr::AllOp { right, .. } => match right.as_mut() {
            SqlExpr::Subquery(q) => Some(q),
            _ => None,
        },
        _ => None,
    }
}

/// Outer-row value for a correlated reference: the enclosing row carries
/// `alias.col` keys when joined, bare `col` keys for a solo base table —
/// the same resolution conventions `eval_expr` applies to the outer query
/// itself. A missing column reads as NULL (schemaless semantics).
fn outer_row_value(doc: &Object, qualifier: &str, rest: &[sqlparser::ast::Ident]) -> Value {
    let rest = rest
        .iter()
        .map(|i| i.value.as_str())
        .collect::<Vec<_>>()
        .join(".");
    let full = format!("{qualifier}.{rest}");
    // Only a genuinely MISSING qualified key falls back to the bare name
    // (solo-table rows carry bare keys). `lookup_col` cannot tell an
    // explicit NULL from a missing column — both are Ok(Null) — so routing
    // Ok(Null) through the fallback let a joined row's explicit
    // `alias.col = NULL` resolve to a DIFFERENT alias's same-named column
    // in correlated subqueries.
    match doc.get(&full) {
        Some(v) => v.clone(),
        None => lookup_col(doc, &rest).unwrap_or(Value::Null),
    }
}

/// Substitute outer references in `e` with literals from the enclosing row
/// `doc`. Precise SQL scoping: names in `shadow` (the inner FROM names at
/// this nesting level) win over `outer`. Returns true when at least one
/// reference was substituted.
fn subst_outer_refs_expr(
    e: &mut SqlExpr,
    shadow: &OuterFrom,
    outer: &OuterFrom,
    doc: &Object,
) -> bool {
    let mut hit = false;
    match e {
        SqlExpr::CompoundIdentifier(parts) if parts.len() >= 2 => {
            let qualifier = parts[0].value.clone();
            if !shadow.contains(&qualifier) && outer.contains(&qualifier) {
                let v = outer_row_value(doc, &qualifier, &parts[1..]);
                hit = true;
                *e = match value_to_literal(v) {
                    Ok(lit) => lit,
                    // Only exotic values fail to render (out-of-domain
                    // timestamps); NULL is the honest row-local answer.
                    Err(_) => SqlExpr::Value(sqlparser::ast::Value::Null.into()),
                };
            }
        }
        SqlExpr::Subquery(q) => {
            hit = subst_outer_refs_query(q, shadow, outer, doc);
        }
        SqlExpr::InSubquery { expr, subquery, .. } => {
            hit = subst_outer_refs_expr(expr, shadow, outer, doc);
            hit |= subst_outer_refs_query(subquery, shadow, outer, doc);
        }
        SqlExpr::Exists { subquery, .. } => {
            hit = subst_outer_refs_query(subquery, shadow, outer, doc);
        }
        SqlExpr::AnyOp { left, right, .. } | SqlExpr::AllOp { left, right, .. } => {
            hit = subst_outer_refs_expr(left, shadow, outer, doc);
            hit |= subst_outer_refs_expr(right, shadow, outer, doc);
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            hit = subst_outer_refs_expr(left, shadow, outer, doc);
            hit |= subst_outer_refs_expr(right, shadow, outer, doc);
        }
        SqlExpr::UnaryOp { expr, .. } => hit = subst_outer_refs_expr(expr, shadow, outer, doc),
        SqlExpr::Nested(inner) => hit = subst_outer_refs_expr(inner, shadow, outer, doc),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            hit = subst_outer_refs_expr(expr, shadow, outer, doc);
            hit |= subst_outer_refs_expr(low, shadow, outer, doc);
            hit |= subst_outer_refs_expr(high, shadow, outer, doc);
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            hit = subst_outer_refs_expr(l, shadow, outer, doc);
            hit |= subst_outer_refs_expr(r, shadow, outer, doc);
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            hit = subst_outer_refs_expr(expr, shadow, outer, doc);
            hit |= subst_outer_refs_expr(pattern, shadow, outer, doc);
        }
        SqlExpr::InList { expr, list, .. } => {
            hit = subst_outer_refs_expr(expr, shadow, outer, doc);
            for item in list.iter_mut() {
                hit |= subst_outer_refs_expr(item, shadow, outer, doc);
            }
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(op) = operand {
                hit = subst_outer_refs_expr(op, shadow, outer, doc);
            }
            for w in conditions.iter_mut() {
                hit |= subst_outer_refs_expr(&mut w.condition, shadow, outer, doc);
                hit |= subst_outer_refs_expr(&mut w.result, shadow, outer, doc);
            }
            if let Some(el) = else_result {
                hit |= subst_outer_refs_expr(el, shadow, outer, doc);
            }
        }
        SqlExpr::Cast { expr, .. } => hit = subst_outer_refs_expr(expr, shadow, outer, doc),
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &mut f.args {
                for a in list.args.iter_mut() {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        hit |= subst_outer_refs_expr(inner, shadow, outer, doc);
                    }
                }
            }
            if let Some(flt) = &mut f.filter {
                hit |= subst_outer_refs_expr(flt, shadow, outer, doc);
            }
        }
        // Shared traversal (mirror of expr_mentions_outer above): an outer
        // reference under a wrapper node (IS NULL/SUBSTRING/TRIM/…) must be
        // substituted too — leaving it reads the outer column as NULL (or an
        // inner same-name column via suffix fallback) inside the subquery.
        _ => {
            for c in child_exprs_mut(e) {
                hit |= subst_outer_refs_expr(c, shadow, outer, doc);
            }
        }
    }
    hit
}

/// `subst_outer_refs_expr` over every scope-local surface of a query.
/// `shadow` is the scope ENCLOSING the query; the query's own FROM names
/// extend a local copy (they win over `outer` inside), and every nested
/// subquery body starts from that copy — so sibling subqueries never
/// inherit each other's FROM names, and an inner alias equal to an outer
/// one (`EXISTS(SELECT 1 FROM t c WHERE c.x = 1)` under an outer alias
/// `c`) keeps the inner `c.x` untouched.
fn subst_outer_refs_query(
    q: &mut Query,
    shadow: &OuterFrom,
    outer: &OuterFrom,
    doc: &Object,
) -> bool {
    let mut hit = false;
    if let Some(w) = &mut q.with {
        // CTE bodies of one WITH share the level's accumulating scope (a
        // later CTE may reference an earlier one): insert each name AFTER
        // its body is rewritten so self-references keep resolving to the
        // CTE, while later bodies see it (a clone taken once never
        // accumulated, so a qualified reference to an earlier CTE could be
        // mistaken for the outer row's alias and substituted with outer
        // values — silently reading the wrong table).
        let mut cte_shadow = shadow.clone();
        for cte in &mut w.cte_tables {
            hit |= subst_outer_refs_query(&mut cte.query, &cte_shadow, outer, doc);
            cte_shadow.insert(cte.alias.name.value.clone());
        }
    }
    hit |= subst_outer_refs_setexpr(&mut q.body, shadow, outer, doc);
    if let Some(ob) = &mut q.order_by {
        // ORDER BY resolves in the body's own scope: reuse its FROM names.
        let mut own = shadow.clone();
        if let sqlparser::ast::SetExpr::Select(sel) = &*q.body {
            from_list_names(&sel.from, &mut own);
        }
        if let sqlparser::ast::OrderByKind::Expressions(exprs) = &mut ob.kind {
            for o in exprs.iter_mut() {
                hit |= subst_outer_refs_expr(&mut o.expr, &own, outer, doc);
            }
        }
    }
    hit
}

fn subst_outer_refs_setexpr(
    body: &mut sqlparser::ast::SetExpr,
    shadow: &OuterFrom,
    outer: &OuterFrom,
    doc: &Object,
) -> bool {
    use sqlparser::ast::SetExpr;
    match body {
        SetExpr::Select(sel) => {
            let mut own = shadow.clone();
            from_list_names(&sel.from, &mut own);
            let mut hit = false;
            for twj in &mut sel.from {
                for j in &mut twj.joins {
                    if let Some(e) = join_on_expr_mut(&mut j.join_operator) {
                        hit |= subst_outer_refs_expr(e, &own, outer, doc);
                    }
                }
            }
            if let Some(sel_expr) = &mut sel.selection {
                hit |= subst_outer_refs_expr(sel_expr, &own, outer, doc);
            }
            if let Some(having) = &mut sel.having {
                hit |= subst_outer_refs_expr(having, &own, outer, doc);
            }
            if let sqlparser::ast::GroupByExpr::Expressions(es, _) = &mut sel.group_by {
                for e in es.iter_mut() {
                    hit |= subst_outer_refs_expr(e, &own, outer, doc);
                }
            }
            for item in &mut sel.projection {
                match item {
                    sqlparser::ast::SelectItem::UnnamedExpr(e)
                    | sqlparser::ast::SelectItem::ExprWithAlias { expr: e, .. } => {
                        hit |= subst_outer_refs_expr(e, &own, outer, doc);
                    }
                    _ => {}
                }
            }
            hit
        }
        SetExpr::SetOperation { left, right, .. } => {
            // Arms do not see each other's FROM names.
            subst_outer_refs_setexpr(left, shadow, outer, doc)
                | subst_outer_refs_setexpr(right, shadow, outer, doc)
        }
        SetExpr::Query(inner) => subst_outer_refs_query(inner, shadow, outer, doc),
        SetExpr::Values(rows) => {
            let mut hit = false;
            for parens in rows.rows.iter_mut() {
                for e in parens.content.iter_mut() {
                    hit |= subst_outer_refs_expr(e, shadow, outer, doc);
                }
            }
            hit
        }
        _ => false,
    }
}

// ---- read-target walkers (stmt_read_targets) ----
// Every walker returns Option<()>: `None` means "shape not fully
// classifiable" and the authorization caller must DENY (fail closed).

fn walk_query(q: &Query, out: &mut Vec<String>, objects: &dyn Fn(&str) -> bool) -> Option<()> {
    walk_query_shadowed(q, out, &[], objects)
}

/// `shadow` carries the CTE names visible at this scope: a WITH alias shadows
/// same-named tables/views for its entire scope (subqueries included), so
/// FROM refs under those names read the CTE, not a base object, and must not
/// land in the base set — a view whose body opens `WITH v AS (…) SELECT *
/// FROM v` used to be misjudged as self-referencing and refused.
/// `objects` tells whether a name matches a real table/view: the engine binds
/// a CTE's own body (and a recursive anchor) BEFORE the CTE enters scope, so
/// a self-name that also names a real object reads the BASE object there —
/// shadowing it would hide that read from authorization and row filters
/// entirely (the name only shadows once its body is done).
fn walk_query_shadowed(
    q: &Query,
    out: &mut Vec<String>,
    outer: &[String],
    objects: &dyn Fn(&str) -> bool,
) -> Option<()> {
    let mut shadow: Vec<String> = outer.to_vec();
    if let Some(w) = &q.with {
        for cte in &w.cte_tables {
            let name = cte.alias.name.value.clone();
            if !objects(&name) {
                shadow.push(name.clone());
            }
            walk_query_shadowed(&cte.query, out, &shadow, objects)?;
            // From here on (later CTE bodies, the main query) the name is a
            // materialized CTE read for everyone.
            shadow.push(name);
        }
    }
    // Fast path only when NO names are shadowed at this level: a body walk
    // arrives with the enclosing scope's shadow in `outer`, and short-
    // circuiting there wrote the refs straight into `out`, skipping the
    // filter entirely (the body's own CTE reads leaked into the base set).
    if shadow.is_empty() {
        return walk_query_inner(q, out, objects);
    }
    let mut refs = Vec::new();
    walk_query_inner(q, &mut refs, objects)?;
    out.extend(refs.into_iter().filter(|r| !shadow.iter().any(|s| s == r)));
    Some(())
}

fn walk_query_inner(
    q: &Query,
    out: &mut Vec<String>,
    objects: &dyn Fn(&str) -> bool,
) -> Option<()> {
    walk_setexpr(&q.body, out, objects)?;
    if let Some(order_by) = &q.order_by {
        if let sqlparser::ast::OrderByKind::Expressions(exprs) = &order_by.kind {
            for obe in exprs {
                walk_expr(&obe.expr, out, objects)?;
            }
        }
    }
    Some(())
}

fn walk_setexpr(se: &SetExpr, out: &mut Vec<String>, objects: &dyn Fn(&str) -> bool) -> Option<()> {
    match se {
        SetExpr::Select(sel) => {
            for twj in &sel.from {
                walk_factor(&twj.relation, out, objects)?;
                for j in &twj.joins {
                    walk_factor(&j.relation, out, objects)?;
                    if let Some(e) = join_on_expr(&j.join_operator) {
                        walk_expr(e, out, objects)?;
                    }
                }
            }
            for item in &sel.projection {
                match item {
                    SelectItem::UnnamedExpr(e) | SelectItem::ExprWithAlias { expr: e, .. } => {
                        walk_expr(e, out, objects)?
                    }
                    _ => {}
                }
            }
            if let Some(sel_expr) = &sel.selection {
                walk_expr(sel_expr, out, objects)?;
            }
            if let sqlparser::ast::GroupByExpr::Expressions(exprs, _) = &sel.group_by {
                for e in exprs {
                    walk_expr(e, out, objects)?;
                }
            }
            if let Some(having) = &sel.having {
                walk_expr(having, out, objects)?;
            }
            Some(())
        }
        SetExpr::Query(inner) => walk_query(inner, out, objects),
        SetExpr::SetOperation { left, right, .. } => {
            walk_setexpr(left, out, objects)?;
            walk_setexpr(right, out, objects)
        }
        SetExpr::Values(values) => {
            for row in &values.rows {
                for e in row.content.iter() {
                    walk_expr(e, out, objects)?;
                }
            }
            Some(())
        }
        // TABLE / InsertStatements shapes: no table refs to collect.
        _ => Some(()),
    }
}

/// The ON predicate of a join, when it has one (USING lists reference
/// already-counted tables; NATURAL/CROSS have no predicate).
fn join_on_expr(op: &sqlparser::ast::JoinOperator) -> Option<&SqlExpr> {
    use sqlparser::ast::JoinConstraint as JC;
    use sqlparser::ast::JoinOperator as JO;
    let constraint = match op {
        JO::Join(c)
        | JO::Inner(c)
        | JO::Left(c)
        | JO::LeftOuter(c)
        | JO::Right(c)
        | JO::RightOuter(c)
        | JO::FullOuter(c)
        | JO::CrossJoin(c)
        | JO::Semi(c)
        | JO::LeftSemi(c)
        | JO::RightSemi(c)
        | JO::Anti(c)
        | JO::LeftAnti(c)
        | JO::RightAnti(c) => c,
        _ => return None,
    };
    match constraint {
        JC::On(e) => Some(e),
        _ => None,
    }
}

/// Mutable twin of [`join_on_expr`] for in-place expression substitution.
/// Every constraint-carrying variant must be covered here AND there: the
/// read-target walkers use the shared accessor, so an uncovered variant
/// would let a subquery inside its ON read tables the authorizer never saw.
fn join_on_expr_mut(op: &mut sqlparser::ast::JoinOperator) -> Option<&mut SqlExpr> {
    use sqlparser::ast::JoinConstraint as JC;
    use sqlparser::ast::JoinOperator as JO;
    let constraint = match op {
        JO::Join(c)
        | JO::Inner(c)
        | JO::Left(c)
        | JO::LeftOuter(c)
        | JO::Right(c)
        | JO::RightOuter(c)
        | JO::FullOuter(c)
        | JO::CrossJoin(c)
        | JO::Semi(c)
        | JO::LeftSemi(c)
        | JO::RightSemi(c)
        | JO::Anti(c)
        | JO::LeftAnti(c)
        | JO::RightAnti(c) => c,
        _ => return None,
    };
    match constraint {
        JC::On(e) => Some(e),
        _ => None,
    }
}

fn walk_factor(
    tf: &sqlparser::ast::TableFactor,
    out: &mut Vec<String>,
    objects: &dyn Fn(&str) -> bool,
) -> Option<()> {
    match tf {
        sqlparser::ast::TableFactor::Table { name, .. } => {
            // Multi-part names keep their QUALIFIED form for the
            // authorization walkers: the compatibility views are addressed
            // as information_schema.columns, and taking the last segment
            // made them indistinguishable from a user table of the same
            // leaf name (the server's readable_by_all prefix never fired).
            // The engine's own name resolution is unchanged — this walker
            // only feeds classification.
            if name.0.len() > 1 {
                let qualified = name
                    .0
                    .iter()
                    .map(|p| match p {
                        sqlparser::ast::ObjectNamePart::Identifier(i) => i.value.clone(),
                        other => other.to_string(),
                    })
                    .collect::<Vec<_>>()
                    .join(".");
                out.push(qualified);
            } else {
                out.push(obj_name(name));
            }
            Some(())
        }
        sqlparser::ast::TableFactor::Derived { subquery, .. } => walk_query(subquery, out, objects),
        sqlparser::ast::TableFactor::NestedJoin {
            table_with_joins, ..
        } => {
            walk_factor(&table_with_joins.relation, out, objects)?;
            for j in &table_with_joins.joins {
                walk_factor(&j.relation, out, objects)?;
            }
            Some(())
        }
        // Table functions / UNNEST: unsupported shapes — deny.
        _ => None,
    }
}

fn walk_expr(e: &SqlExpr, out: &mut Vec<String>, objects: &dyn Fn(&str) -> bool) -> Option<()> {
    use SqlExpr::*;
    match e {
        Value(_) | Identifier(_) | CompoundIdentifier(_) | TypedString { .. } => Some(()),
        IsNull(i) | IsNotNull(i) | Nested(i) | Cast { expr: i, .. } => walk_expr(i, out, objects),
        UnaryOp { expr, .. } => walk_expr(expr, out, objects),
        BinaryOp { left, right, .. } => {
            walk_expr(left, out, objects)?;
            walk_expr(right, out, objects)
        }
        Between {
            expr, low, high, ..
        } => {
            walk_expr(expr, out, objects)?;
            walk_expr(low, out, objects)?;
            walk_expr(high, out, objects)
        }
        Like { expr, pattern, .. } | ILike { expr, pattern, .. } => {
            walk_expr(expr, out, objects)?;
            walk_expr(pattern, out, objects)
        }
        InList { expr, list, .. } => {
            walk_expr(expr, out, objects)?;
            for item in list {
                walk_expr(item, out, objects)?;
            }
            Some(())
        }
        InSubquery { expr, subquery, .. } => {
            walk_expr(expr, out, objects)?;
            walk_query(subquery, out, objects)
        }
        Subquery(q) => walk_query(q, out, objects),
        Exists { subquery, .. } => walk_query(subquery, out, objects),
        Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                walk_expr(o, out, objects)?;
            }
            for w in conditions {
                walk_expr(&w.condition, out, objects)?;
                walk_expr(&w.result, out, objects)?;
            }
            if let Some(r) = else_result {
                walk_expr(r, out, objects)?;
            }
            Some(())
        }
        Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        walk_expr(inner, out, objects)?;
                    }
                }
            }
            // Aggregate FILTER (WHERE …) is evaluated per row and may carry
            // subqueries — an unwalked filter would let a read-only user
            // run a hidden subquery the classifier never sees.
            if let Some(cond) = &f.filter {
                walk_expr(cond, out, objects)?;
            }
            for og in &f.within_group {
                walk_expr(&og.expr, out, objects)?;
            }
            Some(())
        }
        Substring {
            expr,
            substring_from,
            substring_for,
            ..
        } => {
            walk_expr(expr, out, objects)?;
            if let Some(f) = substring_from {
                walk_expr(f, out, objects)?;
            }
            if let Some(l) = substring_for {
                walk_expr(l, out, objects)?;
            }
            Some(())
        }
        Trim {
            expr, trim_what, ..
        } => {
            walk_expr(expr, out, objects)?;
            if let Some(w) = trim_what {
                walk_expr(w, out, objects)?;
            }
            Some(())
        }
        // ANY/ALL and the long tail of rare expression shapes: deny rather
        // than risk authorizing an unread subquery (fail closed).
        _ => None,
    }
}

/// Find `outer_table.column` references in `e` whose qualifier is a known
/// catalog table but not one of the query's own FROM names/aliases — the
/// correlated-reference shape. Unqualified outer references cannot be told
/// apart from legitimate schemaless fields, so only qualified ones flag.
fn collect_correlated_refs(
    e: &SqlExpr,
    from_names: &std::collections::BTreeSet<String>,
    catalog: &std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
    hits: &mut Vec<String>,
) {
    match e {
        SqlExpr::CompoundIdentifier(parts) => {
            if parts.len() >= 2 {
                let qualifier = &parts[0].value;
                if !from_names.contains(qualifier) && catalog.contains_key(qualifier) {
                    hits.push(qualifier.clone());
                }
            }
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            collect_correlated_refs(left, from_names, catalog, hits);
            collect_correlated_refs(right, from_names, catalog, hits);
        }
        SqlExpr::UnaryOp { expr, .. } => collect_correlated_refs(expr, from_names, catalog, hits),
        SqlExpr::Nested(inner) => collect_correlated_refs(inner, from_names, catalog, hits),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            collect_correlated_refs(expr, from_names, catalog, hits);
            collect_correlated_refs(low, from_names, catalog, hits);
            collect_correlated_refs(high, from_names, catalog, hits);
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            collect_correlated_refs(expr, from_names, catalog, hits);
            collect_correlated_refs(pattern, from_names, catalog, hits);
        }
        SqlExpr::InList { expr, list, .. } => {
            collect_correlated_refs(expr, from_names, catalog, hits);
            for item in list {
                collect_correlated_refs(item, from_names, catalog, hits);
            }
        }
        SqlExpr::InSubquery { expr, .. } => {
            collect_correlated_refs(expr, from_names, catalog, hits);
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(op) = operand {
                collect_correlated_refs(op, from_names, catalog, hits);
            }
            for w in conditions {
                collect_correlated_refs(&w.condition, from_names, catalog, hits);
                collect_correlated_refs(&w.result, from_names, catalog, hits);
            }
            if let Some(el) = else_result {
                collect_correlated_refs(el, from_names, catalog, hits);
            }
        }
        SqlExpr::Cast { expr, .. } => collect_correlated_refs(expr, from_names, catalog, hits),
        // Shared traversal (mirror of expr_mentions_outer): a qualified outer
        // reference under a wrapper node (IS NULL/SUBSTRING/…) is still a
        // correlation; missing it let the subquery fall back to the
        // schemaless NULL read.
        _ => {
            for c in child_exprs(e) {
                collect_correlated_refs(c, from_names, catalog, hits);
            }
        }
    }
}

/// Dump-replay insert order: referenced tables before referencing ones
/// (FK checks run per row during replay). Picks the first satisfiable
/// table in catalog order each round; an FK cycle falls back to catalog
/// order for its members (a true cycle needs deferred constraints).
fn fk_dependency_order(
    names: &[String],
    tables: &std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
) -> Vec<String> {
    let mut out: Vec<String> = Vec::with_capacity(names.len());
    let mut remaining: Vec<String> = names.to_vec();
    while !remaining.is_empty() {
        let next = remaining.iter().position(|n| {
            tables.get(n).is_none_or(|m| {
                m.foreign_keys.iter().all(|(_, rt, _)| {
                    rt == n || !names.iter().any(|x| x == rt) || out.iter().any(|o| o == rt)
                })
            })
        });
        match next {
            Some(i) => out.push(remaining.remove(i)),
            None => out.append(&mut remaining),
        }
    }
    out
}

/// Row order for a table that references ITSELF in a dump: parents first.
/// Per-row FK checks run at replay, so a storage-order dump of a
/// self-referencing table fails restore/join/repair replay whenever a row
/// references a later-stored row (reachable via UPDATE, which never had the
/// child-side batch check). Rows with NULL/missing FK values have no
/// dependency; a row whose reference can be satisfied by ITSELF (the replay
/// check counts the statement's own batch) is free too. Same-value parent
/// groups open as soon as one member is emitted (the replay check needs one
/// present parent). A cycle keeps the remaining storage order and fails
/// loudly at replay instead of silently dropping rows. Kahn-style, O(rows +
/// edges) — a long reference chain must not turn the dump quadratic.
fn self_ref_row_order(table: &str, meta: &TableMeta, docs: Vec<Object>) -> Vec<Object> {
    let self_fks: Vec<(&str, &str)> = meta
        .foreign_keys
        .iter()
        .filter(|(_, rt, _)| rt == table)
        .map(|(lc, _, rc)| (lc.as_str(), rc.as_str()))
        .collect();
    if self_fks.is_empty() || docs.len() < 2 {
        return docs;
    }
    // 编码字节作值键:与 B+ 树/判重同源(Value 本身不作 Ord)。
    let key_of = |v: &Value| encode::encode_to_vec(v).ok();
    // 值 → 组号;组员 = rc 值落在该组的行。只把「能当父行」的值建组:
    // NULL 被引用列值不当父(子行 NULL 引用本来就免检,值 NULL 的父行
    // 也不会成为任何非 NULL 引用的目标)。
    let mut group_of: std::collections::BTreeMap<Vec<u8>, usize> =
        std::collections::BTreeMap::new();
    let mut members: Vec<Vec<usize>> = Vec::new();
    for (i, doc) in docs.iter().enumerate() {
        for (_, rc) in &self_fks {
            if let Some(v) = doc.get(*rc).filter(|v| !matches!(v, Value::Null)) {
                if let Some(k) = key_of(v) {
                    let gid = *group_of.entry(k).or_insert_with(|| {
                        members.push(Vec::new());
                        members.len() - 1
                    });
                    members[gid].push(i);
                }
            }
        }
    }
    let n = docs.len();
    // 每行未满足的依赖数 + 每组的等待者;初始扫描定队列。
    let mut blocked: Vec<usize> = vec![0; n];
    let mut waiters: Vec<Vec<usize>> = vec![Vec::new(); members.len()];
    let mut open: Vec<bool> = vec![false; members.len()];
    let mut queue: std::collections::VecDeque<usize> = std::collections::VecDeque::new();
    let mut in_queue = vec![false; n];
    for (i, doc) in docs.iter().enumerate() {
        for (lc, _) in &self_fks {
            let Some(v) = doc.get(*lc) else { continue };
            if matches!(v, Value::Null) {
                continue;
            }
            let Some(k) = key_of(v) else { continue };
            let Some(&gid) = group_of.get(&k) else {
                continue;
            };
            if members[gid].contains(&i) {
                // 引用可由本行自身满足(回放检查计入本语句批次)。
                continue;
            }
            blocked[i] += 1;
            waiters[gid].push(i);
        }
        if blocked[i] == 0 {
            queue.push_back(i);
            in_queue[i] = true;
        }
    }
    let mut order: Vec<usize> = Vec::with_capacity(n);
    let mut emitted = vec![false; n];
    while let Some(i) = queue.pop_front() {
        in_queue[i] = false;
        if emitted[i] {
            continue;
        }
        emitted[i] = true;
        order.push(i);
        // 本行出列后,其 rc 值对应的组随之打开,唤醒等待者。
        for (_, rc) in &self_fks {
            let Some(v) = doc_i_rc(&docs[i], rc) else {
                continue;
            };
            let Some(k) = key_of(v) else { continue };
            let Some(&gid) = group_of.get(&k) else {
                continue;
            };
            if !open[gid] {
                open[gid] = true;
                for &w in &waiters[gid] {
                    if !emitted[w] && !in_queue[w] {
                        // 该依赖被满足,计数清到零入队(blocked 精确记账
                        // 复杂化,直接按「全部依赖已满足」重判一次)。
                        if deps_ready(&docs[w], &self_fks, &group_of, &members, &open, w) {
                            queue.push_back(w);
                            in_queue[w] = true;
                        }
                    }
                }
            }
        }
    }
    if order.len() == n {
        order.into_iter().map(|i| docs[i].clone()).collect()
    } else {
        // 环:剩余行按存储序输出,回放响亮报错。
        let mut out: Vec<Object> = order.into_iter().map(|i| docs[i].clone()).collect();
        out.extend((0..n).filter(|&i| !emitted[i]).map(|i| docs[i].clone()));
        out
    }
}

fn doc_i_rc<'a>(doc: &'a Object, col: &str) -> Option<&'a Value> {
    doc.get(col).filter(|v| !matches!(**v, Value::Null))
}

fn deps_ready(
    doc: &Object,
    self_fks: &[(&str, &str)],
    group_of: &std::collections::BTreeMap<Vec<u8>, usize>,
    members: &[Vec<usize>],
    open: &[bool],
    self_idx: usize,
) -> bool {
    for (lc, _) in self_fks {
        let Some(v) = doc.get(*lc) else { continue };
        if matches!(v, Value::Null) {
            continue;
        }
        let Some(k) = encode::encode_to_vec(v).ok() else {
            continue;
        };
        let Some(&gid) = group_of.get(&k) else {
            continue;
        };
        if !open[gid] && !members[gid].contains(&self_idx) {
            return false;
        }
    }
    true
}

/// Views in creation-safe order for a dump: every view after the views its
/// body references (CREATE VIEW dry-runs the body, so a view of a view needs
/// its base view restored first — alphabetical order would replay
/// `CREATE VIEW a AS SELECT * FROM z` before z exists). A cycle (not
/// constructible through CREATE VIEW; defensive) falls back to name order,
/// and replay fails loudly at the offending CREATE instead of silently
/// omitting the rest.
fn view_dependency_order(
    names: &[String],
    tables: &std::collections::BTreeMap<String, std::sync::Arc<TableMeta>>,
) -> Vec<String> {
    let view_set: std::collections::BTreeSet<&str> = names.iter().map(|s| s.as_str()).collect();
    let objects = |n: &str| tables.contains_key(n);
    // Direct view→view edges (an unparseable body contributes none; the
    // CREATE would fail at replay time anyway).
    let edges: Vec<(String, Vec<String>)> = names
        .iter()
        .map(|n| {
            let mut deps = Vec::new();
            if let Some(sql) = tables.get(n).and_then(|m| m.view_sql.as_ref()) {
                if let Ok(mut stmts) = Parser::parse_sql(&GenericDialect {}, sql) {
                    if let Some(Statement::Query(q)) = stmts.pop() {
                        let mut refs = Vec::new();
                        if walk_query(&q, &mut refs, &objects).is_some() {
                            deps = refs
                                .into_iter()
                                .filter(|r| view_set.contains(r.as_str()))
                                .collect();
                        }
                    }
                }
            }
            (n.clone(), deps)
        })
        .collect();
    let mut out: Vec<String> = Vec::with_capacity(names.len());
    while out.len() < names.len() {
        let before = out.len();
        for (name, deps) in edges.iter() {
            if !out.contains(name) && deps.iter().all(|d| out.contains(d)) {
                out.push(name.clone());
            }
        }
        if out.len() == before {
            let rest: Vec<String> = edges
                .iter()
                .map(|(n, _)| n.clone())
                .filter(|n| !out.contains(n))
                .collect();
            out.extend(rest);
            break;
        }
    }
    out
}

/// Evaluate a constant expression (literal / arithmetic on literals).
pub fn eval_const(e: &SqlExpr) -> Result<Value> {
    match e {
        SqlExpr::Value(v) => sql_value(v),
        SqlExpr::UnaryOp { op, expr } => {
            // `-9223372036854775808` lexes as Minus over 9223372036854775808,
            // which overflows i64 on its own — re-parse the signed text so the
            // value stays an Int instead of degrading to Float.
            if *op == sqlparser::ast::UnaryOperator::Minus {
                if let SqlExpr::Value(nv) = expr.as_ref() {
                    if let sqlparser::ast::Value::Number(n, _) = &nv.value {
                        if let Ok(i) = format!("-{n}").parse::<i64>() {
                            return Ok(Value::Int(i));
                        }
                    }
                }
            }
            let v = eval_const(expr)?;
            match (op, v) {
                (sqlparser::ast::UnaryOperator::Minus, Value::Int(i)) => {
                    Ok(Value::Int(i.wrapping_neg()))
                }
                (sqlparser::ast::UnaryOperator::Minus, Value::Float(f)) => Ok(Value::Float(-f)),
                (sqlparser::ast::UnaryOperator::Minus, Value::Decimal(d)) => {
                    // Signed-zero guard, same as the runtime unary minus.
                    let neg = -d;
                    Ok(Value::Decimal(if neg.is_zero() && neg.is_sign_negative() {
                        rust_decimal::Decimal::ZERO
                    } else {
                        neg
                    }))
                }
                // T-SQL bitwise NOT (~x): two's-complement on 64-bit ints.
                (sqlparser::ast::UnaryOperator::BitwiseNot, Value::Int(i)) => Ok(Value::Int(!i)),
                _ => err("unsupported unary operand"),
            }
        }
        SqlExpr::BinaryOp { left, op, right } => {
            let l = eval_const(left)?;
            let r = eval_const(right)?;
            binop(l, op, r)
        }
        SqlExpr::Nested(e) => eval_const(e),
        SqlExpr::Floor { expr, .. } => scalar_function("FLOOR", &[eval_const(expr)?]),
        SqlExpr::Ceil { expr, .. } => scalar_function("CEILING", &[eval_const(expr)?]),
        // CAST of a constant (bound decimal/blob parameters render as
        // CAST/hex literals; resolved INSERT replay re-evaluates them).
        SqlExpr::Cast {
            kind,
            expr,
            data_type,
            ..
        } => {
            let v = cast_value(eval_const(expr)?, &data_type.to_string());
            // T-SQL TRY_CAST: a failed conversion yields NULL, not an error.
            if matches!(kind, sqlparser::ast::CastKind::TryCast) {
                v.or(Ok(Value::Null))
            } else {
                v
            }
        }
        // Pure scalar functions of constants: resolved replication rewrites
        // and dump scripts render structured values and non-finite floats as
        // JSON_EXTRACT(...)/CAST(...) expressions, which must evaluate back
        // to the same value on replay. Only argument shapes the normal
        // expression path accepts are allowed here.
        SqlExpr::Function(f) => {
            let name = f.name.to_string().to_uppercase();
            if f.over.is_some() {
                return err(format!("window functions (OVER) are not supported: {name}"));
            }
            let mut args = Vec::new();
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    match a {
                        sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(inner),
                        ) => {
                            // Datepart names are bare identifiers, not
                            // columns (see `eval_fn_arg`).
                            if args.is_empty() && takes_datepart_name(&name) {
                                if let SqlExpr::Identifier(i) = inner {
                                    args.push(Value::Str(i.value.clone()));
                                    continue;
                                }
                            }
                            args.push(eval_const(inner)?)
                        }
                        _ => return err(format!("unsupported argument to {name}")),
                    }
                }
            }
            scalar_function(&name, &args)
        }
        SqlExpr::Identifier(i) => err(format!("column {} not allowed here", i.value)),
        SqlExpr::TypedString(ts) => typed_string_value(ts),
        // Constant CASE (`VALUES (CASE WHEN … THEN … END)` in a resolved
        // INSERT, replayed scripts): every branch is constant-foldable, the
        // same comparison rule as the row-level CASE arm applies.
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            let base = operand.as_ref().map(|o| eval_const(o)).transpose()?;
            for w in conditions {
                let hit = match &base {
                    Some(b) => {
                        let cv = eval_const(&w.condition)?;
                        !matches!(b, Value::Null)
                            && !matches!(cv, Value::Null)
                            && cmp_coerced(b, &cv) == Some(std::cmp::Ordering::Equal)
                    }
                    None => matches!(eval_const(&w.condition)?, Value::Bool(true)),
                };
                if hit {
                    return eval_const(&w.result);
                }
            }
            match else_result {
                Some(r) => eval_const(r),
                None => Ok(Value::Null),
            }
        }
        other => err(format!("unsupported expression: {other}")),
    }
}

fn sql_value(v: &sqlparser::ast::Value) -> Result<Value> {
    use sqlparser::ast::Value as V;
    let out = match v {
        V::Number(n, _) => {
            if let Ok(i) = n.parse::<i64>() {
                Value::Int(i)
            } else {
                let f = n
                    .parse::<f64>()
                    .map_err(|_| SqlError::Message(format!("bad number {n}")))?;
                // Overflowing literals ("1e999") parse to inf; admitting
                // them would store rows no dump or journal replay can render.
                if !f.is_finite() {
                    return err(format!("non-finite numeric literal: {n}"));
                }
                Value::Float(f)
            }
        }
        V::SingleQuotedString(s) | V::DoubleQuotedString(s) => Value::Str(s.clone()),
        // T-SQL national strings: the engine has one UTF-8 text type, so the
        // prefix only selects the literal form.
        V::NationalStringLiteral(s) => Value::Str(s.clone()),
        V::Boolean(b) => Value::Bool(*b),
        V::Null => Value::Null,
        // x'deadbeef' — the canonical BLOB literal (params, dumps, replays).
        V::HexStringLiteral(s) => {
            let cleaned: String = s.chars().filter(|c| !c.is_whitespace()).collect();
            if !cleaned.len().is_multiple_of(2) {
                return err(format!("hex literal has an odd digit count: x'{s}'"));
            }
            let mut bytes = Vec::with_capacity(cleaned.len() / 2);
            let chars: Vec<char> = cleaned.chars().collect();
            for pair in chars.chunks(2) {
                let hi = pair[0]
                    .to_digit(16)
                    .ok_or_else(|| SqlError::Message(format!("bad hex digit: {s}")))?;
                let lo = pair[1]
                    .to_digit(16)
                    .ok_or_else(|| SqlError::Message(format!("bad hex digit: {s}")))?;
                bytes.push(((hi << 4) | lo) as u8);
            }
            Value::Bytes(bytes)
        }
        other => return err(format!("unsupported literal: {other}")),
    };
    Ok(out)
}

/// Resolve a bare column name: exact key first, then a unique "alias.col"
/// match (qualified rows from joins); ambiguous matches are an error.
fn lookup_col(doc: &Object, name: &str) -> Result<Value> {
    if let Some(v) = doc.get(name) {
        return Ok(v.clone());
    }
    // Unqualified name on JOINED rows (every key is "alias.col"): take the
    // FIRST source in row order (BTreeMap order is deterministic; matches
    // left-table-first convention). Restricted to genuinely join-shaped
    // rows — every key qualified AND at least two distinct qualifiers. A
    // single-table doc whose only fields are literal dotted names ("g.x")
    // has one prefix: the suffix answer made query results depend on
    // whether an index exists (trees only ever key the bare name). The
    // injected ROWNUM pseudo-column is a bare key that must not disqualify
    // a joined row from the fallback.
    let mut qualifiers = 0usize;
    let mut last_prefix = "";
    let mut join_shaped = true;
    for k in doc.keys() {
        if k == "ROWNUM" {
            continue;
        }
        match k.rfind('.') {
            Some(i) => {
                let p = &k[..i];
                if p != last_prefix {
                    qualifiers += 1;
                    last_prefix = p;
                }
            }
            None => {
                join_shaped = false;
                break;
            }
        }
    }
    if !join_shaped || qualifiers < 2 {
        return Ok(Value::Null);
    }
    let suffix = format!(".{name}");
    Ok(doc
        .iter()
        .find(|(k, _)| k.ends_with(&suffix))
        .map(|(_, v)| v.clone())
        .unwrap_or(Value::Null))
}

/// True for the T-SQL datepart family whose FIRST argument is a bare
/// datepart name (`DATEPART(day, d)`) — never a column reference.
fn takes_datepart_name(name: &str) -> bool {
    matches!(
        name,
        "DATEADD" | "DATEDIFF" | "DATEDIFF_BIG" | "DATEPART" | "DATENAME"
    )
}

/// Evaluate one function argument for the Function arm of [`eval_expr`]:
/// the leading identifier of the datepart family rides through as the
/// datepart name itself.
fn eval_fn_arg(e: &SqlExpr, name: &str, first: bool, doc: &Object) -> Result<Value> {
    if first && takes_datepart_name(name) {
        if let SqlExpr::Identifier(i) = e {
            return Ok(Value::Str(i.value.clone()));
        }
    }
    eval_expr(e, doc)
}

/// Evaluate an expression against a document row.
pub fn eval_expr(e: &SqlExpr, doc: &Object) -> Result<Value> {
    match e {
        // T-SQL variables/parameters (`@p`, `@@ROWCOUNT`) read a document
        // field by that name today, i.e. silently NULL unless the document
        // happens to carry it. Bare (unquoted) forms are almost always a
        // variable: refuse and point at binding/quoted field access.
        SqlExpr::Identifier(i) if i.quote_style.is_none() && i.value.starts_with('@') => err(
            format!(
                "variables/parameters ({0}) are not supported; bind the value or quote the field name (\"{0}\")",
                i.value
            ),
        ),
        SqlExpr::Identifier(i) => lookup_col(doc, &i.value),
        SqlExpr::CompoundIdentifier(parts)
            if parts
                .first()
                .is_some_and(|p| p.quote_style.is_none() && p.value.starts_with('@')) =>
        {
            err(format!(
                "variables/parameters ({}) are not supported; bind the value or quote the field name",
                parts.first().map(|p| p.value.as_str()).unwrap_or("@")
            ))
        }
        SqlExpr::CompoundIdentifier(parts) => {
            let full = parts
                .iter()
                .map(|p| p.value.clone())
                .collect::<Vec<_>>()
                .join(".");
            if let Some(v) = doc.get(&full) {
                Ok(v.clone())
            } else {
                let last = parts.last().map(|p| p.value.clone()).unwrap_or_default();
                lookup_col(doc, &last)
            }
        }
        SqlExpr::Value(v) => sql_value(v),
        // Typed string literal: `TIMESTAMP '2026-09-16T00:00:00Z'`. A
        // malformed timestamp is a query error (static text, evaluated on
        // every row) — unlike a compared string, which degrades to NULL.
        SqlExpr::TypedString(ts) => typed_string_value(ts),
        SqlExpr::UnaryOp { op, expr } => {
            let v = eval_expr(expr, doc)?;
            match (op, v) {
                (sqlparser::ast::UnaryOperator::Minus, Value::Int(i)) => match i.checked_neg() {
                    Some(n) => Ok(Value::Int(n)),
                    // -i64::MIN overflows; mirror literal handling and keep
                    // the value instead of panicking in debug builds.
                    None => Ok(Value::Float(-(i as f64))),
                },
                (sqlparser::ast::UnaryOperator::Minus, Value::Float(f)) => Ok(Value::Float(-f)),
                (sqlparser::ast::UnaryOperator::Minus, Value::Decimal(d)) => {
                    // Signed-zero guard: decimal text cannot replay -0
                    // ("−0.00" parses back to +0), so the dump/replica
                    // rewrite would silently flip the encoded bytes.
                    let neg = -d;
                    Ok(Value::Decimal(
                        if neg.is_zero() && neg.is_sign_negative() {
                            rust_decimal::Decimal::ZERO
                        } else {
                            neg
                        },
                    ))
                }
                (sqlparser::ast::UnaryOperator::Not, Value::Bool(b)) => Ok(Value::Bool(!b)),
                (sqlparser::ast::UnaryOperator::Not, Value::Null) => Ok(Value::Null),
                // T-SQL bitwise NOT (~x): two's-complement on 64-bit ints.
                (sqlparser::ast::UnaryOperator::BitwiseNot, Value::Int(i)) => Ok(Value::Int(!i)),
                _ => err("unsupported unary operand"),
            }
        }
        SqlExpr::BinaryOp { left, op, right } => {
            let l = eval_expr(left, doc)?;
            let r = eval_expr(right, doc)?;
            binop(l, op, r)
        }
        SqlExpr::Nested(e) => eval_expr(e, doc),
        SqlExpr::IsNull(inner) => Ok(Value::Bool(matches!(eval_expr(inner, doc)?, Value::Null))),
        SqlExpr::IsNotNull(inner) => {
            Ok(Value::Bool(!matches!(eval_expr(inner, doc)?, Value::Null)))
        }
        // NULL-safe comparison (SQL:2003): a comparison that is false or
        // unknown is "distinct"; NULL matches only NULL.
        SqlExpr::IsDistinctFrom(l, r) => {
            let (lv, rv) = (eval_expr(l, doc)?, eval_expr(r, doc)?);
            Ok(Value::Bool(!values_equal_null_safe(&lv, &rv)))
        }
        SqlExpr::IsNotDistinctFrom(l, r) => {
            let (lv, rv) = (eval_expr(l, doc)?, eval_expr(r, doc)?);
            Ok(Value::Bool(values_equal_null_safe(&lv, &rv)))
        }
        SqlExpr::Between {
            expr,
            negated,
            low,
            high,
        } => {
            // NULL anywhere makes the predicate unknown -> false in WHERE.
            let (v, lo, hi) = (
                eval_expr(expr, doc)?,
                eval_expr(low, doc)?,
                eval_expr(high, doc)?,
            );
            if matches!(v, Value::Null) || matches!(lo, Value::Null) || matches!(hi, Value::Null) {
                return Ok(Value::Bool(false));
            }
            // Same TIMESTAMP↔string coercion as the bare comparisons; an
            // uncoercable pair is unknown, and unknown is false under either
            // polarity (NOT BETWEEN an unknown is still unknown).
            let (Some(lo_ord), Some(hi_ord)) = (cmp_coerced(&v, &lo), cmp_coerced(&v, &hi))
            else {
                return Ok(Value::Bool(false));
            };
            let inside = lo_ord != Ordering::Less && hi_ord != Ordering::Greater;
            Ok(Value::Bool(inside != *negated))
        }
        SqlExpr::Like {
            negated,
            expr,
            pattern,
            escape_char,
            ..
        }
        | SqlExpr::ILike {
            negated,
            expr,
            pattern,
            escape_char,
            ..
        } => {
            let ci = matches!(e, SqlExpr::ILike { .. });
            let v = eval_expr(expr, doc)?;
            let p = eval_expr(pattern, doc)?;
            let esc = escape_char.as_ref().and_then(|v| match &v.value {
                sqlparser::ast::Value::SingleQuotedString(s) => s.chars().next(),
                _ => None,
            });
            let hit = match (&v, &p) {
                (Value::Null, _) | (_, Value::Null) => false,
                (Value::Str(s), Value::Str(pat)) => {
                    let (s, pat) = if ci {
                        // Char-wise case fold: a full-string to_lowercase()
                        // changes the CHARACTER COUNT for some Unicode
                        // (U+0130 'İ' expands to two chars), skewing `_`
                        // wildcard counts. Folding each char to its first
                        // lowercase char keeps pattern and text aligned.
                        (
                            s.chars()
                                .map(|c| c.to_lowercase().next().unwrap_or(c))
                                .collect::<String>(),
                            pat.chars()
                                .map(|c| c.to_lowercase().next().unwrap_or(c))
                                .collect::<String>(),
                        )
                    } else {
                        (s.clone(), pat.clone())
                    };
                    like_match(&s, &pat, esc)
                }
                _ => false,
            };
            Ok(Value::Bool(hit != *negated))
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            let op = operand.as_ref().map(|o| eval_expr(o, doc)).transpose()?;
            for w in conditions {
                let hit = match &op {
                    Some(base) => {
                        let cv = eval_expr(&w.condition, doc)?;
                        !matches!(base, Value::Null)
                            && !matches!(cv, Value::Null)
                            // Same coercion funnel as `=`: `CASE ts WHEN
                            // '2026-…' THEN` compares like `ts = '2026-…'`.
                            && cmp_coerced(base, &cv) == Some(Ordering::Equal)
                    }
                    None => matches!(eval_expr(&w.condition, doc)?, Value::Bool(true)),
                };
                if hit {
                    return eval_expr(&w.result, doc);
                }
            }
            match else_result {
                Some(r) => eval_expr(r, doc),
                None => Ok(Value::Null),
            }
        }
        SqlExpr::Cast {
            kind,
            expr,
            data_type,
            ..
        } => {
            let v = cast_value(eval_expr(expr, doc)?, &data_type.to_string());
            // T-SQL TRY_CAST: a failed conversion yields NULL, not an error.
            if matches!(kind, sqlparser::ast::CastKind::TryCast) {
                v.or(Ok(Value::Null))
            } else {
                v
            }
        }
        // SUBSTR/SUBSTRING parses to a dedicated node, not a Function call.
        SqlExpr::Substring {
            expr,
            substring_from,
            substring_for,
            ..
        } => {
            let base = eval_expr(expr, doc)?;
            let start = match substring_from {
                Some(e) => match eval_expr(e, doc)? {
                    Value::Int(i) => i,
                    Value::Null => return Ok(Value::Null),
                    other => return err(format!("SUBSTR start must be an integer: {other:?}")),
                },
                None => 1,
            };
            let len = match substring_for {
                Some(e) => match eval_expr(e, doc)? {
                    Value::Int(i) => Some(i),
                    Value::Null => return Ok(Value::Null),
                    other => return err(format!("SUBSTR length must be an integer: {other:?}")),
                },
                None => None,
            };
            let args = vec![
                base,
                Value::Int(start),
                Value::Int(len.unwrap_or(i64::MAX / 4)),
            ];
            scalar_function("SUBSTR", &args)
        }
        SqlExpr::Trim {
            trim_where,
            expr,
            trim_what,
            ..
        } => {
            let base = eval_expr(expr, doc)?;
            // With a character set (T-SQL `TRIM('ab' FROM x)` / the
            // LEADING/TRAILING/BOTH forms) strip exactly those characters
            // from the chosen side; without one this is the classic
            // whitespace TRIM/LTRIM/RTRIM.
            if let Some(what) = trim_what {
                let chars = match eval_expr(what, doc)? {
                    Value::Null => return Ok(Value::Null),
                    v => value_to_text(&v).chars().collect::<Vec<char>>(),
                };
                let strip = |s: &str, head: bool, tail: bool| -> String {
                    if head {
                        s.trim_start_matches(|c| chars.contains(&c))
                    } else {
                        s
                    }
                    .trim_end_matches(|c| tail && chars.contains(&c))
                    .to_string()
                };
                let text = value_to_text(&base);
                return Ok(Value::Str(match trim_where {
                    Some(sqlparser::ast::TrimWhereField::Leading) => strip(&text, true, false),
                    Some(sqlparser::ast::TrimWhereField::Trailing) => strip(&text, false, true),
                    _ => strip(&text, true, true),
                }));
            }
            let name = match trim_where {
                Some(sqlparser::ast::TrimWhereField::Leading) => "LTRIM",
                Some(sqlparser::ast::TrimWhereField::Trailing) => "RTRIM",
                _ => "TRIM",
            };
            scalar_function(name, &[base])
        }
        // FLOOR/CEILING parse into dedicated nodes on some paths; route
        // them onto the scalar library.
        SqlExpr::Floor { expr, .. } => {
            scalar_function("FLOOR", &[eval_expr(expr, doc)?])
        }
        SqlExpr::Ceil { expr, .. } => {
            scalar_function("CEILING", &[eval_expr(expr, doc)?])
        }
        SqlExpr::Function(f) => {
            let name = f.name.to_string().to_uppercase();
            if f.over.is_some() {
                return err(format!("window functions (OVER) are not supported: {name}"));
            }
            if matches!(
                name.as_str(),
                "COUNT" | "COUNT_BIG" | "SUM" | "AVG" | "MIN" | "MAX" | "GROUP_CONCAT"
                    | "STRING_AGG" | "GROUPING"
            ) {
                return err(format!(
                    "aggregate function {name} is not allowed in this context"
                ));
            }
            let mut args = Vec::new();
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    match a {
                        sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(e),
                        ) => args.push(eval_fn_arg(e, &name, args.is_empty(), doc)?),
                        _ => return err(format!("unsupported argument to {name}")),
                    }
                }
            }
            scalar_function(&name, &args)
        }
        SqlExpr::InList {
            expr,
            list,
            negated,
        } => {
            let v = eval_expr(expr, doc)?;
            let mut hit = false;
            // The ONLY unknown source (kept three-valued so `x NOT IN
            // ('garbage')` on a TIMESTAMP column behaves exactly like
            // `x <> 'garbage'`: unknown, filtered — never silently true).
            let mut unknown = false;
            for item in list {
                let iv = eval_expr(item, doc)?;
                // NULL is a comparable value in this engine (the same
                // total order `x = NULL` / hash joins / unique checks
                // use): a NULL ELEMENT therefore participates in the
                // equality like any other. The old saw_null poisoning
                // made `x NOT IN (NULL)` false while `x <> NULL` was
                // true — two spellings of one predicate disagreed, and
                // `= ANY` (rewritten to IN) diverged from `= ALL`.
                // Equality through the TIMESTAMP↔string coercion funnel,
                // so `ts IN ('2026-…', …)` matches like `ts = '2026-…'`.
                match cmp_coerced(&v, &iv) {
                    Some(Ordering::Equal) => {
                        hit = true;
                        break;
                    }
                    None => unknown = true,
                    Some(_) => {}
                }
            }
            if hit {
                return Ok(Value::Bool(!*negated));
            }
            if unknown {
                return Ok(Value::Null);
            }
            Ok(Value::Bool(*negated))
        }
        // Subqueries are resolved per-statement by subst_expr; reaching one
        // here means it was correlated or unsupported.
        SqlExpr::Subquery(_) => err("correlated subqueries are not supported"),
        SqlExpr::InSubquery { .. } => err("correlated subqueries are not supported"),
        SqlExpr::Exists { .. } => err("correlated subqueries are not supported"),
        SqlExpr::AnyOp { .. } | SqlExpr::AllOp { .. } => {
            err("ANY/ALL subqueries are not supported here")
        }
        other => err(format!("unsupported expression: {other}")),
    }
}

/// Typed string literal (`TIMESTAMP '…'` / `DATE '…'`): a malformed
/// timestamp is a query error — the text is static, unlike a compared
/// string, which degrades to NULL in predicates.
fn typed_string_value(ts: &sqlparser::ast::TypedString) -> Result<Value> {
    let is_ts = matches!(
        ts.data_type,
        sqlparser::ast::DataType::Timestamp(_, _)
            | sqlparser::ast::DataType::TimestampNtz(_)
            | sqlparser::ast::DataType::Datetime(_)
            | sqlparser::ast::DataType::Date
    );
    if !is_ts {
        return err(format!("typed literal {} is not supported", ts.data_type));
    }
    let text = match &ts.value.value {
        sqlparser::ast::Value::SingleQuotedString(s)
        | sqlparser::ast::Value::DoubleQuotedString(s) => s.clone(),
        other => return err(format!("bad typed literal value: {other}")),
    };
    Ok(Value::Timestamp(
        crate::value::parse_timestamp_ms(&text)
            .ok_or_else(|| SqlError::Message(format!("bad TIMESTAMP literal '{text}'")))?,
    ))
}

/// SQL LIKE: `%` (any run), `_` (one char), `ESCAPE`, and the T-SQL
/// `[abc]`/`[^a-z]` character classes. The matcher lives in `tsql` and is
/// pinned by its own known-answer tests.
fn like_match(s: &str, pat: &str, esc: Option<char>) -> bool {
    crate::tsql::like_match(s, pat, esc)
}

/// `(skip, take)` when LIMIT/OFFSET are integer constants. `None` means the
/// window cannot be bounded ahead of time (no LIMIT clause, FETCH, or a
/// non-integer bound) — the generic path decides. Negative bounds follow
/// SQLite semantics (LIMIT -1 = no limit, OFFSET -1 = skip nothing), so a
/// pure `LIMIT -1 OFFSET n` skip still uses the index-ordered window with an
/// unbounded take.
fn constant_limit_window(query: &Query) -> Option<(usize, usize)> {
    if query.fetch.is_some() {
        return None;
    }
    fn bound(e: &SqlExpr) -> Option<i64> {
        eval_const(e).ok()?.as_i64()
    }
    fn take(n: i64) -> usize {
        if n < 0 {
            usize::MAX
        } else {
            n as usize
        }
    }
    fn skip(n: i64) -> usize {
        if n < 0 {
            0
        } else {
            n as usize
        }
    }
    match query.limit_clause.as_ref()? {
        LimitClause::LimitOffset { limit, offset, .. } => {
            let limit = bound(limit.as_ref()?)?;
            let offset = match offset {
                Some(o) => bound(&o.value)?,
                None => 0,
            };
            Some((skip(offset), take(limit)))
        }
        LimitClause::OffsetCommaLimit { offset, limit } => {
            Some((skip(bound(offset)?), take(bound(limit)?)))
        }
    }
}

/// LIMIT/OFFSET windowing shared by the FROM-less and general SELECT paths.
/// A negative limit or offset means "no limit"/"skip nothing" (SQLite);
/// non-integer values are an error, not a silently unlimited query.
fn apply_limit_clause(
    limit_clause: &LimitClause,
    rows: Vec<Vec<Value>>,
) -> Result<Vec<Vec<Value>>> {
    fn limit_count(e: &SqlExpr) -> Result<usize> {
        match eval_const(e)?.as_i64() {
            Some(n) if n >= 0 => Ok(n as usize),
            Some(_) => Ok(usize::MAX), // negative LIMIT means "no limit" (SQLite)
            None => err("LIMIT must be a non-negative integer"),
        }
    }
    fn offset_count(e: &SqlExpr) -> Result<usize> {
        match eval_const(e)?.as_i64() {
            Some(n) if n >= 0 => Ok(n as usize),
            Some(_) => Ok(0),
            None => err("OFFSET must be a non-negative integer"),
        }
    }
    match limit_clause {
        LimitClause::LimitOffset { limit, offset, .. } => {
            let n = match limit {
                Some(e) => limit_count(e)?,
                None => usize::MAX,
            };
            let skip = match offset {
                Some(o) => offset_count(&o.value)?,
                None => 0,
            };
            Ok(rows.into_iter().skip(skip).take(n).collect())
        }
        // MySQL form `LIMIT <offset>, <count>` (order reversed).
        LimitClause::OffsetCommaLimit { offset, limit } => {
            let skip = offset_count(offset)?;
            let n = limit_count(limit)?;
            Ok(rows.into_iter().skip(skip).take(n).collect())
        }
    }
}

/// Canonical text form of a value (CAST AS TEXT, GROUP_CONCAT, ||).
/// Current wall clock as the canonical text form (UTC, RFC 3339-style
/// seconds precision) — the SYSDATE() compatibility function's value.
fn now_ms_string() -> String {
    crate::value::format_timestamp_ms(crate::now_ms() as i64)
}

/// Days since epoch → (y, m, d) — Howard Hinnant's `civil_from_days`.
/// Shared with the server's backup UTC stamping; pinned by known-answer
/// tests in both engine and backup suites.
pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

/// True when the statement's projection or WHERE references the Oracle
/// ROWNUM pseudo-column.
fn select_refs_rownum(select: &sqlparser::ast::Select) -> bool {
    let mut refs = false;
    for item in &select.projection {
        match item {
            SelectItem::UnnamedExpr(e) => refs |= refs_rownum(e),
            SelectItem::ExprWithAlias { expr, .. } => refs |= refs_rownum(expr),
            _ => {}
        }
    }
    if let Some(cond) = &select.selection {
        refs |= refs_rownum(cond);
    }
    refs
}

/// Walk an expression tree looking for the Oracle ROWNUM pseudo-column
/// reference (case-insensitive identifier). Non-recursive shapes recurse;
/// subqueries do NOT — a ROWNUM inside `(SELECT ... WHERE ROWNUM <= n)`
/// belongs to the subquery's own row stream and is legal in a write's WHERE.
fn refs_rownum(e: &SqlExpr) -> bool {
    match e {
        SqlExpr::Identifier(i) => i.value.eq_ignore_ascii_case("ROWNUM"),
        SqlExpr::BinaryOp { left, right, .. } => refs_rownum(left) || refs_rownum(right),
        SqlExpr::UnaryOp { expr, .. } => refs_rownum(expr),
        SqlExpr::Nested(e)
        | SqlExpr::IsFalse(e)
        | SqlExpr::IsTrue(e)
        | SqlExpr::IsNotNull(e)
        | SqlExpr::IsNull(e)
        | SqlExpr::Cast { expr: e, .. } => refs_rownum(e),
        SqlExpr::Between {
            expr, low, high, ..
        } => refs_rownum(expr) || refs_rownum(low) || refs_rownum(high),
        SqlExpr::InList { expr, list, .. } => refs_rownum(expr) || list.iter().any(refs_rownum),
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            refs_rownum(expr) || refs_rownum(pattern)
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand.as_deref().is_some_and(refs_rownum)
                || conditions
                    .iter()
                    .any(|w| refs_rownum(&w.condition) || refs_rownum(&w.result))
                || else_result.as_deref().is_some_and(refs_rownum)
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                list.args.iter().any(|a| match a {
                    sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) => refs_rownum(inner),
                    _ => false,
                })
            } else {
                false
            }
        }
        _ => false,
    }
}

pub(crate) fn value_to_text(v: &Value) -> String {
    match v {
        Value::Str(s) => s.clone(),
        Value::Int(i) => i.to_string(),
        Value::Float(f) => {
            let s = format!("{f}");
            if s.contains('.') || s.contains('e') || s.contains('E') {
                s
            } else {
                format!("{f:.1}")
            }
        }
        Value::Decimal(d) => d.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Null => String::new(),
        // Timestamp renders as canonical fixed-width ISO text (Display),
        // not the debug enum shape.
        Value::Timestamp(ms) => crate::value::format_timestamp_ms(*ms),
        // BLOB text renders in its canonical `x'…'` literal form (Display)
        // — the Debug enum shape used to leak out here and the result could
        // never be parsed back.
        Value::Bytes(_) => v.to_string(),
        other => format!("{other:?}"),
    }
}

/// Best-effort CAST across the schemaless value model.
pub(crate) fn cast_value(v: Value, type_name: &str) -> Result<Value> {
    let t = type_name.to_uppercase();
    Ok(match v {
        Value::Null => Value::Null,
        // T-SQL BIT is the boolean-ish column type.
        v if t == "BIT" => match v {
            Value::Bool(_) => v,
            Value::Int(i) => Value::Bool(i != 0),
            Value::Float(f) => Value::Bool(f != 0.0),
            Value::Decimal(d) => Value::Bool(!d.is_zero()),
            Value::Str(s) => Value::Bool(s == "1" || s.eq_ignore_ascii_case("true")),
            other => other,
        },
        v if t.contains("INT") => match v {
            Value::Int(_) => v,
            Value::Float(f) => {
                // `f as i64` saturates silently; a financial conversion that
                // cannot be represented must fail loudly instead of turning
                // a huge amount into i64::MAX. (`i64::MAX as f64` rounds up
                // to 2^63, so `>=` there; `i64::MIN as f64` is exact.)
                if !f.is_finite() || f >= i64::MAX as f64 || f < i64::MIN as f64 {
                    return err(format!("cannot CAST {f} AS {type_name}: out of range"));
                }
                Value::Int(f as i64)
            }
            Value::Decimal(d) => Value::Int(d.trunc().to_i64().ok_or_else(|| {
                SqlError::Message(format!("cannot CAST {d} AS {type_name}: out of range"))
            })?),
            Value::Bool(b) => Value::Int(if b { 1 } else { 0 }),
            Value::Timestamp(ms) => Value::Int(ms),
            Value::Str(s) => Value::Int(
                s.trim()
                    .parse::<i64>()
                    .map_err(|_| SqlError::Message(format!("cannot CAST '{s}' AS {type_name}")))?,
            ),
            // A BLOB silently passing through as "the value" made every
            // downstream comparison/arithmetic silently wrong (`WHERE
            // CONVERT(INT, x'01') = 1` matched nothing, forever).
            Value::Bytes(_) => {
                return err(format!(
                    "cannot CAST a BLOB AS {type_name} (decode it explicitly first)"
                ))
            }
            other => other,
        },
        v if t.contains("CHAR") || t.contains("TEXT") || t.contains("STRING") => {
            Value::Str(value_to_text(&v))
        }
        // TIMESTAMP/DATETIME: strings parse in any accepted timestamp form
        // (malformed → error, like the numeric casts); integers are UTC
        // milliseconds. Timestamp→Int (ms) has its arm in the INT branch.
        v if t.contains("TIMESTAMP") || t.contains("DATETIME") => match v {
            Value::Timestamp(_) => v,
            Value::Int(i) => {
                // Domain check: an out-of-range instant has no canonical
                // text form, so `value_literal` could never replay it
                // (backup restore / join snapshot would fail on this row).
                if !crate::value::is_valid_timestamp_ms(i) {
                    return err(format!("cannot CAST {i} AS {type_name}: out of range"));
                }
                Value::Timestamp(i)
            }
            Value::Str(s) => {
                Value::Timestamp(crate::value::parse_timestamp_ms(&s).ok_or_else(|| {
                    SqlError::Message(format!("cannot CAST '{s}' AS {type_name}: not a timestamp"))
                })?)
            }
            other => {
                return err(format!(
                    "cannot CAST {} AS {type_name}: cast from {} is not defined",
                    value_to_text(&other),
                    other.type_name()
                ))
            }
        },
        // DATE: a real conversion with T-SQL semantics — parse/truncate to
        // UTC midnight (`CONVERT(DATE, getdate())` is the classic idiom).
        // This used to pass the input through untouched, storing a plain
        // string with no date semantics at all.
        v if t == "DATE" => match v {
            Value::Timestamp(ms) => Value::Timestamp(ms - ms.rem_euclid(86_400_000)),
            Value::Str(s) => {
                let ms = crate::value::parse_timestamp_ms(&s).ok_or_else(|| {
                    SqlError::Message(format!("cannot CAST '{s}' AS {type_name}: not a date"))
                })?;
                Value::Timestamp(ms - ms.rem_euclid(86_400_000))
            }
            other => {
                return err(format!(
                    "cannot CAST {} AS {type_name}: cast from {} is not defined",
                    value_to_text(&other),
                    other.type_name()
                ))
            }
        },
        v if t.contains("BOOL") => match v {
            Value::Bool(_) => v,
            Value::Int(i) => Value::Bool(i != 0),
            Value::Decimal(d) => Value::Bool(!d.is_zero()),
            Value::Str(s) => Value::Bool(s == "true"),
            other => other,
        },
        // Exact DECIMAL/NUMERIC: text and integer sources convert losslessly;
        // a Float source only promises its exact binary value.
        v if t.contains("DECIMAL") || t.contains("NUMERIC") => match v {
            Value::Decimal(_) => v,
            Value::Int(i) => Value::Decimal(Decimal::from(i)),
            Value::Float(f) => Value::Decimal(
                Decimal::from_f64_retain(f)
                    .ok_or_else(|| SqlError::Message(format!("cannot CAST {f} AS {type_name}")))?,
            ),
            Value::Str(s) => Value::Decimal(
                s.trim()
                    .parse::<Decimal>()
                    .map_err(|_| SqlError::Message(format!("cannot CAST '{s}' AS {type_name}")))?,
            ),
            Value::Bytes(_) => {
                return err(format!(
                    "cannot CAST a BLOB AS {type_name} (decode it explicitly first)"
                ))
            }
            other => other,
        },
        v if t.contains("REAL") || t.contains("DOUBLE") || t.contains("FLOAT") => match v {
            Value::Float(_) => v,
            Value::Int(i) => Value::Float(i as f64),
            Value::Decimal(d) => Value::Float(d.to_f64().unwrap_or(f64::NAN)),
            Value::Str(s) => Value::Float(
                s.trim()
                    .parse::<f64>()
                    .map_err(|_| SqlError::Message(format!("cannot CAST '{s}' AS {type_name}")))?,
            ),
            Value::Bytes(_) => {
                return err(format!(
                    "cannot CAST a BLOB AS {type_name} (decode it explicitly first)"
                ))
            }
            other => other,
        },
        // BLOB: bytes pass through; text keeps its UTF-8 bytes (SQLite-style
        // CAST semantics that drivers rely on for `CAST(@p AS BLOB)`).
        v if t.contains("BLOB") || t.contains("BYTES") || t.contains("BINARY") => match v {
            Value::Bytes(_) => v,
            Value::Str(s) => Value::Bytes(s.into_bytes()),
            other => other,
        },
        // Unknown type: pass through unchanged (types are documentation here).
        v => v,
    })
}

/// Scalar (non-aggregate) function library. Arity is checked up front:
/// a malformed call (`SELECT UPPER()`) must error, not panic on indexing.
fn scalar_function(name: &str, args: &[Value]) -> Result<Value> {
    fn arg<'a>(args: &'a [Value], i: usize, name: &str) -> Result<&'a Value> {
        args.get(i).ok_or_else(|| {
            SqlError::Message(format!("function {name} requires argument {}", i + 1))
        })
    }
    fn exact_arity(name: &str, args: &[Value], n: usize) -> Result<()> {
        if args.len() != n {
            return Err(SqlError::Message(format!(
                "function {name} takes exactly {n} argument(s), got {}",
                args.len()
            )));
        }
        Ok(())
    }
    let null_prop = |v: &Value| matches!(v, Value::Null);
    Ok(match name {
        "NOW" | "CURRENT_TIMESTAMP" | "NOW_MS" => {
            exact_arity(name, args, 0)?;
            Value::Timestamp(crate::now_ms() as i64)
        }
        "UPPER" | "UCASE" => {
            exact_arity(name, args, 1)?;
            let v = arg(args, 0, name)?;
            if null_prop(v) {
                Value::Null
            } else {
                Value::Str(value_to_text(v).to_uppercase())
            }
        }
        "LOWER" | "LCASE" => {
            exact_arity(name, args, 1)?;
            let v = arg(args, 0, name)?;
            if null_prop(v) {
                Value::Null
            } else {
                Value::Str(value_to_text(v).to_lowercase())
            }
        }
        "LENGTH" | "LEN" => {
            exact_arity(name, args, 1)?;
            Value::Int(match arg(args, 0, name)? {
                Value::Null => return Ok(Value::Null),
                Value::Str(s) => {
                    if name == "LEN" {
                        // T-SQL LEN: trailing blanks are not counted.
                        s.trim_end_matches(' ').chars().count() as i64
                    } else {
                        s.chars().count() as i64
                    }
                }
                Value::Bytes(b) => b.len() as i64,
                other => value_to_text(other).chars().count() as i64,
            })
        }
        "ABS" => {
            exact_arity(name, args, 1)?;
            match arg(args, 0, name)? {
                Value::Int(i) => Value::Int(i.abs()),
                Value::Float(f) => Value::Float(f.abs()),
                Value::Decimal(d) => Value::Decimal(d.abs()),
                Value::Null => Value::Null,
                other => return err(format!("ABS of non-numeric: {other:?}")),
            }
        }
        "ROUND" => {
            if args.is_empty() || args.len() > 2 {
                return err(format!(
                    "function ROUND takes 1 or 2 arguments, got {}",
                    args.len()
                ));
            }
            if null_prop(arg(args, 0, name)?) {
                Value::Null
            } else if let Value::Decimal(d) = arg(args, 0, name)? {
                // Exact rounding: half away from zero (SQL Server semantics).
                // A negative length rounds to tens/hundreds (T-SQL); the
                // decimal crate only rounds toward positive scale, so
                // pre-scale by the magnitude, round at scale 0, scale back.
                let digits = match args.get(1) {
                    // Clamp like the Float branch: a huge i64 truncated to
                    // u32 picked an arbitrary scale (2^32 → 0), and
                    // i64::MIN negated below overflowed in debug builds.
                    Some(Value::Int(d)) => (*d).clamp(-15, 28),
                    _ => 0,
                };
                if digits >= 0 {
                    Value::Decimal(d.round_dp_with_strategy(
                        (digits as u32).min(28),
                        rust_decimal::RoundingStrategy::MidpointAwayFromZero,
                    ))
                } else {
                    let shift_i64 = 10i64
                        .checked_pow(((-digits).min(15)) as u32)
                        .unwrap_or(1_000_000_000_000_000);
                    let shift = Decimal::from(shift_i64);
                    let shifted = (d / shift).round_dp_with_strategy(
                        0,
                        rust_decimal::RoundingStrategy::MidpointAwayFromZero,
                    ) * shift;
                    Value::Decimal(shifted)
                }
            } else {
                let x = as_f64(arg(args, 0, name)?)?;
                let digits = match args.get(1) {
                    // Clamp into f64-precision territory: the raw i64 would
                    // wrap through powi's i32 and round to a random scale.
                    Some(Value::Int(d)) => (*d).clamp(-15, 15),
                    _ => 0,
                };
                let m = 10f64.powi(digits as i32);
                Value::Float((x * m).round() / m)
            }
        }
        "COALESCE" | "IFNULL" | "ISNULL" => {
            if args.is_empty() {
                return err(format!("function {name} requires at least 1 argument"));
            }
            args.iter()
                .find(|v| !matches!(v, Value::Null))
                .cloned()
                .unwrap_or(Value::Null)
        }
        "NULLIF" => {
            exact_arity(name, args, 2)?;
            let a = arg(args, 0, name)?;
            let b = arg(args, 1, name)?;
            // Same comparison funnel as `=` (cmp_coerced): a Timestamp↔
            // parseable-string pair must null out here exactly as the
            // equality predicate matches it.
            if cmp_coerced(a, b) == Some(Ordering::Equal) {
                Value::Null
            } else {
                a.clone()
            }
        }
        "SUBSTR" | "SUBSTRING" => {
            if args.is_empty() || args.len() > 3 {
                return err(format!(
                    "function {name} takes 1 to 3 arguments, got {}",
                    args.len()
                ));
            }
            if null_prop(arg(args, 0, name)?) {
                Value::Null
            } else {
                let s: Vec<char> = value_to_text(arg(args, 0, name)?).chars().collect();
                // SQLite rules: 1-based start; negative start counts from
                // the end; start 0 sits at a virtual pre-string position
                // (so `substr('abcde',0,2)` yields 'a' — one char shorter);
                // negative length selects the |len| characters *before*
                // the start position.
                let n = s.len() as i64;
                let y = match args.get(1) {
                    Some(Value::Int(i)) => *i,
                    _ => 1,
                };
                let z = match args.get(2) {
                    Some(Value::Int(i)) => *i,
                    _ => i64::MAX,
                };
                let (b, take) = if y < 0 {
                    let b0 = n + y;
                    if b0 < 0 {
                        (0, z + b0)
                    } else {
                        (b0, z)
                    }
                } else if y > 0 {
                    (y - 1, z)
                } else {
                    (0, z - 1)
                };
                let (lo, hi) = if take < 0 {
                    ((b + take).max(0), b.max(0))
                } else {
                    (b.max(0), b.saturating_add(take))
                };
                let lo = lo.clamp(0, n) as usize;
                let hi = hi.clamp(0, n) as usize;
                Value::Str(if lo < hi {
                    s[lo..hi].iter().collect()
                } else {
                    String::new()
                })
            }
        }
        "TRIM" | "LTRIM" | "RTRIM" => {
            exact_arity(name, args, 1)?;
            let v = arg(args, 0, name)?;
            if null_prop(v) {
                return Ok(Value::Null);
            }
            let text = value_to_text(v);
            Value::Str(match name {
                "TRIM" => text.trim().to_string(),
                "LTRIM" => text.trim_start().to_string(),
                _ => text.trim_end().to_string(),
            })
        }
        "CONCAT" => {
            // T-SQL CONCAT: NULL arguments are treated as empty strings
            // (only an all-NULL argument list yields the empty string).
            // `||` keeps NULL propagation — the two are deliberately
            // different operators.
            Value::Str(
                args.iter()
                    .map(|v| {
                        if matches!(v, Value::Null) {
                            String::new()
                        } else {
                            value_to_text(v)
                        }
                    })
                    .collect(),
            )
        }
        "TYPEOF" => {
            exact_arity(name, args, 1)?;
            Value::Str(
                match arg(args, 0, name)? {
                    Value::Null => "null",
                    Value::Bool(_) => "bool",
                    Value::Int(_) => "integer",
                    Value::Float(_) => "float",
                    Value::Decimal(_) => "decimal",
                    Value::Timestamp(_) => "timestamp",
                    Value::Str(_) => "text",
                    Value::Bytes(_) => "blob",
                    Value::Array(_) => "array",
                    Value::Object(_) => "object",
                }
                .into(),
            )
        }
        "JSON_VALID" => {
            exact_arity(name, args, 1)?;
            match arg(args, 0, name)? {
                Value::Str(s) => Value::Bool(crate::json::from_str(s).is_ok()),
                _ => Value::Bool(false),
            }
        }
        // Array membership for EF's entity primitive-collection Contains:
        // JSON_ARRAY_CONTAINS(json_text, needle) — NULL text/parse failure and
        // non-array JSON are false (subquery-existence semantics).
        "JSON_ARRAY_CONTAINS" => {
            exact_arity(name, args, 2)?;
            let (haystack, needle) = (arg(args, 0, name)?, arg(args, 1, name)?);
            // Membership uses the same comparison funnel as `IN`/`=`
            // (cmp_coerced): EF serializes DateTime elements to ISO strings
            // while the typed needle arrives as a Timestamp — the raw total
            // order never equates the two, silently emptying the query.
            let contains = |items: &[Value]| {
                items
                    .iter()
                    .any(|it| cmp_coerced(it, needle) == Some(Ordering::Equal))
            };
            let items: &[Value] = match haystack {
                Value::Null => return Ok(Value::Null),
                Value::Array(items) => items,
                Value::Str(s) => match crate::json::from_str(s) {
                    Ok(Value::Array(items)) => {
                        return Ok(Value::Bool(contains(&items)));
                    }
                    _ => return Ok(Value::Bool(false)),
                },
                _ => return Ok(Value::Bool(false)),
            };
            Value::Bool(contains(items))
        }
        // ---- Oracle-style function family (compatibility surface) ----
        "NVL" => {
            exact_arity(name, args, 2)?;
            match arg(args, 0, name)? {
                Value::Null => arg(args, 1, name)?.clone(),
                v => v.clone(),
            }
        }
        "NVL2" => {
            exact_arity(name, args, 3)?;
            match arg(args, 0, name)? {
                Value::Null => arg(args, 2, name)?.clone(),
                _ => arg(args, 1, name)?.clone(),
            }
        }
        "DECODE" => {
            // Oracle DECODE: (expr, search1, result1, … [, default]). Oracle
            // treats NULL as equal to NULL in the comparisons; no match and
            // no default yields NULL.
            if args.len() < 3 {
                return err(format!(
                    "function {name} takes at least 3 arguments, got {}",
                    args.len()
                ));
            }
            let expr = &args[0];
            let mut i = 1;
            while i + 1 < args.len() {
                let s = &args[i];
                let matched = match (expr, s) {
                    (Value::Null, Value::Null) => true,
                    (Value::Null, _) | (_, Value::Null) => false,
                    // Same comparison funnel as `=` (cmp_coerced): a
                    // Timestamp↔parseable-string pair must decode-match
                    // exactly as the equality predicate matches it.
                    (a, b) => cmp_coerced(a, b) == Some(Ordering::Equal),
                };
                if matched {
                    return Ok(args[i + 1].clone());
                }
                i += 2;
            }
            if args.len().is_multiple_of(2) {
                return Ok(args[args.len() - 1].clone());
            }
            Value::Null
        }
        "INSTR" => {
            // 1-based position of the first occurrence; 0 when absent.
            exact_arity(name, args, 2)?;
            if args.iter().any(|v| matches!(v, Value::Null)) {
                return Ok(Value::Null);
            }
            let (Value::Str(hay), Value::Str(needle)) = (arg(args, 0, name)?, arg(args, 1, name)?)
            else {
                return err(format!("function {name} requires text arguments"));
            };
            let pos = hay
                .find(needle.as_str())
                .map(|byte_idx| hay[..byte_idx].chars().count() + 1)
                .unwrap_or(0);
            Value::Int(pos as i64)
        }
        "LPAD" | "RPAD" => {
            // Pad/truncate `str` to `len` display characters with `pad`
            // (default a single space).
            if args.len() < 2 || args.len() > 3 {
                return err(format!(
                    "function {name} takes 2 or 3 arguments, got {}",
                    args.len()
                ));
            }
            if args.iter().any(|v| matches!(v, Value::Null)) {
                return Ok(Value::Null);
            }
            let Value::Str(s) = arg(args, 0, name)? else {
                return err(format!("function {name} requires a text argument"));
            };
            let len = match arg(args, 1, name)? {
                Value::Int(n) if *n >= 0 => *n as usize,
                Value::Int(n) => {
                    return err(format!(
                        "function {name}: length must be non-negative ({n})"
                    ))
                }
                _ => return err(format!("function {name}: length must be an integer")),
            };
            // Bound the padded width: an astronomic length used to reach
            // String::with_capacity directly and abort the whole process
            // on allocation failure (single-writer engine = node-wide DoS
            // from one SELECT). Documents cap out at MAX_DOC_SIZE, so a
            // 1 MiB character budget is far above every legitimate use.
            if len > MAX_PAD_LENGTH {
                return err(format!(
                    "function {name}: length exceeds the supported maximum ({MAX_PAD_LENGTH})"
                ));
            }
            let pad = match args.get(2) {
                Some(Value::Str(p)) if !p.is_empty() => p.clone(),
                Some(Value::Str(_)) => " ".to_string(),
                _ => " ".to_string(),
            };
            let chars: Vec<char> = s.chars().collect();
            if chars.len() >= len {
                return Ok(Value::Str(chars[..len].iter().collect()));
            }
            let fill: Vec<char> = pad.chars().collect();
            let mut out = String::with_capacity(len * 2);
            let need = len - chars.len();
            if name == "LPAD" {
                for k in 0..need {
                    out.push(fill[k % fill.len()]);
                }
                out.extend(chars);
            } else {
                out.extend(chars);
                for k in 0..need {
                    out.push(fill[k % fill.len()]);
                }
            }
            Value::Str(out)
        }
        "GREATEST" | "LEAST" => {
            // Oracle: any NULL argument → NULL; ties return the first.
            if args.is_empty() {
                return err(format!("function {name} requires at least 1 argument"));
            }
            if args.iter().any(|v| matches!(v, Value::Null)) {
                return Ok(Value::Null);
            }
            let mut best = args[0].clone();
            for v in &args[1..] {
                // Prefer the coercion funnel (a Timestamp↔parseable-string
                // pair orders by time, like the predicates do); the total
                // order settles cross-type mixes that never coerce.
                let o = cmp_coerced(v, &best).unwrap_or_else(|| Value::cmp_values(v, &best));
                let better = if name == "GREATEST" {
                    o == Ordering::Greater
                } else {
                    o == Ordering::Less
                };
                if better {
                    best = v.clone();
                }
            }
            best
        }
        "TO_NUMBER" => {
            exact_arity(name, args, 1)?;
            match arg(args, 0, name)?.clone() {
                Value::Int(_) | Value::Float(_) | Value::Decimal(_) => args[0].clone(),
                Value::Str(s) => {
                    let t = s.trim();
                    if let Ok(i) = t.parse::<i64>() {
                        Value::Int(i)
                    } else {
                        // Oracle NUMBER 是精确数值:非整数文本进 DECIMAL 而非 f64
                        match t.parse::<Decimal>() {
                            Ok(d) => Value::Decimal(d),
                            Err(_) => {
                                return err(format!("TO_NUMBER: invalid number {s:?}"));
                            }
                        }
                    }
                }
                _ => return err("function TO_NUMBER requires a text argument"),
            }
        }
        "TO_CHAR" => {
            // Single-argument form: value → text. The Oracle format-mask
            // form requires a typed date/number system and is rejected.
            if args.is_empty() || args.len() > 2 {
                return err(format!(
                    "function {name} takes 1 or 2 arguments, got {}",
                    args.len()
                ));
            }
            if args.len() == 2 {
                return err("TO_CHAR format masks are not supported");
            }
            match arg(args, 0, name)? {
                Value::Str(s) => Value::Str(s.clone()),
                Value::Decimal(d) => Value::Str(d.to_string()),
                other => Value::Str(crate::json::to_string(other).trim_matches('"').to_string()),
            }
        }
        "SYSDATE" => {
            exact_arity(name, args, 0)?;
            Value::Str(now_ms_string())
        }
        "JSON_EXTRACT" | "JSON_TYPE" => {
            // Documents live as JSON text, so point reads into them are the
            // JSON function family's job: extract returns the sub-value
            // (object/array stay structured), type names it SQLite-style.
            // Malformed text or a missing path yields NULL — a query over
            // heterogeneous documents must not abort on one bad row.
            let want_type = name == "JSON_TYPE";
            if args.is_empty() || args.len() > 2 {
                return err(format!(
                    "function {name} takes 1 or 2 arguments, got {}",
                    args.len()
                ));
            }
            let Value::Str(text) = arg(args, 0, name)? else {
                return Ok(Value::Null);
            };
            let parsed = match crate::json::from_str(text) {
                Ok(v) => v,
                Err(_) => return Ok(Value::Null),
            };
            let target = if args.len() == 2 {
                let Value::Str(path) = arg(args, 1, name)? else {
                    return err(format!("function {name} path must be text"));
                };
                match json_path_lookup(&parsed, path) {
                    Some(v) => v.clone(),
                    None => return Ok(Value::Null),
                }
            } else {
                parsed
            };
            if want_type {
                Value::Str(json_type_name(&target).into())
            } else {
                target
            }
        }
        // T-SQL function families live in their own module; None means the
        // name is genuinely unknown to the whole engine.
        other => {
            return match crate::tsql::scalar(other, args) {
                Some(res) => res,
                None => err(format!("unknown function: {other}")),
            }
        }
    })
}

/// Navigate a JSON document by a minimal path grammar: `$` root, `.key`
/// object members, `[n]` array indexes — the point-read subset of the
/// SQLite/JQ path syntax documents stored as JSON text need.
fn json_path_lookup<'a>(root: &'a Value, path: &str) -> Option<&'a Value> {
    let p = path.trim();
    if !p.starts_with('$') {
        return None;
    }
    let mut cur = root;
    let mut rest = &p[1..];
    while !rest.is_empty() {
        if let Some(stripped) = rest.strip_prefix('.') {
            let end = stripped.find(['.', '[']).unwrap_or(stripped.len());
            let key = &stripped[..end];
            if key.is_empty() {
                return None;
            }
            cur = match cur {
                Value::Object(o) => o.get(key)?,
                _ => return None,
            };
            rest = &stripped[end..];
        } else {
            let stripped = rest.strip_prefix('[')?;
            let end = stripped.find(']')?;
            let idx: usize = stripped[..end].parse().ok()?;
            cur = match cur {
                Value::Array(a) => a.get(idx)?,
                _ => return None,
            };
            rest = &stripped[end + 1..];
        }
    }
    Some(cur)
}

/// SQLite-style JSON type names for JSON_TYPE.
fn json_type_name(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Int(_) => "integer",
        Value::Float(_) => "real",
        Value::Decimal(_) => "real",
        Value::Timestamp(_) => "timestamp",
        Value::Str(_) => "text",
        Value::Bytes(_) => "blob",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

/// ORDER BY comparison honoring NULLS FIRST/LAST. Default places NULLs as
/// the smallest value (first on ASC, last on DESC).
fn cmp_maybe_null(a: &Value, b: &Value, nulls_first: Option<bool>) -> Ordering {
    let nulls_first = nulls_first.unwrap_or(true);
    match (a, b) {
        (Value::Null, Value::Null) => Ordering::Equal,
        (Value::Null, _) => {
            if nulls_first {
                Ordering::Less
            } else {
                Ordering::Greater
            }
        }
        (_, Value::Null) => {
            if nulls_first {
                Ordering::Greater
            } else {
                Ordering::Less
            }
        }
        _ => Value::cmp_values(a, b),
    }
}

/// One candidate row of the unindexed ORDER BY top-K heap: extracted sort
/// keys, heap locator, scan sequence (stable tie-break) and the shared
/// per-key directions. The ordering is the row's `ORDER BY` position, so
/// "better" compares less: `BinaryHeap` keeps the worst window entry on top
/// and `into_sorted_vec` yields best first.
struct OrderKeyed<'a> {
    keys: Vec<Value>,
    loc: u64,
    seq: u64,
    dirs: &'a [(bool, Option<bool>)],
}

impl PartialEq for OrderKeyed<'_> {
    fn eq(&self, other: &Self) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}

impl Eq for OrderKeyed<'_> {}

impl PartialOrd for OrderKeyed<'_> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for OrderKeyed<'_> {
    fn cmp(&self, other: &Self) -> Ordering {
        for (i, (asc, nulls_first)) in self.dirs.iter().enumerate() {
            let ord = cmp_maybe_null(&self.keys[i], &other.keys[i], *nulls_first);
            if ord != Ordering::Equal {
                return if *asc { ord } else { ord.reverse() };
            }
        }
        self.seq.cmp(&other.seq)
    }
}

/// True for names that `load_table_factor` resolves to a virtual
/// compatibility view instead of a real heap. Fast paths must not look
/// their rows up in `tables`; keep this list in sync with that resolver.
fn is_compat_view(name: &str) -> bool {
    if name.eq_ignore_ascii_case("DUAL")
        || name.eq_ignore_ascii_case("sqlite_master")
        || name.eq_ignore_ascii_case("sqlite_temporal_master")
        || name.eq_ignore_ascii_case("information_schema.tables")
        || name.eq_ignore_ascii_case("information_schema.columns")
    {
        return true;
    }
    matches!(
        name.to_ascii_uppercase().as_str(),
        "ALL_TABLES"
            | "USER_TABLES"
            | "ALL_TAB_COLUMNS"
            | "USER_TAB_COLUMNS"
            | "ALL_INDEXES"
            | "USER_INDEXES"
    )
}

/// Explicit alias column list (`AS t(a, b)` on a derived table or CTE):
/// renamed positionally, with duplicate or wrong-width lists rejected.
/// `None` means the producing query's own column names are kept.
fn table_alias_columns(
    alias_columns: &[sqlparser::ast::TableAliasColumnDef],
    width: usize,
) -> Result<Option<Vec<String>>> {
    if alias_columns.is_empty() {
        return Ok(None);
    }
    if alias_columns.len() != width {
        return err(format!(
            "alias declares {} columns but the table produces {width}",
            alias_columns.len()
        ));
    }
    let names: Vec<String> = alias_columns.iter().map(|c| c.name.value.clone()).collect();
    let mut seen = std::collections::BTreeSet::new();
    if !names.iter().all(|n| seen.insert(n.clone())) {
        return err("alias column names must be distinct");
    }
    Ok(Some(names))
}

/// Fixed output shape of a known table function. STRING_SPLIT's `ordinal`
/// column only materializes when the third argument is enabled, so the
/// width check for `AS s(v, ord)` follows the actual output, not the
/// argument count.
fn tablefn_static_cols(fname_upper: &str, ordinal_on: bool) -> &'static [&'static str] {
    match fname_upper {
        "STRING_SPLIT" => {
            if ordinal_on {
                &["value", "ordinal"]
            } else {
                &["value"]
            }
        }
        "GENERATE_SERIES" => &["value"],
        _ => &["key", "value", "type"],
    }
}

/// Apply a table function's alias column list (`FROM f(..) AS t(c1, c2)`)
/// as a positional rename over its BARE output columns. Used by every
/// `FROM`-position table function; the APPLY path renames qualified keys
/// itself. Silent omission here made `s.v` read NULL while `s.value`
/// kept working.
fn rename_tablefn_docs(
    alias_obj: &sqlparser::ast::TableAlias,
    fname_upper: &str,
    ordinal_on: bool,
    docs: &mut [Object],
) -> Result<()> {
    let actual: Vec<String> = match docs.first() {
        Some(d) => d.keys().cloned().collect(),
        None => tablefn_static_cols(fname_upper, ordinal_on)
            .iter()
            .map(|s| s.to_string())
            .collect(),
    };
    let Some(rename) = table_alias_columns(&alias_obj.columns, actual.len())? else {
        return Ok(());
    };
    for row in docs.iter_mut() {
        for (new, old) in rename.iter().zip(actual.iter()) {
            if let Some(v) = row.remove(old) {
                row.insert(new.clone(), v);
            }
        }
    }
    Ok(())
}

/// Reject SELECT clause syntax the engine does not implement instead of
/// silently ignoring it (a dropped clause changes results; house rule is
/// loud refusal). Advisory hints (optimizer/index hints) are exempt —
/// they affect planning, not results.
fn reject_unsupported_select_clauses(select: &sqlparser::ast::Select) -> Result<()> {
    if select.into.is_some() {
        return err("SELECT INTO is not supported");
    }
    if select.top.is_some() {
        return err("SELECT TOP is not supported (use LIMIT)");
    }
    // DISTINCT ON is only rejected inside exec_plain_select today — the
    // EXPLAIN mirror plans right past it, describing a statement that can
    // never run.
    if matches!(&select.distinct, Some(sqlparser::ast::Distinct::On(_))) {
        return err("DISTINCT ON is not supported");
    }
    if !select.lateral_views.is_empty() {
        return err("LATERAL VIEW is not supported");
    }
    if select.prewhere.is_some() {
        return err("PREWHERE is not supported");
    }
    if !select.connect_by.is_empty() {
        return err("CONNECT BY is not supported");
    }
    if !select.cluster_by.is_empty() {
        return err("CLUSTER BY is not supported");
    }
    if !select.distribute_by.is_empty() {
        return err("DISTRIBUTE BY is not supported");
    }
    if !select.sort_by.is_empty() {
        return err("SORT BY is not supported");
    }
    if !select.named_window.is_empty() {
        return err("WINDOW clause is not supported");
    }
    if select.value_table_mode.is_some() {
        return err("SELECT AS VALUE/STRUCT is not supported");
    }
    if select.exclude.is_some() {
        return err("SELECT * EXCLUDE is not supported");
    }
    for item in &select.projection {
        // `* EXCLUDE/EXCEPT/REPLACE/RENAME/ILIKE` parse into wildcard
        // options; `exec_plain_select` expands the plain `*`, so anything
        // else here would silently drop the modifier.
        let opts = match item {
            SelectItem::Wildcard(opts) | SelectItem::QualifiedWildcard(_, opts) => opts,
            _ => continue,
        };
        if opts.opt_ilike.is_some()
            || opts.opt_exclude.is_some()
            || opts.opt_except.is_some()
            || opts.opt_replace.is_some()
            || opts.opt_rename.is_some()
            || opts.opt_alias.is_some()
        {
            return err("SELECT * EXCLUDE/EXCEPT/REPLACE/RENAME/ILIKE is not supported");
        }
    }
    if select.select_modifiers.is_some() {
        return err("SELECT modifiers are not supported");
    }
    Ok(())
}

/// Query-level clause guard; see [`reject_unsupported_select_clauses`].
fn reject_unsupported_query_clauses(query: &Query) -> Result<()> {
    if !query.locks.is_empty() {
        return err("FOR UPDATE/FOR SHARE is not supported");
    }
    if query.for_clause.is_some() {
        return err("FOR XML/FOR JSON is not supported");
    }
    if query.settings.is_some() {
        return err("SETTINGS is not supported");
    }
    if query.format_clause.is_some() {
        return err("FORMAT is not supported");
    }
    if !query.pipe_operators.is_empty() {
        return err("pipe operators are not supported");
    }
    // ClickHouse `LIMIT n BY cols`:dropping the BY list would silently run
    // a bare LIMIT — the red line on clause-level silent ignoring.
    if let Some(sqlparser::ast::LimitClause::LimitOffset { limit_by, .. }) = &query.limit_clause {
        if !limit_by.is_empty() {
            return err("LIMIT ... BY is not supported");
        }
    }
    Ok(())
}

/// T-SQL `SELECT TOP (n) [WITH TIES]`: the generic parser carries the
/// clause in `Select.top`; translate it onto the standard LIMIT/FETCH
/// machinery so the executor sees one pagination path (and the ORDER BY
/// requirement of WITH TIES is enforced by the FETCH branch). PERCENT has
/// no pre-count pass to size it and stays a loud error. Set-operation
/// arms re-enter `exec_query_body`, so TOP inside a UNION arm scopes to
/// that arm — SQL Server semantics.
fn rewrite_tsql_top(mut query: Query) -> Result<Query> {
    let top = match query.body.as_mut() {
        SetExpr::Select(select) => select.top.take(),
        _ => None,
    };
    let Some(top) = top else {
        return Ok(query);
    };
    if top.percent {
        return err("SELECT TOP ... PERCENT is not supported (use LIMIT)");
    }
    let n = match top.quantity {
        Some(sqlparser::ast::TopQuantity::Constant(n)) => {
            SqlExpr::Value(sqlparser::ast::Value::Number(n.to_string(), false).into())
        }
        Some(sqlparser::ast::TopQuantity::Expr(e)) => e,
        None => return err("SELECT TOP requires a row count"),
    };
    if top.with_ties {
        if query.fetch.is_some() {
            return err("TOP WITH TIES cannot be combined with FETCH");
        }
        query.fetch = Some(sqlparser::ast::Fetch {
            with_ties: true,
            percent: false,
            quantity: Some(n),
        });
    } else {
        if query.limit_clause.is_some() {
            return err("TOP cannot be combined with LIMIT");
        }
        query.limit_clause = Some(LimitClause::LimitOffset {
            limit: Some(n),
            offset: None,
            limit_by: vec![],
        });
    }
    Ok(query)
}

fn value_to_literal(v: Value) -> Result<SqlExpr> {
    use sqlparser::ast::Value as V;
    Ok(match v {
        Value::Null => SqlExpr::Value(V::Null.into()),
        Value::Bool(b) => SqlExpr::Value(V::Boolean(b).into()),
        Value::Int(i) => SqlExpr::Value(V::Number(i.to_string(), false).into()),
        // Debug formatting keeps integral floats distinguishable from Int
        // (`3.0` prints "3" via Display and would re-parse as Int(3)); same
        // rule value_literal applies to dumps.
        Value::Float(f) => SqlExpr::Value(V::Number(format!("{f:?}"), false).into()),
        Value::Str(s) => SqlExpr::Value(V::SingleQuotedString(s).into()),
        // Exact/exotic scalars ride as subquery-independent expressions the
        // same way value_literal renders them for dumps — a bare number or
        // string would degrade Decimal to Float and Timestamp to Str.
        other @ (Value::Decimal(_) | Value::Timestamp(_)) => {
            parse_expr_text(&value_literal(&other)?)?
        }
        Value::Bytes(b) => {
            let mut hex = String::with_capacity(b.len() * 2 + 3);
            hex.push_str("x'");
            for byte in &b {
                hex.push_str(&format!("{byte:02x}"));
            }
            hex.push('\'');
            parse_expr_text(&hex)?
        }
        other => return err(format!("cannot inline value as literal: {other:?}")),
    })
}

/// Substitute the proposed-row references in a DO UPDATE SET/WHERE tree:
/// `EXCLUDED.col` (PostgreSQL) and `VALUES(col)` (MySQL) become literals of
/// the candidate row's values. Descends the DIRECT expression tree only —
/// a subquery body mentioning the proposed row is rejected afterwards
/// (see [`upsert_proposed_in_subquery`]), so a reference can never
/// silently mis-resolve to the existing row's same-named column.
fn subst_upsert_proposed(e: &mut SqlExpr, proposed: &Object) -> Result<()> {
    match e {
        SqlExpr::CompoundIdentifier(parts)
            if parts.len() >= 2 && parts[0].value.eq_ignore_ascii_case("EXCLUDED") =>
        {
            let leaf = parts.last().map(|p| p.value.clone()).unwrap_or_default();
            let v = proposed.get(&leaf).cloned().unwrap_or(Value::Null);
            *e = value_to_literal(v)?;
        }
        SqlExpr::Function(f) if is_values_call(f) => {
            let col = values_call_column(f);
            let v = proposed.get(&col).cloned().unwrap_or(Value::Null);
            *e = value_to_literal(v)?;
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            subst_upsert_proposed(left, proposed)?;
            subst_upsert_proposed(right, proposed)?;
        }
        SqlExpr::UnaryOp { expr, .. } => subst_upsert_proposed(expr, proposed)?,
        SqlExpr::Nested(inner) => subst_upsert_proposed(inner, proposed)?,
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            subst_upsert_proposed(expr, proposed)?;
            subst_upsert_proposed(low, proposed)?;
            subst_upsert_proposed(high, proposed)?;
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            subst_upsert_proposed(l, proposed)?;
            subst_upsert_proposed(r, proposed)?;
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            subst_upsert_proposed(expr, proposed)?;
            subst_upsert_proposed(pattern, proposed)?;
        }
        SqlExpr::InList { expr, list, .. } => {
            subst_upsert_proposed(expr, proposed)?;
            for item in list {
                subst_upsert_proposed(item, proposed)?;
            }
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(op) = operand {
                subst_upsert_proposed(op, proposed)?;
            }
            for w in conditions.iter_mut() {
                subst_upsert_proposed(&mut w.condition, proposed)?;
                subst_upsert_proposed(&mut w.result, proposed)?;
            }
            if let Some(el) = else_result {
                subst_upsert_proposed(el, proposed)?;
            }
        }
        SqlExpr::Cast { expr, .. } => subst_upsert_proposed(expr, proposed)?,
        SqlExpr::IsNull(inner) | SqlExpr::IsNotNull(inner) => {
            subst_upsert_proposed(inner, proposed)?
        }
        SqlExpr::Floor { expr, .. } | SqlExpr::Ceil { expr, .. } => {
            subst_upsert_proposed(expr, proposed)?
        }
        SqlExpr::Substring {
            expr,
            substring_from,
            substring_for,
            ..
        } => {
            subst_upsert_proposed(expr, proposed)?;
            if let Some(f) = substring_from {
                subst_upsert_proposed(f, proposed)?;
            }
            if let Some(f) = substring_for {
                subst_upsert_proposed(f, proposed)?;
            }
        }
        SqlExpr::Trim {
            expr,
            trim_what,
            trim_characters,
            ..
        } => {
            subst_upsert_proposed(expr, proposed)?;
            if let Some(w) = trim_what {
                subst_upsert_proposed(w, proposed)?;
            }
            if let Some(chars) = trim_characters {
                for c in chars {
                    subst_upsert_proposed(c, proposed)?;
                }
            }
        }
        SqlExpr::Position { expr, r#in } => {
            subst_upsert_proposed(expr, proposed)?;
            subst_upsert_proposed(r#in, proposed)?;
        }
        SqlExpr::Overlay {
            expr,
            overlay_what,
            overlay_from,
            overlay_for,
        } => {
            subst_upsert_proposed(expr, proposed)?;
            subst_upsert_proposed(overlay_what, proposed)?;
            subst_upsert_proposed(overlay_from, proposed)?;
            if let Some(f) = overlay_for {
                subst_upsert_proposed(f, proposed)?;
            }
        }
        SqlExpr::Tuple(items) => {
            for item in items {
                subst_upsert_proposed(item, proposed)?;
            }
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &mut f.args {
                for a in &mut list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        subst_upsert_proposed(inner, proposed)?;
                    }
                }
            }
            if let Some(filter) = &mut f.filter {
                subst_upsert_proposed(filter, proposed)?;
            }
        }
        // Subquery bodies stay untouched (checked by the caller).
        SqlExpr::InSubquery { expr, .. } => subst_upsert_proposed(expr, proposed)?,
        SqlExpr::AnyOp { left, .. } | SqlExpr::AllOp { left, .. } => {
            subst_upsert_proposed(left, proposed)?
        }
        _ => {}
    }
    Ok(())
}

/// `VALUES(col)` — the MySQL proposed-row reference, parsed as a function.
/// Recognizes exactly `VALUES(<single column>)`; anything else is a normal
/// function (and stays one).
fn is_values_call(f: &sqlparser::ast::Function) -> bool {
    f.name.0.last().is_some_and(|p| {
        p.as_ident()
            .is_some_and(|i| i.value.eq_ignore_ascii_case("VALUES"))
    }) && matches!(
        &f.args,
        sqlparser::ast::FunctionArguments::List(list)
            if list.args.len() == 1
                && matches!(
                    list.args.first(),
                    Some(sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(
                            SqlExpr::Identifier(_)
                        )
                    ))
                )
    )
}

fn values_call_column(f: &sqlparser::ast::Function) -> String {
    match &f.args {
        sqlparser::ast::FunctionArguments::List(list) if list.args.len() == 1 => {
            match list.args.first() {
                Some(sqlparser::ast::FunctionArg::Unnamed(
                    sqlparser::ast::FunctionArgExpr::Expr(SqlExpr::Identifier(i)),
                )) => i.value.clone(),
                _ => String::new(),
            }
        }
        _ => String::new(),
    }
}

/// True when a DO UPDATE SET/WHERE tree still references the proposed row
/// AFTER the direct-tree substitution — i.e. inside a subquery body, which
/// the driver does not rewrite. Subquery bodies are probed textually
/// (uppercased rendering); a false positive from a string literal is a
/// loud error, never a silent mis-resolution.
fn upsert_proposed_in_subquery(e: &SqlExpr) -> bool {
    let subquery_text = |q: &sqlparser::ast::Query| -> bool {
        let t = q.to_string().to_ascii_uppercase();
        t.contains("EXCLUDED") || t.contains("VALUES(")
    };
    match e {
        SqlExpr::Subquery(q) => subquery_text(q),
        SqlExpr::Exists { subquery: q, .. } => subquery_text(q),
        SqlExpr::InSubquery { expr, subquery, .. } => {
            upsert_proposed_in_subquery(expr) || subquery_text(subquery)
        }
        SqlExpr::AnyOp { left, right, .. } | SqlExpr::AllOp { left, right, .. } => {
            upsert_proposed_in_subquery(left) || upsert_proposed_in_subquery(right)
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            upsert_proposed_in_subquery(left) || upsert_proposed_in_subquery(right)
        }
        SqlExpr::UnaryOp { expr, .. } => upsert_proposed_in_subquery(expr),
        SqlExpr::Nested(inner) => upsert_proposed_in_subquery(inner),
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            upsert_proposed_in_subquery(expr)
                || upsert_proposed_in_subquery(low)
                || upsert_proposed_in_subquery(high)
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            upsert_proposed_in_subquery(l) || upsert_proposed_in_subquery(r)
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            upsert_proposed_in_subquery(expr) || upsert_proposed_in_subquery(pattern)
        }
        SqlExpr::InList { expr, list, .. } => {
            upsert_proposed_in_subquery(expr) || list.iter().any(upsert_proposed_in_subquery)
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            operand
                .as_ref()
                .is_some_and(|x| upsert_proposed_in_subquery(x))
                || conditions.iter().any(|w| {
                    upsert_proposed_in_subquery(&w.condition)
                        || upsert_proposed_in_subquery(&w.result)
                })
                || else_result
                    .as_ref()
                    .is_some_and(|x| upsert_proposed_in_subquery(x))
        }
        SqlExpr::Cast { expr, .. } => upsert_proposed_in_subquery(expr),
        SqlExpr::Function(f) => {
            let args_hit = match &f.args {
                sqlparser::ast::FunctionArguments::List(list) => list.args.iter().any(|a| {
                    matches!(
                        a,
                        sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(inner)
                        ) if upsert_proposed_in_subquery(inner)
                    )
                }),
                _ => false,
            };
            args_hit
                || f.filter
                    .as_ref()
                    .is_some_and(|x| upsert_proposed_in_subquery(x))
        }
        _ => false,
    }
}

/// ROWNUM guard for the DO UPDATE arm (same rule as UPDATE): assignments
/// and the WHERE predicate see no row stream to number.
fn refs_rownum_in(assignments: &[sqlparser::ast::Assignment], selection: &Option<SqlExpr>) -> bool {
    assignments.iter().any(|a| refs_rownum(&a.value)) || selection.as_ref().is_some_and(refs_rownum)
}

/// Column-restricted grant support: for a single-table SELECT (no joins,
/// no set operations, no WITH, no table functions) return the table name
/// plus every column the statement references. `None` = the shape cannot
/// be attributed (wildcards, subqueries whose columns would need deeper
/// analysis, exotic clauses) — callers must treat None as fail-closed and
/// refuse the statement for column-restricted grants.
pub fn single_table_select_refs(stmt: &Statement) -> Option<(String, Vec<String>)> {
    let Statement::Query(q) = stmt else {
        return None;
    };
    single_table_query_refs(q)
}

/// [`single_table_select_refs`] over a bare query — the INSERT ... SELECT
/// source (used by the write path's column-grant attribution).
pub fn single_table_query_refs(q: &Query) -> Option<(String, Vec<String>)> {
    use sqlparser::ast::{GroupByExpr, OrderByKind, SelectItem, SetExpr, TableFactor};
    if q.with.is_some() {
        return None;
    }
    // LIMIT/OFFSET/FETCH reference no columns; ORDER BY may.
    let SetExpr::Select(select) = q.body.as_ref() else {
        return None;
    };
    if select.from.len() != 1 {
        return None;
    }
    let twj = &select.from[0];
    if !twj.joins.is_empty() {
        return None;
    }
    let sqlparser::ast::TableWithJoins { relation, .. } = twj;
    let TableFactor::Table {
        name,
        alias,
        args: None,
        ..
    } = relation
    else {
        return None;
    };
    if alias.is_some() {
        // An alias renames the row namespace; a column-restricted grant
        // qualifies only the plain single-table spelling.
        return None;
    }
    // A wildcard function argument (COUNT(*)) reads every column of every
    // row — as unattributable as `SELECT *`.
    fn expr_has_star(e: &SqlExpr) -> bool {
        use sqlparser::ast::{FunctionArg, FunctionArgExpr, FunctionArguments};
        match e {
            SqlExpr::Function(f) => match &f.args {
                FunctionArguments::List(list) => list.args.iter().any(|a| {
                    matches!(a, FunctionArg::Unnamed(FunctionArgExpr::Wildcard))
                        || matches!(
                            a,
                            FunctionArg::Unnamed(FunctionArgExpr::Expr(inner))
                                if expr_has_star(inner)
                        )
                }),
                _ => false,
            },
            SqlExpr::BinaryOp { left, right, .. } => expr_has_star(left) || expr_has_star(right),
            SqlExpr::UnaryOp { expr, .. } => expr_has_star(expr),
            SqlExpr::Nested(inner) => expr_has_star(inner),
            _ => false,
        }
    }
    let table = obj_name(name);
    let mut out = Vec::new();
    for item in &select.projection {
        match item {
            SelectItem::UnnamedExpr(e) => {
                if expr_has_star(e) {
                    return None;
                }
                column_refs(e, &mut out)?;
            }
            SelectItem::ExprWithAlias { expr, .. } => {
                if expr_has_star(expr) {
                    return None;
                }
                column_refs(expr, &mut out)?;
            }
            // `*` / `t.*` read every column: not attributable to a subset.
            _ => return None,
        }
    }
    if let Some(sel) = &select.selection {
        column_refs(sel, &mut out)?;
    }
    match &select.group_by {
        GroupByExpr::Expressions(exprs, _) => {
            for e in exprs {
                column_refs(e, &mut out)?;
            }
        }
        GroupByExpr::All(_) => return None,
    }
    if let Some(having) = &select.having {
        column_refs(having, &mut out)?;
    }
    if let Some(ob) = &q.order_by {
        if let OrderByKind::Expressions(exprs) = &ob.kind {
            for oe in exprs {
                column_refs(&oe.expr, &mut out)?;
            }
        }
    }
    if let Some(limit) = &q.limit_clause {
        // LIMIT/OFFSET carry no column refs; ANY other decoration (LOCK
        // etc.) is unsupported-shape territory.
        let _ = limit;
    }
    Some((table, out))
}

/// Map a B+ tree error to a SQL error; duplicate hits become the familiar
/// constraint-failure message.
/// Human spelling of a join operator for error messages (sqlparser's
/// `JoinOperator` implements no Display).
fn join_op_name(op: &sqlparser::ast::JoinOperator) -> &'static str {
    use sqlparser::ast::JoinOperator as J;
    match op {
        J::Join(_) => "JOIN",
        J::Inner(_) => "INNER JOIN",
        J::Left(_) => "LEFT JOIN",
        J::LeftOuter(_) => "LEFT OUTER JOIN",
        J::Right(_) => "RIGHT JOIN",
        J::RightOuter(_) => "RIGHT OUTER JOIN",
        J::FullOuter(_) => "FULL OUTER JOIN",
        J::CrossJoin(_) => "CROSS JOIN",
        J::Semi(_) => "SEMI JOIN",
        J::LeftSemi(_) => "LEFT SEMI JOIN",
        J::RightSemi(_) => "RIGHT SEMI JOIN",
        J::Anti(_) => "ANTI JOIN",
        J::LeftAnti(_) => "LEFT ANTI JOIN",
        J::RightAnti(_) => "RIGHT ANTI JOIN",
        J::CrossApply => "CROSS APPLY",
        J::OuterApply => "OUTER APPLY",
        J::AsOf { .. } => "ASOF JOIN",
        J::StraightJoin(_) => "STRAIGHT_JOIN",
        J::ArrayJoin => "ARRAY JOIN",
        J::LeftArrayJoin => "LEFT ARRAY JOIN",
        J::InnerArrayJoin => "INNER ARRAY JOIN",
    }
}

fn index_err(col: &str, e: BTreeError) -> SqlError {
    match e {
        BTreeError::Duplicate => SqlError::Message(format!("UNIQUE constraint failed: {col}")),
        other => SqlError::Message(format!("index error on {col}: {other}")),
    }
}

/// How an index probe should fetch entries.
#[derive(Debug, Clone)]
enum ProbePlan {
    Eq(Value),
    /// Composite-index prefix probe: `lo` is an `Array` prefix of the full
    /// key; every returned key must start with it (element-wise), which the
    /// probe retains after the bounded scan.
    Prefix(Value),
    /// (lower bound, inclusive?), (upper bound, inclusive?) — either optional.
    Range {
        lo: Option<(Value, bool)>,
        hi: Option<(Value, bool)>,
    },
    /// Equality set (`col IN (…)` / rewritten `IN (SELECT …)`): one bounded
    /// Eq walk per element, merged back into key order. Distinct elements
    /// probe disjoint key runs (a row holds one column value), so the merge
    /// only has to dedupe repeated list entries.
    In(Vec<Value>),
}

/// Smallest string sorting after every string starting with `prefix`: the
/// last character incremented (`abc` → `abd`). A trailing char::MAX has no
/// successor — incrementing an earlier character instead (`ab\u{10FFFF}` →
/// `ac`) would cut the prefix off, since the prefix itself sorts above the
/// carried bound; the caller then walks open-ended and lets the residual
/// filter drop the tail.
fn str_prefix_successor(prefix: &str) -> Option<String> {
    let mut chars: Vec<char> = prefix.chars().collect();
    let last = chars.pop()?;
    let next = char::from_u32(last as u32 + 1)?;
    chars.push(next);
    Some(chars.into_iter().collect())
}

/// Flatten the top-level AND chain of a WHERE expression. Parenthesized
/// conjuncts unwrap transparently (`(a = 1) AND b = 'x'`): a Nested node
/// carries no semantics of its own, and skipping it used to hide every
/// conjunct from the probe/window planners.
fn flatten_and<'a>(e: &'a SqlExpr, out: &mut Vec<&'a SqlExpr>) {
    if let SqlExpr::BinaryOp {
        left,
        op: BinaryOperator::And,
        right,
    } = e
    {
        flatten_and(left, out);
        flatten_and(right, out);
    } else if let SqlExpr::Nested(inner) = e {
        flatten_and(inner, out);
    } else {
        out.push(e);
    }
}

/// Spelling of a probe conjunct's column reference. A quoted identifier
/// WITH a dot is a literal field name ("v.x" as ONE key): eval resolves it
/// by that exact key, so a qualifier-stripped probe would read a different
/// column than the residual/row evaluation — the conjunct must stay opaque
/// (no probe) instead.
fn probe_col_name(e: &SqlExpr) -> Option<String> {
    match e {
        SqlExpr::Identifier(i) if i.value.contains('.') => None,
        SqlExpr::Identifier(i) => Some(i.value.clone()),
        SqlExpr::CompoundIdentifier(_) => Some(expr_name(e)),
        _ => None,
    }
}

/// Resolve a column reference (bare, table- or alias-qualified) to its bare
/// column name when it names a column of this table. `dotted` is the
/// table's literal-dotted-field marker: while set, a qualifier-stripped
/// reference may collide with a literal "a.b" key (eval tries that key
/// first), so stripping is refused.
fn unqualified_col(ident: &str, table: &str, alias: Option<&str>, dotted: bool) -> Option<String> {
    if let Some(c) = ident.strip_prefix(&format!("{table}.")) {
        if dotted {
            return None;
        }
        return Some(c.to_string());
    }
    if let Some(a) = alias {
        if let Some(c) = ident.strip_prefix(&format!("{a}.")) {
            if dotted {
                return None;
            }
            return Some(c.to_string());
        }
    }
    if !ident.contains('.') {
        return Some(ident.to_string());
    }
    None
}

/// Match ORDER BY to one of the table's B+ trees: every key resolves to the
/// tree's columns in order, all one direction, default NULL placement
/// (NULLS FIRST/LAST is a different order — the sort path handles it). The
/// trees omit NULL keys (`index_key_of`), so every key column must be
/// declared NOT NULL or rows would silently go missing from the walk.
///
/// `effective` carries each ORDER BY key's sort SOURCE — the output-column
/// expression when the key name hits a projection alias (the resolution
/// `apply_order_limit` uses), the raw key otherwise — parallel to `exprs`.
fn order_walk_index(
    meta: &TableMeta,
    table: &str,
    alias: Option<&str>,
    selection: &Option<SqlExpr>,
    exprs: &[sqlparser::ast::OrderByExpr],
    effective: &[&SqlExpr],
) -> Option<(String, bool)> {
    let mut cols = Vec::with_capacity(exprs.len());
    let mut asc = true;
    for (i, o) in exprs.iter().enumerate() {
        if o.options.nulls_first.is_some() {
            return None;
        }
        let col = unqualified_col(
            &probe_col_name(effective[i])?,
            table,
            alias,
            meta.dotted_keys,
        )?;
        let this_asc = o.options.asc.unwrap_or(true);
        if i == 0 {
            asc = this_asc;
        } else if asc != this_asc {
            return None;
        }
        cols.push(col);
    }
    if cols.iter().any(|c| !meta.not_null.contains(c)) {
        return None;
    }
    meta.index_roots.keys().find_map(|root| {
        // Path indexes (design 005) hold extracted values, not column
        // values — an ORDER BY over the column name must not walk them.
        let is_path = meta
            .index_defs
            .iter()
            .any(|d| d.name == *root && d.path.is_some());
        // A PARTIAL index walks only its qualifying rows: without a WHERE
        // implying the predicate the window would silently drop the rest.
        let partial_blocked = meta
            .index_defs
            .iter()
            .find(|d| d.name == *root)
            .and_then(|d| d.pred.as_deref())
            .is_some_and(|p| {
                selection
                    .as_ref()
                    .is_none_or(|c| !query_implies_pred(c, p, table, alias))
            });
        (!is_path && !partial_blocked && meta.index_columns_of(root) == cols)
            .then(|| (root.clone(), asc))
    })
}

/// Resolve a column reference (bare or table/alias-qualified) to an indexed
/// column of this table, if it has one.
/// Resolve a column reference to an index root usable for a scalar probe.
/// Only roots that are single-column trees for exactly that column qualify:
/// a composite tree is keyed by the index *name* (or arbitrary root_key), so
/// accepting `index_roots.contains_key(ident)` blindly made a column that
/// shares a composite index's name probe an Array-keyed tree and silently
/// return nothing.
/// CREATE-time validation of a partial-index predicate: row-local only —
/// bare identifiers that name table columns, literals, operators, scalar
/// functions, IS NULL / IN (constants) / BETWEEN / LIKE. Subqueries,
/// aggregates, window functions and qualified names are refused (a probe
/// gate evaluates the predicate per row with the same row-local evaluator,
/// so anything richer could diverge between gate and maintenance). The
/// caller checks identifier existence against the table's columns.
fn validate_partial_pred(e: &SqlExpr) -> Result<SqlExpr> {
    let bad = |what: &str| -> Result<SqlExpr> {
        err(format!(
            "partial-index predicates support row-local expressions only ({what} is not allowed)"
        ))
    };
    match e {
        SqlExpr::Subquery(_) | SqlExpr::Exists { .. } | SqlExpr::InSubquery { .. } => {
            bad("a subquery")
        }
        SqlExpr::CompoundIdentifier(_) => bad("qualified column names (use bare column names)"),
        SqlExpr::Function(f) => {
            if is_agg_fn(f) {
                return bad("an aggregate");
            }
            if f.over.is_some() {
                return bad("a window function");
            }
            walk_partial_pred_args(f)?;
            Ok(e.clone())
        }
        SqlExpr::Nested(inner) => validate_partial_pred(inner),
        SqlExpr::UnaryOp { expr, .. } => validate_partial_pred(expr),
        SqlExpr::BinaryOp { left, right, .. } => {
            validate_partial_pred(left)?;
            validate_partial_pred(right)?;
            Ok(e.clone())
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            validate_partial_pred(expr)?;
            validate_partial_pred(low)?;
            validate_partial_pred(high)?;
            Ok(e.clone())
        }
        SqlExpr::InList { expr, list, .. } => {
            validate_partial_pred(expr)?;
            for item in list {
                validate_partial_pred(item)?;
            }
            Ok(e.clone())
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            validate_partial_pred(l)?;
            validate_partial_pred(r)?;
            Ok(e.clone())
        }
        SqlExpr::IsNull(x) | SqlExpr::IsNotNull(x) => validate_partial_pred(x),
        SqlExpr::Cast { expr, .. } => validate_partial_pred(expr),
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            validate_partial_pred(expr)?;
            validate_partial_pred(pattern)
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                validate_partial_pred(o)?;
            }
            for w in conditions {
                validate_partial_pred(&w.condition)?;
                validate_partial_pred(&w.result)?;
            }
            if let Some(r) = else_result {
                validate_partial_pred(r)?;
            }
            Ok(e.clone())
        }
        _ => Ok(e.clone()),
    }
}

fn walk_partial_pred_args(f: &sqlparser::ast::Function) -> Result<()> {
    if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
        for a in &list.args {
            if let sqlparser::ast::FunctionArg::Unnamed(sqlparser::ast::FunctionArgExpr::Expr(
                inner,
            )) = a
            {
                validate_partial_pred(inner)?;
            }
        }
    }
    Ok(())
}

/// Collect the bare column names a predicate references.
fn pred_columns(e: &SqlExpr, out: &mut std::collections::BTreeSet<String>) {
    match e {
        SqlExpr::Identifier(i) => {
            out.insert(i.value.clone());
        }
        SqlExpr::Nested(inner) => pred_columns(inner, out),
        SqlExpr::UnaryOp { expr, .. } => pred_columns(expr, out),
        SqlExpr::BinaryOp { left, right, .. } => {
            pred_columns(left, out);
            pred_columns(right, out);
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            pred_columns(expr, out);
            pred_columns(low, out);
            pred_columns(high, out);
        }
        SqlExpr::InList { expr, list, .. } => {
            pred_columns(expr, out);
            for item in list {
                pred_columns(item, out);
            }
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            pred_columns(l, out);
            pred_columns(r, out);
        }
        SqlExpr::IsNull(x) | SqlExpr::IsNotNull(x) => pred_columns(x, out),
        SqlExpr::Cast { expr, .. } => pred_columns(expr, out),
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            pred_columns(expr, out);
            pred_columns(pattern, out);
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                pred_columns(o, out);
            }
            for w in conditions {
                pred_columns(&w.condition, out);
                pred_columns(&w.result, out);
            }
            if let Some(r) = else_result {
                pred_columns(r, out);
            }
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        pred_columns(inner, out);
                    }
                }
            }
        }
        _ => {}
    }
}

/// One query conjunct's equality binding: (bare column, values) — `col =
/// const` yields one value, `col IN (consts)` the whole list. NULL never
/// binds (it binds to nothing).
fn pred_eq_binding(q: &SqlExpr) -> Option<(String, Vec<Value>)> {
    match q {
        SqlExpr::BinaryOp {
            left,
            op: BinaryOperator::Eq,
            right,
        } => {
            let (id_side, lit_side) = match (left.as_ref(), right.as_ref()) {
                (SqlExpr::Identifier(i), other) => (i, other),
                (other, SqlExpr::Identifier(i)) => (i, other),
                _ => return None,
            };
            let v = eval_const(lit_side).ok()?;
            if matches!(v, Value::Null) {
                return None;
            }
            Some((id_side.value.clone(), vec![v]))
        }
        SqlExpr::InList {
            expr,
            list,
            negated: false,
            ..
        } => {
            let SqlExpr::Identifier(i) = expr.as_ref() else {
                return None;
            };
            let vals: Option<Vec<Value>> = list.iter().map(|el| eval_const(el).ok()).collect();
            let vals = vals?;
            if vals.is_empty() || vals.iter().any(|v| matches!(v, Value::Null)) {
                return None;
            }
            Some((i.value.clone(), vals))
        }
        _ => None,
    }
}

/// Substitute every bare `col` identifier in `e` with the literal `v`
/// (recursive over the row-local shapes [`validate_partial_pred`] accepts).
/// Returns false when the shape escapes substitution.
fn pred_subst_ident(e: &mut SqlExpr, col: &str, v: &Value) -> bool {
    let mut replaced = false;
    match e {
        SqlExpr::Identifier(i) if i.value == col => {
            if let Ok(lit) = value_to_literal(v.clone()) {
                *e = lit;
                replaced = true;
            }
        }
        SqlExpr::Nested(inner) => replaced = pred_subst_ident(inner, col, v),
        SqlExpr::UnaryOp { expr, .. } => replaced = pred_subst_ident(expr, col, v),
        SqlExpr::BinaryOp { left, right, .. } => {
            let a = pred_subst_ident(left, col, v);
            let b = pred_subst_ident(right, col, v);
            replaced = a || b;
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            let a = pred_subst_ident(expr, col, v);
            let b = pred_subst_ident(low, col, v);
            let c = pred_subst_ident(high, col, v);
            replaced = a || b || c;
        }
        SqlExpr::InList { expr, list, .. } => {
            replaced = pred_subst_ident(expr, col, v);
            for item in list {
                replaced |= pred_subst_ident(item, col, v);
            }
        }
        SqlExpr::IsDistinctFrom(l, r) | SqlExpr::IsNotDistinctFrom(l, r) => {
            let a = pred_subst_ident(l, col, v);
            let b = pred_subst_ident(r, col, v);
            replaced = a || b;
        }
        SqlExpr::IsNull(x) | SqlExpr::IsNotNull(x) => replaced = pred_subst_ident(x, col, v),
        SqlExpr::Cast { expr, .. } => replaced = pred_subst_ident(expr, col, v),
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            let a = pred_subst_ident(expr, col, v);
            let b = pred_subst_ident(pattern, col, v);
            replaced = a || b;
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                replaced |= pred_subst_ident(o, col, v);
            }
            for w in conditions {
                replaced |= pred_subst_ident(&mut w.condition, col, v);
                replaced |= pred_subst_ident(&mut w.result, col, v);
            }
            if let Some(r) = else_result {
                replaced |= pred_subst_ident(r, col, v);
            }
        }
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &mut f.args {
                for a in &mut list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        replaced |= pred_subst_ident(inner, col, v);
                    }
                }
            }
        }
        _ => {}
    }
    replaced
}

/// True when the query's WHERE clause implies the partial-index predicate —
/// the gate that makes a probe over the partial tree a SUPERSET of the
/// answer set (every row the WHERE keeps satisfies the predicate, so it is
/// in the tree). Conservative conjunction proof: both sides decompose into
/// AND-conjuncts; every predicate conjunct must be implied by some query
/// conjunct via (a) normalized syntactic identity, or (b) equality
/// substitution — `col = const` / `col IN (consts)` implies any
/// single-column conjunct that evaluates TRUE under every bound value.
/// Anything unprovable leaves the index invisible to the query (full scan /
/// other indexes) — never wrong rows.
fn query_implies_pred(cond: &SqlExpr, pred_text: &str, table: &str, alias: Option<&str>) -> bool {
    let _ = (table, alias);
    let Ok(pred) = parse_expr_text(pred_text) else {
        return false;
    };
    let mut pred_terms = Vec::new();
    flatten_and(&pred, &mut pred_terms);
    let mut q_terms = Vec::new();
    flatten_and(cond, &mut q_terms);
    'every_term: for t in &pred_terms {
        let mut t_cols = std::collections::BTreeSet::new();
        pred_columns(t, &mut t_cols);
        let t_key = format!("{t}");
        for q in &q_terms {
            if format!("{q}") == t_key {
                continue 'every_term;
            }
            if let Some((col, vals)) = pred_eq_binding(q) {
                let implied = t_cols.len() == 1
                    && t_cols.contains(&col)
                    && vals.iter().all(|v| {
                        let mut sub: SqlExpr = (*t).clone();
                        pred_subst_ident(&mut sub, &col, v)
                            && matches!(eval_expr(&sub, &Object::new()), Ok(Value::Bool(true)))
                    });
                if implied {
                    continue 'every_term;
                }
            }
        }
        return false;
    }
    true
}

fn resolve_indexed_col(
    ident: &str,
    table: &str,
    alias: Option<&str>,
    meta: &TableMeta,
) -> Option<String> {
    let scalar_root = |col: &str| -> Option<String> {
        // The root must exist and name exactly this one column. Testing
        // `index_columns_of` alone is not enough: for an unknown key it
        // synthesizes `[key]`, which would accept any column name.
        if !meta.index_roots.contains_key(col) {
            return None;
        }
        // A JSON path index keyed by the column's NAME (root_key == index
        // name, design 005) holds extracted values, not column values —
        // it must never serve a scalar column probe. Same for a PARTIAL
        // index under that name (its tree is a gated subset).
        if meta
            .index_defs
            .iter()
            .any(|d| d.name == col && (d.path.is_some() || d.pred.is_some()))
        {
            return None;
        }
        let cols = meta.index_columns_of(col);
        (cols.len() == 1 && cols[0] == col).then(|| col.to_string())
    };
    // While the table carries literal dotted field names, eval may answer a
    // qualified reference through the exact "a.b" key — the stripped tree
    // window is not a superset, so refuse to strip.
    if !meta.dotted_keys {
        if let Some(col) = ident.strip_prefix(&format!("{table}.")) {
            if let Some(c) = scalar_root(col) {
                return Some(c);
            }
        }
        if let Some(a) = alias {
            if let Some(col) = ident.strip_prefix(&format!("{a}.")) {
                if let Some(c) = scalar_root(col) {
                    return Some(c);
                }
            }
        }
    }
    if !ident.contains('.') {
        if let Some(c) = scalar_root(ident) {
            return Some(c);
        }
    }
    None
}

/// Choose an index plan from a WHERE expression: an equality conjunct on an
/// indexed column wins; otherwise range bounds on one indexed column. The
/// bool is true when the plan subsumes the whole condition — every conjunct
/// is implied by the probe, so callers may trust the entry count and stop a
/// window walk at the requested end (no residual re-filter).
/// Collapse the collected range bounds (op, value) into ProbePlan's
/// (lo, hi) pair: the TIGHTEST bound wins on each side — repeated
/// inequalities narrow, mirroring the scalar branch's invariant
/// (`a > 10 AND a > 18` must probe from 18). The probe re-filters
/// row-exactly anyway when the plan is inexact, and an exact plan cannot
/// carry contradicting bounds because eq_conflict/path conflict detection
/// refuses those shapes.
fn path_bound(bounds: &[(BinaryOperator, Value)], lower: bool) -> Option<(Value, bool)> {
    let mut best: Option<(Value, bool)> = None;
    for (op, v) in bounds {
        let inclusive = matches!(op, BinaryOperator::GtEq | BinaryOperator::LtEq);
        let is_lower = matches!(op, BinaryOperator::Gt | BinaryOperator::GtEq);
        if is_lower != lower {
            continue;
        }
        best = Some(match best {
            None => (v.clone(), inclusive),
            Some((bv, bi)) => {
                let ord = Value::cmp_values(&bv, v);
                // Keep the bound that narrows the window: the larger lower
                // bound / the smaller upper bound.
                if (lower && ord == std::cmp::Ordering::Less)
                    || (!lower && ord == std::cmp::Ordering::Greater)
                {
                    (v.clone(), inclusive)
                } else {
                    (bv, bi)
                }
            }
        });
    }
    best
}

/// A range-probe target: the tree root key plus the probed column (a FULL
/// single-column index roots at the column itself; a gated PARTIAL index
/// roots at its index name).
type ProbeTarget = (String, String, Vec<(BinaryOperator, Value)>);

fn probe_plan(
    cond: &SqlExpr,
    meta: &TableMeta,
    table: &str,
    alias: Option<&str>,
) -> Option<(String, ProbePlan, bool)> {
    let mut conjuncts = Vec::new();
    flatten_and(cond, &mut conjuncts);
    let empty = Object::new();
    // A conjunct the plan cannot consume: its filter still has to run after
    // the probe, so the plan is inexact.
    let mut opaque = false;
    // All equality conjuncts: composite prefixes need every leading column's
    // value, not just the first one seen.
    let mut eq_map: std::collections::BTreeMap<String, Value> = std::collections::BTreeMap::new();
    // `a = 1 AND a = 2`: a plan built from one of the values would return
    // rows the other conjunct excludes, and `covered` sees a single map key
    // so the plan would be declared exact. Refuse any index plan instead.
    let mut eq_conflict = false;
    // (tree root key, column name, …): a FULL single-column index roots at
    // the column itself; a gated PARTIAL index roots at its index name.
    let mut eq: Option<(String, String, Value)> = None;
    let mut range: Option<ProbeTarget> = None;
    // JSON path conjuncts (design 005): JSON_EXTRACT(col,'$.p') op const.
    // One (col, path) target per plan; a second distinct target or a mix
    // with named-column conjuncts stays usable but inexact.
    let mut path_target: Option<(String, String)> = None;
    let mut path_eq: Option<Value> = None;
    let mut path_range: Option<Vec<(BinaryOperator, Value)>> = None;
    // Scalar equality set: `col IN (…)` on a single-column tree. One target
    // per plan; a second IN list rides the residual filter (inexact).
    let mut in_target: Option<(String, String, Vec<Value>)> = None;
    // Column → tree-root resolution for probe candidates: the column's own
    // full single-column tree, or — when the query WHERE implies the
    // predicate — a single-column PARTIAL index (its tree keys by the index
    // name). Not implied → the partial index is invisible (superset safety).
    let resolve_probe = |name: &str| -> Option<(String, String)> {
        if let Some(c) = resolve_indexed_col(name, table, alias, meta) {
            return Some((c.clone(), c));
        }
        let bare = unqualified_col(name, table, alias, meta.dotted_keys)?;
        for d in &meta.index_defs {
            if d.pred.is_none() || d.columns.len() != 1 || d.columns[0] != *bare {
                continue;
            }
            if !meta.index_roots.contains_key(&d.name) {
                continue;
            }
            if query_implies_pred(cond, d.pred.as_deref().expect("pred set"), table, alias) {
                return Some((d.name.clone(), bare.to_string()));
            }
        }
        None
    };
    for c in conjuncts {
        // col BETWEEN low AND high — a closed range on one indexed column,
        // exactly the two inclusive bounds the Range plan already walks.
        // NOT BETWEEN and NULL bounds stay opaque (NULL never matches, the
        // residual filter decides).
        if let SqlExpr::Between {
            expr,
            negated,
            low,
            high,
        } = c
        {
            if *negated {
                opaque = true;
                continue;
            }
            let name = match probe_col_name(expr.as_ref()) {
                Some(n) => n,
                None => {
                    opaque = true;
                    continue;
                }
            };
            let Some((root, col)) = resolve_probe(&name) else {
                opaque = true;
                continue;
            };
            let (Ok(lo), Ok(hi)) = (eval_const(low), eval_const(high)) else {
                opaque = true;
                continue;
            };
            if matches!(lo, Value::Null) || matches!(hi, Value::Null) {
                opaque = true;
                continue;
            }
            match &mut range {
                Some((_, c2, bounds)) if *c2 == col => {
                    bounds.push((BinaryOperator::GtEq, lo));
                    bounds.push((BinaryOperator::LtEq, hi));
                }
                None => {
                    range = Some((
                        root,
                        col,
                        vec![(BinaryOperator::GtEq, lo), (BinaryOperator::LtEq, hi)],
                    ));
                }
                _ => opaque = true,
            }
            continue;
        }
        // col IN (list of constants): the multi-probe plan. NULL elements
        // are dropped from the probe keys (the tree holds no NULL keys);
        // on a nullable column that costs exactness — NULL rows match the
        // predicate via NULL = NULL — so the conjunct rides the residual
        // filter instead. Non-constant elements forfeit the probe.
        if let SqlExpr::InList {
            expr,
            list,
            negated,
        } = c
        {
            if *negated {
                opaque = true;
                continue;
            }
            let name = match probe_col_name(expr.as_ref()) {
                Some(n) => n,
                None => {
                    opaque = true;
                    continue;
                }
            };
            let Some((root, col)) = resolve_probe(&name) else {
                opaque = true;
                continue;
            };
            let mut saw_null_elem = false;
            let mut vals = Vec::with_capacity(list.len());
            for el in list {
                match eval_const(el) {
                    Ok(Value::Null) => saw_null_elem = true,
                    Ok(v) => vals.push(v),
                    Err(_) => {
                        vals.clear();
                        break;
                    }
                }
            }
            if vals.is_empty() {
                opaque = true;
                continue;
            }
            // Under the engine's total order a NULL element makes
            // `v IN (…, NULL)` TRUE for v-NULL rows as well — but the tree
            // holds no NULL keys, so probe candidates can never include
            // them. A nullable column must ride the residual filter (a NOT
            // NULL column has no NULL rows to lose; non-constant elements
            // forfeit the probe).
            if saw_null_elem && !meta.not_null.contains(&col) {
                opaque = true;
                continue;
            }
            match &mut in_target {
                None => in_target = Some((root, col, vals)),
                Some(_) => opaque = true, // second IN list: rides the residual filter
            }
            continue;
        }
        // col LIKE 'literal-prefix%' — a Str band [prefix, successor) on a
        // single-column tree. `_`, `[...]` classes, interior `%` and ILIKE
        // stay opaque; a prefix ending at char::MAX has no finite successor
        // and probes open-ended (inexact — the residual filter drops the
        // tail beyond the prefix run).
        if let SqlExpr::Like {
            expr,
            pattern,
            escape_char,
            negated,
            ..
        } = c
        {
            if *negated {
                opaque = true;
                continue;
            }
            let name = match probe_col_name(expr.as_ref()) {
                Some(n) => n,
                None => {
                    opaque = true;
                    continue;
                }
            };
            let Some((root, col)) = resolve_probe(&name) else {
                opaque = true;
                continue;
            };
            let esc = escape_char.as_ref().and_then(|v| match &v.value {
                sqlparser::ast::Value::SingleQuotedString(s) => s.chars().next(),
                _ => None,
            });
            let Ok(Value::Str(pat)) = eval_const(pattern) else {
                opaque = true;
                continue;
            };
            let Some(prefix) = crate::tsql::like_literal_prefix(&pat, esc) else {
                opaque = true;
                continue;
            };
            let hi = str_prefix_successor(&prefix);
            if hi.is_none() {
                opaque = true;
            }
            let mut bounds = vec![(BinaryOperator::GtEq, Value::Str(prefix))];
            if let Some(h) = hi {
                bounds.push((BinaryOperator::Lt, Value::Str(h)));
            }
            match &mut range {
                Some((_, c2, prev)) if *c2 == col => prev.append(&mut bounds),
                None => range = Some((root, col, bounds)),
                _ => opaque = true,
            }
            continue;
        }
        let SqlExpr::BinaryOp { left, op, right } = c else {
            opaque = true;
            continue;
        };
        // JSON_EXTRACT(col, '$.p') OP const — or the mirror image.
        let json_side = [left.as_ref(), right.as_ref()].into_iter().find(|e| {
            matches!(e, SqlExpr::Function(f) if f.name.to_string().to_uppercase() == "JSON_EXTRACT")
        });
        if let Some(SqlExpr::Function(f)) = json_side {
            let (Ok((pcol, ppath)), Ok(v)) = (
                parse_json_index_column(f),
                eval_const(if std::ptr::eq(left.as_ref(), json_side.unwrap()) {
                    right
                } else {
                    left
                }),
            ) else {
                opaque = true;
                continue;
            };
            if matches!(v, Value::Null) {
                opaque = true;
                continue;
            }
            let target = (pcol, ppath);
            let mut op = op.clone();
            if !std::ptr::eq(left.as_ref(), json_side.unwrap()) {
                let Some(m) = mirror_op(&op) else {
                    opaque = true;
                    continue;
                };
                op = m;
            }
            match &path_target {
                Some(t) if t != &target => {
                    opaque = true; // second distinct path target: inexact
                    continue;
                }
                None => path_target = Some(target),
                _ => {}
            }
            use BinaryOperator::*;
            match op {
                Eq => {
                    if let Some(prev) = &path_eq {
                        if Value::cmp_values(prev, &v) != Ordering::Equal {
                            eq_conflict = true;
                        }
                    } else {
                        path_eq = Some(v);
                    }
                }
                Gt | GtEq | Lt | LtEq => match &mut path_range {
                    Some(bounds) => bounds.push((op, v)),
                    None => path_range = Some(vec![(op, v)]),
                },
                _ => opaque = true,
            }
            continue;
        }
        // col OP lit, or lit OP col (mirrored)
        let (col_ref, op, lit, mirror) = match (left.as_ref(), right.as_ref()) {
            (SqlExpr::Identifier(_) | SqlExpr::CompoundIdentifier(_), r) => {
                (left.as_ref(), op.clone(), r, false)
            }
            (l, SqlExpr::Identifier(_) | SqlExpr::CompoundIdentifier(_)) => {
                (right.as_ref(), op.clone(), l, true)
            }
            _ => {
                opaque = true;
                continue;
            }
        };
        let name = match probe_col_name(col_ref) {
            Some(n) => n,
            None => {
                opaque = true;
                continue;
            }
        };
        // The literal side must be a constant (subqueries were substituted
        // away; column refs make this conjunct unusable).
        let Ok(v) = eval_expr(lit, &empty) else {
            opaque = true;
            continue;
        };
        if matches!(v, Value::Null) {
            opaque = true;
            continue;
        }
        let op = if mirror { mirror_op(&op)? } else { op };
        use BinaryOperator::*;
        match op {
            Eq => {
                // Composite prefixes match on declared column names, which
                // need not be index_roots keys themselves — collect every
                // equality (raw name), resolve the scalar path separately.
                if let Some(prev) = eq_map.get(&name) {
                    if Value::cmp_values(prev, &v) != Ordering::Equal {
                        eq_conflict = true;
                    }
                }
                if eq.is_none() {
                    if let Some((root, col)) = resolve_probe(&name) {
                        eq = Some((root, col, v.clone()));
                    }
                }
                eq_map.insert(name, v);
            }
            Gt | GtEq | Lt | LtEq => {
                let Some((root, col)) = resolve_probe(&name) else {
                    opaque = true;
                    continue;
                };
                match &mut range {
                    Some((_, c2, bounds)) if *c2 == col => bounds.push((op, v)),
                    None => range = Some((root, col, vec![(op, v)])),
                    _ => opaque = true,
                }
            }
            _ => opaque = true,
        }
    }
    // Equality coverage: every equality conjunct must name one of the probed
    // leading index columns, and do so distinctly (a bare/qualified duplicate
    // of the same column is not proof that both values were consumed).
    let covered = |cols: &[String], map: &std::collections::BTreeMap<String, Value>| -> bool {
        let mut seen = std::collections::BTreeSet::new();
        map.keys().all(|k| {
            let Some(name) = unqualified_col(k, table, alias, meta.dotted_keys) else {
                return false;
            };
            cols.contains(&name) && seen.insert(name)
        })
    };
    if eq_conflict {
        // Two different constants constrain the same column: no index probe
        // can be exact. Fall back to the full scan + residual filter.
        return None;
    }
    // JSON path probe (design 005 §3): a single-column index_def whose
    // column AND path both match, with a live root. exact only when this
    // path condition is the WHOLE plan — any other conjunct forces the
    // residual filter (conservative-correct; the fast paths re-check).
    if let Some((col, ppath)) = &path_target {
        if let Some(def) = meta.index_defs.iter().find(|d| {
            d.path.as_deref() == Some(ppath.as_str())
                && d.columns.as_slice() == std::slice::from_ref(col)
        }) {
            if meta.index_roots.contains_key(&def.name)
                && eq.is_none()
                && range.is_none()
                && eq_map.is_empty()
                && in_target.is_none()
            {
                let exact = !opaque
                    // An Eq plan leaves an unconsumed same-path range
                    // conjunct (`extract = 5 AND extract > 7`) out of the
                    // probe; exactness would claim every hit satisfies the
                    // whole predicate. Mirror the scalar branch's
                    // `range.is_none()` requirement.
                    && !(path_eq.is_some() && path_range.is_some());
                let plan = match (path_eq, path_range) {
                    (Some(v), _) => ProbePlan::Eq(v),
                    (None, Some(bounds)) => {
                        // An unbounded lower side must still reach rows whose
                        // extraction is NULL (`NULL < k` is TRUE — NULL sorts
                        // below everything), but those rows have no tree key.
                        // Only a bounded range is a candidate superset.
                        let lo = path_bound(&bounds, true);
                        lo.as_ref()?;
                        ProbePlan::Range {
                            lo,
                            hi: path_bound(&bounds, false),
                        }
                    }
                    (None, None) => return None,
                };
                return Some((def.name.clone(), plan, exact));
            }
        }
    }
    // Path conjuncts the dedicated plan did not consume (no matching path
    // index, or named-column conjuncts sharing the WHERE) ride the residual
    // filter; every column-plan branch below must stay inexact for them or
    // the exact window would silently drop the JSON predicate.
    if path_target.is_some() {
        opaque = true;
    }
    // Composite-index probe: longest equality prefix over the index columns
    // wins. Full-column equality is an exact key (Eq of the Array); a
    // partial prefix becomes a Prefix scan with a prefix retain. Non-leading
    // columns alone cannot use the tree — they fall back to the scan.
    if !eq_map.is_empty() {
        // eq_map keys keep their SQL spelling (t.a / x.a / a): normalize to
        // bare column names so qualified conjuncts still build the prefix —
        // `covered` already mapped them, only the prefix lookup missed.
        let mut bare_eq: std::collections::BTreeMap<String, Value> =
            std::collections::BTreeMap::new();
        for (k, v) in &eq_map {
            if let Some(name) = unqualified_col(k, table, alias, meta.dotted_keys) {
                bare_eq.insert(name, v.clone());
            }
        }
        let mut best: Option<(String, Vec<Value>)> = None;
        for root_key in meta.index_roots.keys() {
            let cols = meta.index_columns_of(root_key);
            if cols.len() < 2 {
                continue; // single-column trees take the scalar path below
            }
            // Partial composite index: usable only when the query WHERE
            // implies its predicate — otherwise the tree is missing rows the
            // query keeps (superset safety).
            if let Some(d) = meta.index_defs.iter().find(|d| d.name == *root_key) {
                if d.pred.is_some()
                    && !query_implies_pred(cond, d.pred.as_deref().expect("pred set"), table, alias)
                {
                    continue;
                }
            }
            let mut prefix = Vec::with_capacity(cols.len());
            for c in &cols {
                match bare_eq.get(c) {
                    Some(v) => prefix.push(v.clone()),
                    None => break,
                }
            }
            if prefix.is_empty() {
                continue;
            }
            // Partial prefix: a row matching the prefix whose remaining
            // index columns are NULL has no tree key, yet the WHERE (which
            // only constrains the prefix) keeps it — probing would silently
            // drop it. Full-column equality is immune (a NULL anywhere makes
            // the equality false for that row).
            if prefix.len() < cols.len()
                && cols[prefix.len()..]
                    .iter()
                    .any(|c| !meta.not_null.contains(c))
            {
                continue;
            }
            let longer = match &best {
                None => true,
                Some((_, bp)) => prefix.len() > bp.len(),
            };
            if longer {
                best = Some((root_key.clone(), prefix));
            }
        }
        if let Some((root_key, prefix)) = best {
            let cols = meta.index_columns_of(&root_key);
            let prefix_len = prefix.len();
            let plan = if prefix_len == cols.len() {
                ProbePlan::Eq(Value::Array(prefix))
            } else {
                ProbePlan::Prefix(Value::Array(prefix))
            };
            let exact = !opaque
                && range.is_none()
                && in_target.is_none()
                && covered(&cols[..prefix_len], &eq_map);
            return Some((root_key, plan, exact));
        }
    }
    if let Some((root, col, v)) = eq {
        let exact = !opaque
            && range.is_none()
            && in_target.is_none()
            && eq_map.len() == 1
            && eq_map.iter().all(|(k, ev)| {
                unqualified_col(k, table, alias, meta.dotted_keys).as_deref() == Some(&col)
                    && *ev == v
            });
        return Some((root, ProbePlan::Eq(v), exact));
    }
    // Equality-set probe: `col IN (…)` on a single-column tree, one bounded
    // Eq walk per element. NULL elements never match (the tree holds no NULL
    // keys), so the probe subsumes its conjunct exactly; equality/range
    // conjuncts it cannot carry stay in the residual filter and demote
    // exactness. An In plan beats a range when both exist — the list is
    // usually the tighter shape.
    if let Some((iroot, _icol, ivals)) = &in_target {
        if eq.is_none() && path_target.is_none() {
            let exact = !opaque && range.is_none() && eq_map.is_empty();
            return Some((iroot.clone(), ProbePlan::In(ivals.clone()), exact));
        }
        // Unconsumed: the winning plan keeps the IN list in the residual
        // filter — inexact.
        opaque = true;
    }
    let (root, col, bounds) = range?;
    let mut lo: Option<(Value, bool)> = None;
    let mut hi: Option<(Value, bool)> = None;
    // Same-side bounds from different comparison families where one is a
    // Timestamp and the other numeric must not be tightened against each
    // other: the raw order ranks Timestamps above numerics, so the
    // Timestamp literal would "win" and silently swallow the numeric
    // conjunct — an exact plan then sweeps a band whose rows the numeric
    // comparison excludes as NULL. The scan path keeps both conjuncts.
    let ts_num_mix = |a: &Value, b: &Value| -> bool {
        let fam = |v: &Value| -> u8 {
            match v {
                Value::Int(_) | Value::Float(_) | Value::Decimal(_) => 0,
                Value::Timestamp(_) => 1,
                _ => 2,
            }
        };
        let (x, y) = (fam(a), fam(b));
        (x == 0 && y == 1) || (x == 1 && y == 0)
    };
    for (op, v) in bounds {
        use BinaryOperator::*;
        use Ordering::Equal as Eq;
        // Keep the TIGHTEST bound per side, not the last one written —
        // `a > 10 AND a > 5` must probe from 10 (the residual filter
        // guarantees correctness either way; this only narrows the scan).
        match op {
            Gt | GtEq => {
                if lo.as_ref().is_some_and(|(cv, _)| ts_num_mix(&v, cv)) {
                    return None;
                }
                if lo.as_ref().is_none_or(|(cv, incl)| {
                    Value::cmp_values(&v, cv) == Ordering::Greater
                        || (Value::cmp_values(&v, cv) == Eq && *incl && op == Gt)
                }) {
                    lo = Some((v, op == GtEq));
                }
            }
            Lt | LtEq => {
                if hi.as_ref().is_some_and(|(cv, _)| ts_num_mix(&v, cv)) {
                    return None;
                }
                if hi.as_ref().is_none_or(|(cv, incl)| {
                    Value::cmp_values(&v, cv) == Ordering::Less
                        || (Value::cmp_values(&v, cv) == Eq && *incl && op == Lt)
                }) {
                    hi = Some((v, op == LtEq));
                }
            }
            _ => {}
        }
    }
    if lo.is_none() && hi.is_none() {
        return None;
    }
    // An unbounded lower side (`col < k`) is TRUE for NULL keys — NULL
    // sorts below every value — but the tree holds no NULL keys, so the
    // probe candidates would silently drop those rows. Only a NOT NULL
    // column makes the unbounded scan a superset.
    if lo.is_none() && !meta.not_null.contains(&col) {
        return None;
    }
    let exact = !opaque && eq_map.is_empty() && in_target.is_none();
    Some((root, ProbePlan::Range { lo, hi }, exact))
}

/// Mirror a comparison operator for `lit OP col` conjuncts.
fn mirror_op(op: &BinaryOperator) -> Option<BinaryOperator> {
    use BinaryOperator::*;
    Some(match op {
        Eq => Eq,
        Lt => Gt,
        Gt => Lt,
        LtEq => GtEq,
        GtEq => LtEq,
        _ => return None,
    })
}

/// Per-tree maintenance spec, resolved once per statement: column list and
/// uniqueness of one index root. Hoisted because the per-row maintenance
/// loops used to re-resolve both through `index_columns_of` /
/// `root_key_unique` — a linear `index_defs` scan plus a `Vec` clone — for
/// every row of every tree.
struct IdxSpec {
    root_key: String,
    cols: Vec<String>,
    unique: bool,
    /// JSON path index (design 005): keys come from
    /// [`json_path_key`] over `cols[0]`'s JSON text, not the column value.
    path: Option<String>,
    /// Partial index predicate (row-local, parsed once per statement):
    /// rows failing it never enter the tree, so [`reindex_insert`] skips
    /// them. Removal/repoint need no check — [`BTree::delete_entry`]
    /// no-ops on entries that were never there.
    pred: Option<SqlExpr>,
}

/// Resolve [`IdxSpec`]s for every tree in `roots`, in root-key order
/// (matches the previous per-row `roots.keys()` iteration order).
fn idx_specs(meta: &TableMeta, roots: &std::collections::BTreeMap<String, u32>) -> Vec<IdxSpec> {
    roots
        .keys()
        .filter_map(|k| {
            let cols = meta.index_columns_of(k);
            // Orphaned tree (dropped composite index): no column list, so no
            // maintenance key. Keep it out of every write path.
            (!cols.is_empty()).then(|| {
                let def = meta.index_defs.iter().find(|d| d.name == *k);
                IdxSpec {
                    root_key: k.clone(),
                    path: def.and_then(|d| d.path.clone()),
                    // Partial predicate parsed once per statement; a
                    // malformed stored text (impossible via CREATE) leaves
                    // the spec unfiltered — the tree then behaves full, so
                    // the read-side gate (which re-parses and on failure
                    // refuses the probe) still refuses to use it.
                    pred: def
                        .and_then(|d| d.pred.as_deref())
                        .and_then(|p| parse_expr_text(p).ok()),
                    cols,
                    unique: meta.root_key_unique(k),
                }
            })
        })
        .collect()
}

/// Re-point index entries after in-page slot moves: delete (key, old_loc)
/// and insert (key, new_loc) in every tree. `before` holds the page's
/// documents as they were before the mutation.
fn reindex_repoint(
    pager: &Pager,
    tx: &mut crate::pager::Tx,
    specs: &[IdxSpec],
    roots: &mut std::collections::BTreeMap<String, u32>,
    before: &[(u64, Object)],
    old_l: u64,
    new_l: u64,
) -> Result<()> {
    let Some((_, doc)) = before.iter().find(|(l, _)| *l == old_l) else {
        return err("index fixup: moved document not found");
    };
    for spec in specs {
        if let Some(key) = index_key_of_spec(doc, spec) {
            let root = roots[&spec.root_key];
            let mut tree = BTree::open(root);
            let removed = tree
                .delete_entry(pager, tx, &key, old_l)
                .map_err(|e| index_err(&spec.root_key, e))?;
            // Only repoint an entry that was actually there: inserting on a
            // missed delete would add a second entry for the same document
            // (and a unique tree would spuriously reject it).
            if removed {
                tree.insert(pager, tx, key, new_l, spec.unique)
                    .map_err(|e| index_err(&spec.root_key, e))?;
            }
            if tree.root != root {
                roots.insert(spec.root_key.clone(), tree.root);
            }
        }
    }
    Ok(())
}

/// Drop one document's index entries (fast-path DELETE).
/// Composite/single-column index key for one document: single column → the
/// bare value (legacy tree layout); multiple columns → `Value::Array` over
/// the columns in key order (ordered element-wise by `cmp_values`).
/// `None` when any key column is missing or NULL — NULL does not enter
/// indexes (composite rule: one NULL column skips the whole key).
/// JSON path index key (design 005): parse the column's JSON text and
/// walk `path` with the SAME lookup `JSON_EXTRACT` evaluates inline —
/// extraction and query evaluation are one function, so probes cannot
/// diverge from row-local semantics. Column missing / non-text value /
/// malformed JSON / missing path → no key (the tree omits NULL keys, and
/// `JSON_EXTRACT(...) = x` is never true when the extract is NULL, so a
/// probe over this tree is semantically exact).
fn json_path_key(doc: &Object, col: &str, path: &str) -> Option<Value> {
    let Value::Str(text) = doc.get(col)? else {
        return None;
    };
    let parsed = crate::json::from_str(text).ok()?;
    let v = json_path_lookup(&parsed, path)?;
    if matches!(v, Value::Null) {
        return None;
    }
    Some(v.clone())
}

/// Key extraction for one maintenance spec: JSON path or plain column(s).
fn index_key_of_spec(doc: &Object, spec: &IdxSpec) -> Option<Value> {
    match &spec.path {
        Some(p) => json_path_key(doc, &spec.cols[0], p),
        None => index_key_of(doc, &spec.cols),
    }
}

/// Validate a JSON index path (design 005 §2): `$` followed by `.key` /
/// `[n]` segments only — the exact grammar [`json_path_lookup`] walks.
/// Quotes and backslashes are refused so the path can be embedded in the
/// dumped CREATE INDEX text without escaping.
fn validate_json_index_path(path: &str) -> std::result::Result<(), String> {
    let p = path.trim();
    if !p.starts_with('$') {
        return Err(format!(
            "JSON index path {path:?} must start with '$' (e.g. '$.field[0].sub')"
        ));
    }
    let rest = &p[1..];
    if rest.is_empty() {
        return Err(
            "JSON index path must have at least one segment after '$' (e.g. '$.field')".into(),
        );
    }
    let mut rest = rest;
    while !rest.is_empty() {
        if let Some(stripped) = rest.strip_prefix('.') {
            let end = stripped.find(['.', '[']).unwrap_or(stripped.len());
            let key = &stripped[..end];
            if key.is_empty() {
                return Err(format!(
                    "JSON index path {path:?} has an empty '.key' segment"
                ));
            }
            if key.contains(['\'', '\\']) {
                return Err(format!(
                    "JSON index path {path:?} must not contain quotes or backslashes"
                ));
            }
            rest = &stripped[end..];
        } else if let Some(stripped) = rest.strip_prefix('[') {
            let Some(end) = stripped.find(']') else {
                return Err(format!("JSON index path {path:?} has an unterminated '[…'"));
            };
            if stripped[..end].parse::<usize>().is_err() {
                return Err(format!(
                    "JSON index path {path:?} has a non-numeric array index {:?}",
                    &stripped[..end]
                ));
            }
            rest = &stripped[end + 1..];
        } else {
            return Err(format!(
                "JSON index path {path:?} has a malformed segment (expected '.key' or '[n]')"
            ));
        }
    }
    Ok(())
}

/// Parse one CREATE INDEX column of the form JSON_EXTRACT(col, '$.path')
/// into (column, path). Anything else in expression position errors loudly.
fn parse_json_index_column(f: &sqlparser::ast::Function) -> Result<(String, String)> {
    // Result here is the engine's alias (SqlError) — err() builds it.
    use sqlparser::ast::{FunctionArg, FunctionArgExpr, FunctionArguments};
    let args: Vec<&FunctionArg> = match &f.args {
        FunctionArguments::List(list) => list.args.iter().collect(),
        _ => return err("JSON_EXTRACT index column requires (col, '$.path') arguments"),
    };
    if args.len() != 2 {
        return err(format!(
            "JSON_EXTRACT index column requires exactly 2 arguments, got {}",
            args.len()
        ));
    }
    let col = match args[0] {
        FunctionArg::Unnamed(FunctionArgExpr::Expr(SqlExpr::Identifier(i))) => i.value.clone(),
        _ => return err("JSON_EXTRACT index column's first argument must be a plain column name"),
    };
    let FunctionArg::Unnamed(FunctionArgExpr::Expr(path_expr)) = args[1] else {
        return err("JSON_EXTRACT index column's path must be a '$…' string literal");
    };
    let Value::Str(path) = eval_const(path_expr)? else {
        return err("JSON_EXTRACT index column's path must be a '$…' string literal");
    };
    validate_json_index_path(&path).map_err(SqlError::Parse)?;
    Ok((col, path))
}

fn index_key_of(doc: &Object, cols: &[String]) -> Option<Value> {
    if cols.is_empty() {
        // Orphaned tree with no resolvable column list: no key belongs to it.
        return None;
    }
    if cols.len() == 1 {
        return match doc.get(&cols[0]) {
            Some(v) if !matches!(v, Value::Null) => Some(v.clone()),
            _ => None,
        };
    }
    let mut key = Vec::with_capacity(cols.len());
    for c in cols {
        match doc.get(c) {
            Some(v) if !matches!(v, Value::Null) => key.push(v.clone()),
            _ => return None,
        }
    }
    Some(Value::Array(key))
}

/// Remove one document's entries from every index tree (`specs` carries the
/// resolved column lists; see [`IdxSpec`]).
fn reindex_remove(
    pager: &Pager,
    tx: &mut crate::pager::Tx,
    specs: &[IdxSpec],
    roots: &mut std::collections::BTreeMap<String, u32>,
    doc: &Object,
    loc: u64,
) -> Result<()> {
    for spec in specs {
        if let Some(key) = index_key_of_spec(doc, spec) {
            let root = roots[&spec.root_key];
            let mut tree = BTree::open(root);
            tree.delete_entry(pager, tx, &key, loc)
                .map_err(|e| index_err(&spec.root_key, e))?;
            if tree.root != root {
                roots.insert(spec.root_key.clone(), tree.root);
            }
        }
    }
    Ok(())
}

/// Insert one document's index entries (fast-path UPDATE pass 2). Uniqueness
/// comes from the tree: `unique` trees (constraint columns and
/// CREATE UNIQUE INDEX) reject duplicates at insert.
fn reindex_insert(
    pager: &Pager,
    tx: &mut crate::pager::Tx,
    specs: &[IdxSpec],
    roots: &mut std::collections::BTreeMap<String, u32>,
    doc: &Object,
    loc: u64,
) -> Result<()> {
    for spec in specs {
        // Partial index: a row failing the predicate never enters the tree
        // (the removal side needs no mirror check — delete_entry no-ops on
        // absent entries, so flips in either direction stay consistent).
        if let Some(p) = &spec.pred {
            if !matches!(eval_expr(p, doc)?, Value::Bool(true)) {
                continue;
            }
        }
        if let Some(key) = index_key_of_spec(doc, spec) {
            let root = roots[&spec.root_key];
            let mut tree = BTree::open(root);
            tree.insert(pager, tx, key, loc, spec.unique)
                .map_err(|e| index_err(&spec.root_key, e))?;
            if tree.root != root {
                roots.insert(spec.root_key.clone(), tree.root);
            }
        }
    }
    Ok(())
}

/// Composite aggregate projections may reference columns outside the
/// aggregate arguments only when they are GROUP BY expressions — the
/// bare-column rule of `agg_spec`, applied inside nested expressions.
/// Constructs without explicit support reject loudly rather than silently
/// evaluating columns to NULL.
fn check_group_refs(e: &SqlExpr, group_exprs: &[SqlExpr]) -> Result<()> {
    match e {
        SqlExpr::Function(f) if is_agg_fn(f) => Ok(()), // per-row inside eval_agg
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        check_group_refs(inner, group_exprs)?;
                    }
                }
            }
            Ok(())
        }
        SqlExpr::Nested(inner) => check_group_refs(inner, group_exprs),
        SqlExpr::BinaryOp { left, right, .. } => {
            check_group_refs(left, group_exprs)?;
            check_group_refs(right, group_exprs)
        }
        SqlExpr::UnaryOp { expr, .. } => check_group_refs(expr, group_exprs),
        SqlExpr::Cast { expr, .. } => check_group_refs(expr, group_exprs),
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                check_group_refs(o, group_exprs)?;
            }
            for w in conditions {
                check_group_refs(&w.condition, group_exprs)?;
                check_group_refs(&w.result, group_exprs)?;
            }
            if let Some(r) = else_result {
                check_group_refs(r, group_exprs)?;
            }
            Ok(())
        }
        SqlExpr::Identifier(i) => {
            if group_exprs
                .iter()
                .any(|g| matches!(g, SqlExpr::Identifier(gi) if gi.value == i.value))
            {
                Ok(())
            } else {
                err(format!(
                    "column {} must appear in GROUP BY or an aggregate",
                    i.value
                ))
            }
        }
        SqlExpr::CompoundIdentifier(parts) => {
            let name = parts
                .iter()
                .map(|p| p.value.clone())
                .collect::<Vec<_>>()
                .join(".");
            if group_exprs.iter().any(|g| expr_name(g) == name) {
                Ok(())
            } else {
                err(format!(
                    "column {name} must appear in GROUP BY or an aggregate"
                ))
            }
        }
        SqlExpr::Value(_) => Ok(()),
        other => err(format!("unsupported aggregate expression: {other}")),
    }
}

/// HAVING variant of [`check_group_refs`]: a bare identifier may also be one
/// of the projection's output names (aliases resolve through the output row
/// during evaluation). Without this check a column that is neither grouped
/// nor aliased silently read NULL and the predicate dropped every group.
fn check_having_refs(e: &SqlExpr, group_exprs: &[SqlExpr], out_columns: &[String]) -> Result<()> {
    match e {
        SqlExpr::Function(f) if is_agg_fn(f) => Ok(()),
        SqlExpr::Function(f) => {
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    if let sqlparser::ast::FunctionArg::Unnamed(
                        sqlparser::ast::FunctionArgExpr::Expr(inner),
                    ) = a
                    {
                        check_having_refs(inner, group_exprs, out_columns)?;
                    }
                }
            }
            Ok(())
        }
        SqlExpr::Nested(inner) => check_having_refs(inner, group_exprs, out_columns),
        // Common predicate shapes the row-local evaluator (eval_group_expr's
        // fallback) already handles; without them `HAVING k IS NULL` — the
        // idiomatic ROLLUP total-row filter — was rejected as "unsupported".
        SqlExpr::IsNull(inner) => check_having_refs(inner, group_exprs, out_columns),
        SqlExpr::IsNotNull(inner) => check_having_refs(inner, group_exprs, out_columns),
        SqlExpr::IsDistinctFrom(a, b) | SqlExpr::IsNotDistinctFrom(a, b) => {
            check_having_refs(a, group_exprs, out_columns)?;
            check_having_refs(b, group_exprs, out_columns)
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            check_having_refs(expr, group_exprs, out_columns)?;
            check_having_refs(pattern, group_exprs, out_columns)
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            check_having_refs(expr, group_exprs, out_columns)?;
            check_having_refs(low, group_exprs, out_columns)?;
            check_having_refs(high, group_exprs, out_columns)
        }
        SqlExpr::InList { expr, list, .. } => {
            check_having_refs(expr, group_exprs, out_columns)?;
            for item in list {
                check_having_refs(item, group_exprs, out_columns)?;
            }
            Ok(())
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            check_having_refs(left, group_exprs, out_columns)?;
            check_having_refs(right, group_exprs, out_columns)
        }
        SqlExpr::UnaryOp { expr, .. } => check_having_refs(expr, group_exprs, out_columns),
        SqlExpr::Cast { expr, .. } => check_having_refs(expr, group_exprs, out_columns),
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(o) = operand {
                check_having_refs(o, group_exprs, out_columns)?;
            }
            for w in conditions {
                check_having_refs(&w.condition, group_exprs, out_columns)?;
                check_having_refs(&w.result, group_exprs, out_columns)?;
            }
            if let Some(r) = else_result {
                check_having_refs(r, group_exprs, out_columns)?;
            }
            Ok(())
        }
        SqlExpr::Identifier(i) => {
            if out_columns.iter().any(|c| c == &i.value)
                || group_exprs
                    .iter()
                    .any(|g| matches!(g, SqlExpr::Identifier(gi) if gi.value == i.value))
            {
                Ok(())
            } else {
                err(format!(
                    "column {} must appear in GROUP BY, an aggregate, or the SELECT list",
                    i.value
                ))
            }
        }
        SqlExpr::CompoundIdentifier(parts) => {
            let name = parts
                .iter()
                .map(|p| p.value.clone())
                .collect::<Vec<_>>()
                .join(".");
            if out_columns.iter().any(|c| c == &name)
                || group_exprs.iter().any(|g| expr_name(g) == name)
            {
                Ok(())
            } else {
                err(format!(
                    "column {name} must appear in GROUP BY, an aggregate, or the SELECT list"
                ))
            }
        }
        SqlExpr::Value(_) => Ok(()),
        other => err(format!("unsupported aggregate expression: {other}")),
    }
}

/// Group-aware expression evaluation (HAVING and composite aggregate
/// projections): aggregate subcalls run over the group's rows, GROUP BY
/// expressions resolve to the group key (via the group's rows — every row
/// shares the key value), and everything else evaluates against `out` —
/// the projected output row for HAVING, empty for projection items (where
/// `check_group_refs` has already rejected bare non-group columns).
fn eval_group_expr(
    e: &SqlExpr,
    out: &Object,
    docs: &[&Object],
    group_exprs: &[SqlExpr],
) -> Result<Value> {
    match e {
        SqlExpr::Function(f) if is_agg_fn(f) => {
            let (op, arg, distinct, sep, filter) = agg_parts(f, false)?;
            eval_agg(
                &AggSpec::Agg {
                    op,
                    arg,
                    distinct,
                    sep,
                    filter,
                },
                docs,
                &[],
                group_exprs,
            )
        }
        SqlExpr::Function(f) => {
            // Scalar function whose arguments may contain aggregates
            // (`COALESCE(SUM(x), 0)`).
            let name = f.name.to_string().to_uppercase();
            if f.over.is_some() {
                return err(format!("window functions (OVER) are not supported: {name}"));
            }
            let mut args = Vec::new();
            if let sqlparser::ast::FunctionArguments::List(list) = &f.args {
                for a in &list.args {
                    match a {
                        sqlparser::ast::FunctionArg::Unnamed(
                            sqlparser::ast::FunctionArgExpr::Expr(inner),
                        ) => args.push(eval_group_expr(inner, out, docs, group_exprs)?),
                        _ => return err(format!("unsupported argument to {name}")),
                    }
                }
            }
            scalar_function(&name, &args)
        }
        SqlExpr::Identifier(i) => {
            if let Some(g) = group_exprs
                .iter()
                .find(|g| matches!(g, SqlExpr::Identifier(gi) if gi.value == i.value))
            {
                return match docs.first() {
                    Some(d) => eval_expr(g, d),
                    None => Ok(Value::Null),
                };
            }
            eval_expr(e, out)
        }
        SqlExpr::CompoundIdentifier(parts) => {
            let name = parts
                .iter()
                .map(|p| p.value.clone())
                .collect::<Vec<_>>()
                .join(".");
            if let Some(g) = group_exprs.iter().find(|g| expr_name(g) == name) {
                return match docs.first() {
                    Some(d) => eval_expr(g, d),
                    None => Ok(Value::Null),
                };
            }
            eval_expr(e, out)
        }
        SqlExpr::BinaryOp { left, op, right } => {
            let l = eval_group_expr(left, out, docs, group_exprs)?;
            let r = eval_group_expr(right, out, docs, group_exprs)?;
            binop(l, op, r)
        }
        SqlExpr::UnaryOp { op, expr } => {
            let v = eval_group_expr(expr, out, docs, group_exprs)?;
            match (op, v) {
                (sqlparser::ast::UnaryOperator::Minus, Value::Int(i)) => match i.checked_neg() {
                    Some(n) => Ok(Value::Int(n)),
                    // -i64::MIN overflows; mirror literal handling and keep
                    // the value instead of panicking in debug builds.
                    None => Ok(Value::Float(-(i as f64))),
                },
                (sqlparser::ast::UnaryOperator::Minus, Value::Float(f)) => Ok(Value::Float(-f)),
                (sqlparser::ast::UnaryOperator::Minus, Value::Decimal(d)) => {
                    // Signed-zero guard: decimal text cannot replay -0
                    // ("−0.00" parses back to +0), so the dump/replica
                    // rewrite would silently flip the encoded bytes.
                    let neg = -d;
                    Ok(Value::Decimal(if neg.is_zero() && neg.is_sign_negative() {
                        rust_decimal::Decimal::ZERO
                    } else {
                        neg
                    }))
                }
                (sqlparser::ast::UnaryOperator::Not, Value::Bool(b)) => Ok(Value::Bool(!b)),
                (sqlparser::ast::UnaryOperator::Not, Value::Null) => Ok(Value::Null),
                // T-SQL bitwise NOT (~x): two's-complement on 64-bit ints.
                (sqlparser::ast::UnaryOperator::BitwiseNot, Value::Int(i)) => Ok(Value::Int(!i)),
                _ => err("unsupported unary operand"),
            }
        }
        SqlExpr::Nested(inner) => eval_group_expr(inner, out, docs, group_exprs),
        SqlExpr::Cast {
            kind,
            expr,
            data_type,
            ..
        } => {
            let v = eval_group_expr(expr, out, docs, group_exprs)?;
            let out = cast_value(v, &data_type.to_string());
            // T-SQL TRY_CAST: a failed conversion yields NULL, not an error.
            if matches!(kind, sqlparser::ast::CastKind::TryCast) {
                out.or(Ok(Value::Null))
            } else {
                out
            }
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            let base = operand
                .as_ref()
                .map(|o| eval_group_expr(o, out, docs, group_exprs))
                .transpose()?;
            for w in conditions {
                let hit = match &base {
                    Some(b) => {
                        let cv = eval_group_expr(&w.condition, out, docs, group_exprs)?;
                        // Same coerced equality as the scalar CASE arm
                        // (Str ↔ Timestamp lifts etc.); a bare cmp_values
                        // here made grouped CASE disagree with ungrouped.
                        !matches!(b, Value::Null)
                            && !matches!(cv, Value::Null)
                            && cmp_coerced(b, &cv) == Some(Ordering::Equal)
                    }
                    None => matches!(
                        eval_group_expr(&w.condition, out, docs, group_exprs)?,
                        Value::Bool(true)
                    ),
                };
                if hit {
                    return eval_group_expr(&w.result, out, docs, group_exprs);
                }
            }
            match else_result {
                Some(r) => eval_group_expr(r, out, docs, group_exprs),
                None => Ok(Value::Null),
            }
        }
        other => eval_expr(other, out),
    }
}

fn binop(l: Value, op: &BinaryOperator, r: Value) -> Result<Value> {
    use BinaryOperator::*;
    Ok(match op {
        // T-SQL `+` concatenates when both operands are text (NULL
        // propagates through `arith` when either side is NULL); a
        // string/number mix falls through to numeric addition, where the
        // string must convert to a number (SQL Server implicit conversion)
        // or the statement errors loudly. These arms must precede the
        // generic arith arm — `Plus` matches it first otherwise.
        Plus if matches!(l, Value::Str(_)) && matches!(r, Value::Str(_)) => {
            Value::Str(format!("{}{}", value_to_text(&l), value_to_text(&r)))
        }
        Plus if matches!(l, Value::Str(_)) || matches!(r, Value::Str(_)) => {
            if matches!(l, Value::Null) || matches!(r, Value::Null) {
                Value::Null
            } else {
                let num = |v: Value| -> Result<Value> {
                    match &v {
                        Value::Str(s) => {
                            if let Ok(i) = s.trim().parse::<i64>() {
                                Ok(Value::Int(i))
                            } else {
                                s.trim()
                                    .parse::<Decimal>()
                                    .map(Value::Decimal)
                                    .map_err(|_| {
                                        SqlError::Message(format!(
                                            "cannot convert {s:?} to a number for '+'"
                                        ))
                                    })
                            }
                        }
                        other => Ok(other.clone()),
                    }
                };
                arith(num(l)?, op, num(r)?)?
            }
        }
        Plus | Minus | Multiply | Divide | Modulo => arith(l, op, r)?,
        // T-SQL bitwise operators: 64-bit two's complement, integers (and
        // bools as T-SQL BIT) only.
        BitwiseOr => bitwise(l, r, |a, b| a | b)?,
        BitwiseAnd => bitwise(l, r, |a, b| a & b)?,
        BitwiseXor => bitwise(l, r, |a, b| a ^ b)?,
        StringConcat => match (l, r) {
            (Value::Null, _) | (_, Value::Null) => Value::Null,
            (a, b) => Value::Str(format!("{}{}", value_to_text(&a), value_to_text(&b))),
        },
        Eq | NotEq | Lt | LtEq | Gt | GtEq => {
            // Coercion only (timestamp vs parseable string); it must never
            // touch NULL — NULL is a comparable value here (NULL = NULL is
            // true; hash-join and unique-check semantics rely on that).
            let Some((l, r)) = coerce_timestamp_operands(l, r) else {
                // A string that is not a timestamp compared with a
                // TIMESTAMP: unknown, not a silent wrong ordering.
                return Ok(Value::Null);
            };
            let ord = Value::cmp_values(&l, &r);
            let out = match op {
                Eq => ord == Ordering::Equal,
                NotEq => ord != Ordering::Equal,
                Lt => ord == Ordering::Less,
                LtEq => ord != Ordering::Greater,
                Gt => ord == Ordering::Greater,
                GtEq => ord != Ordering::Less,
                _ => unreachable!("matched above"),
            };
            Value::Bool(out)
        }
        // Three-valued AND over the engine's one UNKNOWN source (the
        // uncoercable Timestamp↔string/numeric comparison yields Null):
        // FALSE dominates, TRUE keeps the unknown, and the result stays
        // Null — WHERE already filters anything that is not Bool(true),
        // so a row whose predicate is unknown is dropped instead of
        // erroring the whole statement (`WHERE ts = s AND id = 1` used to
        // fail on the first row with an unparseable s).
        And => match (l, r) {
            (Value::Bool(a), Value::Bool(b)) => Value::Bool(a && b),
            (Value::Bool(false), Value::Null) | (Value::Null, Value::Bool(false)) => {
                Value::Bool(false)
            }
            (Value::Bool(true), Value::Null)
            | (Value::Null, Value::Bool(true))
            | (Value::Null, Value::Null) => Value::Null,
            _ => return err("AND requires booleans"),
        },
        // Three-valued OR: TRUE dominates, FALSE keeps the unknown.
        Or => match (l, r) {
            (Value::Bool(a), Value::Bool(b)) => Value::Bool(a || b),
            (Value::Bool(true), Value::Null) | (Value::Null, Value::Bool(true)) => {
                Value::Bool(true)
            }
            (Value::Bool(false), Value::Null)
            | (Value::Null, Value::Bool(false))
            | (Value::Null, Value::Null) => Value::Null,
            _ => return err("OR requires booleans"),
        },
        other => return err(format!("unsupported operator: {other}")),
    })
}

/// T-SQL bitwise operators (`& | ^`): integers only; BOOLs coerce like
/// T-SQL BIT (1/0) and the result is an integer.
fn bitwise(l: Value, r: Value, f: impl Fn(i64, i64) -> i64) -> Result<Value> {
    let as_int = |v: &Value| -> Option<i64> {
        match v {
            Value::Int(i) => Some(*i),
            Value::Bool(b) => Some(i64::from(*b)),
            _ => None,
        }
    };
    match (&l, &r) {
        (Value::Null, _) | (_, Value::Null) => Ok(Value::Null),
        _ => match (as_int(&l), as_int(&r)) {
            (Some(a), Some(b)) => Ok(Value::Int(f(a, b))),
            _ => err("bitwise operators require integer operands"),
        },
    }
}

/// Comparison-side TIMESTAMP coercion: a string operand against a TIMESTAMP
/// parses into the comparison (any accepted timestamp form — `WHERE ts >
/// '2026-09-16'` works); an unparseable string yields None → the comparison
/// is NULL. cmp_values itself never mixes the bands (a parseable string
/// inserted into the time order would break transitivity), so this is the
/// single funnel where the predicate-level rule lives — the index-probe
/// bound builder shares it (see `promote_timestamp_bound`).
fn coerce_timestamp_operands(l: Value, r: Value) -> Option<(Value, Value)> {
    use crate::value::parse_timestamp_ms;
    match (&l, &r) {
        (Value::Timestamp(t), Value::Str(s)) => {
            parse_timestamp_ms(s).map(|p| (Value::Timestamp(*t), Value::Timestamp(p)))
        }
        (Value::Str(s), Value::Timestamp(t)) => {
            parse_timestamp_ms(s).map(|p| (Value::Timestamp(p), Value::Timestamp(*t)))
        }
        (Value::Timestamp(_), Value::Int(_))
        | (Value::Int(_), Value::Timestamp(_))
        | (Value::Timestamp(_), Value::Decimal(_))
        | (Value::Decimal(_), Value::Timestamp(_))
        | (Value::Timestamp(_), Value::Float(_))
        | (Value::Float(_), Value::Timestamp(_)) => {
            // No silent numeric-date semantics: CAST(ms AS TIMESTAMP)
            // makes the intent explicit.
            None
        }
        _ => Some((l, r)),
    }
}

/// NULL-safe equality for `IS [NOT] DISTINCT FROM` (SQL:2003). The engine's
/// comparison is total — `NULL` is a sortable value, so `NULL` compares
/// equal to `NULL` and unequal to everything else — which is exactly the
/// DISTINCT FROM truth table. Comparison goes through the TIMESTAMP↔string
/// coercion funnel so `ts IS NOT DISTINCT FROM '2026-…'` behaves like `ts =
/// '2026-…'`; an uncoercable pair is simply not equal.
fn values_equal_null_safe(a: &Value, b: &Value) -> bool {
    cmp_coerced(a, b) == Some(Ordering::Equal)
}

/// `cmp_values` behind the predicate-level TIMESTAMP↔string rule
/// ([`coerce_timestamp_operands`]): BETWEEN, IN, CASE and IS [NOT] DISTINCT
/// FROM must compare exactly like `=`/`<`/`>` do. `None` mirrors the
/// comparison-unknown result those operators report for an unparseable
/// string against a TIMESTAMP.
/// The full CREATE TABLE text for one catalog entry (columns, constraints)
/// — shared by dump_script and the sqlite_master table rows, so clients
/// (the EF keep-data rebuild) see the same constraint set the dump would
/// re-create.
fn create_table_ddl(name: &str, meta: &TableMeta) -> String {
    let mut ddl = format!("CREATE TABLE {} (\n", quote_ident(name));
    let mut parts: Vec<String> = Vec::new();
    for col in &meta.columns {
        let mut def = quote_ident(col);
        if meta.autoguid.as_deref() == Some(col.as_str()) {
            def.push_str(" GUID AUTOINCREMENT");
        } else if meta.autoinc.as_deref() == Some(col.as_str()) {
            def.push_str(" INT AUTOINCREMENT");
        } else {
            // Declared types are not enforced (document storage);
            // TEXT round-trips the column shape without pretending
            // to preserve the original declaration.
            def.push_str(" TEXT");
        }
        if meta.primary_key.as_deref() == Some(col.as_str()) {
            def.push_str(" PRIMARY KEY");
        }
        if meta.constraint_unique.contains(col) {
            def.push_str(" UNIQUE");
        }
        if meta.not_null.contains(col) {
            def.push_str(" NOT NULL");
        }
        if let Some((_, expr)) = meta.defaults.iter().find(|(c, _)| c == col) {
            def.push_str(&format!(" DEFAULT ({expr})"));
        }
        parts.push(def);
    }
    for chk in &meta.checks {
        parts.push(format!("CHECK ({chk})"));
    }
    for (lc, rt, rc) in &meta.foreign_keys {
        parts.push(format!(
            "FOREIGN KEY ({}) REFERENCES {} ({})",
            quote_ident(lc),
            quote_ident(rt),
            quote_ident(rc)
        ));
    }
    ddl.push_str(&parts.join(",\n"));
    ddl.push_str("\n);");
    ddl
}

/// Rows of a single-column value-list subquery (scalar / IN / ANY / ALL):
/// more than one output column is a cardinality error. The old silent
/// `row.first()` read only the first column and dropped visible matches
/// from IN lists.
fn single_col_rows(r: &QueryResult) -> Result<()> {
    if r.columns.len() > 1 {
        return err(format!(
            "subquery returns {} columns; a single column is required here",
            r.columns.len()
        ));
    }
    Ok(())
}

fn cmp_coerced(a: &Value, b: &Value) -> Option<Ordering> {
    coerce_timestamp_operands(a.clone(), b.clone()).map(|(a, b)| Value::cmp_values(&a, &b))
}

fn arith(l: Value, op: &BinaryOperator, r: Value) -> Result<Value> {
    use BinaryOperator::*;
    if matches!(l, Value::Null) || matches!(r, Value::Null) {
        return Ok(Value::Null);
    }
    // TIMESTAMP arithmetic: ± INTEGER shifts by milliseconds,
    // TIMESTAMP - TIMESTAMP yields the duration in milliseconds
    // (checked: i64 ms covers ~292 million years either way, but a
    // pathological literal must not panic). Timestamp + Timestamp and
    // numeric↔timestamp mixing are errors — CAST explicitly.
    if matches!(l, Value::Timestamp(_)) || matches!(r, Value::Timestamp(_)) {
        // Result domain: an instant outside 0001..=9999 has no canonical
        // text form (value_literal could not replay it), so it degrades to
        // NULL like any other out-of-range arithmetic result.
        let ts = |ms: i64| {
            if crate::value::is_valid_timestamp_ms(ms) {
                Value::Timestamp(ms)
            } else {
                Value::Null
            }
        };
        return Ok(match (op, l, r) {
            (Plus, Value::Timestamp(t), Value::Int(n))
            | (Plus, Value::Int(n), Value::Timestamp(t)) => {
                t.checked_add(n).map(ts).unwrap_or(Value::Null)
            }
            (Minus, Value::Timestamp(t), Value::Int(n)) => {
                t.checked_sub(n).map(ts).unwrap_or(Value::Null)
            }
            (Minus, Value::Timestamp(a), Value::Timestamp(b)) => {
                a.checked_sub(b).map(Value::Int).unwrap_or(Value::Null)
            }
            _ => {
                return err(
                    "timestamp arithmetic: TIMESTAMP ± INTEGER (ms) or TIMESTAMP - TIMESTAMP",
                )
            }
        });
    }
    // Decimal wins over Float in mixed arithmetic: exactness survives
    // `amount * 1.5` while Int stays promoted losslessly.
    if matches!(l, Value::Decimal(_)) || matches!(r, Value::Decimal(_)) {
        let a = as_decimal(&l)?;
        let b = as_decimal(&r)?;
        let out = match op {
            Plus => a.checked_add(b),
            Minus => a.checked_sub(b),
            Multiply => a.checked_mul(b),
            Divide => a.checked_div(b),
            Modulo => a.checked_rem(b),
            _ => return err("not an arithmetic operator"),
        };
        // Overflow yields NULL (SQLite-style) rather than a panic; division
        // by zero is None from checked_div/checked_rem.
        return Ok(out.map(Value::Decimal).unwrap_or(Value::Null));
    }
    let float_mode = matches!(l, Value::Float(_)) || matches!(r, Value::Float(_));
    if float_mode {
        let a = as_f64(&l)?;
        let b = as_f64(&r)?;
        return Ok(match op {
            Plus => Value::Float(a + b),
            Minus => Value::Float(a - b),
            Multiply => Value::Float(a * b),
            Divide if b == 0.0 => Value::Null,
            Divide => Value::Float(a / b),
            Modulo if b == 0.0 => Value::Null,
            Modulo => Value::Float(a % b),
            _ => return err("not an arithmetic operator"),
        });
    }
    match (&l, &r) {
        (Value::Int(a), Value::Int(b)) => {
            // Copy out so the inherent i64 checked_* methods win over the
            // num-traits impls imported for Decimal.
            let (a, b) = (*a, *b);
            // Overflow yields NULL (SQLite/Decimal semantics) — the old
            // wrapping arithmetic silently returned i64::MIN for
            // `9223372036854775807 + 1` and replicated/backed it up as truth.
            Ok(match op {
                Plus => match a.checked_add(b) {
                    Some(v) => Value::Int(v),
                    None => Value::Null,
                },
                Minus => match a.checked_sub(b) {
                    Some(v) => Value::Int(v),
                    None => Value::Null,
                },
                Multiply => match a.checked_mul(b) {
                    Some(v) => Value::Int(v),
                    None => Value::Null,
                },
                Divide if b == 0 => Value::Null,
                // i64::MIN / -1 overflows (SIGFPE on some ISAs) — treat like
                // division by zero and yield NULL instead of crashing.
                Divide => match a.checked_div(b) {
                    Some(q) => Value::Int(q),
                    None => Value::Null,
                },
                Modulo if b == 0 => Value::Null,
                Modulo => match a.checked_rem(b) {
                    Some(m) => Value::Int(m),
                    None => Value::Null,
                },
                _ => return err("not an arithmetic operator"),
            })
        }
        _ => err(format!(
            "non-numeric operands: {} {op} {}",
            l.type_name(),
            r.type_name()
        )),
    }
}

fn as_f64(v: &Value) -> Result<f64> {
    match v {
        Value::Int(i) => Ok(*i as f64),
        Value::Float(f) => Ok(*f),
        Value::Decimal(d) => Ok(d.to_f64().unwrap_or(f64::NAN)),
        other => err(format!("non-numeric operand of type {}", other.type_name())),
    }
}

/// Exact numeric view of Int/Float/Decimal operands (the decimal arithmetic
/// path). A Float contributes its exact binary value.
fn as_decimal(v: &Value) -> Result<Decimal> {
    match v {
        Value::Decimal(d) => Ok(*d),
        Value::Int(i) => Ok(Decimal::from(*i)),
        Value::Float(f) => Decimal::from_f64_retain(*f)
            .ok_or_else(|| SqlError::Message(format!("non-finite float in arithmetic: {f}"))),
        other => err(format!("non-numeric operand of type {}", other.type_name())),
    }
}

fn union_of_fields(docs: &[Object]) -> Vec<String> {
    let mut seen: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    for d in docs {
        for k in d.keys() {
            seen.insert(k.clone());
        }
    }
    seen.into_iter().collect()
}

